/** Normalize an archive result for comparison with its line.
 *  FT results were historically stored in seconds; lines are in minutes. */
function normalizeArchiveResult(propType: string, result: number): number {
  if (propType === 'FightTime' && result > 25) return result / 60;
  // Same seconds-vs-minutes rescue for Control, for rows the backfill wrote in
  // seconds before ctrlMinsOf existed. 25 is the ceiling for both: a 5R fight is
  // 25 minutes, so anything above it cannot be a minutes value and must be seconds.
  //
  // Deliberately imperfect and that is fine — a legacy row of 18 is genuinely
  // ambiguous (18 seconds of control, or 18 minutes) and this leaves it alone.
  // It barely matters: backfilled rows carry no `line`, and the fighter-stats,
  // per-event hit-rate and platform-bias paths all filter on a finite line, so
  // they never see these. The net exists for resolveVsArchive, which grades a
  // placed leg against the row's result using the LEG's line.
  if (propType === 'Control' && result > 25) return result / 60;
  return result;
}

async function loadFighterArchiveStats(): Promise<void> {
  const payload = await storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY]);
  const rows = Array.isArray(payload[STORAGE_PROP_ARCHIVE_KEY])
    ? (payload[STORAGE_PROP_ARCHIVE_KEY] as PropArchiveRecord[])
    : [];
  const map = new Map<string, Record<string, { hits: number; total: number }>>();
  for (const r of rows) {
    if (!r.fighter || !Number.isFinite(Number(r.line)) || !Number.isFinite(Number(r.result))) continue;
    const key = (normalizeName(r.fighter) || r.fighter).toLowerCase();
    const pt = String(r.propType || 'Unknown');
    if (!map.has(key)) map.set(key, {});
    const entry = map.get(key)!;
    if (!entry[pt]) entry[pt] = { hits: 0, total: 0 };
    entry[pt].total++;
    if (normalizeArchiveResult(pt, Number(r.result)) > Number(r.line)) entry[pt].hits++;
  }
  _fighterArchiveStats = map;
}

async function loadFighterClvDrift(): Promise<void> {
  const payload = await storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY]);
  const rows = Array.isArray(payload[STORAGE_PROP_ARCHIVE_KEY])
    ? (payload[STORAGE_PROP_ARCHIVE_KEY] as PropArchiveRecord[])
    : [];
  const map = new Map<string, Record<string, Record<string, { openLine: number; line: number }>>>();
  for (const r of rows) {
    if (!r.fighter) continue;
    if (Number.isFinite(Number(r.result))) continue; // resolved — not a live market
    const openLine = Number(r.openLine);
    const line = Number(r.line);
    if (!Number.isFinite(openLine) || !Number.isFinite(line)) continue;
    const key = (normalizeName(r.fighter) || r.fighter).toLowerCase();
    const pt = String(r.propType || 'Unknown');
    const plat = String(r.platform || '').toLowerCase();
    if (!map.has(key)) map.set(key, {});
    const byProp = map.get(key)!;
    if (!byProp[pt]) byProp[pt] = {};
    byProp[pt][plat] = { openLine, line };
  }
  _fighterClvDrift = map;
}

