// GLOW-UP 170 (Best Picks level-up 4): placed tracking.
// Legs the user actually entered, persisted per event in chrome.storage so
// they survive reloads (unlike the session-scoped slate queue). This records
// what was TAKEN; best_picks_snapshots_v1 already records what was SUGGESTED
// — the learning engine joins the two against results later.
interface BestPicksPlacedRecord extends BestPicksSlatePick {
  placedAt: number;
  // GLOW-UP 174: settled outcome written back by the Placed Ledger once the
  // archive grades the leg — makes history permanent even after the archive
  // prunes the underlying rows. Absent while pending.
  outcome?: 'hit' | 'miss';
  actual?: number | null;
  resolvedAt?: number;
}
const STORAGE_BEST_PICKS_PLACED_KEY = 'best_picks_placed_v1' as const;
const bestPicksPlaced = new Map<string, BestPicksPlacedRecord>();
const bestPicksEventKey = (): string =>
  ((upcomingEventName || inferredEventNameFromLines || '').trim() || 'Unknown Event').toLowerCase();

// GLOW-UP 176/180: aggregate settled placed legs into a personal record
// keyed `source|direction` (e.g. "ft|under"). Shared by the Best Picks
// calibration chips (176) and the Parlay Lab ones (180) so the two views
// can never compute a different personal hit rate.
function aggregatePlacedPersonalRecord(placedRaw: unknown): Map<string, { hits: number; total: number }> {
  const rec = new Map<string, { hits: number; total: number }>();
  if (!placedRaw || typeof placedRaw !== 'object' || Array.isArray(placedRaw)) return rec;
  for (const evLegs of Object.values(placedRaw as Record<string, unknown>)) {
    if (!evLegs || typeof evLegs !== 'object') continue;
    for (const r of Object.values(evLegs as Record<string, BestPicksPlacedRecord>)) {
      if (!r || typeof r !== 'object' || (r.outcome !== 'hit' && r.outcome !== 'miss')) continue;
      const k = `${r.source}|${String(r.dir || '').toLowerCase()}`;
      const cur = rec.get(k) || { hits: 0, total: 0 };
      cur.total++;
      if (r.outcome === 'hit') cur.hits++;
      rec.set(k, cur);
    }
  }
  return rec;
}
// GLOW-UP 181 (Parlay Lab level 5): placed parlays. A built slip the user
// actually entered, persisted per event — the multi-leg analog of
// best_picks_placed_v1. Resolved in the Data view's Parlay Ledger.
const STORAGE_PARLAY_PLACED_KEY = 'parlay_placed_v1' as const;
interface PlacedParlayLeg { fighter: string; opponent: string | null; dir: string; stat: string; statLabel: string; line: number | null; book: string | null; bookLabel: string; }
interface PlacedParlay { id: string; placedAt: number; legs: PlacedParlayLeg[]; }
async function persistPlacedParlay(legs: PlacedParlayLeg[]): Promise<'placed' | 'dup' | 'err'> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_PARLAY_PLACED_KEY]);
    const raw = payload[STORAGE_PARLAY_PLACED_KEY];
    const all: Record<string, PlacedParlay[]> =
      raw && typeof raw === 'object' && !Array.isArray(raw) ? { ...(raw as Record<string, PlacedParlay[]>) } : {};
    const evKey = bestPicksEventKey();
    const list = Array.isArray(all[evKey]) ? [...all[evKey]] : [];
    // The signature carries BOOK and LINE, not just the side. Without them two
    // genuinely different slips collapsed into one: the same sides taken on Betr
    // (Tsuruya 99.5 + Asakura 96.5) and on Pick6 (95.5 + 90.5) produced an identical
    // signature, so the second was rejected as ALREADY PLACED and the wager went
    // untracked. Leg COUNT was the only thing separating them, which is why that same
    // pair plus a third leg saved fine. The placed-LEG store has always keyed on the
    // book for exactly this reason (`Su Mudaerji|over|ss|underdog`).
    // A true double-submit is still caught: same sides, same book, same lines.
    const sigOf = (ls: PlacedParlayLeg[]): string => ls
      .map(l => `${l.fighter.toLowerCase()}|${l.stat}|${String(l.dir).toLowerCase()}|${l.book ?? ''}|${l.line ?? ''}`)
      .sort().join(',');
    const sig = sigOf(legs);
    if (list.some(p => sigOf(p.legs || []) === sig)) return 'dup';
    list.unshift({ id: `${Date.now()}_${Math.random().toString(36).slice(2, 7)}`, placedAt: Date.now(), legs });
    all[evKey] = list.slice(0, 30);
    const evKeys = Object.keys(all);
    if (evKeys.length > 20) {
      const newest = (ev: string): number => Math.max(0, ...(all[ev] || []).map(p => Number(p.placedAt) || 0));
      evKeys.sort((a, b) => newest(a) - newest(b));
      for (const k of evKeys.slice(0, evKeys.length - 20)) delete all[k];
    }
    await storageSet({ [STORAGE_PARLAY_PLACED_KEY]: all });
    return 'placed';
  } catch { return 'err'; }
}

/**
 * Remove one placed parlay by id. The mirror of persistPlacedParlay, which had
 * no counterpart — a slip placed by mistake, or VOIDED BY THE BOOK when a fight
 * falls off the card, was permanent and kept being graded. Individual placed legs
 * always had their ● PLACED toggle; parlays had nothing.
 *
 * Live case (2026-08-12): Ochoa withdrew from UFC 330, so the two-leg slips
 * carrying Charles Johnson and Jose Ochoa SS void at the book — but the ledger
 * would still resolve them leg-by-leg and stamp a BUST that never happened,
 * polluting the cashed record the same way a voided single would.
 *
 * Deletes the event key entirely when its last slip goes, so the ledger does not
 * render an empty event heading.
 */
async function removePlacedParlay(evKey: string, id: string): Promise<boolean> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_PARLAY_PLACED_KEY]);
    const raw = payload[STORAGE_PARLAY_PLACED_KEY];
    const all: Record<string, PlacedParlay[]> =
      raw && typeof raw === 'object' && !Array.isArray(raw) ? { ...(raw as Record<string, PlacedParlay[]>) } : {};
    const list = Array.isArray(all[evKey]) ? all[evKey] : [];
    const next = list.filter(p => String(p.id) !== String(id));
    if (next.length === list.length) return false;   // nothing matched — no-op
    if (next.length) all[evKey] = next; else delete all[evKey];
    await storageSet({ [STORAGE_PARLAY_PLACED_KEY]: all });
    return true;
  } catch { return false; }
}

// GLOW-UP 180: module-level cache so the synchronous Parlay Lab render can
// read the personal record without a storage round-trip; refreshed async
// and signature-gated so it re-renders exactly once when the data changes.
const placedPersonalRecord = new Map<string, { hits: number; total: number }>();
let placedPersonalRecordSig = '';
async function refreshPlacedPersonalRecord(): Promise<boolean> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_BEST_PICKS_PLACED_KEY]);
    const rec = aggregatePlacedPersonalRecord(payload[STORAGE_BEST_PICKS_PLACED_KEY]);
    const sig = [...rec.entries()].sort((a, b) => a[0].localeCompare(b[0])).map(([k, v]) => `${k}:${v.hits}/${v.total}`).join(',');
    if (sig === placedPersonalRecordSig) return false;
    placedPersonalRecordSig = sig;
    placedPersonalRecord.clear();
    for (const [k, v] of rec) placedPersonalRecord.set(k, v);
    return true;
  } catch { return false; }
}
// GLOW-UP 246b: hydrate the CURRENT event's placed map from storage. This was
// only ever done inside the Best Picks render, so opening Parlay Lab first left
// bestPicksPlaced empty — the ● PLACED chip never rendered and no row could say
// you held it, which reads exactly like the placed legs being absent from the
// pool. Same signature-gated shape as refreshPlacedPersonalRecord above (whose
// comment already named this failure mode for the calibration chips) so it
// re-renders exactly once and cannot loop.
let bestPicksPlacedSig = '';
async function refreshBestPicksPlaced(): Promise<boolean> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_BEST_PICKS_PLACED_KEY]);
    const raw = payload[STORAGE_BEST_PICKS_PLACED_KEY];
    const evMap = raw && typeof raw === 'object' && !Array.isArray(raw)
      ? ((raw as Record<string, unknown>)[bestPicksEventKey()] as Record<string, BestPicksPlacedRecord> | undefined)
      : undefined;
    const entries: Array<[string, BestPicksPlacedRecord]> =
      evMap && typeof evMap === 'object' ? Object.entries(evMap) as Array<[string, BestPicksPlacedRecord]> : [];
    const sig = entries.map(([k]) => k).sort().join(',');
    if (sig === bestPicksPlacedSig) return false;
    bestPicksPlacedSig = sig;
    bestPicksPlaced.clear();
    for (const [k, v] of entries) { if (v && typeof v === 'object') bestPicksPlaced.set(k, v); }
    return true;
  } catch { return false; }
}
async function persistBestPicksPlaced(): Promise<void> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_BEST_PICKS_PLACED_KEY]);
    const raw = payload[STORAGE_BEST_PICKS_PLACED_KEY];
    const all: Record<string, Record<string, BestPicksPlacedRecord>> =
      raw && typeof raw === 'object' && !Array.isArray(raw)
        ? { ...(raw as Record<string, Record<string, BestPicksPlacedRecord>>) }
        : {};
    all[bestPicksEventKey()] = Object.fromEntries(bestPicksPlaced);
    // Cap stored events at 20, dropping the ones with the oldest activity.
    const evKeys = Object.keys(all);
    if (evKeys.length > 20) {
      const newest = (ev: string): number => Math.max(0, ...Object.values(all[ev] || {}).map(r => Number(r?.placedAt) || 0));
      evKeys.sort((a, b) => newest(a) - newest(b));
      for (const k of evKeys.slice(0, evKeys.length - 20)) delete all[k];
    }
    await storageSet({ [STORAGE_BEST_PICKS_PLACED_KEY]: all });
  } catch { /* placed tracking is best-effort — never block the render */ }
}

// Display-only name prettifier — restores apostrophes the fantasy platforms strip
// (e.g. "Sean Omalley" -> "Sean O'Malley"). Lookups, keys, and storage keep the raw name.
const PRETTY_SURNAMES: Record<string, string> = {
  omalley: "O'Malley",
  oneill: "O'Neill",
  osullivan: "O'Sullivan",
  obrien: "O'Brien",
  oconnell: "O'Connell",
  oconnor: "O'Connor",
};
// Count-up ticker for metric strip values. Parses the numeric part of strings
// like "67%", "+60%", "14" and tweens it; non-numeric strings are set directly.
function animateNumberText(el: HTMLElement, value: string, durationMs = 700): void {
  const m = value.match(/^([+-]?)(\d+(?:\.\d+)?)(.*)$/);
  if (!m || matchMedia('(prefers-reduced-motion: reduce)').matches) { el.textContent = value; return; }
  const sign = m[1], target = parseFloat(m[2]), suffix = m[3];
  const decimals = m[2].includes('.') ? m[2].split('.')[1].length : 0;
  const start = performance.now();
  const tick = (now: number): void => {
    const p = Math.min(1, (now - start) / durationMs);
    const eased = 1 - Math.pow(1 - p, 3);
    el.textContent = `${sign}${(target * eased).toFixed(decimals)}${suffix}`;
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

