function getScoringPaths(db: FighterDB): string[] {
  const paths: string[] = [];
  if ((db.slpm ?? 0) >= 4.3) paths.push('Volume');
  if ((db.finishRate ?? 0) >= 0.5) paths.push('Damage');
  if ((db.avgTD ?? 0) >= 1.7 || (db.avgTDperFight ?? 0) >= 1.7) paths.push('Control');
  if ((db.finishRate ?? 0) >= 0.58) paths.push('Finish');
  return paths;
}

function applyBrainV2Overlay(
  db: FighterDB,
  oppDB: FighterDB,
  line: number,
  oppLine: number | null,
  moneyline: number | null,
  oppMoneyline: number | null,
  avgFP: number | null,
  reasons: LeanReason[]
): number {
  const selfBase = db.avgFP_weighted ?? avgFP ?? db.avgFP ?? 0;
  const oppBase = oppDB.avgFP_weighted ?? oppDB.avgFP ?? 0;
  const lineGap = oppLine != null ? line - oppLine : selfBase - oppBase;

  const isFavorite = moneyline != null ? moneyline < 0 : lineGap >= 4;
  const isUnderdog = moneyline != null ? moneyline > 0 : lineGap <= -4;
  const isHeavyFavorite = moneyline != null ? moneyline <= -300 : lineGap >= 10;
  const isExtremeFavorite = moneyline != null ? moneyline <= -600 : lineGap >= 18;

  const overSignals = [
    (db.slpm ?? 0) >= 4.8,
    (avgFP ?? 0) >= line + 4,
    (db.avgTD ?? 0) >= 1.7,
    (db.finishRate ?? 0) >= 0.5,
    (oppDB.strDef ?? 55) < 50 || (oppDB.tdDef ?? 58) < 55 || (oppDB.sapm ?? 3.8) > 4.6,
  ].filter(Boolean).length;

  const underSignals = [
    (db.slpm ?? 0) < 3.4,
    (db.avgTD ?? 0) < 1.2 && (db.tdAcc ?? 40) < 36,
    getScoringPaths(db).length <= 1,
    (db.fpConsistency ?? 55) < 48,
  ].filter(Boolean).length;

  let delta = 0;

  if (isFavorite && overSignals >= 3) {
    delta += 0.8;
    reasons.push({ icon: 'pos', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[0]} — favorite profile shows sustainable scoring conditions` });
  }

  if (isHeavyFavorite && overSignals >= 2) {
    delta += 0.75;
    reasons.push({ icon: 'pos', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[1]} — heavy favorite win equity amplifies scoring${moneyline != null ? ` (ML ${moneyline > 0 ? '+' : ''}${moneyline})` : ''}` });
  }

  if (isExtremeFavorite && overSignals >= 2 && getScoringPaths(db).length >= 2) {
    delta += 1.15;
    reasons.push({ icon: 'pos', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[2]} — extreme mismatch boosts smash OVER expectation${moneyline != null ? ` (ML ${moneyline})` : ' (line-gap proxy)'}` });
  }

  if (moneyline == null && oppMoneyline != null) {
    reasons.push({ icon: 'neu', text: `Moneyline fallback inferred from opponent odds (${oppMoneyline > 0 ? '+' : ''}${oppMoneyline})` });
  }

  if (isUnderdog && underSignals >= 2) {
    delta -= 0.95;
    reasons.push({ icon: 'neg', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[3]} — underdog lacks reliable pace/control paths` });
  }

  const selfPaths = getScoringPaths(db);
  if (selfPaths.length >= 3) {
    delta += 0.6;
    reasons.push({ icon: 'pos', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[7]} (${selfPaths.join(', ')})` });
  } else if (selfPaths.length <= 1) {
    delta -= 0.55;
    reasons.push({ icon: 'neg', text: `${UFC_ANALYZER_BRAIN_V2.global_summary.rules[8]} — single-path profile adds downside variance` });
  }

  return delta;
}

// ── MONEYLINE-ADJUSTED FP PROJECTION ─────────────────────────────────────
function moneylineToImpliedProb(ml: number): number {
  return ml < 0
    ? Math.abs(ml) / (Math.abs(ml) + 100)
    : 100 / (ml + 100);
}

function calcMLAdjustedFP(history: FightResult[], moneyline: number | null): number | null {
  if (!history.length || moneyline == null || !Number.isFinite(moneyline)) return null;

  const wins   = history.filter(h => h.result === 'win'  && h.fp != null && h.fp > 0);
  const losses = history.filter(h => h.result === 'loss' && h.fp != null && h.fp > 0);
  if (!wins.length && !losses.length) return null;
  // Need both sides for the weighting to be meaningful
  if (!wins.length || !losses.length) return null;

  function weightedAvg(fights: FightResult[]): number {
    const w = fights.map((_, i) => Math.pow(0.85, i));
    const tot = w.reduce((s, v) => s + v, 0);
    return fights.reduce((s, f, i) => s + (f.fp ?? 0) * w[i], 0) / tot;
  }

  const winFP  = weightedAvg(wins);
  const lossFP = weightedAvg(losses);
  const p = moneylineToImpliedProb(moneyline);
  return parseFloat((p * winFP + (1 - p) * lossFP).toFixed(1));
}

// ── LEAN ENGINE ────────────────────────────────────────────────────────────
// Empirical-Bayes hit-rate shrinkage (Laplace / Beta(1,1)): one phantom hit +
// one phantom miss pull thin samples toward 50% so the score ladders can't
// award full strength on tiny records (3/4 scores like 67%, not 75%, while
// 12/16 barely moves). Reason text keeps the RAW record — only the ladder
// comparisons read this. Ladder thresholds are tuned so deep records at the
// old raw cutoffs land in the same tier they always did.
function shrunkHitRate(hits: number, n: number): number {
  if (n <= 0) return 0.5;
  return (hits + 1) / (n + 2);
}

/**
 * Wilson score interval bound — the rate we can defend at 95%, not the rate observed.
 *
 * For RANKING leaderboard cells whose sample sizes differ by orders of magnitude.
 * shrunkHitRate (Laplace +1/+1) is the wrong tool here and measurably so: it scores
 * "DK TD 4/4" at .833 against "Pick6 FP 392/632" at .620, so a four-pick cell still
 * outranked a six-hundred-pick one. A fixed +1/+1 prior is simply too light to matter
 * once n leaves single digits, and too light to discipline it while n is there.
 *
 * Wilson scales its penalty with the actual uncertainty: the same 4/4 lands at .510
 * and 392/632 at .582, which is the ordering a reader of the panel actually wants.
 * No arbitrary prior weight to tune.
 *
 * @param lower true for the pessimistic bound (rank BEST cells), false for the
 *              optimistic one (rank WORST cells — otherwise a 3-pick cell tops the
 *              worst list on noise alone, the same bug pointing the other way).
 */
function wilsonBound(hits: number, n: number, lower: boolean): number {
  if (n <= 0) return lower ? 0 : 1;
  const z = 1.96;
  const p = hits / n;
  const denom = 1 + (z * z) / n;
  const centre = p + (z * z) / (2 * n);
  const margin = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));
  return (lower ? centre - margin : centre + margin) / denom;
}

function calcLean(
  name: string,
  db: FighterDB|null,
  line_p6: number|null,
  line_ud: number|null,
  line_pp: number|null,
  line_betr: number|null,
  moneyline: number|null,
  oppDB: FighterDB|null,
  oppLine_p6: number|null = null,
  oppLine_ud: number|null = null,
  oppLine_pp: number|null = null,
  oppLine_betr: number|null = null,
  oppMoneyline: number|null = null,
  platformOverride?: SourcePlatformKey,
): LeanResult {
  // platformOverride lets Best Picks evaluate a fighter's FP lean against a
  // specific book (e.g., PrizePicks) rather than the user's active platform.
  // This matters for FP because PP uses a different scoring formula — its line
  // can't be compared to the P6/UD line directly, the lean must be recomputed
  // against PP's projection.
  const platform = platformOverride ?? currentPlatform;
  const availableLines = ([line_p6, line_ud, line_pp, line_betr].filter(l => l != null) as number[]);
  const avgLine = availableLines.length ? parseFloat((availableLines.reduce((s,l) => s+l, 0) / availableLines.length).toFixed(1)) : null;
  const selectedLine =
    platform === 'pick6' ? line_p6 :
    platform === 'underdog' ? line_ud :
    platform === 'prizepicks' ? line_pp :
    platform === 'draftkings_sportsbook' ? line_p6 :
    line_betr;
  const oppAvailableLines = ([oppLine_p6, oppLine_ud, oppLine_pp, oppLine_betr].filter(l => l != null) as number[]);
  const oppAvgLine = oppAvailableLines.length
    ? parseFloat((oppAvailableLines.reduce((s, l) => s + l, 0) / oppAvailableLines.length).toFixed(1))
    : null;
  const oppSelectedLine =
    platform === 'pick6' ? oppLine_p6 :
    platform === 'underdog' ? oppLine_ud :
    platform === 'prizepicks' ? oppLine_pp :
    platform === 'draftkings_sportsbook' ? oppLine_p6 :
    oppLine_betr;
  const oppLine = oppSelectedLine ?? oppAvgLine;
  const line = selectedLine ?? avgLine;
  if (!line || !db || !db.loaded) return { lean: 'none', conf: 0, reasons: [], verdict: 'Loading stats...' };

  // When called with an explicit platformOverride (Best Picks per-book pass),
  // use ONLY that platform's avgFP. PP scoring differs materially from P6/UD
  // (sub attempts +4pt, no quick-win bonus), so averaging across books would
  // pull the PP projection toward the P6/UD scale and mis-evaluate the lean.
  // Default behavior (no override) keeps the cross-platform average for
  // robustness when the user-facing display can't commit to one book.
  const platformSpecificAvg =
    platformOverride === 'pick6' ? db.avgFP_p6 ?? null :
    platformOverride === 'underdog' ? db.avgFP_ud ?? null :
    platformOverride === 'prizepicks' ? db.avgFP_pp ?? null :
    platformOverride === 'betr' ? db.avgFP_betr ?? null :
    null;
  const platformAvgCandidates = [
    line_p6 != null ? db.avgFP_p6 ?? null : null,
    line_ud != null ? db.avgFP_ud ?? null : null,
    line_pp != null ? db.avgFP_pp ?? null : null,
    line_betr != null ? db.avgFP_betr ?? null : null,
  ].filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
  const avgFP = platformSpecificAvg != null
    ? platformSpecificAvg
    : platformAvgCandidates.length
      ? parseFloat((platformAvgCandidates.reduce((s, v) => s + v, 0) / platformAvgCandidates.length).toFixed(1))
      : (db.avgFP_p6 ?? db.avgFP_ud ?? db.avgFP_pp ?? db.avgFP_betr ?? db.avgFP);
  const history = db.history || [];
  const historyPlatform: 'pick6'|'underdog'|'prizepicks'|'betr' =
    platform === 'pick6' ? 'pick6' :
    platform === 'underdog' ? 'underdog' :
    platform === 'prizepicks' ? 'prizepicks' :
    platform === 'draftkings_sportsbook' ? 'pick6' :
    'betr';
  const historyFP = history.map(h => getFightFantasyValueForPlatform(h, historyPlatform));
  const mlAdjFP = calcMLAdjustedFP(history, moneyline);

  // ── Opp-adjusted FP projection ────────────────────────────────────────────
  // Use opponent's historical FP-allowed to estimate matchup-specific output.
  const oppFPSamples = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => getFightFantasyValueForPlatform(h, historyPlatform))
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const oppAvgFPAllowed = oppFPSamples.length >= 3
    ? parseFloat((oppFPSamples.reduce((s, v) => s + v, 0) / oppFPSamples.length).toFixed(1))
    : null;
  const baseFP = mlAdjFP ?? avgFP ?? null;
  const projFP = (baseFP != null && oppAvgFPAllowed != null)
    ? parseFloat(((baseFP + oppAvgFPAllowed) / 2).toFixed(1))
    : null;
  // When projFP is available it subsumes ML adjustment — use it as the primary signal
  const effectiveFP = projFP ?? baseFP ?? avgFP ?? null;

  const reasons: LeanReason[] = [];
  let score = 0;

  // ── Venue / altitude / cage factors ──────────────────────────────────────
  if (currentVenueFactor.altitudeMeters >= 1200) {
    const altPenalty = currentVenueFactor.altitudeMeters >= 2000 ? -1.5
      : currentVenueFactor.altitudeMeters >= 1500 ? -1.0 : -0.5;
    score += altPenalty;
    reasons.push({ icon: 'neg', text: `High altitude venue (${currentVenueFactor.altitudeMeters}m) — cardio strain reduces FP output` });
  }
  if (currentVenueFactor.cageSizeFt === 25 && db) {
    const cageAdj = db.style === 'grappler' ? 0.3 : db.style === 'striker' ? -0.3 : 0;
    if (cageAdj !== 0) {
      score += cageAdj;
      reasons.push({ icon: cageAdj > 0 ? 'pos' : 'neg',
        text: `Small cage (25ft) — ${cageAdj > 0 ? 'favors grappling-based FP output' : 'limits striking distance for FP'}` });
    }
  }

  if (platformAvgCandidates.length > 1) {
    reasons.push({ icon: 'neu', text: `Platform-aware FP baseline from app-specific scoring profiles across ${platformAvgCandidates.length} books` });
  }

  // Flag line divergence across books — disagreement signals uncertainty or value
  if (availableLines.length > 1) {
    const minL = Math.min(...availableLines);
    const maxL = Math.max(...availableLines);
    if (maxL - minL >= 2.0) {
      const parts = ([['P6', line_p6], ['UD', line_ud], ['PP', line_pp], ['BTR', line_betr]] as [string, number|null][]) 
        .filter(([, v]) => v != null).map(([lbl, v]) => `${lbl} ${v}`).join(' / ');
      if (selectedLine != null) {
        const src = platform === 'pick6' ? 'P6' : platform === 'underdog' ? 'UD' : platform === 'prizepicks' ? 'PP' : platform === 'draftkings_sportsbook' ? 'DK' : 'BTR';
        reasons.push({ icon: 'neu', text: `Books diverge: ${parts} — using ${src} ${selectedLine} for analysis` });
      } else {
        reasons.push({ icon: 'neu', text: `Books diverge: ${parts} — using avg ${line} for analysis` });
      }
      score += (line_p6 ?? line_ud ?? line_pp ?? line_betr)! < line ? 0.3 : -0.3; // favor the lower-line book slightly
    }
  }

  const platformProjections: number[] = [];

  if (effectiveFP != null) {
    const fpLabel = projFP != null
      ? `Proj FP (${effectiveFP.toFixed(1)} — avg ${(baseFP ?? avgFP ?? 0).toFixed(1)} + opp allows ${oppAvgFPAllowed})`
      : `Historical avg (${effectiveFP.toFixed(1)} FP)`;
    const diff = effectiveFP - line;
    if (diff > 12)      { score += 2.5; reasons.push({ icon: 'pos', text: `${fpLabel} is ${diff.toFixed(1)} pts above the line — strong over value` }); }
    else if (diff > 5)  { score += 1.5; reasons.push({ icon: 'pos', text: `${fpLabel} is ${diff.toFixed(1)} pts above the line` }); }
    else if (diff > 1)  { score += 0.5; reasons.push({ icon: 'pos', text: `${fpLabel} slightly edges the line` }); }
    else if (diff < -12){ score -= 2.5; reasons.push({ icon: 'neg', text: `${fpLabel} is ${Math.abs(diff).toFixed(1)} pts BELOW the line — line may be set too high` }); }
    else if (diff < -5) { score -= 1.5; reasons.push({ icon: 'neg', text: `${fpLabel} trails the line by ${Math.abs(diff).toFixed(1)} pts` }); }
    else if (diff < -1) { score -= 0.5; reasons.push({ icon: 'neg', text: `${fpLabel} slightly below the line` }); }
    else                { reasons.push({ icon: 'neu', text: `${fpLabel} is essentially at the line — genuine toss-up` }); }
  } else {
    reasons.push({ icon: 'neu', text: `No historical FP data available — line analysis based on career stats only` });
  }

  // ── MONEYLINE-ADJUSTED PROJECTION ────────────────────────────────────────
  // Only surface the ML adj signal when projFP is NOT active (projFP already incorporates mlAdjFP)
  if (projFP == null && mlAdjFP != null && moneyline != null && avgFP != null) {
    const impliedPct = Math.round(moneylineToImpliedProb(moneyline) * 100);
    const adjDiff = mlAdjFP - line;
    const shift = mlAdjFP - avgFP;
    // Only surface this if the ML adjustment materially changes the picture (≥3 pt shift)
    if (Math.abs(shift) >= 3) {
      const mlLabel = moneyline < 0 ? `${moneyline} (${impliedPct}% win prob)` : `+${moneyline} (${impliedPct}% win prob)`;
      if (adjDiff > 8 && shift > 3) {
        score += 0.8;
        reasons.push({ icon: 'pos', text: `ML-adj projection ${mlAdjFP.toFixed(1)} FP (${mlLabel}) — win-scenario scoring lifts outlook ${shift > 0 ? '+' : ''}${shift.toFixed(1)} vs raw avg` });
      } else if (adjDiff < -8 && shift < -3) {
        score -= 0.8;
        reasons.push({ icon: 'neg', text: `ML-adj projection ${mlAdjFP.toFixed(1)} FP (${mlLabel}) — loss-scenario drag pulls outlook ${shift.toFixed(1)} vs raw avg` });
      } else if (shift > 3) {
        score += 0.4;
        reasons.push({ icon: 'pos', text: `ML-adj projection ${mlAdjFP.toFixed(1)} FP (${mlLabel}) — favorite premium adds +${shift.toFixed(1)} pts to raw avg` });
      } else if (shift < -3) {
        score -= 0.4;
        reasons.push({ icon: 'neg', text: `ML-adj projection ${mlAdjFP.toFixed(1)} FP (${mlLabel}) — underdog discount trims ${Math.abs(shift).toFixed(1)} pts from raw avg` });
      }
    }
  }

  if (history.length >= 3) {
    const hits = historyFP.filter(v => v != null && v > line).length;
    const rate = hits / history.length;
    const rateAdj = shrunkHitRate(hits, history.length);
    if (rateAdj >= 0.72)      { score += 2;   reasons.push({ icon: 'pos', text: `Hit rate: ${hits}/${history.length} fights (${Math.round(rate*100)}%) went over this exact line` }); }
    else if (rateAdj >= 0.58) { score += 1;   reasons.push({ icon: 'pos', text: `Hit rate: ${hits}/${history.length} fights over — consistent over tendency` }); }
    else if (rateAdj <= 0.28) { score -= 2;   reasons.push({ icon: 'neg', text: `Hit rate: only ${hits}/${history.length} fights (${Math.round(rate*100)}%) cleared this line — line is hard to hit` }); }
    else if (rateAdj <= 0.42) { score -= 1;   reasons.push({ icon: 'neg', text: `Hit rate: ${hits}/${history.length} fights over — under tendency at this line` }); }
    else                   {               reasons.push({ icon: 'neu', text: `Hit rate: ${hits}/${history.length} fights over — nearly 50/50` }); }
  }

  if (history.length >= 3 && avgFP != null) {
    const recent = history.slice(0, 3);
    const recentFP = recent.map(h => getFightFantasyValueForPlatform(h, historyPlatform)).filter((v): v is number => v != null);
    const recentAvg = recentFP.length ? recentFP.reduce((s, v) => s + v, 0) / recentFP.length : avgFP;
    const trend = recentAvg - avgFP;
    if (trend > 8)       { score += 1;   reasons.push({ icon: 'pos', text: `Recent form trending UP — last 3 fights avg ${recentAvg.toFixed(1)} FP vs career avg ${avgFP.toFixed(1)}` }); }
    else if (trend < -8) { score -= 1;   reasons.push({ icon: 'neg', text: `Recent form trending DOWN — last 3 fights avg ${recentAvg.toFixed(1)} FP vs career avg ${avgFP.toFixed(1)}` }); }

    // Recent hit rate — more predictive than career hit rate
    const recentHits = recentFP.filter(v => v > line).length;
    if (recentHits === 3)      { score += 1;   reasons.push({ icon: 'pos', text: `Recent hit rate: 3/3 last fights cleared this line — hot right now` }); }
    else if (recentHits === 0) { score -= 1;   reasons.push({ icon: 'neg', text: `Recent hit rate: 0/3 last fights cleared this line — cold streak at this number` }); }
  }

  if (db.style === 'striker') {
    if (db.slpm != null && db.slpm > 6)      { score += 1;   reasons.push({ icon: 'pos', text: `Elite volume striker (${db.slpm.toFixed(1)} SLpM) — naturally high FP ceiling` }); }
    else if (db.slpm != null && db.slpm > 4) { score += 0.3; reasons.push({ icon: 'pos', text: `Active striker (${db.slpm.toFixed(1)} SLpM)` }); }
  } else if (db.style === 'grappler') {
    if (db.avgTD != null && db.avgTD > 3) { score += 0.5; reasons.push({ icon: 'pos', text: `High-volume grappler (${db.avgTD.toFixed(1)} TD/15min) — TD scoring keeps floor high` }); }
    else { score -= 0.5; reasons.push({ icon: 'neg', text: `Grappler style — FP ceiling limited by finishing tendency and low strike volume` }); }
  }

  if (db.finishRate != null) {
    if (db.finishRate > 0.80) { score -= 1.5; reasons.push({ icon: 'neg', text: `Very high finish rate (${Math.round(db.finishRate*100)}%) — frequent early stoppages severely limit counting stats` }); }
    else if (db.finishRate > 0.65) { score -= 1; reasons.push({ icon: 'neg', text: `High finish rate (${Math.round(db.finishRate*100)}%) as winner — early stoppages rob counting stats` }); }
    else if (db.finishRate < 0.35 && history.length >= 4) { score += 0.5; reasons.push({ icon: 'pos', text: `Decision fighter (${Math.round((1-db.finishRate)*100)}% decisions) — fights go full rounds, maximizing volume` }); }
  }

  if (oppDB && oppDB.loaded) {
    const { delta: defDelta, edges: defEdges } = calcOpponentDefenseScore(oppDB, line);
    score += defDelta; reasons.push(...defEdges);

    const oppAllowedSamples = (oppDB.oppHistory || []).slice(0, 5)
      .map((h) => getFightFantasyValueForPlatform(h, historyPlatform))
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
    if (oppAllowedSamples.length >= 3) {
      const allowed = oppAllowedSamples.filter((v) => v > line).length;
      const blocked = oppAllowedSamples.length - allowed;
      const allowedRate = allowed / oppAllowedSamples.length;
      if (allowedRate <= 0.30) {
        score -= 1.1;
        reasons.push({ icon: 'neg', text: `Opponent line defense: only ${allowed}/${oppAllowedSamples.length} opponents cleared ${line.toFixed(2)} FP (${blocked} held under)` });
      } else if (allowedRate <= 0.45) {
        score -= 0.5;
        reasons.push({ icon: 'neg', text: `Opponent line defense: ${allowed}/${oppAllowedSamples.length} opponents cleared ${line.toFixed(2)} FP` });
      } else if (allowedRate >= 0.70) {
        score += 1.1;
        reasons.push({ icon: 'pos', text: `Opponent allows coverage often: ${allowed}/${oppAllowedSamples.length} opponents cleared ${line.toFixed(2)} FP` });
      } else if (allowedRate >= 0.55) {
        score += 0.5;
        reasons.push({ icon: 'pos', text: `Opponent has allowed this FP range: ${allowed}/${oppAllowedSamples.length} opponents cleared ${line.toFixed(2)} FP` });
      } else {
        reasons.push({ icon: 'neu', text: `Opponent line-allow rate is mixed: ${allowed}/${oppAllowedSamples.length} opponents cleared ${line.toFixed(2)} FP` });
      }
    }

    const { delta: matchupDelta, edges: matchupEdges } = styleMatchupEdge(db.style, oppDB.style, db, oppDB);
    score += matchupDelta; reasons.push(...matchupEdges);
    const { score: patScore, reasons: patReasons } = calcMatchupPatternEdge(db, oppDB, null, null, line, statsCache);
    score += patScore; reasons.push(...patReasons);

    // ── Similar-opponent backtest signal ───────────────────────────────────
    if (oppDB.loaded) {
      const simMatches = findSimilarOpponentFights(db, oppDB, 0.45, 5);
      if (simMatches.length >= 2) {
        const simWithFP = simMatches.filter(m => m.betrFP != null);
        if (simWithFP.length >= 2) {
          const simAvgFP = simWithFP.reduce((s, m) => s + m.betrFP!, 0) / simWithFP.length;
          const simDiff = simAvgFP - line;
          const avgSim = simMatches.reduce((s, m) => s + m.similarity, 0) / simMatches.length;
          // Weight the signal by similarity quality (higher similarity = stronger signal)
          const simWeight = Math.min(1.0, avgSim * 1.3);
          if (simDiff > 8)       { score += 1.2 * simWeight; reasons.push({ icon: 'pos', text: `vs similar opponents (${simWithFP.length} fights, ${Math.round(avgSim*100)}% sim): avg ${simAvgFP.toFixed(1)} FP — ${simDiff.toFixed(1)} above line` }); }
          else if (simDiff > 3)  { score += 0.6 * simWeight; reasons.push({ icon: 'pos', text: `vs similar opponents (${simWithFP.length} fights): avg ${simAvgFP.toFixed(1)} FP — edges line by ${simDiff.toFixed(1)}` }); }
          else if (simDiff < -8) { score -= 1.2 * simWeight; reasons.push({ icon: 'neg', text: `vs similar opponents (${simWithFP.length} fights, ${Math.round(avgSim*100)}% sim): avg ${simAvgFP.toFixed(1)} FP — ${Math.abs(simDiff).toFixed(1)} below line` }); }
          else if (simDiff < -3) { score -= 0.6 * simWeight; reasons.push({ icon: 'neg', text: `vs similar opponents (${simWithFP.length} fights): avg ${simAvgFP.toFixed(1)} FP — trails line by ${Math.abs(simDiff).toFixed(1)}` }); }
        }
      }
    }

    // Contextual favorite/underdog behavior & scoring pressure (add-on module)
    const lineGap = oppLine != null ? (line - oppLine) : null;
    const selfBase = db.avgFP_weighted ?? avgFP ?? db.avgFP ?? 0;
    const oppBase = oppDB.avgFP_weighted ?? oppDB.avgFP ?? 0;
    const inferredGap = selfBase - oppBase;
    // Prefer sportsbook moneyline for fav/dog status — cleaner signal than FP line gap
    const isFavorite = moneyline != null ? moneyline <= -150
      : lineGap != null ? lineGap >= 3 : inferredGap >= 8;
    const isUnderdog = moneyline != null ? moneyline >= 150
      : lineGap != null ? lineGap <= -3 : inferredGap <= -8;
    const isHeavyFavorite = moneyline != null && moneyline <= -300;
    const isHeavyUnderdog = moneyline != null && moneyline >= 300;

    const selfPressureProfile =
      (db.style === 'striker' && (db.slpm ?? 0) >= 4.8)
      || ((db.avgTD ?? 0) >= 2.2)
      || ((db.slpm ?? 0) >= 4.2 && (db.avgTD ?? 0) >= 1.6);
    const oppPressureProfile =
      (oppDB.style === 'striker' && (oppDB.slpm ?? 0) >= 4.8)
      || ((oppDB.avgTD ?? 0) >= 2.2)
      || ((oppDB.slpm ?? 0) >= 4.2 && (oppDB.avgTD ?? 0) >= 1.6);

    const selfDefensiveLeaks =
      (db.strDef ?? 55) < 50
      || (db.tdDef ?? 58) < 55
      || (db.sapm ?? 3.8) > 4.4
      || (db.fpConsistency ?? 55) < 45;
    const oppDefensiveLeaks =
      (oppDB.strDef ?? 55) < 50
      || (oppDB.tdDef ?? 58) < 55
      || (oppDB.sapm ?? 3.8) > 4.4
      || (oppDB.fpConsistency ?? 55) < 45;

    const selfNoMinuteWinningTools =
      (db.slpm ?? 0) < 3.2
      && (db.avgTD ?? 0) < 1.2
      && (db.tdAcc ?? 40) < 36
      && (db.fpConsistency ?? 55) < 50;

    const oneWayTraffic =
      selfPressureProfile
      && oppDefensiveLeaks
      && (
        ((db.slpm ?? 0) - (oppDB.slpm ?? 0) >= 0.8)
        || ((db.avgTD ?? 0) - (oppDB.avgTD ?? 0) >= 1.0)
        || ((oppDB.sapm ?? 3.8) >= 4.8)
        || ((oppDB.fpConsistency ?? 55) <= 42)
      );

    if (isFavorite && selfPressureProfile && oppDefensiveLeaks) {
      score += 1.45;
      reasons.push({ icon: 'pos', text: `Favorite pressure path: projected pace/control can suppress opponent output and expand your scoring windows` });
    }

    if (isFavorite && oneWayTraffic) {
      score += 1.25;
      reasons.push({ icon: 'pos', text: `One-way traffic projection: pressure + opponent defensive fragility point to favorite pace dominance` });
    }

    if (isFavorite) {
      const styleExploitsLeak =
        ((db.slpm ?? 0) >= 4.2 && (oppDB.strDef ?? 55) < 52)
        || ((db.avgTD ?? 0) >= 1.8 && (oppDB.tdDef ?? 58) < 58);
      if (oppDefensiveLeaks && styleExploitsLeak) {
        score += 1.05;
        reasons.push({ icon: 'pos', text: `Opponent defensive leaks (str/td defense + absorption profile) inflate favorite scoring expectation` });
      }
    }

    if (isFavorite && (db.finishRate ?? 0) >= 0.45) {
      const hasDecisionVolume = (db.slpm ?? 0) >= 4.0;
      const hasControlPath = (db.avgTD ?? 0) >= 1.5;
      if (hasDecisionVolume || hasControlPath) {
        score += 1.1;
        reasons.push({ icon: 'pos', text: `Favorite finish equity with redundant scoring paths (volume/finish/control) raises OVER probability` });
      }
    }

    if (isFavorite && (db.finishRate ?? 0) >= 0.55 && avgFP != null && (line - avgFP) <= 5) {
      score += 0.6;
      reasons.push({ icon: 'pos', text: `Favorite can clear via multiple paths even near line (decision volume or early finish upside)` });
    }

    if (isUnderdog && oppPressureProfile && selfDefensiveLeaks) {
      score -= 1.35;
      reasons.push({ icon: 'neg', text: `Underdog suppression risk: opponent pressure profile can shrink your attempts, control time, and scoring windows` });
    }

    if (isUnderdog && selfNoMinuteWinningTools) {
      score -= 1.1;
      reasons.push({ icon: 'neg', text: `Underdog lacks reliable minute-winning tools (volume/control pace), increasing UNDER collapse risk` });
    }

    if (isHeavyFavorite && avgFP != null && line <= avgFP + 6) {
      score += 0.8;
      reasons.push({ icon: 'pos', text: `Heavy favorite (${moneyline}) — structural edge: high implied win probability amplifies scoring ceiling and pace dominance` });
    }
    if (isHeavyUnderdog) {
      score -= 0.7;
      reasons.push({ icon: 'neg', text: `Heavy underdog (${moneyline}) — suppression risk elevated; opponent likely controls pace and shortens the fight` });
    }

    // Brain V2 modular overlay: favorite/underdog engine + scoring-path architecture
    score += applyBrainV2Overlay(db, oppDB, line, oppLine, moneyline, oppMoneyline, avgFP ?? null, reasons);
  } else if (oppDB && !oppDB.loaded) {
    reasons.push({ icon: 'neu', text: `Opponent stats loading — matchup analysis will update shortly` });
  }

  const archetypeEdge = calcArchetypeLearnerEdge(name, db, oppDB ?? null, moneyline, line, avgFP ?? effectiveFP ?? null);
  score += archetypeEdge.delta;
  reasons.push(...archetypeEdge.reasons);

  if (db.strAcc != null) {
    if (db.strAcc > 52)      reasons.push({ icon: 'pos', text: `High striking accuracy (${db.strAcc}%) — efficient volume, good FP conversion` });
    else if (db.strAcc < 36) { score -= 0.3; reasons.push({ icon: 'neg', text: `Low striking accuracy (${db.strAcc}%) — volume doesn't always translate to landed strikes` }); }
  }

  if (db.fpFloor != null && db.fpCeiling != null) {
    if (db.fpFloor > line) { score += 1.5; reasons.push({ icon: 'pos', text: `Elite floor: worst recorded game (${db.fpFloor.toFixed(1)} FP) still clears the line — low downside risk` }); }
    else if (db.fpCeiling < line) { score -= 1.5; reasons.push({ icon: 'neg', text: `Hard ceiling: best recorded game (${db.fpCeiling.toFixed(1)} FP) misses the line — very hard to hit over` }); }
    else if (db.fpFloor > line * 0.88 && history.length >= 4) { score += 0.5; reasons.push({ icon: 'pos', text: `Strong floor (${db.fpFloor.toFixed(1)} FP at ${Math.round((db.fpFloor/line)*100)}% of line) — rarely undershoots badly` }); }
  }

  if (db.fpConsistency != null && history.length >= 4) {
    if (db.fpConsistency >= 75) { score += 0.5; reasons.push({ icon: 'pos', text: `High consistency (${db.fpConsistency}%) — FP is predictable and reliable, boosts lean confidence` }); }
    else if (db.fpConsistency <= 35) { score -= 0.5; reasons.push({ icon: 'neg', text: `Volatile fighter (${db.fpConsistency}% consistency) — high variance, line could go either way` }); }
  }

  if (db.streak?.type === 'hot') { score += 0.5; reasons.push({ icon: 'pos', text: `🔥 Hot streak: ${db.streak.text}` }); }
  else if (db.streak?.type === 'cold') { score -= 0.5; reasons.push({ icon: 'neg', text: `❄️ Cold streak: ${db.streak.text}` }); }

  if (db.avgFP_weighted != null && avgFP != null) {
    const drift = db.avgFP_weighted - avgFP;
    if (drift > 10) { score += 0.5; reasons.push({ icon: 'pos', text: `Rising form: recent weighted avg (${db.avgFP_weighted.toFixed(1)}) outpacing career avg (${avgFP.toFixed(1)}) by ${drift.toFixed(1)} pts` }); }
    else if (drift < -10) { score -= 0.5; reasons.push({ icon: 'neg', text: `Fading form: recent weighted avg (${db.avgFP_weighted.toFixed(1)}) lagging career avg (${avgFP.toFixed(1)}) by ${Math.abs(drift).toFixed(1)} pts` }); }
  }

  if (db.fiveRoundRate != null && db.fiveRoundRate > 0.3 && db.avgFP_perRound != null) {
    const projFiveRound = db.avgFP_perRound * 5;
    if (projFiveRound > line * 1.1) { score += 0.3; reasons.push({ icon: 'pos', text: `${Math.round(db.fiveRoundRate*100)}% of fights go 4-5 rounds — FP ceiling expands significantly in long fights (proj ${projFiveRound.toFixed(1)} over 5R)` }); }
  }

  // ── AI ENHANCEMENTS: Integrate multivariate scoring factors ───────────────
  
  // #11: Weighted Recent Form Curve
  const formTrend = calcWeightedFormTrend(history);
  if (formTrend.trend > 3) { score += 0.3; reasons.push({ icon: 'pos', text: `${formTrend.label} — recent fights outpacing average` }); }
  else if (formTrend.trend < -3) { score -= 0.3; reasons.push({ icon: 'neg', text: `${formTrend.label} — recent fights underperforming career average` }); }
  
  // #12: Opponent Strength Adjustment
  if (oppDB && oppDB.loaded) {
    const oppStrengthScore = calcOpponentStrengthScore(oppDB);
    if (oppStrengthScore.score >= 1.45) { score -= 0.8; reasons.push({ icon: 'neg', text: `${oppStrengthScore.label} — high-level opponent profile increases difficulty` }); }
    else if (oppStrengthScore.score >= 0.75) { score -= 0.35; reasons.push({ icon: 'neg', text: `${oppStrengthScore.label} — above-average opponent quality adds resistance` }); }
    else if (oppStrengthScore.score <= -0.4) { score += 0.5; reasons.push({ icon: 'pos', text: `${oppStrengthScore.label} — matchup presents opportunity` }); }
  }
  
  // #13: Fight Context Factors
  const contextFactors = calcFightContextScore(history);
  score += contextFactors.score;
  reasons.push(...contextFactors.reasons);
  
  // #16: Burnout/Rest Cycle
  const restCycle = calcRestCycleFactor(history);
  score += restCycle.score;
  if (restCycle.label && restCycle.score !== 0) {
    reasons.push({ icon: restCycle.score > 0 ? 'pos' : 'neg', text: restCycle.label });
  }
  
  // #19: Extreme Value Detection
  const extremeValue = detectExtremeValue(line, db.fpFloor ?? null, db.fpCeiling ?? null, db.fpStdDev ?? null, history);
  if (extremeValue.isExtreme) {
    reasons.push({ icon: 'neu', text: `${extremeValue.label} — line is ${extremeValue.severity.toFixed(1)} std devs from historical norm` });
  }

  let lean: 'over'|'under'|'push' = 'push';
  const threshold = 1.5;
  if (score >= threshold) lean = 'over';
  else if (score <= -threshold) lean = 'under';
  const rivalry = buildModelRivalry(
    name,
    lean,
    db,
    history,
    line,
    selectedLine ?? null,
    availableLines,
    avgFP ?? null,
    effectiveFP ?? null,
    oppDB ?? null,
    moneyline,
  );
  const confidenceModel = calcEnhancedFPConfidence(
    name,
    lean,
    score,
    db,
    history,
    line,
    selectedLine ?? null,
    availableLines,
    avgFP ?? null,
    effectiveFP ?? null,
    oppDB ?? null,
    moneyline,
    restCycle.daysSince,
    extremeValue.severity || 0,
    rivalry,
  );
  const conf = confidenceModel.confidence;
  reasons.push({
    icon: lean === 'push' ? 'neu' : conf >= 74 ? 'pos' : conf < 58 ? 'neg' : 'neu',
    text: confidenceModel.summary,
  });
  if (confidenceModel.rivalryNote) {
    reasons.push({
      icon: confidenceModel.rivalryDelta > 0 ? 'pos' : 'neg',
      text: confidenceModel.rivalryNote,
    });
  }
  if (confidenceModel.memoryNote) {
    reasons.push({
      icon: confidenceModel.memoryDelta > 0 ? 'pos' : 'neg',
      text: confidenceModel.memoryNote,
    });
  }
  // MODEL v32. Unshifted to the FRONT deliberately when it fires: it is the
  // reason the pick sits where it does, and reasonHeadline() reads reasons[0]
  // to build the verdict line.
  if (confidenceModel.mlGuardNote) {
    reasons.unshift({ icon: 'neg', text: confidenceModel.mlGuardNote });
  }

  // ── GLOW-UP 295 · the headline that was the same on every row ────────────
  // The verdict reads `LEAN OVER <line> — <headline of reasons[0]>`. When
  // reasons[0] is the platform-baseline boilerplate, every row carrying it says
  // "Platform-aware FP baseline from app-specific scoring profiles across 2
  // books" — four of eight overs on the live board, two lines each, and not one
  // word of it distinguishes the pick from any other. The rows that read well
  // (`Proj FP 63.2 · avg 91.4 + opp allows 35 is 25.3 pts BELOW the line`) simply
  // got lucky with their ordering.
  //
  // The project already decided this string is boilerplate — isBoilerplate in the
  // Report Card resolver flags it as `generic` — but that verdict never reached
  // Best Picks. Same test, applied where the headline is chosen: skip it if a real
  // reason follows, and keep it only when it is genuinely all there is.
  //
  // Skips the CHOICE of headline, not the reason itself: it stays in the rail and
  // the tooltip, so nothing is lost, it just stops speaking first.
  const isGenericReason = (t: string | null | undefined): boolean =>
    /^Platform-aware FP baseline/i.test((t ?? '').trim());
  const headlineReason = reasons.find(r => r.text && !isGenericReason(r.text)) ?? reasons[0];

  const lineStr = selectedLine != null
    ? `${platform === 'pick6' ? 'P6' : platform === 'underdog' ? 'UD' : platform === 'prizepicks' ? 'PP' : platform === 'draftkings_sportsbook' ? 'DK' : 'BTR'} ${selectedLine}`
    : (availableLines.length > 1 ? `avg ${line}` : line_p6 ? `P6 ${line_p6}` : line_ud ? `UD ${line_ud}` : line_pp ? `PP ${line_pp}` : `BTR ${line_betr}`);
  const avgStr  = avgFP != null ? ` (avg ${avgFP.toFixed(1)})` : '';
  const verdict = lean === 'over'
    ? `LEAN OVER ${lineStr}${avgStr} — ${reasonHeadline(headlineReason?.text) || 'over value identified'}`
    : lean === 'under'
    ? `LEAN UNDER ${lineStr}${avgStr} — ${reasonHeadline(headlineReason?.text) || 'under value identified'}`
    : `LEAN ${score >= 0 ? 'OVER' : 'UNDER'} ${lineStr}${avgStr} — edge not yet at strong threshold`;

  const ev = lean !== 'push' ? parseFloat(((conf / 100) * 0.1 - (1 - conf / 100) * 1).toFixed(2)) : 0;

  // ── Fair Value Generator ────────────────────────────────────────────────
  const perBookLines: { source: string; line: number }[] = [];
  if (line_p6 != null) perBookLines.push({ source: 'P6', line: line_p6 });
  if (line_ud != null) perBookLines.push({ source: 'UD', line: line_ud });
  if (line_pp != null) perBookLines.push({ source: 'PP', line: line_pp });
  if (line_betr != null) perBookLines.push({ source: 'BTR', line: line_betr });
  const fv = computeFairValue(rivalry, line, perBookLines);

  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: confidenceModel.grade,
    memoryDelta: confidenceModel.memoryDelta,
    memoryNote: confidenceModel.memoryNote,
    mlGuardDelta: confidenceModel.mlGuardDelta,
    mlGuardNote: confidenceModel.mlGuardNote,
    rivalryModels: rivalry.models,
    rivalrySummary: rivalry.summary,
    rivalryDissent: rivalry.dissentSummary,
    rivalryConsensus: rivalry.consensusLean,
    rivalryStrongDissent: rivalry.strongDissent?.model ?? null,
    rivalryConfidenceDelta: rivalry.confidenceDelta,
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    // GLOW-UP 199 L1/L2 — every STAT lean (calcSSLean, calcSSR1Lean, calcTDLean, …)
    // returns its projection and line; the FP lean never did. Consequences were both
    // silent: the Δ edge chip (GLOW-UP 196) rendered blank on every FP pick, and
    // projOpposesLean — the ⚠ PROJ SAYS caution — had to regex the verdict PROSE and
    // its pattern only matched the stat format, so an FP pick whose own projection
    // opposed it was never flagged (Uros Medic: "LEAN OVER BTR 102.5 … Proj FP 75.1 …
    // is 27.4 pts BELOW the line" carried no warning). Exposing the numbers fixes the
    // chip and lets the caution be computed rather than parsed.
    avg: effectiveFP ?? undefined,
    line,
    ev,
    ensembleAgreement: confidenceModel.ensembleAgreement,
    bayesianProbability: confidenceModel.bayesianProbability,
    optimizedLine: confidenceModel.optimizedLine,
    timeWeightedAvg: confidenceModel.timeWeightedAvg,
    kellyBetSize: confidenceModel.kellyBetSize,
    fairValue: fv?.fairValue,
    fairValueEdge: fv?.fairValueEdge,
    fairValuePerBook: fv?.fairValuePerBook,
  };
}

function calcSSLean(
  name: string,
  db: FighterDB|null,
  line_ss: number|null,
  oppDB: FighterDB|null,
  dkLine?: number|null,
  availableLines: number[] = [],
  moneyline: number | null = null,
): LeanResult|null {
  if (!line_ss || !db || !db.loaded) return null;
  const history = (db.history || []).filter(h => h.sigStr != null);
  if (history.length < 3) return null;

  const avgSS = history.reduce((s,h) => s + (h.sigStr || 0), 0) / history.length;

  // ── Opp-adjusted SS projection ────────────────────────────────────────────
  const oppSSSamples = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => h.sigStr)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const oppAvgSSAllowedLean = oppSSSamples.length >= 3
    ? parseFloat((oppSSSamples.reduce((s, v) => s + v, 0) / oppSSSamples.length).toFixed(1))
    : null;
  const projSSLean = oppAvgSSAllowedLean != null
    ? parseFloat(((avgSS + oppAvgSSAllowedLean) / 2).toFixed(1))
    : null;
  let effectiveSS = projSSLean ?? avgSS;

  const reasons: LeanReason[] = [];
  let score = 0;

  // ── Venue / altitude / cage factors ──────────────────────────────────────
  if (currentVenueFactor.altitudeMeters >= 1200) {
    const altPenalty = currentVenueFactor.altitudeMeters >= 2000 ? -0.8
      : currentVenueFactor.altitudeMeters >= 1500 ? -0.5 : -0.3;
    score += altPenalty;
    reasons.push({ icon: 'neg', text: `Altitude (${currentVenueFactor.altitudeMeters}m) — reduced SS volume from cardio fatigue` });
  }
  if (currentVenueFactor.cageSizeFt === 25) {
    score -= 0.3;
    reasons.push({ icon: 'neg', text: 'Small cage (25ft) — less space to maintain distance, lower SS volume' });
  }

  // ── Duration adjustment ───────────────────────────────────────────────────
  // SS accrues with time on the feet; when the market prices this fight much
  // shorter/longer than the fighter's norm, shift the projection (the bimodal-
  // duration blind spot fixed for FT). Bounded, only on a meaningful gap.
  const durAdjSS = durationAdjustProjection(name, db, effectiveSS);
  if (durAdjSS) {
    reasons.push({
      icon: durAdjSS.factor < 1 ? 'neg' : 'pos',
      text: `Duration-adjusted: market ~${durAdjSS.expMins.toFixed(1)}m vs ${durAdjSS.ownMins.toFixed(1)}m career — SS proj ${effectiveSS.toFixed(0)}→${durAdjSS.adjusted.toFixed(0)} (×${durAdjSS.factor.toFixed(2)})`,
    });
    effectiveSS = durAdjSS.adjusted;
  }

  // ── Market anchor (MODEL v37) ─────────────────────────────────────────────
  // The projection ran +6.3 strikes above the actual result across 149 settled
  // picks while the posted line ran +0.3, so the line is the better estimator and
  // the raw projection cleared the line on 68% of picks — the whole source of the
  // 2:1 OVER volume and its 47% hit rate. De-bias, then average with the line.
  // Deliberately not shrink-only: scaling preserves the gap's SIGN and so cuts
  // volume without touching the skew. See the v37 note in config/index.ts.
  const preAnchorSS = effectiveSS;
  effectiveSS = line_ss + SS_MARKET_ANCHOR_WEIGHT * ((effectiveSS - SS_PROJECTION_BIAS) - line_ss);
  if (Math.abs(effectiveSS - preAnchorSS) >= 1) {
    reasons.push({
      // icon is DIRECTIONAL (up/down), not good/bad — see factorPolarity.
      icon: effectiveSS < preAnchorSS ? 'neg' : 'pos',
      text: `Market-anchored: SS proj ${preAnchorSS.toFixed(0)}→${effectiveSS.toFixed(0)} (line ${line_ss}; model runs ~${SS_PROJECTION_BIAS} high vs actual)`,
    });
  }

  const ssLabel = projSSLean != null
    ? `Proj SS (${effectiveSS.toFixed(1)} — avg ${avgSS.toFixed(1)} + opp allows ${oppAvgSSAllowedLean})`
    : `Avg SS (${effectiveSS.toFixed(1)})`;
  const diff = effectiveSS - line_ss;
  if      (diff > 20)  { score += 2.5; reasons.push({ icon:'pos', text:`${ssLabel} is ${diff.toFixed(1)} above line — strong over value` }); }
  else if (diff > 8)   { score += 1.5; reasons.push({ icon:'pos', text:`${ssLabel} edges the line by ${diff.toFixed(1)}` }); }
  else if (diff > 3)   { score += 0.5; reasons.push({ icon:'pos', text:`${ssLabel} slightly above line` }); }
  else if (diff < -20) { score -= 2.5; reasons.push({ icon:'neg', text:`${ssLabel} is ${Math.abs(diff).toFixed(1)} BELOW line — strong under value` }); }
  else if (diff < -8)  { score -= 1.5; reasons.push({ icon:'neg', text:`${ssLabel} trails line by ${Math.abs(diff).toFixed(1)}` }); }
  else if (diff < -3)  { score -= 0.5; reasons.push({ icon:'neg', text:`${ssLabel} slightly below line` }); }
  else                 {               reasons.push({ icon:'neu', text:`${ssLabel} near line — toss-up` }); }

  // ── Hit rate vs this line (MODEL v39: duration-normalised) ────────────────
  // Each past fight is scaled to THIS fight's expected minutes before asking whether it
  // cleared the line. Raw h.sigStr comes from fights of different lengths, so a fighter
  // with 5R main events in his history was credited with clearing a 3R line on volume he
  // only reached because those fights ran 25 minutes. This term is worth ±2 — the largest
  // after diff — and it was the last factor still comparing un-normalised career output
  // against a duration-specific line, while the projection beside it has been
  // duration-adjusted since v6 and market-anchored since v37.
  // Scale is bounded 0.5–1.5 so a 60-second KO is not extrapolated to a full fight: the
  // target is the systematic 3R/5R distortion, not short-fight noise. Falls back to the
  // raw comparison per-fight when duration is missing, so a db without timeSecs behaves
  // exactly as before. (calcTDLean has the same un-normalised pattern — left alone.)
  const schedRoundsSS = upcomingCardPairs.length ? getScheduledRoundsContext(name).rounds : null;
  const expMinsSS = marketExpectedFightMinutes(name, schedRoundsSS);
  let ssNormalisedFights = 0;
  const clearedSSLine = (h: { sigStr?: number | null; timeSecs?: number | null }): boolean => {
    const ss = h.sigStr || 0;
    const mins = Number(h.timeSecs) / 60;
    if (expMinsSS == null || !Number.isFinite(mins) || mins <= 0) return ss > line_ss;
    ssNormalisedFights++;
    return ss * Math.max(0.5, Math.min(1.5, expMinsSS / mins)) > line_ss;
  };
  const hits = history.filter(clearedSSLine).length;
  const rate = hits / history.length;
  const rateAdj = shrunkHitRate(hits, history.length);
  const hrNote = ssNormalisedFights && expMinsSS != null
    ? ` (${ssNormalisedFights}/${history.length} scaled to ~${expMinsSS.toFixed(0)}m)` : '';
  if      (rateAdj >= 0.72) { score += 2;   reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} fights (${Math.round(rate*100)}%) went over SS line${hrNote}` }); }
  else if (rateAdj >= 0.58) { score += 1;   reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} fights over SS line${hrNote}` }); }
  else if (rateAdj <= 0.28) { score -= 2;   reasons.push({ icon:'neg', text:`Hit rate: only ${hits}/${history.length} fights (${Math.round(rate*100)}%) cleared SS line${hrNote}` }); }
  else if (rateAdj <= 0.42) { score -= 1;   reasons.push({ icon:'neg', text:`Hit rate: ${hits}/${history.length} fights over SS line — under tendency${hrNote}` }); }
  else                   {               reasons.push({ icon:'neu', text:`Hit rate: ${hits}/${history.length} fights over SS line — near 50/50${hrNote}` }); }

  if (history.length >= 3) {
    const recentAvg = history.slice(0,3).reduce((s,h) => s + (h.sigStr || 0), 0) / 3;
    const trend = recentAvg - avgSS;
    if      (trend > 15) { score += 1;   reasons.push({ icon:'pos', text:`Recent form UP — last 3 fights avg ${recentAvg.toFixed(0)} SS vs career ${avgSS.toFixed(0)}` }); }
    else if (trend < -15){ score -= 1;   reasons.push({ icon:'neg', text:`Recent form DOWN — last 3 fights avg ${recentAvg.toFixed(0)} SS vs career ${avgSS.toFixed(0)}` }); }
  }

  if (db.style === 'striker') { score += 0.5; reasons.push({ icon:'pos', text:`Striker style — naturally high SS volume` }); }
  else if (db.style === 'grappler') { score -= 0.5; reasons.push({ icon:'neg', text:`Grappler style — may rely on TDs more than striking` }); }

  if (db.strAcc != null && db.strAcc > 52) { score += 0.3; reasons.push({ icon:'pos', text:`High accuracy (${db.strAcc}%) — lands efficiently, SS count reliable` }); }

  if (oppDB?.loaded) {
    const { ssScore: patSS, reasons: patReasons } = calcMatchupPatternEdge(db, oppDB, line_ss, null, null, statsCache);
    score += patSS; reasons.push(...patReasons);

    // Similar-opponent backtest for SS
    const simMatchesSS = findSimilarOpponentFights(db, oppDB, 0.45, 5);
    const simWithSS = simMatchesSS.filter(m => m.fightResult.sigStr != null);
    if (simWithSS.length >= 2) {
      const simAvgSS = simWithSS.reduce((s, m) => s + (m.fightResult.sigStr || 0), 0) / simWithSS.length;
      const simDiff = simAvgSS - line_ss;
      const avgSim = simMatchesSS.reduce((s, m) => s + m.similarity, 0) / simMatchesSS.length;
      const simW = Math.min(1.0, avgSim * 1.3);
      if (simDiff > 12)      { score += 1.0 * simW; reasons.push({ icon: 'pos', text: `vs similar opps (${simWithSS.length} fights): avg ${simAvgSS.toFixed(0)} SS — ${simDiff.toFixed(0)} above line` }); }
      else if (simDiff > 5)  { score += 0.5 * simW; reasons.push({ icon: 'pos', text: `vs similar opps (${simWithSS.length} fights): avg ${simAvgSS.toFixed(0)} SS edges line` }); }
      else if (simDiff < -12){ score -= 1.0 * simW; reasons.push({ icon: 'neg', text: `vs similar opps (${simWithSS.length} fights): avg ${simAvgSS.toFixed(0)} SS — ${Math.abs(simDiff).toFixed(0)} below line` }); }
      else if (simDiff < -5) { score -= 0.5 * simW; reasons.push({ icon: 'neg', text: `vs similar opps (${simWithSS.length} fights): avg ${simAvgSS.toFixed(0)} SS trails line` }); }
    }
  }

  // DK Sportsbook is a sharp line — divergence from fantasy books is a signal
  if (dkLine != null && dkLine !== line_ss && Math.abs(dkLine - line_ss) >= 3) {
    if (dkLine < line_ss) {
      score -= 0.7;
      reasons.push({ icon: 'neg', text: `DK Sportsbook sets SS at ${dkLine} vs fantasy book ${line_ss} — sharp line implies less striking volume` });
    } else {
      score += 0.7;
      reasons.push({ icon: 'pos', text: `DK Sportsbook sets SS at ${dkLine} vs fantasy book ${line_ss} — sharp line implies more striking volume` });
    }
  }

  // MODEL v38 — the ±0.5 tier is gone; |score| < 1.5 is a push.
  // That tier fired a lean at a flat conf 54 off a SINGLE weak factor ("slightly above
  // line" alone is +0.5, as is "striker style"). Measured over the 149 settled SS picks:
  // conf<=55 ran 21/50 = 42% — OVER 40%, UNDER 45%, losing on BOTH sides against a 52.4%
  // breakeven, and the only cut where the two directions agreed. calcSSR1Lean already
  // collapses this exact tier for the same reason; this brings full-fight SS into line.
  // NOTE: 42% was measured under PRE-v37 scoring. The market anchor changes diff, hence
  // score, hence which picks land here — re-measure after Paris rather than expecting 42%.
  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 3)   { lean = 'over';  conf = Math.min(90, 68 + score * 4); }
  else if (score >= 1.5) { lean = 'over';  conf = Math.min(74, 56 + score * 5); }
  else if (score <= -3)  { lean = 'under'; conf = Math.min(90, 68 + Math.abs(score) * 4); }
  else if (score <= -1.5){ lean = 'under'; conf = Math.min(74, 56 + Math.abs(score) * 5); }
  else                   { lean = 'push';  conf = 50; }

  // Variance haircut: high SS spread means the outcome is less predictable
  const ssStdDev = db.ssStdDev ?? null;
  if (ssStdDev != null && lean !== 'push') {
    if (ssStdDev > 14) {
      conf = Math.max(50, conf - 8);
      reasons.push({ icon: 'neg', text: `High SS variance (±${ssStdDev.toFixed(1)}) — volatile output, confidence reduced` });
    } else if (ssStdDev > 7) {
      conf = Math.max(50, conf - 4);
      reasons.push({ icon: 'neu', text: `Moderate SS variance (±${ssStdDev.toFixed(1)}) — some output unpredictability` });
    } else {
      conf = Math.min(90, conf + 3);
      reasons.push({ icon: 'pos', text: `Tight SS variance (±${ssStdDev.toFixed(1)}) — consistent output, confidence boosted` });
    }
  }

  const memoryAdjustment = applyConfidenceMemoryAdjustment({
    fighterName: name,
    source: 'ss',
    lean,
    baseConfidence: conf,
    score,
    db,
    avgValue: avgSS,
    line: line_ss,
    selectedLine: line_ss,
    availableLines: availableLines.length ? availableLines : [line_ss],
    oppDB,
    moneyline,
  });
  conf = memoryAdjustment.confidence;
  if (memoryAdjustment.note) {
    reasons.push({ icon: memoryAdjustment.delta > 0 ? 'pos' : 'neg', text: memoryAdjustment.note });
  }

  // Show the EFFECTIVE projection (opp-adjusted, v6 duration-adjusted AND v37
  // market-anchored), so the headline matches the reasons and the value the score was
  // actually built from. Unconditional since v37: the anchor always applies, so the old
  // `avg N` branch would have printed a number the score never used.
  const ssVerdict = `proj ${effectiveSS.toFixed(1)}`;
  const verdict = lean === 'over'
    ? `SS OVER ${line_ss} (${ssVerdict}) — ${reasons[0]?.text}`
    : lean === 'under'
    ? `SS UNDER ${line_ss} (${ssVerdict}) — ${reasons[0]?.text}`
    : `SS NO LEAN at ${line_ss} (${ssVerdict})`;

  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    memoryDelta: memoryAdjustment.delta,
    memoryNote: memoryAdjustment.note,
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: effectiveSS,
    line: line_ss,
    type: 'ss'
  };
}

// Round-1-only significant-strikes lean (PrizePicks + Underdog + DK Sportsbook).
// Deliberately conservative vs the full-fight SS lean: R1 is a single-round sample
// with built-in early-finish risk, so confidence is capped lower and the weak ±0.5
// tier collapses to a push — only corroborated signals (edge + hit-rate / form /
// style) surface a lean. When PP and UD post different lines, the easiest line for
// the projected direction is used (lowest for OVER, highest for UNDER).
function calcSSR1Lean(
  name: string,
  db: FighterDB|null,
  availableLines: number[] = [],
  oppDB: FighterDB|null,
  moneyline: number | null = null,
): LeanResult|null {
  const lines = availableLines.filter((l): l is number => l != null && Number.isFinite(l));
  if (!lines.length || !db || !db.loaded) return null;
  const history = (db.history || []).filter(h => h.sigStrR1 != null);
  if (history.length < 3) return null;

  const avgR1 = history.reduce((s, h) => s + (h.sigStrR1 || 0), 0) / history.length;

  // Opp-adjusted projection: R1 sig strikes the opponent has historically allowed.
  const oppSamples = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => h.sigStrR1)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const oppAllowed = oppSamples.length >= 3
    ? parseFloat((oppSamples.reduce((s, v) => s + v, 0) / oppSamples.length).toFixed(1))
    : null;

  // MODEL v10: opponent-weighted R1 projection. The flat 50/50 blend under-reads
  // a FINISH-HEAVY fighter against a DURABLE opponent. A fighter who ends fights
  // early has an R1 average deflated by their own stoppages — those low-strike
  // rounds are how they FINISH, not how they STRIKE. When the opponent can't be
  // put away early (long average fight time), the fight will go rounds, so the
  // opponent's allowed number predicts the fighter's R1 output better than the
  // fighter's finish-contaminated history. Up-weight the opponent term in exactly
  // that case — and only when it raises the projection (correcting the deflation
  // upward); a stingy durable opponent doesn't get inflated. Precedent: Sam
  // Patterson (86% finish, R1 avg deflated by early subs) vs Santiago Ponzinibbio
  // (~13m career average, effectively unfinishable early).
  let oppWeight = 0.5;
  let oppWeightNote: string | null = null;
  const fighterFinishHeavy = (db.finishRate ?? 0) >= 0.5;
  const oppDurableMins = oppDB?.avgTimeMins ?? null;
  if (oppAllowed != null && fighterFinishHeavy && oppDurableMins != null && oppDurableMins >= 11 && oppAllowed > avgR1) {
    oppWeight = 0.68;
    oppWeightNote = `Finisher (${Math.round((db.finishRate ?? 0) * 100)}%) vs durable opponent (${oppDurableMins.toFixed(1)}m avg) — own R1 average deflated by early finishes, so opponent-allowed (${oppAllowed}) is weighted higher`;
  }
  const proj = oppAllowed != null
    ? parseFloat((avgR1 * (1 - oppWeight) + oppAllowed * oppWeight).toFixed(1))
    : null;
  const effective = proj ?? avgR1;

  // Pick the best line for the projected direction across PP/UD.
  const minL = Math.min(...lines);
  const maxL = Math.max(...lines);
  const mid = (minL + maxL) / 2;
  const dirHint: 'over' | 'under' = effective >= mid ? 'over' : 'under';
  const line = dirHint === 'over' ? minL : maxL;

  const reasons: LeanReason[] = [];
  let score = 0;

  const label = proj != null
    ? `Proj R1 SS (${effective.toFixed(1)} — avg ${avgR1.toFixed(1)} + opp allows ${oppAllowed})`
    : `Avg R1 SS (${effective.toFixed(1)})`;
  // MODEL v11: a round-1 sig-strike gap is proportionally large — the line sits
  // ~15-20, so a 2-4 strike miss is a real edge, not noise. The old buckets scored
  // a 4.0 gap as "slightly off" (0.6) and used a strict `< -4` boundary, so a proj
  // exactly 4 below the line dropped to the weak tier; a striker prior then cancelled
  // it and the lean died as a toss-up (Ankalaev proj 14.5 vs line 18.5 → NO LEAN when
  // both projection and hit-rate said UNDER). Boundaries are now inclusive and a
  // dedicated 2-4 tier carries the mid-size gaps.
  const diff = effective - line;
  const adiff = Math.abs(diff);
  const dscore = adiff >= 8 ? 2.5 : adiff >= 4 ? 1.6 : adiff >= 2 ? 1.0 : adiff >= 1 ? 0.5 : 0;
  if (dscore === 0) {
    reasons.push({ icon:'neu', text:`${label} near line — toss-up` });
  } else if (diff > 0) {
    score += dscore;
    reasons.push({ icon:'pos', text: adiff >= 8 ? `${label} is ${diff.toFixed(1)} above line — strong over value`
      : adiff >= 4 ? `${label} edges the line by ${diff.toFixed(1)}`
      : `${label} is ${diff.toFixed(1)} above line` });
  } else {
    score -= dscore;
    reasons.push({ icon:'neg', text: adiff >= 8 ? `${label} is ${adiff.toFixed(1)} BELOW line — strong under value`
      : adiff >= 4 ? `${label} trails line by ${adiff.toFixed(1)}`
      : `${label} is ${adiff.toFixed(1)} below line` });
  }

  // Surface the opponent-weight correction (MODEL v10) so a flipped lean is
  // explained, not silent.
  if (oppWeightNote) reasons.push({ icon: 'pos', text: oppWeightNote });

  // Hit rate is the dominant signal for a bounded single-round stat — it directly
  // measures how often the line is covered. An extreme record (never covered, or
  // always covered) over a solid sample is the strongest tell R1 SS offers and is
  // weighted accordingly; it also flags the lean as high-conviction below.
  const hits = history.filter(h => (h.sigStrR1 || 0) > line).length;
  const rate = hits / history.length;
  const rateAdj = shrunkHitRate(hits, history.length);
  const extremeClean = (rate === 0 || rate === 1) && history.length >= 8;
  if      (rate === 1 && history.length >= 8) { score += 3.0; reasons.push({ icon:'pos', text:`Cleared R1 SS line in ALL ${history.length} UFC fights (${history.length}/${history.length}) — structurally clean over` }); }
  else if (rateAdj >= 0.78) { score += 1.8; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} (${Math.round(rate*100)}%) cleared R1 SS line` }); }
  else if (rateAdj >= 0.58) { score += 0.8; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} over R1 SS line` }); }
  else if (rate === 0 && history.length >= 8) { score -= 3.0; reasons.push({ icon:'neg', text:`Never cleared R1 SS line in ${history.length} UFC fights (0/${history.length}) — structurally clean under` }); }
  else if (rateAdj <= 0.22) { score -= 1.8; reasons.push({ icon:'neg', text:`Hit rate: only ${hits}/${history.length} (${Math.round(rate*100)}%) cleared R1 SS line` }); }
  else if (rateAdj <= 0.42) { score -= 0.8; reasons.push({ icon:'neg', text:`Hit rate: ${hits}/${history.length} over R1 SS line — under tendency` }); }
  else                   {               reasons.push({ icon:'neu', text:`Hit rate: ${hits}/${history.length} over R1 SS line — near 50/50` }); }

  if (history.length >= 3) {
    const recentAvg = history.slice(0, 3).reduce((s, h) => s + (h.sigStrR1 || 0), 0) / 3;
    const trend = recentAvg - avgR1;
    if      (trend > 6)  { score += 0.7; reasons.push({ icon:'pos', text:`Recent R1 form UP — last 3 avg ${recentAvg.toFixed(0)} vs career ${avgR1.toFixed(0)}` }); }
    else if (trend < -6) { score -= 0.7; reasons.push({ icon:'neg', text:`Recent R1 form DOWN — last 3 avg ${recentAvg.toFixed(0)} vs career ${avgR1.toFixed(0)}` }); }
  }

  // MODEL v11: archetype nudge, but ONLY when it agrees with the projected direction.
  // A striker's "high output" prior must not cancel a fighter's own projected-under
  // history — that double-counts striking the R1 average already reflects, and it was
  // exactly what buried real unders (Ankalaev, Ponzinibbio) as toss-ups.
  if (db.style === 'striker' && diff > 0) { score += 0.4; reasons.push({ icon:'pos', text:`Striker — typically high round-1 output` }); }
  else if (db.style === 'grappler' && diff < 0) { score -= 0.4; reasons.push({ icon:'neg', text:`Grappler — may chase early takedowns over R1 striking volume` }); }

  // Best-line note last so the diff reason stays as the verdict headline.
  if (lines.length > 1) {
    reasons.push({ icon:'neu', text:`Best ${dirHint.toUpperCase()} line ${line} chosen across PP/UD range ${minL}–${maxL}` });
  }

  // An extreme/clean historical record proves low round-1 variance empirically, so
  // it earns a higher confidence ceiling and is exempt from the volatility haircut
  // (the record already accounts for early finishes and pace swings).
  const cap = extremeClean ? 86 : 80;
  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 3)    { lean = 'over';  conf = Math.min(cap, 62 + score * 3.5); }
  else if (score >= 1.5)  { lean = 'over';  conf = Math.min(70, 54 + score * 5); }
  else if (score <= -3)   { lean = 'under'; conf = Math.min(cap, 62 + Math.abs(score) * 3.5); }
  else if (score <= -1.5) { lean = 'under'; conf = Math.min(70, 54 + Math.abs(score) * 5); }
  else                    { lean = 'push';  conf = 50; }

  // R1 SS volatility haircut — single round + early-finish risk, never boosted.
  // Skipped when the record is structurally clean (variance already proven low).
  const ssStdDev = db.ssStdDev ?? null;
  if (ssStdDev != null && lean !== 'push' && !extremeClean) {
    if (ssStdDev > 14) {
      conf = Math.max(50, conf - 10);
      reasons.push({ icon:'neg', text:`High SS variance (±${ssStdDev.toFixed(1)}) + single-round sample — confidence reduced` });
    } else if (ssStdDev > 7) {
      conf = Math.max(50, conf - 5);
      reasons.push({ icon:'neu', text:`Moderate SS variance (±${ssStdDev.toFixed(1)}) — some R1 unpredictability` });
    }
  }

  const vtxt = proj != null ? `proj ${proj.toFixed(1)}` : `avg ${avgR1.toFixed(1)}`;
  const headline = reasons.find(r => r.icon !== 'neu')?.text ?? reasons[0]?.text ?? '';
  const verdict = lean === 'over'
    ? `R1 SS OVER ${line} (${vtxt}) — ${headline}`
    : lean === 'under'
      ? `R1 SS UNDER ${line} (${vtxt}) — ${headline}`
      : `R1 SS NO LEAN at ${line} (${vtxt})`;

  void name; void moneyline;
  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: effective,
    line,
    type: 'ss_r1',
  };
}

// Knockdowns lean (PrizePicks-only, line typically 0.5 → OVER = at least one KD).
// KDs are rare, high-variance events, so this is the MOST conservative lean source:
// hit-rate driven (how often the fighter's per-fight KD count beat the line),
// corroborated by how often the OPPONENT has been knocked down. Only fighters whose
// PP card offers BOTH More and Less (kd_under_available === true, i.e. a standard
// projection, not a demon/goblin) are Best-Picks eligible — gated in isCandidateUsable.
function calcKDLean(
  name: string,
  db: FighterDB|null,
  line_kd: number|null,
  oppDB: FighterDB|null,
): LeanResult|null {
  if (line_kd == null || !db || !db.loaded) return null;
  const history = (db.history || []).filter(h => h.kd != null);
  if (history.length < 5) return null; // rare stat — demand a real sample

  const avgKd = history.reduce((s, h) => s + (h.kd || 0), 0) / history.length;
  const hits = history.filter(h => (h.kd || 0) > line_kd).length;
  const rate = hits / history.length;
  const rateAdj = shrunkHitRate(hits, history.length);
  const extremeClean = (rate === 0 || rate === 1) && history.length >= 10;

  const reasons: LeanReason[] = [];
  let score = 0;

  // Hit rate IS the signal for a mostly-zero count stat. Note the asymmetric ladder:
  // clearing a 0.5 KD line in 50%+ of fights is elite power; most fighters sit near 0,
  // so the under thresholds are much closer to the floor.
  if      (rate === 1 && history.length >= 10) { score += 3.0; reasons.push({ icon:'pos', text:`Scored a knockdown in ALL ${history.length} tracked fights — structurally clean over` }); }
  else if (rateAdj >= 0.55) { score += 1.8; reasons.push({ icon:'pos', text:`KD in ${hits}/${history.length} fights (${Math.round(rate*100)}%) — elite drop rate vs ${line_kd} line` }); }
  else if (rateAdj >= 0.45) { score += 0.8; reasons.push({ icon:'pos', text:`KD in ${hits}/${history.length} fights — above-average drop rate` }); }
  else if (rate === 0 && history.length >= 10) { score -= 3.0; reasons.push({ icon:'neg', text:`No knockdown in ${history.length} tracked fights (0/${history.length}) — structurally clean under` }); }
  else if (rateAdj <= 0.16) { score -= 1.8; reasons.push({ icon:'neg', text:`KD in only ${hits}/${history.length} fights (${Math.round(rate*100)}%) — rarely drops opponents` }); }
  else if (rateAdj <= 0.30) { score -= 0.8; reasons.push({ icon:'neg', text:`KD in ${hits}/${history.length} fights — under tendency` }); }
  else                      {               reasons.push({ icon:'neu', text:`KD in ${hits}/${history.length} fights — no strong tendency vs ${line_kd} line` }); }

  // Opponent durability: how often the opponent has been dropped (their own fight
  // history's oppStats.kd = knockdowns scored against them).
  const oppDropped = (oppDB?.history ?? [])
    .map(h => h.oppStats?.kd)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
  if (oppDropped.length >= 5) {
    const oppDropRate = oppDropped.filter(v => v > line_kd).length / oppDropped.length;
    if (oppDropRate >= 0.4) { score += 0.8; reasons.push({ icon:'pos', text:`Opponent has been dropped in ${Math.round(oppDropRate*100)}% of tracked fights — vulnerable chin` }); }
    else if (oppDropRate <= 0.1) { score -= 0.8; reasons.push({ icon:'neg', text:`Opponent almost never gets dropped (${Math.round(oppDropRate*100)}% of fights) — durable` }); }
  }

  if (db.style === 'striker') { score += 0.3; reasons.push({ icon:'pos', text:`Striker — more KD-capable output` }); }
  else if (db.style === 'grappler') { score -= 0.3; reasons.push({ icon:'neg', text:`Grappler — fewer power-strike exchanges` }); }

  // Conservative caps — a knockdown is a single moment of variance; only a structurally
  // clean record earns the higher ceiling.
  const cap = extremeClean ? 82 : 76;
  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 2.8)  { lean = 'over';  conf = Math.min(cap, 60 + score * 3); }
  else if (score >= 1.6)  { lean = 'over';  conf = Math.min(68, 52 + score * 4.5); }
  else if (score <= -2.8) { lean = 'under'; conf = Math.min(cap, 60 + Math.abs(score) * 3); }
  else if (score <= -1.6) { lean = 'under'; conf = Math.min(68, 52 + Math.abs(score) * 4.5); }
  else                    { lean = 'push';  conf = 50; }

  const headline = reasons.find(r => r.icon !== 'neu')?.text ?? reasons[0]?.text ?? '';
  const verdict = lean === 'over'
    ? `KD OVER ${line_kd} (avg ${avgKd.toFixed(2)}/fight) — ${headline}`
    : lean === 'under'
      ? `KD UNDER ${line_kd} (avg ${avgKd.toFixed(2)}/fight) — ${headline}`
      : `KD NO LEAN at ${line_kd} (avg ${avgKd.toFixed(2)}/fight)`;

  void name;
  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: parseFloat(avgKd.toFixed(2)),
    line: line_kd,
    type: 'kd',
  };
}

// MODEL v20 (2026-08-06) — evaluate a TD lean at the BEST posted line, not at
// whichever book wins a fixed precedence order.
//
// The books do not post shaded versions of one market here, they post DIFFERENT
// QUESTIONS. DraftKings' takedown line is "lands ANY takedown" = 0.5; the pick'em
// books ask "lands two or more" = 1.5+. The old p6-first order judged Darren
// Elkins at 1.5 — projection 1.2, just under, so NO LEAN — while his record
// against DK's 0.5 was 24 of 30 with L5 5/5 and the opponent allowing it in 2 of
// 4. Answering only the pick'em question hid a real edge behind a shrug.
//
// So ask every question that is actually posted and keep the strongest answer.
// Falls back to the precedence line when no line produces a lean, so a no-lean
// row still renders its "NO LEAN at X" verdict instead of vanishing.
//
// KNOWN TRADE-OFF — this is a best-of-N selection, so it is mildly optimistic by
// construction: scanning several lines and keeping the best finds a favourable
// framing more often than judging one line would. The confidence recalibration
// pass (per source-type x bucket, against realized accuracy) is what corrects
// that over time; do not "fix" it by re-narrowing to one book.
function bestTdLean(
  name: string,
  db: FighterDB|null,
  oppDB: FighterDB|null,
  dkLine: number|null,
  availableLines: number[],
  moneyline: number|null,
  fallbackLine: number|null,
): LeanResult|null {
  let best: LeanResult|null = null;
  for (const candidate of [...new Set(availableLines)]) {
    const r = calcTDLean(name, db, candidate, oppDB, dkLine, availableLines, moneyline);
    if (r && r.lean !== 'none' && (!best || r.conf > best.conf)) best = r;
  }
  return best ?? calcTDLean(name, db, fallbackLine, oppDB, dkLine, availableLines, moneyline);
}

function calcTDLean(
  name: string,
  db: FighterDB|null,
  line_td: number|null,
  oppDB: FighterDB|null,
  dkLine?: number|null,
  availableLines: number[] = [],
  moneyline: number | null = null,
): LeanResult|null {
  if (!line_td || !db || !db.loaded) return null;
  const history = (db.history || []).filter(h => h.td != null);
  if (history.length < 3) return null;

  const avgTD = history.reduce((s,h) => s + (h.td || 0), 0) / history.length;

  // ── Opp-adjusted TD projection ────────────────────────────────────────────
  const oppTDSamples = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => h.td)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v >= 0);
  const oppAvgTDAllowed = oppTDSamples.length >= 3
    ? parseFloat((oppTDSamples.reduce((s, v) => s + v, 0) / oppTDSamples.length).toFixed(1))
    : null;
  const projTD = (oppAvgTDAllowed != null)
    ? parseFloat(((avgTD + oppAvgTDAllowed) / 2).toFixed(1))
    : null;
  let effectiveTD = projTD ?? avgTD;

  const reasons: LeanReason[] = [];
  let score = 0;

  // ── Venue / altitude / cage factors ──────────────────────────────────────
  if (currentVenueFactor.altitudeMeters >= 1200) {
    const altBoost = currentVenueFactor.altitudeMeters >= 2000 ? 0.4
      : currentVenueFactor.altitudeMeters >= 1500 ? 0.3 : 0.2;
    score += altBoost;
    reasons.push({ icon: 'pos', text: `Altitude (${currentVenueFactor.altitudeMeters}m) — fatigued fighters clinch more, TD attempts rise` });
  }
  if (currentVenueFactor.cageSizeFt === 25) {
    score += 0.4;
    reasons.push({ icon: 'pos', text: 'Small cage (25ft) — less space to sprawl, more TD opportunities' });
  }

  // Duration adjustment — TDs accrue with time on the feet/mat too. Same bounded
  // market-vs-career scaling as SS.
  const durAdjTD = durationAdjustProjection(name, db, effectiveTD);
  if (durAdjTD) {
    reasons.push({
      icon: durAdjTD.factor < 1 ? 'neg' : 'pos',
      text: `Duration-adjusted: market ~${durAdjTD.expMins.toFixed(1)}m vs ${durAdjTD.ownMins.toFixed(1)}m career — TD proj ${effectiveTD.toFixed(1)}→${durAdjTD.adjusted.toFixed(1)} (×${durAdjTD.factor.toFixed(2)})`,
    });
    effectiveTD = durAdjTD.adjusted;
  }

  const tdLabel = projTD != null
    ? `Proj TDs (${effectiveTD.toFixed(1)} — avg ${avgTD.toFixed(1)} + opp allows ${oppAvgTDAllowed})`
    : `Avg TDs (${effectiveTD.toFixed(1)})`;
  const diff = effectiveTD - line_td;
  if      (diff > 3)   { score += 2.5; reasons.push({ icon:'pos', text:`${tdLabel} is ${diff.toFixed(1)} above line — strong over value` }); }
  else if (diff > 1.5) { score += 1.5; reasons.push({ icon:'pos', text:`${tdLabel} edges line by ${diff.toFixed(1)}` }); }
  else if (diff > 0.5) { score += 0.5; reasons.push({ icon:'pos', text:`${tdLabel} slightly above line` }); }
  else if (diff < -3)  { score -= 2.5; reasons.push({ icon:'neg', text:`${tdLabel} is ${Math.abs(diff).toFixed(1)} BELOW line — strong under value` }); }
  else if (diff < -1.5){ score -= 1.5; reasons.push({ icon:'neg', text:`${tdLabel} trails line by ${Math.abs(diff).toFixed(1)}` }); }
  else if (diff < -0.5){ score -= 0.5; reasons.push({ icon:'neg', text:`${tdLabel} slightly below line` }); }
  else                 {               reasons.push({ icon:'neu', text:`${tdLabel} near line — toss-up` }); }

  const hits = history.filter(h => (h.td || 0) > line_td).length;
  const rate = hits / history.length;
  const rateAdj = shrunkHitRate(hits, history.length);
  if      (rateAdj >= 0.72) { score += 2;   reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} fights (${Math.round(rate*100)}%) exceeded TD line` }); }
  else if (rateAdj >= 0.58) { score += 1;   reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${history.length} fights over TD line` }); }
  else if (rateAdj <= 0.28) { score -= 2;   reasons.push({ icon:'neg', text:`Hit rate: only ${hits}/${history.length} fights (${Math.round(rate*100)}%) cleared TD line` }); }
  else if (rateAdj <= 0.42) { score -= 1;   reasons.push({ icon:'neg', text:`Hit rate: ${hits}/${history.length} fights over TD line — under tendency` }); }
  else                   {               reasons.push({ icon:'neu', text:`Hit rate: ${hits}/${history.length} fights over TD line — near 50/50` }); }

  if (history.length >= 3) {
    const recentAvg = history.slice(0,3).reduce((s,h) => s + (h.td || 0), 0) / 3;
    const trend = recentAvg - avgTD;
    if      (trend > 2)  { score += 1;   reasons.push({ icon:'pos', text:`Recent form UP — last 3 fights avg ${recentAvg.toFixed(1)} TDs vs career ${avgTD.toFixed(1)}` }); }
    else if (trend < -2) { score -= 1;   reasons.push({ icon:'neg', text:`Recent form DOWN — last 3 fights avg ${recentAvg.toFixed(1)} TDs vs career ${avgTD.toFixed(1)}` }); }
  }

  if (db.style === 'grappler') { score += 1; reasons.push({ icon:'pos', text:`Grappler style — TDs are primary weapon` }); }
  else if (db.style === 'striker') { score -= 0.5; reasons.push({ icon:'neg', text:`Striker style — TDs not primary weapon` }); }

  if (db.tdDef != null && db.tdDef > 75) { score -= 0.5; reasons.push({ icon:'neg', text:`Opponent has strong TD defense — may limit attempts` }); }
  else if (db.tdDef != null && db.tdDef < 50) { score += 0.5; reasons.push({ icon:'pos', text:`Opponent has weak TD defense — good target for takedowns` }); }

  if (oppDB?.loaded) {
    const { tdScore: patTD, reasons: patReasons } = calcMatchupPatternEdge(db, oppDB, null, line_td, null, statsCache);
    score += patTD; reasons.push(...patReasons);

    // Similar-opponent backtest for TD
    const simMatchesTD = findSimilarOpponentFights(db, oppDB, 0.45, 5);
    const simWithTD = simMatchesTD.filter(m => m.fightResult.td != null);
    if (simWithTD.length >= 2) {
      const simAvgTD = simWithTD.reduce((s, m) => s + (m.fightResult.td || 0), 0) / simWithTD.length;
      const simDiff = simAvgTD - line_td;
      const avgSim = simMatchesTD.reduce((s, m) => s + m.similarity, 0) / simMatchesTD.length;
      const simW = Math.min(1.0, avgSim * 1.3);
      if (simDiff > 2)       { score += 1.0 * simW; reasons.push({ icon: 'pos', text: `vs similar opps (${simWithTD.length} fights): avg ${simAvgTD.toFixed(1)} TDs — ${simDiff.toFixed(1)} above line` }); }
      else if (simDiff > 0.8){ score += 0.5 * simW; reasons.push({ icon: 'pos', text: `vs similar opps (${simWithTD.length} fights): avg ${simAvgTD.toFixed(1)} TDs edges line` }); }
      else if (simDiff < -2) { score -= 1.0 * simW; reasons.push({ icon: 'neg', text: `vs similar opps (${simWithTD.length} fights): avg ${simAvgTD.toFixed(1)} TDs — ${Math.abs(simDiff).toFixed(1)} below line` }); }
      else if (simDiff < -0.8){score -= 0.5 * simW; reasons.push({ icon: 'neg', text: `vs similar opps (${simWithTD.length} fights): avg ${simAvgTD.toFixed(1)} TDs trails line` }); }
    }
  }

  if (dkLine != null && dkLine !== line_td && Math.abs(dkLine - line_td) >= 1) {
    if (dkLine < line_td) {
      score -= 0.7;
      reasons.push({ icon: 'neg', text: `DK Sportsbook sets TD at ${dkLine} vs fantasy book ${line_td} — sharp line implies fewer takedowns` });
    } else {
      score += 0.7;
      reasons.push({ icon: 'pos', text: `DK Sportsbook sets TD at ${dkLine} vs fantasy book ${line_td} — sharp line implies more takedowns` });
    }
  }

  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 3)   { lean = 'over';  conf = Math.min(90, 68 + score * 4); }
  else if (score >= 1.5) { lean = 'over';  conf = Math.min(74, 56 + score * 5); }
  else if (score >= 0.5) { lean = 'over';  conf = 54; }
  else if (score <= -3)  { lean = 'under'; conf = Math.min(90, 68 + Math.abs(score) * 4); }
  else if (score <= -1.5){ lean = 'under'; conf = Math.min(74, 56 + Math.abs(score) * 5); }
  else if (score <= -0.5){ lean = 'under'; conf = 54; }
  else                   { lean = 'push';  conf = 50; }

  const memoryAdjustment = applyConfidenceMemoryAdjustment({
    fighterName: name,
    source: 'td',
    lean,
    baseConfidence: conf,
    score,
    db,
    avgValue: avgTD,
    line: line_td,
    selectedLine: line_td,
    availableLines: availableLines.length ? availableLines : [line_td],
    oppDB,
    moneyline,
  });
  conf = memoryAdjustment.confidence;
  if (memoryAdjustment.note) {
    reasons.push({ icon: memoryAdjustment.delta > 0 ? 'pos' : 'neg', text: memoryAdjustment.note });
  }

  // Effective projection = opp-adjusted AND v6 duration-adjusted, matching the reason text.
  const tdVerdict = (projTD != null || durAdjTD != null) ? `proj ${effectiveTD.toFixed(1)}` : `avg ${avgTD.toFixed(1)}`;
  const verdict = lean === 'over'
    ? `TD OVER ${line_td} (${tdVerdict}) — ${reasons[0]?.text}`
    : lean === 'under'
    ? `TD UNDER ${line_td} (${tdVerdict}) — ${reasons[0]?.text}`
    : `TD NO LEAN at ${line_td} (${tdVerdict})`;

  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    memoryDelta: memoryAdjustment.delta,
    memoryNote: memoryAdjustment.note,
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: effectiveTD,
    line: line_td,
    type: 'td'
  };
}

// American odds → implied probability (includes vig).
function americanToImplied(a: number | null | undefined): number | null {
  if (a == null || !Number.isFinite(a) || a === 0) return null;
  return a < 0 ? (-a) / ((-a) + 100) : 100 / (a + 100);
}

// De-vigged P(fight REACHES round N) from a "Fight to Start Round N" Yes/No pair.
function devigReachRound(pair?: { yes: number | null; no: number | null } | null): number | null {
  if (!pair) return null;
  const y = americanToImplied(pair.yes), n = americanToImplied(pair.no);
  if (y == null || n == null) return null;
  const s = y + n;
  if (s <= 0) return null;
  return Math.min(1, Math.max(0, y / s));
}

// Resolve a fighter's DK round-start ladder (fuzzy name match, like moneylines).
function resolveRoundStartFromMap(name: string): Record<string, { yes: number | null; no: number | null }> | null {
  const normalized = normalizeName(name);
  if (!normalized) return null;
  if (dkRoundStartByName[normalized]) return dkRoundStartByName[normalized];
  for (const [k, v] of Object.entries(dkRoundStartByName)) {
    if (namesMatch(k, normalized)) return v;
  }
  return null;
}

// De-vigged P(fight goes to DECISION) from DK's "Fight to Go the Distance" market.
function resolveDistanceDecisionProb(name: string): number | null {
  const normalized = normalizeName(name);
  if (!normalized) return null;
  let pair = dkDistanceByName[normalized];
  if (!pair) {
    for (const [k, v] of Object.entries(dkDistanceByName)) {
      if (namesMatch(k, normalized)) { pair = v; break; }
    }
  }
  if (!pair) return null;
  const y = americanToImplied(pair.yes), n = americanToImplied(pair.no);
  if (y == null || n == null) return null;
  const s = y + n;
  if (s <= 0) return null;
  return Math.min(1, Math.max(0, y / s)); // Yes = goes the distance
}

// De-vigged CONDITIONAL finish-time shape from DK's Time-of-Finish 1-minute buckets:
// [{ start, p }] with p summing to 1 (P of finishing in that minute GIVEN a finish).
function finishHistogramConditional(name: string): Array<{ start: number; p: number }> | null {
  const normalized = normalizeName(name);
  if (!normalized) return null;
  let buckets = dkTimeOfFinishByName[normalized];
  if (!buckets) {
    for (const [k, v] of Object.entries(dkTimeOfFinishByName)) {
      if (namesMatch(k, normalized)) { buckets = v; break; }
    }
  }
  if (!buckets || !buckets.length) return null;
  const implied = buckets
    .map(b => ({ start: b.start, p: americanToImplied(b.odds) }))
    .filter((b): b is { start: number; p: number } => b.p != null && b.p > 0);
  const sum = implied.reduce((s, b) => s + b.p, 0);
  if (sum <= 0) return null;
  return implied.map(b => ({ start: b.start, p: b.p / sum }));
}

// P(fight duration < line) straight from the Time-of-Finish histogram (finish shape)
// × (1 − P(decision)) from the distance market. Preferred over the round-ladder
// derivation — no uniform-within-round assumption. Null if either market is missing.
function marketFtUnderProbDirect(name: string, line: number): number | null {
  const shape = finishHistogramConditional(name);
  const pDecision = resolveDistanceDecisionProb(name);
  if (!shape || pDecision == null) return null;
  const pFinish = 1 - pDecision;
  let p = 0;
  for (const b of shape) {
    const abs = b.p * pFinish;                             // absolute P(finish in this 1-min bucket)
    if (b.start + 1 <= line) p += abs;                     // whole bucket before the line
    else if (b.start < line) p += abs * (line - b.start);  // partial (buckets are 1 min wide)
  }
  return Math.min(1, Math.max(0, p));                      // decisions sit at full duration — never under a sub-max line
}

// E[fight minutes] from the "Fight to Start Round" ladder + "Go the Distance".
// Unlike the Time-of-Finish version below, these two markets carry FULL-SLATE
// coverage (26/26 on the Ankalaev card) rather than main-event-only, so this is
// the variant the Prop Line Predictor can actually rely on. Builds the per-round
// finish distribution from the ladder:
//   P(finish in round r) = P(reach r) − P(reach r+1),  final round exits to decision
// then takes the mid-round finish time as the expected exit point.
function marketExpectedFightMinutesFromLadder(name: string, schedRounds: number | null): number | null {
  const pDecision = resolveDistanceDecisionProb(name);
  const ladder = resolveRoundStartFromMap(name);
  if (pDecision == null || !ladder) return null;
  const maxRound = schedRounds && schedRounds > 0 ? schedRounds : 3;
  // P(reach round r) for r = 1..maxRound. De-vig noise can break monotonicity, so
  // clamp each rung between the decision probability and the previous rung.
  const reach: number[] = [1];
  for (let r = 2; r <= maxRound; r++) {
    const prev = reach[reach.length - 1];
    const raw = devigReachRound(ladder[String(r)]);
    reach.push(Math.min(prev, Math.max(pDecision, raw ?? prev)));
  }
  let e = 0;
  for (let r = 1; r <= maxRound; r++) {
    const next = r < maxRound ? reach[r] : pDecision;
    e += Math.max(0, reach[r - 1] - next) * ((r - 1) * 5 + 2.5);
  }
  return e + pDecision * (maxRound * 5);
}

// E[fight minutes] straight from the Time-of-Finish histogram + distance market.
function marketExpectedFightMinutesDirect(name: string, schedRounds: number | null): number | null {
  const shape = finishHistogramConditional(name);
  const pDecision = resolveDistanceDecisionProb(name);
  if (!shape || pDecision == null) return null;
  const maxRound = schedRounds && schedRounds > 0 ? schedRounds : 3;
  const pFinish = 1 - pDecision;
  let e = pDecision * (maxRound * 5);
  for (const b of shape) e += b.p * pFinish * (b.start + 0.5);  // mid-bucket finish time
  return e;
}

// Market-implied P(fight duration < `line` minutes). Prefers DK's Time-of-Finish
// histogram; falls back to the round-start ladder (+ "Fight to Go the Distance" for the
// final round). Returns null when the covering markets are missing — callers then fall
// back to stat-only logic.
function marketFtUnderProb(name: string, line: number, schedRounds: number | null): number | null {
  if (!Number.isFinite(line) || line <= 0) return null;
  const direct = marketFtUnderProbDirect(name, line);
  if (direct != null) return direct;
  const ladder = resolveRoundStartFromMap(name);
  if (!ladder) return null;
  const maxRound = schedRounds && schedRounds > 0 ? schedRounds : 3;
  const r = Math.min(maxRound, Math.max(1, Math.ceil(line / 5)));  // round the line sits in
  const offset = Math.min(5, Math.max(0, line - (r - 1) * 5));     // minutes into round r
  const reach = (k: number): number | null => (k <= 1 ? 1 : devigReachRound(ladder[String(k)]));

  if (r >= maxRound) {
    // Final scheduled round: the round ladder alone can't split a late finish from a
    // decision. DK's "Fight to Go the Distance" gives P(decision), which sits at the
    // full duration (never under a sub-max line), so the finishes in the last round
    // are (reachFinal - pDecision), spread uniformly across the round.
    const pDecision = resolveDistanceDecisionProb(name);
    const reachFinal = reach(maxRound);
    if (pDecision == null || reachFinal == null) return null;
    const endedBeforeFinal = 1 - reachFinal;                      // finished in rounds 1..maxRound-1
    const finishesInFinal = Math.max(0, reachFinal - pDecision);  // finishes during the final round
    const p = endedBeforeFinal + finishesInFinal * (offset / 5);
    return Math.min(1, Math.max(0, p));
  }

  const rr = reach(r), rr1 = reach(r + 1);
  if (rr == null || rr1 == null) return null;
  const endedBeforeRoundR = 1 - rr;                               // finished in rounds 1..r-1
  const endsInRoundR = Math.max(0, rr - rr1);                     // finishes during round r (uniform within round)
  const p = endedBeforeRoundR + endsInRoundR * (offset / 5);
  return Math.min(1, Math.max(0, p));
}

// Fighter's average fight duration (minutes) from UFCStats history.
function avgFightMinutes(db: FighterDB | null): number | null {
  const timed = (db?.history || []).map(h => Number(h.timeSecs)).filter(v => Number.isFinite(v) && v > 0);
  if (timed.length < 3) return null;
  return (timed.reduce((s, v) => s + v, 0) / timed.length) / 60;
}

// Market-implied EXPECTED fight duration (minutes) from DK's round ladder + distance
// market. Used to duration-adjust SS/TD projections (both scale with time on the feet).
// Σ P(finish in round r)·(mid-round mins) + P(decision)·(full duration).
function marketExpectedFightMinutes(name: string, schedRounds: number | null): number | null {
  const direct = marketExpectedFightMinutesDirect(name, schedRounds);
  if (direct != null) return direct;
  const ladder = resolveRoundStartFromMap(name);
  if (!ladder) return null;
  const maxRound = schedRounds && schedRounds > 0 ? schedRounds : 3;
  const reach = (k: number): number | null => (k <= 1 ? 1 : devigReachRound(ladder[String(k)]));
  const pDecision = resolveDistanceDecisionProb(name);
  let expected = 0;
  for (let r = 1; r <= maxRound; r++) {
    const rr = reach(r);
    if (rr == null) return null;
    const midFinishMins = (r - 1) * 5 + 2.5;            // uniform finish within the round
    if (r < maxRound) {
      const rNext = reach(r + 1);
      if (rNext == null) return null;
      expected += Math.max(0, rr - rNext) * midFinishMins;
    } else {
      const dec = pDecision ?? 0;
      expected += Math.max(0, rr - dec) * midFinishMins;  // finishes in the final round
      expected += dec * (maxRound * 5);                    // decisions at full duration
    }
  }
  return expected;
}

// Duration-scale a per-fight stat projection when the market prices THIS fight
// materially shorter/longer than the fighter's own norm (SS/TD both accrue with time
// on the feet). Returns { adjusted, factor, expMins, ownMins } or null when it doesn't
// apply (no market/history, or the gap is within noise). Bounded 0.5–1.4×.
function durationAdjustProjection(name: string, db: FighterDB | null, value: number): { adjusted: number; factor: number; expMins: number; ownMins: number } | null {
  const schedR = upcomingCardPairs.length ? getScheduledRoundsContext(name).rounds : null;
  const expMins = marketExpectedFightMinutes(name, schedR);
  const ownMins = avgFightMinutes(db);
  if (expMins == null || ownMins == null || ownMins <= 0) return null;
  const raw = expMins / ownMins;
  // Asymmetric: the DOWNWARD scale is ~linear (less time genuinely = fewer strikes)
  // and kept full. The UPWARD scale is sub-linear — a finisher who goes longer than
  // his norm doesn't land proportionally more SS (the extra minutes skew to clinch /
  // grappling / feeling-out), so a raw 1.4× over-projects. Damp upward by half and
  // cap it, so the boost TEMPERS leans instead of creating them.
  let factor = raw >= 1 ? 1 + (raw - 1) * 0.5 : raw;
  factor = Math.max(0.5, Math.min(1.2, factor));
  if (Math.abs(factor - 1) < 0.12) return null;             // within noise — leave it
  return { adjusted: parseFloat((value * factor).toFixed(1)), factor, expMins, ownMins };
}

function calcFTLean(
  name: string,
  db: FighterDB|null,
  line_ft: number|null,
  oppDB: FighterDB|null,
  dkLine?: number|null,
  availableLines: number[] = [],
  moneyline: number | null = null,
): LeanResult|null {
  if (!line_ft) return null;
  const schedRounds = upcomingCardPairs.length ? getScheduledRoundsContext(name).rounds : null;
  const mktUnderP = marketFtUnderProb(name, line_ft, schedRounds);

  const history = (db?.history || []).filter(h => Number.isFinite(Number(h.timeSecs)) && Number(h.timeSecs) > 0);
  const hasHistory = !!(db && db.loaded && history.length >= 3);

  // No usable UFCStats duration history (e.g. debut/low-sample fighters). If DK's
  // round-start market prices a finish-timing distribution, emit a market-only FT
  // lean so those spots surface; otherwise stay silent as before.
  if (!hasHistory) {
    if (mktUnderP == null) return null;
    return buildMarketOnlyFtLean(name, line_ft, mktUnderP, db, oppDB, availableLines, moneyline);
  }
  if (!db || !db.loaded) return null;

  const mins = history.map(h => (Number(h.timeSecs) / 60));
  // Round-normalize the average for THIS fight's scheduled duration: a 22m
  // five-round war cannot happen in a 15m three-rounder — it would have gone
  // the 3R distance instead. Cap each historical fight at the upcoming
  // fight's max so 5R history can't inflate the OVER case. The hit-rate
  // check below stays uncapped on purpose: lasting 22m is still real
  // evidence the fighter lasted past a 12.5m line.
  // Headliner-aware rounds (findHeadlinerPair → 5R), not the raw scrape map —
  // UFCStats pre-fight pages default to 3, which would cap the main event's
  // history at 15m. No upcoming card at all → no cap (unknown context).
  const maxMins = schedRounds != null ? schedRounds * 5 : null;
  const cappedMins = maxMins != null ? mins.map(v => Math.min(v, maxMins)) : mins;
  const rawAvgFT = mins.reduce((s, v) => s + v, 0) / mins.length;
  const avgFT = cappedMins.reduce((s, v) => s + v, 0) / cappedMins.length;
  const reasons: LeanReason[] = [];
  let score = 0;
  if (maxMins != null && rawAvgFT - avgFT > 0.3) {
    reasons.push({ icon: 'neu', text: `Round-normalized: raw avg ${rawAvgFT.toFixed(1)}m capped to ${avgFT.toFixed(1)}m for a ${schedRounds}R fight (${maxMins}m max)` });
  }

  const diff = avgFT - line_ft;
  if      (diff > 2.0) { score += 2.4; reasons.push({ icon:'pos', text:`Avg fight time (${avgFT.toFixed(1)}m) is ${diff.toFixed(1)}m above line` }); }
  else if (diff > 1.0) { score += 1.4; reasons.push({ icon:'pos', text:`Avg fight time (${avgFT.toFixed(1)}m) edges line by ${diff.toFixed(1)}m` }); }
  else if (diff > 0.4) { score += 0.5; reasons.push({ icon:'pos', text:`Avg fight time (${avgFT.toFixed(1)}m) slightly above line` }); }
  else if (diff < -2.0){ score -= 2.4; reasons.push({ icon:'neg', text:`Avg fight time (${avgFT.toFixed(1)}m) is ${Math.abs(diff).toFixed(1)}m below line` }); }
  else if (diff < -1.0){ score -= 1.4; reasons.push({ icon:'neg', text:`Avg fight time (${avgFT.toFixed(1)}m) trails line by ${Math.abs(diff).toFixed(1)}m` }); }
  else if (diff < -0.4){ score -= 0.5; reasons.push({ icon:'neg', text:`Avg fight time (${avgFT.toFixed(1)}m) slightly below line` }); }
  else                 {               reasons.push({ icon:'neu', text:`Avg fight time (${avgFT.toFixed(1)}m) near line — toss-up` }); }

  const hits = mins.filter(v => v > line_ft).length;
  const rate = hits / mins.length;
  const rateAdj = shrunkHitRate(hits, mins.length);
  if      (rateAdj >= 0.72) { score += 1.6; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${mins.length} fights (${Math.round(rate*100)}%) over fight-time line` }); }
  else if (rateAdj >= 0.58) { score += 0.9; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${mins.length} fights over line` }); }
  else if (rateAdj <= 0.28) { score -= 1.6; reasons.push({ icon:'neg', text:`Hit rate: only ${hits}/${mins.length} fights (${Math.round(rate*100)}%) over line` }); }
  else if (rateAdj <= 0.42) { score -= 0.9; reasons.push({ icon:'neg', text:`Hit rate: ${hits}/${mins.length} fights over line — under tendency` }); }
  else                   {               reasons.push({ icon:'neu', text:`Hit rate: ${hits}/${mins.length} fights over line — near 50/50` }); }

  if (db.finishRate != null) {
    if (db.finishRate > 0.65) { score -= 0.8; reasons.push({ icon:'neg', text:`High finish profile (${Math.round(db.finishRate*100)}%) can cap fight duration` }); }
    else if (db.finishRate < 0.35) { score += 0.6; reasons.push({ icon:'pos', text:`Decision-heavy profile supports longer fight time` }); }
  }

  // Only credit 4-5 round durability when this fight can actually go there —
  // in a 3R fight that upside is capped at 15m. Unknown schedule keeps the
  // legacy behavior.
  if ((schedRounds == null || schedRounds === 5) && db.fiveRoundRate != null && db.fiveRoundRate > 0.3) {
    score += 0.5;
    reasons.push({ icon:'pos', text:`Frequent 4-5 round sample profile increases duration upside` });
  }

  if (oppDB?.loaded && oppDB.finishRate != null && oppDB.finishRate > 0.65) {
    score -= 0.4;
    reasons.push({ icon:'neg', text:`Opponent finish profile increases early-stoppage risk` });
  }

  // KO/TKO loss vulnerability — chin exposure shortens fights
  const allHist = db.history || [];
  const lossesWithMethod = allHist.filter(h => h.result === 'loss' && h.method);
  if (lossesWithMethod.length >= 2) {
    const koLosses = lossesWithMethod.filter(h => /KO|TKO/i.test(h.method || '')).length;
    if (koLosses >= Math.ceil(lossesWithMethod.length * 0.5)) {
      score -= 0.7;
      reasons.push({ icon:'neg', text:`KO/TKO stoppage vulnerability (${koLosses}/${lossesWithMethod.length} losses by stoppage) — opponent may end it early` });
    }
  }
  // Opponent KO threat compounds the chin concern
  if (oppDB?.loaded && oppDB.finishRate != null && oppDB.finishRate > 0.5) {
    const oppAllHist = oppDB.history || [];
    const oppWinsWithMethod = oppAllHist.filter(h => h.result === 'win' && h.method);
    if (oppWinsWithMethod.length >= 3) {
      const oppKOWins = oppWinsWithMethod.filter(h => /KO|TKO/i.test(h.method || '')).length;
      if (oppKOWins / oppWinsWithMethod.length >= 0.4) {
        score -= 0.5;
        reasons.push({ icon:'neg', text:`Opponent finishes ${oppKOWins}/${oppWinsWithMethod.length} wins by KO/TKO — high early-stoppage threat` });
      }
    }
  }

  if (dkLine != null && dkLine !== line_ft && Math.abs(dkLine - line_ft) >= 0.5) {
    if (dkLine < line_ft) {
      score -= 0.7;
      reasons.push({ icon: 'neg', text: `DK Sportsbook sets FT at ${dkLine}m vs fantasy book ${line_ft}m — sharp line implies shorter fight` });
    } else {
      score += 0.7;
      reasons.push({ icon: 'pos', text: `DK Sportsbook sets FT at ${dkLine}m vs fantasy book ${line_ft}m — sharp line implies longer fight` });
    }
  }

  // DK market blend. NON-final-round lines: the market corroborates the stat via a
  // bounded nudge. FINAL-round lines: the avg-based stat read is unreliable — a
  // decision-heavy fighter's fight time is bimodal (early finish OR the full-distance
  // spike), so the average understates duration and pushes a bogus under. The market's
  // P(under) (round ladder + "Fight to Go the Distance") is the sharp, correct read
  // there, so let it DRIVE the lean rather than merely nudge it.
  if (mktUnderP != null) {
    const isFinalRoundLine = schedRounds != null && Math.ceil(line_ft / 5) >= schedRounds;
    if (isFinalRoundLine) {
      score = (0.5 - mktUnderP) * 12;
      reasons.push({
        icon: mktUnderP < 0.45 ? 'pos' : mktUnderP > 0.55 ? 'neg' : 'neu',
        text: `DK round+distance market implies ${Math.round(mktUnderP * 100)}% under ${line_ft}m — market-led (avg unreliable near the distance)`,
      });
    } else {
      const nudge = Math.max(-1.8, Math.min(1.8, (0.5 - mktUnderP) * 6));
      score += nudge;
      reasons.push({
        icon: nudge < -0.05 ? 'neg' : nudge > 0.05 ? 'pos' : 'neu',
        text: `DK round market implies ${Math.round(mktUnderP * 100)}% chance under ${line_ft}m (Fight to Start Round odds)`,
      });
    }
  }

  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 3)   { lean = 'over';  conf = Math.min(89, 68 + score * 4); }
  else if (score >= 1.5) { lean = 'over';  conf = Math.min(74, 56 + score * 5); }
  else if (score >= 0.5) { lean = 'over';  conf = 54; }
  else if (score <= -3)  { lean = 'under'; conf = Math.min(89, 68 + Math.abs(score) * 4); }
  else if (score <= -1.5){ lean = 'under'; conf = Math.min(74, 56 + Math.abs(score) * 5); }
  else if (score <= -0.5){ lean = 'under'; conf = 54; }
  else                   { lean = 'push';  conf = 50; }

  const memoryAdjustment = applyConfidenceMemoryAdjustment({
    fighterName: name,
    source: 'ft',
    lean,
    baseConfidence: conf,
    score,
    db,
    avgValue: avgFT,
    line: line_ft,
    selectedLine: line_ft,
    availableLines: availableLines.length ? availableLines : [line_ft],
    oppDB,
    moneyline,
  });
  conf = memoryAdjustment.confidence;
  if (memoryAdjustment.note) {
    reasons.push({ icon: memoryAdjustment.delta > 0 ? 'pos' : 'neg', text: memoryAdjustment.note });
  }

  // Market confidence cap: the career-average stat must not be MORE confident in a
  // fight-time lean than the sharp book is. Cap the FT confidence at the market-implied
  // probability for the lean's side; if the market actively contradicts the lean
  // (<50%), drop it to no-lean. Reins in the overconfidence the bounded nudge can't —
  // e.g. McGregor's 8.0m career avg implies a strong under 12.25, but DK prices it a
  // coinflip because Holloway is famously durable (the average can't see that).
  if (mktUnderP != null && lean !== 'push') {
    const marketConfForLean = (lean === 'under' ? mktUnderP : 1 - mktUnderP) * 100;
    if (marketConfForLean < 50) {
      reasons.push({ icon: 'neu', text: `DK market puts the ${lean} at only ${Math.round(marketConfForLean)}% — no edge, lean dropped` });
      lean = 'push';
      conf = 50;
    } else if (marketConfForLean < conf) {
      reasons.push({ icon: 'neu', text: `Confidence capped to DK market ${Math.round(marketConfForLean)}% (sharp fight-time line ceiling)` });
      conf = marketConfForLean;
    }
  }

  const verdict = lean === 'over'
    ? `FT OVER ${line_ft}m (avg ${avgFT.toFixed(1)}m) — ${reasons[0]?.text}`
    : lean === 'under'
    ? `FT UNDER ${line_ft}m (avg ${avgFT.toFixed(1)}m) — ${reasons[0]?.text}`
    : `FT NO LEAN at ${line_ft}m (avg ${avgFT.toFixed(1)}m)`;

  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    memoryDelta: memoryAdjustment.delta,
    memoryNote: memoryAdjustment.note,
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: avgFT,
    line: line_ft,
    type: 'ft'
  };
}

// FT lean built purely from DK's round-start market, used when a fighter has no
// usable UFCStats duration history but DK prices a finish-timing distribution
// (e.g. Olympic-wrestler debuts). Confidence comes directly from the de-vigged
// market probability and is capped below a fully stat-corroborated lean.
function buildMarketOnlyFtLean(
  name: string,
  line_ft: number,
  mktUnderP: number,
  db: FighterDB | null,
  oppDB: FighterDB | null,
  availableLines: number[],
  moneyline: number | null,
): LeanResult | null {
  const lean: 'over'|'under'|'push' = mktUnderP >= 0.56 ? 'under' : mktUnderP <= 0.44 ? 'over' : 'push';
  const pForSide = lean === 'under' ? mktUnderP : 1 - mktUnderP;
  let conf = lean === 'push' ? 50 : Math.min(80, Math.max(53, Math.round(pForSide * 100)));
  const score = parseFloat(((0.5 - mktUnderP) * 6).toFixed(2));
  const reasons: LeanReason[] = [{
    icon: lean === 'under' ? 'neg' : lean === 'over' ? 'pos' : 'neu',
    text: `No fight-time history — DK round market implies ${Math.round(mktUnderP * 100)}% under ${line_ft}m (Fight to Start Round odds)`,
  }];

  if (db && db.loaded) {
    const memoryAdjustment = applyConfidenceMemoryAdjustment({
      fighterName: name, source: 'ft', lean, baseConfidence: conf, score,
      db, avgValue: line_ft, line: line_ft, selectedLine: line_ft,
      availableLines: availableLines.length ? availableLines : [line_ft], oppDB, moneyline,
    });
    conf = memoryAdjustment.confidence;
    if (memoryAdjustment.note) {
      reasons.push({ icon: memoryAdjustment.delta > 0 ? 'pos' : 'neg', text: memoryAdjustment.note });
    }
    const verdict = lean === 'push'
      ? `FT NO LEAN at ${line_ft}m (market ~50/50)`
      : `FT ${lean.toUpperCase()} ${line_ft}m — DK round market ${Math.round(mktUnderP * 100)}% under`;
    return {
      lean, conf: Math.round(conf), confidenceGrade: getConfidenceGrade(Math.round(conf)),
      memoryDelta: memoryAdjustment.delta, memoryNote: memoryAdjustment.note,
      score, reasons, verdict, avg: line_ft, line: line_ft, type: 'ft',
    };
  }

  const verdict = lean === 'push'
    ? `FT NO LEAN at ${line_ft}m (market ~50/50)`
    : `FT ${lean.toUpperCase()} ${line_ft}m — DK round market ${Math.round(mktUnderP * 100)}% under`;
  return {
    lean, conf: Math.round(conf), confidenceGrade: getConfidenceGrade(Math.round(conf)),
    memoryDelta: 0, memoryNote: undefined,
    score, reasons, verdict, avg: line_ft, line: line_ft, type: 'ft',
  };
}

function calcCTRLLean(
  name: string,
  db: FighterDB|null,
  line_ctrl: number|null,  // minutes
  oppDB: FighterDB|null,
  dkLine?: number|null,
  availableLines: number[] = [],
  moneyline: number | null = null,
  underAvailable: boolean | null = null,  // Pick6: whether Less button is offered
): LeanResult|null {
  if (!line_ctrl || !db || !db.loaded) return null;
  const history = (db.history || []).filter(h => Number.isFinite(Number(h.ctrlSecs)));
  if (history.length < 3) return null;

  const ctrlMinsSamples = history.map(h => Number(h.ctrlSecs) / 60);
  const avgCTRL = ctrlMinsSamples.reduce((s, v) => s + v, 0) / ctrlMinsSamples.length;

  // ── MODEL v24 — opponent-allowed control ─────────────────────────────────
  // CTRL was the ONLY lean that never read `oppHistory`. FP, SS, TD, FT and R1
  // SS all blend what the opponent ALLOWS into their projection; CTRL scored
  // from the fighter's own average and inferred the opponent from two proxies
  // (their takedown-defence % and whether they wrestle back). So on UFC 330 the
  // board put Jeremiah Wells CTRL OVER 1:30 at the top at 91% off his own 5:12
  // average, while the panel directly beneath it showed Orolbai Uulu allowing
  // 0:57 across six fights with 2 of 6 over that line — the model could not see
  // the number the user was reading.
  //
  // NOTE the filter: SS drops zero samples, and CTRL must NOT. A shut-out
  // (Hermansson 0:00 against Uulu) is the most informative sample there is for
  // this stat; dropping zeros would bias the allowed-average upward exactly
  // when the opponent is a control-denier.
  const oppCtrlRaw = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => Number(h.ctrlSecs))
    .filter(v => Number.isFinite(v) && v >= 0)
    .map(v => v / 60);

  // ── MODEL v26 — duration ─────────────────────────────────────────────────
  // Two related defects, both about time.
  //
  // (a) CTRL never duration-adjusted at all. SS and TD both run their
  //     projection through durationAdjustProjection; control accrues with time
  //     on the mat exactly the way strikes accrue with time on the feet.
  //
  // (b) v24's opp-allowed average is contaminated by fight LENGTH. Jeremiah
  //     Wells "allows 1:21" across seven fights — but four of them he finished
  //     by KO or submission (opponents at 0:13, 0:00, 0:03, 0:22), and nobody
  //     accumulates control in a fight that ends in ninety seconds. Averaging
  //     raw seconds conflates "hard to control" with "his fights end early",
  //     and v24 then weighted that number 50%.
  //
  // Both halves are now expressed against THIS fight's expected length: the
  // opponent's allowed control as a SHARE of fight time projected onto the
  // market's expected minutes, and the fighter's own average through the same
  // helper SS and TD use. Each half is scaled exactly once — running
  // durationAdjustProjection over an already-projected blend would count the
  // market's duration twice.
  const schedRoundsCtrl = upcomingCardPairs.length ? getScheduledRoundsContext(name).rounds : null;
  const expMinsCtrl = marketExpectedFightMinutes(name, schedRoundsCtrl);
  const oppShareSamples = (oppDB?.oppHistory ?? []).slice(0, 5)
    .map(h => ({ ctrl: Number(h.ctrlSecs), secs: Number(h.timeSecs) }))
    .filter(s => Number.isFinite(s.ctrl) && s.ctrl >= 0 && Number.isFinite(s.secs) && s.secs > 0)
    .map(s => s.ctrl / s.secs);
  // The samples every downstream test uses: duration-normalised when the market
  // gives us an expected length and the histories carry fight times, raw
  // minutes otherwise (v24 behaviour, which is still better than nothing).
  const oppEvalSamples = (oppShareSamples.length >= 3 && expMinsCtrl != null)
    ? oppShareSamples.map(s => s * expMinsCtrl)
    : oppCtrlRaw;
  const durationNormalised = oppEvalSamples !== oppCtrlRaw;
  const oppAvgCtrlAllowed = oppEvalSamples.length >= 3
    ? parseFloat((oppEvalSamples.reduce((s, v) => s + v, 0) / oppEvalSamples.length).toFixed(2))
    : null;

  const ownDurAdj = durationAdjustProjection(name, db, avgCTRL);
  const ownProjected = ownDurAdj ? ownDurAdj.adjusted : avgCTRL;

  // Same 50/50 blend SS and FP use — his history and their resistance, weighted
  // equally, rather than his history alone.
  const effectiveCTRL = oppAvgCtrlAllowed != null
    ? parseFloat(((ownProjected + oppAvgCtrlAllowed) / 2).toFixed(2))
    : ownProjected;

  const reasons: LeanReason[] = [];
  let score = 0;

  // The projection names both halves, so a blended number can never be mistaken
  // for the fighter's own average the way "Avg control (5.2m)" was.
  const ownLabel = ownDurAdj ? `avg ${avgCTRL.toFixed(1)}m→${ownProjected.toFixed(1)}m` : `avg ${avgCTRL.toFixed(1)}m`;
  const ctrlLabel = oppAvgCtrlAllowed != null
    ? `Proj control ${effectiveCTRL.toFixed(1)}m (${ownLabel} + opp allows ${oppAvgCtrlAllowed.toFixed(1)}m${durationNormalised ? ' at this fight’s length' : ''})`
    : `${ownDurAdj ? `Proj control ${ownProjected.toFixed(1)}m (avg ${avgCTRL.toFixed(1)}m)` : `Avg control (${avgCTRL.toFixed(1)}m)`}`;
  const diff = effectiveCTRL - line_ctrl;
  if      (diff >  1.5) { score += 2.4; reasons.push({ icon:'pos', text:`${ctrlLabel} is ${diff.toFixed(1)}m above line` }); }
  else if (diff >  0.8) { score += 1.4; reasons.push({ icon:'pos', text:`${ctrlLabel} edges line by ${diff.toFixed(1)}m` }); }
  else if (diff >  0.3) { score += 0.5; reasons.push({ icon:'pos', text:`${ctrlLabel} slightly above line` }); }
  else if (diff < -1.5) { score -= 2.4; reasons.push({ icon:'neg', text:`${ctrlLabel} is ${Math.abs(diff).toFixed(1)}m below line` }); }
  else if (diff < -0.8) { score -= 1.4; reasons.push({ icon:'neg', text:`${ctrlLabel} trails line by ${Math.abs(diff).toFixed(1)}m` }); }
  else if (diff < -0.3) { score -= 0.5; reasons.push({ icon:'neg', text:`${ctrlLabel} slightly below line` }); }
  else                  {               reasons.push({ icon:'neu', text:`${ctrlLabel} near line — toss-up` }); }

  const hits = ctrlMinsSamples.filter(v => v > line_ctrl).length;
  const rate = hits / ctrlMinsSamples.length;
  const rateAdj = shrunkHitRate(hits, ctrlMinsSamples.length);
  if      (rateAdj >= 0.72) { score += 1.6; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${ctrlMinsSamples.length} fights (${Math.round(rate*100)}%) over control line` }); }
  else if (rateAdj >= 0.58) { score += 0.9; reasons.push({ icon:'pos', text:`Hit rate: ${hits}/${ctrlMinsSamples.length} fights over line` }); }
  else if (rateAdj <= 0.28) { score -= 1.6; reasons.push({ icon:'neg', text:`Hit rate: only ${hits}/${ctrlMinsSamples.length} fights (${Math.round(rate*100)}%) over line` }); }
  else if (rateAdj <= 0.42) { score -= 0.9; reasons.push({ icon:'neg', text:`Hit rate: ${hits}/${ctrlMinsSamples.length} fights over line — under tendency` }); }
  else                   {               reasons.push({ icon:'neu', text:`Hit rate: ${hits}/${ctrlMinsSamples.length} fights over line — near 50/50` }); }

  // Style profile: grappler pushes CTRL up, striker pushes it down.
  if (db.style === 'grappler') { score += 0.7; reasons.push({ icon:'pos', text:`Grappler profile supports sustained top control` }); }
  else if (db.style === 'striker') { score -= 0.7; reasons.push({ icon:'neg', text:`Striker profile rarely posts large control windows` }); }

  // Takedown volume correlates strongly with CTRL potential.
  const tdAvg = db.avgTDperFight ?? db.avgTD ?? null;
  if (tdAvg != null) {
    if      (tdAvg >= 2.5) { score += 1.1; reasons.push({ icon:'pos', text:`High TD volume (${tdAvg.toFixed(1)}/fight) fuels control upside` }); }
    else if (tdAvg >= 1.2) { score += 0.4; reasons.push({ icon:'pos', text:`Moderate TD volume (${tdAvg.toFixed(1)}/fight) supports control` }); }
    else if (tdAvg < 0.4)  { score -= 1.0; reasons.push({ icon:'neg', text:`Low TD volume (${tdAvg.toFixed(1)}/fight) caps control ceiling` }); }
  }

  // MODEL v24 — how many of the opponent's recent foes actually cleared THIS
  // line. Takedown-defence % is a proxy for this; when the measurement itself is
  // available it SUPERSEDES the proxy rather than stacking with it, or a
  // control-denier gets charged twice for the same trait. Thresholds and
  // magnitudes deliberately mirror the tdDef block they replace.
  // v26: judged on the same duration-normalised samples as the projection, so a
  // foe shut out inside ninety seconds is measured on the share of the fight he
  // controlled rather than on a raw total no one could have reached.
  const oppOverRate = oppEvalSamples.length >= 3
    ? oppEvalSamples.filter(v => v > line_ctrl).length / oppEvalSamples.length
    : null;
  if (oppOverRate != null) {
    const over = oppEvalSamples.filter(v => v > line_ctrl).length;
    const basis = durationNormalised ? ' (at this fight’s expected length)' : '';
    if (oppOverRate <= 0.40) {
      score -= 1.1;
      reasons.push({ icon:'neg', text:`Opponent has allowed only ${over}/${oppEvalSamples.length} recent foes over this control line${basis}` });
    } else if (oppOverRate >= 0.60) {
      score += 0.8;
      reasons.push({ icon:'pos', text:`Opponent has allowed ${over}/${oppEvalSamples.length} recent foes over this control line${basis}` });
    }
  } else if (oppDB?.loaded && oppDB.tdDef != null) {
    // No allowed-control history — fall back to the defence-percentage proxy.
    if      (oppDB.tdDef >= 75) { score -= 1.1; reasons.push({ icon:'neg', text:`Opponent TD defense ${oppDB.tdDef}% suppresses ground control` }); }
    else if (oppDB.tdDef <= 45) { score += 0.8; reasons.push({ icon:'pos', text:`Opponent TD defense only ${oppDB.tdDef}% — favorable for control accumulation` }); }
  }
  // Opponent wrestling pressure (their own TD output) means fighter may be on bottom
  const oppTdAvg = oppDB?.avgTDperFight ?? oppDB?.avgTD ?? null;
  if (oppDB?.loaded && oppTdAvg != null && oppTdAvg >= 2.2) {
    score -= 0.5;
    reasons.push({ icon:'neg', text:`Opponent also wrestles (${oppTdAvg.toFixed(1)} TD/fight) — fighter may lose scramble battles` });
  }

  // Early finisher caps control time.
  if (db.finishRate != null && db.finishRate > 0.65) {
    score -= 0.5;
    reasons.push({ icon:'neg', text:`High finish profile (${Math.round(db.finishRate*100)}%) can end fight before control accumulates` });
  }

  // ── MODEL v25 — the price ────────────────────────────────────────────────
  // calcCTRLLean took `moneyline` as a parameter and never scored with it; it
  // reached only the confidence-memory call. calcLean has had a heavy-favourite
  // / heavy-underdog branch for a long time, and control time is if anything
  // MORE win-coupled than fantasy points: a dog banking sustained top position
  // is largely describing a fight he is winning, whereas FP can accrue from
  // volume while losing. On UFC 330 that left a +675 dog at 12% vig-removed win
  // probability projected for 3.2m of control with the price nowhere in the
  // math.
  //
  // Thresholds and magnitudes mirror the FP block rather than inventing a
  // steeper curve for CTRL — a bespoke tier would be tuning, not precedent.
  if (moneyline != null && moneyline <= -300) {
    score += 0.8;
    reasons.push({
      icon: 'pos',
      text: `Heavy favorite (${moneyline}) — ${Math.round(moneylineToImpliedProb(moneyline) * 100)}% implied win probability supports sustained top position`,
    });
  } else if (moneyline != null && moneyline >= 300) {
    score -= 0.7;
    reasons.push({
      icon: 'neg',
      text: `Heavy underdog (+${moneyline}) at ${Math.round(moneylineToImpliedProb(moneyline) * 100)}% implied win probability — sustained control largely implies winning the fight`,
    });
  }

  if (dkLine != null && dkLine !== line_ctrl && Math.abs(dkLine - line_ctrl) >= 0.3) {
    if (dkLine < line_ctrl) {
      score -= 0.6;
      reasons.push({ icon: 'neg', text: `DK Sportsbook sets control at ${dkLine}m vs fantasy book ${line_ctrl}m — sharp line implies less control` });
    } else {
      score += 0.6;
      reasons.push({ icon: 'pos', text: `DK Sportsbook sets control at ${dkLine}m vs fantasy book ${line_ctrl}m — sharp line implies more control` });
    }
  }

  let lean: 'over'|'under'|'push', conf: number;
  if      (score >= 3)   { lean = 'over';  conf = Math.min(89, 68 + score * 4); }
  else if (score >= 1.5) { lean = 'over';  conf = Math.min(74, 56 + score * 5); }
  else if (score >= 0.5) { lean = 'over';  conf = 54; }
  else if (score <= -3)  { lean = 'under'; conf = Math.min(89, 68 + Math.abs(score) * 4); }
  else if (score <= -1.5){ lean = 'under'; conf = Math.min(74, 56 + Math.abs(score) * 5); }
  else if (score <= -0.5){ lean = 'under'; conf = 54; }
  else                   { lean = 'push';  conf = 50; }

  // Pick6 doesn't always offer the Less/UNDER side for CTRL. When the scraper
  // confirmed Less is missing for this fighter, suppress UNDER recommendations
  // entirely — they're unplaceable. See project_pickem_platform_rules memory.
  if (lean === 'under' && underAvailable === false) {
    reasons.push({ icon: 'neu', text: 'Pick6 does not offer UNDER on this CTRL line — suppressing lean (unplaceable).' });
    lean = 'push';
    conf = 50;
  }

  const memoryAdjustment = applyConfidenceMemoryAdjustment({
    fighterName: name,
    source: 'ctrl',
    lean,
    baseConfidence: conf,
    score,
    db,
    avgValue: avgCTRL,
    line: line_ctrl,
    selectedLine: line_ctrl,
    availableLines: availableLines.length ? availableLines : [line_ctrl],
    oppDB,
    moneyline,
  });
  conf = memoryAdjustment.confidence;
  if (memoryAdjustment.note) {
    reasons.push({ icon: memoryAdjustment.delta > 0 ? 'pos' : 'neg', text: memoryAdjustment.note });
  }

  const verdict = lean === 'over'
    ? `CTRL OVER ${line_ctrl}m (avg ${avgCTRL.toFixed(1)}m) — ${reasons[0]?.text}`
    : lean === 'under'
    ? `CTRL UNDER ${line_ctrl}m (avg ${avgCTRL.toFixed(1)}m) — ${reasons[0]?.text}`
    : `CTRL NO LEAN at ${line_ctrl}m (avg ${avgCTRL.toFixed(1)}m)`;

  return {
    lean,
    conf: Math.round(conf),
    confidenceGrade: getConfidenceGrade(Math.round(conf)),
    memoryDelta: memoryAdjustment.delta,
    memoryNote: memoryAdjustment.note,
    score: parseFloat(score.toFixed(2)),
    reasons,
    verdict,
    avg: avgCTRL,
    line: line_ctrl,
    type: 'ctrl'
  };
}

// ── RENDER UTILITIES ──────────────────────────────────────────────────────
function activePlatformLine(f: AnalyzerFighter): number|null {
  return getSourceActiveLine(f, 'fp');
}

function activePlatformLabel(f: AnalyzerFighter): string {
  return formatSourcePlatformLabel(f, 'fp');
  if (currentPlatform === 'pick6' && f.line_p6 != null) return `Pick6 ${f.line_p6}`;
  if (currentPlatform === 'underdog' && f.line_ud != null) return `Underdog ${f.line_ud}`;
  if (currentPlatform === 'prizepicks' && f.line_pp != null) return `PrizePicks ${f.line_pp}`;
  if (currentPlatform === 'draftkings_sportsbook' && (f.line_dk_ss != null || f.line_dk_td != null || f.line_dk_ft != null)) {
    return `DK SS ${f.line_dk_ss ?? '—'} / TD ${f.line_dk_td ?? '—'} / FT ${f.line_dk_ft ?? '—'}`;
  }
  if (f.line_betr != null) return `Betr ${f.line_betr}`;
  if (f.line_pp != null) return `PrizePicks ${f.line_pp}`;
  if (f.line_p6 != null) return `Pick6 ${f.line_p6}`;
  if (f.line_ud != null) return `Underdog ${f.line_ud}`;
  if (f.line_dk_ss != null || f.line_dk_td != null || f.line_dk_ft != null) return `DK SS ${f.line_dk_ss ?? '—'} / TD ${f.line_dk_td ?? '—'} / FT ${f.line_dk_ft ?? '—'}`;
  return '—';
}

function activePlatformAvgFP(db: FighterDB): number | null {
  if (currentPlatform === 'pick6') return db.avgFP_p6 ?? db.avgFP_ud ?? db.avgFP_pp ?? db.avgFP_betr ?? db.avgFP ?? null;
  if (currentPlatform === 'underdog') return db.avgFP_ud ?? db.avgFP_p6 ?? db.avgFP_pp ?? db.avgFP_betr ?? db.avgFP ?? null;
  if (currentPlatform === 'prizepicks') return db.avgFP_pp ?? db.avgFP_p6 ?? db.avgFP_ud ?? db.avgFP_betr ?? db.avgFP ?? null;
  if (currentPlatform === 'draftkings_sportsbook') return db.avgFP_p6 ?? db.avgFP_ud ?? db.avgFP_pp ?? db.avgFP_betr ?? db.avgFP ?? null;
  return db.avgFP_betr ?? db.avgFP_p6 ?? db.avgFP_ud ?? db.avgFP_pp ?? db.avgFP ?? null;
}

function ensureLineLeans(): void {
  // Assign percentile-based leans for fighters without stats
  const fightersWithLines = allFighters.filter(f => activePlatformLine(f) != null);
  if (fightersWithLines.length < 4) return; // Need minimum for percentiles

  const lines = fightersWithLines.map(f => activePlatformLine(f)!).sort((a, b) => a - b);
  const overThreshold = lines[Math.floor(lines.length * 0.75)]; // Top 25%
  const underThreshold = lines[Math.floor(lines.length * 0.25)]; // Bottom 25%

  fightersWithLines.forEach(f => {
    if (f.lean?.lean && f.lean.lean !== 'none') return; // Already has a lean
    const line = activePlatformLine(f);
    if (!line) return;

    let lean: 'over' | 'under' | 'push' = 'push';
    let conf = 50;
    const reasons: LeanReason[] = [];

    if (line >= overThreshold) {
      lean = 'over';
      conf = 60;
      reasons.push({ icon: 'pos', text: `Line in top 25% of all fighters — percentile-based over lean` });
    } else if (line <= underThreshold) {
      lean = 'under';
      conf = 60;
      reasons.push({ icon: 'neg', text: `Line in bottom 25% of all fighters — percentile-based under lean` });
    } else {
      reasons.push({ icon: 'neu', text: `Line in middle 50% — no strong percentile lean` });
    }

    const verdict = lean === 'over' ? `PERCENTILE OVER ${line} — top quartile line` :
                    lean === 'under' ? `PERCENTILE UNDER ${line} — bottom quartile line` :
                    `NO PERCENTILE LEAN at ${line}`;

    f.lean = { lean, conf, reasons, verdict };
  });
}

function _computeEffectiveLean(f: AnalyzerFighter): EffectiveLean {
  // Sub-leans are pre-adjusted by applyWeightMissToFighter during primeCaches,
  // so this just picks priority and tags with _source/_label.
  // GLOW-UP 194: FP is top priority, but only when its side is actually PLACEABLE.
  // A dog's FP-under with no Underdog line (Pick6 blocks it) isn't an actionable
  // play, so fall through to the top placeable sub-lean IN THE SAME DIRECTION
  // (never flip the model's read) and only fall back to the unplaceable FP when
  // nothing else covers that direction.
  if (f.lean?.lean && f.lean.lean !== 'none') {
    const fpDir = f.lean.lean;
    // Only fall through to a sub-lean whose side is actually placeable on some book
    // (leanBestBook returns a book) — else a Pick6 TD-under (More-only) would just be
    // the next unplaceable play.
    const _pl = (src: string) => leanBestBook(f, src, fpDir).book != null;
    // MODEL v23 — FP is judged by the SAME test as the sub-leans below it: does
    // ANY book take this side. It used to call shouldSkipFpSideForFighter with no
    // book override, which judges only the ACTIVE platform — so a dog holding a
    // Pick6 FP line (active, blocked) AND an Underdog one had its perfectly
    // placeable FP under declared dead and fell through to a sub-lean. A dog's FP
    // under is blocked on exactly Pick6 and Betr; Underdog and PrizePicks post it.
    if (fpDir === 'push' || _pl('fp')) {
      return { ...f.lean, _source: 'fp', _label: '' };
    }
    if (f.lean_ss?.lean === fpDir && _pl('ss'))       return { ...f.lean_ss,    _source: 'ss',    _label: ' (SS)' };
    if (f.lean_td?.lean === fpDir && _pl('td'))       return { ...f.lean_td,    _source: 'td',    _label: ' (TD)' };
    if (f.lean_ft?.lean === fpDir && _pl('ft'))       return { ...f.lean_ft,    _source: 'ft',    _label: ' (FT)' };
    if (f.lean_ss_r1?.lean === fpDir && _pl('ss_r1')) return { ...f.lean_ss_r1, _source: 'ss_r1', _label: ' (R1 SS)' };
    if (f.lean_kd?.lean === fpDir && _pl('kd'))       return { ...f.lean_kd,    _source: 'kd',    _label: ' (KD)' };
    // MODEL v23 — nothing in this direction is takeable anywhere. The read is
    // kept (it is real: Neil Magny's FP UNDER is an 81% read on a fighter Pick6
    // simply will not let you fade) but it is FLAGGED, and a flagged lean must
    // not be presented as a recommendation. Previously this returned the
    // unplaceable FP unmarked, so it could and did win the board's top pick.
    return { ...f.lean, _source: 'fp', _label: '', _unplaceable: true };
  }
  // No FP lean at all. MODEL v23 — these used to be returned with no placeability
  // test whatsoever, so a Pick6-only TD under (More-only) or a demon/goblin KD
  // could win the effective lean outright. Same rule as above: a placeable side
  // wins first; an unplaceable one is kept as a read but flagged.
  const _plStat = (src: string, dir: string) => leanBestBook(f, src, dir).book != null;
  const statOrder: Array<[LeanResult | null | undefined, LeanSource, string]> = [
    [f.lean_ss, 'ss', ' (SS)'], [f.lean_td, 'td', ' (TD)'], [f.lean_ft, 'ft', ' (FT)'],
    [f.lean_ss_r1, 'ss_r1', ' (R1 SS)'], [f.lean_kd, 'kd', ' (KD)'],
  ];
  const live = statOrder.filter(([l]) => l?.lean && l.lean !== 'none' && l.lean !== 'push');
  for (const [l, src, label] of live) {
    if (_plStat(src, l!.lean)) return { ...l!, _source: src, _label: label };
  }
  // Nothing placeable — fall back to the highest-priority read, flagged.
  if (live.length) {
    const [l, src, label] = live[0];
    return { ...l!, _source: src, _label: label, _unplaceable: true };
  }
  return { ...(f.lean || { lean: 'none', conf: 0, reasons: [], verdict: '' }), _source: 'fp', _label: '' };
}

// Severity-tiered weight-miss treatment:
//   small (<1lb)     drained, no upside           → clear UNDER nudge
//   moderate (1-2lb) drained, mild cardio risk    → mild UNDER nudge
//   big (2-5lb)      MIXED: size advantage + cardio risk
//                      → grappler on TD/CTRL gets OVER (size wins exchanges)
//                      → striker/balanced gets UNDER (cardio dominates)
//   extreme (5+lb)   major cut failure           → strong UNDER (with grappler-on-TD nuance)
//   unknown amount   conservative moderate UNDER nudge
// Opponent-style amplification: when opp pace (slpm+sapm) ≥ 8.5, cardio drain
// hits harder — multiply negative deltas by 1.2 (positive size-advantage signals
// in the grappler-on-TD branches are not amplified).
function _computeWeightMissDeltas(
  sig: WeightMissSignal,
  source: LeanSource,
  isGrappler: boolean,
  oppPaceHigh: boolean,
  oppPaceTotal: number,
  lbsLabel: string,
): { confDelta: number; avgDelta: number; reasonsToPrepend: LeanReason[]; ampReason: LeanReason | null } {
  const reasonsToPrepend: LeanReason[] = [];
  let confDelta = 0;
  let avgDelta = 0;

  switch (sig.severity) {
    case 'small':
      reasonsToPrepend.push({ icon: 'neg', text: `Missed weight by ${lbsLabel} — completed cut, drained, no size upside` });
      confDelta = -10;
      avgDelta = source === 'fp' ? -8 : source === 'ss' ? -7 : source === 'ss_r1' ? -3.5 : source === 'ft' ? -1.5 : source === 'td' ? -0.3 : 0;
      break;
    case 'moderate':
      reasonsToPrepend.push({ icon: 'neg', text: `Missed weight by ${lbsLabel} — failed cut, mild cardio risk` });
      confDelta = -7;
      avgDelta = source === 'fp' ? -5 : source === 'ss' ? -4 : source === 'ss_r1' ? -2 : source === 'ft' ? -1.0 : source === 'td' ? -0.2 : 0;
      break;
    case 'big':
      if (isGrappler && (source === 'td' || source === 'ctrl')) {
        reasonsToPrepend.push({ icon: 'pos', text: `Missed weight by ${lbsLabel} — likely size/control advantage in grappling exchanges` });
        reasonsToPrepend.push({ icon: 'neg', text: `Big miss also signals possible cardio fade in later rounds` });
        confDelta = +5;
        avgDelta = source === 'td' ? +0.5 : +25;
      } else if (isGrappler) {
        reasonsToPrepend.push({ icon: 'pos', text: `Missed weight by ${lbsLabel} — possible size edge` });
        reasonsToPrepend.push({ icon: 'neg', text: `Big miss also signals cardio risk` });
        confDelta = -3;
        avgDelta = source === 'fp' ? -3 : source === 'ss' ? -3 : source === 'ss_r1' ? -1.5 : 0;
      } else {
        reasonsToPrepend.push({ icon: 'neg', text: `Missed weight by ${lbsLabel} — failed cut + cardio collapse risk` });
        confDelta = -8;
        avgDelta = source === 'fp' ? -7 : source === 'ss' ? -6 : source === 'ss_r1' ? -3 : source === 'ft' ? -1.2 : 0;
      }
      break;
    case 'extreme':
      if (isGrappler && (source === 'td' || source === 'ctrl')) {
        reasonsToPrepend.push({ icon: 'pos', text: `Massive miss (${lbsLabel}) — major size advantage but extreme cardio risk` });
        confDelta = -3;
        avgDelta = source === 'td' ? +0.3 : +15;
      } else {
        reasonsToPrepend.push({ icon: 'neg', text: `Massive miss (${lbsLabel}) — major cut failure, severe cardio + prep red flag` });
        confDelta = -15;
        avgDelta = source === 'fp' ? -12 : source === 'ss' ? -10 : source === 'ss_r1' ? -5 : source === 'ft' ? -2.0 : source === 'td' ? -0.5 : 0;
      }
      break;
    case 'unknown':
      reasonsToPrepend.push({ icon: 'neg', text: `Missed weight (amount unconfirmed) — likely failed cut, conservative UNDER nudge` });
      confDelta = -5;
      avgDelta = source === 'fp' ? -4 : source === 'ss' ? -3 : source === 'ss_r1' ? -1.5 : source === 'ft' ? -0.7 : 0;
      break;
  }

  let ampReason: LeanReason | null = null;
  if (oppPaceHigh && confDelta < 0) {
    confDelta = Math.round(confDelta * 1.2);
    if (avgDelta < 0) avgDelta = avgDelta * 1.2;
    ampReason = {
      icon: 'neg',
      text: `High-pace opponent (${oppPaceTotal.toFixed(1)} SLpM+SApM) amplifies cardio drain risk`,
    };
  }

  return { confDelta, avgDelta, reasonsToPrepend, ampReason };
}

function _formatLbsLabel(sig: WeightMissSignal): string {
  return sig.lbsOver != null
    ? `${sig.lbsOver % 1 === 0 ? sig.lbsOver : sig.lbsOver.toFixed(1)} lb`
    : 'unknown amount';
}

function _getOppPace(fighter: AnalyzerFighter): { oppPaceHigh: boolean; oppPaceTotal: number } {
  const oppName = fighter.opponent;
  if (!oppName) return { oppPaceHigh: false, oppPaceTotal: 0 };
  const oppNorm = (normalizeName(oppName) || oppName).toLowerCase();
  const opp = _fighterByNorm?.get(oppNorm);
  const slpm = opp?.db?.slpm ?? null;
  const sapm = opp?.db?.sapm ?? null;
  if (slpm == null || sapm == null) return { oppPaceHigh: false, oppPaceTotal: 0 };
  const total = slpm + sapm;
  return { oppPaceHigh: total >= 8.5, oppPaceTotal: total };
}

// Mutates each sub-lean (lean, lean_ss, lean_td, lean_ft, lean_ctrl) in place
// so SS/TD/FT/CTRL panel displays reflect the weight-miss signal — not just the
// priority-picked effective lean. Idempotent across re-priming via shadow-copy
// snapshot keyed by signal: same signal → skip; different/cleared → restore + re-apply.
type WeightMissShadow = { conf: number; avg: number | undefined; lean: 'over' | 'under' | 'push' | 'none'; reasonsLen: number };
type LeanWithShadow = LeanResult & { _wmKey?: string; _wmOrig?: WeightMissShadow };

function applyWeightMissToFighter(fighter: AnalyzerFighter): void {
  const sig = _weightMissSignals.get(fighter.name.toLowerCase());
  const sigKey = sig ? `${sig.severity}:${sig.lbsOver ?? '?'}` : '';
  const isGrappler = fighter.db?.style === 'grappler';
  const { oppPaceHigh, oppPaceTotal } = _getOppPace(fighter);
  const lbsLabel = sig ? _formatLbsLabel(sig) : '';

  const targets: Array<['lean' | 'lean_ss' | 'lean_ss_r1' | 'lean_td' | 'lean_ft' | 'lean_ctrl', LeanSource]> = [
    ['lean', 'fp'],
    ['lean_ss', 'ss'],
    ['lean_ss_r1', 'ss_r1'],
    ['lean_td', 'td'],
    ['lean_ft', 'ft'],
    ['lean_ctrl', 'ctrl'],
  ];

  for (const [key, source] of targets) {
    const lean = fighter[key] as LeanWithShadow | null | undefined;
    if (!lean) continue;
    if (lean._wmKey === sigKey) continue;

    if (lean._wmOrig) {
      lean.conf = lean._wmOrig.conf;
      lean.avg = lean._wmOrig.avg;
      lean.lean = lean._wmOrig.lean;
      if (lean.reasons) lean.reasons.length = lean._wmOrig.reasonsLen;
      delete lean._wmOrig;
    }
    delete lean._wmKey;

    if (!sig) continue;
    if (lean.lean === 'none') { lean._wmKey = sigKey; continue; }

    lean._wmOrig = {
      conf: lean.conf,
      avg: lean.avg,
      lean: lean.lean,
      reasonsLen: lean.reasons?.length ?? 0,
    };
    lean._wmKey = sigKey;

    const { confDelta, avgDelta, reasonsToPrepend, ampReason } = _computeWeightMissDeltas(
      sig, source, isGrappler, oppPaceHigh, oppPaceTotal, lbsLabel,
    );

    lean.conf = Math.max(0, Math.min(95, lean.conf + confDelta));
    if (lean.avg != null) lean.avg = lean.avg + avgDelta;
    if (!lean.reasons) lean.reasons = [];
    lean.reasons.unshift(...reasonsToPrepend);
    if (ampReason) lean.reasons.push(ampReason);

    if (lean.avg != null && lean.line != null) {
      if (lean.lean === 'over' && lean.avg < lean.line) {
        lean.lean = 'under';
        lean.reasons.push({ icon: 'neg', text: `Adjusted projection ${lean.avg.toFixed(1)} now below line ${lean.line} — lean flipped to UNDER` });
      } else if (lean.lean === 'under' && lean.avg > lean.line) {
        lean.lean = 'over';
        lean.reasons.push({ icon: 'pos', text: `Adjusted projection ${lean.avg.toFixed(1)} now above line ${lean.line} — lean flipped to OVER` });
      }
    }
  }
}
function getEffectiveLean(f: AnalyzerFighter): EffectiveLean {
  return _leanCache?.get(f.name) ?? _computeEffectiveLean(f);
}

// ── PAYOUT-WEIGHTED EV ENGINE ────────────────────────────────────────────────

/** Convert any odds format to profit-per-unit.  Returns null for invalid input. */
function oddsToProfit(odds: number | null | undefined): number | null {
  if (odds == null || !Number.isFinite(odds)) return null;
  // American odds (|odds| >= 100)
  if (Math.abs(odds) >= 100) return odds < 0 ? 100 / Math.abs(odds) : odds / 100;
  // Payout multiplier (e.g. 0.66x, 1.34x — used by UD and some DK props)
  if (odds > 0) return odds;
  return null;
}

/** Compute implied probability from odds (any format). */
function oddsToImpliedProb(odds: number | null | undefined): number | null {
  const profit = oddsToProfit(odds);
  if (profit == null) return null;
  return 1 / (1 + profit);
}

/** Compute vig/overround when both sides' odds are available.
 *  Returns the vig as percentage points above 100% (e.g. 4.5 means 4.5% juice). */
function computeVig(overOdds: number | null | undefined, underOdds: number | null | undefined): number | null {
  const overProb  = oddsToImpliedProb(overOdds);
  const underProb = oddsToImpliedProb(underOdds);
  if (overProb == null || underProb == null) return null;
  const overround = (overProb + underProb - 1) * 100;
  return parseFloat(overround.toFixed(1));
}

/**
 * Compute EV% for a fighter's effective lean using actual side odds when available.
 * For FP leans (no book odds), uses assumed -110 standard vig (profit = 0.909).
 * EV% = round((winProb * profitPerUnit - lossProb) * 100)
 * Returns { ev, isAssumedVig, vig } or null for push/none leans.
 */
interface EVResult { ev: number; isAssumedVig: boolean; vig: number | null; profit: number; prob: number; recalibrated: boolean }

// Win probability for EV — matched step-for-step to the pipeline that produces
// the DISPLAYED confidence (CLV boost → clamp → recalibration against realized
// accuracy), so the EV chip can never disagree with the confidence chip beside
// it. Falls back to raw conf while the recalibration map is unpopulated.
function evWinProb(f: AnalyzerFighter, el: EffectiveLean): { p: number; recalibrated: boolean } {
  const raw = el.conf || 0;
  if (raw <= 0) return { p: 0, recalibrated: false };
  const clv = getClvBoost(f, el);
  const boosted = clv ? Math.max(25, Math.min(90, raw + clv.delta)) : raw;
  const recal = getRecalibratedConfidence(boosted, el._source);
  return { p: (recal ?? boosted) / 100, recalibrated: recal != null };
}
function computeFighterEV(f: AnalyzerFighter, el: EffectiveLean): number | null {
  return computeDetailedEV(f, el)?.ev ?? null;
}
function computeDetailedEV(f: AnalyzerFighter, el: EffectiveLean): EVResult | null {
  if (el.lean !== 'over' && el.lean !== 'under') return null;
  const { p: winProb, recalibrated } = evWinProb(f, el);
  if (winProb <= 0) return null;
  const isOver = el.lean === 'over';

  // Try to get actual side odds for the lean direction
  let leanOdds: number | null = null;
  let oppOdds: number | null = null;
  if (el._source === 'ss') {
    leanOdds = isOver ? (f.ss_over_odds ?? null)  : (f.ss_under_odds ?? null);
    oppOdds  = isOver ? (f.ss_under_odds ?? null)  : (f.ss_over_odds ?? null);
  } else if (el._source === 'ss_r1') {
    leanOdds = isOver ? (f.ss_r1_over_odds ?? null)  : (f.ss_r1_under_odds ?? null);
    oppOdds  = isOver ? (f.ss_r1_under_odds ?? null)  : (f.ss_r1_over_odds ?? null);
  } else if (el._source === 'td') {
    leanOdds = isOver ? (f.td_over_odds ?? null)  : (f.td_under_odds ?? null);
    oppOdds  = isOver ? (f.td_under_odds ?? null)  : (f.td_over_odds ?? null);
  } else if (el._source === 'ft') {
    leanOdds = isOver ? (f.ft_over_odds ?? null)  : (f.ft_under_odds ?? null);
    oppOdds  = isOver ? (f.ft_under_odds ?? null)  : (f.ft_over_odds ?? null);
  }
  // else: FP lean — no odds available

  const profit = oddsToProfit(leanOdds);
  if (profit != null) {
    // Real odds available — compute vig from both sides if possible
    const vig = computeVig(
      isOver ? leanOdds : oppOdds,
      isOver ? oppOdds : leanOdds,
    );
    const ev = Math.round((winProb * profit - (1 - winProb)) * 100);
    return { ev, isAssumedVig: false, vig, profit, prob: winProb, recalibrated };
  }

  // No real odds — use assumed -110 standard vig (breakeven 52.38%)
  const ASSUMED_PROFIT = 100 / 110; // 0.909
  const ev = Math.round((winProb * ASSUMED_PROFIT - (1 - winProb)) * 100);
  return { ev, isAssumedVig: true, vig: null, profit: ASSUMED_PROFIT, prob: winProb, recalibrated };
}

/** Per-book EV breakdown for stat leans with odds from multiple platforms.
 *  Returns array sorted by best EV first. */
interface PerBookEV { source: string; odds: number; profit: number; ev: number; vig: number | null; isBest: boolean }
function computePerBookEV(f: AnalyzerFighter, el: EffectiveLean): PerBookEV[] {
  if (el.lean !== 'over' && el.lean !== 'under') return [];
  const { p: winProb } = evWinProb(f, el);
  if (winProb <= 0) return [];
  const isOver = el.lean === 'over';

  type OddsPair = { source: string; leanOdds: number | null | undefined; oppOdds: number | null | undefined };
  const pairs: OddsPair[] = [];

  if (el._source === 'ss') {
    if (f.ss_over_odds != null || f.ss_under_odds != null) {
      pairs.push({
        source: 'DK',
        leanOdds: isOver ? f.ss_over_odds  : f.ss_under_odds,
        oppOdds:  isOver ? f.ss_under_odds : f.ss_over_odds,
      });
    }
  } else if (el._source === 'ss_r1') {
    if (f.ss_r1_over_odds != null || f.ss_r1_under_odds != null) {
      pairs.push({
        source: 'DK',
        leanOdds: isOver ? f.ss_r1_over_odds  : f.ss_r1_under_odds,
        oppOdds:  isOver ? f.ss_r1_under_odds : f.ss_r1_over_odds,
      });
    }
  } else if (el._source === 'td') {
    if (f.td_over_odds != null || f.td_under_odds != null) {
      pairs.push({
        source: 'DK',
        leanOdds: isOver ? f.td_over_odds  : f.td_under_odds,
        oppOdds:  isOver ? f.td_under_odds : f.td_over_odds,
      });
    }
  } else if (el._source === 'ft') {
    if (f.ft_over_odds != null || f.ft_under_odds != null) {
      pairs.push({
        source: 'DK',
        leanOdds: isOver ? f.ft_over_odds  : f.ft_under_odds,
        oppOdds:  isOver ? f.ft_under_odds : f.ft_over_odds,
      });
    }
  }
  // Future: add UD/PP/BT odds pairs here when scraped

  const results: PerBookEV[] = [];
  for (const p of pairs) {
    const profit = oddsToProfit(p.leanOdds);
    if (profit == null) continue;
    const vig = computeVig(
      isOver ? p.leanOdds : p.oppOdds,
      isOver ? p.oppOdds : p.leanOdds,
    );
    const ev = Math.round((winProb * profit - (1 - winProb)) * 100);
    results.push({ source: p.source, odds: p.leanOdds!, profit, ev, vig, isBest: false });
  }
  results.sort((a, b) => b.ev - a.ev);
  if (results.length > 0) results[0].isBest = true;
  return results;
}

/** Returns true when FP drives the lean but SS AND TD both lean the opposite direction — hidden risk. */
function hasCrossStatConflict(f: AnalyzerFighter): boolean {
  const eff = getEffectiveLean(f);
  if (eff._source !== 'fp' || !eff.lean || eff.lean === 'none' || eff.lean === 'push') return false;
  const opposite = eff.lean === 'over' ? 'under' : 'over';
  const ssOpp = f.lean_ss?.lean === opposite;
  const tdOpp = f.lean_td?.lean === opposite;
  return ssOpp && tdOpp;
}
// Consensus lean: FP + SS + TD all point the same direction with actionable confidence
function hasConsensusLean(f: AnalyzerFighter): 'over' | 'under' | null {
  const eff = getEffectiveLean(f);
  const dir = eff.lean;
  if (!dir || dir === 'none' || dir === 'push') return null;
  if ((f.lean_ss?.conf ?? 0) < 55 || (f.lean_td?.conf ?? 0) < 55) return null;
  const ssMatch = f.lean_ss?.lean === dir;
  const tdMatch = f.lean_td?.lean === dir;
  return (ssMatch && tdMatch) ? dir : null;
}
function primeCaches(): void {
  // Build fighter-by-name index FIRST so weight-miss adjustment can look up
  // opponent pace via _fighterByNorm before we compute leans.
  _fighterByNorm = new Map();
  for (const f of allFighters) {
    const norm = (normalizeName(f.name) || f.name).toLowerCase();
    _fighterByNorm.set(norm, f);
  }
  // Apply weight-miss adjustments to all sub-leans (mutates in place; idempotent).
  for (const f of allFighters) applyWeightMissToFighter(f);
  // Compute effective leans now that sub-leans are adjusted.
  _leanCache = new Map();
  for (const f of allFighters) {
    _leanCache.set(f.name, _computeEffectiveLean(f));
  }
}

// Reorder fighters so they appear in UFCStats card order with each fight's two
// fighters adjacent. This is what the fight-group badge logic in renderFighters
// (Math.floor(i / 2) → fightIndex) assumes; without it, fighters end up paired
// by whatever order allFighters happens to be in (typically Pick6/UD scrape
// order) and adjacent rows can be from different fights entirely.
function orderFightersByCard(fighters: AnalyzerFighter[]): AnalyzerFighter[] {
  if (!upcomingCardPairs.length) return fighters;
  const normCache = new Map<AnalyzerFighter, string>();
  for (const f of fighters) {
    const n = normalizeName(f.name);
    if (n) normCache.set(f, n);
  }
  const findFighter = (cardName: string): AnalyzerFighter | undefined => {
    for (const [f, n] of normCache) if (n === cardName) return f;
    for (const [f, n] of normCache) {
      if (namesMatch(n, cardName) || strictCardNameMatch(n, cardName)) return f;
    }
    return undefined;
  };
  const ordered: AnalyzerFighter[] = [];
  const used = new Set<AnalyzerFighter>();
  for (const cp of upcomingCardPairs) {
    let f1 = findFighter(cp.f1);
    let f2 = findFighter(cp.f2);
    // Ensure favorite (negative ML) is always first (left side)
    if (f1 && f2) {
      const ml1 = f1.moneyline ?? resolveMoneylineFromMap(f1.name);
      const ml2 = f2.moneyline ?? resolveMoneylineFromMap(f2.name);
      if (ml1 != null && ml2 != null && ml1 > 0 && ml2 < 0) {
        [f1, f2] = [f2, f1];
      }
    }
    if (f1 && !used.has(f1)) { ordered.push(f1); used.add(f1); }
    if (f2 && !used.has(f2)) { ordered.push(f2); used.add(f2); }
  }
  for (const f of fighters) if (!used.has(f)) ordered.push(f);
  return ordered;
}

function sortFighters(fighters: AnalyzerFighter[], sortKey: string): AnalyzerFighter[] {
  const copy = [...fighters];
  const primarySSLine = (f: AnalyzerFighter): number => {
    if (currentPlatform === 'pick6') return f.line_p6_ss ?? f.line_ud_ss ?? f.line_pp_ss ?? f.line_betr_ss ?? 0;
    if (currentPlatform === 'underdog') return f.line_ud_ss ?? f.line_p6_ss ?? f.line_pp_ss ?? f.line_betr_ss ?? 0;
    if (currentPlatform === 'prizepicks') return f.line_pp_ss ?? f.line_p6_ss ?? f.line_ud_ss ?? f.line_betr_ss ?? 0;
    return f.line_betr_ss ?? f.line_p6_ss ?? f.line_ud_ss ?? f.line_pp_ss ?? 0;
  };
  const primaryFTLine = (f: AnalyzerFighter): number => {
    if (currentPlatform === 'pick6') return f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? 0;
    if (currentPlatform === 'underdog') return f.line_ud_ft ?? f.line_p6_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? 0;
    if (currentPlatform === 'prizepicks') return f.line_pp_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? 0;
    if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? 0;
    return f.line_betr_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_dk_ft ?? 0;
  };
  const ssDelta = (f: AnalyzerFighter): number => {
    const avg = f.db?.avgSigStr ?? 0;
    const line = primarySSLine(f);
    return avg - line;
  };
  switch (sortKey) {
    case 'line':        return copy.sort((a, b) => (activePlatformLine(b) || 0) - (activePlatformLine(a) || 0));
    case 'ssline':      return copy.sort((a, b) => primarySSLine(b) - primarySSLine(a));
    case 'ftline':      return copy.sort((a, b) => primaryFTLine(b) - primaryFTLine(a));
    case 'avgss':       return copy.sort((a, b) => (b.db?.avgSigStr || 0) - (a.db?.avgSigStr || 0));
    case 'delta':       return copy.sort((a, b) => ssDelta(b) - ssDelta(a));
    case 'conf':        return copy.sort((a, b) => (getEffectiveLean(b).conf || 0) - (getEffectiveLean(a).conf || 0));
    case 'avgfp':       return copy.sort((a, b) => (b.db?.avgFP_p6 || 0) - (a.db?.avgFP_p6 || 0));
    case 'floor':       return copy.sort((a, b) => (b.db?.fpFloor || 0) - (a.db?.fpFloor || 0));
    case 'ceil':        return copy.sort((a, b) => (b.db?.fpCeiling || 0) - (a.db?.fpCeiling || 0));
    case 'consistency': return copy.sort((a, b) => (b.db?.fpConsistency || 0) - (a.db?.fpConsistency || 0));
    default: return copy;
  }
}

/**
 * GLOW-UP 223 L9 — time from now to the first bell, which the QA panel and the
 * report card both need.
 *
 * Event timestamps are frequently date-only (local midnight) and no card starts
 * at midnight, so a 7pm start is assumed — otherwise the countdown and the
 * fight-day escalation both fire a day early. That shim lived inside
 * renderQAPanel; the report card would have had to re-derive it, and a fact
 * derived twice drifts (see the two line-staleness checks, and the report card's
 * own screen-vs-export split).
 */
function eventCountdown(): { msToEvent: number; fightDay: boolean; tMinus: string } {
  let effEventTs = upcomingEventTs;
  if (effEventTs > 0) {
    const evD = new Date(effEventTs);
    if (evD.getHours() === 0 && evD.getMinutes() === 0) effEventTs += 19 * 3600e3;
  }
  const msToEvent = effEventTs > 0 ? effEventTs - Date.now() : NaN;
  const fightDay = Number.isFinite(msToEvent) && msToEvent > -12 * 3600e3 && msToEvent < 24 * 3600e3;
  const tMinus = ((): string => {
    if (!Number.isFinite(msToEvent) || msToEvent <= 0) return '';
    const h = Math.floor(msToEvent / 3600e3);
    const d = Math.floor(h / 24);
    return d >= 1 ? `T-${d}d ${h % 24}h` : h >= 1 ? `T-${h}h ${Math.floor((msToEvent % 3600e3) / 60000)}m` : `T-${Math.floor(msToEvent / 60000)}m`;
  })();
  return { msToEvent, fightDay, tMinus };
}

/** Minutes → the compact age the platform pills and the report card both print. */
function fmtAgeMin(min: number): string {
  if (min < 60) return `${min}m`;
  if (min < 1440) return `${Math.floor(min / 60)}h`;
  return `${Math.floor(min / 1440)}d`;
}

async function renderQAPanel(): Promise<void> {
  const panel = document.getElementById('qaPanel');
  if (!panel) return;

  // GLOW-UP 163 (level-up 5): sticky mini-verdict in the toolbar — kept in
  // sync here so the slate state is readable from anywhere on the board.
  const miniVerdict = document.getElementById('qaMiniVerdict') as HTMLButtonElement | null;
  if (miniVerdict && !miniVerdict.dataset['wired']) {
    miniVerdict.dataset['wired'] = '1';
    miniVerdict.addEventListener('click', () => {
      document.getElementById('qaPanel')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }

  // Only show on the main fighter-card views — archive/calibration/etc. have their own context.
  const hideForView = currentView === 'archive' || currentView === 'calibration';
  if (!allFighters.length || hideForView) {
    panel.style.display = 'none';
    if (miniVerdict) miniVerdict.hidden = true;
    return;
  }

  const totalFighters = allFighters.length;

  const [linesPayload, manualPayload] = await Promise.all([
    storageGet<Record<string, any>>([...STORAGE_LINE_KEYS]),
    storageGet<Record<string, any>>([STORAGE_BETR_MANUAL_KEY, 'qa_acked_v1', 'qa_cov_prev_v1']),
  ]);

  // `manual: true` means the platform has no auto-scrape — staleness is informational only,
  // thresholds are relaxed, and the platform never contributes to the top "stale/missing" error.
  type PlatformInfo = { key: string; label: string; capturedAt: number; ageMin: number | null; manual: boolean };
  const platformInfo: PlatformInfo[] = [
    { key: 'lines_pick6',                 label: 'P6', capturedAt: 0, ageMin: null, manual: false },
    { key: 'lines_underdog',              label: 'UD', capturedAt: 0, ageMin: null, manual: false },
    { key: 'lines_betr',                  label: 'BT', capturedAt: 0, ageMin: null, manual: true  },
    { key: 'lines_prizepicks',            label: 'PP', capturedAt: 0, ageMin: null, manual: false },
    { key: 'lines_draftkings_sportsbook', label: 'DK', capturedAt: 0, ageMin: null, manual: false },
  ];
  // Apply the same manual-Betr overlay the main line loader uses — otherwise
  // a fresh manual entry renders as "5h stale" because lines_betr.capturedAt
  // is still the old seed timestamp.
  const manualBetrForOverlay = manualPayload[STORAGE_BETR_MANUAL_KEY] as { fighters?: unknown[]; capturedAt?: number } | null;
  if (manualBetrForOverlay?.fighters?.length) {
    const effectiveBetrTs = Number(manualBetrForOverlay.capturedAt) || Date.now();
    const betrRaw = linesPayload['lines_betr'] || {};
    linesPayload['lines_betr'] = { ...betrRaw, capturedAt: effectiveBetrTs };
  }
  for (const p of platformInfo) {
    const val = linesPayload[p.key];
    const ts = Number(val?.capturedAt || 0);
    p.capturedAt = ts;
    p.ageMin = ts > 0 ? Math.floor((Date.now() - ts) / 60000) : null;
  }

  // Co-locate freshness with the top-of-page platform pills (Pick6/UD/Betr/DK/PP).
  const PILL_AGE_IDS: Record<string, string> = {
    'lines_pick6':                 'ageP6',
    'lines_underdog':              'ageUD',
    'lines_betr':                  'ageBetr',
    'lines_prizepicks':            'agePP',
    'lines_draftkings_sportsbook': 'ageDK',
  };
  for (const p of platformInfo) {
    const ageEl = document.getElementById(PILL_AGE_IDS[p.key]);
    if (!ageEl) continue;
    if (p.ageMin == null) {
      ageEl.textContent = '';
      ageEl.className = 'pill-age';
      ageEl.removeAttribute('title');
      continue;
    }
    const warnAt = p.manual ? 720 : 15;
    const errAt  = p.manual ? 1440 : 60;
    const cls = p.ageMin >= errAt ? 'stale' : p.ageMin >= warnAt ? 'aging' : 'fresh';
    const ageLabel = p.ageMin < 1 ? 'now' : p.ageMin < 60 ? `${p.ageMin}m` : `${Math.floor(p.ageMin/60)}h`;
    ageEl.textContent = ageLabel;
    ageEl.className = `pill-age ${cls}`;
    const staleIntensity = cls === 'stale'
      ? Math.min(1, Math.max(0, (p.ageMin - errAt) / 600))
      : 0;
    ageEl.style.setProperty('--stale-intensity', staleIntensity.toFixed(2));
    ageEl.title = `${p.label} captured ${ageLabel} ago${p.manual ? ' (manual entry — no auto-scrape)' : ''}`;
  }

  const hasPlatformLine = (f: AnalyzerFighter, plat: string): boolean => {
    if (plat === 'lines_pick6')                 return f.line_p6 != null || f.line_p6_ss != null || f.line_p6_td != null || f.line_p6_ft != null;
    if (plat === 'lines_underdog')              return f.line_ud != null || f.line_ud_ss != null || f.line_ud_td != null || f.line_ud_ft != null;
    if (plat === 'lines_betr')                  return f.line_betr != null || f.line_betr_ss != null || f.line_betr_td != null || f.line_betr_ft != null;
    if (plat === 'lines_prizepicks')            return f.line_pp != null || f.line_pp_ss != null || f.line_pp_td != null || f.line_pp_ft != null;
    if (plat === 'lines_draftkings_sportsbook') return f.line_dk_ss != null || f.line_dk_td != null || f.line_dk_ft != null;
    return false;
  };
  // GLOW-UP 163 (level-up 3): keep the NAMES, not just the count — the row
  // expands to show which fighters are lineless, each chip jumping to the card.
  const missingByPlatform = new Map<string, string[]>();
  for (const p of platformInfo) {
    // Skip platforms with no data at all — staleness will already flag them.
    if (p.ageMin == null) continue;
    // DK Sportsbook posts fighter props progressively across the week — partial
    // coverage is expected, not a data issue. Skip it from the missing-lines check.
    if (p.key === 'lines_draftkings_sportsbook') continue;
    const missingNames = allFighters.filter(f => !hasPlatformLine(f, p.key)).map(f => f.name);
    if (missingNames.length > 0 && missingNames.length < totalFighters) missingByPlatform.set(p.label, missingNames);
  }

  // GLOW-UP 165 (level-up 3): convergence deltas — remember the last observed
  // coverage counts (per event) and mark movement on the chips (▲ filling in,
  // ▼ pulled), so the strip answers "is this slate trending toward ready?".
  const covNow: Record<string, number> = {};
  for (const p of platformInfo) {
    if (p.ageMin == null) continue;
    covNow[p.label] = allFighters.filter(f => hasPlatformLine(f, p.key)).length;
  }
  const covPrevRaw = manualPayload['qa_cov_prev_v1'] as { event?: string; prev?: Record<string, number>; curr?: Record<string, number> } | undefined;
  const covStored = covPrevRaw?.event === upcomingEventName ? covPrevRaw : undefined;
  const covPrev: Record<string, number> = { ...(covStored?.prev || {}) };
  const covCurr: Record<string, number> = { ...(covStored?.curr || {}) };
  let covChanged = !covStored;
  for (const [label, n] of Object.entries(covNow)) {
    if (covCurr[label] !== n) {
      if (covCurr[label] != null) covPrev[label] = covCurr[label];
      covCurr[label] = n;
      covChanged = true;
    }
  }
  if (covChanged) void storageSet({ qa_cov_prev_v1: { event: upcomingEventName, prev: covPrev, curr: covCurr } });
  const covDelta = (label: string): string => {
    const prev = covPrev[label];
    const now = covNow[label];
    if (prev == null || now == null || prev === now) return '';
    const d = now - prev;
    return `<span class="qa-cov-delta ${d > 0 ? 'up' : 'down'}" title="${label} coverage moved ${prev}→${now} since the last check">${d > 0 ? '▲' : '▼'}${Math.abs(d)}</span>`;
  };

  // Did the last run actually reach the books? Auto-fetch clears a platform's
  // store before fetching and only writes on success, so "returned nothing" and
  // "never attempted" both end up with no store — indistinguishable on their own.
  // The other books settle it: if they captured, this one was asked too.
  // Defined ONCE and shared with the staleness check below, because the coverage
  // chip and the issue list disagreeing is the exact defect this pass is fixing.
  const anyAutoFetched = platformInfo.some(p =>
    !p.manual && p.key !== 'lines_draftkings_sportsbook' && p.ageMin != null);

  // GLOW-UP 163 (level-up 4): coverage strip — per-book freshness + line
  // coverage, always visible so even a clean slate reports its state.
  const covChips = platformInfo.map(p => {
    const isDk = p.key === 'lines_draftkings_sportsbook';
    if (p.ageMin == null) {
      // Never captured. For a MANUAL book that is not a failure and not something
      // a fetch can fix — it is waiting on you, and saying "no data" next to a
      // "run AUTO-FETCH" directive points at the wrong action entirely.
      if (p.manual) {
        return `<span class="qa-cov qa-cov-nopost" title="${p.label}: nothing entered yet. This book is MANUAL — Auto-Fetch does not touch it. Use ✎ BETR LINES when the book posts."><b>${p.label}</b><i>not entered</i></span>`;
      }
      // No store — but the other books captured, so this one WAS asked and had
      // nothing. Saying "not fetched" here would contradict the issue list, which
      // has already decided this is not a fetch problem.
      return anyAutoFetched
        ? `<span class="qa-cov qa-cov-nopost" title="${p.label}: asked in the last run and returned nothing — the book has not posted these props yet, so another fetch will not help.${isDk ? ' DK posts fighter props progressively; absence early in fight week is normal.' : ' Check the book itself before suspecting the scraper.'}"><b>${p.label}</b><i>none posted</i></span>`
        : `<span class="qa-cov qa-cov-none" title="${p.label}: never captured, and no other book captured either — nothing has been fetched yet. This one IS a fetch away."><b>${p.label}</b><i>not fetched</i></span>`;
    }
    const covered = covNow[p.label] ?? 0;
    const warnAt = p.manual ? 720 : 15;
    const errAt  = p.manual ? 1440 : 60;
    const freshCls: 'ok'|'warn'|'err' = p.ageMin >= errAt ? 'err' : p.ageMin >= warnAt ? 'warn' : 'ok';
    // ── "NOTHING POSTED" IS NOT "NOTHING FETCHED" ─────────────────────────
    // A book we captured SUCCESSFULLY that yields zero fighters on this card has
    // nothing posted — running Auto-Fetch again cannot conjure lines the book has
    // not published. Treating that as a coverage warning sends you chasing a
    // scraper bug that does not exist: on 2026-08-11 PrizePicks read `0/24` and
    // cost an hour before the answer turned out to be that PP had only DWCS
    // standard props plus demon/goblin UFC 330 props — i.e. correct behaviour.
    // It gets its own neutral state, distinct from a partial gap you can act on.
    const nonePosted = covered === 0 && !isDk;
    // DK partial coverage is expected (progressive posting) — freshness only.
    const covCls: 'ok'|'warn'|'nopost' = (isDk || covered >= totalFighters) ? 'ok' : nonePosted ? 'nopost' : 'warn';
    const state = freshCls === 'err' ? 'err'
                : freshCls === 'warn' ? 'warn'
                : covCls === 'warn' ? 'warn'
                : covCls === 'nopost' ? 'nopost'
                : 'ok';
    const ageLabel = p.ageMin < 1 ? 'now' : p.ageMin < 60 ? `${p.ageMin}m` : `${Math.floor(p.ageMin / 60)}h`;
    const covTip = nonePosted
      ? `captured ${ageLabel} ago and returned NOTHING for this card — the book has not posted these props yet, so another fetch will not help.${p.manual ? ' Manual book: enter rows when it posts.' : ' Check the book itself before suspecting the scraper.'}`
      : `captured ${ageLabel} ago · ${covered}/${totalFighters} fighters with lines${p.manual ? ' · manual entry (no auto-scrape)' : ''}${isDk ? ' · DK partial coverage is normal' : ''}`;
    return `<span class="qa-cov qa-cov-${state}" title="${p.label}: ${covTip}"><b>${p.label}</b><span class="qa-cov-age">${ageLabel}</span><span class="qa-cov-n">${nonePosted ? 'none posted' : `${covered}/${totalFighters}`}</span>${covDelta(p.label)}</span>`;
  }).join('');
  const covStrip = `<div class="qa-cov-strip">${covChips}</div>`;

  const manualBetr = manualPayload[STORAGE_BETR_MANUAL_KEY];
  const manualRowCount = manualBetr?.fighters?.length || 0;
  const betrPlatformLoaded = platformInfo.find(p => p.key === 'lines_betr')?.ageMin != null;
  const betrManualShort = betrPlatformLoaded && manualRowCount > 0 && manualRowCount < totalFighters;

  // GLOW-UP 163 (level-up 2): `action` marks issues whose fix is a single
  // existing button — the row carries the button instead of making the user
  // hunt for it (fetch → AUTO-FETCH LINES, betr → BETR LINES manual entry).
  // GLOW-UP 164: acknowledged known gaps — issues with an ackKey can be muted
  // for the CURRENT event (short-notice fights whose props post late are the
  // recurring case). Scoped to upcomingEventName so acks self-reset on flip.
  // Staleness rows are deliberately NOT ack-able — they're time-driven.
  const ackedRaw = manualPayload['qa_acked_v1'] as { event?: string; keys?: string[] } | undefined;
  const acked = new Set<string>(ackedRaw?.event === upcomingEventName ? (ackedRaw.keys || []) : []);

  type Issue = { level: 'err'|'warn'; text: string; chip: string; action?: 'fetch'|'betr'; fighters?: string[]; ackKey?: string };
  const issues: Issue[] = [];

  // GLOW-UP 165 (level-up 2): time-to-lock awareness — the slate's urgency
  // depends on how far out the event is. Within 24h ("fight day") aging lines
  // escalate from warning to blocker: stale lines inside the entry window are
  // entry-threatening, not cosmetic.
  // GLOW-UP 223 L9: the countdown (including the midnight → 7pm shim) now lives
  // in eventCountdown(), shared with the report card's vintage line.
  const { msToEvent, fightDay, tMinus } = eventCountdown();
  const tlock = Number.isFinite(msToEvent)
    ? (msToEvent <= 0
      ? `<span class="qa-tlock qa-tlock-hot" title="${upcomingEventName || 'Event'} has started — lines are locked">● LOCKED</span>`
      : `<span class="qa-tlock${fightDay ? ' qa-tlock-hot' : ''}" title="Time until ${upcomingEventName || 'the event'}${fightDay ? ' — FIGHT DAY: aging lines now count as blockers' : ' — slate must be READY before lock'}">⏱ ${tMinus}</span>`)
    : '';

  // Manual platforms (Betr) don't auto-scrape — excluded from the top stale/missing blocker.
  const autoPlatforms = platformInfo.filter(p => !p.manual);
  // DK is excluded here for the same reason it is already excluded from the
  // missing-lines check and the freshness SCORE: it posts fighter props
  // progressively across the week, so "DK has nothing" four days out is normal.
  // Left in, it became a BLOCKER whose prescribed fix was a fetch that cannot
  // conjure props DK has not published — the panel read NOT READY and pointed at
  // the wrong action (observed 2026-08-11, T-4d).
  const stalePlatforms = autoPlatforms.filter(p => p.key !== 'lines_draftkings_sportsbook');
  // A never-captured book is only a FETCH problem if we have not fetched AT ALL.
  // When the other books captured fine in the same run, that book was asked and
  // returned nothing — "has not posted", not "stale". Uses the SAME shared
  // `anyAutoFetched` the coverage chips read, so the strip and the verdict cannot
  // tell different stories about the same book.
  const staleErr  = stalePlatforms.filter(p => (p.ageMin == null ? !anyAutoFetched : p.ageMin >= 60));
  const staleWarn = stalePlatforms.filter(p => p.ageMin != null && p.ageMin >= 15 && p.ageMin < 60);
  if (staleErr.length) {
    const names = staleErr.map(p => p.ageMin == null ? `${p.label} (not fetched)` : `${p.label} (${p.ageMin}m)`).join(', ');
    const chip = staleErr.length === 1
      ? `${staleErr[0].label} ${staleErr[0].ageMin == null ? 'not fetched' : 'stale'}`
      : `${staleErr.length} books stale`;
    // "stale/missing" conflated two things with different fixes. This row now
    // only ever holds books a fetch can actually help — genuinely aged data, or
    // a run where nothing was captured at all.
    issues.push({ level: 'err', text: `Platform lines stale: ${names}`, chip, action: 'fetch' });
  }
  if (staleWarn.length) {
    const names = staleWarn.map(p => `${p.label} (${p.ageMin}m)`).join(', ');
    const chip = staleWarn.length === 1
      ? `${staleWarn[0].label} ${staleWarn[0].ageMin}m`
      : `${staleWarn.length} books aging`;
    issues.push({
      level: fightDay ? 'err' : 'warn',
      text: fightDay
        ? `Lines aging: ${names} — FIGHT DAY: refresh before entering`
        : `Lines aging: ${names} — consider refresh`,
      chip,
      action: 'fetch',
    });
  }
  for (const [label, names] of missingByPlatform) {
    issues.push({
      level: 'warn',
      text: `${label}: ${names.length} of ${totalFighters} fighters without lines`,
      chip: `${label} missing ${names.length}`,
      action: label === 'BT' ? 'betr' : undefined,
      fighters: names,
      ackKey: `missing:${label}`,
    });
  }
  if (betrManualShort) {
    issues.push({
      level: 'err',
      text: `Betr manual entries: ${manualRowCount} of ${totalFighters} — missing ${totalFighters - manualRowCount} rows`,
      chip: `Betr ${manualRowCount}/${totalFighters}`,
      action: 'betr',
      ackKey: 'betr-short',
    });
  }

  // Blockers before warnings — implicit grouping without needing section headers.
  issues.sort((a, b) => (a.level === b.level ? 0 : a.level === 'err' ? -1 : 1));

  // GLOW-UP 164: acknowledged issues drop out of counts, verdict, and rows —
  // they collapse into a muted one-liner with a restore control below.
  const activeIssues = issues.filter(i => !(i.ackKey && acked.has(i.ackKey)));
  const ackedIssues = issues.filter(i => i.ackKey && acked.has(i.ackKey));

  const errCount = activeIssues.filter(i => i.level === 'err').length;
  const warnCount = activeIssues.filter(i => i.level === 'warn').length;
  const hasErr = errCount > 0;
  const hasWarn = warnCount > 0;
  const level: 'ok'|'warn'|'err' = hasErr ? 'err' : hasWarn ? 'warn' : 'ok';
  const chipMode = activeIssues.length > 0 && activeIssues.length <= 3;

  const fetchBtn = document.getElementById('autoScrapeBtn');
  if (fetchBtn) {
    const freshness = staleErr.length > 0 ? 'stale'
      : staleWarn.length > 0 ? 'aging'
      : autoPlatforms.every(p => p.ageMin != null) ? 'fresh'
      : '';
    if (freshness) fetchBtn.setAttribute('data-freshness', freshness);
    else fetchBtn.removeAttribute('data-freshness');
  }

  const sumParts: string[] = [];
  if (errCount) sumParts.push(`<span class="qa-sum-err">${errCount} ${errCount === 1 ? 'blocker' : 'blockers'}</span>`);
  if (warnCount) sumParts.push(`<span class="qa-sum-warn">${warnCount} ${warnCount === 1 ? 'warning' : 'warnings'}</span>`);
  const summary = level === 'ok'
    ? `✓ Ready to pick · all platforms fresh · ${totalFighters} fighters loaded`
    : sumParts.join('<span class="qa-sum-sep">·</span>');

  const chipsHtml = chipMode
    ? `<div class="qa-issue-chips">${activeIssues.map(i =>
        `<span class="qa-issue-chip qa-issue-${i.level}" title="${i.text.replace(/"/g, '&quot;')}">${i.chip}</span>`
      ).join('')}</div>`
    : '';
  const fixBtnHtml = (i: Issue): string => i.action
    ? `<button class="qa-fix" data-fix="${i.action}" title="${i.action === 'fetch' ? 'Run AUTO-FETCH LINES for the auto-scraped books' : 'Open the BETR LINES manual entry flow'}">${i.action === 'fetch' ? '⚡ FETCH' : '✎ BETR'}</button>`
    : '';
  // GLOW-UP 163 (level-up 3): expandable rows — issues that know their
  // fighters render a caret + a hidden chip list; a chip jumps to the card.
  const caretHtml = (i: Issue): string => i.fighters?.length
    ? `<span class="qa-exp-caret" aria-hidden="true">▸</span>`
    : '';
  const missingListHtml = (i: Issue): string => i.fighters?.length
    ? `<div class="qa-missing-list">${i.fighters.map(n =>
        `<button class="qa-missing-chip" data-name="${n.replace(/"/g, '&quot;')}" title="Open ${prettyName(n)}'s fighter card">${prettyName(n)}</button>`
      ).join('')}</div>`
    : '';
  const ackBtnHtml = (i: Issue): string => i.ackKey
    ? `<button class="qa-ack" data-ack="${i.ackKey}" title="Acknowledge as a known gap (e.g. short-notice fight whose props post late) — mutes this issue for the current event; resets automatically when the slate flips">✓ ACK</button>`
    : '';
  const issuesHtml = (!chipMode && activeIssues.length)
    ? `<ul class="qa-issues">${activeIssues.map(i =>
        `<li class="qa-issue-${i.level}${i.fighters?.length ? ' qa-expandable' : ''}"${i.fighters?.length ? ' title="Click to show which fighters"' : ''}><span class="qa-issue-icon" aria-hidden="true">${i.level === 'err' ? '✕' : '!'}</span><span class="qa-issue-text">${i.text}</span>${fixBtnHtml(i)}${ackBtnHtml(i)}${caretHtml(i)}${missingListHtml(i)}</li>`
      ).join('')}</ul>`
    : '';
  const ackedHtml = ackedIssues.length
    ? `<div class="qa-acked-row"><span class="qa-acked-note">✓ ${ackedIssues.length} acknowledged known gap${ackedIssues.length === 1 ? '' : 's'} · ${ackedIssues.map(i => i.chip).join(' · ')}</span><button id="qaAckUndo" class="qa-ack-undo" title="Restore acknowledged issues to the checklist">restore</button></div>`
    : '';

  panel.className = `qa-panel qa-${level}${(level === 'ok' || chipMode) ? ' qa-compact' : ''}`;
  panel.style.display = '';
  // GLOW-UP 165 (Slate Check level-up 1): weighted readiness score 0–100 —
  // freshness of the auto-scraped books (36) + per-book line coverage (44) +
  // Betr manual entry completeness (20). Acked known gaps waive their penalty
  // so the score agrees with the verdict's semantics.
  const freshScore = (p: { ageMin: number | null }): number =>
    p.ageMin == null ? 0 : p.ageMin >= 60 ? 0 : p.ageMin >= 15 ? 0.6 : 1;
  const covScore = (label: string, key: string): number => {
    if (acked.has(`missing:${label}`)) return 1;
    const info = platformInfo.find(x => x.label === label);
    if (!info || info.ageMin == null) return 0;
    return allFighters.filter(f => hasPlatformLine(f, key)).length / (totalFighters || 1);
  };
  const betrScore = (betrManualShort && !acked.has('betr-short'))
    ? manualRowCount / (totalFighters || 1)
    : betrPlatformLoaded ? 1 : 0;
  // DK is excluded from freshness like it is from coverage — its progressive
  // posting is informational, and counting it pushed the sum past 100 (the
  // clamp then showed a saturated "100%" next to NOT READY).
  const readiness = Math.min(100, Math.round(
    autoPlatforms.filter(p => p.key !== 'lines_draftkings_sportsbook').reduce((s, p) => s + freshScore(p) * 12, 0) +
    covScore('P6', 'lines_pick6') * 11 +
    covScore('UD', 'lines_underdog') * 11 +
    covScore('PP', 'lines_prizepicks') * 11 +
    covScore('BT', 'lines_betr') * 11 +
    betrScore * 20
  ));
  const readinessBar = `<div class="qa-readiness qa-readiness-${level}" title="Slate readiness: ${readiness}% — freshness 36 · coverage 44 · Betr entry 20 (acked gaps don't count against it)"><i style="width:${readiness}%"></i></div>`;

  // GLOW-UP 165 (level-up 4): single next-step directive — the checklist names
  // THE one action that moves readiness most, in the Learning Drilldown's
  // directive voice, with the action button on the line itself.
  const staleBlocker  = activeIssues.find(i => i.level === 'err' && i.action === 'fetch');
  const betrBlocker   = activeIssues.find(i => i.ackKey === 'betr-short');
  const missingWarns  = activeIssues.filter(i => i.ackKey?.startsWith('missing:'));
  const agingWarn     = activeIssues.find(i => i.level === 'warn' && i.action === 'fetch');
  const nextRow = (text: string, btn = ''): string =>
    `<div class="qa-next"><span class="qa-next-label">NEXT</span><span class="qa-next-text">${text}</span>${btn}</div>`;
  const nextHtml = staleBlocker
    // Says STALE, not "stale or missing". This branch only fires on a freshness
    // error, and conflating the two sent the eye to books that had simply not
    // posted — which no amount of fetching fixes. Missing coverage has its own
    // branch below ("wait for props to post"), which is the honest instruction.
    ? nextRow('Run AUTO-FETCH — book data is stale', `<button class="qa-fix" data-fix="fetch">⚡ FETCH</button>`)
    : betrBlocker
    ? nextRow(`Enter the ${totalFighters - manualRowCount} missing Betr row${totalFighters - manualRowCount === 1 ? '' : 's'} — or ACK if they can't be entered yet`, `<button class="qa-fix" data-fix="betr">✎ BETR</button>`)
    : missingWarns.length
    ? nextRow(`Wait for props to post — or acknowledge the ${missingWarns.length} known gap${missingWarns.length === 1 ? '' : 's'} to clear the slate`, `<button class="qa-ack-all" title="Acknowledge all known coverage gaps for this event">✓ ACK ALL</button>`)
    : agingWarn
    ? nextRow(fightDay ? 'Fight day — refresh lines before entering' : 'Lines aging — refresh when convenient', `<button class="qa-fix" data-fix="fetch">⚡ FETCH</button>`)
    : `<div class="qa-next qa-next-ok"><span class="qa-next-label">NEXT</span><span class="qa-next-text">Slate ready — build your entries from Best Picks</span></div>`;

  // GLOW-UP 163 (Slate Check level-up 1): readiness verdict — one chip that
  // answers "can I pick yet" before the eye reads any counts or rows.
  const verdict = level === 'ok'
    ? `<span class="qa-verdict qa-verdict-ok" title="All platforms fresh, no missing lines — safe to build entries">✓ READY · ${readiness}%</span>`
    : level === 'warn'
    ? `<span class="qa-verdict qa-verdict-warn" title="${warnCount} warning${warnCount === 1 ? '' : 's'} — picks work, but review the gaps below before locking entries">! CHECK SLATE · ${readiness}%</span>`
    : `<span class="qa-verdict qa-verdict-err" title="${errCount} blocker${errCount === 1 ? '' : 's'} — fix these before trusting the board">✕ NOT READY · ${readiness}%</span>`;
  if (miniVerdict) {
    miniVerdict.hidden = false;
    miniVerdict.className = `qa-mini-verdict qa-mini-${level}`;
    miniVerdict.textContent = `${level === 'ok' ? '✓' : level === 'warn' ? '!' : '✕'} SLATE ${readiness}%`;
    miniVerdict.title = level === 'ok'
      ? 'Slate Check: ready — click to review'
      : `Slate Check: ${errCount ? `${errCount} blocker${errCount === 1 ? '' : 's'}` : ''}${errCount && warnCount ? ' · ' : ''}${warnCount ? `${warnCount} warning${warnCount === 1 ? '' : 's'}` : ''} — click to review`;
  }
  // GLOW-UP 165 (level-up 5): Go/No-Go final form — a clean (or fully
  // acknowledged) slate collapses the checklist into a green GO bar that
  // hands off into the pick workflow; the expanded checklist only exists
  // while something needs the user.
  if (level === 'ok') {
    const bpCount = document.getElementById('tabCountBestPicks')?.textContent?.trim() || '';
    panel.className = 'qa-panel qa-ok qa-go';
    panel.innerHTML = `
      <div class="qa-go-bar">
        <span class="qa-go-badge">GO</span>
        <span class="qa-go-title">Slate ready · ${readiness}%</span>
        ${tlock}
        <div class="qa-go-actions">
          <button class="qa-go-btn" data-goview="bestpicks" title="Open AI Best Picks">⚡ Best Picks${bpCount && bpCount !== '—' ? ` · ${bpCount}` : ''} →</button>
          <button class="qa-go-btn" data-goview="parlaylab" title="Open Parlay Lab">🔗 Parlay Lab →</button>
        </div>
      </div>
      <div class="qa-go-sub">${covStrip}${ackedHtml}</div>
    `;
  } else {
    panel.innerHTML = `
    <div class="qa-panel-header">
      <span class="qa-panel-title">Slate Check</span>
      ${tlock}
      ${verdict}
    </div>
    <div class="qa-summary">${summary}</div>
    ${readinessBar}
    ${nextHtml}
    ${covStrip}
    ${chipsHtml}
    ${issuesHtml}${ackedHtml}
  `;
  }

  // GO bar launch buttons → activate the real view tabs so all existing
  // tab-switch logic (render, visibility, QA re-sync) runs unchanged.
  panel.querySelectorAll<HTMLButtonElement>('.qa-go-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const view = btn.dataset['goview'];
      if (view) document.querySelector<HTMLElement>(`.tab-btn[data-view="${view}"]`)?.click();
    });
  });

  // GLOW-UP 163 (level-up 2): wire the inline fix buttons to the existing
  // header controls — same code paths, zero new behavior to maintain.
  panel.querySelectorAll<HTMLButtonElement>('.qa-fix').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const target = btn.dataset['fix'] === 'betr' ? 'manualEntryBtn' : 'autoScrapeBtn';
      document.getElementById(target)?.click();
    });
  });
  panel.querySelectorAll<HTMLElement>('li.qa-expandable').forEach(li => {
    li.addEventListener('click', () => li.classList.toggle('qa-open'));
  });
  panel.querySelectorAll<HTMLButtonElement>('.qa-missing-chip').forEach(chip => {
    chip.addEventListener('click', (e) => {
      e.stopPropagation();
      jumpToFighterCard(chip.dataset['name'] || '');
    });
  });
  // GLOW-UP 164: ack / restore — per-event UI state in qa_acked_v1 (never
  // touches line stores); event mismatch on read = automatic reset on flip.
  panel.querySelectorAll<HTMLButtonElement>('.qa-ack').forEach(btn => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      const key = btn.dataset['ack'];
      if (!key) return;
      acked.add(key);
      await storageSet({ qa_acked_v1: { event: upcomingEventName, keys: [...acked] } });
      void renderQAPanel();
    });
  });
  document.getElementById('qaAckUndo')?.addEventListener('click', async (e) => {
    e.stopPropagation();
    await storageSet({ qa_acked_v1: { event: upcomingEventName, keys: [] } });
    void renderQAPanel();
  });
  // GLOW-UP 165 (level-up 4): ACK ALL — acknowledge every ack-able coverage
  // gap at once from the NEXT directive line.
  panel.querySelector<HTMLButtonElement>('.qa-ack-all')?.addEventListener('click', async (e) => {
    e.stopPropagation();
    for (const i of issues) { if (i.ackKey?.startsWith('missing:')) acked.add(i.ackKey); }
    await storageSet({ qa_acked_v1: { event: upcomingEventName, keys: [...acked] } });
    void renderQAPanel();
  });
}

function renderModelHealthWidget(): void {
  void renderQAPanel();
  const leanPairs = allFighters
    .map(f => ({ f, l: getEffectiveLean(f) }))
    .filter(({ l }) => l.lean !== 'none' && l.conf > 0);
  const leans = leanPairs.map(p => p.l);
  const setText = (id: string, value: string): void => {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
  };
  const setNum = (id: string, value: string): void => {
    const el = document.getElementById(id);
    if (el) animateNumberText(el, value);
  };
  const setTileStatus = (id: string, status: 'good' | 'warn' | 'bad' | 'info' | null): void => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove('mh-good', 'mh-warn', 'mh-bad', 'mh-info');
    if (status) el.classList.add(`mh-${status}`);
  };
  const setMeter = (id: string, pct: number): void => {
    const el = document.getElementById(id);
    if (el) el.style.width = `${Math.max(0, Math.min(100, pct))}%`;
  };
  const BREAKEVEN = 52.4; // -110 pick-em breakeven; matches computeDetailedEV's assumed vig

  if (!leans.length) {
    setText('mhHitRate', '--%');
    setText('mhHitTrend', 'Waiting for model data');
    setText('mhTopEdge', '--');
    setText('mhTopEdgeTrend', 'No actionable edges');
    setText('mhCoverage', '0');
    setText('mhCoverageTrend', 'fighters with actionable leans');
    setTileStatus('mhTileHit', null);
    setTileStatus('mhTileEdge', null);
    setTileStatus('mhTileCov', 'info');
    setMeter('mhHitFill', 0);
    setMeter('mhCoverageFill', 0);
    void renderLearningDiagnosticsWidget();
    return;
  }

  const hitProbs = leans
    .map(l => {
      // calibratedProbability (P over) takes precedence; fall back to conf/100 which already
      // represents the model's confidence that the directional lean is correct.
      if (l.calibratedProbability != null) {
        return l.lean === 'under' ? (1 - l.calibratedProbability) : l.calibratedProbability;
      }
      return Number.isFinite(l.conf) ? l.conf / 100 : null;
    })
    .filter((v): v is number => v != null);

  const avgHit = hitProbs.length ? Math.round((hitProbs.reduce((s, v) => s + v, 0) / hitProbs.length) * 100) : 0;

  let topEdge: { name: string; source: LeanSource; dir: 'over' | 'under'; ev: number } | null = null;
  for (const { f, l } of leanPairs) {
    const dir = l.lean as 'over' | 'under';
    if (shouldSkipFpSideForFighter(f, l._source, dir, l._platform)) continue;
    const ev = computeFighterEV(f, l);
    if (ev == null) continue;
    if (!topEdge || ev > topEdge.ev) {
      topEdge = { name: f.name, source: l._source, dir, ev };
    }
  }

  // ── Tile 1: Calibrated Hit Rate — meter vs the −110 breakeven it must clear ──
  const hitEdge = avgHit - BREAKEVEN;
  setNum('mhHitRate', `${avgHit}%`);
  setMeter('mhHitFill', avgHit);
  setTileStatus('mhTileHit', hitEdge >= 3 ? 'good' : hitEdge >= -2 ? 'warn' : 'bad');
  setText('mhHitTrend', `${hitEdge >= 0 ? '+' : ''}${hitEdge.toFixed(1)} pts vs 52.4% breakeven`);

  // ── Tile 2: Top Edge — sign-colored (the best actionable EV on the slate) ──
  if (topEdge) {
    const sign = topEdge.ev >= 0 ? '+' : '';
    setNum('mhTopEdge', `${sign}${topEdge.ev}%`);
    setText('mhTopEdgeTrend', `${topEdge.name} · ${topEdge.source.toUpperCase()}-${topEdge.dir.toUpperCase()}`);
    setTileStatus('mhTileEdge', topEdge.ev > 0 ? 'good' : topEdge.ev < 0 ? 'bad' : 'warn');
  } else {
    setText('mhTopEdge', '--');
    setText('mhTopEdgeTrend', 'No actionable edges');
    setTileStatus('mhTileEdge', null);
  }

  // ── Tile 3: Actionable Leans — coverage fill over the visible slate ──
  const slateSize = allFighters.length || leans.length;
  setNum('mhCoverage', `${leans.length}`);
  setMeter('mhCoverageFill', slateSize ? (leans.length / slateSize) * 100 : 0);
  setTileStatus('mhTileCov', 'info');
  setText('mhCoverageTrend', `of ${slateSize} fighters with leans`);

  void renderLearningDiagnosticsWidget();
}

async function renderLearningDiagnosticsWidget(): Promise<void> {
  const setText = (id: string, value: string): void => {
    const el = document.getElementById(id);
    if (el) el.textContent = value;
  };
  const setHtml = (id: string, value: string): void => {
    const el = document.getElementById(id);
    if (el) el.innerHTML = value;
  };
  const escLd = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  // Directive line: verb chip (▲ LEAN INTO green / ▼ FADE red) + target text.
  // The target inherits its container's styling (gold headline in the title
  // slot, muted meta in the fade slot) so only the verb becomes a badge.
  // GLOW-UP 199: the directive now names its own matches on tonight's card and
  // links to them. Without the count it was advice with no addressee.
  const directiveHtml = (
    verb: 'lean' | 'fade',
    target: string,
    m: { full: number; sideOnly: number } = { full: 0, sideOnly: 0 },
    sideLabel = '',
  ): string => {
    const head = `<span class="ld-chip ld-chip-${verb}">${verb === 'lean' ? '▲ LEAN INTO' : '▼ FADE'}</span><span class="ld-target">${escLd(target)}</span>`;
    if (m.full > 0) {
      return head + `<button class="ld-matches ld-matches-${verb}" data-ld-match="${verb}" title="${m.full} fighter(s) on this card carry this exact pattern — click to filter the board to them">${m.full} on this card →</button>`;
    }
    // Say WHY it's zero: nobody on that side at all, vs. several but untagged.
    const why = m.sideOnly > 0
      ? `${m.sideOnly} fighter(s) lean ${escLd(sideLabel)} on this card, but none carry the "${escLd(target.split('·').pop()?.trim() || '')}" tag yet — lines are still filling in.`
      : `No fighter on this card leans ${escLd(sideLabel)} at all.`;
    const short = m.sideOnly > 0 ? `0 of ${m.sideOnly} ${escLd(sideLabel)}` : 'none on this card';
    return head + `<span class="ld-matches ld-matches-none" title="${why}">${short}</span>`;
  };
  // Footer becomes stat chips instead of one gray string. SS/FP are market
  // over-rates (share of resolved props that went OVER), not model accuracy —
  // the titles say so to head off misreading.
  const footerHtml = (resolved: number, ss: string, fp: string, top: string | null, note?: string): string => [
    `<span class="ld-fchip ld-fchip-n">${resolved} resolved</span>`,
    `<span class="ld-fchip ld-fchip-ss" title="Share of resolved SS props that went OVER — market over-rate, not model accuracy">SS ${ss}</span>`,
    `<span class="ld-fchip ld-fchip-fp" title="Share of resolved FP props that went OVER — market over-rate, not model accuracy">FP ${fp}</span>`,
    top ? `<span class="ld-fchip ld-fchip-top" title="Strongest archive pattern right now">★ ${escLd(top)}</span>` : '',
    note ? `<span class="ld-fchip ld-fchip-note">${escLd(note)}</span>` : '',
  ].filter(Boolean).join('');
  const hasWidget = !!document.getElementById('learningDiagnosticsWidget');
  if (!hasWidget) return;

  // Load data FIRST, then update DOM — avoids "0 resolved" flash on tab switches
  try {
    const archivePayload = await storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY]);
    const allRowsRaw = archivePayload[STORAGE_PROP_ARCHIVE_KEY];
    const allRows = Array.isArray(allRowsRaw) ? (allRowsRaw as PropArchiveRecord[]) : [];
    if (!allRows.length) return;

    const londonTs = Date.parse(UFC_LONDON_CUTOFF_ISO);
    const nowTs = Date.now();
    const resolvedRows = allRows.filter((row) => {
      const ts = Date.parse(row.date);
      const line = Number(row.line);
      const result = Number(row.result);
      return Number.isFinite(ts)
        && ts >= londonTs
        && ts <= nowTs
        && Number.isFinite(line)
        && Number.isFinite(result);
    });

    if (!resolvedRows.length) {
      setText('ldResolved', '0 resolved');
      setText('ldCoverage', 'No settled outcomes yet');
      setText('ldMarketAcc', 'SS --% · FP --%');
      setText('ldMarketAccMeta', 'Waiting for resolved results');
      setText('ldPatternWin', 'Top hit tag: --');
      setText('ldPatternMiss', 'Top miss tag: --');
      setText('ldDrilldownTitle', 'No drilldown yet');
      setText('ldDrilldownMeta', 'Need resolved outcomes');
      setText('ldDrilldownBody', 'No settled picks yet.');
      setText('ldFooterSummary', '0 resolved · waiting for settled outcomes');
      return;
    }

    const fighterCount = new Set(
      resolvedRows
        .map((row) => normalizeName(row.fighter)?.toLowerCase())
        .filter((name): name is string => !!name)
    ).size;
    const eventCount = new Set(
      resolvedRows
        .map((row) => String(row.event || '').trim())
        .filter((name) => !!name)
    ).size;
    setText('ldResolved', `${resolvedRows.length} resolved`);
    const MIN_CALIBRATION_EVENTS = 6;
    const calibNote = eventCount >= MIN_CALIBRATION_EVENTS
      ? `(archive window)`
      : `(archive window · ${MIN_CALIBRATION_EVENTS - eventCount} more event${MIN_CALIBRATION_EVENTS - eventCount === 1 ? '' : 's'} to unlock calibration)`;
    setText('ldCoverage', `${fighterCount} fighters across ${eventCount} event${eventCount === 1 ? '' : 's'} ${calibNote}`);

    const computeOverRate = (rows: PropArchiveRecord[]): { hits: number; total: number; pct: number | null } => {
      let hits = 0;
      let total = 0;
      for (const row of rows) {
        const line = Number(row.line);
        const result = Number(row.result);
        if (!Number.isFinite(line) || !Number.isFinite(result) || result === line) continue;
        total += 1;
        if (result > line) hits += 1;
      }
      return { hits, total, pct: total ? Math.round((hits / total) * 100) : null };
    };

    const ssStats = computeOverRate(resolvedRows.filter((row) => String(row.propType) === 'SS'));
    const fpStats = computeOverRate(resolvedRows.filter((row) => String(row.propType) === 'Fantasy' || String(row.propType) === 'Fantasy_PP'));
    const tdStats = computeOverRate(resolvedRows.filter((row) => String(row.propType) === 'TD'));
    const ftStats = computeOverRate(resolvedRows.filter((row) => String(row.propType) === 'FightTime'));
    const ssLabel = ssStats.pct == null ? '--%' : `${ssStats.pct}%`;
    const fpLabel = fpStats.pct == null ? '--%' : `${fpStats.pct}%`;
    const tdLabel = tdStats.pct == null ? '--%' : `${tdStats.pct}%`;
    const ftLabel = ftStats.pct == null ? '--%' : `${ftStats.pct}%`;
    setText('ldMarketAcc', `SS ${ssLabel} · FP ${fpLabel}`);
    const tdFtMeta = [
      tdStats.total ? `TD ${tdLabel} (${tdStats.total})` : null,
      ftStats.total ? `FT ${ftLabel} (${ftStats.total})` : null,
    ].filter(Boolean).join(' · ');
    setText('ldMarketAccMeta', `${ssStats.total} SS samples · ${fpStats.total} FP samples${tdFtMeta ? ' · ' + tdFtMeta : ''}`);

    const memoryProfile = await loadConfidenceMemoryEngine();
    if (memoryProfile.topHit || memoryProfile.topMiss) {
      const topHit = memoryProfile.topHit;
      const topMiss = memoryProfile.topMiss;
      const hitLabel = topHit
        ? `${formatSourceLabel(topHit.source)} ${topHit.lean.toUpperCase()} · ${topHit.tagLabel}`
        : 'Need >=3 settled tagged rows';
      const missLabel = topMiss
        ? `${formatSourceLabel(topMiss.source)} ${topMiss.lean.toUpperCase()} · ${topMiss.tagLabel}`
        : 'Need >=3 settled tagged rows';

      if (topHit) {
        setText('ldPatternWin', `Top hit tag: ${hitLabel} (${Math.round(topHit.hitRate * 100)}% · ${topHit.total} rows)`);
      } else {
        setText('ldPatternWin', 'Top hit tag: Need >=3 settled tagged rows');
      }

      if (topMiss) {
        setText('ldPatternMiss', `Top miss tag: ${missLabel} (${Math.round(topMiss.hitRate * 100)}% · ${topMiss.total} rows)`);
      } else {
        setText('ldPatternMiss', 'Top miss tag: Need >=3 settled tagged rows');
      }

      _memoryDirectives = { lean: topHit || null, fade: topMiss || null };
      const leanMatches = countDirectiveMatches(topHit);
      const fadeMatches = countDirectiveMatches(topMiss);

      const leanSide = topHit ? `${formatSourceLabel(topHit.source)} ${topHit.lean.toUpperCase()}` : '';
      const fadeSide = topMiss ? `${formatSourceLabel(topMiss.source)} ${topMiss.lean.toUpperCase()}` : '';

      if (topHit && topMiss) {
        setHtml('ldDrilldownTitle', directiveHtml('lean', hitLabel, leanMatches, leanSide));
        setHtml('ldDrilldownMeta', directiveHtml('fade', missLabel, fadeMatches, fadeSide));
      } else if (topHit) {
        setHtml('ldDrilldownTitle', directiveHtml('lean', hitLabel, leanMatches, leanSide));
        setText('ldDrilldownMeta', 'No clear fade yet');
      } else {
        setText('ldDrilldownTitle', 'No clear lean yet');
        setHtml('ldDrilldownMeta', directiveHtml('fade', missLabel, fadeMatches, fadeSide));
      }
      // Bind after the innerHTML writes above, or the buttons don't exist yet.
      document.querySelectorAll<HTMLElement>('[data-ld-match]').forEach((btn) => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          _slateFilter = btn.dataset['ldMatch'] === 'fade' ? 'fadepattern' : 'pattern';
          (document.querySelector('.tab-btn[data-view="all"]') as HTMLElement | null)?.click();
          renderFighters();
        });
      });
      setHtml('ldDrilldownBody', `<span class="ld-evidence" title="Settled picks carrying context tags — the sample base behind this directive">📎 ${memoryProfile.taggedSamples} tagged samples</span>`);
      const topShort = topHit ? hitLabel : (topMiss ? `fade ${missLabel}` : null);
      setHtml('ldFooterSummary', footerHtml(resolvedRows.length, ssLabel, fpLabel, topShort));
      return;
    }

    type PatternBucket = { label: string; wins: number; total: number; rate: number };
    const patternMap = new Map<string, { platform: string; propType: string; overWins: number; underWins: number; total: number }>();
    for (const row of resolvedRows) {
      const line = Number(row.line);
      const result = Number(row.result);
      if (!Number.isFinite(line) || !Number.isFinite(result) || result === line) continue;
      const platform = String(row.platform || 'unknown').toLowerCase();
      const propType = String(row.propType || 'Unknown');
      const key = `${platform}|${propType}`;
      const bucket = patternMap.get(key) || { platform, propType, overWins: 0, underWins: 0, total: 0 };
      bucket.total += 1;
      if (result > line) bucket.overWins += 1;
      if (result < line) bucket.underWins += 1;
      patternMap.set(key, bucket);
    }

    const toLabel = (platform: string, propType: string, side: 'OVER' | 'UNDER'): string => {
      const p = platform && platform !== 'unknown' ? platform.toUpperCase() : 'ALL BOOKS';
      return `${p} ${propType} ${side}`;
    };

    const candidates: PatternBucket[] = [];
    for (const bucket of patternMap.values()) {
      if (bucket.total < 2) continue;
      candidates.push({
        label: toLabel(bucket.platform, bucket.propType, 'OVER'),
        wins: bucket.overWins,
        total: bucket.total,
        rate: bucket.overWins / bucket.total,
      });
      candidates.push({
        label: toLabel(bucket.platform, bucket.propType, 'UNDER'),
        wins: bucket.underWins,
        total: bucket.total,
        rate: bucket.underWins / bucket.total,
      });
    }

    if (!candidates.length) {
      setText('ldPatternWin', 'Top hit tag: Need >=2 settled rows per tag');
      setText('ldPatternMiss', 'Top miss tag: Need >=2 settled rows per tag');
      setText('ldDrilldownTitle', 'Not enough pattern samples yet');
      setText('ldDrilldownMeta', `${resolvedRows.length} resolved rows captured`);
      setText('ldDrilldownBody', 'Keep grading events to unlock stronger tag diagnostics.');
      setHtml('ldFooterSummary', footerHtml(resolvedRows.length, ssLabel, fpLabel, null, 'keep grading to unlock patterns'));
      return;
    }

    const topHit = [...candidates].sort((a, b) => b.rate - a.rate || b.total - a.total)[0];
    const topMiss = [...candidates].sort((a, b) => a.rate - b.rate || b.total - a.total)[0];
    const hitPct = Math.round(topHit.rate * 100);
    const missPct = Math.round(topMiss.rate * 100);

    setText('ldPatternWin', `Top hit tag: ${topHit.label} (${hitPct}% · ${topHit.wins}/${topHit.total})`);
    setText('ldPatternMiss', `Top miss tag: ${topMiss.label} (${missPct}% · ${topMiss.wins}/${topMiss.total})`);
    setHtml('ldDrilldownTitle', directiveHtml('lean', topHit.label));
    setHtml('ldDrilldownMeta', directiveHtml('fade', topMiss.label));
    setText(
      'ldDrilldownBody',
      missPct <= 45
        ? `${topMiss.label} hits only ${missPct}% on ${topMiss.total} rows — strong fade.`
        : `${topMiss.label} hits ${missPct}% on ${topMiss.total} rows — soft fade.`
    );
    setHtml('ldFooterSummary', footerHtml(resolvedRows.length, ssLabel, fpLabel, topHit.label));
  } catch (e) {
    debugLog(`learning diagnostics render failed: ${(e as Error).message}`);
  }
}

function normalizeArchivePlatformLabel(label: string): string | null {
  const lower = label.trim().toLowerCase();
  if (!lower || lower === '—') return null;
  if (lower.startsWith('pick6')) return 'pick6';
  if (lower.startsWith('underdog')) return 'underdog';
  if (lower.startsWith('prizepicks')) return 'prizepicks';
  if (lower.startsWith('betr')) return 'betr';
  if (lower.startsWith('dk')) return 'draftkings_sportsbook';
  return null;
}

// ── BOOK COLORS ───────────────────────────────────────────────────────────
// One palette for every place multiple books are plotted together (line
// timeline sparklines, archive platform-bias charts). There were THREE
// contradictory sets before GLOW-UP 185 — Pick6 was blue in the chip rail, teal
// in the archive dashboard and cyan in the timeline; Underdog was purple in one
// and GREEN in two others, colliding with green=direction.
//
// Book color is identity, and only valid where no stat axis competes: on the
// fighter board the stat owns the hue and a book is named by its text tag.
// KEEP IN SYNC with the --book-* custom properties in analyzer.html.
// Keys match the line-history platform keys ('betr', not 'btr') — those come
// straight from Object.keys(point.v) in line_history_v1.
const BOOK_COLORS: Record<string, string> = {
  p6:   '#4a9eff',
  ud:   '#b98bff',
  pp:   '#ff7ac8',
  betr: '#ff9f45',
  dk:   '#7de0ff',
};

/** GLOW-UP 188: does a pick's own projection sit on the far side of its line
 *  from the lean it supports?
 *
 *  Not a model error. The projection-vs-line term is capped at ±2.5 in a score
 *  that also weighs hit rate, opponent-allowed, style, venue and archive — so
 *  history and matchup can legitimately outvote the projection. But the row
 *  renders "SS UNDER 28.5 (proj 43.0)", putting the side directly beside a
 *  number arguing the other way, and nothing said so. Surfaced on the row for
 *  the same reason LEAN ✓ · VALUE ✗ exists: two numbers that disagree should
 *  say they disagree rather than let the reader assume one justifies the other.
 *
 *  Parses the DISPLAYED reason on purpose — the claim being checked is that the
 *  row as shown is self-consistent. */
// GLOW-UP 199 L2 — takes the projection as a NUMBER (from the lean's own `avg`) and
// only falls back to scraping the verdict prose when that's missing.
//
// It used to be prose-only, with a pattern anchored to the STAT verdict format
// ("SS OVER 51.5 (proj 69.3) — …"). FP leans render a different shape
// ("LEAN OVER BTR 102.5 (avg 78.8) — Proj FP (75.1 …) is 27.4 pts BELOW the line"),
// so the regex never matched and the ⚠ PROJ SAYS caution was silently absent on every
// FP pick — including ones whose own text said the projection sat 27 points the wrong
// side of the line. FP is also what actually gets placed, so this was the worst place
// to lose the warning. Now that calcLean exposes `avg`, the check is arithmetic.
/** GLOW-UP 296 — smallest projection-vs-line gap worth flagging. Matches the ±2.5
 *  cap on how much projection-vs-line can move the lean score: below it the
 *  disagreement cannot fully express itself in the number either. */
const PROJ_CONFLICT_MIN_GAP = 2.5;

/**
 * PERF — group archive rows by event ONCE per scope.
 *
 * Eight sites ran the identical `allRows.filter(r => eventDedupeKey(r.event) === key)`,
 * each a full scan of a 38,689-row archive calling a regex on every row, and every one
 * sat inside a `for (const snap of aiSnapshots)` loop of up to 80 snapshots — roughly
 * 3.1M eventDedupeKey calls per site. Same class of cost as the resolveVsArchive scan,
 * spread across the rest of the Archive render.
 *
 * Lazy, so a view that never asks for an event's rows pays nothing. One instance per
 * `allRows` scope, because the archive is re-read in several of them.
 *
 * Returns the SHARED array rather than a copy — verified no caller mutates it (they
 * only .find/.filter over it). If that ever changes, copy HERE rather than at the call
 * sites, or the sharing becomes a very quiet bug.
 */
/**
 * Collapse the DAILY snapshot history to one synthetic snapshot per event.
 *
 * persistAiLeanSnapshot keys on eventName + eventDate, and eventDate falls back to
 * TODAY, so a new snapshot is stored every calendar day the board is open. Measured on
 * the live store: 80 snapshots across 14 events - McGregor vs Holloway 2 alone holds
 * eleven, one per day from 06-30 to 07-11.
 *
 * Every aggregate panel iterated all 80 and counted each pick once per day it survived.
 * A pick flagged eleven days out scored eleven times; one added on fight day scored once.
 * That is not a sample, it is a weighting by how early the line posted - and it inflated
 * FP by 3.06x and SS by 20.58x. It also fed initRecalibrationMap, so it moved displayed
 * confidence, not just the readouts.
 *
 * Collapsed per event and then per fighter+stat, because the same pick recurs across days
 * (often at a different line, sometimes in a different direction as the board moved).
 *
 * @param prefer "latest" keeps each pick as it FINALLY stood - the version you would have
 *   acted on - and is right for accuracy, grading and calibration. "earliest" keeps the
 *   first time the model flagged it, which is the only reading that makes CLV mean
 *   anything: measured against the latest snapshot the entry line IS the close, and the
 *   number collapses to zero by construction.
 */
function collapseSnapshotsByEvent(
  snaps: Array<Record<string, any>>,
  keyOf: (event: string) => string,
  prefer: 'latest' | 'earliest',
): Array<Record<string, any>> {
  // capturedAt is an ISO string, so lexical order is chronological. A snapshot without
  // one sorts to the front of neither pass rather than silently winning the pick.
  const ordered = [...snaps].sort((a, b) => {
    const ta = String(a?.capturedAt || '');
    const tb = String(b?.capturedAt || '');
    if (!ta || !tb) return ta ? -1 : tb ? 1 : 0;
    return prefer === 'latest' ? tb.localeCompare(ta) : ta.localeCompare(tb);
  });
  const byEvent = new Map<string, { base: Record<string, any>; picks: Map<string, any> }>();
  for (const snap of ordered) {
    const key = keyOf(String(snap?.event || ''));
    if (!key) continue;
    let entry = byEvent.get(key);
    if (!entry) { entry = { base: snap, picks: new Map() }; byEvent.set(key, entry); }
    for (const pick of (snap?.picks ?? []) as Array<Record<string, any>>) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      if (!fighter) continue;
      const pk = fighter + '|' + String(pick?.source || 'fp');
      if (entry.picks.has(pk)) continue; // first in the preferred order wins
      entry.picks.set(pk, pick);
    }
  }
  return Array.from(byEvent.values()).map(e => ({ ...e.base, picks: Array.from(e.picks.values()) }));
}

function makeRowsByEvent(
  rows: PropArchiveRecord[],
  keyOf: (event: string) => string,
): (key: string) => PropArchiveRecord[] {
  let idx: Map<string, PropArchiveRecord[]> | null = null;
  return (key: string): PropArchiveRecord[] => {
    if (!idx) {
      idx = new Map<string, PropArchiveRecord[]>();
      for (const r of rows) {
        const k = keyOf(r.event || '');
        const list = idx.get(k);
        if (list) list.push(r); else idx.set(k, [r]);
      }
    }
    return idx.get(key) || [];
  };
}

function projOpposesLean(
  reason: string,
  side: string | null | undefined,
  displayedLine: number | null,
  projValue?: number | null,
): { proj: number; gap: number; implies: 'OVER' | 'UNDER' } | null {
  if (displayedLine == null || (side !== 'over' && side !== 'under')) return null;
  let proj: number | null = (typeof projValue === 'number' && Number.isFinite(projValue)) ? projValue : null;
  if (proj == null) {
    // Legacy path — leans that still don't carry a numeric projection.
    const m = reason.match(/^(?:R1 SS|SS|TD|FT|FP|CTRL)\s+(?:OVER|UNDER)\s+[\d.]+m?\s+\((?:proj|avg)\s+([\d.]+)m?\)/i);
    if (!m) return null;
    proj = parseFloat(m[1]);
  }
  if (proj == null || !Number.isFinite(proj)) return null;
  const opposes = side === 'over' ? proj < displayedLine : proj > displayedLine;
  if (!opposes) return null;
  const gap = Math.abs(proj - displayedLine);
  // ── GLOW-UP 296 · a caveat carried by half a column is not a caveat ───────
  // This fired on ANY opposition, however small, so ⚠ PROJ SAYS UNDER landed on
  // four of eight overs — and Hernandez, whose projection sits 25.3 under his
  // line, flagged identically to Padilla, whose own verdict says "essentially at
  // the line". A projection a point off the line is agreement with rounding on it.
  //
  // 2.5 is not a taste threshold: projection-vs-line contributes at most ±2.5 to
  // the lean score (the cap the tooltip already cites, and the reason a
  // "backwards" pick is not a bug). A gap the score itself cannot fully express
  // is not one worth stopping the reader for.
  if (gap < PROJ_CONFLICT_MIN_GAP) return null;
  return { proj, gap, implies: proj > displayedLine ? 'OVER' : 'UNDER' };
}

// Stat labels for an EffectiveLean's _source. The "Lean Analysis" panel renders
// getEffectiveLean(), which is whichever stat is that fighter's strongest signal
// — so its title was wrong whenever that wasn't FP. Mid-week, with no FP lines
// posted yet, every card read "Lean Analysis (FP)" over an SS verdict.
const EFFECTIVE_LEAN_STAT_LABEL: Record<string, string> = {
  fp: 'FP', ss: 'SS', ss_r1: 'R1 SS', td: 'TD', ft: 'FT', ctrl: 'CTRL', kd: 'KD',
};

// ── STRUCTURED LEAN FACTORS ───────────────────────────────────────────────
// Classifies a lean reason's prose into one scannable keyword. Hoisted out of
// renderBestPicks (GLOW-UP 162) so the fighter-card stat panels classify with
// the SAME map — two copies would drift and the same reason would read as
// different factors in different places.
function leanFactorLabel(text: string): string {
  const s = (text || '').toLowerCase();
  if (/archive|settled sample/.test(s)) return 'ARCHIVE';
  if (/duration|market ~|round/.test(s)) return 'DURATION';
  if (/opp allows|opponent/.test(s)) return 'OPPONENT';
  if (/platform-aware|scoring profile|book/.test(s)) return 'BOOKS';
  if (/consensus/.test(s)) return 'CONSENSUS';
  if (/news|injur|withdraw/.test(s)) return 'NEWS';
  if (/weight/.test(s)) return 'WEIGHT';
  if (/cage/.test(s)) return 'CAGE';
  if (/volatil|variance/.test(s)) return 'VOLATILITY';
  if (/diverg|disagree|dissent/.test(s)) return 'LINE SPLIT';
  if (/finish|\bko\b|\bsub\b/.test(s)) return 'FINISH';
  if (/last \d|recent|trend|streak|form/.test(s)) return 'FORM';
  if (/style|grappl|strik|wrestl/.test(s)) return 'STYLE';
  if (/memory|recalibrat|calibrat/.test(s)) return 'CALIBRATION';
  if (/proj|edges the line|above the line|below the line|\bavg\b/.test(s)) return 'PROJECTION';
  return 'MODEL';
}

/** Does this reason argue FOR or AGAINST the lean it belongs to?
 *
 *  LeanReason.icon is DIRECTIONAL, not judgemental: 'pos' means "pushes the
 *  number up", 'neg' means "pushes it down" — which is why the FP panel builds
 *  its UNDER drivers out of riskReasons ("risks against OVER are pros for
 *  UNDER"). Rendering the raw icon as ✓/✗ therefore inverts every UNDER pick:
 *  the reasons driving it all show as ✗. Resolve against the direction instead. */
function factorPolarity(icon: string | undefined, leanDir: string | null | undefined): 'sup' | 'opp' | 'neu' {
  if (icon !== 'pos' && icon !== 'neg') return 'neu';
  if (leanDir === 'over')  return icon === 'pos' ? 'sup' : 'opp';
  if (leanDir === 'under') return icon === 'neg' ? 'sup' : 'opp';
  return 'neu';   // push / no lean — nothing to be for or against
}

/** One ✓/✗ factor chip, polarity resolved against the lean direction. */
function factorChipHtml(r: LeanReason, leanDir: string | null | undefined, cls: string): string {
  const pol = factorPolarity(r.icon, leanDir);
  const glyph = pol === 'sup' ? '✓' : pol === 'opp' ? '✗' : '·';
  const dirWord = pol === 'sup' ? 'Supports' : pol === 'opp' ? 'Argues against' : 'Context for';
  const tip = `${dirWord} this lean — ${(r.text || '')}`.replace(/"/g, '&quot;');
  return `<span class="${cls} ${cls}-${pol}" title="${tip}">${glyph} ${leanFactorLabel(r.text || '')}</span>`;
}

/** First `max` reasons, one per distinct factor label — the ranked stack already
 *  puts the strongest first, so dedupe keeps the best instance of each. */
function pickDistinctFactors(reasons: LeanReason[] | undefined, max: number): LeanReason[] {
  const seen = new Set<string>();
  return (reasons || []).filter(r => {
    const lbl = leanFactorLabel(r.text || '');
    if (seen.has(lbl)) return false;
    seen.add(lbl);
    return true;
  }).slice(0, max);
}

/** ✓/✗ factor chips + the full prose rationale folded behind a native <details>.
 *  <details> deliberately over a JS accordion: renderFighters() rebuilds these
 *  rows constantly and there are no handlers to re-bind after each render. */
function buildLeanFactorBlock(reasons: LeanReason[] | undefined, leanDir: string | null | undefined, chipClass = 'lean-factor'): string {
  const all = reasons || [];
  if (!all.length) return '';
  const factors = pickDistinctFactors(all, 5);
  // Prose keeps the DIRECTIONAL arrows (↑ up / ↓ down) — that's what the raw
  // reason text describes. Only the chips speak in for/against terms.
  const proseRows = all.map(r =>
    `<div class="lean-point"><span class="lean-point-icon ${r.icon === 'pos' ? 'pos' : r.icon === 'neg' ? 'neg' : ''}">${r.icon === 'pos' ? '↑' : r.icon === 'neg' ? '↓' : '→'}</span><span>${r.text}</span></div>`
  ).join('');
  // One factor is not a summary — show the prose plainly instead of hiding a
  // single line behind a disclosure that costs a click to read.
  if (factors.length < 2) return `<div class="lean-reason">${proseRows}</div>`;
  const chips = factors.map(r => factorChipHtml(r, leanDir, chipClass)).join('');
  return `<div class="lean-factors">${chips}</div>
    <details class="lean-prose"><summary>Full rationale · ${all.length} point${all.length === 1 ? '' : 's'}</summary><div class="lean-reason">${proseRows}</div></details>`;
}

function renderBestPicks(container: HTMLElement, renderSeq = 0): Promise<void> {
  return (async () => {
  const mySeq = renderSeq;
  if (!allFighters.length) {
    container.innerHTML = '<div class="inline-empty-msg">No fighter data loaded yet</div>';
    renderModelHealthWidget();
    return;
  }
  const visibleFighters = applySourceVisibilityFilter(allFighters);
  if (!visibleFighters.length) {
    container.innerHTML = '<div class="inline-empty-msg">No fighters match selected source filters</div>';
    renderModelHealthWidget();
    return;
  }

  const archivePayload = await storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY, STORAGE_BEST_PICKS_PLACED_KEY]);
  if (mySeq !== bestPicksRenderSeq) return; // a newer render started while we awaited storage — bail

  // GLOW-UP 170: hydrate placed records for the current event — storage is
  // the source of truth, rebuilt every render so a second analyzer tab or a
  // reload can never show stale placed state.
  // GLOW-UP 176: same payload also feeds personal calibration — your settled
  // record per stat-family + direction across ALL stored events (persisted
  // outcomes only, so no archive re-resolve on the Best Picks render path).
  const bpPersonalRecord = new Map<string, { hits: number; total: number }>();
  {
    const evKey = bestPicksEventKey();
    const placedRaw = archivePayload[STORAGE_BEST_PICKS_PLACED_KEY];
    const evMap = placedRaw && typeof placedRaw === 'object' && !Array.isArray(placedRaw)
      ? ((placedRaw as Record<string, unknown>)[evKey] as Record<string, BestPicksPlacedRecord> | undefined)
      : undefined;
    bestPicksPlaced.clear();
    if (evMap && typeof evMap === 'object') {
      for (const [k, v] of Object.entries(evMap)) {
        if (v && typeof v === 'object') bestPicksPlaced.set(k, v);
      }
    }
    for (const [k, v] of aggregatePlacedPersonalRecord(placedRaw)) bpPersonalRecord.set(k, v);
  }
  const archiveRowsRaw = archivePayload[STORAGE_PROP_ARCHIVE_KEY];
  const archiveRows = Array.isArray(archiveRowsRaw) ? (archiveRowsRaw as PropArchiveRecord[]) : [];
  const londonTs = Date.parse(UFC_LONDON_CUTOFF_ISO);
  const roster = new Set(
    visibleFighters
      .map((f) => normalizeName(f.name)?.toLowerCase())
      .filter((name): name is string => !!name)
  );
  const recentResolvedRows = archiveRows.filter((row) => {
    const fighter = normalizeName(row.fighter)?.toLowerCase();
    const ts = Date.parse(row.date);
    return !!fighter
      && roster.has(fighter)
      && Number.isFinite(Number(row.line))
      && Number.isFinite(Number(row.result))
      && Number.isFinite(ts)
      && ts >= londonTs;
  });

  const bestPickConfidenceCache = new Map<string, number>();
  const bestPickReasonCache = new Map<string, string | null>();
  // GLOW-UP 187 (L2): the archive adjustment is keyed by (propType, side, book)
  // — NOT by fighter — so every SS-over-on-Pick6 pick produced a byte-identical
  // sentence. Kept structured so the section header can state it once instead of
  // each row repeating it.
  interface BestPickArchiveMeta { propType: string; lean: string; platform: string; pct: number; total: number; dir: 'up' | 'down' }
  const bestPickArchiveMetaCache = new Map<string, BestPickArchiveMeta | null>();
  const bestPickLeanCache = new Map<string, EffectiveLean>();

  // Best Picks lookups can target a specific book via the optional `platform`
  // arg — used when a candidate carries `_platform` (e.g., a PrizePicks-specific
  // FP candidate). Without it, falls back to the user's active-platform priority.
  const lineForLeanSource = (f: AnalyzerFighter, source: EffectiveLean['_source'], platform?: SourcePlatformKey): number | null => {
    if (source === 'fp') {
      if (platform === 'pick6') return f.line_p6 ?? null;
      if (platform === 'underdog') return f.line_ud ?? null;
      if (platform === 'prizepicks') return f.line_pp ?? null;
      if (platform === 'betr') return f.line_betr ?? null;
      return activePlatformLine(f);
    }
    if (source === 'ss') {
      if (platform === 'pick6') return f.line_p6_ss ?? null;
      if (platform === 'underdog') return f.line_ud_ss ?? null;
      if (platform === 'prizepicks') return f.line_pp_ss ?? null;
      if (platform === 'betr') return f.line_betr_ss ?? null;
      if (platform === 'draftkings_sportsbook') return f.line_dk_ss ?? null;
      if (currentPlatform === 'pick6') return f.line_p6_ss ?? f.line_ud_ss ?? f.line_pp_ss ?? f.line_betr_ss ?? f.line_dk_ss ?? null;
      if (currentPlatform === 'underdog') return f.line_ud_ss ?? f.line_p6_ss ?? f.line_pp_ss ?? f.line_betr_ss ?? f.line_dk_ss ?? null;
      if (currentPlatform === 'prizepicks') return f.line_pp_ss ?? f.line_p6_ss ?? f.line_ud_ss ?? f.line_betr_ss ?? f.line_dk_ss ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_ss ?? f.line_p6_ss ?? f.line_ud_ss ?? f.line_pp_ss ?? f.line_betr_ss ?? null;
      return f.line_betr_ss ?? f.line_p6_ss ?? f.line_ud_ss ?? f.line_pp_ss ?? f.line_dk_ss ?? null;
    }
    if (source === 'ss_r1') {
      // R1 SS is offered by PrizePicks, Underdog, and DK Sportsbook (added ~07-09).
      // When a specific book is requested (e.g. bestSideLineForPick walking all books),
      // return null for any platform that doesn't carry the prop so no phantom
      // candidates are created.
      if (platform) {
        if (platform === 'prizepicks') return f.line_pp_ss_r1 ?? null;
        if (platform === 'underdog') return f.line_ud_ss_r1 ?? null;
        if (platform === 'draftkings_sportsbook') return f.line_dk_ss_r1 ?? null;
        return null;
      }
      if (currentPlatform === 'underdog') return f.line_ud_ss_r1 ?? f.line_pp_ss_r1 ?? f.line_dk_ss_r1 ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_ss_r1 ?? f.line_pp_ss_r1 ?? f.line_ud_ss_r1 ?? null;
      return f.line_pp_ss_r1 ?? f.line_ud_ss_r1 ?? f.line_dk_ss_r1 ?? null;
    }
    if (source === 'kd') {
      // Knockdowns are PrizePicks-only — null for every other book so no phantom
      // candidates get created when a specific platform is requested.
      if (platform) return platform === 'prizepicks' ? (f.line_pp_kd ?? null) : null;
      return f.line_pp_kd ?? null;
    }
    if (source === 'td') {
      if (platform === 'pick6') return f.line_p6_td ?? null;
      if (platform === 'underdog') return f.line_ud_td ?? null;
      if (platform === 'prizepicks') return f.line_pp_td ?? null;
      if (platform === 'betr') return f.line_betr_td ?? null;
      if (platform === 'draftkings_sportsbook') return f.line_dk_td ?? null;
      if (currentPlatform === 'pick6') return f.line_p6_td ?? f.line_ud_td ?? f.line_pp_td ?? f.line_betr_td ?? f.line_dk_td ?? null;
      if (currentPlatform === 'underdog') return f.line_ud_td ?? f.line_p6_td ?? f.line_pp_td ?? f.line_betr_td ?? f.line_dk_td ?? null;
      if (currentPlatform === 'prizepicks') return f.line_pp_td ?? f.line_p6_td ?? f.line_ud_td ?? f.line_betr_td ?? f.line_dk_td ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_td ?? f.line_p6_td ?? f.line_ud_td ?? f.line_pp_td ?? f.line_betr_td ?? null;
      return f.line_betr_td ?? f.line_p6_td ?? f.line_ud_td ?? f.line_pp_td ?? f.line_dk_td ?? null;
    }
    if (source === 'ft') {
      if (platform === 'pick6') return f.line_p6_ft ?? null;
      if (platform === 'underdog') return f.line_ud_ft ?? null;
      if (platform === 'prizepicks') return f.line_pp_ft ?? null;
      if (platform === 'betr') return f.line_betr_ft ?? null;
      if (platform === 'draftkings_sportsbook') return f.line_dk_ft ?? null;
      if (currentPlatform === 'pick6') return f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? null;
      if (currentPlatform === 'underdog') return f.line_ud_ft ?? f.line_p6_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? null;
      if (currentPlatform === 'prizepicks') return f.line_pp_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_betr_ft ?? f.line_dk_ft ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_betr_ft ?? null;
      return f.line_betr_ft ?? f.line_p6_ft ?? f.line_ud_ft ?? f.line_pp_ft ?? f.line_dk_ft ?? null;
    }
    // CTRL (MODEL v16). This branch did not exist, so the function fell through to
    // `return null` for control time — which silently made CTRL uncollectable as a
    // Best Picks candidate regardless of confidence (the collector guards on
    // `lineForLeanSource(f, 'ctrl') != null`). Hailey Cowan's CTRL OVER at 86% was
    // being dropped here, not out-ranked.
    if (source === 'ctrl') {
      if (platform === 'pick6') return f.line_p6_ctrl ?? null;
      if (platform === 'underdog') return f.line_ud_ctrl ?? null;
      if (platform === 'prizepicks') return f.line_pp_ctrl ?? null;
      if (platform === 'betr') return f.line_betr_ctrl ?? null;
      if (platform === 'draftkings_sportsbook') return f.line_dk_ctrl ?? null;
      if (currentPlatform === 'pick6') return f.line_p6_ctrl ?? f.line_ud_ctrl ?? f.line_pp_ctrl ?? f.line_betr_ctrl ?? f.line_dk_ctrl ?? null;
      if (currentPlatform === 'underdog') return f.line_ud_ctrl ?? f.line_p6_ctrl ?? f.line_pp_ctrl ?? f.line_betr_ctrl ?? f.line_dk_ctrl ?? null;
      if (currentPlatform === 'prizepicks') return f.line_pp_ctrl ?? f.line_p6_ctrl ?? f.line_ud_ctrl ?? f.line_betr_ctrl ?? f.line_dk_ctrl ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return f.line_dk_ctrl ?? f.line_p6_ctrl ?? f.line_ud_ctrl ?? f.line_pp_ctrl ?? f.line_betr_ctrl ?? null;
      return f.line_betr_ctrl ?? f.line_p6_ctrl ?? f.line_ud_ctrl ?? f.line_pp_ctrl ?? f.line_dk_ctrl ?? null;
    }
    return null;
  };

  // For SS/TD/FT/CTRL picks: pick the easiest line for the lean direction
  // across all books that have a value (lowest for OVER, highest for UNDER).
  // FP already runs per-book candidate generation and carries _platform on the
  // chosen candidate; FP and push/none directions short-circuit to null here.
  // SS UNDER side availability across books:
  //  • PrizePicks / Betr — both sides for EVERY fighter (favorite or underdog).
  //  • DraftKings — real sportsbook, both sides.
  //  • Pick6 — SS UNDER only for FAVORITES (underdogs are More/OVER-only).
  //  • Underdog — SS UNDER only for UNDERDOGS (favorites are Higher/OVER-only).
  const ssUnderBookOffered = (f: AnalyzerFighter, book: SourcePlatformKey): boolean => {
    // Betr reports the offered sides per prop (allowedOptions). Trust the flag when we
    // have one; fall back to permissive only for lines captured before the flags existed
    // (manual entry, or pre-auto-fetch storage).
    if (book === 'betr') return (f.betr_ss_under_avail ?? null) !== false;
    if (book === 'draftkings_sportsbook' || book === 'prizepicks') return true;
    const dog = isMoneylineUnderdog(f);
    if (book === 'underdog') return dog;
    return !dog; // pick6 → favorites only
  };

  // TD UNDER side availability per book — mirrors the authoritative gating already in
  // isCandidateUsable so bestSideLineForPick can't surface an unplaceable line:
  //  • Pick6 — TD unders are More/OVER-only by default (low takedown lines); only a
  //    positively-confirmed Less button (td_under_available === true) makes it placeable.
  //  • Underdog — records the actual offered side at ingest; a false flag means UD had the
  //    TD line but not the under side.
  //  • DraftKings — real sportsbook, posts both sides (line presence checked separately).
  //  • Betr — posts takedowns MORE-only in practice; the fetched allowedOptions confirm
  //    it per prop, so an UNDER needs a positively-confirmed Less side.
  //  • PrizePicks — pick-em book that carries both sides on the TD props it offers.
  const tdUnderBookOffered = (f: AnalyzerFighter, book: SourcePlatformKey): boolean => {
    if (book === 'pick6') return (f.td_under_available ?? null) === true;
    if (book === 'underdog') return (f.ud_td_under_avail ?? null) !== false;
    // Betr: takedowns came back MORE-only on every prop across the whole 2026-08-29
    // board. The old blanket `return true` here treated Betr like PrizePicks and would
    // have surfaced unplaceable TD unders the moment Betr takedown lines were fetched.
    if (book === 'betr') return (f.betr_td_under_avail ?? null) === true;
    return true; // draftkings_sportsbook / prizepicks
  };

  const bestSideLineForPick = (
    f: AnalyzerFighter,
    source: EffectiveLean['_source'] | undefined,
    dir: 'over' | 'under' | 'push' | 'none' | undefined
  ): { line: number | null; book: SourcePlatformKey | null } => {
    if (!source || source === 'fp' || dir !== 'over' && dir !== 'under') {
      return { line: null, book: null };
    }
    const books: SourcePlatformKey[] = ['pick6', 'underdog', 'prizepicks', 'betr', 'draftkings_sportsbook'];
    const candidates: Array<{ line: number; book: SourcePlatformKey }> = [];
    for (const b of books) {
      // For SS/TD unders, only consider books that actually offer the under side for this
      // fighter — otherwise we'd surface an unplaceable line (e.g. a non-favorite's SS under
      // on Pick6, which is OVER-only there, or a Pick6 TD under that has no Less button).
      if (dir === 'under' && source === 'ss' && !ssUnderBookOffered(f, b)) continue;
      if (dir === 'under' && source === 'td' && !tdUnderBookOffered(f, b)) continue;
      const v = lineForLeanSource(f, source, b);
      if (v != null) candidates.push({ line: v, book: b });
    }
    if (!candidates.length) return { line: null, book: null };
    candidates.sort((a, b) => dir === 'over' ? a.line - b.line : b.line - a.line);
    return { line: candidates[0].line, book: candidates[0].book };
  };

  const sourceBonus = (source: EffectiveLean['_source']): number => {
    if (source === 'ft') return 1.8;
    // R1 SS sits between full-fight stat leans and FT: it's a bounded single-round
    // market whose clean historical records are highly predictive, so it earns a
    // bonus above SS/TD but below FT.
    if (source === 'ss_r1') return 1.5;
    if (source === 'ss' || source === 'td') return 1.2;
    // KD: bounded, hit-rate-driven like R1 SS, but a knockdown is a single moment of
    // variance — keep the bonus modest so KD picks must earn their slot on confidence.
    if (source === 'kd') return 1.0;
    // CTRL (MODEL v16): explicitly zero, not an accidental fall-through. Control
    // time is the newest source on the board and has no settled track record yet,
    // so it must out-CONFIDENCE an SS/TD candidate to take the slot rather than
    // being handed a head start. Revisit once the archive carries CTRL outcomes.
    if (source === 'ctrl') return 0;
    return 0;
  };

  // Per-book FP lean: PrizePicks uses a different scoring formula, so its line
  // can't be evaluated against the P6/UD projection — calcLean must be re-run
  // with the explicit book so projection, history, and platform-tagged reasons
  // all line up. We generate one FP candidate per book that has a line; if a
  // book's lean is "none" or "push" it's filtered out and won't dilute the pool.
  const FP_BOOKS_FOR_BEST_PICKS: SourcePlatformKey[] = ['pick6', 'underdog', 'prizepicks', 'betr'];
  const computeFpLeanForBook = (f: AnalyzerFighter, platform: SourcePlatformKey): LeanResult | null => {
    const book = lineForLeanSource(f, 'fp', platform);
    if (book == null) return null;
    if (!f.db?.loaded) return null;
    const opp = f.opponent ? allFighters.find(x => x.name === f.opponent) : null;
    return calcLean(
      f.name, f.db,
      f.line_p6 ?? null, f.line_ud ?? null, f.line_pp ?? null, f.line_betr ?? null,
      f.moneyline ?? null,
      opp?.db ?? null,
      opp?.line_p6 ?? null, opp?.line_ud ?? null, opp?.line_pp ?? null, opp?.line_betr ?? null,
      opp?.moneyline ?? null,
      platform,
    );
  };

  // Chalk filter: reject sides priced > 0.667 implied probability (= worse than
  // -200 American or below 0.5x payout). User wants to avoid "to-end-inside-the-
  // distance" -300 lines and similar — they hit often but pay nothing, so even
  // a confident lean isn't actually +EV after juice. FT UNDERs are tightened
  // further (0.6 = -150) because finish-inside-distance is structurally chalk-
  // prone for power punchers and the looser threshold lets juiced FT unders slip.
  const CHALK_IMPLIED_PROB_LIMIT = 0.667;
  // FT UNDER threshold tightened to 0.55 (~-122 American). Finish-inside-distance
  // markets are structurally chalk-prone; -150 is still too juiced once the
  // model's edge gets eaten by the payout.
  const CHALK_IMPLIED_PROB_LIMIT_FT_UNDER = 0.55;
  const impliedProbInline = (odds: number | null | undefined): number | null => {
    if (odds == null || !Number.isFinite(odds)) return null;
    if (Math.abs(odds) >= 100) return odds < 0 ? Math.abs(odds) / (Math.abs(odds) + 100) : 100 / (odds + 100);
    if (odds > 0) return 1 / (1 + odds);
    return null;
  };
  const sideOddsFor = (f: AnalyzerFighter, source: LeanSource, dir: 'over' | 'under'): number | null => {
    if (source === 'ss') return dir === 'over' ? (f.ss_over_odds ?? null) : (f.ss_under_odds ?? null);
    if (source === 'td') return dir === 'over' ? (f.td_over_odds ?? null) : (f.td_under_odds ?? null);
    if (source === 'ft') return dir === 'over' ? (f.ft_over_odds ?? null) : (f.ft_under_odds ?? null);
    return null;
  };
  // UD pick-em is often one-sided. Returns true=UD offered this side, false=UD has
  // the line but didn't offer this side, null=no UD line / unknown. The merged
  // ft_under_odds field can't be used for this check because DK chalk odds will
  // overwrite it even when UD didn't offer the side.
  const udSideAvailable = (f: AnalyzerFighter, source: LeanSource, dir: 'over' | 'under'): boolean | null => {
    if (source === 'ss') return dir === 'over' ? (f.ud_ss_over_avail ?? null) : (f.ud_ss_under_avail ?? null);
    if (source === 'td') return dir === 'over' ? (f.ud_td_over_avail ?? null) : (f.ud_td_under_avail ?? null);
    if (source === 'ft') return dir === 'over' ? (f.ud_ft_over_avail ?? null) : (f.ud_ft_under_avail ?? null);
    return null;
  };
  // Pick6 SS/TD props are frequently More/OVER-only (e.g. low takedown lines) — the
  // card shows no "Less" button, so an UNDER lean is unplaceable. Captured at scrape
  // via the Less-button check. true = Less offered, false = More-only, null = unknown
  // (pre-flag / stale lines captured before this was tracked — leave alone, don't drop).
  const p6UnderAvailable = (f: AnalyzerFighter, source: LeanSource): boolean | null => {
    if (source === 'ss') return f.ss_under_available ?? null;
    if (source === 'td') return f.td_under_available ?? null;
    return null;
  };
  const isCandidateUsable = (f: AnalyzerFighter, c: EffectiveLean): boolean => {
    // FP pick-em rules judged against THIS candidate's book (Pick6/PP/Betr underdog UNDER
    // not offered; Betr underdog OVER inflated). Underdog FP unders are allowed for dogs.
    if (shouldSkipFpSideForFighter(f, c._source, c.lean as 'over' | 'under', c._platform)) return false;
    if (c._source === 'fp') {
      // Authoritative Pick6 placeability: Pick6 gives underdogs a More/OVER-only FP prop
      // (no Less button). When the scrape positively recorded no Less side for THIS book's
      // FP card, the UNDER is unplaceable on Pick6 — even when the (often-incomplete)
      // moneyline map never flagged the fighter as a dog. Scoped to the Pick6 candidate so
      // a book that does offer the under (e.g. Underdog) can still surface. null = unknown
      // (stale/pre-flag or no Pick6 FP line) → keep, relying on the moneyline rule above.
      const platform = c._platform ?? getSourceActivePlatformKey(f, 'fp');
      if (c.lean === 'under' && platform === 'pick6' && (f.fp_under_available ?? null) === false) return false;
      return true;
    }
    // R1 SS pick-em sides (PrizePicks/Underdog) have no scraped side-odds, so the
    // chalk/side-availability gates the other stats use don't apply. DK's R1 SS odds
    // (ss_r1_over_odds/ss_r1_under_odds, added ~07-09) feed EV pricing only — worthiness
    // stays enforced upstream by calcSSR1Lean's conservative confidence gating, so accept
    // any non-push R1 SS candidate that survived candidate collection.
    if (c._source === 'ss_r1') return true;
    // Knockdowns (PrizePicks-only): eligible for Best Picks ONLY when PP offers BOTH
    // More and Less (a standard projection). More-only demon/goblin KD cards carry
    // non-standard payouts, so neither direction is a normal pick-em play there —
    // per product rule, they're display-only.
    if (c._source === 'kd') return f.kd_under_available === true;
    // CTRL is OVER-only (MODEL v16). Belt-and-braces with the collector above so a
    // CTRL under can never reach the board through any other path — the Less side
    // isn't reliably offered on any book, so it would be an unenterable pick.
    // Everything below (chalk reject, per-book side availability) still applies to
    // the over.
    if (c._source === 'ctrl' && c.lean !== 'over') return false;
    const dir = c.lean as 'over' | 'under';
    const sideOdds = sideOddsFor(f, c._source, dir);
    const platform = c._platform ?? getSourceActivePlatformKey(f, c._source);
    // Per-platform side availability for Underdog: when UD shows "—" for a side,
    // we can't use the merged sideOdds field as a proxy because DK may have
    // overwritten it with chalk odds for the same prop. The ud_*_avail flags
    // are recorded at UD ingest from Underdog's actual response. Falls back to
    // the merged sideOdds null-check for stale data captured before the flags
    // were added (avail === null means the flag was never populated).
    if (platform === 'underdog') {
      const avail = udSideAvailable(f, c._source, dir);
      if (avail === false) return false;
      if (avail == null && sideOdds == null) return false;
    } else if (platform === 'draftkings_sportsbook' && sideOdds == null) {
      // DK posts both sides explicitly; null odds means the side wasn't scraped.
      return false;
    } else if (platform === 'pick6' && c._source === 'td' && dir === 'under' && p6UnderAvailable(f, 'td') !== true) {
      // Pick6 TD unders are almost always More/OVER-only (low takedown lines) and aren't
      // offered on other books either, so suppress unless a Less button was positively
      // confirmed at scrape (suppress-by-default, same rule as Pick6 CTRL).
      return false;
    }
    // SS UNDER placeability is favorite-dependent and book-specific: keep the candidate
    // only if SOME book offers the under side for this fighter (favorites → Pick6/PP/Betr,
    // underdogs → Underdog, DK → either). Drops e.g. a non-favorite whose SS line sits only
    // on Pick6 (OVER-only there); bestSideLineForPick then shows whichever book is valid.
    if (c._source === 'ss' && dir === 'under') {
      const ssBooks: SourcePlatformKey[] = ['pick6', 'underdog', 'prizepicks', 'betr', 'draftkings_sportsbook'];
      if (!ssBooks.some(b => ssUnderBookOffered(f, b) && lineForLeanSource(f, 'ss', b) != null)) return false;
    }
    // Chalk reject: implied prob > 0.667 means -200+ American — line hits often
    // but pays so little that even a strong lean isn't worth taking. FT UNDER
    // uses a tighter 0.55 threshold (~-122).
    const implied = impliedProbInline(sideOdds);
    const chalkLimit = c._source === 'ft' && dir === 'under' ? CHALK_IMPLIED_PROB_LIMIT_FT_UNDER : CHALK_IMPLIED_PROB_LIMIT;
    if (implied != null && implied > chalkLimit) return false;
    // UD pick-em FT UNDER +money disagreement: when UD prices UNDER as the
    // unlikely side (implied < 0.45 = +money), the market is contradicting our
    // strong UNDER lean by a wide margin. Historically that signals model error
    // rather than value — drop the pick rather than recommend against the book.
    if (platform === 'underdog' && c._source === 'ft' && dir === 'under' && implied != null && implied < 0.45) {
      return false;
    }
    return true;
  };

  const collectLeanCandidates = (f: AnalyzerFighter): EffectiveLean[] => {
    const candidates: EffectiveLean[] = [];
    // FP: one candidate per book that has a line. Lets PP-specific leans
    // surface even when a P6/UD line also exists for the same fighter.
    for (const book of FP_BOOKS_FOR_BEST_PICKS) {
      if (lineForLeanSource(f, 'fp', book) == null) continue;
      const lean = computeFpLeanForBook(f, book);
      if (!lean || !lean.lean || lean.lean === 'none' || lean.lean === 'push') continue;
      candidates.push({ ...lean, _source: 'fp', _label: '', _platform: book });
    }
    // SS/TD/FT: scoring is identical across books (same underlying stat).
    // Stick with the existing single-lean approach; line variance is small.
    if (f.lean_ss?.lean && f.lean_ss.lean !== 'none' && f.lean_ss.lean !== 'push' && lineForLeanSource(f, 'ss') != null) {
      candidates.push({ ...f.lean_ss, _source: 'ss', _label: ' (SS line)' });
    }
    if (f.lean_ss_r1?.lean && f.lean_ss_r1.lean !== 'none' && f.lean_ss_r1.lean !== 'push' && lineForLeanSource(f, 'ss_r1') != null) {
      candidates.push({ ...f.lean_ss_r1, _source: 'ss_r1', _label: ' (R1 SS line)' });
    }
    if (f.lean_td?.lean && f.lean_td.lean !== 'none' && f.lean_td.lean !== 'push' && lineForLeanSource(f, 'td') != null) {
      candidates.push({ ...f.lean_td, _source: 'td', _label: ' (TD line)' });
    }
    if (f.lean_ft?.lean && f.lean_ft.lean !== 'none' && f.lean_ft.lean !== 'push' && lineForLeanSource(f, 'ft') != null) {
      candidates.push({ ...f.lean_ft, _source: 'ft', _label: ' (FT line)' });
    }
    if (f.lean_kd?.lean && f.lean_kd.lean !== 'none' && f.lean_kd.lean !== 'push' && lineForLeanSource(f, 'kd') != null) {
      candidates.push({ ...f.lean_kd, _source: 'kd', _label: ' (KD line)' });
    }
    // CTRL (MODEL v16): control time was a full lean source with its own panel data
    // and line cells, but was never collected as a Best Picks candidate at all — so
    // a CTRL edge could never reach the board no matter how strong.
    // OVER-ONLY by product rule: control-time props are More-only in practice
    // (Pick6 is the primary CTRL book and gives them no Less button), so an UNDER
    // is unplaceable even when the model likes it. calcCtrlLean already suppresses
    // the under when the scraper positively confirms no Less side; this is the
    // stricter, suppress-by-default version for pick selection.
    if (f.lean_ctrl?.lean === 'over' && lineForLeanSource(f, 'ctrl') != null) {
      candidates.push({ ...f.lean_ctrl, _source: 'ctrl', _label: ' (CTRL line)' });
    }
    // Usability FIRST. Dominance below compares entry prices, and comparing an
    // unplaceable line against a placeable one would drop the only pick that could
    // actually be taken — a dog's FP UNDER is placeable on Underdog alone, so if Pick6
    // held the higher under line the pruner would keep Pick6, drop Underdog, and then
    // this filter would delete the survivor, losing the pick entirely.
    const usable = candidates.filter(c => isCandidateUsable(f, c));

    // MODEL v33 — SAME-SCALE FP DOMINANCE.
    // pick6 / underdog / betr all score fantasy points with FANTASY_SCORING, so a
    // fighter's projection is IDENTICAL across them and their lines sit on one axis.
    // A candidate on a worse line than a same-direction sibling is therefore dominated:
    // same read, worse entry. It used to be able to win anyway, because sortCandidates
    // ranks on confidence alone — Rei Tsuruya surfaced as OVER Betr 99.5 while Underdog
    // offered 88.99 on the same scale, and the row rendered "PROJ SAYS UNDER 18.7"
    // because the shared projection (92.6) sat 6.9 BELOW the displayed line, where on
    // the UD line it sat 3.6 ABOVE. Keep only the best-priced sibling per direction.
    // PrizePicks is deliberately NOT in this set: PRIZEPICKS_SCORING is a different
    // formula (sig strikes only, no control time, no quick-finish bonus), so its line is
    // not comparable and keeps its own candidate.
    const SHARED_FP_SCALE: SourcePlatformKey[] = ['pick6', 'underdog', 'betr'];
    const onSharedScale = (c: EffectiveLean): boolean =>
      c._source === 'fp' && !!c._platform && SHARED_FP_SCALE.includes(c._platform);
    for (const dir of ['over', 'under'] as const) {
      const sibs = usable.filter(c => onSharedScale(c) && c.lean === dir);
      if (sibs.length < 2) continue;
      let keep = sibs[0];
      let keepLine = lineForLeanSource(f, 'fp', keep._platform!);
      for (const c of sibs.slice(1)) {
        const v = lineForLeanSource(f, 'fp', c._platform!);
        if (v == null || keepLine == null) continue;
        if (dir === 'over' ? v < keepLine : v > keepLine) { keep = c; keepLine = v; }
      }
      for (const c of sibs) {
        if (c === keep) continue;
        const k = usable.indexOf(c);
        if (k >= 0) usable.splice(k, 1);
      }
      debugLog(`FP dominance: ${f.name} ${dir} — kept ${keep._platform} ${keepLine}, dropped ${sibs.length - 1} worse-priced placeable sibling(s)`);
    }

    return usable;
  };

  const sortCandidates = (candidates: EffectiveLean[]): void => {
    candidates.sort((a, b) => {
      const bScore = (b.conf || 0) + sourceBonus(b._source);
      const aScore = (a.conf || 0) + sourceBonus(a._source);
      if (bScore !== aScore) return bScore - aScore;
      return (b.ev || 0) - (a.ev || 0);
    });
  };

  const getBestPickLean = (f: AnalyzerFighter): EffectiveLean => {
    const cached = bestPickLeanCache.get(f.name);
    if (cached) return cached;

    const candidates = collectLeanCandidates(f);
    if (!candidates.length) {
      const fallback = getEffectiveLean(f);
      bestPickLeanCache.set(f.name, fallback);
      return fallback;
    }

    sortCandidates(candidates);
    const selected = candidates[0];
    bestPickLeanCache.set(f.name, selected);
    return selected;
  };

  // Direction-specific lean: best OVER or best UNDER lean for a fighter (independent columns)
  const bestPickLeanByDir = new Map<string, EffectiveLean>();
  const getBestPickLeanForDir = (f: AnalyzerFighter, dir: 'over' | 'under'): EffectiveLean | null => {
    const cacheKey = `${f.name}|${dir}`;
    const cached = bestPickLeanByDir.get(cacheKey);
    if (cached) return cached;
    const candidates = collectLeanCandidates(f).filter(c => c.lean === dir);
    if (!candidates.length) return null;
    sortCandidates(candidates);
    bestPickLeanByDir.set(cacheKey, candidates[0]);
    return candidates[0];
  };

  const formatSideOdds = (odds: number): string => {
    if (Math.abs(odds) >= 100) return odds > 0 ? `+${Math.round(odds)}` : `${Math.round(odds)}`;
    return `${odds.toFixed(2)}x`;
  };

  const impliedProbabilityFromSideOdds = (odds: number | null | undefined): number | null => {
    if (odds == null || !Number.isFinite(odds)) return null;
    // American odds branch.
    if (Math.abs(odds) >= 100) {
      if (odds < 0) return Math.abs(odds) / (Math.abs(odds) + 100);
      return 100 / (odds + 100);
    }
    // Payout multiplier branch (e.g., 0.66x means 1 stake returns 1.66 total).
    if (odds > 0) return 1 / (1 + odds);
    return null;
  };

  const getLeanSideOdds = (f: AnalyzerFighter, el: EffectiveLean): number | null => {
    if (el.lean !== 'over' && el.lean !== 'under') return null;
    if (el._source === 'ss') return el.lean === 'over' ? (f.ss_over_odds ?? null) : (f.ss_under_odds ?? null);
    if (el._source === 'td') return el.lean === 'over' ? (f.td_over_odds ?? null) : (f.td_under_odds ?? null);
    if (el._source === 'ft') return el.lean === 'over' ? (f.ft_over_odds ?? null) : (f.ft_under_odds ?? null);
    return null;
  };

  const getOddsAdjustment = (f: AnalyzerFighter, el: EffectiveLean, baseConfidence: number): { delta: number; note: string | null } => {
    const sideOdds = getLeanSideOdds(f, el);
    const implied = impliedProbabilityFromSideOdds(sideOdds);
    if (sideOdds == null || implied == null) return { delta: 0, note: null };

    const overPricedPenalty = implied >= 0.6
      ? Math.min(10, ((implied - 0.6) * 40) + Math.max(0, (80 - baseConfidence) / 12))
      : 0;
    const plusMoneyBonus = implied <= 0.45
      ? Math.min(7, ((0.45 - implied) * 28) + Math.max(0, (baseConfidence - 58) / 18))
      : 0;

    const delta = Math.round(plusMoneyBonus - overPricedPenalty);
    if (Math.abs(delta) < 2) return { delta, note: null };

    const note = delta < 0
      ? `Side price ${formatSideOdds(sideOdds)} is juiced for ${el.lean}, so confidence was trimmed.`
      : `Side price ${formatSideOdds(sideOdds)} is favorable for ${el.lean}, so confidence was boosted.`;
    return { delta, note };
  };

  const getAdjustedBestPickConfidence = (f: AnalyzerFighter): number => {
    const cacheKey = f.name;
    const cached = bestPickConfidenceCache.get(cacheKey);
    if (cached != null) return cached;

    const el = getBestPickLean(f);
    const baseConfidence = el.conf || 0;
    const propType = el._source === 'fp' ? 'Fantasy' : el._source.toUpperCase();
    // Archive lookup: validate against the book actually shown in the badge — its hit
    // rate, not the user's active platform's. FP candidates carry _platform directly;
    // SS/TD/FT show the placeable best-side book from bestSideLineForPick (e.g. a TD
    // under shown on DK must be checked against DK's archive rows, not Pick6's — Pick6
    // may not even offer that under). Falls back to the active platform label.
    const displayedBook = (el._source !== 'fp' && (el.lean === 'over' || el.lean === 'under'))
      ? bestSideLineForPick(f, el._source, el.lean).book
      : null;
    const platform = el._platform ?? displayedBook ?? normalizeArchivePlatformLabel(activePlatformLabel(f));
    const matchingRows = recentResolvedRows.filter((row) => {
      if (String(row.propType) !== propType) return false;
      if (platform && String(row.platform || '').toLowerCase() !== platform) return false;
      return true;
    });

    // FT and TD are low-sample stat types — require only 2 settled rows instead of 3
    const minSamples = (propType === 'FT' || propType === 'TD') ? 2 : 3;

    if (matchingRows.length < minSamples) {
      bestPickConfidenceCache.set(cacheKey, baseConfidence);
      bestPickReasonCache.set(cacheKey, null);
      bestPickArchiveMetaCache.set(cacheKey, null);
      return baseConfidence;
    }

    let hits = 0;
    let total = 0;
    let directionalEdgeSum = 0;
    for (const row of matchingRows) {
      const line = Number(row.line);
      const result = Number(row.result);
      if (!Number.isFinite(line) || !Number.isFinite(result) || result === line) continue;
      const directionalEdge = el.lean === 'over' ? (result - line) : (line - result);
      total += 1;
      directionalEdgeSum += directionalEdge;
      if (directionalEdge > 0) hits += 1;
    }

    if (total < minSamples) {
      bestPickConfidenceCache.set(cacheKey, baseConfidence);
      bestPickReasonCache.set(cacheKey, null);
      bestPickArchiveMetaCache.set(cacheKey, null);
      return baseConfidence;
    }

    const hitRate = hits / total;
    // Dead zone: 47–53% hit rate is statistical noise, not signal — skip adjustment entirely
    if (hitRate >= 0.47 && hitRate <= 0.53) {
      bestPickConfidenceCache.set(cacheKey, baseConfidence);
      bestPickReasonCache.set(cacheKey, null);
      bestPickArchiveMetaCache.set(cacheKey, null);
      return baseConfidence;
    }
    const avgDirectionalEdge = directionalEdgeSum / total;
    const penalty = hitRate < 0.47
      ? Math.min(18, ((0.52 - hitRate) * 42) + (avgDirectionalEdge < 0 ? Math.min(8, Math.abs(avgDirectionalEdge) / 4) : 0))
      : 0;
    const bonus = hitRate > 0.62 && avgDirectionalEdge > 0
      ? Math.min(6, ((hitRate - 0.62) * 20) + Math.min(3, avgDirectionalEdge / 8))
      : 0;
    const oddsAdjustment = getOddsAdjustment(f, el, baseConfidence);
    const adjustedConfidence = Math.round(Math.max(0, Math.min(99, baseConfidence - penalty + bonus + oddsAdjustment.delta)));

    const lowNTag = minSamples === 2 ? ' (low-n)' : '';
    let note: string | null = null;
    let meta: BestPickArchiveMeta | null = null;
    if (penalty >= 4) {
      note = `Archive check: ${propType} ${el.lean}s on ${platform || 'active book'} are ${Math.round(hitRate * 100)}% over ${total} settled samples${lowNTag}, so confidence was trimmed.`;
      meta = { propType, lean: el.lean, platform: platform || 'active book', pct: Math.round(hitRate * 100), total, dir: 'down' };
    } else if (bonus >= 3) {
      note = `Archive check: ${propType} ${el.lean}s on ${platform || 'active book'} are ${Math.round(hitRate * 100)}% over ${total} settled samples${lowNTag}, so confidence was boosted.`;
      meta = { propType, lean: el.lean, platform: platform || 'active book', pct: Math.round(hitRate * 100), total, dir: 'up' };
    }
    if (oddsAdjustment.note) {
      note = note ? `${note} ${oddsAdjustment.note}` : oddsAdjustment.note;
    }

    bestPickConfidenceCache.set(cacheKey, adjustedConfidence);
    bestPickReasonCache.set(cacheKey, note);
    bestPickArchiveMetaCache.set(cacheKey, meta);
    return adjustedConfidence;
  };

  const getBestPickArchiveNote = (f: AnalyzerFighter): string | null => {
    void getAdjustedBestPickConfidence(f);
    return bestPickReasonCache.get(f.name) ?? null;
  };
  const getBestPickArchiveMeta = (f: AnalyzerFighter): BestPickArchiveMeta | null => {
    void getAdjustedBestPickConfidence(f);
    return bestPickArchiveMetaCache.get(f.name) ?? null;
  };

  type Tier = 'High' | 'Med' | 'Low';
  const pickTier = (f: AnalyzerFighter): { label: Tier; rank: number } => {
    const el = getBestPickLean(f);
    const db = f.db;
    const line = lineForLeanSource(f, el._source, el._platform);
    const samples = db?.history?.length || 0;
    const conf = getAdjustedBestPickConfidence(f);
    const statLean = el._source === 'ss' || el._source === 'ss_r1' || el._source === 'td' || el._source === 'ft' || el._source === 'kd';
    const highConfReq = statLean ? 78 : 72;
    const highSampleReq = statLean ? 8 : 7;
    const medConfReq = statLean ? 64 : 58;
    const medSampleReq = statLean ? 5 : 4;
    if (conf >= highConfReq && samples >= highSampleReq && line != null) return { label: 'High', rank: 3 };
    if (conf >= medConfReq && samples >= medSampleReq) return { label: 'Med', rank: 2 };
    return { label: 'Low', rank: 1 };
  };

  // Correlation penalty map: same-fight pair in same section — lower-ranked fighter is demoted
  const corrPenaltyMap = new Map<string, number>();

  const bestPickSort = (a: AnalyzerFighter, b: AnalyzerFighter): number => {
    const ta = pickTier(a);
    const tb = pickTier(b);
    if (tb.rank !== ta.rank) return tb.rank - ta.rank;
    const ea = getBestPickLean(a);
    const eb = getBestPickLean(b);
    // Duration coupling demotes by 8 — meaningful but below the 10 carried by a
    // same-direction same-fight pair, which is the harder conflict.
    const adjA = getAdjustedBestPickConfidence(a) - (corrPenaltyMap.get(a.name) || 0) - (durationCoupledMap.has(a.name) ? 8 : 0);
    const adjB = getAdjustedBestPickConfidence(b) - (corrPenaltyMap.get(b.name) || 0) - (durationCoupledMap.has(b.name) ? 8 : 0);
    if (adjB !== adjA) return adjB - adjA;
    return ((eb.ev || 0) - (ea.ev || 0));
  };

  // ── Duration coupling (GLOW-UP 189) ──────────────────────────────────────
  // A volume OVER (SS/TD/CTRL) is not independent of how long the fight lasts,
  // and the opponent controls that. The existing same-fight logic only handles
  // SAME-direction pairs; opposite-direction SS was treated as the coherent
  // "A outworks B" shape. That holds when the under side is low output over a
  // full fight — it BREAKS when the under side's path is a finish, because a
  // finish suppresses both fighters' volume together.
  //
  // Live case that exposed it: Ponzinibbio SS OVER 29.5 opposite Patterson SS
  // UNDER 28.5. Patterson finishes 86% of his fights, career average 5:14, five
  // of his last seven inside 3:10. Ponzinibbio needs ~6.2 min at his 4.78
  // SS/min just to reach 29.5. Both picks can't be right: Patterson's under
  // arrives via a finish, and that finish takes Ponzinibbio under too.
  const FINISH_DRIVEN_RATE = 0.65;   // finishes ≥65% of fights
  const FINISH_DRIVEN_MINS = 7.0;    // or averages under 7 minutes
  const durationCoupledMap = new Map<string, { oppName: string; oppFinishPct: number; oppAvgMins: number | null; needMins: number | null }>();
  const isFinishDriven = (db: FighterDB | null | undefined): boolean => {
    if (!db) return false;
    return (db.finishRate ?? 0) >= FINISH_DRIVEN_RATE
        || (db.avgTimeMins != null && db.avgTimeMins <= FINISH_DRIVEN_MINS);
  };
  const buildDurationCoupling = (pool: AnalyzerFighter[]): void => {
    for (const f of pool) {
      const el = getBestPickLean(f);
      if (el.lean !== 'over') continue;
      if (el._source !== 'ss' && el._source !== 'ss_r1' && el._source !== 'td' && el._source !== 'ctrl') continue;
      const opp = f.opponent ? allFighters.find(x => x.name.toLowerCase() === f.opponent!.toLowerCase()) : null;
      if (!isFinishDriven(opp?.db)) continue;
      const line = lineForLeanSource(f, el._source, el._platform);
      // Minutes this OVER needs at the fighter's own career strike rate. Null
      // when we lack a rate — the finish-driven opponent alone still qualifies.
      const slpm = f.db?.slpm ?? null;
      const needMins = (line != null && slpm != null && slpm > 0 && (el._source === 'ss' || el._source === 'ss_r1'))
        ? line / slpm
        : null;
      const oppAvg = opp?.db?.avgTimeMins ?? null;
      // If the number is reachable well inside the opponent's typical fight,
      // duration isn't the binding constraint — don't cry wolf.
      if (needMins != null && oppAvg != null && needMins <= oppAvg * 0.8) continue;
      durationCoupledMap.set(f.name, {
        oppName: opp?.name || f.opponent || 'opponent',
        oppFinishPct: Math.round((opp?.db?.finishRate ?? 0) * 100),
        oppAvgMins: oppAvg,
        needMins,
      });
    }
  };

  // Detect same-fight pairs and penalize the lower-ranked fighter
  const buildCorrPenalties = (sorted: AnalyzerFighter[]): void => {
    const seenNames = new Map<string, string>(); // lowercase name → original
    for (const f of sorted) {
      if (!f.opponent) continue;
      const oppKey = f.opponent.toLowerCase();
      if (seenNames.has(oppKey)) {
        // f appears after its opponent in the ranked list — it's the weaker side
        corrPenaltyMap.set(f.name, 10);
      } else {
        seenNames.set(f.name.toLowerCase(), f.name);
      }
    }
  };

  // Populate each column independently: a fighter's best OVER lean goes to the
  // OVER column, and their best UNDER lean to the UNDER column.  A fighter can
  // appear on both sides when they have actionable leans in both directions.
  const allOversRaw  = visibleFighters.filter(f => {
    const el = getBestPickLeanForDir(f, 'over');
    if (!el) return false;
    // Skip Betr underdog FP OVERs — inflated +money odds, user doesn't take them.
    if (shouldSkipFpSideForFighter(f, el._source, 'over', el._platform)) return false;
    return true;
  });
  const allUndersRaw = visibleFighters.filter(f => {
    const el = getBestPickLeanForDir(f, 'under');
    if (!el) return false;
    // Drop unplaceable unders: underdogs have no UNDER side on pick-em FP props.
    if (shouldSkipFpSideForFighter(f, el._source, 'under', el._platform)) return false;
    return true;
  });

  // Temporarily override the bestPickLeanCache for sorting so confidence/tier
  // functions use the direction-specific lean when ranking each column.
  const overrideLeanForSort = (fighters: AnalyzerFighter[], dir: 'over' | 'under'): void => {
    for (const f of fighters) {
      const dirLean = getBestPickLeanForDir(f, dir);
      if (dirLean) bestPickLeanCache.set(f.name, dirLean);
    }
  };

  overrideLeanForSort(allOversRaw, 'over');
  // Clear confidence cache so it recalculates with the overridden lean
  bestPickConfidenceCache.clear();
  bestPickReasonCache.clear();
  // Order-independent, so it must be built BEFORE the first sort reads it.
  buildDurationCoupling(allOversRaw);
  const allOvers = allOversRaw.sort(bestPickSort);
  buildCorrPenalties(allOvers);
  const allOversSorted = allOvers.sort(bestPickSort);

  overrideLeanForSort(allUndersRaw, 'under');
  bestPickConfidenceCache.clear();
  bestPickReasonCache.clear();
  const allUnders = allUndersRaw.sort(bestPickSort);
  buildCorrPenalties(allUnders);
  const allUndersSorted = allUnders.sort(bestPickSort);

  // Restore each fighter's true best lean in cache for card rendering
  bestPickLeanCache.clear();
  bestPickConfidenceCache.clear();
  bestPickReasonCache.clear();

  // Drop negatively-correlated same-fight pairs.  Two layers:
  // 1. Cross-stat: if a fight has an FP pick, non-FP picks from that fight are
  //    dropped (FP captures total fight outcome).  Different non-FP stats from
  //    the same fight are also blocked (first stat seen wins).
  // 2. FP zero-sum: at most one FP pick per fight per section — both fighters
  //    going FP-OVER or FP-UNDER is contradictory.
  // Non-FP same-stat pairs (e.g. both SS-OVER) are allowed: positive
  // correlation in high-volume fights.
  const dedupeNegCorrelatedSameFight = (sorted: AnalyzerFighter[], dir: 'over'|'under', limit: number, minTarget = 0): AnalyzerFighter[] => {
    const fightHasFpPick = new Set<string>();
    for (const f of sorted) {
      const oppName = (f.opponent || '').toLowerCase();
      const fightKey = oppName ? [f.name.toLowerCase(), oppName].sort().join('|') : '';
      if (!fightKey) continue;
      const lean = getBestPickLeanForDir(f, dir);
      if (lean?._source === 'fp') fightHasFpPick.add(fightKey);
    }
    const result: AnalyzerFighter[] = [];
    const fightFirstStat = new Map<string, string>();
    const fightFpSeen = new Set<string>();
    for (const f of sorted) {
      if (result.length >= limit) break;
      const oppName = (f.opponent || '').toLowerCase();
      const fightKey = oppName ? [f.name.toLowerCase(), oppName].sort().join('|') : '';
      const lean = getBestPickLeanForDir(f, dir);
      const source = lean?._source || 'fp';
      if (fightKey) {
        if (fightHasFpPick.has(fightKey) && source !== 'fp') continue;
        const existing = fightFirstStat.get(fightKey);
        if (existing && existing !== source) continue;
        if (!existing) fightFirstStat.set(fightKey, source);
        if (source === 'fp' && fightFpSeen.has(fightKey)) continue;
        if (source === 'fp') fightFpSeen.add(fightKey);
      }
      result.push(f);
    }
    if (result.length < minTarget) {
      const have = new Set(result.map((x) => x.name.toLowerCase()));
      for (const f of sorted) {
        if (result.length >= limit) break;
        const key = f.name.toLowerCase();
        if (have.has(key)) continue;
        const oppName2 = (f.opponent || '').toLowerCase();
        const fk = oppName2 ? [key, oppName2].sort().join('|') : '';
        const lean2 = getBestPickLeanForDir(f, dir);
        const src2 = lean2?._source || 'fp';
        // Projection floor: a backfilled pick must not argue against itself —
        // its own avg/projection has to sit on the direction's side of the line.
        const line2 = getSourceActiveLine(f, src2);
        const avg2 = lean2?.avg;
        if (line2 != null && typeof avg2 === 'number' && Number.isFinite(avg2)) {
          if (dir === 'over' ? avg2 <= line2 : avg2 >= line2) continue;
        }
        if (fk && src2 === 'fp' && fightFpSeen.has(fk)) continue;
        if (fk && fightHasFpPick.has(fk) && src2 !== 'fp') continue;
        const ex = fk ? fightFirstStat.get(fk) : undefined;
        if (ex && ex !== src2) continue;
        result.push(f);
        have.add(key);
        if (fk && src2 === 'fp') fightFpSeen.add(fk);
        if (fk && !fightFirstStat.has(fk)) fightFirstStat.set(fk, src2);
      }
    }
    return result;
  };
  const overs  = dedupeNegCorrelatedSameFight(allOversSorted, 'over', 8, 7);
  const unders = dedupeNegCorrelatedSameFight(allUndersSorted, 'under', 8, 7);

  // FT exclusivity across sections: fight time is a SHARED stat — the fight
  // only has one duration. Fighter A "FT OVER 12.5" in the overs column and
  // opponent B "FT UNDER 12.5" in the unders column are contradictory (at
  // most one can cash), so keep only the higher-confidence side. Opposite-
  // direction pairs on per-fighter stats (SS/TD) are untouched — those are
  // the coherent "A outworks B" shape.
  {
    const underByName = new Map(unders.map((f) => [f.name.toLowerCase(), f] as const));
    for (const overF of [...overs]) {
      const overLean = getBestPickLeanForDir(overF, 'over');
      if (overLean?._source !== 'ft' || !overF.opponent) continue;
      const oppUnder = underByName.get(overF.opponent.toLowerCase());
      if (!oppUnder) continue;
      const underLean = getBestPickLeanForDir(oppUnder, 'under');
      if (underLean?._source !== 'ft') continue;
      const overConf = Number(overLean.conf) || 0;
      const underConf = Number(underLean.conf) || 0;
      if (overConf >= underConf) {
        unders.splice(unders.indexOf(oppUnder), 1);
        underByName.delete(oppUnder.name.toLowerCase());
        debugLog(`FT exclusivity: dropped ${oppUnder.name} FT UNDER (conf ${underConf}) — opponent ${overF.name} FT OVER stronger (conf ${overConf})`);
      } else {
        overs.splice(overs.indexOf(overF), 1);
        debugLog(`FT exclusivity: dropped ${overF.name} FT OVER (conf ${overConf}) — opponent ${oppUnder.name} FT UNDER stronger (conf ${underConf})`);
      }
    }
  }

  // Hand over the SAME direction-resolved lean the board just rendered. The snapshot
  // used to re-derive it with getEffectiveLean(), which is direction-agnostic, so a
  // fighter listed in the overs column was logged with whatever their single strongest
  // lean happened to be — frequently the UNDER, and frequently a different STAT.
  // Resolve the line and book the BOARD shows, not just the lean. persistBestPicks
  // Snapshot used to re-derive these from getSourceActiveLine/formatSourcePlatformLabel,
  // which are direction-agnostic and know nothing about which candidate won — so after
  // v33's best-line selection the log said "85.5 @Pick6" for a pick the board rendered as
  // BTR 81.5. Six of sixteen picks disagreed with their own verdict text. The learning
  // engine grades against `line`, so it was scoring numbers that were never offered.
  const snapshotEntry = (f: AnalyzerFighter, dir: 'over' | 'under') => {
    const lean = getBestPickLeanForDir(f, dir);
    const source = lean?._source || 'fp';
    // FP carries its book on the candidate (one candidate per book); the stat sources
    // resolve theirs through the same best-side helper the row renders with.
    const best = bestSideLineForPick(f, source, lean?.lean);
    const book = lean?._platform ?? best.book ?? null;
    const line = book ? lineForLeanSource(f, source, book) : (best.line ?? getSourceActiveLine(f, source));
    return { fighter: f, lean, line: line ?? getSourceActiveLine(f, source), book };
  };
  void persistBestPicksSnapshot(
    overs.map((f) => snapshotEntry(f, 'over')),
    unders.map((f) => snapshotEntry(f, 'under')),
  );

  // Flag fighters whose opponent is still in the SAME section after demotion
  const overNames = new Set(overs.map(f => f.name.toLowerCase()));
  const underNames = new Set(unders.map(f => f.name.toLowerCase()));
  const conflictFighters = new Set<string>();
  for (const f of overs)  { if (f.opponent && overNames.has(f.opponent.toLowerCase()))  conflictFighters.add(f.name); }
  for (const f of unders) { if (f.opponent && underNames.has(f.opponent.toLowerCase())) conflictFighters.add(f.name); }

  // ── GLOW-UP 167 (Best Picks level-up 1): command strip ──
  // View-only sort/filter applied AFTER the pipeline is done: candidate
  // generation, dedupe, FT exclusivity, snapshot persistence, and conflict
  // flags all see the full columns — this transform only changes what gets
  // drawn. Ranks and the #1 hero deck follow the current view order, so
  // "sort by EV" literally re-crowns the hero.
  // GLOW-UP 192: the metric now also resolves the DISPLAYED book and the caveat
  // flags, so the CLEAN filter (L2), exposure strip (L3) and BY BOOK plan (L5)
  // all read the same values the rows render — no second source of truth.
  const bpViewMetric = (f: AnalyzerFighter, dir: 'over' | 'under'): {
    src: string; ev: number | null; conf: number;
    book: SourcePlatformKey | null; line: number | null;
    projConflict: boolean; needsRounds: boolean; clean: boolean; caveats: number;
    proj: number | null; edge: number | null;
  } => {
    const el = getBestPickLeanForDir(f, dir) || getBestPickLean(f);
    const evd = computeDetailedEV(f, el);
    // Same line/book resolution the row render uses: stat picks take the
    // best-side book, FP keeps its per-book platform.
    let line = lineForLeanSource(f, el._source, el._platform);
    let book: SourcePlatformKey | undefined = el._platform;
    if (el._source !== 'fp' && (el.lean === 'over' || el.lean === 'under')) {
      const best = bestSideLineForPick(f, el._source, el.lean);
      if (best.line != null && best.book != null) { line = best.line; book = best.book; }
    }
    const reason = el.verdict || el.reasons?.[0]?.text || '';
    const projConflict = !!projOpposesLean(reason, el.lean, line, el.avg);
    // durationCoupledMap is built for the OVER pool only (a volume over is what
    // needs rounds), so this is inherently false on the unders side.
    const needsRounds = durationCoupledMap.has(f.name);
    const ev = evd ? evd.ev : null;
    // Unknown EV isn't a caveat — only a negative one is.
    const negEv = ev != null && ev < 0;
    // GLOW-UP 205 — the three caveats were OR'd into one bit, so a pick that is
    // merely -EV looked identical to one that is -EV AND arguing against its own
    // projection AND needing rounds it may not get. Fine while few picks carried
    // anything; useless once real prices land. On this card CLEAN went 7 -> 1 and
    // FLAGGED 5 -> 13 as the books posted, i.e. the "review queue" became the
    // whole board. Counting them restores the ranking the OR threw away.
    const caveats = (projConflict ? 1 : 0) + (needsRounds ? 1 : 0) + (negEv ? 1 : 0);
    const clean = caveats === 0;
    // GLOW-UP 196 L1 — the projection and its gap to the line were already computed
    // but only ever reached the UI inside prose ("edges the line by 12.1"), so rows
    // weren't numerically comparable. Signed so positive ALWAYS means favourable,
    // whichever side the pick is on, and measured against the DISPLAYED line (the
    // one you'd actually enter) rather than whichever line the lean happened to use.
    const proj = (typeof el.avg === 'number' && Number.isFinite(el.avg)) ? el.avg : null;
    const edge = (proj != null && line != null)
      ? parseFloat((el.lean === 'under' ? line - proj : proj - line).toFixed(1))
      : null;
    return {
      src: el._source || 'fp', ev, conf: Number(el.conf) || 0,
      book: book ?? getSourceActivePlatformKey(f, el._source) ?? null,
      line, projConflict, needsRounds, clean, caveats, proj, edge,
    };
  };
  const overMetrics = new Map(overs.map(f => [f.name, bpViewMetric(f, 'over')] as const));
  const underMetrics = new Map(unders.map(f => [f.name, bpViewMetric(f, 'under')] as const));
  type BpMetric = ReturnType<typeof bpViewMetric>;
  const bpApplyView = (list: AnalyzerFighter[], metrics: Map<string, BpMetric>): AnalyzerFighter[] => {
    let out = list.filter(f => {
      const m = metrics.get(f.name);
      if (!m) return true;
      if (bestPicksStatFilter !== 'all' && m.src !== bestPicksStatFilter) return false;
      if (bestPicksEvOnly && !(m.ev != null && m.ev > 0)) return false;
      if (bestPicksCleanOnly && !m.clean) return false;
      if (bestPicksFlaggedOnly && m.clean) return false;
      if (bestPicksSevereOnly && m.caveats < 2) return false;
      return true;
    });
    if (bestPicksSortMode === 'ev') {
      out = [...out].sort((a, b) => (metrics.get(b.name)?.ev ?? -Infinity) - (metrics.get(a.name)?.ev ?? -Infinity));
    } else if (bestPicksSortMode === 'conf') {
      out = [...out].sort((a, b) => (metrics.get(b.name)?.conf ?? 0) - (metrics.get(a.name)?.conf ?? 0));
    } else if (bestPicksSortMode === 'edge') {
      // GLOW-UP 196 L5 — rank by how far the projection sits from the line you'd
      // enter. Distinct from EV (which prices the calibrated win probability) and
      // from MODEL (score + demotions): this is raw disagreement with the book.
      out = [...out].sort((a, b) => (metrics.get(b.name)?.edge ?? -Infinity) - (metrics.get(a.name)?.edge ?? -Infinity));
    }
    return out;
  };
  const displayOvers = bpApplyView(overs, overMetrics);
  const displayUnders = bpApplyView(unders, underMetrics);

  // ── GLOW-UP 169 (Best Picks level-up 3): same-fight cross-column linkage ──
  // A fight whose picks land in BOTH columns is one event feeding two rows:
  // either the opponent pair (A over / B under — the coherent "A outworks B"
  // shape, still one fight's worth of variance) or the same fighter dual-
  // listed on two stats. Computed on the DISPLAY lists so tags never point
  // at rows the 167 filters hid.
  // ── GLOW-UP 199 L3: placed-vs-board reconciliation ────────────────────────
  // `isPlaced` matches on the FULL slate key (name|direction|stat), so it only lights
  // up when you placed exactly the pick the board is showing. Place a different stat
  // or the opposite side on that fighter and the row says nothing — you can be staked
  // on Bogdan Grad FP OVER while the board recommends Grad SS UNDER and see no hint of
  // it. Index every placed leg by fighter so a row can report what you already hold.
  const placedByFighter = new Map<string, Array<{ dir: string; stat: string }>>();
  for (const key of bestPicksPlaced.keys()) {
    const [pName, pDir, pStat] = key.split('|');
    if (!pName) continue;
    const k = (normalizeName(pName) || pName).toLowerCase();
    if (!placedByFighter.has(k)) placedByFighter.set(k, []);
    placedByFighter.get(k)!.push({ dir: pDir || '', stat: pStat || 'fp' });
  }
  // Returns a chip when this fighter carries a placed leg that ISN'T this pick:
  // opposite direction is a genuine conflict, a different stat is worth knowing.
  const placedElsewhereTag = (f: AnalyzerFighter, dir: string, src: string): string => {
    const held = placedByFighter.get((normalizeName(f.name) || f.name).toLowerCase());
    if (!held || !held.length) return '';
    const other = held.filter(h => !(h.dir === dir && h.stat === src));
    if (!other.length) return '';
    const opposed = other.filter(h => h.dir && h.dir !== dir);
    const label = (h: { dir: string; stat: string }) =>
      `${(h.dir || '').toUpperCase()} ${EFFECTIVE_LEAN_STAT_LABEL[h.stat] || h.stat.toUpperCase()}`;
    if (opposed.length) {
      return `<span class="bp-placed-conflict" title="You already have money on ${prettyName(f.name)} the OTHER way — placed ${opposed.map(label).join(', ')}, while this pick is ${dir.toUpperCase()} ${EFFECTIVE_LEAN_STAT_LABEL[src] || src.toUpperCase()}. Taking both stakes opposite outcomes on one fighter.">⚠ PLACED ${opposed.map(label).join(', ')}</span>`;
    }
    return `<span class="bp-placed-other" title="You've already placed a different stat on ${prettyName(f.name)}: ${other.map(label).join(', ')}. Same fighter, so this adds exposure to one outcome rather than diversifying.">● PLACED ${other.map(label).join(', ')}</span>`;
  };

  const bpFightKey = (f: AnalyzerFighter): string => {
    const opp = f.opponent ? f.opponent.toLowerCase() : '';
    return opp ? [f.name.toLowerCase(), opp].sort().join('|') : '';
  };
  const overFightMap = new Map<string, string[]>();
  for (const f of displayOvers) { const fk = bpFightKey(f); if (fk) overFightMap.set(fk, [...(overFightMap.get(fk) || []), f.name.toLowerCase()]); }
  const underFightMap = new Map<string, string[]>();
  for (const f of displayUnders) { const fk = bpFightKey(f); if (fk) underFightMap.set(fk, [...(underFightMap.get(fk) || []), f.name.toLowerCase()]); }
  const linkedFightKeys = new Set([...overFightMap.keys()].filter(k => underFightMap.has(k)));

  // Stat-family chips are built from what's actually on the board (with
  // counts), so a card with no KD lines never shows a dead KD chip.
  const BP_SRC_CHIP: Record<string, string> = { fp: 'FP', ss: 'SS', ss_r1: 'R1 SS', td: 'TD', ft: 'FT', kd: 'KD', ctrl: 'CTRL' };
  const bpSrcCounts = new Map<string, number>();
  for (const m of overMetrics.values()) bpSrcCounts.set(m.src, (bpSrcCounts.get(m.src) || 0) + 1);
  for (const m of underMetrics.values()) bpSrcCounts.set(m.src, (bpSrcCounts.get(m.src) || 0) + 1);
  const bpEvPosCount = [...overMetrics.values(), ...underMetrics.values()].filter(m => m.ev != null && m.ev > 0).length;
  const bpCleanCount = [...overMetrics.values(), ...underMetrics.values()].filter(m => m.clean).length;
  const bpSevereCount = [...overMetrics.values(), ...underMetrics.values()].filter(m => m.caveats >= 2).length;
  const bpChipsHtml = Object.keys(BP_SRC_CHIP)
    .filter(s => (bpSrcCounts.get(s) || 0) > 0)
    .map(s => `<button class="bpc-chip${bestPicksStatFilter === s ? ' on' : ''}" data-bp-stat="${s}" title="Show only ${BP_SRC_CHIP[s]} picks (click again for all)">${BP_SRC_CHIP[s]} <i>${bpSrcCounts.get(s)}</i></button>`)
    .join('');
  const bpControlsHtml = `<div class="bp-controls">
    <span class="bpc-group">
      <span class="bpc-label">SORT</span>
      <button class="bpc-btn${bestPicksSortMode === 'model' ? ' on' : ''}" data-bp-sort="model" title="The model's own pick order — score, tier, and correlation demotions">MODEL</button>
      <button class="bpc-btn${bestPicksSortMode === 'ev' ? ' on' : ''}" data-bp-sort="ev" title="Highest calibrated EV first — money order, not signal order">EV</button>
      <button class="bpc-btn${bestPicksSortMode === 'conf' ? ' on' : ''}" data-bp-sort="conf" title="Highest model confidence first">CONF%</button>
      <button class="bpc-btn${bestPicksSortMode === 'edge' ? ' on' : ''}" data-bp-sort="edge" title="Biggest gap between the model's projection and the line you'd enter (the Δ chip) — raw disagreement with the book, independent of how EV prices it">Δ EDGE</button>
    </span>
    <span class="bpc-group">
      <span class="bpc-label">SHOW</span>
      <button class="bpc-chip${bestPicksStatFilter === 'all' ? ' on' : ''}" data-bp-stat="all" title="All stat families">ALL <i>${overs.length + unders.length}</i></button>
      ${bpChipsHtml}
      <button class="bpc-chip bpc-ev${bestPicksEvOnly ? ' on' : ''}" data-bp-evonly="1" title="Only picks whose calibrated EV clears breakeven">+EV <i>${bpEvPosCount}</i></button>
      <button class="bpc-chip bpc-clean${bestPicksCleanOnly ? ' on' : ''}" data-bp-cleanonly="1" title="Only picks carrying no caveat — no ⚠ PROJ SAYS (projection opposes its own lean), no ⚠ NEEDS ROUNDS (volume over against a finisher), and not negative EV. The picks that need no explanation.">CLEAN <i>${bpCleanCount}</i></button>
      <button class="bpc-chip bpc-flagged${bestPicksFlaggedOnly ? ' on' : ''}" data-bp-flaggedonly="1" title="Only picks carrying at least one caveat — ⚠ PROJ SAYS, ⚠ NEEDS ROUNDS, or negative EV. Note this widens sharply once real prices post (negative EV alone can flag a third of the board); when it does, use 2+ CAVEATS for the picks whose objections actually compound.">FLAGGED <i>${(overs.length + unders.length) - bpCleanCount}</i></button>
      ${bpSevereCount > 0 ? `<button class="bpc-chip bpc-severe${bestPicksSevereOnly ? ' on' : ''}" data-bp-severeonly="1" title="Picks carrying TWO OR MORE caveats at once — e.g. negative EV AND the projection arguing against its own lean, or a volume over that needs rounds against a finisher AND prices badly. One objection is a note; two stacking is the actual review queue. Hidden when nothing on the board qualifies.">⚠⚠ 2+ CAVEATS <i>${bpSevereCount}</i></button>` : ''}
    </span>
    <span class="bpc-group">
      <span class="bpc-label">VIEW</span>
      <button class="bpc-chip bpc-bybook${bestPicksByBook ? ' on' : ''}" data-bp-bybook="1" title="Show an entry plan: the same picks regrouped by the app you'd actually place them in, so you can work book by book instead of jumping between them.">🏪 BY BOOK</button>
    </span>
  </div>`;

  // GLOW-UP 168: per-render pick payloads for the slate toggle — built while
  // rows render (all display values in scope), consumed by the click handler.
  const slateRowData = new Map<string, BestPicksSlatePick>();

  /**
   * DISPLAY ONLY — the correlation engine's read on a same-fight pair, built at
   * render time on purpose. Nothing here feeds buildCorrPenalties, bestPickSort
   * or the dedupe, so it cannot move a pick. (A previous attempt wired this into
   * the demotion instead and silently dropped a pick from the board; the two
   * concerns are kept apart deliberately.)
   */
  const bpLegFor = (f: AnalyzerFighter, dir: 'over' | 'under'): ParlayLeg => {
    const el = getBestPickLeanForDir(f, dir) || getBestPickLean(f);
    return {
      fighter: f.name,
      opponent: f.opponent || '',
      stat: (el._source || 'fp') as LeanSource,
      direction: dir,
      line: lineForLeanSource(f, el._source, el._platform) ?? 0,
      confidence: 0, tier: '', platform: '',
    };
  };

  function buildSection(fighters: AnalyzerFighter[], type: 'over'|'under'): string {
    if (!fighters.length) return '';
    const title = type === 'over' ? 'Best Overs' : 'Best Unders';
    const typeClass = type === 'over' ? 'over' : 'under';
    const icon = type === 'over' ? '▲' : '▼';
    // Override lean cache for this column so confidence/tier use the direction-specific lean
    for (const f of fighters) {
      const dirLean = getBestPickLeanForDir(f, type);
      if (dirLean) bestPickLeanCache.set(f.name, dirLean);
    }
    bestPickConfidenceCache.clear();
    bestPickReasonCache.clear();
    const tierCounts: Record<string, number> = { High: 0, Med: 0, Low: 0 };
    const confVals: number[] = [];
    const rows = fighters.map((f, i) => {
      const el = getBestPickLeanForDir(f, type) || getBestPickLean(f);
      // For SS/TD/FT/CTRL: override the displayed line with the easiest one
      // for the lean direction (lowest for OVER, highest for UNDER). FP keeps
      // its per-book _platform from candidate generation.
      const originalLine = lineForLeanSource(f, el._source, el._platform);
      let line = originalLine;
      let displayPlatform: SourcePlatformKey | undefined = el._platform;
      if (el._source !== 'fp' && (el.lean === 'over' || el.lean === 'under')) {
        const best = bestSideLineForPick(f, el._source, el.lean);
        if (best.line != null && best.book != null) {
          line = best.line;
          displayPlatform = best.book;
        }
      }
      const tier = pickTier(f);
      tierCounts[tier.label] = (tierCounts[tier.label] || 0) + 1;
      if (el.conf) confVals.push(Number(el.conf) || 0);
      const archiveNote = getBestPickArchiveNote(f);
      // GLOW-UP 187 (L1): the row's one prose line must say something about THIS
      // fighter. The archive note used to win this slot, but it's keyed by
      // (propType, side, book) — so 9 of 11 rows rendered a byte-identical
      // sentence while each fighter's own verdict (proj vs line) was suppressed.
      // The note is a confidence ADJUSTMENT, not a rationale; it moves to the
      // section header (L2) and is kept here only as a last resort.
      let reason = el.verdict || el.reasons?.[0]?.text || archiveNote || '—';
      // If we overrode the displayed line, sync the line value embedded in
      // the verdict prefix (e.g. "SS OVER 46.5 (proj 69.3) — ...") so the
      // reason stays consistent with the displayed line/book.
      if (line != null && originalLine != null && line !== originalLine && el._source && (el.lean === 'over' || el.lean === 'under')) {
        const prefix = `${el._source === 'ss_r1' ? 'R1 SS' : el._source.toUpperCase()} ${el.lean.toUpperCase()} `;
        if (reason.startsWith(prefix)) {
          const tail = reason.slice(prefix.length);
          const m = tail.match(/^(\d+(?:\.\d+)?)/);
          if (m && Math.abs(parseFloat(m[1]) - originalLine) < 0.01) {
            reason = prefix + line + tail.slice(m[1].length);
          }
        }
      }
      // GLOW-UP 161: the old srcTag "(SS line)" next to the name duplicated
      // the type chip's label in the same row — name line carries identity
      // (name / risk / opponent), the meta chip carries the market.

      // Fight context: opponent + MAIN tag when this pick lives in the headliner.
      const hp = findHeadlinerPair();
      const normPick = (s: string): string => (normalizeName(s) || s).toLowerCase();
      const isMainPick = !!hp && (normPick(f.name) === normPick(hp.f1) || normPick(f.name) === normPick(hp.f2));
      const vsTag = f.opponent
        ? ` <span class="bp-vs">vs ${prettyName(f.opponent)}${isMainPick ? ' <b class="bp-main">MAIN</b>' : ''}</span>`
        : '';

      // Risk flag: audit rule 7 — a picked fighter carrying news/weight-miss
      // should say so ON the pick, not only back on the fighter card.
      const wmPick = _weightMissSignals.get(f.name.toLowerCase());
      const riskTag = wmPick
        ? ` <span class="bp-flag bp-flag-miss" title="Missed weight${wmPick.lbsOver != null ? ` by ${wmPick.lbsOver} lb` : ''} — projections already adjusted, but volatility risk is elevated">⚖ MISS</span>`
        : _newsAlertFighters.has(f.name.toLowerCase())
        ? ` <span class="bp-flag bp-flag-news" title="Recent injury/withdrawal news on this fighter — check headlines before entering">⚠ NEWS</span>`
        : '';

      // GLOW-UP 200 L2 — this pick won its fight on model SCORE while the side it
      // displaced scored higher on CONFIDENCE. Worth knowing before you lock it.
      const inv = bpInversion.get(f.name.toLowerCase());
      const invTag = inv
        ? ` <span class="bp-flag bp-flag-inv" title="${inv.name} was cut from this fight at ${inv.conf}% confidence — higher than this pick's. The model still ranked this side first (score includes correlation and duration demotions that confidence doesn't), but the more confident side of the fight is the one you're NOT on.">⇅ ${inv.conf}% CUT</span>`
        : '';

      // Calibrated EV under the confidence meter — same evWinProb pipeline as
      // the fighter rows, so board and picks can never disagree.
      const evd = computeDetailedEV(f, el);
      const evTag = evd
        ? `<div class="bp-ev ${evd.ev > 0 ? 'pos' : evd.ev < 0 ? 'neg' : ''}" title="EV from ${Math.round(evd.prob * 100)}% win prob${evd.recalibrated ? ' (recalibrated ↻)' : ''} · ${evd.isAssumedVig ? 'assumed -110 vig' : 'actual odds'}">${evd.isAssumedVig ? '~' : ''}EV ${evd.ev > 0 ? '+' : ''}${evd.ev}%${evd.recalibrated ? ' ↻' : ''}</div>`
        : '';
      // Signal ≠ price: High/Med tier next to a red EV isn't a contradiction —
      // tier grades signal strength + sample depth, EV prices the calibrated
      // hit probability against the odds. Say so on the row instead of letting
      // the two numbers silently fight each other.
      const durCoupled = durationCoupledMap.get(f.name);
      const durTag = durCoupled
        ? `<div class="bp-dur-split" title="This OVER needs rounds, and ${prettyName(durCoupled.oppName)} is a finisher — ${durCoupled.oppFinishPct}% finish rate${durCoupled.oppAvgMins != null ? `, ${durCoupled.oppAvgMins.toFixed(1)}m career average` : ''}.${durCoupled.needMins != null ? ` This line needs roughly ${durCoupled.needMins.toFixed(1)} min at his own strike rate.` : ''} An early finish takes this under regardless of who is winning, so it is NOT independent of the other side of this fight. Demoted 8pts.">⚠ NEEDS ROUNDS</div>`
        : '';
      const projConflict = projOpposesLean(reason, el.lean, line, el.avg);
      const projTag = projConflict
        ? `<div class="bp-proj-split${projConflict.gap >= 12 ? ' is-wide' : ''}" title="This pick's own projection (${projConflict.proj}) sits ${projConflict.gap.toFixed(1)} on the ${projConflict.implies} side of the ${line} line — the projection argues ${projConflict.implies}, the pick is ${(el.lean || '').toUpperCase()}. Not necessarily wrong: projection-vs-line contributes at most ±2.5 to the lean score, so hit-rate, opponent and matchup terms can outvote it. Gaps under ${PROJ_CONFLICT_MIN_GAP} are not flagged at all — the score cannot fully express them either. Worth checking manually before entering.">⚠ PROJ SAYS ${projConflict.implies} <b>${projConflict.gap.toFixed(1)}</b></div>`
        : '';
      const splitNote = evd && evd.ev <= -3 && tier.label !== 'Low'
        ? `<div class="bp-ev-split" title="${tier.label.toUpperCase()} tier grades signal strength and sample depth; EV prices the calibrated ${Math.round(evd.prob * 100)}% hit probability against the ${evd.isAssumedVig ? 'assumed -110' : 'posted'} odds. Strong directional lean, but the price doesn't clear breakeven — fine as a pick-em leg, not a value play.">LEAN ✓ · VALUE ✗</div>`
        : '';

      // Brighten the key numbers in the reason (projection + edge vs line)
      const reasonHtml = reason
        .replace(/\(proj ([\d.]+)\)/, '(proj <b class="bpr-key">$1</b>)')
        .replace(/\(avg ([\d.]+m?)\)/, '(avg <b class="bpr-key">$1</b>)')
        .replace(/by ([\d.]+m?)/, 'by <b class="bpr-key">$1</b>')
        .replace(/is ([\d.]+m?) (above|below)/, 'is <b class="bpr-key">$1</b> $2');

      // Correlation tag: penalized fighters show ⬇ corr, remaining conflicts ↔ corr.
      //
      // GLOW-UP 204 — the old text read "correlated slate risk" for EVERY
      // same-fight pair, which says "these fight each other". For two same-fight
      // SS OVERs that is simply wrong, and once GLOW-UP 203 put the engine's
      // verdict on the SHARED FIGHTS card the board visibly contradicted itself:
      // "✓ SYNERGY +0.18 — action fight benefits both strikers" above two rows
      // reading "⬇ corr". They were answering different questions:
      //
      //   engine verdict → CAN both hit?      (yes — they rise together)
      //   the demotion   → how much of the board rides on one fight?
      //
      // Both are true at once, so the row now names which one it means. The
      // demotion itself is untouched — this is a wording fix, not a scoring one.
      const corrPenalty = corrPenaltyMap.get(f.name) || 0;
      const corrPartner = f.opponent
        ? fighters.find(o => o.name.toLowerCase() === (f.opponent || '').toLowerCase())
        : undefined;
      const corrVerdict = corrPartner
        ? calcPairCorrelation(bpLegFor(f, type), f, bpLegFor(corrPartner, type), corrPartner)
        : null;
      const corrReinforces = !!corrVerdict && corrVerdict.impact >= 0;
      const conflictTag = corrPenalty > 0
        ? (corrReinforces
            ? ` <span class="best-pick-conflict bp-corr-pair" title="${(corrVerdict as CorrelationAlert).message.replace(/"/g, '&quot;')} — these two rise together, so this is NOT a contradiction. Still demoted ${corrPenalty}pts because two picks ride one fight: that is concentration, not conflict.">↔ pair −${corrPenalty}</span>`
            : ` <span class="best-pick-conflict" title="${corrVerdict ? `${corrVerdict.message.replace(/"/g, '&quot;')} — ` : 'Opponent picked same direction — '}demoted ${corrPenalty}pts (correlated slate risk)">⬇ corr</span>`)
        : conflictFighters.has(f.name)
        ? ` <span class="best-pick-conflict${corrReinforces ? ' bp-corr-pair' : ''}" title="${corrVerdict ? `${corrVerdict.message.replace(/"/g, '&quot;')}${corrReinforces ? ' — these two rise together' : ''}` : 'Opponent also picked in same direction — correlated picks'}">${corrReinforces ? '↔ pair' : '↔ corr'}</span>`
        : '';

      // GLOW-UP 169: same-fight tag + fight key for hover cross-highlight.
      // ⇄ DUAL = this fighter appears in the other column on another stat;
      // ↔ SAME FIGHT = the opponent holds the other column's row.
      const rowFightKey = bpFightKey(f);
      let sameFightTag = '';
      let fightAttr = '';
      if (rowFightKey && linkedFightKeys.has(rowFightKey)) {
        const otherColNames = (type === 'over' ? underFightMap.get(rowFightKey) : overFightMap.get(rowFightKey)) || [];
        const otherColLabel = type === 'over' ? 'Unders' : 'Overs';
        const isDual = otherColNames.includes(f.name.toLowerCase());
        sameFightTag = isDual
          ? ` <span class="bp-samefight bp-dual" title="This fighter also appears in the ${otherColLabel} column on a different stat — one fight feeding two rows; hover to highlight the paired row">⇄ DUAL</span>`
          : ` <span class="bp-samefight" title="The other side of this fight is picked in the ${otherColLabel} column — coherent pair, but still one fight's worth of variance; hover to highlight the paired row">↔ SAME FIGHT</span>`;
        fightAttr = ` data-fightkey="${rowFightKey.replace(/"/g, '&quot;')}"`;
      }

      // Lineshop badge: only meaningful for FP picks now — SS/TD/FT/CTRL
      // displayed line is already the best-side across all books.
      const src = el._source;
      // GLOW-UP 192 (L1): was FP-only and warn-only. Stat picks already take the
      // best-side book via bestSideLineForPick, but the row never SAID so — you
      // had to trust it. Now every pick reports where it stands across books:
      // a warning when something better exists, otherwise a confirmation with
      // the spread, so you can see what the shopping was actually worth.
      let lineShopTag = '';
      if (line != null && src && (el.lean === 'over' || el.lean === 'under')) {
        const shopBooks: [string, SourcePlatformKey][] = [
          ['P6', 'pick6'], ['UD', 'underdog'], ['PP', 'prizepicks'],
          ['BTR', 'betr'], ['DK', 'draftkings_sportsbook'],
        ];
        const available = shopBooks
          .map(([lbl, k]) => [lbl, lineForLeanSource(f, src, k)] as [string, number | null])
          .filter((x): x is [string, number] => x[1] != null);
        if (available.length > 1) {
          const pickBest = (a: [string, number], b: [string, number]) =>
            el.lean === 'over' ? (b[1] < a[1] ? b : a) : (b[1] > a[1] ? b : a);
          const pickWorst = (a: [string, number], b: [string, number]) =>
            el.lean === 'over' ? (b[1] > a[1] ? b : a) : (b[1] < a[1] ? b : a);
          const best = available.reduce(pickBest);
          const worst = available.reduce(pickWorst);
          const spread = Math.abs(worst[1] - best[1]);
          const dirWord = el.lean === 'over' ? 'lowest' : 'highest';
          if (Math.abs(best[1] - line) >= 1.5) {
            lineShopTag = ` <span class="best-pick-lineshop warn" title="${best[0]} offers ${best[1]} — better for an ${el.lean.toUpperCase()} than the ${line} shown here (${dirWord} line wins). Worth entering there instead.">🏪 ${best[0]} ${best[1]}</span>`;
          } else if (spread >= 0.5) {
            lineShopTag = ` <span class="best-pick-lineshop best" title="This is the best of ${available.length} books for an ${el.lean.toUpperCase()} (${dirWord} line wins) — ${available.map(x => `${x[0]} ${x[1]}`).join(' · ')}. Spread between best and worst is ${spread.toFixed(1)}, which is what the shopping saved you.">🏪 best of ${available.length} · ${spread.toFixed(1)}</span>`;
          }
        }
      }

      // GLOW-UP 162 (Best Picks level-up 1): EV magnitude classes — +EV picks
      // read as money at a glance; ev-hot (>= +10%) gets the loud treatment.
      // GLOW-UP 196 L3 — there was no negative branch here, so a -14% EV pick rendered
      // identically to a strong one and read as equally actionable just because it held
      // a rank. Sub-breakeven picks are now visually demoted (still present and still
      // ranked — the model's order is information — just no longer competing for the eye).
      const evClass = evd && evd.ev >= 10 ? ' ev-hot'
        : evd && evd.ev > 0 ? ' ev-pos'
        : evd && evd.ev < 0 ? ' bp-weak'
        : '';

      // GLOW-UP 162 (level-up 3): structured factor chips — the lean's ranked
      // reason stack rendered as scannable ✓/✗ chips (label = keyword class,
      // full reason text on hover) instead of dying unseen behind one prose line.
      // Classifier now lives at module scope as leanFactorLabel (GLOW-UP 184) so
      // the fighter-card stat panels label identically.
      // GLOW-UP 162 (level-up 4): placeability exclusivity — the candidate
      // pipeline already guarantees the displayed book takes this side; what
      // it can't show is when that book is the ONLY one (dog FP UNDER → UD
      // only, Pick6 More-only cards, single-book stat lines). One placeable
      // book = no line-shopping and no fallback, so flag it on the row.
      const placeableBooks = ((): SourcePlatformKey[] => {
        const dir = el.lean;
        if ((dir !== 'over' && dir !== 'under') || !el._source) return [];
        if (el._source === 'fp') {
          return FP_BOOKS_FOR_BEST_PICKS.filter(b => {
            if (lineForLeanSource(f, 'fp', b) == null) return false;
            if (shouldSkipFpSideForFighter(f, 'fp', dir, b)) return false;
            if (dir === 'under' && b === 'pick6' && (f.fp_under_available ?? null) === false) return false;
            return true;
          });
        }
        const books: SourcePlatformKey[] = ['pick6', 'underdog', 'prizepicks', 'betr', 'draftkings_sportsbook'];
        return books.filter(b => {
          if (dir === 'under' && el._source === 'ss' && !ssUnderBookOffered(f, b)) return false;
          if (dir === 'under' && el._source === 'td' && !tdUnderBookOffered(f, b)) return false;
          return lineForLeanSource(f, el._source, b) != null;
        });
      })();
      const BOOK_ABBR: Record<string, string> = { pick6: 'P6', underdog: 'UD', prizepicks: 'PP', betr: 'BTR', draftkings_sportsbook: 'DK' };
      const onlyBookTag = placeableBooks.length === 1
        ? `<span class="bp-onlybook" title="This side is only placeable on ${BOOK_ABBR[placeableBooks[0]]} for this fighter — no alternative book to shop or fall back to if the line moves or fills">⚑ ${BOOK_ABBR[placeableBooks[0]]} ONLY</span>`
        : '';

      // GLOW-UP 162 (level-up 5): slip-ready copy text for this pick.
      const STAT_LABEL: Record<string, string> = { fp: 'FP', ss: 'SS', ss_r1: 'R1 SS', td: 'TD', ft: 'FT', ctrl: 'CTRL' };
      const clipBook = displayPlatform ?? getSourceActivePlatformKey(f, el._source);
      const BOOK_NAME: Record<string, string> = { pick6: 'Pick6', underdog: 'Underdog', prizepicks: 'PrizePicks', betr: 'Betr', draftkings_sportsbook: 'DK Sportsbook' };
      const clipText = `${prettyName(f.name)} ${(el.lean || '').toUpperCase()} ${line ?? ''} ${STAT_LABEL[el._source || 'fp'] || 'FP'}${clipBook ? ` @ ${BOOK_NAME[clipBook] || clipBook}` : ''}${f.opponent ? ` (vs ${prettyName(f.opponent)})` : ''}`;
      const copyBtn = `<button class="bp-copy" data-clip="${clipText.replace(/"/g, '&quot;')}" title="Copy slip line: ${clipText.replace(/"/g, '&quot;')}">⧉</button>`;

      // GLOW-UP 168: slate toggle — + adds this pick to My Slate, ✓ removes.
      // Sits left of the ⧉ copy button; stays visible (not hover-only) once on.
      const slateKey = `${f.name}|${el.lean}|${el._source || 'fp'}`;
      slateRowData.set(slateKey, {
        key: slateKey,
        name: f.name,
        pretty: prettyName(f.name),
        dir: (el.lean || '').toUpperCase(),
        source: el._source || 'fp',
        statLabel: STAT_LABEL[el._source || 'fp'] || 'FP',
        line: line ?? null,
        book: clipBook ?? null,
        bookLabel: clipBook ? (BOOK_NAME[clipBook] || clipBook) : 'No book',
        clip: clipText,
        opponent: f.opponent ? prettyName(f.opponent) : null,
        opponentRaw: f.opponent || null,
      });
      const inSlate = bestPicksSlate.has(slateKey);
      const slateBtn = `<button class="bp-slate-toggle${inSlate ? ' on' : ''}" data-slate-key="${slateKey.replace(/"/g, '&quot;')}" title="${inSlate ? 'Remove from My Slate' : 'Add to My Slate'}">${inSlate ? '✓' : '+'}</button>`;

      // GLOW-UP 170: placed badge — persisted per event, so it survives
      // reloads even though the slate queue itself is session-scoped.
      const isPlaced = bestPicksPlaced.has(slateKey);
      const placedTag = isPlaced
        ? `<span class="bp-placed" title="You marked this leg placed for this event — recorded for actual-vs-suggested tracking">● PLACED</span>`
        : '';

      // GLOW-UP 176: personal calibration chip — your settled record on this
      // stat family + direction from the Placed Ledger. Informational only
      // (house rule: never mutates model confidence); needs 2+ settled legs
      // so a single lucky hit doesn't masquerade as a track record.
      const youRec = bpPersonalRecord.get(`${el._source || 'fp'}|${el.lean}`);
      const youStatLbl = STAT_LABEL[el._source || 'fp'] || 'FP';
      const youTag = youRec && youRec.total >= 2
        ? `<span class="bp-you ${youRec.hits * 2 >= youRec.total ? 'good' : 'bad'}" title="Your settled record on ${youStatLbl} ${(el.lean || '').toUpperCase()} legs you placed across past events (from My Placed Ledger) — informational only, does not affect model confidence">YOU ${youRec.hits}/${youRec.total}</span>`
        : '';

      // ── GLOW-UP 294 · the rail dropped factors without saying so ───────────
      // pickDistinctFactors caps at 4. Rows routinely carry eight or more reasons,
      // so on most picks four were shown and the rest vanished with no mark. The
      // Predictions rail solved this long ago by printing `+N`; Best Picks — the
      // board you actually bet from — never got it, so a row with four supporting
      // factors and a row with four supporting factors and five more looked
      // identical. Counting DISTINCT reasons, matching what the cap consumes.
      const FACTOR_CAP = 4;
      const factors = pickDistinctFactors(el.reasons, FACTOR_CAP);
      const factorsAll = pickDistinctFactors(el.reasons, 99);
      const factorMore = Math.max(0, factorsAll.length - factors.length);
      // ── GLOW-UP 303 · the visible four were an arbitrary prefix ─────────────
      // pickDistinctFactors is `.slice(0, 4)` — the first four in array order,
      // which is the lean builder's code-execution order, not importance and not
      // a balanced sample. So Dolidze's rail reads ✗ DURATION ✗ OPPONENT ✗ MODEL
      // ✓ STYLE on a pick showing 80% WIN and +100% EV: three visible factors
      // arguing against a pick the model is confident in, with whatever supports
      // it inside the +2.
      //
      // Reordering the four would be worse, not better. Sorting by contribution
      // is impossible — reasons carry no magnitude — and sorting for polarity
      // balance would be manufacturing a summary, either burying real warnings or
      // inventing reassurance. So the imbalance is DISCLOSED rather than dressed:
      // the +N chip says what is behind it, and reads ✓2 when the hidden factors
      // are the supporting ones. A reader who sees three ✗ and a ✓2 knows the
      // visible rail is not the whole argument; today they could only assume it was.
      const hiddenFactors = factorsAll.slice(FACTOR_CAP);
      const hidSup = hiddenFactors.filter(r => factorPolarity(r.icon, el.lean) === 'sup').length;
      const hidOpp = hiddenFactors.filter(r => factorPolarity(r.icon, el.lean) === 'opp').length;
      // GLOW-UP 304: the counts carry COLOUR, not just a glyph. At 9px in the mono
      // face ✓ and ✗ are near-identical shapes, so the mixed form read as "√3 √2" —
      // 303 made the chip more informative and less legible in the same move. Green
      // and rose separate the halves whether or not the glyph resolves, and they are
      // the same two colours the ✓/✗ factor chips beside it already use.
      const hidTally = hidSup && hidOpp
        ? `<i class="hm-sup">✓${hidSup}</i> <i class="hm-opp">✗${hidOpp}</i>`
        : hidSup ? `<i class="hm-sup">✓${hidSup}</i>`
        : hidOpp ? `<i class="hm-opp">✗${hidOpp}</i>`
        : `+${factorMore}`;
      const factorMoreChip = factorMore > 0
        ? `<span class="bp-factor bp-factor-more${hidSup && !hidOpp ? ' hid-sup' : hidOpp && !hidSup ? ' hid-opp' : ''}" title="${factorMore} further factor${factorMore === 1 ? '' : 's'} behind this pick, hidden to keep the row short — ${hidSup} supporting, ${hidOpp} against${hiddenFactors.length - hidSup - hidOpp > 0 ? `, ${hiddenFactors.length - hidSup - hidOpp} context` : ''}. The four shown are the first four the model recorded, not the four that mattered most, so read this chip before concluding the visible rail is the whole argument: ${hiddenFactors.map(r => reasonHeadline(r.text)).join(' · ').replace(/"/g, '&quot;')}">${hidTally}</span>`
        : '';
      // Polarity resolves against el.lean — the raw icon is directional, so an
      // UNDER pick used to render every reason driving it as ✗ (GLOW-UP 184).
      const factorChips = factors.length >= 2
        ? `<div class="bp-factors">${factors.map(r => factorChipHtml(r, el.lean, 'bp-factor')).join('')}${factorMoreChip}</div>`
        : '';
      // GLOW-UP 196 L1 — numeric edge. The projection and its gap to the line were
      // already computed but only surfaced inside prose ("edges the line by 12.1"),
      // so rows couldn't be compared at a glance or sorted on it. Signed so positive
      // is always favourable regardless of side, measured against the DISPLAYED line.
      const bpProj = (typeof el.avg === 'number' && Number.isFinite(el.avg)) ? el.avg : null;
      const bpEdge = (bpProj != null && line != null)
        ? parseFloat((el.lean === 'under' ? line - bpProj : bpProj - line).toFixed(1))
        : null;
      const edgeChip = (bpEdge != null && bpProj != null)
        ? `<span class="bp-edge ${bpEdge > 0 ? 'pos' : bpEdge < 0 ? 'neg' : 'flat'}" title="Model projection ${bpProj.toFixed(1)} vs the ${line} line you'd enter — a ${Math.abs(bpEdge).toFixed(1)} gap on the ${bpEdge >= 0 ? (el.lean || '').toUpperCase() : 'opposite'} side. This is how far the model disagrees with the book: a bigger gap is a bigger claimed edge, and also the place the model is furthest from the market.">Δ <b>${bpEdge > 0 ? '+' : ''}${bpEdge.toFixed(1)}</b></span>`
        : '';
      return `<div class="best-pick-row tier-${tier.label.toLowerCase()} ${typeClass}${evClass}${inSlate ? ' in-slate' : ''}${isPlaced ? ' placed' : ''}" data-jump="${f.name}"${fightAttr} title="Open fighter card">
        <div class="best-pick-rank">#${i+1}</div>
        <div class="bp-avatar"><span class="bp-avatar-flag">${f.db?.country || '🥊'}</span><img class="bp-avatar-img" data-name="${f.name}" alt="" /></div>
        <div><div class="best-pick-name">${prettyName(f.name)}${i === 0 ? ' <span class="bp-top-pick">★ TOP PICK</span>' : ''}${riskTag}${invTag}${vsTag}${sameFightTag}${conflictTag}${lineShopTag}${placedElsewhereTag(f, el.lean, el._source || 'fp')}</div><div class="best-pick-reason" title="${reason.replace(/"/g, '&quot;')}">${reasonHtml}</div>${factorChips}</div>
        <div class="best-pick-meta">
          <span class="best-pick-type ${typeClass} bpt-${el._source || 'fp'}">${type.toUpperCase()}${el._label ? `<i class="bpt-stat">${el._label}</i>` : ''}</span>
          <span class="best-pick-tier ${tier.label.toLowerCase()}">${tier.label}</span>
          <span class="best-pick-platform plat-${displayPlatform ?? getSourceActivePlatformKey(f, el._source) ?? 'none'}">${formatSourcePlatformLabel(f, el._source, displayPlatform)}</span>${edgeChip}${onlyBookTag}${placedTag}${youTag}
        </div>
        <div class="best-pick-line-wrap">
          ${evd ? `<div class="bp-hero-stats${i === 0 ? '' : ' bp-row-stats'}">
            <div class="best-pick-line">${line || '—'}</div>
            <div class="bp-hero-side">
              <div class="bp-hs" title="Calibrated win probability for this pick — the number EV is priced from"><span class="bp-hs-label">WIN</span><b class="bp-hs-val">${Math.round(evd.prob * 100)}%</b></div>
              <div class="bp-hs" title="EV from ${Math.round(evd.prob * 100)}% win prob${evd.recalibrated ? ' (recalibrated ↻)' : ''} · ${evd.isAssumedVig ? 'assumed -110 vig' : 'actual odds'}"><span class="bp-hs-label">EV</span><b class="bp-hs-val ${evd.ev > 0 ? 'pos' : evd.ev < 0 ? 'neg' : ''}">${evd.isAssumedVig ? '~' : ''}${evd.ev > 0 ? '+' : ''}${evd.ev}%</b></div>
            </div>
          </div>` : `<div class="best-pick-line">${line || '—'}</div>`}
          ${el.conf ? `<div class="best-pick-conf ${tier.label.toLowerCase()}" title="Model confidence: ${el.conf}%"><i style="width:${Math.min(100, Math.max(8, Number(el.conf) || 0))}%"></i></div>` : ''}
          ${evd ? '' : evTag}${splitNote}${projTag}${durTag}
        </div>
        ${slateBtn}${copyBtn}
      </div>`;
    }).join('');
    const avgConf = confVals.length ? Math.round(confVals.reduce((a, b) => a + b, 0) / confVals.length) : null;
    // GLOW-UP 161: tier tallies + avg confidence live in the section header
    // (glanceable before scrolling) instead of a footer under the 8th row.
    const headerStats = `<span class="bph-stats">${
      tierCounts['High'] ? `<span class="bps-tally bps-high">${tierCounts['High']} HIGH</span>` : ''
    }${
      tierCounts['Med'] ? `<span class="bps-tally bps-med">${tierCounts['Med']} MED</span>` : ''
    }${
      tierCounts['Low'] ? `<span class="bps-tally bps-low">${tierCounts['Low']} LOW</span>` : ''
    }${
      avgConf != null ? `<span class="bph-avg" title="Average model confidence across this column's picks">avg ${avgConf}%</span>` : ''
    }${
      // GLOW-UP 199 L5 — aggregate Δ. Every pick now carries a signed edge (GLOW-UP
      // 196, extended to FP by L1 above), so the column can report how far the model
      // sits from the books OVERALL rather than only per row. This is a health signal,
      // not a scoreboard: a column averaging a large positive Δ is one where the model
      // disagrees with every book at once, which is exactly the shape MODEL v15 found
      // to be over-projection rather than edge. Flagged above 10 so it reads as
      // "check this" rather than "free money".
      (() => {
        const ds = fighters
          .map(f => (type === 'over' ? overMetrics : underMetrics).get(f.name)?.edge)
          .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
        if (ds.length < 2) return '';
        const avgD = ds.reduce((a, b) => a + b, 0) / ds.length;
        const stretched = avgD >= 10;
        // ── GLOW-UP 298 · only one end of this number was ever flagged ─────────
        // `edge` is signed so POSITIVE always means favourable. A big positive
        // average was flagged as possible over-projection, and a NEGATIVE one —
        // the column's own projections arguing against its own picks, on average,
        // across every row — rendered in the same quiet grey as a healthy board.
        // On the live card the overs column sat at -3.7 with three rows already
        // carrying ⚠ PROJ SAYS individually, and the header said nothing.
        //
        // Same 2.5 floor as the per-row flag, applied to the mean: this IS that
        // flag aggregated, so the two should agree about what counts as opposition.
        const opposed = avgD <= -PROJ_CONFLICT_MIN_GAP;
        const cls = stretched ? ' warn' : opposed ? ' opposed' : '';
        const tip = `Mean gap between the model's projection and the line you'd enter, across this column's ${ds.length} picks. Positive is favourable on either side.`
          + (stretched
            ? ` Above 10 the column is disagreeing with the books broadly rather than on a few spots — the pattern MODEL v15 measured as over-projection, so treat it as a prompt to check rather than a signal to press.`
            : opposed
              ? ` Negative means the projections behind this column point AGAINST its own picks on average — not a few contrarian rows, the whole column. The individual ⚠ PROJ SAYS chips are the same fact per row; this is what they sum to. The lean can still be right (projection-vs-line moves the score by at most ±2.5) but a column that argues with itself is worth reading before pressing.`
              : ``);
        return `<span class="bph-avgd${cls}" title="${tip.replace(/"/g, '&quot;')}">${stretched ? '⚠ ' : opposed ? '⚠ ' : ''}avg Δ ${avgD > 0 ? '+' : ''}${avgD.toFixed(1)}</span>`;
      })()
    }${
      // GLOW-UP 187 (L5): "best" ranks by model, not by price — 5 of 7 picks
      // sitting at EV -12% under a header that says BEST reads as an
      // endorsement. State the split so model-ranked isn't read as value.
      (() => {
        let pos = 0, neg = 0;
        for (const f of fighters) { const e = computeDetailedEV(f, getBestPickLean(f)); if (!e) continue; if (e.ev > 0) pos++; else if (e.ev < 0) neg++; }
        if (!pos && !neg) return '';
        return `<span class="bph-ev-split" title="This column ranks by model signal, not by price. ${pos} pick${pos === 1 ? '' : 's'} clear breakeven on the posted odds; ${neg} do not — those are playable as pick-em legs, not as value.">${pos ? `<b class="bps-evpos">${pos} +EV</b>` : ''}${pos && neg ? ' · ' : ''}${neg ? `<b class="bps-evneg">${neg} −EV</b>` : ''}</span>`;
      })()
    }</span>`;
    // GLOW-UP 187 (L2/L3): the archive adjustment is a property of
    // (stat, side, book), so it belongs to the column — not stamped on every
    // row. Deduped here, with the sample count exposed: a 3-sample archive
    // check moving confidence is thin, and the row prose never said so.
    const archiveChips = (() => {
      const seen = new Map<string, BestPickArchiveMeta>();
      for (const f of fighters) {
        const m = getBestPickArchiveMeta(f);
        if (m) seen.set(`${m.propType}|${m.lean}|${m.platform}|${m.dir}`, m);
      }
      if (!seen.size) return '';
      const chips = [...seen.values()].map(m => {
        const thin = m.total < 5;
        return `<span class="bph-arch ${m.dir === 'up' ? 'up' : 'down'}${thin ? ' thin' : ''}" title="Archive check: ${m.propType} ${m.lean}s on ${m.platform} hit ${m.pct}% across ${m.total} settled sample${m.total === 1 ? '' : 's'}, so model confidence was ${m.dir === 'up' ? 'boosted' : 'trimmed'} for those picks.${thin ? ' Thin sample — treat this adjustment as weak evidence.' : ''}">${m.dir === 'up' ? '▲' : '▼'} ${m.propType} ${m.lean.toUpperCase()} · ${m.platform.toUpperCase()} ${m.pct}% <i>n=${m.total}</i></span>`;
      }).join('');
      return `<div class="bph-archive" title="Confidence adjustments applied to this column from settled archive results">${chips}</div>`;
    })();
    return `<div class="best-picks-section ${typeClass}"><div class="best-picks-header"><span class="best-picks-title">${icon} ${title}</span>${headerStats}<span class="best-picks-count">${fighters.length} picks</span></div>${archiveChips}${rows}</div>`;
  }

  // GLOW-UP 167: controls render whenever the board has picks; the grid draws
  // the filtered view. A filter that empties the view gets its own message
  // (with reset) instead of the "no leans yet" cold-start fallback.
  const hasAnyPicks = overs.length + unders.length > 0;

  // ── GLOW-UP 192 (L3): board exposure strip ────────────────────────────────
  // Sixteen rows read as a list; this reads them as a portfolio. How many
  // distinct fights am I actually exposed to, is any single fight carrying too
  // much of the board, and which apps will I be opening to enter it all.
  const BP_BOOK_SHORT: Record<string, string> = { pick6: 'P6', underdog: 'UD', prizepicks: 'PP', betr: 'BTR', draftkings_sportsbook: 'DK' };
  const BP_BOOK_FULL: Record<string, string> = { pick6: 'Pick6', underdog: 'Underdog', prizepicks: 'PrizePicks', betr: 'Betr', draftkings_sportsbook: 'DK Sportsbook' };
  const exposureHtml = (() => {
    const shown: Array<{ f: AnalyzerFighter; m: BpMetric }> = [
      ...displayOvers.map(f => ({ f, m: overMetrics.get(f.name)! })),
      ...displayUnders.map(f => ({ f, m: underMetrics.get(f.name)! })),
    ].filter(x => !!x.m);
    if (shown.length < 2) return '';
    const fightCount = new Map<string, number>();
    // bpFightKey lowercases for grouping, so keep a properly-cased label from
    // the fighter objects rather than title-casing the key back.
    const fightLabel = new Map<string, string>();
    for (const { f } of shown) {
      const k = bpFightKey(f) || f.name.toLowerCase();
      fightCount.set(k, (fightCount.get(k) || 0) + 1);
      if (!fightLabel.has(k)) {
        fightLabel.set(k, f.opponent ? `${prettyName(f.name)} vs ${prettyName(f.opponent)}` : prettyName(f.name));
      }
    }
    const distinctFights = fightCount.size;
    let maxFight = 0; let maxFightKey = '';
    for (const [k, c] of fightCount) if (c > maxFight) { maxFight = c; maxFightKey = k; }
    const maxFightLabel = fightLabel.get(maxFightKey) || maxFightKey;
    // GLOW-UP 200 L5 — the book chips counted picks but never priced them, so a
    // book carrying 6 thin picks looked heavier than one carrying 2 strong ones.
    // Average EV per book says which app is actually carrying the slate.
    const bookCount = new Map<string, number>();
    const bookEv = new Map<string, number[]>();
    for (const { m } of shown) {
      if (!m.book) continue;
      bookCount.set(m.book, (bookCount.get(m.book) || 0) + 1);
      if (m.ev != null) bookEv.set(m.book, [...(bookEv.get(m.book) || []), m.ev]);
    }
    const bookChips = [...bookCount.entries()]
      .sort((a, b) => b[1] - a[1])
      .map(([k, c]) => {
        const evs = bookEv.get(k) || [];
        const avg = evs.length ? evs.reduce((s, v) => s + v, 0) / evs.length : null;
        const evChip = avg != null
          ? ` <em class="bpx-book-ev ${avg > 0 ? 'pos' : 'neg'}">${avg > 0 ? '+' : ''}${avg.toFixed(0)}%</em>`
          : '';
        const evTitle = avg != null ? ` · average EV ${avg > 0 ? '+' : ''}${avg.toFixed(1)}% across ${evs.length} priced pick${evs.length === 1 ? '' : 's'}` : '';
        return `<span class="bpx-book plat-${k}" title="${c} pick${c === 1 ? '' : 's'} to enter on ${BP_BOOK_FULL[k] || k}${evTitle}">${BP_BOOK_SHORT[k] || k.toUpperCase()} <i>${c}</i>${evChip}</span>`;
      })
      .join('');
    // Concentration: >=40% of the board on one fight means the slate is much
    // less diversified than the pick count suggests.
    const concentrated = maxFight >= 3 && maxFight / shown.length >= 0.4;
    return `<div class="bp-exposure">
      <span class="bpx-label">EXPOSURE</span>
      <span class="bpx-item" title="Distinct fights these ${shown.length} picks touch. Fewer fights than picks means repeated exposure to the same outcomes.">${distinctFights} fight${distinctFights === 1 ? '' : 's'} · ${shown.length} picks</span>
      <span class="bpx-item${concentrated ? ' warn' : ''}" title="${concentrated ? `${maxFight} of ${shown.length} picks ride on ${maxFightLabel} — that fight going the wrong way takes a large share of the board with it. Correlated, not diversified.` : `Heaviest single fight is ${maxFightLabel} with ${maxFight} pick${maxFight === 1 ? '' : 's'}.`}">${concentrated ? '⚠ ' : ''}MAX <b>${maxFight}</b> on ${maxFightLabel}</span>
      <span class="bpx-books" title="Where these picks would be placed — one group per app you'd open">${bookChips}</span>
    </div>`;
  })();

  // ── GLOW-UP 196 L2: per-fight roll-up ─────────────────────────────────────
  // The ⇄ DUAL / ↔ SAME FIGHT badges tell a row that it shares a fight with
  // another row, but not WITH WHAT — so reading a board where one fight feeds
  // three picks across both columns meant hovering badges and cross-referencing
  // two columns by eye. This enumerates every multi-pick fight in one place:
  // what the picks are, which side each sits on, and how much of the board rides
  // on that single outcome. Click jumps to the fighter card.
  const fightRollupHtml = (() => {
    const shown: Array<{ f: AnalyzerFighter; m: BpMetric; dir: 'over' | 'under' }> = [
      ...displayOvers.map(f => ({ f, m: overMetrics.get(f.name)!, dir: 'over' as const })),
      ...displayUnders.map(f => ({ f, m: underMetrics.get(f.name)!, dir: 'under' as const })),
    ].filter(x => !!x.m);
    if (shown.length < 2) return '';
    const byFight = new Map<string, { label: string; picks: typeof shown }>();
    for (const row of shown) {
      const k = bpFightKey(row.f) || row.f.name.toLowerCase();
      if (!byFight.has(k)) {
        byFight.set(k, {
          label: row.f.opponent ? `${prettyName(row.f.name)} vs ${prettyName(row.f.opponent)}` : prettyName(row.f.name),
          picks: [],
        });
      }
      byFight.get(k)!.picks.push(row);
    }
    const multi = [...byFight.values()].filter(v => v.picks.length >= 2).sort((a, b) => b.picks.length - a.picks.length);
    if (!multi.length) return '';
    const cards = multi.map(v => {
      const overN = v.picks.filter(p => p.dir === 'over').length;
      const underN = v.picks.length - overN;
      // ── GLOW-UP 203 ──────────────────────────────────────────────────────
      // The roll-up said WHICH picks share a fight but never whether they pull
      // together or against each other — and calcPairCorrelation has answered
      // exactly that all along, for Parlay Lab. A same-fight pair is not
      // automatically a diversification problem OR automatically fine: an
      // SS OVER opposite an FT UNDER is the house rule's named conflict (volume
      // needs rounds, an FT under needs a finish), while an FT under opposite a
      // volume under is mutually reinforcing. Reading it off the board beat
      // hovering two badges and reasoning it out per fight.
      // Worst pair wins the chip: with 3+ picks the cluster is only as sound as
      // its most contradictory pairing.
      const asLeg = (p: { f: AnalyzerFighter; m: BpMetric; dir: 'over' | 'under' }): ParlayLeg => ({
        fighter: p.f.name,
        opponent: p.f.opponent || '',
        stat: (p.m.src || 'fp') as LeanSource,
        direction: p.dir,
        line: p.m.line ?? 0,
        confidence: 0, tier: '', platform: '',
      });
      let worst: CorrelationAlert | null = null;
      for (let i = 0; i < v.picks.length; i++) {
        for (let j = i + 1; j < v.picks.length; j++) {
          const alert = calcPairCorrelation(asLeg(v.picks[i]), v.picks[i].f, asLeg(v.picks[j]), v.picks[j].f);
          if (alert && (!worst || alert.impact < worst.impact)) worst = alert;
        }
      }
      const CORR_LABEL: Record<string, string> = {
        synergy: '✓ SYNERGY', conflict: '⚠ CONFLICT', caution: '⚠ CAUTION', neutral: '· NEUTRAL',
      };
      const corrChip = worst
        ? `<span class="bpfr-corr bpfr-corr-${worst.type}" title="${worst.message.replace(/"/g, '&quot;')}">${CORR_LABEL[worst.type]} ${worst.impact > 0 ? '+' : ''}${worst.impact.toFixed(2)}</span>`
        : '';
      const legs = v.picks.map(p => {
        const stat = EFFECTIVE_LEAN_STAT_LABEL[p.m.src] || p.m.src.toUpperCase();
        return `<button class="bpfr-leg ${p.dir}" data-jump="${p.f.name}" title="${prettyName(p.f.name)} ${p.dir.toUpperCase()} ${stat} ${p.m.line ?? ''} — click to open the card">`
          + `${p.dir === 'over' ? '▲' : '▼'} ${prettyName(p.f.name).split(' ').slice(-1)[0]} <i>${stat}${p.m.line != null ? ` ${p.m.line}` : ''}</i></button>`;
      }).join('');
      const heavy = v.picks.length >= 3;
      return `<div class="bpfr-fight${heavy ? ' heavy' : ''}">
        <div class="bpfr-head"><span class="bpfr-name">${v.label}</span>${corrChip}<span class="bpfr-count" title="${v.picks.length} of the ${shown.length} picks on the board ride on this one fight (${overN} over, ${underN} under)">${heavy ? '⚠ ' : ''}${v.picks.length} picks</span></div>
        <div class="bpfr-legs">${legs}</div>
      </div>`;
    }).join('');
    return `<div class="bp-fight-rollup">
      <div class="bpfr-label" title="Every fight feeding more than one pick on this board. One fight going the wrong way takes all of its picks with it — these are the correlated clusters.">↔ SHARED FIGHTS <i>${multi.length}</i></div>
      <div class="bpfr-grid">${cards}</div>
    </div>`;
  })();

  // ── GLOW-UP 200 L2: rank inversions ───────────────────────────────────────
  // dedupeNegCorrelatedSameFight keeps ONE pick per fight per column, ranked by
  // model score. Score is not confidence, so the survivor can be the LOWER-
  // confidence side — on the Medic/Rodriguez card, Uros Medic (68%) was cut for
  // Daniel Rodriguez (52%) and Kyle Prepolec (61%) for Mateusz Rebecki (53%),
  // two of four dedups. The cut list recorded it; the surviving row never did,
  // so the board silently presented the weaker side as the fight's best pick.
  // Not necessarily wrong — score carries demotions confidence doesn't — but it
  // must be visible.
  const bpInversion = new Map<string, { name: string; conf: number }>();
  let bpDedupCount = 0;
  {
    const scan = (all: AnalyzerFighter[], final: AnalyzerFighter[], dir: 'over' | 'under'): void => {
      const kept = new Map<string, AnalyzerFighter>();
      for (const f of final) { const k = bpFightKey(f); if (k) kept.set(k, f); }
      for (const f of all) {
        const fk = bpFightKey(f);
        if (!fk) continue;
        const winner = kept.get(fk);
        if (!winner || winner.name.toLowerCase() === f.name.toLowerCase()) continue;
        bpDedupCount++;
        const cutEl = getBestPickLeanForDir(f, dir);
        const winEl = getBestPickLeanForDir(winner, dir);
        if (!cutEl || !winEl) continue;
        const cutConf = Number(cutEl.conf) || 0;
        const winConf = Number(winEl.conf) || 0;
        if (cutConf <= winConf) continue;
        const key = winner.name.toLowerCase();
        const prev = bpInversion.get(key);
        if (!prev || cutConf > prev.conf) bpInversion.set(key, { name: prettyName(f.name), conf: cutConf });
      }
    };
    scan(allOversSorted, overs, 'over');
    scan(allUndersSorted, unders, 'under');
  }

  // ── GLOW-UP 200 L1: board verdict strip ───────────────────────────────────
  // Each column summarises itself (tiers · avg conf · +EV count), but nothing
  // summarised the BOARD — so "how good is tonight overall, and how much of it
  // needs a second look" meant adding two headers up by eye. Every figure here
  // is already computed per-pick; this only aggregates.
  const verdictHtml = (() => {
    const all = [
      ...displayOvers.map(f => overMetrics.get(f.name)).filter((m): m is BpMetric => !!m),
      ...displayUnders.map(f => underMetrics.get(f.name)).filter((m): m is BpMetric => !!m),
    ];
    if (all.length < 2) return '';
    const evs = all.map(m => m.ev).filter((v): v is number => v != null);
    const avgEv = evs.length ? evs.reduce((s, v) => s + v, 0) / evs.length : null;
    const avgConf = all.reduce((s, m) => s + m.conf, 0) / all.length;
    const flagged = all.filter(m => !m.clean).length;
    const negEv = all.filter(m => m.ev != null && m.ev < 0).length;
    const inversions = bpInversion.size;
    // A board is only as good as its weakest habit: lead with the count that
    // most often needs action rather than the flattering average.
    const verdictCls = avgEv == null ? 'flat' : avgEv >= 10 ? 'strong' : avgEv > 0 ? 'ok' : 'weak';
    return `<div class="bp-verdict bpv-${verdictCls}">
      <span class="bpv-label">BOARD</span>
      <span class="bpv-picks" title="Picks currently displayed across both columns">${all.length} picks</span>
      <span class="bpv-conf" title="Mean displayed confidence across the board">avg conf <b>${Math.round(avgConf)}%</b></span>
      ${avgEv != null ? `<span class="bpv-ev ${avgEv > 0 ? 'pos' : 'neg'}" title="Mean calibrated EV across the ${evs.length} priced picks. Not a return estimate — the average edge you're taking.">avg EV <b>${avgEv > 0 ? '+' : ''}${avgEv.toFixed(1)}%</b></span>` : ''}
      <span class="bpv-sep"></span>
      ${flagged > 0
        ? `<button class="bpv-flag" data-bp-flaggedonly="1" title="${flagged} pick(s) carry a caveat — projection opposing its own lean, a volume over needing rounds, or negative EV. Click to review only those.">⚠ ${flagged} need review</button>`
        : `<span class="bpv-clean" title="No pick carries a caveat">✓ all clean</span>`}
      ${negEv > 0 ? `<span class="bpv-neg" title="${negEv} pick(s) price below breakeven — the model likes the signal, the odds don't pay for it">${negEv} −EV</span>` : ''}
      ${inversions > 0
        ? `<span class="bpv-inv" title="${inversions} fight(s) where the pick shown was ranked first on model score while the side it displaced scored higher on confidence. Look for the ⇅ chip.">⇅ ${inversions} inversion${inversions === 1 ? '' : 's'}</span>`
        : bpDedupCount > 0
        ? `<span class="bpv-inv-none" title="${bpDedupCount} same-fight dedupe(s) happened and in every one the surviving pick was ALSO the more confident side. A zero here is a real check, not an unrun one.">⇅ 0 of ${bpDedupCount} dedupes</span>`
        : ''}
    </div>`;
  })();

  // ── GLOW-UP 192 (L4): considered but cut ──────────────────────────────────
  // The board shows survivors. This shows who was in contention and why they
  // aren't — so the selection is auditable instead of taken on trust. Reasons
  // are derived, not guessed: dedupeNegCorrelatedSameFight either dropped a
  // fighter because the other side of their fight outranked them, or they fell
  // below the cut.
  const nearMissHtml = (() => {
    const rows: string[] = [];
    // GLOW-UP 199 L4 — the list is collapsed by default, so the header was the only
    // thing most reads ever saw and it carried a bare count. Tally WHY things were cut
    // so the closed state still answers "did I lose anything that mattered".
    let cutSameFight = 0, cutBelowBar = 0, cutInverted = 0;
    const build = (all: AnalyzerFighter[], final: AnalyzerFighter[], dir: 'over' | 'under') => {
      const kept = new Set(final.map(f => f.name.toLowerCase()));
      const keptFights = new Map<string, string>();
      for (const f of final) { const k = bpFightKey(f); if (k) keptFights.set(k, f.name); }
      for (const f of all) {
        if (kept.has(f.name.toLowerCase())) continue;
        const el = getBestPickLeanForDir(f, dir);
        if (!el || (el.lean !== 'over' && el.lean !== 'under')) continue;
        const fk = bpFightKey(f);
        const blockedBy = fk ? keptFights.get(fk) : undefined;
        const conf = Number(el.conf) || 0;
        const stat = el._source === 'ss_r1' ? 'R1 SS' : (el._source || 'fp').toUpperCase();
        // MODEL v32: a pick the moneyline guard pushed under the bar was cut for a
        // specific, measured reason. Naming it here is the difference between an
        // audit trail and a list of things that vanished.
        const mlg = Number(el.mlGuardDelta) || 0;
        const reason = blockedBy && blockedBy.toLowerCase() !== f.name.toLowerCase()
          ? `same fight as ${prettyName(blockedBy)}, who ranked higher`
          : mlg < 0
            ? `<b class="bpnm-guard">${mlg}</b> ${el.lean === 'over' ? 'FP over priced to lose' : 'FP under against a comfortable win'} — was ${conf - mlg}, below the cut at ${conf}`
            : 'below the cut for this column';
        // GLOW-UP 200 L4 — the audit trail was honest but inert: you could read
        // that a fighter was cut and had no way to go look at them. Rows now jump
        // to the card, and a cut that OUTRANKS its winner on confidence says so
        // here too, matching the ⇅ chip on the surviving row.
        const beat = blockedBy ? (Number(getBestPickLeanForDir(
          allFighters.find(x => x.name.toLowerCase() === blockedBy.toLowerCase()) || f, dir)?.conf) || 0) : 0;
        const inverted = !!blockedBy && conf > beat;
        if (blockedBy && blockedBy.toLowerCase() !== f.name.toLowerCase()) cutSameFight++; else cutBelowBar++;
        if (inverted) cutInverted++;
        // GLOW-UP 297: a row cut by a MEASURED rule is not the same kind of row as
        // one cut by seating order. "same fight as X, who ranked higher" is
        // bookkeeping; "-16 for an FP over priced to lose" is the model telling you
        // it overruled something. Both rendered in the same 9px --text3, so the one
        // row worth reading was the hardest to find. Marked, like bpnm-inverted
        // already is — the list's own precedent for "this line is different".
        rows.push(`<div class="bpnm-row${inverted ? ' bpnm-inverted' : ''}${mlg < 0 ? ' bpnm-guarded' : ''}" data-bpnm-jump="${f.name.replace(/"/g, '&quot;')}" title="Open ${prettyName(f.name)}'s card">
          <span class="bpnm-dir ${dir}">${dir.toUpperCase()}</span>
          <span class="bpnm-name">${prettyName(f.name)}</span>
          <span class="bpnm-stat">${stat}</span>
          <span class="bpnm-conf">${conf}%</span>
          <span class="bpnm-why">${reason}${inverted ? ` <b class="bpnm-inv" title="This cut pick was MORE confident than the one that displaced it (${beat}%). The model ranks on score, not confidence.">⇅ more confident than the pick that displaced it</b>` : ''}</span>
        </div>`);
      }
    };
    build(allOversSorted, overs, 'over');
    build(allUndersSorted, unders, 'under');
    if (!rows.length) return '';
    return `<div class="best-picks-section bp-nearmiss${_bpNearMissOpen ? '' : ' collapsed'}">
      <div class="best-picks-header bpnm-head"><span class="best-picks-title">Considered but cut</span><span class="best-picks-count">${rows.length}</span><span class="bpnm-summary">${
        [
          cutSameFight ? `<span class="bpnm-s" title="Cut because the other side of their fight ranked higher — one pick per fight per column.">${cutSameFight} same-fight</span>` : '',
          cutBelowBar ? `<span class="bpnm-s" title="Had an actionable lean but ranked below the cut for their column.">${cutBelowBar} below bar</span>` : '',
          cutInverted ? `<span class="bpnm-s warn" title="These cut picks were MORE confident than the pick that displaced them — the model ranks on score, not confidence. Worth opening the list.">⇅ ${cutInverted} more confident</span>` : '',
        ].filter(Boolean).join('')
      }</span><span class="section-chevron">▼</span></div>
      <div class="section-body"><div class="bpnm-note">Fighters with an actionable lean that didn't make the board — and why. Nothing here was silently dropped.</div>${rows.join('')}</div>
    </div>`;
  })();

  // ── GLOW-UP 192 (L5): BY BOOK entry plan ──────────────────────────────────
  // Deliberately an additional panel rather than a replacement for the two
  // columns: the grid carries the slate-tray checkboxes, jump-to-card handlers
  // and cross-column linkage, and regrouping it would break all three. This
  // answers the last-mile question the columns can't — "what do I open, and
  // what do I type into it".
  const byBookHtml = (() => {
    if (!bestPicksByBook) return '';
    const shown: Array<{ f: AnalyzerFighter; m: BpMetric; dir: 'over' | 'under' }> = [
      ...displayOvers.map(f => ({ f, m: overMetrics.get(f.name)!, dir: 'over' as const })),
      ...displayUnders.map(f => ({ f, m: underMetrics.get(f.name)!, dir: 'under' as const })),
    ].filter(x => !!x.m);
    if (!shown.length) return '';
    const groups = new Map<string, typeof shown>();
    for (const s of shown) {
      const k = s.m.book || 'unknown';
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k)!.push(s);
    }
    const order = [...groups.keys()].sort((a, b) => groups.get(b)!.length - groups.get(a)!.length);
    const cards = order.map(k => {
      const g = groups.get(k)!;
      const lines = g.map(({ f, m, dir }) => {
        const stat = m.src === 'ss_r1' ? 'R1 SS' : m.src.toUpperCase();
        const flag = !m.clean ? `<span class="bpbb-flag" title="${m.projConflict ? 'Projection opposes this lean' : m.needsRounds ? 'Volume over against a finisher — needs rounds' : 'Negative EV at the posted price'}">⚠</span>` : '';
        return `<div class="bpbb-line" data-jump="${f.name}" title="Jump to ${prettyName(f.name)}'s card">
          <span class="bpbb-dir ${dir}">${dir.toUpperCase()}</span>
          <span class="bpbb-name">${prettyName(f.name)}</span>
          <span class="bpbb-stat">${stat}</span>
          <span class="bpbb-line-val">${m.line ?? '—'}</span>${flag}
        </div>`;
      }).join('');
      return `<div class="bpbb-card">
        <div class="bpbb-head plat-${k}">${k === 'unknown' ? 'NO BOOK' : (BP_BOOK_SHORT[k] || k.toUpperCase())}<span class="bpbb-count">${g.length}</span></div>
        ${lines}
      </div>`;
    }).join('');
    return `<div class="bp-bybook">
      <div class="bpbb-title">ENTRY PLAN — BY BOOK<span class="bpbb-sub">the same ${shown.length} picks, grouped by the app you'd open</span></div>
      <div class="bpbb-grid">${cards}</div>
    </div>`;
  })();

  const gridHtml = displayOvers.length + displayUnders.length > 0
    ? `${verdictHtml}${exposureHtml}${fightRollupHtml}${byBookHtml}<div class="best-picks-grid">${buildSection(displayOvers, 'over')}${buildSection(displayUnders, 'under')}</div>${nearMissHtml}`
    : hasAnyPicks
    ? '<div class="bp-filter-empty">No picks match the current view — <button class="bpc-reset">reset filters</button></div>'
    : '';
  // GLOW-UP 168: My Slate tray — docked under the grid, sticky to the
  // viewport bottom while the columns scroll. Collapsed = one-line summary
  // (count + per-book tallies); open = picks grouped by book. The tray
  // ignores the 167 filters on purpose: once checked, a pick stays visible
  // here even when the view above hides its row.
  // GLOW-UP 170: the tray shows the union of the session slate queue and
  // the event's persisted placed legs — after a reload the queue is empty
  // but placed legs still surface here (marked ●, un-place to drop them).
  // Shared with the 171 slip-export handlers, which need the same view.
  const trayUnionNow = (): Map<string, BestPicksSlatePick> => {
    const u = new Map<string, BestPicksSlatePick>(bestPicksSlate);
    for (const [k, r] of bestPicksPlaced) { if (!u.has(k)) u.set(k, r); }
    return u;
  };
  const buildSlateTray = (): string => {
    const trayUnion = trayUnionNow();
    if (!trayUnion.size) return '';
    const groups = new Map<string, BestPicksSlatePick[]>();
    for (const p of trayUnion.values()) {
      const k = p.book || 'unbooked';
      const list = groups.get(k) || [];
      list.push(p);
      groups.set(k, list);
    }
    // GLOW-UP 169: shared-fight detection inside the slate — two checked
    // legs from one fight is concentrated variance the user should see
    // before building an entry. Keyed on raw names (see opponentRaw).
    const slateFightKeyOf = (p: BestPicksSlatePick): string =>
      p.opponentRaw ? [p.name.toLowerCase(), p.opponentRaw.toLowerCase()].sort().join('|') : '';
    const slateFightCounts = new Map<string, number>();
    for (const p of trayUnion.values()) {
      const k = slateFightKeyOf(p);
      if (k) slateFightCounts.set(k, (slateFightCounts.get(k) || 0) + 1);
    }
    const sharedFightCount = [...slateFightCounts.values()].filter(c => c > 1).length;
    const sharedWarn = sharedFightCount > 0
      ? `<span class="bps-warn" title="Legs marked ⚠ below come from the same fight — one result swings multiple legs at once">⚠ ${sharedFightCount} shared fight${sharedFightCount === 1 ? '' : 's'}</span>`
      : '';
    const presentBooks = BP_SLATE_BOOK_ORDER.filter(b => groups.has(b));
    const bookTallies = presentBooks.map(b => `<span class="bps-tally-book plat-${b}">${BP_SLATE_BOOK_ABBR[b]} ${groups.get(b)!.length}</span>`).join('');
    const groupsHtml = presentBooks.map(b => {
      const list = groups.get(b)!;
      const entries = list.map(p => {
        // GLOW-UP 211b: use the key the pick was STORED under. Rebuilding it here
        // dropped the book segment on book-targeted picks (`…|betr`), so the
        // lookup missed and ○ PLACE did nothing at all — and the ✕ beside it was
        // removing by the same wrong key. The reconstruction survives only as the
        // fallback for picks persisted before `key` existed, which were all
        // three-part by definition.
        const key = p.key || `${p.name}|${p.dir.toLowerCase()}|${p.source}`;
        const fk = slateFightKeyOf(p);
        const corrWarn = fk && (slateFightCounts.get(fk) || 0) > 1
          ? ` <span class="bps-corr" title="Another checked leg comes from this same fight — correlated legs on one slip">⚠</span>`
          : '';
        // GLOW-UP 170: ○ PLACE ↔ ● PLACED toggle per leg; a placed leg loses
        // its ✕ (un-place first) so removal is always a deliberate two-step.
        const placed = bestPicksPlaced.has(key);
        const placeBtn = `<button class="bps-place${placed ? ' on' : ''}" data-place-key="${key.replace(/"/g, '&quot;')}" title="${placed ? 'Un-mark — removes this leg from the event’s placed record' : 'Mark placed — persists for this event and feeds actual-vs-suggested tracking'}">${placed ? '● PLACED' : '○ PLACE'}</button>`;
        return `<div class="bps-entry${placed ? ' is-placed' : ''}">
          <span class="bps-entry-main">${p.pretty} <b class="bps-dir ${p.dir === 'OVER' ? 'ov' : 'un'}">${p.dir}</b> <span class="bps-line">${p.line ?? '—'}</span> <i class="bps-stat">${p.statLabel}</i>${p.opponent ? `<span class="bps-vs"> vs ${p.opponent}</span>` : ''}${corrWarn}</span>
          ${placeBtn}${placed ? '' : `<button class="bps-remove" data-slate-key="${key.replace(/"/g, '&quot;')}" title="Remove from My Slate">✕</button>`}
        </div>`;
      }).join('');
      // GLOW-UP 171: per-book slip export — one click copies every leg in
      // this group as slip-ready lines (the ⧉ clip format, one per row).
      const groupCopyBtn = `<button class="bps-copy-group" data-copy-book="${b}" title="Copy all ${list.length} ${list[0].bookLabel} leg${list.length === 1 ? '' : 's'} as slip-ready lines">⧉ COPY ${list.length}</button>`;
      return `<div class="bps-group"><div class="bps-group-head plat-${b}">${list[0].bookLabel} <i>${list.length} leg${list.length === 1 ? '' : 's'}</i>${groupCopyBtn}</div>${entries}</div>`;
    }).join('');
    return `<div class="bp-slate-tray${bestPicksSlateOpen ? ' open' : ''}">
      <div class="bps-head" data-slate-head="1" title="${bestPicksSlateOpen ? 'Collapse' : 'Expand'} My Slate">
        <span class="bps-title">MY SLATE</span>
        <span class="bps-count">${trayUnion.size} leg${trayUnion.size === 1 ? '' : 's'}</span>
        ${bestPicksPlaced.size ? `<span class="bps-placed-tally" title="Legs marked placed for this event — persisted across reloads">● ${bestPicksPlaced.size} placed</span>` : ''}
        <span class="bps-books">${bookTallies}</span>
        ${sharedWarn}
        <button class="bps-copy-all" data-slate-copyall="1" title="Copy every leg in the tray as slip-ready lines, grouped in book order">⧉ COPY ALL</button>
        <button class="bps-clear" data-slate-clear="1" title="Empty the queued picks — placed records stay">CLEAR</button>
        <span class="bps-chevron">${bestPicksSlateOpen ? '▼' : '▲'}</span>
      </div>
      ${bestPicksSlateOpen ? `<div class="bps-body">${groupsHtml}</div>` : ''}
    </div>`;
  };
  container.innerHTML = hasAnyPicks
    ? bpControlsHtml + gridHtml + buildSlateTray()
    : '<div class="inline-empty-msg">No leans calculated yet — wait for UFCStats to finish loading</div>';

  // Hydrate Best Picks avatars from the cached headshot pipeline
  container.querySelectorAll<HTMLImageElement>('.bp-avatar-img[data-name]').forEach(img => {
    const nm = img.dataset['name'] || '';
    if (!nm) return;
    void fetchFighterImageUrl(nm)
      .then(url => {
        if (!url) return;
        img.onload = () => img.parentElement?.classList.add('has-img');
        img.src = url;
      })
      .catch(() => { /* cosmetic only */ });
  });

  // Click a pick to jump to that fighter's card
  container.querySelectorAll<HTMLElement>('.best-pick-row[data-jump]').forEach(el => {
    el.addEventListener('click', () => jumpToFighterCard(el.dataset['jump'] || ''));
  });
  // GLOW-UP 196 L2 — the shared-fight roll-up's leg buttons carry data-jump too, but
  // the handler above is scoped to .best-pick-row, so they need their own binding.
  container.querySelectorAll<HTMLElement>('.bpfr-leg[data-jump]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      jumpToFighterCard(btn.dataset['jump'] || '');
    });
  });

  // GLOW-UP 169: hovering a linked row lights up its same-fight counterpart
  // in the other column — the ↔/⇄ tag says a pair exists, the glow says WHERE.
  container.querySelectorAll<HTMLElement>('.best-pick-row[data-fightkey]').forEach(row => {
    const fk = row.dataset['fightkey'] || '';
    row.addEventListener('mouseenter', () => {
      container.querySelectorAll<HTMLElement>(`.best-pick-row[data-fightkey="${CSS.escape(fk)}"]`).forEach(r => {
        if (r !== row) r.classList.add('fight-glow');
      });
    });
    row.addEventListener('mouseleave', () => {
      container.querySelectorAll<HTMLElement>('.best-pick-row.fight-glow').forEach(r => r.classList.remove('fight-glow'));
    });
  });

  // GLOW-UP 167: command strip handlers — every change bumps the render seq
  // and re-renders (same in-flight-guard path the view switcher uses).
  // Clicking the active stat chip again returns to ALL.
  const bpRerender = (): void => { bestPicksRenderSeq++; void renderBestPicks(container, bestPicksRenderSeq); };
  container.querySelectorAll<HTMLElement>('[data-bp-sort]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['bpSort'] as BestPicksSortMode;
      if (v && v !== bestPicksSortMode) { bestPicksSortMode = v; bpRerender(); }
    });
  });
  container.querySelectorAll<HTMLElement>('[data-bp-stat]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['bpStat'] as BestPicksStatFilter;
      if (!v) return;
      bestPicksStatFilter = (bestPicksStatFilter === v ? 'all' : v);
      bpRerender();
    });
  });
  container.querySelectorAll<HTMLElement>('[data-bp-evonly]').forEach(btn => {
    btn.addEventListener('click', () => { bestPicksEvOnly = !bestPicksEvOnly; bpRerender(); });
  });
  // GLOW-UP 192 handlers
  /**
   * CLEAN / FLAGGED / 2+ CAVEATS all filter the SAME axis (how many caveats a
   * pick carries), so any two of them together describe an impossible pick and
   * blank the board — which reads as the app being broken, not as an empty
   * intersection. Selecting one clears the others; clicking the active one
   * turns it off. This also fixes the pre-existing CLEAN + FLAGGED dead end,
   * which could strand you on an empty board with no hint why.
   */
  const setCaveatView = (which: 'clean' | 'flagged' | 'severe'): void => {
    const wasOn = which === 'clean' ? bestPicksCleanOnly
      : which === 'flagged' ? bestPicksFlaggedOnly
      : bestPicksSevereOnly;
    bestPicksCleanOnly = false;
    bestPicksFlaggedOnly = false;
    bestPicksSevereOnly = false;
    if (!wasOn) {
      if (which === 'clean') bestPicksCleanOnly = true;
      else if (which === 'flagged') bestPicksFlaggedOnly = true;
      else bestPicksSevereOnly = true;
    }
    bpRerender();
  };
  container.querySelectorAll<HTMLElement>('[data-bp-cleanonly]').forEach(btn => {
    btn.addEventListener('click', () => setCaveatView('clean'));
  });
  // GLOW-UP 200 L4 — cut rows jump to the fighter's card.
  container.querySelectorAll<HTMLElement>('[data-bpnm-jump]').forEach(row => {
    row.addEventListener('click', (e) => {
      e.stopPropagation();
      jumpToFighterCard(row.dataset['bpnmJump'] || '');
    });
  });
  container.querySelectorAll<HTMLElement>('[data-bp-flaggedonly]').forEach(btn => {
    btn.addEventListener('click', () => setCaveatView('flagged'));
  });
  container.querySelectorAll<HTMLElement>('[data-bp-severeonly]').forEach(btn => {
    btn.addEventListener('click', () => setCaveatView('severe'));
  });
  container.querySelectorAll<HTMLElement>('[data-bp-bybook]').forEach(btn => {
    btn.addEventListener('click', () => { bestPicksByBook = !bestPicksByBook; bpRerender(); });
  });
  container.querySelectorAll<HTMLElement>('.bp-nearmiss .bpnm-head').forEach(head => {
    head.addEventListener('click', () => {
      _bpNearMissOpen = !_bpNearMissOpen;
      head.closest('.bp-nearmiss')?.classList.toggle('collapsed', !_bpNearMissOpen);
    });
  });
  // BY BOOK lines jump to the fighter card, same as a board row.
  container.querySelectorAll<HTMLElement>('.bpbb-line[data-jump]').forEach(row => {
    row.addEventListener('click', () => {
      const name = row.dataset['jump'];
      if (name) jumpToFighterCard(name);
    });
  });
  container.querySelectorAll<HTMLElement>('.bpc-reset').forEach(btn => {
    btn.addEventListener('click', () => {
      bestPicksSortMode = 'model';
      bestPicksStatFilter = 'all';
      bestPicksEvOnly = false;
      bestPicksCleanOnly = false;
      bestPicksFlaggedOnly = false;
      bestPicksSevereOnly = false;
      bpRerender();
    });
  });

  // GLOW-UP 168: slate handlers — toggle on rows, remove/clear/collapse in
  // the tray. Adding the first pick auto-opens the tray so it's discovered.
  container.querySelectorAll<HTMLElement>('.bp-slate-toggle').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset['slateKey'] || '';
      if (bestPicksSlate.has(key)) {
        bestPicksSlate.delete(key);
      } else {
        const d = slateRowData.get(key);
        if (!d) return;
        if (!bestPicksSlate.size) bestPicksSlateOpen = true;
        bestPicksSlate.set(key, d);
      }
      bpRerender();
    });
  });
  container.querySelectorAll<HTMLElement>('.bps-remove').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      bestPicksSlate.delete(btn.dataset['slateKey'] || '');
      bpRerender();
    });
  });
  // GLOW-UP 170: place toggle — mutate, persist, THEN re-render: the
  // re-render re-hydrates placed state from storage, so rendering before
  // the write lands would resurrect the pre-toggle state.
  container.querySelectorAll<HTMLElement>('.bps-place').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset['placeKey'] || '';
      if (bestPicksPlaced.has(key)) {
        bestPicksPlaced.delete(key);
      } else {
        const d = bestPicksSlate.get(key) || slateRowData.get(key);
        if (!d) return;
        bestPicksPlaced.set(key, { ...d, placedAt: Date.now() });
      }
      void persistBestPicksPlaced().then(() => bpRerender());
    });
  });
  container.querySelectorAll<HTMLElement>('[data-slate-clear]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      bestPicksSlate.clear();
      bestPicksSlateOpen = false;
      bpRerender();
    });
  });
  container.querySelectorAll<HTMLElement>('[data-slate-head]').forEach(el => {
    el.addEventListener('click', (e) => {
      if ((e.target as HTMLElement).closest('[data-slate-clear],[data-slate-copyall]')) return;
      bestPicksSlateOpen = !bestPicksSlateOpen;
      bpRerender();
    });
  });

  // GLOW-UP 171: slip export — per-book group copy + tray-wide COPY ALL.
  // Same flash-confirm pattern as the row ⧉; no re-render needed, so the
  // button restores itself after the flash.
  const copySlipLegs = (btn: HTMLElement, legs: BestPicksSlatePick[]): void => {
    if (!legs.length) return;
    const original = btn.textContent || '';
    const ordered = [...legs].sort((a, b) =>
      BP_SLATE_BOOK_ORDER.indexOf(a.book || 'unbooked') - BP_SLATE_BOOK_ORDER.indexOf(b.book || 'unbooked'));
    navigator.clipboard.writeText(ordered.map(p => p.clip).join('\n')).then(() => {
      btn.textContent = '✓ COPIED';
      btn.classList.add('copied');
      setTimeout(() => { btn.textContent = original; btn.classList.remove('copied'); }, 1200);
    }).catch(() => { /* clipboard denied — leave the button as-is */ });
  };
  container.querySelectorAll<HTMLElement>('.bps-copy-group').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const book = btn.dataset['copyBook'] || '';
      copySlipLegs(btn, [...trayUnionNow().values()].filter(p => (p.book || 'unbooked') === book));
    });
  });
  container.querySelectorAll<HTMLElement>('.bps-copy-all').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      copySlipLegs(btn, [...trayUnionNow().values()]);
    });
  });

  // GLOW-UP 162 (level-up 5): copy-to-slip — ⧉ button copies a slip-ready
  // pick line; stopPropagation keeps the row's jump-to-card click intact.
  container.querySelectorAll<HTMLElement>('.bp-copy').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const txt = btn.dataset['clip'] || '';
      navigator.clipboard.writeText(txt).then(() => {
        btn.textContent = '✓';
        btn.classList.add('copied');
        setTimeout(() => { btn.textContent = '⧉'; btn.classList.remove('copied'); }, 1200);
      }).catch(() => { /* clipboard denied — leave the button as-is */ });
    });
  });

  renderModelHealthWidget();
  })();
}

// ── GLOW-UP 199 — memory-tag helpers, hoisted to module scope ─────────────
// These were closures inside persistBestPicksSnapshot. The Learning Drilldown
// now needs to tag LIVE board fighters with the same vocabulary the archive was
// tagged with, and the two must classify identically or the directive would
// count fighters the snapshot wouldn't. Same reason leanFactorLabel was hoisted
// in GLOW-UP 184.
function resolveOpponentDbFor(f: AnalyzerFighter): FighterDB | null {
  const normalizedOpp = normalizeName(f.opponent || '')?.toLowerCase() || '';
  const opponent = normalizedOpp
    ? (_fighterByNorm?.get(normalizedOpp) || allFighters.find((entry) => (normalizeName(entry.name) || entry.name).toLowerCase() === normalizedOpp) || null)
    : null;
  return opponent?.db?.loaded ? opponent.db : null;
}

function sourceAverageForFighter(f: AnalyzerFighter, source: LeanSource): number | null {
  const history = f.db?.history || [];
  if (source === 'fp') return activePlatformAvgFP(f.db) ?? f.db.avgFP_weighted ?? f.db.avgFP ?? null;
  const pick = (get: (fight: FightResult) => number | null | undefined): number | null => {
    const values = history.map(get).filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
    return values.length ? values.reduce((s, v) => s + v, 0) / values.length : null;
  };
  if (source === 'ss') return pick((fight) => fight.sigStr);
  if (source === 'ss_r1') return pick((fight) => fight.sigStrR1);
  if (source === 'td') return pick((fight) => fight.td);
  const mins = history
    .map((fight) => Number(fight.timeSecs) / 60)
    .filter((v): v is number => Number.isFinite(v) && v > 0);
  return mins.length ? mins.reduce((s, v) => s + v, 0) / mins.length : null;
}

// GLOW-UP 199 — the Learning Drilldown's two directives, cached at module scope
// so the slate filter can reach them. The panel derived them and then dropped
// them on the floor: it said "LEAN INTO SS UNDER · split markets" without ever
// naming which of tonight's fighters actually qualify.
let _memoryDirectives: { lean: ConfidenceMemorySignal | null; fade: ConfidenceMemorySignal | null } = { lean: null, fade: null };

/** Does this fighter's live lean carry the directive's source + side + tag? */
function fighterMatchesDirective(f: AnalyzerFighter, sig: ConfidenceMemorySignal | null): boolean {
  if (!sig) return false;
  const el = getEffectiveLean(f);
  if (el.lean !== sig.lean) return false;
  if ((el._source || 'fp') !== sig.source) return false;
  // Must mirror countDirectiveMatches exactly, or the filtered board would show
  // rows the count didn't include.
  if (shouldSkipFpSideForFighter(f, el._source, el.lean, el._platform)) return false;
  return memoryTagsForFighter(f, sig.source, el).includes(sig.tag);
}

/**
 * How many board fighters match a directive — full (source+side+tag) and
 * sideOnly (source+side, tag ignored). The split matters: "none on this card"
 * is ambiguous on its own, since it can mean nobody leans that way OR that
 * several do but none carry the tag. Reporting both also proves the matcher is
 * live rather than silently returning zero.
 */
function countDirectiveMatches(sig: ConfidenceMemorySignal | null): { full: number; sideOnly: number } {
  const out = { full: 0, sideOnly: 0 };
  if (!sig || !allFighters.length) return out;
  for (const f of allFighters) {
    if (isCancelledFighter(f.name)) continue;
    const el = getEffectiveLean(f);
    if (el.lean !== sig.lean || (el._source || 'fp') !== sig.source) continue;
    // Same placeability gate updateViewTabCounts uses, so a directive can never
    // point at a side no book will take (a dog's FP UNDER on Betr/Pick6). Without
    // it these counts also disagreed with the LEAN OVER/UNDER tab badges.
    if (shouldSkipFpSideForFighter(f, el._source, el.lean, el._platform)) continue;
    out.sideOnly++;
    if (memoryTagsForFighter(f, sig.source, el).includes(sig.tag)) out.full++;
  }
  return out;
}

/** Context tags for a live board fighter, in the archive's tag vocabulary. */
function memoryTagsForFighter(f: AnalyzerFighter, source: LeanSource, el: LeanResult): string[] {
  const activeLine = getSourceActiveLine(f, source);
  if (activeLine == null || !f.db?.loaded) return [];
  return deriveConfidenceMemoryTagsLive({
    fighterName: f.name,
    source,
    lean: el.lean,
    baseConfidence: el.conf || 0,
    score: el.score ?? 0,
    db: f.db,
    avgValue: sourceAverageForFighter(f, source),
    line: activeLine,
    selectedLine: activeLine,
    availableLines: getSourceLineEntries(f, source).map((entry) => entry.value),
    oppDB: resolveOpponentDbFor(f),
    moneyline: f.moneyline ?? null,
  });
}

/** One entry per rendered pick: the fighter plus the lean the BOARD chose for that
 *  column. Passing the lean in (rather than recomputing it here) is the whole point —
 *  best_picks_snapshots_v1 is what the learning engine grades against results, so a
 *  second derivation that drifts silently poisons every accuracy number. Same lesson
 *  as the report-card export (ccf538c): one resolve, shared. */
type BestPicksSnapshotEntry = {
  fighter: AnalyzerFighter;
  lean: EffectiveLean | null;
  /** The line and book the ROW DISPLAYS — resolved at the call site by the same helpers
   *  the renderer uses. Never re-derive these here; that is the drift this replaced. */
  line?: number | null;
  book?: SourcePlatformKey | null;
};

const BOOK_LABELS: Record<string, string> = { pick6: 'Pick6', underdog: 'Underdog', prizepicks: 'PrizePicks', betr: 'Betr', draftkings_sportsbook: 'DK Sportsbook' };

async function persistBestPicksSnapshot(overs: BestPicksSnapshotEntry[], unders: BestPicksSnapshotEntry[]): Promise<void> {
  try {
    const resolveOpponentDb = resolveOpponentDbFor;

    const getSourceAverageFromFighter = (f: AnalyzerFighter, source: LeanSource): number | null => {
      const history = f.db?.history || [];
      if (source === 'fp') return activePlatformAvgFP(f.db) ?? f.db.avgFP_weighted ?? f.db.avgFP ?? null;
      if (source === 'ss') {
        const values = history.map((fight) => fight.sigStr).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
        return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
      }
      if (source === 'ss_r1') {
        const values = history.map((fight) => fight.sigStrR1).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
        return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
      }
      if (source === 'td') {
        const values = history.map((fight) => fight.td).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
        return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
      }
      const values = history
        .map((fight) => Number(fight.timeSecs) / 60)
        .filter((value): value is number => Number.isFinite(value) && value > 0);
      return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
    };

    const buildMemoryTagsForFighter = (f: AnalyzerFighter, source: LeanSource, el: LeanResult): string[] => {
      const activeLine = getSourceActiveLine(f, source);
      if (activeLine == null || !f.db?.loaded) return [];
      const context: ConfidenceMemoryContext = {
        fighterName: f.name,
        source,
        lean: el.lean,
        baseConfidence: el.conf || 0,
        score: el.score ?? 0,
        db: f.db,
        avgValue: getSourceAverageFromFighter(f, source),
        line: activeLine,
        selectedLine: activeLine,
        availableLines: getSourceLineEntries(f, source).map((entry) => entry.value),
        oppDB: resolveOpponentDb(f),
        moneyline: f.moneyline ?? null,
      };
      return deriveConfidenceMemoryTagsLive(context);
    };

    const normalizePick = (entry: BestPicksSnapshotEntry, lean: 'over' | 'under') => {
      const f = entry.fighter;
      // Fall back only if the column somehow had no lean in its own direction — that
      // would be a builder bug, and logging the effective lean is better than nothing.
      const el = entry.lean || getEffectiveLean(f);
      const source = el._source || 'fp';
      return {
        fighter: f.name,
        opponent: f.opponent || null,
        lean,
        line: entry.line !== undefined ? entry.line : getSourceActiveLine(f, source),
        platform: entry.book
          ? (BOOK_LABELS[entry.book] || entry.book)
          : formatSourcePlatformLabel(f, source),
        source,
        confidence: el.conf || 0,
        confidenceGrade: el.confidenceGrade || getConfidenceGrade(el.conf || 0),
        // Written but not yet read here — the placed ledger still reports raw confidence.
        // Snapshots are write-once history and cannot be backfilled, so this starts being
        // recorded now; the ledger can switch to it whenever that panel gets audited.
        displayedConfidence: displayedConfFor(f, el),
        verdict: el.verdict || '',
        memoryTags: buildMemoryTagsForFighter(f, source, el),
        modelVersion: MODEL_VERSION,
      };
    };

    const picks = [
      ...overs.map((e) => normalizePick(e, 'over')),
      ...unders.map((e) => normalizePick(e, 'under')),
    ];

    if (!picks.length) return;

    const eventName = (upcomingEventName || '').trim() || 'Unknown Event';
    const date = new Date().toISOString();
    const key = `${eventName}|${date.slice(0, 10)}`;

    const payload = await storageGet<Record<string, unknown>>([STORAGE_BEST_PICKS_SNAPSHOT_KEY]);
    const current = Array.isArray(payload[STORAGE_BEST_PICKS_SNAPSHOT_KEY])
      ? (payload[STORAGE_BEST_PICKS_SNAPSHOT_KEY] as Array<any>)
      : [];

    const snapshot = {
      key,
      event: eventName,
      date,
      modelVersion: MODEL_VERSION,
      total: picks.length,
      overs: overs.length,
      unders: unders.length,
      picks,
    };

    const merged = [snapshot, ...current.filter((x) => String(x?.key || '') !== key)].slice(0, 60);
    await storageSet({ [STORAGE_BEST_PICKS_SNAPSHOT_KEY]: merged });
  } catch (e) {
    debugLog(`snapshot save failed: ${(e as Error).message}`);
  }
}

async function persistAiLeanSnapshot(fighters: AnalyzerFighter[]): Promise<void> {
  try {
    if (!fighters.length) return;

    const eventName = (upcomingEventName || '').trim();
    const eventDate = (document.getElementById('eventDate')?.textContent || '').trim();
    if (!eventName) return;

    // The caller fires this and initRecalibrationMap as two un-awaited voids, so on a cold
    // load the map is still null here and every displayedConfidence would quietly fall back
    // to the un-recalibrated number — recalibrated on a warm re-render, not on a fresh load.
    // Awaiting makes the stored value deterministic; it early-returns once populated.
    await initRecalibrationMap();
    const recalReady = isRecalibrationReady();

    const picks = fighters
      .map((f) => {
        const el = getEffectiveLean(f);
        const displayedConf = displayedConfFor(f, el);
        const source = el._source || 'fp';
        const activeLine = getSourceActiveLine(f, source);
        const activePlatform = getSourceActivePlatformKey(f, source);
        const opponentNorm = normalizeName(f.opponent || '')?.toLowerCase() || '';
        const opponent = opponentNorm
          ? (_fighterByNorm?.get(opponentNorm) || allFighters.find((entry) => (normalizeName(entry.name) || entry.name).toLowerCase() === opponentNorm) || null)
          : null;
        const avgValue = source === 'fp'
          ? (activePlatformAvgFP(f.db) ?? f.db.avgFP_weighted ?? f.db.avgFP ?? null)
          : source === 'ss'
            ? (() => {
                const values = (f.db?.history || []).map((fight) => fight.sigStr).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
                return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
              })()
            : source === 'ss_r1'
            ? (() => {
                const values = (f.db?.history || []).map((fight) => fight.sigStrR1).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
                return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
              })()
            : source === 'td'
              ? (() => {
                  const values = (f.db?.history || []).map((fight) => fight.td).filter((value): value is number => typeof value === 'number' && Number.isFinite(value));
                  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
                })()
              : (() => {
                  const values = (f.db?.history || [])
                    .map((fight) => Number(fight.timeSecs) / 60)
                    .filter((value): value is number => Number.isFinite(value) && value > 0);
                  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
                })();
        const memoryTags = activeLine != null && f.db?.loaded
          ? deriveConfidenceMemoryTagsLive({
              fighterName: f.name,
              source,
              lean: el.lean,
              baseConfidence: el.conf || 0,
              score: el.score ?? 0,
              db: f.db,
              avgValue,
              line: activeLine,
              selectedLine: activeLine,
              availableLines: getSourceLineEntries(f, source).map((entry) => entry.value),
              oppDB: opponent?.db?.loaded ? opponent.db : null,
              moneyline: f.moneyline ?? null,
            })
          : [];
        return {
          fighter: f.name,
          opponent: f.opponent || null,
          lean: el.lean,
          source,
          // RAW confidence — before the CLV boost, before recalibration. This is the domain
          // the recalibration map and the confidence-memory engine are keyed on, so it must
          // stay raw: feeding either of them their own output compounds the correction every
          // cycle. Readout panels want displayedConfidence below instead.
          confidence: el.conf || 0,
          confidenceGrade: el.confidenceGrade || getConfidenceGrade(el.conf || 0),
          // What the BOARD actually showed: raw → CLV boost → clamp → recalibration.
          // recalibrationReady records whether the map was live when this was taken, so a
          // readout can tell a real displayed value from a boosted-but-uncorrected one.
          displayedConfidence: displayedConf,
          displayedConfidenceGrade: displayedConf > 0 ? getConfidenceGrade(displayedConf) : '',
          recalibrationReady: recalReady,
          verdict: el.verdict || '',
          score: el.score ?? null,
          activePlatform,
          activeLine,
          memoryVersion: CONFIDENCE_MEMORY_VERSION,
          memoryTags,
          lines: {
            pick6: { fp: f.line_p6 ?? null, ss: f.line_p6_ss ?? null, td: f.line_p6_td ?? null, ft: f.line_p6_ft ?? null },
            underdog: { fp: f.line_ud ?? null, ss: f.line_ud_ss ?? null, td: f.line_ud_td ?? null, ft: f.line_ud_ft ?? null },
            prizepicks: { fp: f.line_pp ?? null, ss: f.line_pp_ss ?? null, td: f.line_pp_td ?? null, ft: f.line_pp_ft ?? null },
            betr: { fp: f.line_betr ?? null, ss: f.line_betr_ss ?? null, td: f.line_betr_td ?? null, ft: f.line_betr_ft ?? null },
            draftkings_sportsbook: { ss: f.line_dk_ss ?? null, td: f.line_dk_td ?? null, ft: f.line_dk_ft ?? null },
          },
        };
      })
      .filter((pick) => pick.lean !== 'none' && pick.lean !== 'push' && Number.isFinite(Number(pick.activeLine)));

    if (!picks.length) return;

    const keyDate = eventDate || new Date().toISOString().slice(0, 10);
    const key = `${eventName}|${keyDate}`;
    const signature = JSON.stringify(
      picks
        .map((pick) => ({ fighter: pick.fighter, lean: pick.lean, source: pick.source, line: pick.activeLine, confidence: pick.confidence }))
        .sort((a, b) => a.fighter.localeCompare(b.fighter))
    );

    const payload = await storageGet<Record<string, unknown>>([STORAGE_AI_LEAN_SNAPSHOT_KEY]);
    const current = Array.isArray(payload[STORAGE_AI_LEAN_SNAPSHOT_KEY])
      ? (payload[STORAGE_AI_LEAN_SNAPSHOT_KEY] as Array<any>)
      : [];

    const existing = current.find((entry) => String(entry?.key || '') === key);
    if (existing && String(existing?.signature || '') === signature) return;

    const snapshot = {
      key,
      event: eventName,
      eventDate: keyDate,
      capturedAt: new Date().toISOString(),
      totalLeans: picks.length,
      overCount: picks.filter((pick) => pick.lean === 'over').length,
      underCount: picks.filter((pick) => pick.lean === 'under').length,
      signature,
      picks,
    };

    const merged = [snapshot, ...current.filter((entry) => String(entry?.key || '') !== key)].slice(0, 80);
    await storageSet({ [STORAGE_AI_LEAN_SNAPSHOT_KEY]: merged });
  } catch (e) {
    debugLog(`AI lean snapshot save failed: ${(e as Error).message}`);
  }
}

// ── PARLAY LAB / CORRELATION ENGINE ──────────────────────────────────────

interface ParlayLeg {
  fighter: string;
  opponent: string;
  stat: LeanSource;
  direction: 'over' | 'under';
  line: number;
  confidence: number;
  tier: string;
  platform: string;
  /** GLOW-UP 207 — OFF-BOARD legs. The pool only ever contained the model's own
   *  lean side, so the other side of a prop and a prop the model has no read on
   *  were simply not parlayable here. These now appear BELOW the ranked pool,
   *  flagged, with the reason they didn't make it. Building a slip is the user's
   *  call; the model's silence on a prop is information, not a lock on the board.
   *  (GLOW-UP 208 promoted R1 SS / CTRL / KD into the ranked tier, so what lands
   *  here is a complement, a no-read, or a side the market won't carry.) */
  offBoard?: boolean;
  /** Why this leg isn't in the ranked pool — rendered as the flag's tooltip. */
  offReason?: string;
  /** Direction-aware best book for an off-board side (null = no book posts it).
   *  Ranked legs resolve their book from the active platform as before. */
  bookKey?: string | null;
}

interface CorrelationAlert {
  type: 'synergy' | 'conflict' | 'caution' | 'neutral';
  leg1: string; // fighter name
  leg2: string;
  message: string;
  impact: number; // -1 to +1 score impact
}

interface ParlayHealth {
  score: number; // 0-100
  grade: 'excellent' | 'good' | 'fair' | 'poor';
  alerts: CorrelationAlert[];
  avgConfidence: number;
  legCount: number;
  /** GLOW-UP 197 L1 — the score's component parts. It's assembled from four
   *  distinct terms and then shown as one opaque number, so a 93 gave no hint
   *  what to change to improve it. */
  breakdown?: {
    base: number;      // average leg confidence — the starting point
    corr: number;      // sum of correlation-alert impacts (±)
    legs: number;      // leg-count bonus/penalty (2-4 sweet spot, 6+ penalised)
    diversity: number; // all legs from different fights
  };
}

const parlaySelectedLegs: Set<string> = new Set(); // "fighter|stat|dir" keys

// GLOW-UP 177 (Parlay Lab level 1): pool command strip — view-only sort/
// filter over the AVAILABLE LEGS pool. Session-scoped (resets on reload):
// changes what's drawn, never which legs exist or which are selected.
type ParlaySortMode = 'conf' | 'ev' | 'tier';
type ParlayStatFilter = 'all' | LeanSource;
let parlayPoolSort: ParlaySortMode = 'conf';
let parlayPoolStat: ParlayStatFilter = 'all';
let parlayPoolDir: 'all' | 'over' | 'under' = 'all';
// GLOW-UP 246: filter the pool to props you've already marked placed. Same
// session-scoped, draw-only contract as the rest of the strip.
let parlayPoolPlacedOnly = false;
// GLOW-UP 207: off-board section is collapsed by default — it is deliberately
// the LONGER of the two lists (every side of every prop), and expanding it by
// default would bury the ranked pool the view is built around.
let parlayPoolShowOffBoard = false;

/**
 * GLOW-UP 211 — `book` is part of the identity for FP only. FP lines aren't
 * comparable across books, so Pick6 93.5 and Betr 85.5 are two different legs and
 * must not share a key; every other stat IS line-shopped to one best book, so its
 * key stays three-part. Session-scoped (`parlaySelectedLegs`), so widening it
 * carries no migration cost.
 */
function parlayLegKey(fighter: string, stat: LeanSource, dir: string, book?: string | null): string {
  return `${fighter}|${stat}|${dir}${book ? `|${book}` : ''}`;
}
/**
 * The key for a leg, book-qualified.
 *
 * GLOW-UP 227 — this used to book-qualify FP only, on the reasoning that every
 * other stat is line-shopped down to one best book. That reasoning describes
 * SHOPPING, not PLACING: books post genuinely different numbers on the same prop
 * (Machado Garry R1 SS was PP 6.5, DK 7.5, UD 13.5), and a leg already placed at
 * one of them has to be selectable as itself. Every book now gets its own leg, so
 * every leg needs its own key. Selection is session-scoped and placed parlays are
 * persisted by leg VALUES (`fighter|stat|dir` signature), so widening this key
 * carries no migration.
 */
function parlayLegKeyOf(l: ParlayLeg): string {
  return parlayLegKey(l.fighter, l.stat, l.direction, l.bookKey ?? null);
}

/**
 * GLOW-UP 208 — why the RANKED pool won't score this (stat, side). Null means it
 * will.
 *
 * One source of truth for BOTH leg collectors. `renderParlayLab` and
 * `suggestParlays` build near-identical pools independently, and drift between
 * them is exactly how R1 SS, CTRL and KD stayed unrankable in the Lab long after
 * the board had adopted them — so the rule lives in one place now.
 *
 * It doubles as the off-board tier's explanation text, which means a leg's flag
 * can never disagree with the rule that demoted it.
 *
 * Mirrors renderBestPicks' `isCandidateUsable`: R1 SS needs no side gating
 * (calcSSR1Lean's confidence gating does that upstream), KD is standard-projection
 * only, CTRL is over-only. The board and the Lab now agree family for family.
 */
function parlayUnrankableReason(f: AnalyzerFighter, stat: LeanSource, dir: 'over' | 'under'): string | null {
  // FP placeability (no-ops for every other stat): a dog's FP UNDER is Underdog-
  // only, and Betr prices a dog's OVER at +money rather than true pick-em.
  if (shouldSkipFpSideForFighter(f, stat, dir)) {
    return 'No book posts this FP side for this fighter — a dog’s FP UNDER is Underdog-only, and Betr prices a dog’s OVER at +money rather than true pick-em value.';
  }
  // Knockdowns are PrizePicks-only. A standard projection posts More AND Less;
  // demon/goblin cards are More-only on a non-standard payout, so NEITHER side is
  // an ordinary pick-em play — the board keeps those display-only.
  if (stat === 'kd' && f.kd_under_available !== true) {
    return 'PrizePicks prices this knockdowns prop More-only (demon/goblin) — the non-standard payout means neither side is a normal pick-em play, so it stays off the ranked board.';
  }
  // Control time is an over-only market (MODEL v16): Pick6 is the primary CTRL
  // book and gives these props no Less button, so an under lean is information
  // rather than a play.
  if (stat === 'ctrl' && dir !== 'over') {
    return 'Control time is an OVER-only market — Pick6 is the primary CTRL book and posts no Less button, so an under lean is information, not a play.';
  }
  // ── GLOW-UP 229 — the general case the three rules above kept missing ─────
  // Each of them names ONE market rule. None of them asked the plain question:
  // does any book take this side at all? So a TD UNDER whose only pick-em book
  // is More-only, with the sportsbook's other side priced as chalk, ranked
  // freely — on UFC 330 that put Barboza, Ribovics and Machado Garry at the top
  // of the pool at 90% and seeded all three AI suggestions with legs nobody
  // will write. Pick6 posts those three More-only and DK's under is -2500.
  //
  // leanBestBook already encodes every book rule (per-book under availability,
  // DK chalk exclusion, FP's per-book placeability), so this asks it directly
  // rather than adding a fourth hand-written rule to drift out of sync.
  if (leanBestBook(f, stat, dir).book == null) {
    return `No book takes this ${dir.toUpperCase()} — the pick-em books that post the prop are one-sided on it, or the sportsbook prices the side as chalk. It stays parlayable off-board; it just isn't a ranked play.`;
  }
  return null;
}

function areSameFight(f1: AnalyzerFighter, f2: AnalyzerFighter): boolean {
  if (!f1.opponent || !f2.opponent) return false;
  const n1 = (normalizeName(f1.name) || f1.name).toLowerCase();
  const n2 = (normalizeName(f2.name) || f2.name).toLowerCase();
  const o1 = (normalizeName(f1.opponent) || f1.opponent).toLowerCase();
  const o2 = (normalizeName(f2.opponent) || f2.opponent).toLowerCase();
  return (n1 === o2 && n2 === o1) || (n1 === o2) || (n2 === o1);
}

function areSameFighter(f1Name: string, f2Name: string): boolean {
  return (normalizeName(f1Name) || f1Name).toLowerCase() === (normalizeName(f2Name) || f2Name).toLowerCase();
}

/**
 * Correlation rules for parlay legs.
 *
 * Same-fight correlations (A fights B):
 *   A Over SS + B Over SS  → synergy (action fight = both land)
 *   A Over SS + B Under SS → conflict (contradictory: if fight is active, both land)
 *   A Over FP + B Over FP  → caution (counting stats can both go up, but win bonus goes to only one)
 *   A Over FP + B Under FP → synergy (one dominates)
 *   A Under FP + B Under FP→ caution (both low = short fight possible, but risky)
 *   A Over TD + B Over SS  → conflict (grappling eats striking time)
 *   A Over TD + B Over TD  → caution (one usually controls more)
 *
 * Same-fighter correlations:
 *   A Over SS + A Over FP  → synergy (strikes = biggest FP driver)
 *   A Over TD + A Over FP  → synergy (TDs contribute to FP)
 *   A Over SS + A Over TD  → caution (strikers don't usually wrestle)
 *   A Over SS + A Under TD → synergy (consistent striking style)
 *   A Over FP + A Under FP → impossible (filtered out)
 */
// ── Correlation-aware parlay joint probability ─────────────────────────────
// Inverse standard-normal CDF (Acklam's rational approximation) — maps a leg
// probability to its Gaussian-copula threshold.
function invNormalCDF(p: number): number {
  if (p <= 0) return -1e9;
  if (p >= 1) return 1e9;
  const a = [-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00];
  const b = [-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01];
  const c = [-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00];
  const d = [7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00];
  const plow = 0.02425, phigh = 1 - plow;
  if (p < plow) { const q = Math.sqrt(-2 * Math.log(p)); return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
  if (p <= phigh) { const q = p - 0.5, r = q * q; return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1); }
  const q = Math.sqrt(-2 * Math.log(1 - p)); return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
}

let _spareNorm: number | null = null;
function randn(): number {
  if (_spareNorm != null) { const s = _spareNorm; _spareNorm = null; return s; }
  let u = 0, v = 0; while (u === 0) u = Math.random(); while (v === 0) v = Math.random();
  const mag = Math.sqrt(-2 * Math.log(u)); _spareNorm = mag * Math.sin(2 * Math.PI * v); return mag * Math.cos(2 * Math.PI * v);
}

// Cholesky of a correlation matrix, shrinking off-diagonals toward identity until it's
// positive-definite (the heuristic ρ's aren't guaranteed PSD).
function choleskyCorr(sigma: number[][]): number[][] {
  const n = sigma.length;
  for (let lambda = 0; lambda <= 1.0001; lambda += 0.05) {
    const m = sigma.map((row, i) => row.map((val, j) => (i === j ? 1 : (1 - lambda) * val)));
    const L = Array.from({ length: n }, () => new Array<number>(n).fill(0));
    let ok = true;
    for (let i = 0; i < n && ok; i++) {
      for (let j = 0; j <= i; j++) {
        let sum = m[i][j];
        for (let k = 0; k < j; k++) sum -= L[i][k] * L[j][k];
        if (i === j) { if (sum <= 1e-9) { ok = false; break; } L[i][j] = Math.sqrt(sum); }
        else L[i][j] = sum / L[j][j];
      }
    }
    if (ok) return L;
  }
  return Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i === j ? 1 : 0)));
}

// Independent P(exactly k hits) via exact subset enumeration (n ≤ 6 → ≤ 64 terms).
function independentHitCounts(probs: number[]): number[] {
  const n = probs.length; const out = new Array<number>(n + 1).fill(0);
  for (let mask = 0; mask < (1 << n); mask++) {
    let p = 1, k = 0;
    for (let i = 0; i < n; i++) { if (mask & (1 << i)) { p *= probs[i]; k++; } else p *= 1 - probs[i]; }
    out[k] += p;
  }
  return out;
}

// Correlation-aware P(exactly k hits) via a Gaussian copula, Monte-Carlo'd: draw
// correlated normals, threshold each leg at its marginal, count hits. Same-fight legs
// (ρ ≠ 0) rise/fall together; cross-fight legs (ρ = 0) stay independent.
function correlatedHitCounts(probs: number[], rho: number[][], iters = 8000): number[] {
  const n = probs.length;
  const thresh = probs.map(p => invNormalCDF(1 - Math.min(0.999, Math.max(0.001, p))));
  const L = choleskyCorr(rho);
  const counts = new Array<number>(n + 1).fill(0);
  for (let it = 0; it < iters; it++) {
    const zr = new Array<number>(n); for (let i = 0; i < n; i++) zr[i] = randn();
    let k = 0;
    for (let i = 0; i < n; i++) { let zi = 0; for (let j = 0; j <= i; j++) zi += L[i][j] * zr[j]; if (zi >= thresh[i]) k++; }
    counts[k]++;
  }
  return counts.map(c => c / iters);
}

function calcPairCorrelation(
  leg1: ParlayLeg, f1: AnalyzerFighter,
  leg2: ParlayLeg, f2: AnalyzerFighter,
): CorrelationAlert | null {
  const sameFighter = areSameFighter(leg1.fighter, leg2.fighter);
  const sameFight = !sameFighter && areSameFight(f1, f2);

  if (sameFighter) {
    // Same fighter, different stat types
    const stats = [leg1.stat, leg2.stat].sort().join('+');
    const dirs = [leg1.direction, leg2.direction].sort().join('+');

    if (leg1.stat === leg2.stat) {
      // Same fighter, same stat, must be same direction (can't have both) — skip
      return null;
    }

    if (stats === 'fp+ss') {
      if (leg1.direction === leg2.direction) {
        // Both over or both under SS+FP = synergistic (strikes drive FP)
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: SS and FP move together — strikes are the #1 FP driver`, impact: 0.15 };
      }
      // SS Over + FP Under (or vice versa) = conflicting
      const ssLeg = leg1.stat === 'ss' ? leg1 : leg2;
      const fpLeg = leg1.stat === 'fp' ? leg1 : leg2;
      if (ssLeg.direction === 'over' && fpLeg.direction === 'under') {
        return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over SS but Under FP is contradictory — more strikes = more FP`, impact: -0.25 };
      }
      if (ssLeg.direction === 'under' && fpLeg.direction === 'over') {
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over FP with Under SS needs big TDs/ctrl/finish bonus to hit`, impact: -0.08 };
      }
    }

    if (stats === 'fp+td') {
      if (leg1.direction === leg2.direction) {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: TDs and FP move together — each TD = 5 FP`, impact: 0.10 };
      }
      const tdLeg = leg1.stat === 'td' ? leg1 : leg2;
      const fpLeg = leg1.stat === 'fp' ? leg1 : leg2;
      if (tdLeg.direction === 'over' && fpLeg.direction === 'under') {
        return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over TD but Under FP conflicts — TDs add FP directly`, impact: -0.20 };
      }
    }

    if (stats === 'ss+td') {
      if (leg1.direction === 'over' && leg2.direction === 'over') {
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over SS + Over TD is rare — grappling reduces striking time`, impact: -0.12 };
      }
      const ssLeg = leg1.stat === 'ss' ? leg1 : leg2;
      const tdLeg = leg1.stat === 'td' ? leg1 : leg2;
      if (ssLeg.direction === 'over' && tdLeg.direction === 'under') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over SS + Under TD is consistent — striker profile`, impact: 0.10 };
      }
      if (ssLeg.direction === 'under' && tdLeg.direction === 'over') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Under SS + Over TD is consistent — grappler profile`, impact: 0.10 };
      }
    }

    // FT combos
    if (leg1.stat === 'ft' || leg2.stat === 'ft') {
      const ftLeg = leg1.stat === 'ft' ? leg1 : leg2;
      const otherLeg = leg1.stat === 'ft' ? leg2 : leg1;
      if (ftLeg.direction === 'over' && otherLeg.stat !== 'ft') {
        // Longer fight = more counting stats
        if (otherLeg.direction === 'over') {
          return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over FT + Over ${otherLeg.stat.toUpperCase()} — longer fight = more stats`, impact: 0.12 };
        }
        return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Over FT but Under ${otherLeg.stat.toUpperCase()} — more time usually means more output`, impact: -0.15 };
      }
      if (ftLeg.direction === 'under') {
        if (otherLeg.direction === 'under' && otherLeg.stat !== 'fp') {
          return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Under FT + Under ${otherLeg.stat.toUpperCase()} — short fight = fewer stats`, impact: 0.10 };
        }
        if (otherLeg.direction === 'over' && otherLeg.stat === 'fp') {
          return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `${leg1.fighter}: Under FT + Over FP needs a dominant finish bonus to hit`, impact: -0.05 };
        }
      }
    }

    return null;
  }

  if (sameFight) {
    // Two fighters in the SAME fight (opponents)
    // SS correlations
    if (leg1.stat === 'ss' && leg2.stat === 'ss') {
      if (leg1.direction === leg2.direction) {
        // Both Over SS or both Under SS
        if (leg1.direction === 'over') {
          return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Over SS — action fight benefits both strikers`, impact: 0.18 };
        }
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Under SS — grapple-heavy or quick finish scenario`, impact: 0.12 };
      }
      // One Over, one Under SS in same fight
      return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `Opposite SS directions in same fight — if pace is high, both land`, impact: -0.22 };
    }

    // FP correlations in same fight
    if (leg1.stat === 'fp' && leg2.stat === 'fp') {
      if (leg1.direction === 'over' && leg2.direction === 'over') {
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Over FP in same fight — counting stats can both go up, but only one gets win bonus (30-90 pts)`, impact: -0.10 };
      }
      if (leg1.direction === 'under' && leg2.direction === 'under') {
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Under FP in same fight — needs quick finish (less time for either)`, impact: -0.08 };
      }
      // One Over, one Under FP = synergy (one dominates)
      return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `Over/Under FP split in same fight — dominant win scenario benefits both legs`, impact: 0.15 };
    }

    // TD correlations in same fight
    if (leg1.stat === 'td' && leg2.stat === 'td') {
      if (leg1.direction === 'over' && leg2.direction === 'over') {
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Over TD in same fight — one wrestler usually dominates position`, impact: -0.10 };
      }
      if (leg1.direction === leg2.direction) {
        return { type: 'neutral', leg1: leg1.fighter, leg2: leg2.fighter, message: `Both Under TD in same fight — stand-up war scenario`, impact: 0.05 };
      }
    }

    // Cross-stat in same fight
    if ((leg1.stat === 'td' && leg2.stat === 'ss') || (leg1.stat === 'ss' && leg2.stat === 'td')) {
      const tdLeg = leg1.stat === 'td' ? leg1 : leg2;
      const ssLeg = leg1.stat === 'ss' ? leg1 : leg2;
      if (tdLeg.direction === 'over' && ssLeg.direction === 'over') {
        // One guy wrestling, other landing strikes — possible but TDs eat clock
        return { type: 'caution', leg1: leg1.fighter, leg2: leg2.fighter, message: `${tdLeg.fighter} Over TD + ${ssLeg.fighter} Over SS — grappling reduces striking time for both`, impact: -0.08 };
      }
      if (tdLeg.direction === 'over' && ssLeg.direction === 'under') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${tdLeg.fighter} Over TD + ${ssLeg.fighter} Under SS — wrestling controls the fight`, impact: 0.15 };
      }
      if (tdLeg.direction === 'under' && ssLeg.direction === 'over') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${tdLeg.fighter} Under TD + ${ssLeg.fighter} Over SS — stand-up fight benefits striker`, impact: 0.12 };
      }
    }

    // FP + SS cross-stat in same fight
    if ((leg1.stat === 'fp' && leg2.stat === 'ss') || (leg1.stat === 'ss' && leg2.stat === 'fp')) {
      const fpLeg = leg1.stat === 'fp' ? leg1 : leg2;
      const ssLeg = leg1.stat === 'ss' ? leg1 : leg2;
      if (areSameFighter(fpLeg.fighter, ssLeg.fighter)) return null; // handled by same-fighter
      // Opponent's FP vs our SS
      if (ssLeg.direction === 'over' && fpLeg.direction === 'under') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `${ssLeg.fighter} Over SS + ${fpLeg.fighter} Under FP — one dominates on the feet`, impact: 0.12 };
      }
    }

    // FT in same fight. FT is the fight's DURATION, so it couples to every
    // stat that accumulates while the fight runs — all four quadrants of
    // (FT direction × volume direction) carry a signal, not just the two that
    // were here. The missing two returned null, i.e. "independent", which is
    // the one thing they are definitely not.
    //
    // ss_r1 and kd are deliberately NOT duration-coupled stats: R1 SS is capped
    // by a single round regardless of how long the fight runs, and a knockdown
    // tends to END fights, so it moves opposite to the others.
    if (leg1.stat === 'ft' || leg2.stat === 'ft') {
      const ftLeg = leg1.stat === 'ft' ? leg1 : leg2;
      const otherLeg = leg1.stat === 'ft' ? leg2 : leg1;
      const DURATION_COUPLED = ['ss', 'fp', 'td', 'ctrl'];
      const vol = DURATION_COUPLED.includes(otherLeg.stat);
      const S = otherLeg.stat.toUpperCase();
      if (vol && ftLeg.direction === 'over' && otherLeg.direction === 'over') {
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `Over FT + ${otherLeg.fighter} Over ${S} — longer fight = more counting stats`, impact: 0.12 };
      }
      if (vol && ftLeg.direction === 'under' && otherLeg.direction === 'over') {
        return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `Under FT + ${otherLeg.fighter} Over ${S} — quick finish cuts counting time`, impact: -0.18 };
      }
      // NEW: the two quadrants that used to fall through.
      if (vol && ftLeg.direction === 'over' && otherLeg.direction === 'under') {
        // Rounds keep accruing, so staying UNDER a volume line gets harder the
        // longer the fight runs. Rated softer than its mirror above on purpose:
        // a quick finish HARD-CAPS volume, whereas a long fight only tends to
        // raise it — a grindy control-heavy decision can run long and still
        // finish under on strikes.
        return { type: 'conflict', leg1: leg1.fighter, leg2: leg2.fighter, message: `Over FT + ${otherLeg.fighter} Under ${S} — more rounds means more time to clear the ${S} line`, impact: -0.14 };
      }
      if (vol && ftLeg.direction === 'under' && otherLeg.direction === 'under') {
        // A finish suppresses duration and volume together — these want the
        // same fight. Slightly stronger than the over/over case because the cap
        // is hard rather than a tendency.
        return { type: 'synergy', leg1: leg1.fighter, leg2: leg2.fighter, message: `Under FT + ${otherLeg.fighter} Under ${S} — a finish suppresses duration and ${S} together`, impact: 0.15 };
      }
    }

    return null;
  }

  // Different fights — generally independent
  return null;
}

function analyzeParlayHealth(legs: ParlayLeg[], fighters: AnalyzerFighter[]): ParlayHealth {
  const alerts: CorrelationAlert[] = [];
  const fighterMap = new Map<string, AnalyzerFighter>();
  for (const f of fighters) {
    fighterMap.set((normalizeName(f.name) || f.name).toLowerCase(), f);
  }

  // Check all pairs
  for (let i = 0; i < legs.length; i++) {
    for (let j = i + 1; j < legs.length; j++) {
      const f1 = fighterMap.get((normalizeName(legs[i].fighter) || legs[i].fighter).toLowerCase());
      const f2 = fighterMap.get((normalizeName(legs[j].fighter) || legs[j].fighter).toLowerCase());
      if (!f1 || !f2) continue;
      const alert = calcPairCorrelation(legs[i], f1, legs[j], f2);
      if (alert) alerts.push(alert);
    }
  }

  const avgConfidence = legs.length > 0 ? legs.reduce((s, l) => s + l.confidence, 0) / legs.length : 0;

  // Score: start at base from average confidence, adjust by correlation alerts
  let score = avgConfidence;
  let corrTerm = 0;
  for (const a of alerts) {
    corrTerm += a.impact * 30; // each ±0.1 impact = ±3 points on health score
  }
  score += corrTerm;

  // Leg count bonus/penalty
  let legsTerm = 0;
  if (legs.length >= 2 && legs.length <= 4) legsTerm += 3; // sweet spot
  if (legs.length >= 6) legsTerm -= (legs.length - 5) * 4; // diminishing odds
  score += legsTerm;

  // Diversity bonus: legs from different fights
  const fightKeys = new Set(legs.map(l => [l.fighter, l.opponent].sort().join('vs')));
  let diversityTerm = 0;
  if (fightKeys.size >= 2 && fightKeys.size === legs.length) diversityTerm += 5; // all independent fights
  score += diversityTerm;

  score = Math.max(0, Math.min(100, Math.round(score)));
  const grade: ParlayHealth['grade'] =
    score >= 78 ? 'excellent' : score >= 60 ? 'good' : score >= 40 ? 'fair' : 'poor';

  return {
    score, grade, alerts, avgConfidence, legCount: legs.length,
    breakdown: {
      base: parseFloat(avgConfidence.toFixed(1)),
      corr: parseFloat(corrTerm.toFixed(1)),
      legs: legsTerm,
      diversity: diversityTerm,
    },
  };
}

/** Scan all available legs and surface pairs with positive correlation (synergy). */
function findCorrelatedPairs(
  availableLegs: { leg: ParlayLeg; fighter: AnalyzerFighter }[],
): { leg1: ParlayLeg; leg2: ParlayLeg; alert: CorrelationAlert }[] {
  const pairs: { leg1: ParlayLeg; leg2: ParlayLeg; alert: CorrelationAlert }[] = [];
  const seen = new Set<string>();
  for (let i = 0; i < availableLegs.length; i++) {
    for (let j = i + 1; j < availableLegs.length; j++) {
      const a = availableLegs[i];
      const b = availableLegs[j];
      // Skip duplicate fighter+stat combos
      const n1 = (normalizeName(a.leg.fighter) || a.leg.fighter).toLowerCase();
      const n2 = (normalizeName(b.leg.fighter) || b.leg.fighter).toLowerCase();
      if (n1 === n2 && a.leg.stat === b.leg.stat) continue;
      const alert = calcPairCorrelation(a.leg, a.fighter, b.leg, b.fighter);
      if (!alert || alert.type !== 'synergy') continue;
      // Dedup by sorted fighter+stat key
      const pairKey = [`${n1}|${a.leg.stat}|${a.leg.direction}`, `${n2}|${b.leg.stat}|${b.leg.direction}`].sort().join('~');
      if (seen.has(pairKey)) continue;
      seen.add(pairKey);
      pairs.push({ leg1: a.leg, leg2: b.leg, alert });
    }
  }
  // Sort by combined confidence descending, then impact
  pairs.sort((a, b) => {
    const confA = a.leg1.confidence + a.leg2.confidence;
    const confB = b.leg1.confidence + b.leg2.confidence;
    if (confB !== confA) return confB - confA;
    return b.alert.impact - a.alert.impact;
  });
  return pairs.slice(0, 8); // cap at 8 most confident pairs
}

/** Suggest top parlay combinations from available leans */
/**
 * GLOW-UP 227 — ONE ranked-leg builder, for both pools.
 *
 * `renderParlayLab` and `suggestParlays` each built a near-identical leg from the
 * same lean, which is the shape that keeps biting this codebase: the moment the
 * Lab's leg started resolving its line direction-aware, the suggestions beside it
 * would still have been quoting the active-platform number for the same pick —
 * and their legs, lacking a bookKey, would no longer have matched a pool key at
 * all, breaking LOAD. Derived once here; both callers consume it.
 *
 * Returns null when the lean has no side, no line, or a market rule keeps the
 * side off the ranked board.
 */
function buildRankedParlayLeg(
  f: AnalyzerFighter,
  lean: LeanResult | null | undefined,
  stat: LeanSource,
): ParlayLeg | null {
  if (!lean || lean.lean === 'none' || lean.lean === 'push') return null;
  const dir = lean.lean as 'over' | 'under';
  // FP excluded from best-book shopping on purpose: its books score fantasy
  // points differently, so there is no better or worse line to shop for.
  const best = stat === 'fp'
    ? { book: null as string | null, line: null as number | null }
    : leanBestBook(f, stat, dir);
  const line = best.line ?? getSourceActiveLine(f, stat);
  if (line == null) return null;
  if (parlayUnrankableReason(f, stat, dir)) return null;
  const conf = lean.conf || 0;
  return {
    fighter: f.name,
    opponent: f.opponent || '?',
    stat,
    direction: dir,
    line,
    confidence: conf,
    tier: conf >= 72 ? 'High' : conf >= 58 ? 'Med' : 'Low',
    platform: activePlatformLabel(f),
    bookKey: stat === 'fp'
      ? (getSourceActivePlatformKey(f, 'fp') ?? null)
      : (best.book ?? getSourceActivePlatformKey(f, stat) ?? null),
  };
}

function suggestParlays(
  fighters: AnalyzerFighter[],
  maxLegs: number = 3,
  count: number = 3,
): { legs: ParlayLeg[]; health: ParlayHealth }[] {
  // Collect all available legs from fighters with leans
  const available: { leg: ParlayLeg; fighter: AnalyzerFighter }[] = [];
  for (const f of fighters) {
    if (!f.db?.loaded) continue;
    const addLeg = (lean: LeanResult | null | undefined, stat: LeanSource) => {
      if ((lean?.conf || 0) < 55) return; // skip low confidence
      const leg = buildRankedParlayLeg(f, lean, stat);
      if (leg) available.push({ leg, fighter: f });
    };
    // GLOW-UP 208: same seven families the pool ranks. Suggestions drawing from a
    // NARROWER set than the list they sit beside was the older half of the same
    // bug — a leg could rank #2 in the pool and still be unreachable to the engine.
    addLeg(f.lean, 'fp');
    addLeg(f.lean_ss, 'ss');
    addLeg(f.lean_ss_r1, 'ss_r1');
    addLeg(f.lean_td, 'td');
    addLeg(f.lean_ft, 'ft');
    addLeg(f.lean_ctrl, 'ctrl');
    addLeg(f.lean_kd, 'kd');
  }

  // Sort by confidence descending
  available.sort((a, b) => b.leg.confidence - a.leg.confidence);

  // Generate combinations: take top N legs, try all combos of size maxLegs
  const top = available.slice(0, 12); // cap to avoid combinatorial explosion
  const combos: { legs: ParlayLeg[]; health: ParlayHealth }[] = [];

  // Helper: generate combinations of size k
  function* combinations<T>(arr: T[], k: number): Generator<T[]> {
    if (k === 0) { yield []; return; }
    for (let i = 0; i <= arr.length - k; i++) {
      for (const rest of combinations(arr.slice(i + 1), k - 1)) {
        yield [arr[i], ...rest];
      }
    }
  }

  for (let size = maxLegs; size >= 2; size--) {
    for (const combo of combinations(top, size)) {
      // Skip if same fighter+stat appears twice
      const seen = new Set<string>();
      let skip = false;
      for (const c of combo) {
        const key = `${(normalizeName(c.leg.fighter) || c.leg.fighter).toLowerCase()}|${c.leg.stat}`;
        if (seen.has(key)) { skip = true; break; }
        seen.add(key);
      }
      if (skip) continue;

      const legs = combo.map(c => c.leg);
      const health = analyzeParlayHealth(legs, fighters);
      combos.push({ legs, health });
    }
  }

  // Sort by health score, then by avg confidence
  combos.sort((a, b) => {
    if (b.health.score !== a.health.score) return b.health.score - a.health.score;
    return b.health.avgConfidence - a.health.avgConfidence;
  });

  return combos.slice(0, count);
}

function renderParlayLab(container: HTMLElement): void {
  if (!allFighters.length) {
    container.innerHTML = '<div class="inline-empty-msg">No fighter data loaded yet</div>';
    return;
  }
  const visibleFighters = applySourceVisibilityFilter(allFighters);
  if (!visibleFighters.length) {
    container.innerHTML = '<div class="inline-empty-msg">No fighters match selected source filters</div>';
    return;
  }

  // GLOW-UP 180: refresh the personal-record cache (async, storage-backed);
  // re-render once if it actually changed, so calibration chips appear even
  // when Parlay Lab is the first view opened. Signature-gated → no loop.
  void refreshPlacedPersonalRecord().then((changed) => {
    if (changed && currentView === 'parlaylab') renderParlayLab(container);
  });
  // GLOW-UP 246b: same treatment for the placed map itself — see above.
  void refreshBestPicksPlaced().then((changed) => {
    if (changed && currentView === 'parlaylab') renderParlayLab(container);
  });
  // YOU n/m chip for a leg's stat + direction — informational only (house
  // rule: never mutates model confidence); needs 2+ settled legs.
  const parlayYouTag = (stat: string, dir: string): string => {
    const r = placedPersonalRecord.get(`${stat}|${dir}`);
    // GLOW-UP 270: an EMPTY span rather than nothing. The row is a grid now, and
    // grid auto-placement fills tracks in source order — a missing optional chip
    // does not leave a hole, it pulls every column after it one track to the left.
    // That is precisely how the old flex row drifted, so the fix has to hold the
    // slot open, not merely name it.
    if (!r || r.total < 2) return '<span class="bp-you plr-empty"></span>';
    const lbl = stat === 'ss_r1' ? 'R1 SS' : stat.toUpperCase();
    return `<span class="bp-you ${r.hits * 2 >= r.total ? 'good' : 'bad'}" title="Your settled record on ${lbl} ${dir.toUpperCase()} legs you placed (from My Placed Ledger) — informational only, does not affect model confidence or health">YOU ${r.hits}/${r.total}</span>`;
  };

  // Build available legs
  const availableLegs: { leg: ParlayLeg; fighter: AnalyzerFighter }[] = [];
  for (const f of visibleFighters) {
    if (!f.db?.loaded) continue;
    // ── GLOW-UP 227 — the ranked leg is priced at the best book for its SIDE ──
    // It used to take `getSourceActiveLine`, which walks the active-platform
    // priority chain and knows nothing about direction. On UFC 330 that put Ian
    // Machado Garry's ranked R1 SS OVER on Underdog 13.5 while PrizePicks posted
    // 6.5 — a seven-point giveaway on an OVER, and worse, the 58% beside it was
    // scored by calcSSR1Lean against 6.5 ("edges the line by 5.4", projection
    // 11.9). Displayed at 13.5, that same confidence describes a leg the model's
    // own projection lands UNDER. Best Picks has shopped the best side for a long
    // while; this is the Lab catching up. Shared with suggestParlays.
    const addLeg = (lean: LeanResult | null | undefined, stat: LeanSource) => {
      const leg = buildRankedParlayLeg(f, lean, stat);
      if (leg) availableLegs.push({ leg, fighter: f });
    };
    // GLOW-UP 208: R1 SS, CTRL and KD are first-class ranked sources here now.
    // Best Picks has scored all three for a while (R1 SS can even overrule FT
    // there); Parlay Lab was the last surface still ranking four families, which
    // is why a strong R1 SS read could be seen on the board and not parlayed.
    // parlayUnrankableReason carries the market rules that keep them honest —
    // CTRL over-only, KD standard-projections-only.
    addLeg(f.lean, 'fp');
    addLeg(f.lean_ss, 'ss');
    addLeg(f.lean_ss_r1, 'ss_r1');
    addLeg(f.lean_td, 'td');
    addLeg(f.lean_ft, 'ft');
    addLeg(f.lean_ctrl, 'ctrl');
    addLeg(f.lean_kd, 'kd');
  }
  availableLegs.sort((a, b) => b.leg.confidence - a.leg.confidence);

  // ── GLOW-UP 207 — OFF-BOARD POOL ─────────────────────────────────────────
  // The ranked pool above is the model's own lean side on FP/SS/TD/FT. Everything
  // else on the board was unreachable from this view: the OTHER side of a leaned
  // prop, a prop the model has no read on, and the R1 SS / CTRL / KD families,
  // which the pool has never ranked. A parlay is the user's build, and the
  // model's silence on a prop is information, not a lock — so every remaining
  // side is collected here, priced honestly, and shown BELOW the ranked list
  // under a flag saying why it didn't make it.
  //
  // Nothing above this line changes. `availableLegs` stays the ranked pool, so
  // the suggestions, the weakest-leg swap, the synergy scan and the header count
  // all see exactly what they saw before.
  //
  // Confidence for the other side is `100 - conf` and that is not an
  // approximation: evWinProb reads `conf` AS the win probability (it divides by
  // 100), so the complement is the model's own number for the opposite side. A
  // prop with no lean sits at 50 — a coin flip is the honest prior, and it lands
  // where it should once EV prices the vig in.
  const PARLAY_ALL_STATS: LeanSource[] = ['fp', 'ss', 'ss_r1', 'td', 'ft', 'ctrl', 'kd'];
  const rankedKeys = new Set(availableLegs.map(a => parlayLegKeyOf(a.leg)));
  const offBoardLegs: { leg: ParlayLeg; fighter: AnalyzerFighter }[] = [];
  for (const f of visibleFighters) {
    if (!f.db?.loaded) continue;
    for (const stat of PARLAY_ALL_STATS) {
      const lean = leanForStat(f, stat);
      const leanDir = (lean && lean.lean !== 'none' && lean.lean !== 'push') ? lean.lean as 'over' | 'under' : null;
      const leanConf = lean?.conf || 0;
      for (const dir of ['over', 'under'] as const) {
        // ── GLOW-UP 227 — EVERY stat gets one candidate per book ──────────────
        // GLOW-UP 211 gave FP per-book candidates because its books score fantasy
        // points differently, and left every other stat on a single best-book pick
        // "because they're line-shoppable". Shopping is what you do BEFORE placing;
        // afterwards you need the leg you actually hold. The board offered exactly
        // one number per side, so a PrizePicks SS 21.5 and a placed DK R1 SS 7.5
        // were both unreachable while UD's 20.5 and 13.5 sat in the pool. Books
        // disagree hard on these props — R1 SS ran PP 6.5 / DK 7.5 / UD 13.5 on one
        // fighter — so a single line was never a fair summary of the market either.
        const candidates: Array<{ book: string | null; line: number | null }> =
          (LEAN_STAT_FIELDS[stat] || []).map(([bk]) => ({ book: bk, line: lineForBook(f, stat, bk) }));
        for (const cand of candidates) {
        // Book-qualified for every stat now, so a book's leg dedupes against the
        // ranked leg only when it IS the ranked leg's book.
        const key = parlayLegKey(f.name, stat, dir, cand.book);
        if (rankedKeys.has(key)) continue;
        // A book with no line for this prop has nothing to offer — skip it rather
        // than inventing a leg at some other book's number.
        if (cand.line == null) continue;
        // Placeability is REPORTED here, never enforced: a side this book won't
        // take still gets a leg, flagged, because you may hold it anyway. Via
        // bookTakesSide so the non-FP market rules (Pick6 TD More-only, DK chalk)
        // are applied per book instead of being silently skipped.
        const takes = cand.book != null && bookTakesSide(f, stat, dir, cand.book);
        const bb = { book: takes ? cand.book : null, line: cand.line };
        const line = bb.line;
        const statLbl = statDisplayLabel(stat);
        const bookLbl = cand.book ? (LEAN_BOOK_LABEL[cand.book] || cand.book) : '';
        // The market rule that would keep this side off the ranked board, if any.
        // Same call the pool builder gates on, so the flag and the demotion can
        // never tell different stories.
        const marketBlock = parlayUnrankableReason(f, stat, dir);
        let conf: number;
        let reason: string;
        if (leanDir && leanDir !== dir) {
          conf = Math.max(1, 100 - leanConf);
          reason = `Model leans ${leanDir.toUpperCase()} here at ${leanConf}% — this is the other side, so it carries the complement (${conf}%). Your read is allowed to disagree with the board's.`;
        } else if (leanDir === dir) {
          // Same stat, same side as the lean, yet not ranked: either a market rule
          // blocks the side (CTRL under, a demon/goblin KD, an unplaceable FP
          // side) or the ACTIVE book has no line for it while another book does.
          // Either way the model is ON this side — say so before the caveat.
          conf = leanConf;
          reason = marketBlock
            ? `Model leans ${dir.toUpperCase()} ${leanConf}% here, but the ranked board can't carry this side.`
            : `Model leans ${dir.toUpperCase()} ${leanConf}% here, but the ranked pool dropped this side — the active book doesn't post it for this fighter. Still yours to take.`;
        } else {
          conf = 50;
          reason = `No model lean on this ${statLbl} prop either way — 50% is the honest prior, not a read. EV prices the vig against it.`;
        }
        if (marketBlock) reason += ` · ${marketBlock}`;
        // GLOW-UP 227: every leg names its book now, not just FP. With one leg per
        // book in the pool, "SS UNDER 21.5" beside "SS UNDER 20.5" is unreadable
        // unless each says whose number it is.
        if (bookLbl) reason = `${bookLbl} ${statLbl} ${line}. ${reason}`;
        if (!bb.book && bookLbl) {
          reason += ` · ${bookLbl} does not offer this side — queue it anyway if you have it.`;
        }
        offBoardLegs.push({
          leg: {
            fighter: f.name,
            opponent: f.opponent || '?',
            stat,
            direction: dir,
            line,
            confidence: conf,
            tier: conf >= 72 ? 'High' : conf >= 58 ? 'Med' : 'Low',
            platform: activePlatformLabel(f),
            offBoard: true,
            offReason: reason,
            // GLOW-UP 227: the CANDIDATE's book for every stat, even when that book
            // won't take the side — the row has to say whose line it is, and the
            // key has to stay unique per book. Whether the book takes it is carried
            // by the flag in `reason`, not by blanking the book.
            bookKey: cand.book,
          },
          fighter: f,
        });
        }
      }
    }
  }
  offBoardLegs.sort((a, b) => b.leg.confidence - a.leg.confidence);
  // Both tiers, for everything that must see a leg the user can actually click:
  // EV, selection, the slip. Ranking, suggestions and swaps stay on availableLegs.
  const poolLegs = [...availableLegs, ...offBoardLegs];

  // Which book a leg's line came from. Off-board legs resolved theirs
  // direction-aware in leanBestBook; ranked legs use the active platform as before.
  const parlayLegBook = (l: ParlayLeg, lf: AnalyzerFighter): SourcePlatformKey | null => {
    // A leg that named its own book wins — that's every FP leg now (GLOW-UP 211)
    // and every off-board leg. leanBestBook types its book as a plain string; the
    // values are the same platform keys every other book lookup here uses.
    if (l.bookKey !== undefined) return (l.bookKey ?? null) as SourcePlatformKey | null;
    return l.offBoard ? null : (getSourceActivePlatformKey(lf, l.stat) ?? null);
  };

  // GLOW-UP 177: per-leg EV via the same computeDetailedEV pipeline the board
  // uses, so the pool's EV sort can never disagree with Best Picks. Synthesize
  // a minimal EffectiveLean from the leg's direction/stat/confidence.
  const parlayLegEv = new Map<string, number | null>();
  for (const a of poolLegs) {
    const el = { lean: a.leg.direction, _source: a.leg.stat, conf: a.leg.confidence } as unknown as EffectiveLean;
    parlayLegEv.set(parlayLegKeyOf(a.leg), computeDetailedEV(a.fighter, el)?.ev ?? null);
  }

  // Determine which are selected (keep the fighter ref for render-time
  // platform-key lookups on slip rows)
  const selectedLegs: ParlayLeg[] = [];
  const selectedPairs: { leg: ParlayLeg; fighter: AnalyzerFighter }[] = [];
  for (const a of poolLegs) {
    const key = parlayLegKeyOf(a.leg);
    if (parlaySelectedLegs.has(key)) { selectedLegs.push(a.leg); selectedPairs.push(a); }
  }

  // Compute health for current parlay
  const health = selectedLegs.length >= 2
    ? analyzeParlayHealth(selectedLegs, visibleFighters)
    : null;

  // Suggest parlays. Ask for a WIDER candidate set than we display: suggestParlays
  // ranks purely on health (confidence + correlation + legs + spread), which is
  // EV-blind, so the top 3 by health can all be priced below breakeven while a
  // profitable combination sits at #5. Re-ranked against price below — see
  // GLOW-UP 206 L2. Fetching 3 and reordering them could only shuffle the same
  // three losers.
  const suggestionPool = suggestParlays(visibleFighters, 3, 12);

  // ── Render ──
  // Live slip guards: flag pool legs that would CONTRADICT the current slip
  // before they're clicked. FT is a shared stat (one fight, one duration), so
  // same-fight opposite-direction FT legs are mutually exclusive; same-fight
  // same-direction FP legs are zero-sum (only one side gets the win bonus).
  const legNorm = (s: string): string => (normalizeName(s) || s).toLowerCase();
  // Generalised so the same rules can be checked against an arbitrary leg set —
  // the live slip (below) and the slip-minus-weakest used by the L3 swap.
  const conflictAgainst = (cand: ParlayLeg, against: ParlayLeg[]): string | null => {
    for (const s of against) {
      if (s.fighter === cand.fighter && s.stat === cand.stat && s.direction === cand.direction) continue;
      const sameFight = legNorm(cand.opponent) === legNorm(s.fighter) || legNorm(cand.fighter) === legNorm(s.opponent);
      if (!sameFight) continue;
      if (cand.stat === 'ft' && s.stat === 'ft' && cand.direction !== s.direction) {
        return `Contradicts ${prettyName(s.fighter)} FT ${s.direction.toUpperCase()} in your slip — one fight, one duration; both legs can't cash`;
      }
      if (cand.stat === 'fp' && s.stat === 'fp' && cand.direction === s.direction) {
        return `FP zero-sum vs ${prettyName(s.fighter)} in your slip — only one fighter gets the win bonus`;
      }
    }
    return null;
  };
  const conflictsWithSlip = (cand: ParlayLeg): string | null => conflictAgainst(cand, selectedLegs);

  // Fighter lookup by normalised name — needed by every correlation call below.
  const legFighterMap = new Map<string, AnalyzerFighter>();
  for (const vf of visibleFighters) legFighterMap.set(legNorm(vf.name), vf);
  const fighterForLeg = (l: ParlayLeg): AnalyzerFighter | undefined => legFighterMap.get(legNorm(l.fighter));

  // GLOW-UP 191 (L1): the mirror of conflictsWithSlip. The pool already warns
  // what CLASHES with the slip; a leg that correlates positively with something
  // already selected is just as decision-relevant while building.
  const synergyWithSlip = (cand: ParlayLeg, candF: AnalyzerFighter): string | null => {
    for (const s of selectedLegs) {
      if (s.fighter === cand.fighter && s.stat === cand.stat && s.direction === cand.direction) continue;
      const sf = fighterForLeg(s);
      if (!sf) continue;
      const alert = calcPairCorrelation(cand, candF, s, sf);
      if (alert && alert.type === 'synergy' && alert.impact > 0) {
        return `Pairs with ${prettyName(s.fighter)} ${s.stat === 'ss_r1' ? 'R1 SS' : s.stat.toUpperCase()} in your slip — ${alert.message}`;
      }
    }
    return null;
  };

  // GLOW-UP 191 (L4): one analysis used by BOTH the live slip and the suggestion
  // cards, so a suggestion's EV can never disagree with what you'd see after
  // loading it. Mirrors the previous inline slip math exactly.
  const analyzeSlipLegs = (legs: ParlayLeg[]) => {
    const nn = legs.length;
    if (nn < 2) return null;
    const probs = legs.map((l) => {
      const recal = getRecalibratedConfidence(l.confidence, l.stat);
      return Math.min(0.85, Math.max(0.35, (recal ?? l.confidence) / 100));
    });
    const anyRecal = legs.some((l) => getRecalibratedConfidence(l.confidence, l.stat) != null);
    const rr: number[][] = Array.from({ length: nn }, () => new Array<number>(nn).fill(0));
    let maxPos = 0;
    for (let i = 0; i < nn; i++) for (let j = i + 1; j < nn; j++) {
      const c1 = fighterForLeg(legs[i]); const c2 = fighterForLeg(legs[j]);
      if (!c1 || !c2) continue;
      const alert = calcPairCorrelation(legs[i], c1, legs[j], c2);
      if (!alert) continue;
      const r = Math.max(-0.85, Math.min(0.85, alert.impact * 4));
      rr[i][j] = rr[j][i] = r;
      if (r > maxPos) maxPos = r;
    }
    const anyCorr = rr.some((row) => row.some((v) => Math.abs(v) > 0.01));
    const byHits = anyCorr ? correlatedHitCounts(probs, rr) : independentHitCounts(probs);
    const combined = Math.round((byHits[nn] || 0) * 100);
    const evRows: { label: string; mult: number; ev: number }[] = [];
    for (const key of Object.keys(PICKEM_PAYOUTS)) {
      const table = PICKEM_PAYOUTS[key].byLegs[nn];
      if (!table) continue;
      let ret = 0;
      for (const hitsStr of Object.keys(table)) ret += (byHits[Number(hitsStr)] || 0) * table[Number(hitsStr)];
      const topMult = table[nn] ?? Math.max(...Object.values(table));
      evRows.push({ label: PICKEM_PAYOUTS[key].label, mult: topMult, ev: Math.round((ret - 1) * 100) });
    }
    evRows.sort((a, b) => b.ev - a.ev);
    return { n: nn, combined, evRows, best: evRows[0] || null, anyCorr, maxPosCorr: maxPos, anyRecal };
  };

  // ── GLOW-UP 206 L2 ────────────────────────────────────────────────────────
  // suggestParlays ranks on health.score then avgConfidence. Health is
  // avgConfidence + correlation + legCount + diversity — it never sees price, so
  // the board could recommend a beautifully correlated ticket priced at -50% and
  // grade it "excellent" purely for being well built. Suggestions are what the
  // app actively pushes at you, so this is the one place that EV blindness is
  // not just mislabelling.
  //
  // Price is a GATE, not a new ranking axis: any suggestion that clears
  // breakeven outranks any that doesn't, and within each group the existing
  // health order is preserved untouched. That deliberately avoids inventing a
  // weighting between "well built" and "well priced" — there is no evidence for
  // what that trade should be, and health remains the tiebreak it always was.
  const suggestionsRanked = [...suggestionPool].sort((a, b) => {
    const ea = analyzeSlipLegs(a.legs)?.best?.ev ?? null;
    const eb = analyzeSlipLegs(b.legs)?.best?.ev ?? null;
    const pa = ea != null && ea >= 0 ? 1 : 0;
    const pb = eb != null && eb >= 0 ? 1 : 0;
    if (pa !== pb) return pb - pa;                       // +EV first
    if (b.health.score !== a.health.score) return b.health.score - a.health.score;
    return b.health.avgConfidence - a.health.avgConfidence;
  });
  const suggestions = suggestionsRanked.slice(0, 3);
  // If nothing on the board clears breakeven, say so rather than quietly serving
  // the three least-bad losers under an "excellent" badge.
  const anySuggestionPositive = suggestionsRanked.some(s => (analyzeSlipLegs(s.legs)?.best?.ev ?? -1) >= 0);

  // GLOW-UP 177: apply the command-strip view (filter then sort) to the pool
  // only — selection, conflict checks, health, suggestions all still see the
  // full availableLegs, so hiding a leg here never changes the math.
  // ── GLOW-UP 246 — the legs you already hold, findable ────────────────────
  // The pool sorts by confidence, so a leg placed AGAINST the model's lean sinks.
  // On UFC 330 four Underdog FP OVERs were placed; the model leans UNDER on two of
  // them, which puts those at 38% and 39% — real rows about 150 down a ~180-prop
  // list, with no way to search for a fighter. They read as missing. Index the
  // event's placed legs so a row can say you hold it and the strip can filter to
  // exactly them. bestPicksPlaced is the in-memory map the slate tray already
  // writes, so this stays synchronous — no storage round-trip in a sync render.
  const placedPropKeys = new Set<string>();
  const placedBookKeys = new Set<string>();
  for (const r of bestPicksPlaced.values()) {
    const nm = (normalizeName(r.name) || r.name || '').toLowerCase();
    const dir = String(r.dir || '').toLowerCase();
    if (!nm || (dir !== 'over' && dir !== 'under')) continue;
    const stat = String(r.source || 'fp');
    placedPropKeys.add(`${nm}|${stat}|${dir}`);
    if (r.book) placedBookKeys.add(`${nm}|${stat}|${dir}|${r.book}`);
  }
  const legPlacedKey = (l: ParlayLeg): string =>
    `${(normalizeName(l.fighter) || l.fighter).toLowerCase()}|${l.stat}|${l.direction}`;
  const isLegPlaced = (l: ParlayLeg): boolean => placedPropKeys.has(legPlacedKey(l));
  const isBookPlaced = (l: ParlayLeg): boolean =>
    l.bookKey != null && placedBookKeys.has(`${legPlacedKey(l)}|${l.bookKey}`);
  const placedInPool = new Set(poolLegs.filter(a => isLegPlaced(a.leg)).map(a => legPlacedKey(a.leg))).size;

  const evOf = (a: typeof availableLegs[number]): number | null =>
    parlayLegEv.get(parlayLegKeyOf(a.leg)) ?? null;
  const tierRank = (t: string): number => (t === 'High' ? 0 : t === 'Med' ? 1 : 2);
  // GLOW-UP 207: the same view (filter + sort) is applied to BOTH tiers, so the
  // off-board section obeys the command strip exactly like the ranked one and
  // "sorted by EV" means one thing on the page, not two.
  const applyPoolView = (legs: typeof availableLegs): typeof availableLegs => {
    const out = legs.filter(a =>
      (parlayPoolStat === 'all' || a.leg.stat === parlayPoolStat)
      && (parlayPoolDir === 'all' || a.leg.direction === parlayPoolDir)
      && (!parlayPoolPlacedOnly || isLegPlaced(a.leg)));
    if (parlayPoolSort === 'ev') {
      return [...out].sort((a, b) => (evOf(b) ?? -Infinity) - (evOf(a) ?? -Infinity));
    }
    if (parlayPoolSort === 'tier') {
      return [...out].sort((a, b) => tierRank(a.leg.tier) - tierRank(b.leg.tier) || b.leg.confidence - a.leg.confidence);
    }
    return out; // 'conf' keeps the base confidence-desc order
  };
  const displayLegs = applyPoolView(availableLegs);
  const displayOffLegs = applyPoolView(offBoardLegs);

  // Stat-family chips built from the pool (only families actually present).
  // Counts span both tiers because the chips filter both.
  const PL_STAT_LABEL: Record<string, string> = { fp: 'FP', ss: 'SS', ss_r1: 'R1 SS', td: 'TD', ft: 'FT', ctrl: 'CTRL', kd: 'KD' };
  const plStatCounts = new Map<string, number>();
  for (const a of poolLegs) plStatCounts.set(a.leg.stat, (plStatCounts.get(a.leg.stat) || 0) + 1);
  // ── GLOW-UP 277 — the only two chips that would not say how many ─────────
  // Every other chip in the strip carries its count: ALL 308, SS 198, TD 14,
  // FT 28, PLACED 33. OVER and UNDER — the split you most want to know before
  // you touch anything, because it tells you which way the whole board leans —
  // were bare. You had to click one to find out, and clicking is what you were
  // trying to decide about.
  const plDirCounts = { over: 0, under: 0 };
  for (const a of poolLegs) {
    if (a.leg.direction === 'over') plDirCounts.over++;
    else if (a.leg.direction === 'under') plDirCounts.under++;
  }
  const plStatChips = Object.keys(PL_STAT_LABEL)
    .filter(s => (plStatCounts.get(s) || 0) > 0)
    .map(s => `<button class="plq-chip${parlayPoolStat === s ? ' on' : ''}" data-plq-stat="${s}" title="Show only ${PL_STAT_LABEL[s]} legs (click again for all)">${PL_STAT_LABEL[s]} <i>${plStatCounts.get(s)}</i></button>`)
    .join('');
  const parlayPoolControls = `<div class="plq-controls">
    <span class="plq-group">
      <span class="plq-label">SORT</span>
      <button class="plq-btn${parlayPoolSort === 'conf' ? ' on' : ''}" data-plq-sort="conf" title="Highest model confidence first">CONF</button>
      <button class="plq-btn${parlayPoolSort === 'ev' ? ' on' : ''}" data-plq-sort="ev" title="Highest calibrated EV first — same pipeline as Best Picks">EV</button>
      <button class="plq-btn${parlayPoolSort === 'tier' ? ' on' : ''}" data-plq-sort="tier" title="High → Med → Low tier, then confidence">TIER</button>
    </span>
    <span class="plq-group">
      <span class="plq-label">SHOW</span>
      <button class="plq-chip${parlayPoolStat === 'all' ? ' on' : ''}" data-plq-stat="all" title="All stat families — ranked pool plus off-board">ALL <i>${poolLegs.length}</i></button>
      ${plStatChips}
    </span>
    <span class="plq-group">
      <button class="plq-chip${parlayPoolDir === 'over' ? ' on' : ''}" data-plq-dir="over" title="Only OVER legs">OVER <i>${plDirCounts.over}</i></button>
      <button class="plq-chip${parlayPoolDir === 'under' ? ' on' : ''}" data-plq-dir="under" title="Only UNDER legs">UNDER <i>${plDirCounts.under}</i></button>
    </span>
    ${placedPropKeys.size ? `<span class="plq-group">
      <button class="plq-chip plq-placed${parlayPoolPlacedOnly ? ' on' : ''}" data-plq-placed title="Show only props you marked placed for this event — the fastest way to rebuild a ticket from legs you already hold, since a leg placed against the model's lean sorts to the bottom of the pool.${placedInPool < placedPropKeys.size ? ` ${placedPropKeys.size - placedInPool} of your ${placedPropKeys.size} placed props aren't in the pool at all — no book the scraper can see still posts them.` : ''}">● PLACED <i>${placedInPool}</i></button>
    </span>` : ''}
  </div>`;

  // ── GLOW-UP 272 — labels, now that there is something to label ───────────
  // A hundred rows of `UNDER · SS · 54.5 · BT · YOU 4/7 · +52% · 81%` and not one
  // word saying which number is which. You could work out that the last figure is
  // confidence because it has a bar under it, and that `+52%` is EV because the EV
  // sort reorders by it — but both are inferences, and the row carries two
  // different percentages side by side. A header was impossible while the columns
  // drifted; GLOW-UP 270 makes it both possible and obvious. Same track list,
  // inherited rather than restated, so it cannot fall out of step with the rows.
  const parlayPoolColumnHead = `<div class="plr-head" aria-hidden="true">
    <span></span>
    <span>Fighter</span>
    <span title="Which side of the line you are backing">Side</span>
    <span title="Stat family">Stat</span>
    <span title="The posted line and the book it comes from. Off-board rows show every book on the prop — click a chip to take that number.">Line · Book</span>
    <span title="Your own settled record on this stat and side, from the Placed ledger. Informational only.">You</span>
    <span title="Calibrated expected value for the leg on its own">EV</span>
    <span title="What adding the leg would do to slip health, correlation included">Δ</span>
    <span title="Model confidence in the leg">Conf</span>
  </div>`;

  // GLOW-UP 197 L2 — the row never said who the opponent was, so fight membership was
  // invisible in a flat 19-leg list. The `vs <Opponent>` label fixes that on every row.
  // The amber flag is deliberately scoped to fights ALREADY IN THE SLIP: flagging
  // "this fight has siblings in the pool" fired on nearly every row (19 legs over ~7
  // fights) and so discriminated nothing. What matters is whether picking this leg
  // doubles up on an outcome you're already exposed to.
  const legFightKeyOf = (l: { fighter: string; opponent?: string }): string =>
    [l.fighter, l.opponent || ''].map(x => x.toLowerCase()).sort().join('|');
  const slipFightCount = new Map<string, number>();
  for (const l of selectedLegs) {
    const k = legFightKeyOf(l);
    slipFightCount.set(k, (slipFightCount.get(k) || 0) + 1);
  }

  // GLOW-UP 197 L3 — marginal impact. Picking a leg was guesswork: the row showed the
  // leg's own confidence and EV, but not what it would do to the SLIP once correlation
  // with the legs already selected is accounted for. A high-confidence leg that rides
  // the same fight can still drop slip health. Re-scores the slip with each candidate
  // added (cheap — 19 candidates over a <=5-leg slip) and shows the delta.
  const baseHealthScore = health ? health.score : null;
  const marginalDelta = (leg: ParlayLeg): number | null => {
    if (baseHealthScore == null) return null; // needs a >=2-leg slip to compare against
    const withLeg = analyzeParlayHealth([...selectedLegs, leg], visibleFighters);
    return withLeg.score - baseHealthScore;
  };

  // ── GLOW-UP 292 — the off-board tier never showed its slip impact ───────
  // Ranked rows have carried the marginal-delta chip since GLOW-UP 197; grouped
  // and paired off-board rows hardcoded an empty placeholder and rendered a blank
  // Δ column. That is the tier where the number matters MOST: these are the sides
  // the model is against or silent on, so the only honest reason to take one is
  // what it does to the ticket you are building — and that was the one thing the
  // row would not say. Same helper for both shapes, same pipeline as the ranked
  // rows, and it goes quiet when the leg is already in the slip or the slip is
  // too short to score against.
  const offMargTag = (leg: ParlayLeg, alreadySelected: boolean): string => {
    const d = alreadySelected ? null : marginalDelta(leg);
    if (d == null) return '<span class="parlay-leg-marg plr-empty"></span>';
    return `<span class="parlay-leg-marg ${d > 0 ? 'pos' : d < 0 ? 'neg' : 'flat'}" title="Adding this side would take slip health from ${baseHealthScore} to ${baseHealthScore! + d} — correlation with the legs you've already picked included. Priced on this side's best entry; the other books on the row score the same.">${d > 0 ? '▲' : d < 0 ? '▼' : '·'}${d > 0 ? '+' : ''}${d}</span>`;
  };

  const renderPoolRow = (a: typeof availableLegs[number]): string => {
    const key = parlayLegKeyOf(a.leg);
    const sel = parlaySelectedLegs.has(key);
    const mDelta = sel ? null : marginalDelta(a.leg);
    const legFightKey = legFightKeyOf(a.leg);
    const inSlipFight = !sel ? (slipFightCount.get(legFightKey) || 0) : 0;
    const vsTag = a.leg.opponent
      // GLOW-UP 291: the `shared` treatment goes too. It boxed the opponent label
      // when the slip already held that fight — which the ↺ on the Δ chip now says,
      // and the box was spending padding in the one cell that cannot afford any.
      ? `<span class="parlay-leg-vs" title="Opponent: ${prettyName(a.leg.opponent)}">vs ${prettyName(a.leg.opponent).split(' ').slice(-1)[0]}</span>`
      : '';
    const conflict = sel ? null : conflictsWithSlip(a.leg);
    // GLOW-UP 191 (L1): only look for synergy when there's no conflict — a leg
    // that contradicts the slip shouldn't also advertise that it pairs well.
    const synergy = (sel || conflict) ? null : synergyWithSlip(a.leg, a.fighter);
    const legEv = evOf(a);
    const confClass = a.leg.confidence >= 72 ? 'conf-high' : a.leg.confidence >= 58 ? 'conf-med' : 'conf-low';
    const pk = parlayLegBook(a.leg, a.fighter);
    const platChip = pk
      ? `<span class="parlay-leg-plat plat-${pk}" title="Line source: ${a.leg.offBoard ? `${PL_BOOK_NAME[pk] || pk} ${a.leg.line} — best book for this SIDE` : formatSourcePlatformLabel(a.fighter, a.leg.stat)}">${platformKeyShort(pk)}</span>`
      // GLOW-UP 207: an off-board side no book posts still gets a row (placeability
      // is reported, not enforced — same call the two-sided slate picker makes).
      : (a.leg.offBoard ? '<span class="parlay-leg-plat plat-none" title="No book the scraper can see posts this side. The line shown is the prop\'s active line; queue it anyway if you have it somewhere else.">NO BK</span>' : '');
    // GLOW-UP 288: the ⊘ is gone from the identity cell. Every row it appeared on
    // is already inside a section headed OFF-BOARD PROPS, so the glyph was the
    // section's own label reprinted once per row — and it was costing 26px of the
    // one cell that cannot spare any. Its only real payload, the per-leg reason,
    // moves to the row's own tooltip.
    const offTag = '';
    const offRowTitle = a.leg.offBoard
      ? ` title="Off-board. ${(a.leg.offReason || '').replace(/"/g, '&quot;')}"`
      : '';
    const placedTag = isLegPlaced(a.leg)
      ? `<span class="parlay-leg-placed" title="You marked this prop placed for this event. Flagged on the row so a leg you already hold is findable without hunting the confidence order — the ● PLACED chip in the strip filters to just these.">●</span>`
      : '';
    // ── GLOW-UP 282 — the last two words that cost a fighter his name ─────
    // These appear only once a slip exists, which is why 281's measurements did
    // not see them: on the rows that earn one, `🔗 synergy` adds ~70px to an
    // identity cell that has no slack left, and the name goes back to
    // `Shamil Gazi...`. Same trade the `off-board` tag lost in 281 — the word
    // duplicates the icon, and the sentence that actually explains the
    // relationship was always in the tooltip, never on the row.
    // ── GLOW-UP 290 — three ways of saying what the Δ chip already says ───
    // `🔗 synergy`, `✗ vs slip` and the `↺N` suffix on the opponent label are all
    // answers to one question: what does adding this leg do to the slip I have?
    // The Δ column answers exactly that, numerically, and only exists when a slip
    // does — the same condition all three of these flags need. So they were three
    // extra objects in the identity cell restating the sign of a number two
    // columns over.
    //
    // It is not merely redundant, it is the thing that broke the cell. Measured at
    // the real window width, two-column, slip live: identity 249px against a
    // worst-case 304px once a row carries `vs Rodrigues ↺2`, the placed dot and
    // 🔗 — a 55px deficit, which is why `Anthony Hernand...` and `Shamil Gazi...`
    // truncated while their neighbours did not. Folding all three into the Δ chip
    // returns ~48px to identity and leaves it holding identity alone.
    const warnTag = '';
    const synTag = '';
    const slipRelCls = `${conflict ? ' is-conflict' : ''}${synergy ? ' is-syn' : ''}${inSlipFight ? ' is-samefight' : ''}`;
    const slipRelIcon = conflict ? '✗' : synergy ? '🔗' : inSlipFight ? '↺' : '';
    const slipRelWhy = (conflict ? ` ✗ CONFLICT: ${conflict}` : '')
      + (synergy ? ` 🔗 SYNERGY: ${synergy}` : '')
      + (inSlipFight ? ` ↺ Your slip already holds ${inSlipFight} leg${inSlipFight === 1 ? '' : 's'} on this fight — adding this one stakes the same outcome again rather than diversifying, and the delta already prices it.` : '');
    const mTag = mDelta != null
      ? `<span class="parlay-leg-marg ${mDelta > 0 ? 'pos' : mDelta < 0 ? 'neg' : 'flat'}${slipRelCls}" title="${`Adding this leg would take slip health from ${baseHealthScore} to ${baseHealthScore! + mDelta} — correlation with the legs you've already picked included.${slipRelWhy}`.replace(/"/g, '&quot;')}">${slipRelIcon}${mDelta > 0 ? '▲' : mDelta < 0 ? '▼' : '·'}${mDelta > 0 ? '+' : ''}${mDelta}</span>`
      : '<span class="parlay-leg-marg plr-empty"></span>';
    // EV was already computed for the pool's EV sort but never shown — the sort
    // ranked by a number the row didn't display.
    const evTag = legEv != null
      ? `<span class="parlay-leg-ev ${legEv > 0 ? 'pos' : legEv < 0 ? 'neg' : ''}" title="Calibrated EV for this leg as a single pick — same pipeline as the Best Picks board. Parlay EV is the slip deck on the right; this prices the leg on its own.">${legEv > 0 ? '+' : ''}${legEv}%</span>`
      : '';
    // ── GLOW-UP 270 — the pool is a table that was never aligned ──────────
    // Measured across the 103 rows this board renders at 1900px: the OVER/UNDER
    // chip starts anywhere across a 159px band, the stat label across 153px. The
    // row was `display:flex` with the NAME set to `flex:1`, so every column after
    // it was positioned by subtraction — its x depended on how long the fighter's
    // name was, how many tags the leg carried, and whether the optional YOU and
    // marginal-delta chips happened to exist. A list of a hundred rows sorted by
    // confidence, whose most important token (which SIDE you are backing) never
    // lands twice in the same place, cannot be scanned; it can only be read.
    //
    // Three wrappers give the grid stable slots: identity, market, and the two
    // always-emitted placeholders above. Grouped off-board rows use the same
    // wrappers, so the two row shapes finally share one track list.
    return `<div class="parlay-leg-row${sel ? ' selected' : ''}${conflict ? ' leg-conflict' : ''}${a.leg.offBoard ? ' off-board' : ''} ${confClass}"${offRowTitle} data-parlay-key="${key}" data-fighter="${a.leg.fighter}" data-stat="${a.leg.stat}" data-dir="${a.leg.direction}">
      <span class="parlay-leg-check">${sel ? '☑' : '☐'}</span>
      <span class="plr-id">
        <span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">🥊</span><img class="bp-avatar-img" data-name="${a.leg.fighter}" alt="" /></span><span class="parlay-leg-name" title="${prettyName(a.leg.fighter)}">${prettyName(a.leg.fighter)}</span>
        ${vsTag}${placedTag}${offTag}${warnTag}${synTag}
      </span>
      <span class="parlay-leg-dir ${a.leg.direction}">${a.leg.direction.toUpperCase()}</span>
      <span class="parlay-leg-stat src-${a.leg.stat}">${a.leg.stat === 'ss_r1' ? 'R1 SS' : a.leg.stat.toUpperCase()}</span>
      <span class="plr-market"><span class="parlay-leg-line">${a.leg.line}</span>${platChip}</span>
      ${parlayYouTag(a.leg.stat, a.leg.direction)}
      ${evTag}${mTag}
      <span class="parlay-leg-conf">${a.leg.confidence}%<i class="plc-bar"><b style="width:${Math.min(100, Math.max(8, a.leg.confidence))}%"></b></i></span>
    </div>`;
  };

  // GLOW-UP 178: slip-ready clip text for a parlay leg — same shape as the
  // Best Picks ⧉ payload so a leg copied here reads identically to one copied
  // from the board.
  const PL_STAT_CLIP: Record<string, string> = { fp: 'FP', ss: 'SS', ss_r1: 'R1 SS', td: 'TD', ft: 'FT', ctrl: 'CTRL', kd: 'KD' };
  const PL_BOOK_NAME: Record<string, string> = { pick6: 'Pick6', underdog: 'Underdog', prizepicks: 'PrizePicks', betr: 'Betr', draftkings_sportsbook: 'DK Sportsbook' };

  // ── GLOW-UP 228 L1 — off-board legs group by PROP; books become a rail ────
  // Making every book parlayable (GLOW-UP 227) took this tier from 194 rows to
  // 462, and the new ones are near-clones. Within one (fighter, stat, side) the
  // confidence and the EV are IDENTICAL across books — both are computed from
  // the lean, which knows nothing about which book posted the line — so the only
  // thing that varies down the list is the book and its number. Rendered flat,
  // that reads as 462 separate ideas; it is ~180 props, each with a choice of
  // book. One row per prop, every book selectable on it.
  const groupKeyOf = (a: { leg: ParlayLeg }): string =>
    `${a.leg.fighter}|${a.leg.stat}|${a.leg.direction}`;
  const renderGroupedOffRow = (g: typeof offBoardLegs): string => {
    const head = g[0];
    const dir = head.leg.direction;
    const selected = g.filter(a => parlaySelectedLegs.has(parlayLegKeyOf(a.leg)));
    const confClass = head.leg.confidence >= 72 ? 'conf-high' : head.leg.confidence >= 58 ? 'conf-med' : 'conf-low';
    const legEv = evOf(head);
    // Best entry first: an OVER wants the lowest number, an UNDER the highest —
    // the same rule leanBestBook shops by, so the rail reads in value order and
    // the leftmost chip is the one the model would have taken.
    const books = [...g].sort((a, b) => dir === 'over'
      ? (a.leg.line ?? 0) - (b.leg.line ?? 0)
      : (b.leg.line ?? 0) - (a.leg.line ?? 0));
    const chips = books.map((a, i) => {
      const k = parlayLegKeyOf(a.leg);
      const on = parlaySelectedLegs.has(k);
      const pk = parlayLegBook(a.leg, a.fighter);
      const label = pk ? platformKeyShort(pk) : 'NO BK';
      const takes = pk != null;
      const tip = `${pk ? (PL_BOOK_NAME[pk] || pk) : 'No book the scraper can see'} ${a.leg.line}`
        + `${i === 0 ? ` — best ${dir.toUpperCase()} entry of the ${books.length}` : ''}`
        + `${takes ? '' : ' · queue it anyway if you have it somewhere'}`
        + ` · ${on ? 'in your slip — click to remove' : 'click to add this book to your slip'}`;
      return `<button type="button" class="plg-book plat-${pk || 'none'}${on ? ' on' : ''}${i === 0 ? ' is-best' : ''}${isBookPlaced(a.leg) ? ' is-placed' : ''}"`
        + ` data-parlay-key="${k}" title="${tip.replace(/"/g, '&quot;')}">${label} <b>${a.leg.line}</b>${on ? '<i>✓</i>' : ''}</button>`;
    }).join('');
    const vsTag = head.leg.opponent
      ? `<span class="parlay-leg-vs" title="Opponent: ${prettyName(head.leg.opponent)}">vs ${prettyName(head.leg.opponent).split(' ').slice(-1)[0]}</span>`
      : '';
    const evTag = legEv != null
      ? `<span class="parlay-leg-ev ${legEv > 0 ? 'pos' : legEv < 0 ? 'neg' : ''}" title="Calibrated EV for this leg as a single pick. Identical across the books on this row — EV prices the model's confidence, not the line.">${legEv > 0 ? '+' : ''}${legEv}%</span>`
      : '';
    // ── GLOW-UP 246 — a grouped row was unclickable everywhere but the chips ──
    // The row carries no data-parlay-key (each BOOK owns one), so the row-level
    // handler bails on it — while `.parlay-leg-row` sets cursor:pointer for the
    // whole strip. A single-book prop renders through renderPoolRow and IS fully
    // clickable, so identical-looking rows behaved differently with no way to tell
    // which was which: Brahimaj's FP OVER (one book) clicked, Orolbai's (two) did
    // not. The ☐ now toggles the BEST book — leftmost chip, the one the model would
    // take — so every row in the pool has one obvious target. Cursors corrected in
    // CSS so neither the dead row body nor the live chips lie about it.
    // GLOW-UP 246b — the row picks YOUR book when you have one.
    // 246 had the row toggle the best-VALUE entry, which is right for shopping
    // and wrong for the job that surfaced it: rebuilding a ticket already placed.
    // Every leg of the UFC 330 parlay was on Underdog, but best-value for an OVER
    // is the lowest number, so row-clicking Ribovics added Pick6 99.5 and Islam
    // would have added PrizePicks 63.55 — never the UD line the user actually
    // holds. When the prop is one you placed, your book leads.
    const rowPick = books.find(a => isBookPlaced(a.leg)) || books[0];
    const rowIsYours = rowPick !== books[0] || isBookPlaced(books[0].leg);
    const bestKey = parlayLegKeyOf(rowPick.leg);
    const bestBk = parlayLegBook(rowPick.leg, rowPick.fighter);
    const placedTag = isLegPlaced(head.leg)
      ? `<span class="parlay-leg-placed" title="You marked this prop placed for this event. The ● PLACED chip in the strip filters to just these; a book chip outlined in gold is the one you placed at.">●</span>`
      : '';
    return `<div class="parlay-leg-row is-grouped off-board ${confClass}${parlaySelectedLegs.has(bestKey) ? ' selected' : ''}" title="Off-board. ${(head.leg.offReason || '').replace(/"/g, '&quot;')}" data-parlay-key="${bestKey}" data-fighter="${head.leg.fighter}" data-stat="${head.leg.stat}" data-dir="${dir}">
      <span class="parlay-leg-check is-multi" data-parlay-key="${bestKey}" title="${selected.length} of ${books.length} books on this prop are in your slip. Click to ${parlaySelectedLegs.has(bestKey) ? 'remove' : 'add'} ${rowIsYours ? 'the book you placed at' : `the best ${dir.toUpperCase()} entry`} (${bestBk ? (PL_BOOK_NAME[bestBk] || bestBk) : 'no book'} ${rowPick.leg.line}) — or click any book chip for that specific number.">${selected.length ? `☑<i>${selected.length}</i>` : '☐'}</span>
      <span class="plr-id">
        <span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">🥊</span><img class="bp-avatar-img" data-name="${head.leg.fighter}" alt="" /></span><span class="parlay-leg-name" title="${prettyName(head.leg.fighter)}">${prettyName(head.leg.fighter)}</span>
        ${vsTag}${placedTag}
      </span>
      <span class="parlay-leg-dir ${dir}">${dir.toUpperCase()}</span>
      <span class="parlay-leg-stat src-${head.leg.stat}">${head.leg.stat === 'ss_r1' ? 'R1 SS' : head.leg.stat.toUpperCase()}</span>
      <span class="plr-market"><span class="plg-books" title="Every book posting this prop. Confidence and EV are the same whichever you take — only the number moves.">${chips}</span></span>
      ${parlayYouTag(head.leg.stat, dir)}
      ${evTag}${offMargTag(rowPick.leg, selected.length > 0)}
      <span class="parlay-leg-conf">${head.leg.confidence}%<i class="plc-bar"><b style="width:${Math.min(100, Math.max(8, head.leg.confidence))}%"></b></i></span>
    </div>`;
  };
  // ── GLOW-UP 284 — both sides of a prop are ONE prop ──────────────────────
  // The off-board tier collects every side the ranked pool did not take, so a
  // prop the model has no read on arrives as TWO rows — identical fighter,
  // identical stat, adjacent, differing only in the direction chip. Reinier De
  // Ridder ran five consecutive rows on this card, Anthony Wint four, with
  // `OVER SS 16.5 −8%` sitting directly on top of `UNDER SS 16.5 −8%`.
  //
  // Nothing is dropped — both sides stay fully selectable, because the whole
  // point of this tier is being able to take either one. They just stop being
  // presented as two unrelated ideas. One prop, one row, one identity, with each
  // side keeping its own books, its own YOU record, its own EV and confidence:
  // those genuinely differ (Gaziev's FT sides price at −14% and −4% off two
  // different lines), so they are shown per side rather than merged away.
  //
  // Placement is left to grid auto-flow with `grid-row: span 2` on the three
  // shared cells. Explicit column numbers would have been wrong the moment the
  // no-delta and narrow variants drop tracks; auto-flow lands correctly on all
  // three track lists because the per-side cell count always matches the number
  // of non-shared columns.
  const sideCells = (g: typeof offBoardLegs, dir: 'over' | 'under'): { dirBtn: string; rest: string } => {
    const head = g[0];
    const legEv = evOf(head);
    const books = [...g].sort((a, b) => dir === 'over'
      ? (a.leg.line ?? 0) - (b.leg.line ?? 0)
      : (b.leg.line ?? 0) - (a.leg.line ?? 0));
    const chips = books.map((a, i) => {
      const k = parlayLegKeyOf(a.leg);
      const on = parlaySelectedLegs.has(k);
      const pk = parlayLegBook(a.leg, a.fighter);
      const label = pk ? platformKeyShort(pk) : 'NO BK';
      const tip = `${pk ? (PL_BOOK_NAME[pk] || pk) : 'No book the scraper can see'} ${a.leg.line}`
        + `${i === 0 ? ` — best ${dir.toUpperCase()} entry of the ${books.length}` : ''}`
        + `${pk != null ? '' : ' · queue it anyway if you have it somewhere'}`
        + ` · ${on ? 'in your slip — click to remove' : 'click to add this book to your slip'}`;
      return `<button type="button" class="plg-book plat-${pk || 'none'}${on ? ' on' : ''}${i === 0 ? ' is-best' : ''}${isBookPlaced(a.leg) ? ' is-placed' : ''}"`
        + ` data-parlay-key="${k}" title="${tip.replace(/"/g, '&quot;')}">${label} <b>${a.leg.line}</b>${on ? '<i>✓</i>' : ''}</button>`;
    }).join('');
    const pick = books.find(a => isBookPlaced(a.leg)) || books[0];
    const pickKey = parlayLegKeyOf(pick.leg);
    const pickBk = parlayLegBook(pick.leg, pick.fighter);
    const nSel = g.filter(a => parlaySelectedLegs.has(parlayLegKeyOf(a.leg))).length;
    const evTag = legEv != null
      ? `<span class="parlay-leg-ev ${legEv > 0 ? 'pos' : legEv < 0 ? 'neg' : ''}" title="Calibrated EV for this side as a single pick. Identical across the books on this side — EV prices the model's confidence, not the line.">${legEv > 0 ? '+' : ''}${legEv}%</span>`
      : '<span class="parlay-leg-ev plr-empty"></span>';
    const dirBtn = `<button type="button" class="parlay-leg-dir ${dir} plr-side${nSel ? ' has-sel' : ''}" data-parlay-key="${pickKey}"`
      + ` title="${dir.toUpperCase()} — ${nSel} of ${books.length} book${books.length === 1 ? '' : 's'} on this side are in your slip. Click to ${parlaySelectedLegs.has(pickKey) ? 'remove' : 'add'} ${isBookPlaced(pick.leg) ? 'the book you placed at' : `the best ${dir.toUpperCase()} entry`} (${pickBk ? (PL_BOOK_NAME[pickBk] || pickBk) : 'no book'} ${pick.leg.line}), or click any book chip for that specific number.">${dir.toUpperCase()}${nSel ? `<i>${nSel}</i>` : ''}</button>`;
    const rest = `<span class="plr-market"><span class="plg-books" title="Every book posting this side. Confidence and EV are the same whichever you take — only the number moves.">${chips}</span></span>`
      + parlayYouTag(head.leg.stat, dir)
      + evTag
      // GLOW-UP 293: keyed on whether ANY book on this side is in the slip, not on
      // whether the row's default pick happens to be. Taking PP 50.5 rather than the
      // best-value UD 47.5 left the side reading `·0` — an invitation to add a side
      // already held — while sides taken at their default pick correctly showed
      // nothing. The side is the unit here; which book you took is not.
      + offMargTag(pick.leg, nSel > 0)
      + `<span class="parlay-leg-conf">${head.leg.confidence}%<i class="plc-bar"><b style="width:${Math.min(100, Math.max(8, head.leg.confidence))}%"></b></i></span>`;
    // Split, because grid auto-flow places by DOM order and the shared `stat`
    // cell sits BETWEEN the direction column and the market column in the track
    // list. Emitting a side as one blob put stat in the confidence column.
    return { dirBtn, rest };
  };

  const renderPairedOffRow = (over: typeof offBoardLegs, under: typeof offBoardLegs): string => {
    const head = over[0];
    const all = [...over, ...under];
    const nSel = all.filter(a => parlaySelectedLegs.has(parlayLegKeyOf(a.leg))).length;
    const topConf = Math.max(over[0].leg.confidence, under[0].leg.confidence);
    const confClass = topConf >= 72 ? 'conf-high' : topConf >= 58 ? 'conf-med' : 'conf-low';
    const vsTag = head.leg.opponent
      ? `<span class="parlay-leg-vs" title="Opponent: ${prettyName(head.leg.opponent)}">vs ${prettyName(head.leg.opponent).split(' ').slice(-1)[0]}</span>`
      : '';
    const placedTag = isLegPlaced(head.leg)
      ? `<span class="parlay-leg-placed" title="You marked this prop placed for this event. A book chip outlined in gold is the one you placed at.">●</span>`
      : '';
    const overCells = sideCells(over, 'over');
    const underCells = sideCells(under, 'under');
    return `<div class="parlay-leg-row is-paired off-board ${confClass}${nSel ? ' selected' : ''}" title="Off-board. ${(head.leg.offReason || '').replace(/"/g, '&quot;')}" data-fighter="${head.leg.fighter}" data-stat="${head.leg.stat}">
      <span class="parlay-leg-check is-multi plr-span2" title="${nSel} of ${all.length} book${all.length === 1 ? '' : 's'} across both sides of this prop are in your slip. Both sides stay available — click a side label to take its best entry, or any book chip for that exact number.">${nSel ? `☑<i>${nSel}</i>` : '☐'}</span>
      <span class="plr-id plr-span2">
        <span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">🥊</span><img class="bp-avatar-img" data-name="${head.leg.fighter}" alt="" /></span><span class="parlay-leg-name" title="${prettyName(head.leg.fighter)}">${prettyName(head.leg.fighter)}</span>
        ${vsTag}${placedTag}
      </span>
      ${overCells.dirBtn}
      <span class="parlay-leg-stat src-${head.leg.stat} plr-span2">${head.leg.stat === 'ss_r1' ? 'R1 SS' : head.leg.stat.toUpperCase()}</span>
      ${overCells.rest}
      ${underCells.dirBtn}${underCells.rest}
    </div>`;
  };

  const renderOffBoardRows = (legs: typeof offBoardLegs): string => {
    // Group by PROP (fighter + stat), then split the sides inside it, so a prop
    // with both sides available renders once instead of twice.
    const props = new Map<string, { over: typeof offBoardLegs; under: typeof offBoardLegs }>();
    const order: string[] = [];
    for (const a of legs) {
      const pk = `${a.leg.fighter}|${a.leg.stat}`;
      let cur = props.get(pk);
      if (!cur) { cur = { over: [], under: [] }; props.set(pk, cur); order.push(pk); }
      (a.leg.direction === 'over' ? cur.over : cur.under).push(a);
    }
    const one = (g: typeof offBoardLegs): string =>
      (g.length === 1 ? renderPoolRow(g[0]) : renderGroupedOffRow(g));
    return order.map(pk => {
      const { over, under } = props.get(pk)!;
      // Only pair when BOTH sides survived the direction filter — with OVER or
      // UNDER selected in the strip there is only ever one side to show.
      if (over.length && under.length) return renderPairedOffRow(over, under);
      return over.length ? one(over) : one(under);
    }).join('');
  };
  const offPropCount = new Set(displayOffLegs.map(a => `${a.leg.fighter}|${a.leg.stat}`)).size;

  // Rendered here (not at the map above) so the row can name its book via
  // PL_BOOK_NAME without tripping over the const's temporal dead zone.
  const poolRows = displayLegs.map(renderPoolRow).join('');
  const offRows = parlayPoolShowOffBoard ? renderOffBoardRows(displayOffLegs) : '';
  // GLOW-UP 207: the off-board section header. Always present when there is
  // anything down there — the note has to be readable BEFORE expanding, or the
  // rows read as a second ranked list rather than the model's leftovers.
  const offBoardHtml = displayOffLegs.length ? `<div class="parlay-offboard">
      <button class="parlay-offboard-head${parlayPoolShowOffBoard ? ' open' : ''}" data-plq-offboard title="${parlayPoolShowOffBoard ? 'Hide' : 'Show'} the props that didn't make the ranked pool">
        <span class="pob-caret">${parlayPoolShowOffBoard ? '▾' : '▸'}</span>
        OFF-BOARD PROPS <span class="parlay-count-pill">${displayOffLegs.length}${displayOffLegs.length !== offBoardLegs.length ? `/${offBoardLegs.length}` : ''}</span>
        <span class="pob-props" title="${displayOffLegs.length} legs across ${offPropCount} distinct props — a prop with several books posting it is ONE row with a book rail, not one row per book.">${offPropCount} props</span>
      </button>
      <div class="parlay-offboard-note" title="These didn't make the ranked pool — the model leans the other side, has no read on the prop, or the market itself won't carry the side (CTRL is over-only, a demon/goblin KD is More-only, a dog's FP UNDER is blocked on Pick6 and Betr). Confidence is the model's own complement, or 50% where it has no read; EV and slip health price them exactly like any other leg, so they simply sort low. Hover any off-board flag for that leg's own reason.">Fully parlayable — they sort low because the model is against them or silent on them. <b>Hover a row for why.</b>${parlayPoolShowOffBoard ? '' : ' Open to build off them.'}</div>
      ${offRows}
    </div>` : '';
  const parlayLegClip = (l: ParlayLeg, lf: AnalyzerFighter): string => {
    const pk = parlayLegBook(l, lf);
    const oppOk = l.opponent && l.opponent !== '?';
    return `${prettyName(l.fighter)} ${l.direction.toUpperCase()} ${l.line} ${PL_STAT_CLIP[l.stat] || l.stat.toUpperCase()}${pk ? ` @ ${PL_BOOK_NAME[pk] || pk}` : ''}${oppOk ? ` (vs ${prettyName(l.opponent)})` : ''}`;
  };

  // GLOW-UP 191 (L5): legs that share a fight aren't independent, and the slip
  // said so only via a chip. Group them under the matchup so "2 legs on one
  // fight ≈ 1 bet" is visible in the STRUCTURE. Single-leg fights render bare —
  // grouping every row would add chrome where there's no correlation to show.
  const slipFightKey = (l: ParlayLeg): string => [legNorm(l.fighter), legNorm(l.opponent)].sort().join('|');
  const renderSlipLeg = ({ leg: l, fighter: lf }: { leg: ParlayLeg; fighter: AnalyzerFighter }): string => {
        const key = parlayLegKeyOf(l);
        const pk = parlayLegBook(l, lf);
        const platChip = pk
          ? `<span class="parlay-leg-plat plat-${pk}" title="Line source: ${l.offBoard ? `${PL_BOOK_NAME[pk] || pk} ${l.line} — best book for this SIDE` : formatSourcePlatformLabel(lf, l.stat)}">${platformKeyShort(pk)}</span>`
          : (l.offBoard ? '<span class="parlay-leg-plat plat-none" title="No book the scraper can see posts this side — enter it wherever you have it.">NO BK</span>' : '');
        // The off-board flag rides along into the slip: once a leg is in the
        // ticket its row no longer says which tier it came from, and "this leg is
        // the side the model is against" is exactly what you want visible while
        // reading a built slip.
        const offTag = l.offBoard
          ? `<span class="parlay-leg-off" title="${(l.offReason || '').replace(/"/g, '&quot;')}">off-board</span>`
          : '';
        const clip = parlayLegClip(l, lf);
        return `<div class="parlay-slip-leg${l.offBoard ? ' off-board' : ''}">
          <span class="parlay-slip-remove" data-parlay-remove="${key}" title="Remove leg">✕</span>
          <span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">🥊</span><img class="bp-avatar-img" data-name="${l.fighter}" alt="" /></span><span class="parlay-leg-name" style="flex:1">${prettyName(l.fighter)}</span>${offTag}
          <span class="parlay-leg-dir ${l.direction}">${l.direction.toUpperCase()}</span>
          <span class="parlay-leg-stat src-${l.stat}">${l.stat === 'ss_r1' ? 'R1 SS' : l.stat.toUpperCase()}</span>
          <span class="parlay-leg-line">${l.line}</span>
          ${platChip}
          ${parlayYouTag(l.stat, l.direction)}
          <button class="parlay-slip-copy" data-parlay-clip="${clip.replace(/"/g, '&quot;')}" title="Copy slip line: ${clip.replace(/"/g, '&quot;')}">⧉</button>
        </div>`;
  };

  const slipRows = (() => {
    if (!selectedPairs.length) return '<div class="parlay-slip-empty">Click legs on the left to build your parlay</div>';
    // Preserve selection order; group only where a fight actually repeats.
    const order: string[] = [];
    const groups = new Map<string, typeof selectedPairs>();
    for (const p of selectedPairs) {
      const k = slipFightKey(p.leg);
      if (!groups.has(k)) { groups.set(k, []); order.push(k); }
      groups.get(k)!.push(p);
    }
    return order.map((k) => {
      const grp = groups.get(k)!;
      if (grp.length < 2) return renderSlipLeg(grp[0]);
      const a = grp[0].leg;
      const matchup = `${prettyName(a.fighter)} vs ${a.opponent && a.opponent !== '?' ? prettyName(a.opponent) : '?'}`;
      // Strongest pairwise correlation inside this fight, for the header badge.
      let strongest: CorrelationAlert | null = null;
      for (let i = 0; i < grp.length; i++) for (let j = i + 1; j < grp.length; j++) {
        const c1 = fighterForLeg(grp[i].leg); const c2 = fighterForLeg(grp[j].leg);
        if (!c1 || !c2) continue;
        const al = calcPairCorrelation(grp[i].leg, c1, grp[j].leg, c2);
        if (al && (!strongest || Math.abs(al.impact) > Math.abs(strongest.impact))) strongest = al;
      }
      const badge = strongest
        ? `<span class="psf-corr ${strongest.type}" title="${String(strongest.message).replace(/"/g, '&quot;')}">${strongest.type === 'conflict' ? '✗' : strongest.type === 'synergy' ? '🔗' : '⚠'} ${strongest.impact > 0 ? '+' : ''}${Math.round(strongest.impact * 100)}%</span>`
        : '';
      return `<div class="parlay-slip-fight">
        <div class="psf-head" title="These ${grp.length} legs come from ONE fight — they share its duration and outcome, so they are correlated rather than independent bets.">
          <span class="psf-matchup">${matchup}</span><span class="psf-count">${grp.length} legs · one fight</span>${badge}
        </div>
        ${grp.map(renderSlipLeg).join('')}
      </div>`;
    }).join('');
  })();

  // GLOW-UP 178: whole-slip export — every selected leg as slip-ready lines,
  // grouped in book order (matches the Best Picks tray COPY ALL behavior).
  const PL_BOOK_ORDER = ['pick6', 'underdog', 'prizepicks', 'betr', 'draftkings_sportsbook'];
  const parlaySlipClipAll = (): string => {
    const withBook = selectedPairs.map(({ leg: l, fighter: lf }) => ({
      book: getSourceActivePlatformKey(lf, l.stat) || 'zzz',
      text: parlayLegClip(l, lf),
    }));
    withBook.sort((a, b) => {
      const ai = PL_BOOK_ORDER.indexOf(a.book); const bi = PL_BOOK_ORDER.indexOf(b.book);
      return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
    });
    return withBook.map(x => x.text).join('\n');
  };
  const copySlipBtn = selectedPairs.length
    ? `<button class="parlay-copy-slip" data-parlay-copyslip="1" title="Copy all ${selectedPairs.length} leg${selectedPairs.length === 1 ? '' : 's'} as slip-ready lines">⧉ COPY SLIP</button>`
    : '';
  // GLOW-UP 181: place the whole slip into the Parlay Ledger (Data view).
  // Needs 2+ legs — a parlay by definition.
  const placeParlayBtn = selectedPairs.length >= 2
    ? `<button class="parlay-place-slip" data-parlay-place="1" title="Save this slip to your Parlay Ledger (Data view) for this event — records what you actually entered, graded against results after the event">● PLACE PARLAY</button>`
    : '';

  // Slip intelligence: calibrated per-leg probabilities (same recalibration the
  // board's confidence chips use, clamped 35-85 so one hot leg can't print
  // silly numbers), their product as combined hit probability, the weakest leg,
  // and stake-inclusive payout EV per platform table. Independence assumed —
  // contradictory slips get the ⛔ chip instead of an EV number.
  let slipSummaryHtml = '';
  let swapPlan: { fromKey: string; toKey: string; toLabel: string } | null = null;
  if (selectedLegs.length >= 2) {
    // GLOW-UP 191 (L4): shared analysis — the suggestion cards run the exact
    // same function, so a suggestion's EV can't disagree with the slip's.
    const A = analyzeSlipLegs(selectedLegs)!;
    const { n, combined, evRows, best, anyCorr, maxPosCorr, anyRecal } = A;
    const weakest = selectedLegs.reduce((w, l) => (l.confidence < w.confidence ? l : w), selectedLegs[0]);
    const weakestKey = parlayLegKeyOf(weakest);
    const slipContradiction = selectedLegs.map((l) => conflictsWithSlip(l)).find((m): m is string => !!m) || null;

    // GLOW-UP 191 (L3): the weakest leg was a passive warning. Find the best
    // legal replacement now so the chip can offer a one-click fix — highest
    // confidence, not already selected, stronger than what it replaces, and not
    // conflicting with the REST of the slip. availableLegs is confidence-desc,
    // so the first match is the best one.
    const restOfSlip = selectedLegs.filter((l) => parlayLegKeyOf(l) !== weakestKey);
    const swapCand = availableLegs.find((a) => {
      const k = parlayLegKeyOf(a.leg);
      if (parlaySelectedLegs.has(k)) return false;
      if (a.leg.confidence <= weakest.confidence) return false;
      return !conflictAgainst(a.leg, restOfSlip);
    });
    if (swapCand) {
      swapPlan = {
        fromKey: weakestKey,
        toKey: parlayLegKeyOf(swapCand.leg),
        toLabel: `${prettyName(swapCand.leg.fighter)} ${swapCand.leg.direction.toUpperCase()} ${swapCand.leg.stat === 'ss_r1' ? 'R1 SS' : swapCand.leg.stat.toUpperCase()} ${swapCand.leg.line} (${swapCand.leg.confidence}%)`,
      };
    }

    let payoutHtml = '';
    if (!slipContradiction && evRows.length) {
      payoutHtml = `<span class="pss-payouts" title="Stake-inclusive payout tables × ${anyRecal ? 'recalibrated' : 'model'} leg probabilities${anyCorr ? ', correlation-adjusted for same-fight legs (Gaussian copula)' : ' (independent)'}. Verify multipliers in-app — promos and boosts change them.">${evRows.map((r, idx) => `<span class="pss-ev ${idx === 0 ? 'best ' : ''}${r.ev >= 0 ? 'pos' : 'neg'}">${idx === 0 ? '★ ' : ''}${r.label} ${r.mult}x <b>${r.ev >= 0 ? '+' : ''}${r.ev}%</b></span>`).join('')}</span>`;
    }

    // GLOW-UP 191 (L2): the headline numbers become a deck, and the missing one
    // is the DOLLAR return — EV% and a multiplier don't answer "what does this
    // pay". $10 is the reference stake.
    const STAKE = 10;
    const deckHtml = (!slipContradiction && best)
      ? `<div class="pss-deck">
          <div class="pss-tile"><span class="pss-t-label">LEGS</span><b class="pss-t-val">${n}</b></div>
          <div class="pss-tile" title="${anyCorr ? 'Joint P(all hit) — correlation-adjusted for same-fight legs via a duration copula, not the independent product' : 'Product of independent leg probabilities'} (clamped 35-85)"><span class="pss-t-label">COMBINED</span><b class="pss-t-val">~${combined}%</b></div>
          <div class="pss-tile" title="Highest-EV book for this ${n}-leg slip at ${anyRecal ? 'recalibrated' : 'model'} leg probabilities${anyCorr ? ', correlation-adjusted for same-fight legs' : ' (independent)'}. Verify multipliers in-app — promos and boosts change them."><span class="pss-t-label">BEST BOOK</span><b class="pss-t-val">${best.label} <i class="pss-t-mult">${best.mult}x</i></b></div>
          <div class="pss-tile" title="What a $${STAKE} stake returns if ALL ${n} legs hit, at ${best.label}'s ${best.mult}x. This is the payout, not the expected value — the EV tile prices how likely that is."><span class="pss-t-label">$${STAKE} RETURNS</span><b class="pss-t-val money">$${(STAKE * best.mult) % 1 === 0 ? (STAKE * best.mult).toFixed(0) : (STAKE * best.mult).toFixed(2)}</b></div>
          <div class="pss-tile" title="Expected value at the best book — the payout table weighted by the calibrated chance of each hit-count. Negative means the price doesn't clear the model's probability."><span class="pss-t-label">EV</span><b class="pss-t-val ${best.ev >= 0 ? 'pos' : 'neg'}">${best.ev >= 0 ? '+' : ''}${best.ev}%</b></div>
        </div>`
      : '';

    slipSummaryHtml = `<div class="parlay-slip-summary">
      ${deckHtml}
      <div class="pss-strip">
        <span class="pss-weak" title="Lowest-confidence leg in the slip — the most likely one to sink it">WEAKEST <b>${prettyName(weakest.fighter)} ${weakest.stat === 'ss_r1' ? 'R1 SS' : weakest.stat.toUpperCase()} ${weakest.confidence}%</b><button class="pss-weak-act" data-parlay-drop="${weakestKey}" title="Drop this leg from the slip">✕ drop</button>${swapPlan ? `<button class="pss-weak-act swap" data-parlay-swap="1" title="Swap it for ${swapPlan.toLabel.replace(/"/g, '&quot;')} — the highest-confidence available leg that doesn't conflict with the rest of your slip">⇄ swap</button>` : ''}</span>
        ${maxPosCorr >= 0.5 ? `<span class="pss-corr" title="Same-fight legs here are strongly positively correlated — they mostly hit or miss together, so this slip is closer to ONE bet than ${selectedLegs.length}. The combined % and EV account for it, but you are not diversifying.">🔗 ~1 BET (correlated)</span>` : anyCorr ? `<span class="pss-corr" title="Same-fight legs are correlated — the combined % and EV are the joint probability, not the independent product.">🔗 corr-adjusted</span>` : ''}
        ${payoutHtml}
        ${slipContradiction ? `<span class="pss-conflict" title="${slipContradiction.replace(/"/g, '&quot;')}">⛔ CONTRADICTORY LEGS</span>` : ''}
      </div>
    </div>`;
  }

  // Health display
  let healthHtml = '';
  if (health) {
    const alertsHtml = health.alerts.map(a => {
      const icon = a.type === 'synergy' ? '✓' : a.type === 'conflict' ? '✗' : a.type === 'caution' ? '⚠' : '○';
      return `<div class="parlay-corr-alert ${a.type}">${icon} ${a.message}</div>`;
    }).join('');

    // GLOW-UP 197 L1 — decompose the score. It's four separate terms collapsed into
    // one number, so a "93 EXCELLENT" told you nothing about what to change. Each
    // term is now a chip: where the score started (avg leg confidence) and what
    // each adjustment did to it.
    const bd = health.breakdown;
    const bdHtml = bd ? `<div class="ph-breakdown">
      <span class="ph-bd" title="Starting point: the average confidence of your ${health.legCount} legs. Everything else adjusts this.">conf <b>${bd.base.toFixed(0)}</b></span>
      ${bd.corr !== 0 ? `<span class="ph-bd ${bd.corr > 0 ? 'pos' : 'neg'}" title="Net correlation adjustment across every leg pair. Positive = the legs reinforce each other (synergy); negative = they fight each other or ride the same outcome.">corr <b>${bd.corr > 0 ? '+' : ''}${bd.corr.toFixed(1)}</b></span>` : ''}
      ${bd.legs !== 0 ? `<span class="ph-bd ${bd.legs > 0 ? 'pos' : 'neg'}" title="${bd.legs > 0 ? '2-4 legs is the sweet spot — enough payout without stacking too much that must all land.' : 'Six or more legs is penalised: every extra leg multiplies the ways the slip dies.'}">legs <b>${bd.legs > 0 ? '+' : ''}${bd.legs}</b></span>` : ''}
      ${bd.diversity !== 0 ? `<span class="ph-bd pos" title="Every leg comes from a different fight, so no single fight going wrong takes out more than one leg.">spread <b>+${bd.diversity}</b></span>` : ''}
    </div>` : '';
    // ── GLOW-UP 206 L1 ───────────────────────────────────────────────────
    // The health score is avgConfidence + correlation + legCount + diversity.
    // EV is nowhere in it, yet the grade renders as a bare "EXCELLENT" — so a
    // slip priced at -26% read EXCELLENT, sitting directly above its own
    // negative number. The score is not wrong, it is just answering a narrower
    // question than its label implies: is this well BUILT, not is it worth
    // backing. Both verdicts now sit side by side, same split Best Picks
    // already uses with LEAN ✓ · VALUE ✗.
    // `A` above is scoped to the slip-summary block, so re-derive here. Same
    // pure function, so the two can't disagree.
    const hb = analyzeSlipLegs(selectedLegs)?.best ?? null;
    const slipEv = hb ? hb.ev : null;
    const valueHtml = (hb && slipEv != null)
      ? `<span class="ph-value ${slipEv >= 0 ? 'pos' : 'neg'}" title="${slipEv >= 0
          ? `Priced at ${hb.label} ${hb.mult}x this slip clears breakeven. The health score beside it grades STRUCTURE — leg confidence, correlation, spread — and does not include price. Both good is the case you want.`
          : `The health score grades STRUCTURE only — leg confidence, correlation and spread — and does not include price. This slip is well BUILT but priced below breakeven on every payout table available (best is ${hb.label} ${hb.mult}x at ${slipEv}%). Fine as a pick-em ticket you want for other reasons; it is not a value play.`}">VALUE ${slipEv >= 0 ? '✓' : '✗'} <b>${slipEv >= 0 ? '+' : ''}${slipEv}%</b></span>`
      : '';
    healthHtml = `<div class="parlay-health">
      <div class="parlay-health-title">PARLAY HEALTH</div>
      <span class="parlay-health-score ${health.grade}">${health.score}</span>
      <span class="parlay-health-label">${health.grade.toUpperCase()} STRUCTURE — ${health.legCount} legs, avg conf ${Math.round(health.avgConfidence)}%</span>
      ${valueHtml}
      ${bdHtml}
      ${alertsHtml ? `<div class="parlay-corr-list">${alertsHtml}</div>` : ''}
    </div>`;
  }

  // Suggested parlays
  let suggestHtml = '';
  if (suggestions.length > 0) {
    const cards = suggestions.map((s, i) => {
      const legsText = s.legs.map(l =>
        `${l.fighter} <span class="parlay-leg-dir ${l.direction}" style="display:inline">${l.direction.toUpperCase()}</span> ${l.stat.toUpperCase()} ${l.line}`
      ).join('<br>');
      const alertCount = s.health.alerts.filter(a => a.type === 'synergy').length;
      const conflictCount = s.health.alerts.filter(a => a.type === 'conflict').length;
      const tag = alertCount > 0 ? `${alertCount} synerg${alertCount > 1 ? 'ies' : 'y'}` : '';
      const cTag = conflictCount > 0 ? `${conflictCount} conflict${conflictCount > 1 ? 's' : ''}` : '';
      const tags = [tag, cTag].filter(Boolean).join(', ');
      const legKeys = s.legs.map(l => parlayLegKeyOf(l));
      const legsDataAttr = legKeys.join(',');
      // GLOW-UP 191 (L4): price the suggestion with the SAME analysis the slip
      // uses, so "score 83" is no longer the only number — you can compare a
      // suggestion to what you've built on the axis that decides placement.
      const sa = analyzeSlipLegs(s.legs);
      const evChip = sa?.best
        ? `<span class="psg-ev ${sa.best.ev >= 0 ? 'pos' : 'neg'}" title="Best-EV book for this suggestion at ${sa.anyRecal ? 'recalibrated' : 'model'} leg probabilities${sa.anyCorr ? ', correlation-adjusted' : ''} — same pipeline as your slip deck. $10 returns $${(10 * sa.best.mult) % 1 === 0 ? (10 * sa.best.mult).toFixed(0) : (10 * sa.best.mult).toFixed(2)} if all ${sa.n} hit.">${sa.best.label} ${sa.best.mult}x <b>${sa.best.ev >= 0 ? '+' : ''}${sa.best.ev}%</b></span>`
        : '';
      const combChip = sa ? `<span class="psg-comb" title="Joint probability all ${sa.n} legs hit${sa.anyCorr ? ' (correlation-adjusted)' : ''}">~${sa.combined}%</span>` : '';
      // Diff vs the live slip — is this a small tweak or a different bet?
      const shared = legKeys.filter(k => parlaySelectedLegs.has(k)).length;
      const fresh = legKeys.length - shared;
      // "Matches" only when it's the SAME set — all suggestion legs in the slip
      // AND no extras in the slip. A strict subset must not read as a match: it
      // implies loading changes nothing when it would actually drop legs.
      const dropped = selectedLegs.length - shared;
      const isExactMatch = shared === legKeys.length && dropped === 0;
      const diffLabel = isExactMatch
        ? 'MATCHES YOUR SLIP'
        : `${shared} shared · +${fresh} new${dropped > 0 ? ` · −${dropped}` : ''}`;
      const diffChip = selectedLegs.length
        ? `<span class="psg-diff${isExactMatch ? ' same' : ''}" title="How this suggestion compares to the slip you've built: ${shared} leg${shared === 1 ? '' : 's'} you already have, ${fresh} new${dropped > 0 ? `, and it drops ${dropped} of yours` : ''}. Loading it replaces your current selection.">${diffLabel}</span>`
        : '';
      // GLOW-UP 206 L2 — the score grades STRUCTURE. Saying "(excellent)" beside
      // a ticket priced at -50% reads as an endorsement of the bet.
      const sNeg = !!sa?.best && sa.best.ev < 0;
      return `<div class="parlay-suggest-card grade-${s.health.grade}${sNeg ? ' psg-negev' : ''}" data-suggest-legs="${legsDataAttr}" title="Click to load these ${legKeys.length} legs into your slip (replaces the current selection)">
        <div class="parlay-suggest-label">#${i + 1} — Score: ${s.health.score} (${s.health.grade} structure)${sNeg ? '<span class="psg-negtag" title="Well built, but priced below breakeven at every payout table available. Ranked below any suggestion that clears it.">✗ VALUE</span>' : ''}<span class="psg-load">LOAD →</span></div>
        <div class="parlay-suggest-legs">${legsText}</div>
        <div class="parlay-suggest-meta">${combChip}${evChip}${diffChip}</div>
        <div class="parlay-suggest-score">Avg confidence: ${Math.round(s.health.avgConfidence)}%${tags ? ` · ${tags}` : ''}</div>
      </div>`;
    }).join('');

    // ── GLOW-UP 278 — three cards, one bet ───────────────────────────────
    // On this board #1 is Gaziev TD UNDER + Reed SS UNDER, and #2 and #3 are that
    // exact pair plus one extra leg. Measured: #1∩#2 = 2 of 2, #1∩#3 = 2 of 2 —
    // the whole of the first suggestion is contained in both the others. Three
    // cards stacked vertically read as three independent ideas to compare; they
    // are one idea with two garnishes, and if the core is wrong all three die
    // together. That is the single most useful thing about the section and it
    // was the one thing it did not say. Only stated when the overlap is real —
    // a genuinely diverse set of suggestions shows nothing.
    const sugSets = suggestions.map(s2 => s2.legs.map(l => parlayLegKeyOf(l)));
    const sharedCore = sugSets.length > 1
      ? sugSets.reduce((acc, cur) => acc.filter(k => cur.includes(k)))
      : [];
    const minLen = sugSets.length ? Math.min(...sugSets.map(x => x.length)) : 0;
    const coreNote = sharedCore.length >= 2
      ? `<div class="psg-core" title="Every suggestion below is built on the same ${sharedCore.length} legs${sharedCore.length === minLen ? ', and the shortest of them is nothing but that core' : ''}. They are variations on one bet, not ${sugSets.length} independent reads — if the shared core misses, all ${sugSets.length} miss together. Compare them on what they ADD, not as alternatives.">⚠ All ${sugSets.length} share the same ${sharedCore.length}-leg core — variations on one bet, not ${sugSets.length} separate reads</div>`
      : '';

    suggestHtml = `<div class="parlay-suggest-section">
      <div class="parlay-suggest-title">AI SUGGESTED PARLAYS</div>
      ${coreNote}
      ${!anySuggestionPositive
        ? `<div class="psg-none-positive" title="These are ranked on STRUCTURE — leg confidence, correlation, spread — because nothing available clears breakeven on price. They are the best-BUILT combinations on the board, not profitable ones. Shown so you can see what the model likes; the honest read is that this slate does not offer a priced parlay.">⚠ Nothing on this board clears breakeven — these are the best-built, not the best-priced</div>`
        : ''}
      ${cards}
    </div>`;
  }

  // Synergy pairs discovery
  const synergyPairs = findCorrelatedPairs(availableLegs);
  let synergyHtml = '';
  if (synergyPairs.length > 0) {
    const pairCards = synergyPairs.map(p => {
      const key1 = parlayLegKeyOf(p.leg1);
      const key2 = parlayLegKeyOf(p.leg2);
      const sel1 = parlaySelectedLegs.has(key1);
      const sel2 = parlaySelectedLegs.has(key2);
      const bothSelected = sel1 && sel2;
      const avgConf = Math.round((p.leg1.confidence + p.leg2.confidence) / 2);
      const impactPct = `+${(p.alert.impact * 100).toFixed(0)}%`;
      // GLOW-UP 206 L3 — these cards said the two legs move together and nothing
      // about whether backing them pays. "+18% health · avg 63%" is an argument
      // for correlation, and correlation is not edge: a perfectly synergistic
      // pair priced below breakeven is still a losing ticket, and this section
      // was the one place you could build one without ever seeing a price.
      // Same analyzeSlipLegs the slip and the suggestions use.
      const pb = analyzeSlipLegs([p.leg1, p.leg2])?.best ?? null;
      const pairEvHtml = pb
        ? `<span class="synergy-pair-ev ${pb.ev >= 0 ? 'pos' : 'neg'}" title="Best-priced book for this pair as a 2-leg ticket (${pb.label} ${pb.mult}x), correlation-adjusted — the same pipeline as your slip. Synergy is about whether they hit TOGETHER; this is whether the pair is worth backing at all.">${pb.label} ${pb.mult}x <b>${pb.ev >= 0 ? '+' : ''}${pb.ev}%</b></span>`
        : '';
      // GLOW-UP 228 L4 — say WHICH KIND of pair this is. "Ribovics UNDER TD +
      // Ribovics OVER SS" and "Robertson UNDER SS + Dern UNDER SS" were rendered
      // identically, and they are not the same bet: the first is one fighter
      // twice (a single profile read — if it's wrong, both legs die together),
      // the second is two fighters in one fight. Same word, very different
      // concentration.
      const sameFighter = legNorm(p.leg1.fighter) === legNorm(p.leg2.fighter);
      const scopeTag = sameFighter
        ? `<span class="synergy-pair-scope same-fighter" title="Both legs are the SAME FIGHTER — one profile read expressed twice. They hit together, and they miss together: this is concentration, not diversification.">SAME FIGHTER</span>`
        : `<span class="synergy-pair-scope same-fight" title="Two different fighters in the same bout. Correlated through the shape of the fight rather than through one man's night.">SAME FIGHT</span>`;
      // R1 SS renders as "SS_R1" through a bare toUpperCase — the pool rows have
      // always mapped it; these never did.
      const synStat = (s: string): string => (s === 'ss_r1' ? 'R1 SS' : s.toUpperCase());
      return `<div class="synergy-pair-card${bothSelected ? ' synergy-active' : ''}" data-synergy-key1="${key1}" data-synergy-key2="${key2}">
        <div class="synergy-pair-legs">
          <span class="synergy-pair-leg"><span class="parlay-leg-name">${prettyName(p.leg1.fighter)}</span> <span class="parlay-leg-dir ${p.leg1.direction}">${p.leg1.direction.toUpperCase()}</span> <span class="parlay-leg-stat">${synStat(p.leg1.stat)}</span> <span class="parlay-leg-line">${p.leg1.line}</span></span>
          <span class="synergy-pair-plus">+</span>
          <span class="synergy-pair-leg"><span class="parlay-leg-name">${prettyName(p.leg2.fighter)}</span> <span class="parlay-leg-dir ${p.leg2.direction}">${p.leg2.direction.toUpperCase()}</span> <span class="parlay-leg-stat">${synStat(p.leg2.stat)}</span> <span class="parlay-leg-line">${p.leg2.line}</span></span>
          ${scopeTag}
        </div>
        <div class="synergy-pair-reason">${p.alert.message}</div>
        <div class="synergy-pair-meta"><span class="synergy-pair-impact">${impactPct} health</span><span class="synergy-pair-conf">avg ${avgConf}%</span>${pairEvHtml}${bothSelected ? '<span class="synergy-pair-added">IN SLIP</span>' : ''}</div>
      </div>`;
    }).join('');
    synergyHtml = `<div class="synergy-pairs-section">
      <div class="synergy-pairs-title">SYNERGY PAIRS</div>
      <div class="synergy-pairs-subtitle">Correlated legs — if one hits, the other likely does too</div>
      ${pairCards}
    </div>`;
  }

  // ── GLOW-UP 281 — stop reserving a column for nothing ─────────────────
  // The marginal-delta chip only exists once the slip has two legs to re-score
  // against; below that EVERY row renders the empty placeholder, and the track
  // holds 50px of blank across a hundred rows — on the row that most needs the
  // width, because the fighter's name is the cell being squeezed for it. The
  // whole board knows at render time whether a single Δ can exist, so it can
  // drop the track outright rather than paying for the possibility.
  const noDeltaCls = baseHealthScore == null ? ' no-delta' : '';
  container.innerHTML = `<div class="parlay-lab${noDeltaCls}">
    <div class="parlay-lab-header">
      <div>
        <div class="parlay-lab-title">PARLAY LAB</div>
        <div class="parlay-lab-subtitle">Build multi-leg parlays with correlation analysis · ${availableLegs.length} ranked legs${offBoardLegs.length ? ` · ${offBoardLegs.length} off-board` : ''}</div>
      </div>
      <div class="parlay-selected-chip${selectedLegs.length >= 2 ? ' ready' : ''}">
        ${selectedLegs.length} leg${selectedLegs.length !== 1 ? 's' : ''} selected
      </div>
    </div>
    <div class="parlay-lab-cols">
      <div class="parlay-pool">
        <div class="parlay-pool-head-sticky">
          <div class="parlay-pool-title">RANKED LEGS <span class="parlay-count-pill">${displayLegs.length !== availableLegs.length ? `${displayLegs.length}/${availableLegs.length}` : availableLegs.length}</span></div>
          ${poolLegs.length ? parlayPoolControls : ''}
          ${poolLegs.length ? parlayPoolColumnHead : ''}
        </div>
        ${poolRows || (availableLegs.length
          ? '<div class="parlay-slip-empty">No ranked legs match the current filter — <button class="plq-reset">reset</button></div>'
          // The ranked pool being empty is no longer the end of the view: the
          // off-board section below can still have every side of every prop.
          : `<div class="parlay-slip-empty">No leans calculated yet${offBoardLegs.length ? ' — the off-board props below are still parlayable' : ''}</div>`)}
        ${offBoardHtml}
      </div>
      <div>
        <div class="parlay-builder">
          <div class="parlay-builder-title">YOUR PARLAY${selectedLegs.length ? ` <span class="parlay-count-pill">${selectedLegs.length}</span>` : ''}${copySlipBtn}${placeParlayBtn}</div>
          <div class="parlay-slip">${slipRows}</div>
          ${slipSummaryHtml}
          ${healthHtml}
        </div>
        ${suggestHtml}
        ${synergyHtml}
      </div>
    </div>
  </div>`;

  // ── Bind click handlers ──
  hydrateAvatarImgs(container);

  // GLOW-UP 279: stamp each row's position in the LIST, not in its markup. The
  // pool and the off-board tier are separate containers, so `:nth-child` restarts
  // halfway down and the cascade ran backwards across the boundary. Capped so a
  // hundred-row board still finishes arriving in about a quarter second.
  container.querySelectorAll<HTMLElement>('.parlay-leg-row').forEach((row, i) => {
    row.style.setProperty('--plr-i', String(Math.min(i, 29)));
  });

  // GLOW-UP 228 L1 — the book chips on a grouped off-board row each toggle their
  // OWN leg, so the click must not also reach the row (whose own key is absent).
  container.querySelectorAll<HTMLElement>('.plg-book, .plr-side').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset['parlayKey'];
      if (!key) return;
      if (parlaySelectedLegs.has(key)) parlaySelectedLegs.delete(key);
      else parlaySelectedLegs.add(key);
      renderParlayLab(container);
    });
  });

  // GLOW-UP 246: the grouped row's ☐ owns the best book's key. stopPropagation
  // so it can never also reach the row handler below.
  container.querySelectorAll<HTMLElement>('.parlay-leg-check[data-parlay-key]').forEach(box => {
    box.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = box.dataset['parlayKey'];
      if (!key) return;
      if (parlaySelectedLegs.has(key)) parlaySelectedLegs.delete(key);
      else parlaySelectedLegs.add(key);
      renderParlayLab(container);
    });
  });

  container.querySelectorAll<HTMLElement>('.parlay-leg-row').forEach(row => {
    row.addEventListener('click', () => {
      const key = row.dataset['parlayKey'];
      if (!key) return;
      if (parlaySelectedLegs.has(key)) {
        parlaySelectedLegs.delete(key);
      } else {
        parlaySelectedLegs.add(key);
      }
      renderParlayLab(container);
    });
  });

  container.querySelectorAll<HTMLElement>('.parlay-slip-remove').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset['parlayRemove'];
      if (!key) return;
      parlaySelectedLegs.delete(key);
      renderParlayLab(container);
    });
  });

  // GLOW-UP 191 (L3): weakest-leg actions — drop it, or swap it for the best
  // legal replacement computed during render.
  container.querySelectorAll<HTMLElement>('[data-parlay-drop]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const key = btn.dataset['parlayDrop'];
      if (!key) return;
      parlaySelectedLegs.delete(key);
      renderParlayLab(container);
    });
  });
  container.querySelectorAll<HTMLElement>('[data-parlay-swap]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (!swapPlan) return;
      parlaySelectedLegs.delete(swapPlan.fromKey);
      parlaySelectedLegs.add(swapPlan.toKey);
      showToast(`⇄ Swapped in ${swapPlan.toLabel}`);
      renderParlayLab(container);
    });
  });

  // GLOW-UP 177: command-strip handlers — re-render on any view change.
  // Clicking the active stat/direction chip toggles back to ALL.
  container.querySelectorAll<HTMLElement>('[data-plq-sort]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['plqSort'] as ParlaySortMode;
      if (v && v !== parlayPoolSort) { parlayPoolSort = v; renderParlayLab(container); }
    });
  });
  container.querySelectorAll<HTMLElement>('[data-plq-stat]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['plqStat'] as ParlayStatFilter;
      if (!v) return;
      parlayPoolStat = (parlayPoolStat === v ? 'all' : v);
      renderParlayLab(container);
    });
  });
  container.querySelectorAll<HTMLElement>('[data-plq-dir]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['plqDir'] as 'over' | 'under';
      if (!v) return;
      parlayPoolDir = (parlayPoolDir === v ? 'all' : v);
      renderParlayLab(container);
    });
  });
  // GLOW-UP 207: expand/collapse the off-board section. Session-scoped like the
  // rest of the command strip — it changes what's drawn, never what's selected.
  container.querySelectorAll<HTMLElement>('[data-plq-placed]').forEach(btn => {
    btn.addEventListener('click', () => {
      parlayPoolPlacedOnly = !parlayPoolPlacedOnly;
      // Placed legs are mostly off-board (they're the sides the model is against),
      // so filtering to them with that section collapsed would show an empty pool.
      if (parlayPoolPlacedOnly) parlayPoolShowOffBoard = true;
      renderParlayLab(container);
    });
  });
  container.querySelectorAll<HTMLElement>('[data-plq-offboard]').forEach(btn => {
    btn.addEventListener('click', () => {
      parlayPoolShowOffBoard = !parlayPoolShowOffBoard;
      renderParlayLab(container);
    });
  });
  container.querySelectorAll<HTMLElement>('.plq-reset').forEach(btn => {
    btn.addEventListener('click', () => {
      parlayPoolSort = 'conf'; parlayPoolStat = 'all'; parlayPoolDir = 'all'; parlayPoolPlacedOnly = false;
      renderParlayLab(container);
    });
  });

  // GLOW-UP 178: slip export — per-leg ⧉ and whole-slip COPY SLIP. Flash-
  // confirm ✓ in place; no re-render, so stopPropagation keeps the leg's
  // row interactions (remove) intact.
  const parlayFlashCopy = (btn: HTMLElement, text: string, okLabel: string): void => {
    const original = btn.textContent || '';
    navigator.clipboard.writeText(text).then(() => {
      btn.textContent = okLabel;
      btn.classList.add('copied');
      setTimeout(() => { btn.textContent = original; btn.classList.remove('copied'); }, 1200);
    }).catch(() => { /* clipboard denied — leave as-is */ });
  };
  container.querySelectorAll<HTMLElement>('.parlay-slip-copy').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      parlayFlashCopy(btn, btn.dataset['parlayClip'] || '', '✓');
    });
  });
  container.querySelectorAll<HTMLElement>('[data-parlay-copyslip]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      parlayFlashCopy(btn, parlaySlipClipAll(), '✓ COPIED');
    });
  });

  // GLOW-UP 181: place the slip into the Parlay Ledger (persisted per event).
  container.querySelectorAll<HTMLElement>('[data-parlay-place]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const legs: PlacedParlayLeg[] = selectedPairs.map(({ leg: l, fighter: lf }) => {
        const pk = parlayLegBook(l, lf);
        return {
          fighter: l.fighter,
          opponent: (l.opponent && l.opponent !== '?') ? l.opponent : null,
          dir: l.direction.toUpperCase(),
          stat: l.stat,
          statLabel: PL_STAT_CLIP[l.stat] || l.stat.toUpperCase(),
          line: l.line,
          book: pk || null,
          bookLabel: pk ? (PL_BOOK_NAME[pk] || pk) : 'No book',
        };
      });
      const original = btn.textContent || '';
      btn.classList.add('placed');
      void persistPlacedParlay(legs).then((res) => {
        btn.textContent = res === 'placed' ? '✓ PLACED' : res === 'dup' ? '✓ ALREADY PLACED' : '✕ FAILED';
        if (res === 'placed') showToast('✓ Parlay saved to your Parlay Ledger (Data view)');
        setTimeout(() => { btn.textContent = original; btn.classList.remove('placed'); }, 1600);
      });
    });
  });

  container.querySelectorAll<HTMLElement>('.parlay-suggest-card').forEach(card => {
    card.addEventListener('click', () => {
      const legsStr = card.dataset['suggestLegs'] || '';
      parlaySelectedLegs.clear();
      for (const key of legsStr.split(',')) {
        if (key.trim()) parlaySelectedLegs.add(key.trim());
      }
      renderParlayLab(container);
    });
  });

  // Synergy pair click: add both legs to parlay (or remove if both already selected)
  container.querySelectorAll<HTMLElement>('.synergy-pair-card').forEach(card => {
    card.addEventListener('click', () => {
      const key1 = card.dataset['synergyKey1'] || '';
      const key2 = card.dataset['synergyKey2'] || '';
      if (!key1 || !key2) return;
      const bothSelected = parlaySelectedLegs.has(key1) && parlaySelectedLegs.has(key2);
      if (bothSelected) {
        parlaySelectedLegs.delete(key1);
        parlaySelectedLegs.delete(key2);
      } else {
        parlaySelectedLegs.add(key1);
        parlaySelectedLegs.add(key2);
      }
      renderParlayLab(container);
    });
  });
}

let _archiveAutoSettleFired = false;
let _archiveBiasSortKey: 'hitRate' | 'avgEdge' | 'total' = 'avgEdge';
const _archiveCollapsedSections = new Set<string>();

// ── DATA VIEW SUB-NAV ─────────────────────────────────────────────────────
// Archive stacks 14 accordions and Calibration 5, both reached through a
// two-item dropdown — so finding one meant scrolling blind past the rest.
// The rail is DERIVED from the DOM after render rather than threaded through
// both panels' markup, so a section added later joins it for free.
const DATA_SECTION_GROUPS: Record<string, string> = {
  predictions: 'Forecast', learning: 'Forecast',
  events: 'Results', 'ai-accuracy': 'Results', grading: 'Results',
  'placed-ledger': 'My Bets', 'parlay-ledger': 'My Bets', 'entry-clv': 'My Bets',
  'fp-hitrate': 'Hit Rates', 'ss-hitrate': 'Hit Rates', 'td-hitrate': 'Hit Rates',
  calibration: 'Model', backtest: 'Model', bias: 'Model',
  'cal-curve': 'Calibration', 'cal-diagnosis': 'Calibration', 'cal-trend': 'Calibration',
  'cal-recal': 'Calibration', 'cal-bias': 'Calibration',
};
// Short rail labels — the section headers themselves are sentence-length by
// design ("Fantasy Line Hit Rate (Current Roster)") and won't fit a chip.
const DATA_SECTION_LABELS: Record<string, string> = {
  predictions: 'Predictions', learning: 'Learning',
  events: 'Per-Event', 'ai-accuracy': 'AI Accuracy', grading: 'Grading',
  'placed-ledger': 'Placed', 'parlay-ledger': 'Parlays', 'entry-clv': 'CLV',
  'fp-hitrate': 'FP', 'ss-hitrate': 'SS', 'td-hitrate': 'TD',
  calibration: 'Calibration', backtest: 'Backtest', bias: 'Platform Bias',
  'cal-curve': 'Curve', 'cal-diagnosis': 'Diagnosis', 'cal-trend': 'Trend',
  'cal-recal': 'Recalibration', 'cal-bias': 'Line Bias',
};
// header (54) + sticky filter bar (34). Matches .fighter-header-row's top.
const DATA_SUBNAV_STICKY_TOP = 88;
// Held so each rebuild can detach the previous listener instead of stacking one
// per archive re-render.
let _dataSubNavScrollHandler: (() => void) | null = null;

function buildDataSubNav(container: HTMLElement): void {
  container.querySelector('.data-subnav')?.remove();
  const sections = Array.from(container.querySelectorAll<HTMLElement>('.best-picks-section[data-section-id]'));
  if (sections.length < 3) return;   // a short view navigates fine by scrolling

  const groups = new Map<string, Array<{ id: string; label: string; empty: boolean }>>();
  for (const sec of sections) {
    const id = sec.dataset.sectionId || '';
    if (!id) continue;
    const label = DATA_SECTION_LABELS[id] || (sec.querySelector('.best-picks-title')?.textContent || id).trim();
    // Sections render a shared empty-state block when they have nothing to show;
    // dimming those turns the rail into a coverage map, not just a jump list.
    const empty = !!sec.querySelector('.archive-empty-state');
    const group = DATA_SECTION_GROUPS[id] || 'Other';
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group)!.push({ id, label, empty });
  }

  const nav = document.createElement('div');
  nav.className = 'data-subnav';
  nav.innerHTML = `
    <div class="dsn-rail">
      ${Array.from(groups.entries()).map(([group, items]) => `
        <div class="dsn-group">
          <span class="dsn-group-label">${group}</span>
          ${items.map(i => `<button class="dsn-chip${i.empty ? ' dsn-empty' : ''}" data-target="${i.id}" type="button" title="${i.empty ? 'No data in this section yet' : `Jump to ${i.label}`}">${i.label}</button>`).join('')}
        </div>`).join('')}
    </div>
    <div class="dsn-actions">
      <button class="dsn-action" data-dsn-action="expand" type="button" title="Expand every section">⊞ ALL</button>
      <button class="dsn-action" data-dsn-action="collapse" type="button" title="Collapse every section">⊟ NONE</button>
    </div>`;
  container.prepend(nav);

  const sectionById = (id: string) =>
    sections.find(s => s.dataset.sectionId === id) || null;
  // Expanding via the header's own click keeps the slide animation and the
  // _archiveCollapsedSections bookkeeping in one place.
  const expand = (sec: HTMLElement) => {
    if (sec.classList.contains('collapsed')) sec.querySelector<HTMLElement>('.best-picks-header')?.click();
  };

  nav.querySelectorAll<HTMLElement>('.dsn-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const sec = sectionById(chip.dataset.target || '');
      if (!sec) return;
      expand(sec);
      const top = sec.getBoundingClientRect().top + window.scrollY - (DATA_SUBNAV_STICKY_TOP + nav.offsetHeight + 8);
      window.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });
    });
  });

  nav.querySelectorAll<HTMLElement>('.dsn-action').forEach(btn => {
    btn.addEventListener('click', () => {
      const wantCollapsed = btn.dataset.dsnAction === 'collapse';
      sections.forEach(sec => {
        if (sec.classList.contains('collapsed') !== wantCollapsed) {
          sec.querySelector<HTMLElement>('.best-picks-header')?.click();
        }
      });
    });
  });

  // ── Scroll-spy ──────────────────────────────────────────────────────────
  // Computed straight from geometry on each frame rather than accumulated from
  // IntersectionObserver entries: sections here are thousands of px tall, so a
  // visible-set went stale (it reported "backtest" while sitting on "events"),
  // and every archive re-render leaked another live observer.
  // Semantics: the last section whose top has passed under the rail is the one
  // you are reading.
  if (_dataSubNavScrollHandler) window.removeEventListener('scroll', _dataSubNavScrollHandler);
  const anchor = DATA_SUBNAV_STICKY_TOP + nav.offsetHeight + 12;
  const chips = Array.from(nav.querySelectorAll<HTMLElement>('.dsn-chip'));
  let scheduled = false;
  // Active = the last section whose top has passed under the rail, i.e. the one
  // you are reading. Two alternatives were measured and rejected: an
  // IntersectionObserver visible-set went stale on these very tall sections
  // (reported "backtest" while sitting on "events"), and "section filling the
  // most screen" let a tall section win from anywhere on the page (6/14 vs
  // 12/14). The last section is reachable because the container reserves
  // trailing scroll room — see #cardContainer:has(> .data-subnav) in the CSS.
  const updateSpy = () => {
    scheduled = false;
    if (!nav.isConnected) return;
    let activeId = sections[0]?.dataset.sectionId || '';
    let bestTop = -Infinity;
    for (const sec of sections) {
      const top = sec.getBoundingClientRect().top;
      // Strict > keeps the first of a side-by-side pair (ss/td hit rates share
      // a .best-picks-grid row, so their tops are identical).
      if (top - anchor <= 0 && top > bestTop) { bestTop = top; activeId = sec.dataset.sectionId || activeId; }
    }
    for (const chip of chips) chip.classList.toggle('active', chip.dataset.target === activeId);
  };
  _dataSubNavScrollHandler = () => {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(updateSpy);
  };
  window.addEventListener('scroll', _dataSubNavScrollHandler, { passive: true });
  updateSpy();
}

// ── Cached backtest results (computed once per renderArchivePanel call) ────
let _cachedBacktestResults: {
  wf: WalkForwardResults;
  bankrollCurve: Array<{fold: number; bankroll: number}>;
  totalPreds: number;
  totalEvents: number;
} | null = null;

function computeBacktestFromHistory(): typeof _cachedBacktestResults {
  const engine = new BacktestingEngine();
  const eventsByDate = new Map<number, WalkForwardEvent>();
  let totalPreds = 0;

  allFighters.forEach(f => {
    const line = activePlatformLine(f) ?? f.db?.avgFP ?? null;
    const history = (f.db?.history || []).filter(h => h.fp != null) as FightResult[];
    if (!line || history.length < 7) return;

    for (let i = 6; i < history.length; i++) {
      const train = history.slice(Math.max(0, i - 6), i);
      const trainFP = train.map(h => h.fp || 0);
      if (!trainFP.length) continue;

      const mean = trainFP.reduce((s, v) => s + v, 0) / trainFP.length;
      const variance = trainFP.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / trainFP.length;
      const std = Math.max(8, Math.sqrt(variance));
      const overProb = 1 / (1 + Math.exp(-((mean - line) / std)));
      const lean = overProb > 0.52 ? 'over' : overProb < 0.48 ? 'under' : 'push';
      if (lean === 'push') continue;

      const confidence = Math.min(0.95, Math.abs(overProb - 0.5) * 2 + 0.45);
      const expectedValue = lean === 'over' ? overProb : 1 - overProb;

      const ts = history[i].date ? new Date(history[i].date as string).getTime() : (Date.now() - (history.length - i) * 86400000);
      const eventTs = Number.isFinite(ts) ? ts : Date.now();

      if (!eventsByDate.has(eventTs)) {
        eventsByDate.set(eventTs, { timestamp: eventTs, predictions: [], actualResults: [] });
      }

      const evt = eventsByDate.get(eventTs)!;
      evt.predictions.push({
        fighter: f.name, line,
        prediction: { lean, confidence, edge: Math.abs(overProb - 0.5) * 2, expectedValue }
      });
      evt.actualResults.push({ fighter: f.name, actualFP: history[i].fp || 0 });
      totalPreds++;
    }
  });

  const events = Array.from(eventsByDate.values())
    .filter(e => e.predictions.length > 0)
    .sort((a, b) => a.timestamp - b.timestamp);

  if (events.length < 7) return null;

  const wf = engine.runWalkForwardValidation(events, 6);
  if (!wf.folds.length) return null;

  // Simulate bankroll curve from fold results (starting at $1000)
  let bankroll = 1000;
  const bankrollCurve: Array<{fold: number; bankroll: number}> = [{ fold: 0, bankroll: 1000 }];
  wf.folds.forEach((fold, idx) => {
    // Simple model: each fold, if accuracy > 50%, gain proportional to accuracy - 50%, else lose
    const edge = fold.accuracy - 0.5;
    const pnl = bankroll * 0.05 * (edge / 0.1) * (fold.testSize / Math.max(1, fold.testSize));
    bankroll += pnl;
    bankrollCurve.push({ fold: idx + 1, bankroll: Math.max(0, bankroll) });
  });

  return { wf, bankrollCurve, totalPreds, totalEvents: events.length };
}
const _h2hFighterMap = new Map<string, AnalyzerFighter>();

// ── OPENING LINE TRACKER ───────────────────────────────────────────────────
const _openingLines = new Map<string, number>();
let _openingLinesEventKey = '';
let _betrSeedHash = '';  // tracks which betr seed the baselines belong to
// Durable event tag written to every lines_open_v1 write. Mirrors the Betr reset
// rule (feedback_betr_reset_rule.md): the Betr seed's own event date is the only
// signal that can't drift across auto-advances. On load, a mismatch between the
// saved tag and the current betr_event_date means the baselines belong to a prior
// event and must be wiped along with line_history_v1.
let _currentBetrEventDate = '';
let _baselineCapturedAt = 0;  // epoch ms when baselines were first created
const MAX_BASELINE_AGE_MS = 7 * 24 * 60 * 60 * 1000; // 7 days — auto-expire only across event cycles
// Inter-refresh delta: stores line values from the PREVIOUS refresh cycle.
// When a new refresh brings different values, the delta shows as a movement badge.
// This catches movements even when the opening baseline equals current values.
const _prevRefreshLines = new Map<string, number>();
// ── LINE HISTORY TRACKER ─────────────────────────────────────────────────
const STORAGE_LINE_HISTORY_KEY = 'line_history_v1';
const LINE_HISTORY_MAX_AGE_MS = 48 * 60 * 60 * 1000; // 48h
let _lineHistory: { eventKey: string; updatedAt: number; forBetrEventDate?: string; series: Record<string, Array<{ t: number; v: Record<string, number> }>> } = { eventKey: '', updatedAt: 0, series: {} };
function openingLineKey(platform: string, stat: string, name: string): string {
  return `${platform}|${stat}|${name.toLowerCase().trim()}`;
}

// Maximum plausible line movement per stat type. Anything beyond this is a
// stale/corrupt baseline and should be discarded rather than displayed.
const MAX_PLAUSIBLE_DELTA: Record<string, number> = { fp: 12, ss: 15, ss_r1: 6, td: 3, ft: 5, ctrl: 4, kd: 1 };

/** Returns true when a stored opening value is plausible for its stat type. */
function isPlausibleBaseline(stat: string, value: number): boolean {
  if (!Number.isFinite(value) || value < 0) return false;
  if (stat === 'ft'    && value > 25)  return false;   // FT lines are 0–25 min
  if (stat === 'td'    && value > 15)  return false;   // TD lines are 0–15
  if (stat === 'ss'    && value > 250) return false;   // SS lines are 0–~200
  if (stat === 'ss_r1' && value > 60)  return false;   // R1 SS is a single round — 0–~40
  if (stat === 'fp'    && value > 250) return false;   // FP lines are 0–~200
  if (stat === 'ctrl'  && value > 25)  return false;   // CTRL lines are 0–25 min (theoretical max in a 5R fight)
  if (stat === 'kd'    && value > 3)   return false;   // KD lines are 0.5–1.5 in practice
  return true;
}

/**
 * The single platform×stat inventory used by every baseline path: opening
 * capture, delta-0 baseline repair, the RESET-LINES re-anchor, the fighter-card
 * sharp-move scan and the Line Movers board. This was four near-identical
 * literals that had already drifted (the fighter-card copy never learned about
 * any stat added after FT), so a new prop silently tracked on some paths and not
 * others. Add a line here and every path picks it up.
 *
 * CTRL / R1 SS / KD joined in GLOW-UP 201 — CTRL is Best-Picks-eligible as of
 * MODEL v16 and R1 SS / KD are lean sources, so their movement is actionable.
 * Body/leg lines are deliberately absent: no lean reads them, so their movement
 * has nothing to confirm or contradict.
 */
const LINE_STAT_ACCESSORS: Array<[string, string, (f: AnalyzerFighter) => number | null | undefined]> = [
  ['p6',   'fp',    f => f.line_p6],
  ['p6',   'ss',    f => f.line_p6_ss],
  ['p6',   'td',    f => f.line_p6_td],
  ['p6',   'ft',    f => f.line_p6_ft],
  ['p6',   'ctrl',  f => f.line_p6_ctrl],
  ['ud',   'fp',    f => f.line_ud],
  ['ud',   'ss',    f => f.line_ud_ss],
  ['ud',   'ss_r1', f => f.line_ud_ss_r1],
  ['ud',   'td',    f => f.line_ud_td],
  ['ud',   'ft',    f => f.line_ud_ft],
  ['ud',   'ctrl',  f => f.line_ud_ctrl],
  ['pp',   'fp',    f => f.line_pp],
  ['pp',   'ss',    f => f.line_pp_ss],
  ['pp',   'ss_r1', f => f.line_pp_ss_r1],
  ['pp',   'td',    f => f.line_pp_td],
  ['pp',   'ft',    f => f.line_pp_ft],
  ['pp',   'ctrl',  f => f.line_pp_ctrl],
  ['pp',   'kd',    f => f.line_pp_kd],
  ['betr', 'fp',    f => f.line_betr],
  ['betr', 'ss',    f => f.line_betr_ss],
  ['betr', 'td',    f => f.line_betr_td],
  ['betr', 'ft',    f => f.line_betr_ft],
  ['betr', 'ctrl',  f => f.line_betr_ctrl],
  ['dk',   'ss',    f => f.line_dk_ss],
  ['dk',   'ss_r1', f => f.line_dk_ss_r1],
  ['dk',   'td',    f => f.line_dk_td],
  ['dk',   'ft',    f => f.line_dk_ft],
  ['dk',   'ctrl',  f => f.line_dk_ctrl],
];

/**
 * LINE_STAT_ACCESSORS regrouped stat-first, for the paths that iterate by stat
 * rather than by platform (line-history recording, the Line Movers board).
 * Derived rather than written out so it can't fall behind the flat list.
 */
type StatPlatAccessors = Array<[string, (f: AnalyzerFighter) => number | null | undefined]>;
const LINE_STAT_BY_STAT: Array<[string, StatPlatAccessors]> = (() => {
  const order: string[] = [];
  const byStat = new Map<string, StatPlatAccessors>();
  for (const [plat, stat, get] of LINE_STAT_ACCESSORS) {
    let bucket = byStat.get(stat);
    if (!bucket) { bucket = []; byStat.set(stat, bucket); order.push(stat); }
    bucket.push([plat, get]);
  }
  return order.map(s => [s, byStat.get(s) as StatPlatAccessors] as [string, StatPlatAccessors]);
})();

/** Book label for a LINE_STAT_ACCESSORS platform key. */
function statPlatLabel(plat: string): string {
  return plat === 'p6' ? 'P6' : plat === 'ud' ? 'UD' : plat === 'pp' ? 'PP' : plat === 'dk' ? 'DK' : 'BT';
}

/** Display label for a LINE_STAT_ACCESSORS stat key ('ss_r1' → 'R1 SS'). */
function statDisplayLabel(stat: string): string {
  return stat === 'ss_r1' ? 'R1 SS' : stat.toUpperCase();
}

/** The sub-lean a given stat key is scored by, or null when the stat has none. */
function leanForStat(f: AnalyzerFighter, stat: string): LeanResult | null {
  switch (stat) {
    case 'fp':    return f.lean ?? null;
    case 'ss':    return f.lean_ss ?? null;
    case 'ss_r1': return f.lean_ss_r1 ?? null;
    case 'td':    return f.lean_td ?? null;
    case 'ft':    return f.lean_ft ?? null;
    case 'ctrl':  return f.lean_ctrl ?? null;
    case 'kd':    return f.lean_kd ?? null;
    default:      return null;
  }
}

/** Returns null if delta exceeds plausible range for the stat type. */
function sanitizeDelta(stat: string, delta: number | null): number | null {
  if (delta == null) return null;
  const cap = MAX_PLAUSIBLE_DELTA[stat] ?? 30;
  return Math.abs(delta) <= cap ? delta : null;
}

// Builds the persistence payload for lines_open_v1, stamped with the current
// Betr event-date tag so loadOpeningLines can detect cross-event staleness.
/**
 * GLOW-UP 210 — has `_currentBetrEventDate` actually been READ from storage in
 * this page lifetime? It starts '' and was only ever populated by
 * loadOpeningLines, so every baseline written before that ran — or after
 * betr_event_date changed mid-session — got stamped with an empty tag it had no
 * business claiming. That drift is what defects 1–4 kept turning into a wipe.
 */
let _betrEventDateLoaded = false;

/** Read betr_event_date into `_currentBetrEventDate` once per page lifetime. */
async function ensureBetrEventDateLoaded(): Promise<void> {
  if (_betrEventDateLoaded) return;
  const stored = await storageGet<{ betr_event_date?: string }>(['betr_event_date']);
  setCurrentBetrEventDate(typeof stored.betr_event_date === 'string' ? stored.betr_event_date : '');
}

/** The ONLY way `_currentBetrEventDate` changes — keeps the loaded flag honest. */
function setCurrentBetrEventDate(value: string): void {
  _currentBetrEventDate = value;
  _betrEventDateLoaded = true;
}

/**
 * GLOW-UP 210 — every write of lines_open_v1 goes through here, and every write
 * therefore knows the real tag. Previously each call site did
 * `void storageSet({ lines_open_v1: buildOpeningLinesRecord() })` directly, which
 * stamps whatever `_currentBetrEventDate` happens to hold — '' on any path that
 * runs before loadOpeningLines (clicking ✏ BETR LINES is the reproducible one:
 * its open handler re-snapshots) or after betr_event_date changed mid-session.
 */
async function persistOpeningLines(overrideLines?: Record<string, number>): Promise<void> {
  await ensureBetrEventDateLoaded();
  await storageSet({ lines_open_v1: buildOpeningLinesRecord(overrideLines) });
}

function buildOpeningLinesRecord(overrideLines?: Record<string, number>): { eventKey: string; betrSeedHash: string; forBetrEventDate: string; capturedAt: number; lines: Record<string, number> } {
  let lines: Record<string, number>;
  if (overrideLines) {
    lines = overrideLines;
  } else {
    lines = {};
    _openingLines.forEach((v, k) => { lines[k] = v; });
  }
  return {
    eventKey: _openingLinesEventKey,
    betrSeedHash: _betrSeedHash,
    forBetrEventDate: _currentBetrEventDate,
    capturedAt: _baselineCapturedAt || Date.now(),
    lines,
  };
}

/**
 * GLOW-UP 209 — is a stored record's Betr event tag stale? THE one copy.
 *
 * This predicate existed twice: once inside loadOpeningLines and once written
 * out inline in loadLineHistory. Fixing the first left the second wiping
 * line_history_v1 on its own, which is how a restore with a correct tag still
 * came back empty. Both loaders call this now.
 *
 * NO REFERENCE, NO VERDICT: `_currentBetrEventDate` is '' whenever
 * betr_event_date isn't in storage yet — Betr not entered on this card, or just
 * a load pass that ran before the stamp was written. Comparing a real tag
 * against '' and calling it a mismatch destroyed valid baselines; an unknown
 * reference is not evidence of change.
 */
function isBetrTagStale(tag: unknown): boolean {
  if (!_currentBetrEventDate) return false;                 // no reference yet
  if (tag === undefined || tag === null) return true;       // migration — no tag
  if (typeof tag !== 'string') return true;                 // corrupt
  return tag !== _currentBetrEventDate;                     // real mismatch
}

/**
 * GLOW-UP 209 — how much of the CURRENT slate is already present in a stored
 * baseline set. The same evidence `snapshotOpeningLines` uses to tell a real
 * event change from a flickering event NAME, lifted so the staleness wipe can
 * use it too: fighters are the durable identity of a slate, event strings are not.
 *
 * `total === 0` means the fighters haven't loaded yet, which is NOT evidence of
 * anything. Callers must treat it as "cannot judge" and keep the baselines —
 * reading an unknown slate as a changed one is what destroys data.
 */
function baselineSlateOverlap(lines: Record<string, number> | null | undefined): { rate: number; hits: number; total: number } {
  if (!lines) return { rate: 0, hits: 0, total: 0 };
  let hits = 0, total = 0;
  for (const fighter of allFighters) {
    total++;
    const hit = ['p6', 'ud', 'pp', 'betr'].some(plat =>
      lines[openingLineKey(plat, 'fp', fighter.name)] != null
      || lines[openingLineKey(plat, 'ss', fighter.name)] != null);
    if (hit) hits++;
  }
  return { rate: total > 0 ? hits / total : 0, hits, total };
}

async function loadOpeningLines(): Promise<void> {
  const stored = await storageGet<{
    lines_open_v1?: { eventKey: string; betrSeedHash?: string; forBetrEventDate?: string; capturedAt?: number; lines: Record<string, number> } | null;
    betr_seed_hash?: string;
    betr_event_date?: string;
    [STORAGE_LINE_HISTORY_KEY]?: { eventKey?: string; series?: Record<string, Array<{ t: number; v: Record<string, number> }>> } | null;
  }>(['lines_open_v1', 'betr_seed_hash', 'betr_event_date', STORAGE_LINE_HISTORY_KEY]);
  setCurrentBetrEventDate(typeof stored.betr_event_date === 'string' ? stored.betr_event_date : '');
  const data = stored.lines_open_v1;
  const historyRaw = stored[STORAGE_LINE_HISTORY_KEY];

  // Cross-event staleness wipe. The Betr seed's event date (written by
  // initializeBetrLines in background.ts via BETR_EVENT_DATE) is the durable
  // "which event does this belong to" tag — it can't drift when the analyzer
  // auto-advances. Wipe conditions (ANY of):
  //   1. Migration: baseline has no forBetrEventDate tag (saved before this fix).
  //   2. Event change: baseline's tag doesn't match the current seed's date.
  //   3. Same checks applied to line_history_v1 — otherwise the reconstruction
  //      path below resurrects stale history into fresh baselines.
  // GLOW-UP 209: shared with loadLineHistory — see isBetrTagStale.
  const baselineStale = !!data?.lines && isBetrTagStale((data as { forBetrEventDate?: unknown }).forBetrEventDate);
  const historyStale  = !!historyRaw?.series && Object.keys(historyRaw.series).length > 0
                        && isBetrTagStale((historyRaw as { forBetrEventDate?: unknown }).forBetrEventDate);

  // ── FIRST-BETR MIGRATION (2026-08-06) ──────────────────────────────────
  // The tag only exists once manual Betr lines do: analyzer.ts ~21231 stamps
  // betr_event_date with the card's date "whenever manual Betr lines exist".
  // So on a card where Betr hasn't been entered yet, baselines are written with
  // an EMPTY tag — and the moment the user enters Betr mid-week the tag flips
  // from "" to the card date, every baseline reads as stale, and lines_open_v1
  // AND line_history_v1 are both destroyed. That is exactly what happened here:
  // adding Betr lines wiped a week of movement for the SAME event, and Line
  // Movers went silent right before lock-in.
  //
  // An empty prior tag is the precise signature of "Betr data first appeared",
  // NOT of an event change — a real event change carries a non-empty OLD date.
  // So migrate in place instead of wiping. Where the event name is known it has
  // to agree too; where it isn't known yet the empty-tag signal stands alone.
  //
  // Risk direction is deliberate: the failure mode of migrating wrongly is
  // visibly bogus movement, which is correctable. The failure mode of wiping
  // wrongly is permanent loss of data that cannot be re-derived.
  const prevTag = (data as { forBetrEventDate?: unknown } | null | undefined)?.forBetrEventDate;
  const prevHistTag = (historyRaw as { forBetrEventDate?: unknown } | null | undefined)?.forBetrEventDate;
  const tagWasEmpty = (t: unknown): boolean => t === '' || t === undefined || t === null;
  const curEventKey = normalizeEventKey(upcomingEventName || inferredEventNameFromLines || '');
  const baseEventKey = normalizeEventKey((data as { eventKey?: string } | null | undefined)?.eventKey || '');
  // GLOW-UP 209 — the name comparison alone was wrong, and it defeated this very
  // guard on 2026-08-13. The baseline carried the event name INFERRED FROM LINES
  // ("UFC Fight Night: Ian Machado Garry vs Islam Makhachev") while the card
  // carried the UFCStats name ("UFC 330: Makhachev vs. Machado Garry"). One
  // event, two strings, so `baseEventKey !== curEventKey` declared a contradiction,
  // firstBetrOnly went false, and 83h of baselines plus 256 history points were
  // wiped on the first Betr entry — the exact loss this migration exists to stop.
  //
  // Fighters are the durable identity of a slate; event strings flicker with
  // whatever source named them. So a name disagreement only counts when the
  // SLATE disagrees too. Same evidence snapshotOpeningLines already uses.
  const slateOverlap = baselineSlateOverlap(data?.lines);
  const slateAgrees = slateOverlap.total === 0 || slateOverlap.rate >= 0.2;
  const eventContradicts = !!curEventKey && curEventKey !== 'unknown'
                        && !!baseEventKey && baseEventKey !== 'unknown'
                        && baseEventKey !== curEventKey
                        && !slateAgrees;
  if (baseEventKey && curEventKey && baseEventKey !== curEventKey && slateAgrees) {
    console.log(`[LineMovement] Event name differs ("${baseEventKey}" vs "${curEventKey}") but ${slateOverlap.hits}/${slateOverlap.total} of the slate matches the baseline — same event, NOT a contradiction`);
  }
  // GLOW-UP 209b — PER-STORE, not all-or-nothing. This was still ALL-or-nothing
  // (`tagWasEmpty(prevTag) && tagWasEmpty(prevHistTag)`), and the two stores are
  // written by different paths, so they drift: opening the Betr modal re-wrote
  // lines_open_v1 stamped "" (buildOpeningLinesRecord stamps whatever
  // `_currentBetrEventDate` holds, and it is '' until loadOpeningLines has run in
  // that page lifetime) while line_history_v1 kept its correct "2026-08-15".
  // One migratable store + one healthy store = `firstBetrOnly` false, and the
  // wipe branch destroyed BOTH. Observed 2026-08-13 on a bare open-and-close of
  // the modal with no edit: `Stale (baseline=true, history=false)`.
  //
  // Each store is now judged on its own tag. An empty tag is migratable; only a
  // genuinely DIFFERENT non-empty date (a real event change) still wipes — and a
  // real event change makes both stores stale together anyway.
  const canMigrate = !!_currentBetrEventDate && !eventContradicts;
  const migrateBaseline = baselineStale && canMigrate && tagWasEmpty(prevTag);
  const migrateHistory  = historyStale  && canMigrate && tagWasEmpty(prevHistTag);
  const trulyStale = (baselineStale && !migrateBaseline) || (historyStale && !migrateHistory);

  if (!trulyStale && (migrateBaseline || migrateHistory)) {
    console.log(`[LineMovement] Betr tag "" -> "${_currentBetrEventDate}" on the SAME event ("${baseEventKey || 'unknown'}") — migrating ${[migrateBaseline && 'baseline', migrateHistory && 'history'].filter(Boolean).join(' + ')}, KEEPING ${Object.keys(data?.lines || {}).length} baselines`);
    if (migrateBaseline && data) (data as { forBetrEventDate?: string }).forBetrEventDate = _currentBetrEventDate;
    if (migrateHistory && historyRaw) (historyRaw as { forBetrEventDate?: string }).forBetrEventDate = _currentBetrEventDate;
    await storageSet({
      lines_open_v1: data ?? null,
      [STORAGE_LINE_HISTORY_KEY]: historyRaw ?? null,
    });
  } else if (trulyStale) {
    console.log(`[LineMovement] Stale (baseline=${baselineStale}, history=${historyStale}, currentBetrDate="${_currentBetrEventDate}") — wiping lines_open_v1 + line_history_v1`);
    await storageSet({ lines_open_v1: null, [STORAGE_LINE_HISTORY_KEY]: null });
    _lineHistory = { eventKey: '', updatedAt: 0, forBetrEventDate: _currentBetrEventDate, series: {} };
    _openingLines.clear();
    _prevRefreshLines.clear();
    _baselineCapturedAt = 0;
    _openingLinesEventKey = '';
    return;
  }

  // If no baselines exist, try to reconstruct from line history (earliest data points)
  if (!data?.lines) {
    const history = stored[STORAGE_LINE_HISTORY_KEY];
    if (history?.series && Object.keys(history.series).length > 0) {
      console.log('[LineMovement] No baselines found — reconstructing from line history');
      const reconstructed: Record<string, number> = {};
      let minT = Infinity;
      for (const [seriesKey, entries] of Object.entries(history.series)) {
        if (!entries?.length) continue;
        const earliest = entries[0];
        if (earliest.t < minT) minT = earliest.t;
        const parts = seriesKey.split('|');
        const name = parts[0];
        const stat = parts[1];
        if (!name || !stat) continue;
        for (const [platform, value] of Object.entries(earliest.v)) {
          if (typeof value !== 'number' || !Number.isFinite(value)) continue;
          if (!isPlausibleBaseline(stat, value)) continue;
          reconstructed[`${platform}|${stat}|${name}`] = value;
        }
      }
      if (Object.keys(reconstructed).length > 0) {
        _baselineCapturedAt = minT === Infinity ? Date.now() : minT;
        _openingLinesEventKey = history.eventKey || '';
        _betrSeedHash = stored.betr_seed_hash || '';
        for (const [k, v] of Object.entries(reconstructed)) {
          _openingLines.set(k, v);
        }
        void persistOpeningLines(reconstructed);
        console.log(`[LineMovement] Reconstructed ${Object.keys(reconstructed).length} baselines from line history`);
      }
    }
    return;
  }

  // Auto-expire baselines that are older than MAX_BASELINE_AGE_MS
  const storedCapturedAt = data.capturedAt || 0;
  if (storedCapturedAt > 0 && (Date.now() - storedCapturedAt) > MAX_BASELINE_AGE_MS) {
    console.log(`[LineMovement] Baselines expired (age ${((Date.now() - storedCapturedAt) / 3600000).toFixed(1)}h > ${MAX_BASELINE_AGE_MS / 3600000}h) — clearing`);
    void storageSet({ lines_open_v1: null });
    // Try to reconstruct from history instead of losing everything
    const history = stored[STORAGE_LINE_HISTORY_KEY];
    if (history?.series && Object.keys(history.series).length > 0) {
      console.log('[LineMovement] Reconstructing expired baselines from line history');
      const reconstructed: Record<string, number> = {};
      let minT = Infinity;
      for (const [seriesKey, entries] of Object.entries(history.series)) {
        if (!entries?.length) continue;
        const earliest = entries[0];
        if (earliest.t < minT) minT = earliest.t;
        const parts = seriesKey.split('|');
        const name = parts[0];
        const stat = parts[1];
        if (!name || !stat) continue;
        for (const [platform, value] of Object.entries(earliest.v)) {
          if (typeof value !== 'number' || !Number.isFinite(value)) continue;
          if (!isPlausibleBaseline(stat, value)) continue;
          reconstructed[`${platform}|${stat}|${name}`] = value;
        }
      }
      if (Object.keys(reconstructed).length > 0) {
        _baselineCapturedAt = Date.now(); // reset age since we're reconstructing
        _openingLinesEventKey = history.eventKey || '';
        _betrSeedHash = stored.betr_seed_hash || '';
        for (const [k, v] of Object.entries(reconstructed)) {
          _openingLines.set(k, v);
        }
        void persistOpeningLines(reconstructed);
        console.log(`[LineMovement] Reconstructed ${Object.keys(reconstructed).length} baselines from history`);
      }
    }
    return;
  }
  _baselineCapturedAt = storedCapturedAt;
  _openingLinesEventKey = data.eventKey || '';

  // Compare the betr seed hash (set by initializeBetrLines in background.ts)
  // with the hash stored alongside the baselines. If they differ, the hardcoded
  // seed changed (new event) and betr baselines are stale → skip them.
  // If they match, the baselines were created for the current seed → load normally.
  const currentSeedHash = stored.betr_seed_hash || '';
  _betrSeedHash = currentSeedHash;
  const baselineSeedHash = data.betrSeedHash || '';
  const betrBaselinesStale = currentSeedHash !== baselineSeedHash;

  let hadStaleBetrKeys = false;
  for (const [k, v] of Object.entries(data.lines)) {
    if (k.startsWith('betr|') && betrBaselinesStale) { hadStaleBetrKeys = true; continue; }
    if (!Number.isFinite(v)) continue;
    const stat = k.split('|')[1] || '';
    if (!isPlausibleBaseline(stat, v)) continue;
    if (!_openingLines.has(k)) {
      _openingLines.set(k, v);
    }
  }

  // Clean stale betr keys out of persisted storage and update the seed hash
  if (hadStaleBetrKeys) {
    const cleaned: Record<string, number> = {};
    for (const [k, v] of Object.entries(data.lines)) {
      if (!k.startsWith('betr|')) cleaned[k] = v;
    }
    void persistOpeningLines(cleaned);
  }
}

function normalizeEventKey(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
}

function snapshotOpeningLines(): void {
  // The gate is narrowly about Betr's abbreviated names ("C. Duncan") — they
  // create orphaned keys when a later full-name load arrives. So skip only when
  // Betr is the ONLY platform with data; any non-Betr platform alone (UD, P6,
  // PP, DK) is safe to snapshot because those use full names.
  const _snapshotPlats = new Set<string>();
  for (const f of allFighters) {
    if (f.line_p6 != null || f.line_p6_ss != null || f.line_p6_td != null || f.line_p6_ft != null) _snapshotPlats.add('p6');
    if (f.line_ud != null || f.line_ud_ss != null || f.line_ud_td != null || f.line_ud_ft != null) _snapshotPlats.add('ud');
    if (f.line_betr != null || f.line_betr_ss != null || f.line_betr_td != null || f.line_betr_ft != null) _snapshotPlats.add('betr');
    if (f.line_pp != null || f.line_pp_ss != null || f.line_pp_td != null || f.line_pp_ft != null) _snapshotPlats.add('pp');
    if (f.line_dk_ss != null || f.line_dk_td != null || f.line_dk_ft != null) _snapshotPlats.add('dk');
  }
  if (_snapshotPlats.size === 0) return;
  if (_snapshotPlats.size === 1 && _snapshotPlats.has('betr')) return;

  const eventKey = inferredEventNameFromLines || 'unknown';
  // Only reset opening lines when the event genuinely changes (normalized match).
  // Never clear if stored key is empty (first session) or current key is unknown.
  const storedNorm  = normalizeEventKey(_openingLinesEventKey);
  const currentNorm = normalizeEventKey(eventKey);
  if (currentNorm !== 'unknown' && storedNorm !== '' && currentNorm !== storedNorm) {
    // Before clearing, check if current fighters overlap with existing baseline.
    // During clear+re-fetch, platforms arrive one-by-one and inferEventNameFromPayloads
    // can flicker to a different "best pair" from partial data. Only truly clear if
    // the fighters themselves changed (<20% overlap = genuinely new event).
    let overlapHits = 0;
    let overlapTotal = 0;
    for (const fighter of allFighters) {
      const fpKey = openingLineKey('p6', 'fp', fighter.name);
      const ssKey = openingLineKey('p6', 'ss', fighter.name);
      const btKey = openingLineKey('betr', 'fp', fighter.name);
      overlapTotal++;
      if (_openingLines.has(fpKey) || _openingLines.has(ssKey) || _openingLines.has(btKey)) overlapHits++;
    }
    const overlapRate = overlapTotal > 0 ? overlapHits / overlapTotal : 0;
    if (overlapRate < 0.2) {
      // Truly different event — clear baseline
      _openingLines.clear();
      _prevRefreshLines.clear();
      _openingLinesEventKey = eventKey;
      _baselineCapturedAt = 0;
      clearLineHistory();
    }
    // Otherwise: same fighters, event name flickered from partial data — keep baseline
  } else if (currentNorm !== 'unknown' && storedNorm === '') {
    _openingLinesEventKey = eventKey;
  }

  const platformStats = LINE_STAT_ACCESSORS;

  // Collect current fighter names (full-form) to detect orphaned abbreviated-name keys
  const currentNames = new Set(allFighters.map(f => f.name.toLowerCase().trim()));

  let changed = false;
  for (const fighter of allFighters) {
    for (const [plat, stat, getVal] of platformStats) {
      const val = getVal(fighter);
      if (val == null || !isPlausibleBaseline(stat, val)) continue;
      const key = openingLineKey(plat, stat, fighter.name);
      if (_openingLines.get(key) == null) {
        _openingLines.set(key, val);
        changed = true;
      }
    }
  }

  // Clean up orphaned keys from prior partial-load snapshots (abbreviated names
  // like "c. duncan" that no longer match any current fighter "chris duncan").
  for (const key of [..._openingLines.keys()]) {
    const namePart = key.split('|')[2];
    if (namePart && !currentNames.has(namePart)) {
      _openingLines.delete(key);
      changed = true;
    }
  }

  if (changed || _openingLines.size > 0) {
    if (_baselineCapturedAt === 0) _baselineCapturedAt = Date.now();
    void persistOpeningLines();
  }
}
// Post-merge movement detection: called AFTER mergeAndEnrich() with the NEW allFighters.
// Compares new values against _prevRefreshLines (the previous cycle's values).
// For any key where the value changed, records the OLD value into _openingLines
// (if not already tracked) so the movement persists in the storage-backed baseline.
// Then updates _prevRefreshLines to the new values for the next cycle.
function detectAndRecordMovements(): void {
  if (allFighters.length === 0) return;
  const platformStats = LINE_STAT_ACCESSORS;
  let baselineRepaired = false;
  for (const fighter of allFighters) {
    for (const [plat, stat, getVal] of platformStats) {
      const newVal = getVal(fighter);
      if (newVal == null) continue;
      const key = openingLineKey(plat, stat, fighter.name);
      const prevVal = _prevRefreshLines.get(key);
      if (prevVal != null && isPlausibleBaseline(stat, prevVal) && sanitizeDelta(stat, newVal - prevVal) != null && Math.abs(newVal - prevVal) >= 0.5) {
        // Delta-0 baseline repair only. The baseline must already exist AND be
        // captured at the post-move value — in that case we rewrite it to the
        // pre-move prev-refresh value so the badge shows correctly on the next
        // render. If no baseline exists yet, do NOT create one from prev-refresh:
        // prev-refresh is a within-session snapshot, not an authoritative opening.
        const openVal = _openingLines.get(key);
        if (openVal != null && Math.abs(openVal - newVal) < 0.5) {
          _openingLines.set(key, prevVal);
          baselineRepaired = true;
        }
      }
      // Always update _prevRefreshLines to current values for next cycle
      _prevRefreshLines.set(key, newVal);
    }
  }
  if (baselineRepaired) {
    // Persist repaired baselines to storage
    if (_baselineCapturedAt === 0) _baselineCapturedAt = Date.now();
    void persistOpeningLines();
  }
}

// Legacy name kept for call sites — now a no-op since detection moved to post-merge.
function snapshotPrevRefreshLines(): void {
  // Intentionally empty — movement detection now happens in detectAndRecordMovements()
  // called AFTER mergeAndEnrich. This function exists only to avoid breaking call sites.
}

// ── LINE HISTORY PERSISTENCE ─────────────────────────────────────────────
function lineHistoryKey(name: string, stat: string): string {
  return `${name.toLowerCase().trim()}|${stat}`;
}

async function loadLineHistory(): Promise<void> {
  const stored = await storageGet<Record<string, typeof _lineHistory | null>>([STORAGE_LINE_HISTORY_KEY]);
  const data = stored[STORAGE_LINE_HISTORY_KEY];
  if (!data?.series) return;
  // Same forBetrEventDate staleness check as loadOpeningLines — if loadOpeningLines
  // didn't already wipe it (because its own check path was skipped), catch it here.
  const histTag = (data as { forBetrEventDate?: unknown }).forBetrEventDate;
  if (isBetrTagStale(histTag)) {
    console.log(`[LineMovement] loadLineHistory: stale (tag="${histTag}" ≠ current="${_currentBetrEventDate}") — clearing`);
    _lineHistory = { eventKey: '', updatedAt: 0, forBetrEventDate: _currentBetrEventDate, series: {} };
    await storageSet({ [STORAGE_LINE_HISTORY_KEY]: null });
    return;
  }
  const currentNorm = normalizeEventKey(_openingLinesEventKey || '');
  const storedNorm = normalizeEventKey(data.eventKey || '');
  if (currentNorm !== 'unknown' && storedNorm !== '' && currentNorm !== storedNorm) {
    // Different event — start fresh
    return;
  }
  _lineHistory = data;
  // Prune old points
  const cutoff = Date.now() - LINE_HISTORY_MAX_AGE_MS;
  for (const key of Object.keys(_lineHistory.series)) {
    _lineHistory.series[key] = _lineHistory.series[key].filter(p => p.t >= cutoff);
    if (_lineHistory.series[key].length === 0) delete _lineHistory.series[key];
  }
}

function getLineHistoryForFighter(name: string, stat: string): Array<{ t: number; v: Record<string, number> }> {
  return _lineHistory.series[lineHistoryKey(name, stat)] || [];
}

// ── CHIP MICRO-SPARKLINE ──────────────────────────────────────────────────
// A ~9px strip inside a platform line chip showing how that ONE book's line has
// moved across recent snapshots. The Line Movers strip stays the summary view
// and buildLineTimelinePanel stays the full chart — this puts the shape of the
// move next to the number you actually read.
const CHIP_SPARK_W = 44;
const CHIP_SPARK_H = 12;
const CHIP_SPARK_TAIL = 7;   // viewBox units held at the current value
function buildChipSparkline(name: string, stat: string, platform: string): string {
  const history = getLineHistoryForFighter(name, stat);
  if (history.length < 2) return '';
  const vals: Array<{ t: number; v: number }> = [];
  for (const pt of history) {
    const v = pt.v[platform];
    if (v != null && Number.isFinite(v)) vals.push({ t: pt.t, v });
  }
  if (vals.length < 2) return '';

  const first = vals[0].v;
  const last = vals[vals.length - 1].v;
  // Same plausibility gate the movement badge uses — a corrupt baseline should
  // draw nothing rather than a convincing-looking lie.
  const delta = sanitizeDelta(stat, parseFloat((last - first).toFixed(1)));
  if (delta == null) return '';
  const dirClass = delta > 0 ? 'spark-up' : delta < 0 ? 'spark-down' : 'spark-flat';

  const tMin = vals[0].t;
  const tMax = vals[vals.length - 1].t;
  const w = CHIP_SPARK_W, h = CHIP_SPARK_H, pad = 1.5;
  const tRange = (tMax - tMin) || 1;
  const seriesVals = vals.map(p => p.v);
  const vMin = Math.min(...seriesVals);
  const vMax = Math.max(...seriesVals);
  const vRange = vMax - vMin;

  // A book that has never moved draws nothing. A flat dashed rule sat a few
  // pixels above the rail's own scrollbar and read as a rendering artifact
  // rather than data — and "hasn't moved" is the default state, so it earns no
  // ink. Note a round trip (30 → 31 → 30) still draws: it moved, delta is just 0.
  if (vRange === 0) return '';

  // vRange > 0 guarantees at least one consecutive difference, so moves >= 1.
  const moves = vals.reduce((c, p, i) => (i > 0 && p.v !== vals[i - 1].v ? c + 1 : c), 0);
  const spanH = Math.max(1, Math.round((tMax - tMin) / 3600000));
  const platLabel = platform === 'betr' ? 'BT' : platform.toUpperCase();
  const tip = `${platLabel} ${stat.toUpperCase()} ${first} → ${last} (${delta > 0 ? '+' : ''}${delta}) · ${moves} move${moves === 1 ? '' : 's'} over ~${spanH}h`;

  // Reserve a tail so the CURRENT value always sits on a visible plateau.
  // Without it the newest snapshot lands flush on the right edge and a move
  // reads as a bare spike with no level to read it against.
  const plotW = w - pad * 2 - CHIP_SPARK_TAIL;
  const pts = vals.map(p => ({
    x: pad + ((p.t - tMin) / tRange) * plotW,
    y: pad + (h - pad * 2) - ((p.v - vMin) / vRange) * (h - pad * 2),
  }));
  // Step path — a posted line holds its value until the book moves it.
  let d = `M${pts[0].x.toFixed(1)},${pts[0].y.toFixed(1)}`;
  for (let i = 1; i < pts.length; i++) {
    d += ` L${pts[i].x.toFixed(1)},${pts[i - 1].y.toFixed(1)} L${pts[i].x.toFixed(1)},${pts[i].y.toFixed(1)}`;
  }
  const lastY = pts[pts.length - 1].y.toFixed(1);
  d += ` L${(w - pad).toFixed(1)},${lastY}`;
  // No head marker: the x axis is stretched by preserveAspectRatio="none", which
  // non-scaling-stroke fixes for the stroke but not for a filled shape — a dot
  // came out an ellipse. The plateau tail already marks the current level.
  const body = `<path d="${d}" fill="none"/>`;

  return `<svg class="line-spark ${dirClass}" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" role="img"><title>${tip}</title>${body}</svg>`;
}

function snapshotLineHistory(): void {
  if (allFighters.length === 0) return;
  // Same gate as snapshotOpeningLines — only skip when Betr is the sole platform.
  const plats = new Set<string>();
  for (const f of allFighters) {
    if (f.line_p6 != null || f.line_p6_ss != null) plats.add('p6');
    if (f.line_ud != null || f.line_ud_ss != null) plats.add('ud');
    if (f.line_betr != null || f.line_betr_ss != null) plats.add('betr');
    if (f.line_pp != null || f.line_pp_ss != null) plats.add('pp');
    if (f.line_dk_ss != null) plats.add('dk');
  }
  if (plats.size === 0) return;
  if (plats.size === 1 && plats.has('betr')) return;

  const now = Date.now();
  const cutoff = now - LINE_HISTORY_MAX_AGE_MS;
  const eventKey = _openingLinesEventKey || inferredEventNameFromLines || 'unknown';

  // If event changed, clear history
  const curNorm = normalizeEventKey(eventKey);
  const storedNorm = normalizeEventKey(_lineHistory.eventKey || '');
  if (curNorm !== 'unknown' && storedNorm !== '' && curNorm !== storedNorm) {
    _lineHistory = { eventKey, updatedAt: now, forBetrEventDate: _currentBetrEventDate, series: {} };
  }
  _lineHistory.eventKey = eventKey;
  _lineHistory.forBetrEventDate = _currentBetrEventDate;

  let changed = false;
  for (const fighter of allFighters) {
    for (const [stat, plats] of LINE_STAT_BY_STAT) {
      const platVals: Record<string, number> = {};
      for (const [plat, get] of plats) {
        const val = get(fighter);
        if (val != null) platVals[plat] = val;
      }
      if (Object.keys(platVals).length === 0) continue;

      const key = lineHistoryKey(fighter.name, stat);
      if (!_lineHistory.series[key]) _lineHistory.series[key] = [];
      const series = _lineHistory.series[key];

      // Dedup: skip if identical to last point
      const last = series[series.length - 1];
      if (last) {
        const lastKeys = Object.keys(last.v).sort();
        const newKeys = Object.keys(platVals).sort();
        if (lastKeys.join(',') === newKeys.join(',') && lastKeys.every(k => last.v[k] === platVals[k])) {
          continue;
        }
      }

      series.push({ t: now, v: platVals });
      changed = true;

      // Prune old points
      while (series.length > 0 && series[0].t < cutoff) series.shift();
    }
  }

  if (changed) {
    _lineHistory.updatedAt = now;
    void storageSet({ [STORAGE_LINE_HISTORY_KEY]: _lineHistory });
  }
}

function clearLineHistory(): void {
  _lineHistory = { eventKey: '', updatedAt: 0, forBetrEventDate: _currentBetrEventDate, series: {} };
  void storageSet({ [STORAGE_LINE_HISTORY_KEY]: _lineHistory });
}

// ── PROP LINE PREDICTOR ──────────────────────────────────────────────────
let _cachedPredictions: PredictionEvent[] | null = null;
// GLOW-UP 256: predictions sort. Session-scoped and draw-only, the same contract
// the report card and Parlay Lab sorts use — it changes what is DRAWN, never what
// the model produced, so it resets on reload. CARD stays the default because the
// board is read alongside a fight order; the rest deliberately flatten.
type PredSort = 'card' | 'fp' | 'gap' | 'conf' | 'eviD';

// ── GLOW-UP 260 · factor lanes ────────────────────────────────────────────
// Three separate lists encoded the same thing and had drifted apart: a regex
// that assigned a colour, a hard-coded legend in the header, and a PRIORITY map
// deciding which chips survive the five-chip clamp. The drift was not cosmetic.
//
//   · MODEL v29 removed the FP duration adjustment, so no reason string starts
//     with `Duration adj` on a freshly generated board — yet DURATION kept its
//     amber key in the legend and rank 1 in the priority list. The legend was
//     advertising a lane that could not light.
//   · `pf-finish` renders green on every finisher and was in neither the legend
//     nor the priority map.
//   · Worst of the three: `No history — component estimate` matched the finish
//     lane's /No history/i and came out GREEN — the app's over/good colour — on
//     exactly the rows GLOW-UP 250 exists to make look THIN. The one chip that
//     says "there is nothing behind this number" was styled as a positive.
//
// One ordered table now owns all three jobs. Array order IS truncation priority
// AND legend order, so a lane cannot be ranked without being labelled. The legend
// is derived from the lanes actually drawn (see `lanesSeen`), which is why
// `duration` can stay: stored pre-v29 boards still carry those chips, and the
// amber key now appears on exactly the boards that have them.
const FACTOR_LANES: Array<{ cls: string; label: string; test: RegExp }> = [
  // A hard rule replaced or capped the number. Rose, never green: this is the
  // opposite of a finding — a warning that the model had little to work with.
  { cls: 'pf-guard',    label: 'guard',      test: /^No history|^Clamped to historic|^Anchored to market/i },
  // Post-hoc multipliers on the level — calibration, the book prior, the learned
  // trend. Same family as the shrink, so they share its gold.
  { cls: 'pf-cal',      label: 'correction', test: /^FP cal|^Book prior|^Trend/i },
  // Legacy: pre-v29 boards only.
  { cls: 'pf-duration', label: 'duration',   test: /^Duration adj/ },
  // Anchored so it cannot swallow `Opp adj: x1.09 (... Finish synergy ...)`, an
  // opponent chip that merely mentions finish synergy inside its parenthetical.
  { cls: 'pf-finish',   label: 'finish',     test: /^High P\(finish\)/ },
  { cls: 'pf-opp',      label: 'opponent',   test: /^Opp |opponent|style|^vs (Grappler|Striker)|(Grappler|Striker) vs/i },
  { cls: 'pf-rate',     label: 'rate',       test: /SS\/min|^Output/ },
  { cls: 'pf-hist',     label: 'history',    test: /Betr (platform )?avg|Recency-weighted|Avg TD|Career avg/ },
];
const SHRINK_LANE = { cls: 'pred-factor-shrink', label: 'shrink' };

// ── GLOW-UP 263 · the rail was mostly label ───────────────────────────────
// Every row carried the same six phrasings — `Opp absorbs`, `SS/min`, `Output`,
// `Avg TD/fight`, `Betr avg`, `(N fights)`, `Recency-weighted` — around about four
// characters of actual number. Twenty-six rows of that is one sentence repeated
// twenty-six times with a different digit in it, and it cost real information:
// the top row was spending its whole 569px rail on five chips and folding four
// more into `+4`.
//
// The lane colour and the header legend already say WHICH quantity a chip is, so
// the chip only has to say HOW MUCH. Full strings stay in every `title`, and any
// reason with no entry here falls through unchanged — an unrecognised factor is
// printed in full rather than silently mangled.
//
// `(N fights)` is dropped from the Betr average specifically because the evidence
// meter beside the fighter's name already states the sample size; it was the same
// number printed twice on the same row.
const FACTOR_SHORT: Array<[RegExp, (m: RegExpMatchArray) => string]> = [
  [/^No history/i,                              () => 'NO HISTORY'],
  [/^Clamped to historic range:\s*(.+)$/i,      m => `CLAMP ${m[1]!.replace('-', '–')}`],
  // MODEL v31. The chip carries what the MODEL said; the FP cell beside it already
  // shows what it was pulled to, so the pair reads as a before/after without the
  // chip having to spell either side out.
  [/^Anchored to market: model said ([\d.]+)/,   m => `⚓ ${m[1]}`],
  [/^FP cal \([^)]*\): ×([\d.]+)/,              m => `CAL ×${Number(m[1]).toFixed(2)}`],
  [/^Book prior: ([\d.]+)/,                     m => `BOOK ${m[1]}`],
  [/^Trend(?: adj)?:\s*([+-][\d.]+)/,           m => `TREND ${m[1]}`],
  [/^Duration adj:.*\(×([\d.]+)\)/,             m => `DUR ×${m[1]}`],
  [/^High P\(finish\) (\d+)%/,                  m => `FIN ${m[1]}%`],
  [/^Opp adj: ×([\d.]+)/,                       m => `OPP× ${m[1]}`],
  [/^Opp absorbs ([\d.]+) SS\/min/,             m => `OPP ${m[1]}/m`],
  [/^Opp TD Def: (\d+%)/,                       m => `OPP TD ${m[1]}`],
  [/^Output ([\d.]+) SS\/min/,                  m => `OUT ${m[1]}/m`],
  [/^Avg TD\/fight: ([\d.]+)/,                  m => `TD ${m[1]}`],
  [/^Betr (?:platform )?avg: ([\d.]+)/,         m => `AVG ${m[1]}`],
  [/^Career avg fallback: ([\d.]+)/,            m => `AVG ${m[1]}†`],
  [/^Recency-weighted: ([\d.]+)/,               m => `REC ${m[1]}`],
  [/^(?:Striker|Grappler) style \(([+-][\d.]+%)\)/, m => `STYLE ${m[1]}`],
  [/^vs (Striker|Grappler) \(([+-][\d.]+%)\)/,  m => `vs ${m[1]!.slice(0, 4).toUpperCase()} ${m[2]}`],
  [/^(?:Striker|Grappler) vs \w+ \(([+-][\d.]+%)\)/, m => `MIRROR ${m[1]}`],
  [/^5-round fight$/,                           () => '5R'],
];
const compressFactor = (r: string): string => {
  for (const [re, fmt] of FACTOR_SHORT) {
    const m = r.match(re);
    if (m) return fmt(m);
  }
  return r;
};
let _predSort: PredSort = 'card';
let _cachedLearningLog: LearningResult[] | null = null;
// MODEL v30 — how far posted FP lines sit above outcomes, learned from the
// archive. Loaded alongside the predictions so the board can show a FAIR line
// next to the posted one. See computeMarketFpShift for the measurement.
let _marketFpShift: { shift: number; sampleCount: number } | null = null;

async function generatePredictions(container: HTMLElement): Promise<void> {
  // Always force-refresh to get the nearest upcoming event (not a stale cached card)
  showToast('Fetching upcoming card...');
  await syncUpcomingCardContext(true);
  if (!upcomingCardPairs.length) {
    showToast('No upcoming card detected — no events found on UFCStats');
    return;
  }

  showToast(`Generating predictions for ${upcomingCardPairs.length} fights...`);

  const weights = await PropLinePredictorService.getWeights();
  const trends = await PropLinePredictorService.getTrends();
  // Load prop archive once — used for per-fighter bookmaker FP priors.
  const archiveRaw = await new Promise<Record<string, any>>(res => chrome.storage.local.get(['prop_archive_v1'], res));
  const propArchive: PropArchiveRecord[] = Array.isArray(archiveRaw.prop_archive_v1) ? archiveRaw.prop_archive_v1 as PropArchiveRecord[] : [];
  const predictions: PropPrediction[] = [];

  // MODEL v31 — the market anchor needs the posted fantasy line and the learned
  // shading. Same accessor shape as marketFt below, and the same getSourceActiveLine
  // the board's book chip reads, so the number capped against is the number shown.
  const fpShift = PropLinePredictorService.computeMarketFpShift(propArchive).shift;
  const postedFp = (name: string): number | null => {
    const entry = allFighters.find(x => namesMatch(normalizeName(x.name) || '', normalizeName(name) || ''));
    return entry ? getSourceActiveLine(entry, 'fp') : null;
  };

  const headliner = findHeadlinerPair();
  for (const pair of upcomingCardPairs) {
    const isMainEvent = headliner != null && headliner.f1 === pair.f1 && headliner.f2 === pair.f2;
    const rounds = isMainEvent ? 5 : 3;

    // Fetch UFCStats data for both fighters (uses 24h cache)
    const [f1Stats, f2Stats] = await Promise.all([
      fetchFromUFCStats(pair.f1),
      fetchFromUFCStats(pair.f2),
    ]);

    const f1DB = buildFighterDB(pair.f1, f1Stats);
    const f2DB = buildFighterDB(pair.f2, f2Stats);

    const f1Trend = PropLinePredictorService.findTrend(trends, pair.f1);
    const f2Trend = PropLinePredictorService.findTrend(trends, pair.f2);

    const f1Book = PropLinePredictorService.computeBookPriorFP(propArchive, pair.f1);
    const f2Book = PropLinePredictorService.computeBookPriorFP(propArchive, pair.f2);

    // MODEL v12: hand the predictor the market's fight-time line. It's the book's
    // own read on how long this fight lasts and prices in finish likelihood the
    // career averages miss, so the SS projection blends it into expected minutes.
    const marketFt = (name: string): number | null => {
      const entry = allFighters.find(x => namesMatch(normalizeName(x.name) || '', normalizeName(name) || ''));
      if (!entry) return null;
      return entry.line_pp_ft ?? entry.line_dk_ft ?? entry.line_ud_ft ?? entry.line_p6_ft ?? entry.line_betr_ft ?? null;
    };
    // MODEL v13: prefer a market-DERIVED expected duration (DK round ladder +
    // Go-the-Distance, both full-slate). Falls back to the pick-em FT line, then to
    // the career-based estimate, so it's inert until those markets post.
    const mktMin = (name: string): number | null =>
      marketExpectedFightMinutesDirect(name, rounds) ?? marketExpectedFightMinutesFromLadder(name, rounds);
    const p1 = PropLinePredictorService.predictFighter(
      pair.f1, pair.f2, f1DB, f2DB, rounds, weights, f1Trend, pair.weightClass, f1Book, marketFt(pair.f1), mktMin(pair.f1),
    );
    const p2 = PropLinePredictorService.predictFighter(
      pair.f2, pair.f1, f2DB, f1DB, rounds, weights, f2Trend, pair.weightClass, f2Book, marketFt(pair.f2), mktMin(pair.f2),
    );
    // MODEL v31: pull the fantasy number toward the fair line before it is stored.
    // Done HERE rather than inside the predictor because this is where the posted
    // lines live, and done BEFORE the save so that Best Picks, EV and the parlay
    // maths all read the anchored number — a cap that only trimmed the display
    // would leave the manufactured edge running underneath it.
    p1.fantasy = PropLinePredictorService.applyMarketAnchor(p1.fantasy, postedFp(pair.f1), fpShift);
    p2.fantasy = PropLinePredictorService.applyMarketAnchor(p2.fantasy, postedFp(pair.f2), fpShift);
    predictions.push(p1, p2);
  }

  const eventName = upcomingEventName || 'Unknown Event';
  const predEvent: PredictionEvent = {
    event: eventName,
    date: new Date().toISOString(),
    generatedAt: Date.now(),
    predictions,
    settled: false,
  };

  // Save (append, cap at 10)
  const existing = await PropLinePredictorService.getPredictions();
  // Replace if same event already exists
  const idx = existing.findIndex(e => e.event === eventName);
  if (idx >= 0) existing[idx] = predEvent;
  else existing.push(predEvent);
  await PropLinePredictorService.savePredictions(existing);
  _cachedPredictions = null;

  showToast(`✓ ${predictions.length} predictions generated for ${eventName}`);
  void renderArchivePanel(container);
}

function renderPredictionsHtml(
  cSec: (id: string, extra: string, hdr: string, title: string, count: string, body: string, style?: string) => string,
): string {
  const preds = _cachedPredictions ?? [];
  const log = _cachedLearningLog ?? [];

  // Find latest prediction event
  const latest = preds.length > 0 ? preds[preds.length - 1] : null;

  // Prediction table
  let predBody = '';
  if (latest && latest.predictions.length > 0) {
    const age = Date.now() - latest.generatedAt;
    const agoLabel = age < 3600000 ? `${Math.round(age / 60000)}m ago` : `${Math.round(age / 3600000)}h ago`;

    // ── GLOW-UP 259 — which model built this board ─────────────────────────
    // "Generated 45m ago" measures the wrong axis. A board is stale when the
    // MODEL moved under it, not when the clock did — and the model moved three
    // times in one night (v27 regression-to-mean, v28 no-history prior, v29 the
    // duration removal, which alone took Hernandez 102→~80 and McVey 95→~60).
    // A board carrying those old numbers rendered pixel-for-pixel identical to a
    // fresh one, and it is the number you would have bet off. The rows have
    // carried `modelVersion` since stamping began; the panel simply never read
    // it. Missing on pre-stamping rows, which read as v1 by the type's own note.
    const boardVersions = [...new Set(latest.predictions.map(p => p.modelVersion ?? 1))].sort((a, b) => a - b);
    const boardV = boardVersions[boardVersions.length - 1] ?? 1;
    const modelStale = boardV < MODEL_VERSION;
    // A board built by two different models is a partial regenerate — rarer, and
    // worse, because half the rows are comparable and half are not.
    const modelMixed = boardVersions.length > 1;
    const modelTip = modelStale
      ? `This board was built by MODEL v${boardV}. The predictor is now v${MODEL_VERSION}, so every number here predates ${MODEL_VERSION - boardV} model change${MODEL_VERSION - boardV === 1 ? '' : 's'} and is not what the current model would produce. Regenerate before reading it as a projection.`
      : `Built by MODEL v${boardV} — the current predictor. Numbers on this board are what the model produces today.`;
    const modelChip = `<span class="pred-model${modelStale ? ' is-stale' : ''}" title="${(modelTip + (modelMixed ? ` Mixed board: rows span v${boardVersions.join(', v')} — a partial regenerate. Regenerate the whole card so every row is comparable.` : '')).replace(/"/g, '&quot;')}">`
      + `MODEL v${boardV}${modelStale ? ` <b>→ v${MODEL_VERSION}</b>` : ''}${modelMixed ? ' <i>mixed</i>' : ''}</span>`;

    // Model-vs-book: the predictor ran pre-lines; once books post, the gap
    // between predicted and posted line IS the signal. Green = model sees
    // more than the book (over-shaded), red = less (under-shaded).
    const predByName = new Map(allFighters.map(f => [(normalizeName(f.name) || f.name).toLowerCase(), f] as const));
    const bookLineOf = (fighterName: string, src: 'ss' | 'td' | 'fp'): number | null => {
      const f = predByName.get((normalizeName(fighterName) || fighterName).toLowerCase());
      return f ? getSourceActiveLine(f, src) : null;
    };
    // The gap that counts as a gap. Shared by the book chip's colour and by the
    // split flag below, so a chip that reads "book agrees" can never also be
    // flagged as disagreeing.
    const gapThreshold = (src: 'ss' | 'td' | 'fp'): number => (src === 'td' ? 0.5 : 2);
    // ── MODEL v30 — a posted fantasy line is not a fair line ────────────────
    // Measured over 354 settled Pick6 FP props, recomputed from raw UFCStats with
    // the current scorer: the posted line runs about eleven points ABOVE the
    // outcome, and it does so persistently — all twelve event-clusters from April
    // to August came in negative, over-rate 38-48%. Fantasy points are dominated
    // by the win bonus, so clearing a line means winning the fight: winners clear
    // 81.7% of the time, losers 2.9%. A book setting the line near the mean is
    // setting it well above the median result.
    //
    // The board was comparing the model against that shaded number, so every
    // "model is under the book" reading carried eleven points of market shading
    // inside it. The gap is measured against the FAIR line now, and the posted
    // line is still shown because it is the number you actually bet.
    //
    // FP only. The same shading has NOT been measured on SS or TD and is not
    // assumed — those still compare against the posted line.
    const fpShift = _marketFpShift && Number.isFinite(_marketFpShift.shift) ? _marketFpShift.shift : 0;
    const bookCell = (fighterName: string, src: 'ss' | 'td' | 'fp', pred: number): string => {
      const f = predByName.get((normalizeName(fighterName) || fighterName).toLowerCase());
      const book = bookLineOf(fighterName, src);
      // A dash rather than the words "no line" — this state repeats up to 52 times
      // on a card and was the loudest quiet thing on the board.
      if (book == null || !Number.isFinite(Number(pred))) return `<div class="pred-book none" title="No posted line for this prop yet">—</div>`;
      const fair = src === 'fp' ? book + fpShift : book;
      const d = pred - fair;
      const thr = gapThreshold(src);
      const cls = d >= thr ? 'pos' : d <= -thr ? 'neg' : 'flat';
      // Name the actual book instead of a generic "BK". getSourceActiveLine walks the
      // platform priority, so the number can come from any of P6/UD/PP/BT/DK — printing
      // "BK" hid which one, and the whole point of the chip is comparing to a real line.
      const bookKey = f ? getSourceActivePlatformKey(f, src) : null;
      const bookTag = bookKey ? platformKeyShort(bookKey) : 'BK';
      const driving = _predSort === 'gap' && gapSrcByFighter.get(fighterName) === src ? ' is-driver' : '';
      const fairNote = src === 'fp' && fpShift !== 0
        ? ` Posted ${book}, but fantasy lines have run ${Math.abs(fpShift).toFixed(1)} points ABOVE the outcome across every settled card measured — winners clear a fantasy line 82% of the time, losers 3%, so a line set near the mean sits well above the median. Fair line ≈ ${fair.toFixed(1)}, and the gap shown is measured against that. You still bet the posted ${book}.`
        : '';
      return `<div class="pred-book ${cls}${driving}${src === 'fp' && fpShift !== 0 ? ' is-fair' : ''}" title="Model ${pred} vs ${bookTag} ${src === 'fp' && fpShift !== 0 ? `fair line ${fair.toFixed(1)}` : `line ${book}`} — gap ${d > 0 ? '+' : ''}${d.toFixed(1)} (${d >= thr ? 'line shaded under the model — over-side value' : d <= -thr ? 'line shaded over the model — under-side value' : 'line agrees with the model'}).${fairNote}">${bookTag} ${book} <b>${d > 0 ? '+' : ''}${d.toFixed(1)}</b></div>`;
    };

    // Model-vs-book gap on FP, used by the GAP sort. Signed by the model's own
    // direction, so "biggest edge" means biggest gap IN THE DIRECTION IT LEANS —
    // a 20-point gap the model is on the wrong side of is not an edge.
    // GLOW-UP 257: this used to read the FP gap only, and on a card where Betr has
    // not posted FP every row scored -Infinity — the sort ran, changed nothing, and
    // said nothing about why. A control that silently does nothing is worse than no
    // control. Now it walks FP → SS → TD and uses the first stat that actually has a
    // posted line, so it degrades to whatever the board knows instead of to noise.
    // Still signed by the model's own direction: a gap it sits on the wrong side of
    // is not an edge and sorts last.
    const gapOf = (p: PropPrediction): { v: number; src: 'ss' | 'td' | 'fp' | null } => {
      const f = predByName.get((normalizeName(p.fighter) || p.fighter).toLowerCase());
      if (!f) return { v: -Infinity, src: null };
      const tries: Array<['fp' | 'ss' | 'td', number, string]> = [
        ['fp', p.fantasy.line, p.fantasy.lean],
        ['ss', p.ss.line, p.ss.lean],
        ['td', p.td.line, p.td.lean],
      ];
      for (const [src, line, lean] of tries) {
        const book = getSourceActiveLine(f, src);
        if (book == null || !Number.isFinite(Number(line))) continue;
        // MODEL v30: same fair-line basis the chip uses, so the sort and the number
        // it is sorting by can never tell different stories.
        const d = line - (src === 'fp' ? book + fpShift : book);
        return { v: lean === 'over' ? d : -d, src };
      }
      return { v: -Infinity, src: null };
    };
    // Which stat the gap sort is reading per fighter — used to ring the driving
    // book chip so the ordering is self-explaining rather than mysterious.
    const gapSrcByFighter = new Map<string, 'ss' | 'td' | 'fp' | null>();
    for (const p of latest.predictions) gapSrcByFighter.set(p.fighter, gapOf(p).src);
    const gapUsable = latest.predictions.some(p => gapOf(p).src != null);
    const eviDOf = (p: PropPrediction): number =>
      p.fantasy.sampleSize ?? Number((p.fantasy.reasons.join(' ').match(/\((\d+)\s*fights?\)/) || [])[1] ?? 0);
    const sorted = _predSort === 'card' ? latest.predictions : [...latest.predictions].sort((a, b) =>
        _predSort === 'fp'   ? b.fantasy.line - a.fantasy.line
      : _predSort === 'conf' ? b.fantasy.confidence - a.fantasy.confidence
      : _predSort === 'eviD' ? eviDOf(b) - eviDOf(a)
      : gapOf(b).v - gapOf(a).v);
    // ── GLOW-UP 265 — a gauge that reads the same on a third of the board ───
    // Confidence is clamped at 92, and it is dominated by sample size: 30 + 4 per
    // past fight, plus consistency and a flat bonus for knowing the opponent. Any
    // fighter with nine or more fights lands on the ceiling, which on this card is
    // eight of twenty-six rows — and under the EVIDENCE sort those eight are the
    // entire first screen, ten identical lit cells stacked one above the other.
    // Rendering the clamp exactly like an earned score claims a distinction the
    // number does not make. The gauge now shows where the rail is, and the tooltip
    // counts the rows tied at it, so the reader knows what they are looking at.
    const cappedCount = latest.predictions.filter(p => Math.round(p.fantasy.confidence) >= FP_CONFIDENCE_CEILING).length;

    // Populated during the row map; the header legend is built from it afterwards.
    const lanesSeen = new Set<string>();
    const rows = sorted.map((p, rowIdx) => {
      const ssArrow = p.ss.lean === 'over' ? '▲' : '▼';
      const tdArrow = p.td.lean === 'over' ? '▲' : '▼';
      const fpArrow = p.fantasy.lean === 'over' ? '▲' : '▼';
      const ssColor = p.ss.lean === 'over' ? 'var(--green)' : 'var(--red)';
      const tdColor = p.td.lean === 'over' ? 'var(--green)' : 'var(--red)';
      const fpColor = p.fantasy.lean === 'over' ? 'var(--green)' : 'var(--red)';
      const confWidth = Math.round(p.fantasy.confidence);
      const confColor = confWidth >= 65 ? 'var(--green)' : confWidth >= 45 ? 'var(--amber)' : 'var(--red)';
      // ── GLOW-UP 250 — evidence weight ──────────────────────────────────
      // A projection off ONE fight rendered identically to one off thirteen: same
      // size, same weight, same colour, with the count buried as the fifth grey
      // pill in the factor rail. On this card that put Wint (1 fight, 99.5),
      // McVey (3, 95), Douglas (2, 94) and Barbosa (2, 93) among the highest FP
      // numbers on the board, indistinguishable from Hernandez's 102 off 13.
      // The walk-forward measured thin-history fighters running ~4pts hot at high
      // baselines BEFORE the duration step compounds it. Same principle the
      // calibration panel got tonight: thin evidence should LOOK thin.
      //
      // sampleSize is populated from v28 on; predictions stored before that lack
      // it, so fall back to the reason string, which already carries the count.
      const fpReasonText = p.fantasy.reasons.join(' ');
      const nFights = p.fantasy.sampleSize ?? (() => {
        const m = fpReasonText.match(/\((\d+)\s*fights?\)/);
        if (m) return Number(m[1]);
        return /no history/i.test(fpReasonText) ? 0 : null;
      })();
      const evTier = nFights == null ? null
        : nFights === 0 ? 'none' : nFights <= 2 ? 'thin' : nFights <= 7 ? 'mid' : 'solid';
      const evTip = nFights === 0
        ? 'No fight history at all — this number is built from components and shrunk hard toward the league mean. Read it as a prior, not a projection.'
        : nFights == null ? ''
        : `${nFights} past fight${nFights === 1 ? '' : 's'} behind this projection.` + (
            nFights <= 2 ? ' Measured: thin-history fighters run roughly 4 points hot at high projections, before the duration adjustment compounds it.'
          : nFights >= 8 ? ' Enough history that the estimate keeps real signal — measured slope 0.42 at 8+ priors, against 0.02-0.23 below.'
          : ' Middling sample: most of the deviation from league average is shrunk away.');
      // GLOW-UP 251: a signal meter rather than a number in a box. Five ascending
      // bars, lit by sample size — pre-attentive, so you read evidence depth while
      // scanning rather than stopping to parse "2f" against "13f". The count stays
      // beside it for the exact figure. `⌀` for no history matches the symbol the
      // rest of the app already uses for that state.
      const evLvl = nFights == null || nFights === 0 ? 0
        : nFights <= 2 ? 1 : nFights <= 4 ? 2 : nFights <= 7 ? 3 : nFights <= 11 ? 4 : 5;
      const evBadge = evTier
        ? `<span class="pred-ev pred-ev-${evTier}" title="${evTip.replace(/"/g, '&quot;')}">`
          + `<i class="pev-frame"></i><i class="pev-sheen"></i>`
          + `<span class="pev-meter" data-lvl="${evLvl}"><i></i><i></i><i></i><i></i><i></i></span>`
          + `<span class="pev-sep"></span>`
          + `<span class="pev-n">${nFights === 0 ? '⌀' : `${nFights}<b>f</b>`}</span>`
          + `</span>`
        : '';
      const thinCls = (evTier === 'thin' || evTier === 'none') ? ' pred-val-thin' : '';

      // The shrink is the single largest adjustment the model makes to an FP number,
      // and it was being truncated out of the rail by slice(0,2) on the fighters who
      // needed it most — Hernandez's "Betr avg" and "Recency-weighted" ate both slots.
      // Pull it out and always show it, with the two numbers legible at a glance.
      const shrinkReason = p.fantasy.reasons.find(r => r.startsWith('Regression to mean'));
      const shrinkM = shrinkReason?.match(/([\d.]+)→([\d.]+)/);
      const shrinkChip = shrinkM
        ? `<span class="pred-factor pred-factor-shrink" title="${(shrinkReason || '').replace(/"/g, '&quot;')}">${Number(shrinkM[1]) > Number(shrinkM[2]) ? '↓' : '↑'} ${shrinkM[1]}→${shrinkM[2]}</span>`
        : '';
      // GLOW-UP 258: was `.slice(0, 2)` — which truncated the FP reasons BEFORE the
      // priority sort could see them, defeating the whole point of ranking. Any
      // fighter carrying both `Betr avg` and `Recency-weighted` had those two eat
      // the budget and lost their `Duration adj` chip entirely. Hernandez (×1.48,
      // 79.7→101.6) and McVey (×2.05, 64.9→101.8) were both silently missing the
      // single largest adjustment on their row while Barbosa and Douglas showed
      // theirs, purely by accident of list position. Rank the full set; the SHOWN
      // cap below is what does the trimming, after priority has had its say.
      const otherFp = p.fantasy.reasons.filter(r => r !== shrinkReason);
      // Lane assignment, truncation priority and the legend all come from one
      // ordered table (FACTOR_LANES) — see the note there for what drifting apart
      // had cost. First match wins, so the table's order is also its precedence.
      const laneOf = (r: string): number => FACTOR_LANES.findIndex(l => l.test.test(r));
      const factorCls = (r: string): string => {
        const i = laneOf(r);
        return i < 0 ? '' : ` ${FACTOR_LANES[i]!.cls}`;
      };
      // GLOW-UP 255: the rail wrapped to two lines on eight of 26 rows, which broke
      // the scan rhythm, and it spent that space on chips like `Avg TD/fight: 0.0`
      // — a fighter with no takedowns, stated at the same weight as a finding.
      // Drop the no-signal ones, order by what actually moves a projection, and
      // clamp to a single line so every row is the same height. Priority ordering
      // is what makes the clamp safe: the guard and correction chips can never be
      // the ones pushed out of view.
      const isNoise = (r: string): boolean => /:\s*0(\.0)?$/.test(r.trim());
      const ranked = [...p.ss.reasons.slice(0, 2), ...p.td.reasons.slice(0, 1), ...otherFp]
        .filter(r => !isNoise(r))
        .map(r => ({ r, cls: factorCls(r), rank: laneOf(r) }))
        .sort((a, b) => (a.rank < 0 ? 99 : a.rank) - (b.rank < 0 ? 99 : b.rank));
      // 5 was set when a chip averaged ~110px. Compressed they average ~52px, so
      // the same rail holds seven — which is the whole factor set for most rows,
      // and `+N` now means something unusual rather than "this is a normal row".
      const SHOWN = 7;
      const shown = ranked.slice(0, SHOWN);
      const hidden = ranked.slice(SHOWN);
      const moreChip = hidden.length
        ? `<span class="pred-factor pf-more" title="${hidden.map(h => h.r).join(' · ').replace(/"/g, '&quot;')}">+${hidden.length}</span>`
        : '';
      // Only lanes actually DRAWN feed the legend — a key for a colour that is not
      // on screen is the exact failure this replaces. Chips folded into `+N` do not
      // count: their colour is not visible either.
      if (shrinkChip) lanesSeen.add(SHRINK_LANE.cls);
      for (const { cls } of shown) if (cls) lanesSeen.add(cls.trim());
      const reasons = shrinkChip
        + shown.map(({ r, cls }) => `<span class="pred-factor${cls}" title="${r.replace(/"/g, '&quot;')}">${compressFactor(r)}</span>`).join('')
        + moreChip;
      // Confidence as a ten-cell gauge in the same language as the evidence meter,
      // so the two instruments on a row read as one system. Same six grid children
      // in the same order — the track list is untouched.
      const confCells = Array.from({ length: 10 }, (_, i) =>
        `<i${i < Math.round(confWidth / 10) ? ' class="on"' : ''}></i>`).join('');
      const confTier = confWidth >= 65 ? 'hi' : confWidth >= 45 ? 'mid' : 'lo';
      const confCapped = confWidth >= FP_CONFIDENCE_CEILING;
      const confTip = confCapped
        ? `${confWidth}% is the model's confidence CEILING, not a top score — ${cappedCount} of ${latest.predictions.length} rows on this board read exactly the same number, and they do not have the same evidence behind them. Confidence is driven mostly by how many past fights the estimate rests on, so read the meter beside the fighter's name for the part that still separates them.`
        : `Model confidence ${confWidth}%. Driven mostly by how many past fights the estimate rests on, plus how consistent that history is and whether the opponent is known. It caps at ${FP_CONFIDENCE_CEILING}%.`;
      // GLOW-UP 262: `thinCls` used to be passed in `extra`, which put it on the
      // `.pcell` CONTAINER. `.pred-val-thin` sets `opacity` and a dotted underline,
      // and both inherit — so the doubt marker landed on the "FP" label and on the
      // book chip as well as on the number. The book line is a fact posted by a
      // sportsbook; dimming it as unreliable because the MODEL is short of history
      // is exactly backwards. Its own rule says "the number itself carries the
      // doubt", so give it a slot on the number.
      // ── GLOW-UP 266 — two directions wearing the same colour ────────────
      // The ▲/▼ beside a projection answers "is this ABOVE this fighter's own
      // career norm?" The book chip under it answers "is this above the POSTED
      // LINE?" Those are different questions, and on this card they disagree on
      // four rows — Jamall Emmers renders a red ▼ on an SS projection of 39
      // against a posted 29.5, nine and a half points the other way. Both
      // statements are correct; the problem is that the arrow, the value colour
      // and the row's whole accent beam all speak the app's direction axis, so a
      // scan reads "under" on a prop where the model is well over the line.
      // Nothing about the model changes here. The cell just stops presenting one
      // comparison in a way that will be read as the other.
      const splitMark = (src: 'ss' | 'td' | 'fp', pred: number, lean: string): string => {
        const book = bookLineOf(p.fighter, src);
        if (book == null || !Number.isFinite(Number(pred))) return '';
        const d = pred - book;
        if (Math.abs(d) < gapThreshold(src)) return '';
        const bookSide = d > 0 ? 'over' : 'under';
        if (bookSide === lean) return '';
        const tip = `Split read. The arrow says ${lean.toUpperCase()} because ${pred} is ${lean === 'over' ? 'above' : 'below'} ${prettyName(p.fighter)}'s own ${src.toUpperCase()} norm. But the posted line is ${book}, so against the BOOK this projection sits ${d > 0 ? 'over' : 'under'} by ${Math.abs(d).toFixed(1)}. The line is the side you can bet; the arrow is context about the fighter.`;
        return `<i class="pcell-split" title="${tip.replace(/"/g, '&quot;')}">⇅</i>`;
      };
      // MODEL v31: the cap changed the number on this row, so the row says so.
      // A silently-capped projection is worse than an uncapped one — it looks like
      // the model's own view while being the market's, and there would be no way
      // to tell the two apart on a board where both are just numbers.
      const anchorMark = (fp: StatPrediction): string => {
        if (fp.anchoredFrom == null) return '';
        const tip = `Model said ${fp.anchoredFrom.toFixed(1)}; pulled to ${fp.line.toFixed(1)}, the furthest MODEL v31 lets a fantasy projection sit from the fair line.`
          + ` Across 133 settled props the model was beaten by the bare line in every gap bucket and beaten worst where it disagreed most — 48.8 MAE against 32.7 on gaps past +30, and its OVER calls hit 37%.`
          + ` So the size of a disagreement is not evidence for it. The direction here still stands; only the magnitude was market-anchored.`;
        return `<i class="pcell-anchor" title="${tip.replace(/"/g, '&quot;')}">⚓</i>`;
      };
      const statCell = (lab: string, val: string, color: string, arrow: string, extra: string, book: string, valCls = '', mark = '') =>
        `<div class="pcell${extra}${mark ? ' has-split' : ''}"><span class="pcell-lab">${lab}${mark}</span>`
        + `<span class="pcell-val${valCls}" style="color:${color}">${val}<i>${arrow}</i></span>${book}</div>`;
      // GLOW-UP 264: both halves of a fight are on this board, and every sort
      // except CARD scatters them. Under EVIDENCE, Hernandez sits at row 6 and
      // Rodrigues at row 4; under FP they can be twenty rows apart. Two
      // projections priced against each other are the pair you most want to read
      // together — the opponent adjustment on one row IS the other row's fighter.
      // Same key and the same hover treatment Best Picks has used since GLOW-UP
      // 169, so the gesture transfers rather than being a second thing to learn.
      const fightKey = [p.fighter.toLowerCase(), (p.opponent || '').toLowerCase()].sort().join('|');
      return `<div class="pred-row pr-${p.fantasy.lean}" data-jump="${p.fighter}" data-fightkey="${fightKey.replace(/"/g, '&quot;')}" title="Open fighter card">
        <div class="pred-fighter"><span class="pred-rank" title="${_predSort === 'card' ? 'Position on the card, main event first' : `Rank ${rowIdx + 1} of ${sorted.length} under the current sort`}">${rowIdx + 1}</span><span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">🥊</span><img class="bp-avatar-img" data-name="${p.fighter}" alt="" /></span><div style="min-width:0"><div class="pf-name">${prettyName(p.fighter)}</div><div class="pf-sub"><span class="pf-vs">vs ${prettyName(p.opponent)} · ${p.scheduledRounds}R</span>${evBadge}</div></div></div>
        ${statCell('SS', String(p.ss.line), ssColor, ssArrow, '', bookCell(p.fighter, 'ss', p.ss.line), '', splitMark('ss', p.ss.line, p.ss.lean))}
        ${statCell('TD', String(p.td.line), tdColor, tdArrow, '', bookCell(p.fighter, 'td', p.td.line), '', splitMark('td', p.td.line, p.td.lean))}
        ${statCell('FP', String(p.fantasy.line), fpColor, fpArrow, ' pcell-fp' + (p.fantasy.anchoredFrom != null ? ' is-anchored' : ''), bookCell(p.fighter, 'fp', p.fantasy.line), thinCls, splitMark('fp', p.fantasy.line, p.fantasy.lean) + anchorMark(p.fantasy))}
        <div class="pconf pconf-${confTier}${confCapped ? ' is-capped' : ''}" title="${confTip.replace(/"/g, '&quot;')}"><span class="pcell-lab">CONF</span><span class="pconf-gauge">${confCells}</span><span class="pconf-n">${confWidth}<b>%</b></span></div>
        <div class="prail">${reasons}</div>
      </div>`;
    }).join('');

    // ── MODEL v30b — a board-wide offset is one fact, not twenty-four ───────
    // With the fair-line correction in, this card shows the model above fair on
    // 18 of 24 fighters at a median of about +8. Read row by row that looks like
    // eighteen edges. It is almost certainly one: a disagreement about the LEVEL
    // between the model and the market, which is a property of the board, not of
    // any fighter on it.
    //
    // It matters here more than usual because the -11 shift was calibrated against
    // stored predictions from MODEL v1 through v22 — the only versions with
    // settled results — and this board is v30. The measurement that said "the
    // model is unbiased" does not automatically transfer across eight model
    // revisions, several of which moved the FP level deliberately. Until a v30
    // board settles, the honest position is that the offset might be the market's
    // shading, might be the model's level, and the board should not pretend to
    // know which.
    //
    // Same principle as the evidence meter and the confidence rail: state the
    // uncertainty on the surface that would otherwise hide it.
    const fairGaps: number[] = [];
    for (const p2 of latest.predictions) {
      const bk = bookLineOf(p2.fighter, 'fp');
      if (bk == null || !Number.isFinite(Number(p2.fantasy.line))) continue;
      fairGaps.push(p2.fantasy.line - (bk + fpShift));
    }
    let boardChip = '';
    if (fairGaps.length >= 6) {
      const sorted = [...fairGaps].sort((a, b) => a - b);
      const med = sorted[Math.floor(sorted.length / 2)]!;
      const above = fairGaps.filter(g => g > 0).length;
      const skewed = Math.abs(med) >= 5;
      const tip = `Across the ${fairGaps.length} fighters with a posted fantasy line, the model sits a median of ${med > 0 ? '+' : ''}${med.toFixed(1)} against the fair line, above it on ${above} of them.`
        + (skewed
          ? ` That is a LEVEL disagreement between the model and the market, not ${above} separate edges — a real edge shows up on a few rows, not on most of them. Read each row's gap RELATIVE to this number: a fighter at +${med.toFixed(0)} is average for this board and carries no signal, and the informative rows are the ones far from it in either direction.`
          + ` Which side is wrong is genuinely unknown: the ${Math.abs(fpShift).toFixed(0)}-point market shift was measured against stored predictions from MODEL v7-v22, the only versions with settled results, and this board is v${MODEL_VERSION}. A v${MODEL_VERSION} card has not settled yet.`
          + ` MODEL v31 caps how far any single row may sit from its fair line (⚓ marks the rows it moved), because across those 133 settled props a bigger disagreement was reliably a WORSE one — the model's OVER calls hit 37%. The cap limits each row; it cannot correct a board-wide level, which is what this number is.`
          : ` Small enough that the model and the market broadly agree on the level, so row-level gaps can be read at face value.`);
      boardChip = `<span class="pred-board-skew${skewed ? ' is-skewed' : ''}" title="${tip.replace(/"/g, '&quot;')}">`
        + `${skewed ? '⚠ ' : ''}BOARD ${med > 0 ? '+' : ''}${med.toFixed(1)} <i>${above}/${fairGaps.length} above fair</i></span>`;
    }

    // The key dot carries the LANE'S OWN CLASS, so it inherits the same `color`
    // declaration the chips do. A legend swatch cannot drift from the chip it
    // describes when there is only one place the colour is written down.
    const legendKeys = [SHRINK_LANE, ...FACTOR_LANES]
      .filter(l => lanesSeen.has(l.cls))
      .map(l => `<span class="pkey"><i class="pkey-dot ${l.cls}"></i>${l.label}</span>`)
      .join('');

    const sortBtn = (k: PredSort, lab: string, tip: string) =>
      `<button class="psort${_predSort === k ? ' on' : ''}" data-psort="${k}" title="${tip}">${lab}</button>`;
    predBody = `<div class="pred-bar">
      <button id="predictorGenerateBtn" class="btn btn-sm pred-gen">⚡ Generate Predictions</button>
      <span class="pred-age">Generated ${agoLabel}${latest.settled ? ' · settled' : ''}</span>
      ${modelChip}${boardChip}
      <span class="pred-sortbar">
        <span class="pred-sortlab">SORT</span>
        ${sortBtn('card', 'CARD', 'Fight order, main event down — the order the night runs in')}
        ${gapUsable
          ? sortBtn('gap', 'Δ BOOK', 'Biggest gap between the model and the posted line, signed by the direction the model leans — a gap it sits on the wrong side of is not an edge and sorts last. Reads FP where a line exists, otherwise SS, otherwise TD; the chip it is reading gets a ring.')
          : `<button class="psort is-off" disabled title="No posted lines on this card yet, so there is nothing to measure a gap against. Load lines and this becomes available.">Δ BOOK</button>`}
        ${sortBtn('fp', 'FP', 'Highest projected fantasy score first')}
        ${sortBtn('conf', 'CONF', 'Highest model confidence first')}
        ${sortBtn('eviD', 'EVIDENCE', 'Most past fights behind the projection first — the inverse tells you which rows to distrust')}
      </span>
    </div>
    <div class="pred-head">
      <div>Fighter</div><div>SS</div><div>TD</div><div>FP</div><div>Conf</div>
      <div class="pred-head-rail">Factors${legendKeys}</div>
    </div>
    ${rows}`;
  } else {
    predBody = `<div style="text-align:center;padding:16px 0">
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px">${upcomingCardPairs.length > 0 ? `${upcomingCardPairs.length} fights detected on upcoming card` : 'No upcoming card detected yet'}</div>
      <button id="predictorGenerateBtn" class="btn btn-sm" style="background:var(--accent);color:#fff;padding:6px 16px;border-radius:6px;border:none;cursor:pointer;font-size:12px;font-weight:600">⚡ Generate Predictions</button>
    </div>`;
  }

  const predCount = latest ? `${latest.predictions.length} fighters · ${latest.event}` : 'no predictions yet';

  // Learning summary
  let learnBody = '';
  const latestLearn = log.length > 0 ? log[log.length - 1] : null;
  if (latestLearn) {
    const s = latestLearn.summary;
    const wAdj = Object.entries(s.weightAdjustments)
      .filter(([, v]) => v !== 0)
      .map(([k, v]) => `${k.replace(/_/g, ' ')}: ${(v as number) > 0 ? '+' : ''}${(v as number).toFixed(2)}`)
      .join(', ') || 'none';

    const deltaRows = latestLearn.predictions
      .filter(p => Number.isFinite(p.delta.ss) || Number.isFinite(p.delta.fp))
      .map(p => {
        const ssDelta = Number.isFinite(p.delta.ss) ? `${p.delta.ss > 0 ? '+' : ''}${p.delta.ss.toFixed(1)}` : '—';
        const tdDelta = Number.isFinite(p.delta.td) ? `${p.delta.td > 0 ? '+' : ''}${p.delta.td.toFixed(1)}` : '—';
        const fpDelta = Number.isFinite(p.delta.fp) ? `${p.delta.fp > 0 ? '+' : ''}${p.delta.fp.toFixed(1)}` : '—';
        const totalErr = Math.abs(p.delta.ss || 0) + Math.abs(p.delta.td || 0) + Math.abs(p.delta.fp || 0);
        const errColor = totalErr < 15 ? 'var(--green)' : totalErr < 30 ? 'var(--amber)' : 'var(--red)';
        const barPct = Math.min(100, (totalErr / 45) * 100);
        return `<div class="learn-delta-row" style="display:flex;gap:8px;align-items:center;padding:5px 4px;font-size:10px;border-bottom:1px solid rgba(255,255,255,0.04);border-radius:4px;transition:background 120ms" onmouseover="this.style.background='rgba(255,255,255,0.025)'" onmouseout="this.style.background='transparent'">
          <span class="learn-delta-name" style="min-width:100px;color:var(--text);font-weight:500">${p.fighter}</span>
          <span style="min-width:50px;color:var(--text-muted);font-variant-numeric:tabular-nums">SS ${ssDelta}</span>
          <span style="min-width:50px;color:var(--text-muted);font-variant-numeric:tabular-nums">TD ${tdDelta}</span>
          <span style="min-width:50px;color:var(--text-muted);font-variant-numeric:tabular-nums">FP ${fpDelta}</span>
          <div class="learn-delta-bar" style="flex:1;height:4px;background:rgba(255,255,255,0.05);border-radius:2px;overflow:hidden;min-width:36px" title="|Δ| magnitude">
            <div style="height:100%;width:${barPct.toFixed(0)}%;background:${errColor};border-radius:2px"></div>
          </div>
          <span class="learn-delta-total" style="color:${errColor};font-variant-numeric:tabular-nums;min-width:42px;text-align:right;font-weight:600">±${totalErr.toFixed(1)}</span>
        </div>`;
      }).join('');

    // A past-event prediction that hasn't been learned from yet — surface the
    // button even when prior learning history exists, so each settled event can
    // be absorbed without re-checking whether the log is empty.
    // Surface the learning button once the event is OVER, even if upcomingEventName hasn't
    // flipped to the next card yet — lets a just-finished, settled card (e.g. same-day Baku)
    // be absorbed immediately instead of waiting for the next slate's lines to load.
    const eventIsOver = Number.isFinite(upcomingEventTs) && upcomingEventTs > 0 && upcomingEventTs < Date.now();
    const pendingLearn = preds.find(p => {
      if (p.settled) return false;
      const isDifferentEvent = p.event !== (upcomingEventName || '').trim() && p.event !== upcomingEventName;
      return isDifferentEvent || eventIsOver;
    });
    const pendingBanner = pendingLearn ? `<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;margin-bottom:10px;background:rgba(56,176,0,0.08);border:1px solid rgba(56,176,0,0.3);border-radius:6px;flex-wrap:wrap">
      <span style="font-size:11px;color:var(--text);flex:1;min-width:160px">Predictions for "${pendingLearn.event}" ready for learning</span>
      <button id="predictorLearnBtn" class="btn btn-sm" style="background:var(--green);color:#000;padding:4px 12px;border-radius:6px;border:none;cursor:pointer;font-size:11px;font-weight:600">▶ Run Learning Cycle</button>
      <button id="predictorDeleteBtn" class="btn btn-sm" style="background:none;border:1px solid var(--text-muted);color:var(--text-muted);padding:3px 10px;border-radius:6px;cursor:pointer;font-size:10px" title="Delete these predictions">✕ Delete</button>
    </div>` : '';

    // Accuracy trajectory: compare against the PREVIOUS learning cycle so the
    // summary answers "is the model getting better?" instead of being a
    // memoryless snapshot. Lower |Δ| = better, so ▼ is the good direction.
    const prevLearn = log.length > 1 ? log[log.length - 2] : null;
    const prevS = prevLearn?.summary ?? null;
    const trendTag = (cur: number, prev: number | null | undefined): string => {
      if (prev == null || !Number.isFinite(prev)) return '';
      const d = cur - prev;
      if (Math.abs(d) < 0.05) return `<span class="learn-trend-chip flat" title="Unchanged vs last learning cycle">＝</span>`;
      const better = d < 0;
      return `<span class="learn-trend-chip ${better ? 'better' : 'worse'}" title="${better ? 'Improved' : 'Regressed'} vs last cycle (${prev.toFixed(1)} → ${cur.toFixed(1)})">${better ? '▼' : '▲'}${Math.abs(d).toFixed(1)}</span>`;
    };

    // ── GLOW-UP 331-334 · this panel was adding strikes to takedowns ──────────
    // Every aggregate here combined SS, TD and FP as if they shared a unit:
    //   overallAvg = (SS + TD + FP) / 3        chipColor(v) = v < 8 ? green : ...
    //   totalErr   = |dSS| + |dTD| + |dFP|     pct = val / 40
    // On the settled Hernandez card that reads SS ±25.5, TD ±1.2, FP ±35.8. TD is
    // not thirty times better than FP — it is measured on a scale thirty times
    // smaller. With one 8/16 threshold for all three, TD renders green with a 3%
    // stub no matter how wrong it gets, so the stat the model is WORST at
    // proportionally is the one the panel calls its best.
    //
    // Everything below normalises by the stat's own mean actual on the card, so a
    // ±1.2 takedown error against ~1 takedown a fight reads as what it is.
    const lrnRows = latestLearn.predictions || [];
    const meanOf = (pick: (p: typeof lrnRows[number]) => number): number => {
      const v = lrnRows.map(pick).filter(Number.isFinite);
      return v.length ? v.reduce((a, b) => a + b, 0) / v.length : 0;
    };
    // Signed bias — the number this panel never had. Absolute error says how far
    // off the model was; only the sign says which WAY, and that is the half that
    // decides whether a correction gets added, kept or reversed.
    const biasOf = (pick: (p: typeof lrnRows[number]) => number): number | null => {
      const v = lrnRows.map(pick).filter(Number.isFinite);
      return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
    };
    const SCALE_FLOOR: Record<string, number> = { SS: 5, TD: 0.5, FP: 10 };
    const scaleFor = (label: string): number => {
      const raw = label === 'SS' ? meanOf(p => Math.abs(p.actual.ss))
        : label === 'TD' ? meanOf(p => Math.abs(p.actual.td))
        : meanOf(p => Math.abs(p.actual.fp));
      return Math.max(raw, SCALE_FLOOR[label] ?? 1);
    };
    const biasFor = (label: string): number | null =>
      label === 'SS' ? biasOf(p => p.delta.ss)
      : label === 'TD' ? biasOf(p => p.delta.td)
      : biasOf(p => p.delta.fp);
    // Normalised error: avg |delta| as a share of that stat's own typical size.
    const normErr = (label: string, val: number): number => val / scaleFor(label);
    const chipColor = (n: number) => n < 0.30 ? 'var(--green)' : n < 0.50 ? 'var(--amber)' : 'var(--red)';
    const chipGrade = (n: number) => n < 0.30 ? 'good' : n < 0.50 ? 'mid' : 'bad';
    const statChip = (label: string, val: number, prevVal?: number | null) => {
      const n = normErr(label, val);
      const c = chipColor(n);
      const g = chipGrade(n);
      const bias = biasFor(label);
      // Bar is now the normalised share, so the three chips are finally comparable
      // to each other rather than each being a fraction of an arbitrary 40.
      const pct = Math.min(100, Math.round(n * 100));
      const biasTag = bias != null && Math.abs(bias) >= 0.05
        ? `<span class="learn-chip-bias ${bias > 0 ? 'under' : 'over'}" title="Signed bias: on average the model predicted ${bias > 0 ? 'BELOW' : 'ABOVE'} the outcome by ${Math.abs(bias).toFixed(1)}. Absolute error tells you how far off; only this tells you which way, which is what decides whether a correction is added, kept or reversed.">${bias > 0 ? '↑' : '↓'}${Math.abs(bias).toFixed(1)}</span>`
        : '';
      return `<div class="learn-stat-chip" data-grade="${g}">
        <div class="learn-chip-header"><span class="learn-chip-dot" style="background:${c}"></span><span class="learn-chip-label">Avg |Δ| ${label}</span></div>
        <span class="learn-chip-value" style="color:${c}">±${val.toFixed(1)}</span>${biasTag}${trendTag(val, prevVal)}
        <div class="learn-chip-bar-track" title="${(n * 100).toFixed(0)}% of a typical ${label} on this card (±${val.toFixed(1)} against a mean of ${scaleFor(label).toFixed(1)}). Shown as a share so SS, TD and FP can be compared — a raw ±1.2 on TD and ±35.8 on FP are not thirty times apart in quality."><div class="learn-chip-bar-fill" style="width:${pct}%;background:${c}"></div></div>
      </div>`;
    };
    const sortedDeltas = latestLearn.predictions
      .filter(p => Number.isFinite(p.delta.ss) || Number.isFinite(p.delta.fp))
      .map(p => {
        // GLOW-UP 335: was |dSS| + |dTD| + |dFP| — strikes plus takedowns plus
        // fantasy points. TD contributed ~1 of a ~40 sum, so the ranking was
        // essentially SS+FP and a fighter whose takedowns were badly missed sorted
        // as if they had been predicted perfectly. Worse, `|| 0` turned an
        // UNRESOLVED takedown into a perfect one — Kuse and Dorsainvil had no TD
        // market on the settled card and were scored as exact hits on it.
        // GLOW-UP 338: normalising fixed the old bug and introduced its mirror. A
        // ratio is unbounded, and TD sits on a scale near 1 — so being off by five
        // takedowns is 500%, which swamps a three-stat average on its own. Serghei
        // Spivac predicted SS to within HALF A STRIKE and still ranked 24th of 26,
        // because one takedown stat contributed 5.0 of his 5.67 total.
        //
        // Capped at 2.0 per stat. Past twice a typical performance the prediction is
        // simply wrong and how wrong stops carrying information about the fighter —
        // it only reflects how small that stat's denominator is. The cap bounds any
        // one stat's share of a composite without hiding it: the per-stat chips above
        // are uncapped, so a catastrophic TD still reads as catastrophic there.
        const STAT_CAP = 2.0;
        const parts: number[] = [];
        if (Number.isFinite(p.delta.ss)) parts.push(Math.min(STAT_CAP, Math.abs(p.delta.ss) / scaleFor('SS')));
        if (Number.isFinite(p.delta.td)) parts.push(Math.min(STAT_CAP, Math.abs(p.delta.td) / scaleFor('TD')));
        if (Number.isFinite(p.delta.fp)) parts.push(Math.min(STAT_CAP, Math.abs(p.delta.fp) / scaleFor('FP')));
        const totalErr = parts.length ? parts.reduce((a, b) => a + b, 0) / parts.length : 0;
        // GLOW-UP 340: the cap improves the ranking but conceals a real thing — a
        // row at 107% could be three mediocre stats or one blown-out stat dragging
        // two good ones. Recorded so the row can say which, rather than the cap
        // quietly flattening the difference.
        const capped: string[] = [];
        if (Number.isFinite(p.delta.ss) && Math.abs(p.delta.ss) / scaleFor('SS') > STAT_CAP) capped.push('SS');
        if (Number.isFinite(p.delta.td) && Math.abs(p.delta.td) / scaleFor('TD') > STAT_CAP) capped.push('TD');
        if (Number.isFinite(p.delta.fp) && Math.abs(p.delta.fp) / scaleFor('FP') > STAT_CAP) capped.push('FP');
        return { ...p, totalErr, capped };
      })
      .sort((a, b) => a.totalErr - b.totalErr);

    // GLOW-UP 333: the grade was the mixed-unit average of the three, so it was
    // effectively (SS + FP)/3 — TD could be arbitrarily wrong and move it by a
    // rounding error. Normalised per stat first, then averaged, and computed the
    // same way for past cycles so the trajectory stays internally comparable.
    // ── GLOW-UP 342 · ONE measure, everywhere ────────────────────────────────
    // This panel had grown two normalisations: a per-STAT one for the hero, the
    // previous-cycle comparison and the trajectory, and a per-FIGHTER capped one
    // for the table. 341 pointed the hero at the table and left the other two
    // behind, so the trend chip then compared 63% (per-fighter, this card) against
    // a per-stat figure for the last one and reported a meaningless ▲0.1.
    //
    // That is three times in this pass that fixing one path left a sibling on the
    // old maths. The cause was a wrong assumption of mine — I kept the per-stat
    // path believing past cycles stored only summaries. They store `predictions`
    // too, so every cycle can be scored exactly the way the table is scored, and
    // there is no reason for a second measure to exist.
    //
    // Scales are computed from each entry's OWN card, because a typical SS or FP
    // differs between slates and normalising last month's card by this month's
    // means would compare the wrong things.
    const perFighterNormOf = (entry: LearningResult): number => {
      // Same filter the table applies, so a cycle scored here and a cycle read off
      // the column below can never differ by which rows were counted.
      const rows = (entry.predictions || [])
        .filter(r => Number.isFinite(r.delta.ss) || Number.isFinite(r.delta.fp));
      if (!rows.length) return 0;
      const mean = (pick: (p: typeof rows[number]) => number): number => {
        const v = rows.map(pick).filter(Number.isFinite);
        return v.length ? v.reduce((a, b) => a + b, 0) / v.length : 0;
      };
      const sc = {
        SS: Math.max(mean(p => Math.abs(p.actual.ss)), SCALE_FLOOR.SS!),
        TD: Math.max(mean(p => Math.abs(p.actual.td)), SCALE_FLOOR.TD!),
        FP: Math.max(mean(p => Math.abs(p.actual.fp)), SCALE_FLOOR.FP!),
      };
      const CAP = 2.0;
      const per = rows.map(r => {
        const parts: number[] = [];
        if (Number.isFinite(r.delta.ss)) parts.push(Math.min(CAP, Math.abs(r.delta.ss) / sc.SS));
        if (Number.isFinite(r.delta.td)) parts.push(Math.min(CAP, Math.abs(r.delta.td) / sc.TD));
        if (Number.isFinite(r.delta.fp)) parts.push(Math.min(CAP, Math.abs(r.delta.fp) / sc.FP));
        return parts.length ? parts.reduce((a, b) => a + b, 0) / parts.length : 0;
      });
      return per.reduce((a, b) => a + b, 0) / per.length;
    };
    // GLOW-UP 341/342: the headline is the mean of the column beneath it, so the
    // panel can be checked by eye. Same function scores the previous cycle and the
    // trajectory, so a trend chip always compares like with like.
    const overallNorm = sortedDeltas.length
      ? sortedDeltas.reduce((a, x) => a + x.totalErr, 0) / sortedDeltas.length
      : perFighterNormOf(latestLearn);
    // Bands are provisional and stated on the ring: they were chosen so the raw
    // grade on the first normalised card lands where the old formula put it, not
    // fitted to anything. Revisit once several cycles have been scored this way.
    const overallGrade = overallNorm < 0.30 ? 'A' : overallNorm < 0.45 ? 'B' : overallNorm < 0.65 ? 'C' : 'D';
    const overallColor = overallNorm < 0.30 ? 'var(--green)' : overallNorm < 0.45 ? 'var(--amber)' : 'var(--red)';
    const prevOverall = prevLearn ? perFighterNormOf(prevLearn) : null;
    const overallAvg = overallNorm;

    // Mini trajectory chart: overall avg |Δ| across the last learning cycles
    // (bar height ∝ error, so a shrinking skyline = an improving model).
    const trajEntries = log.slice(-8);
    let trajHtml = '';
    if (trajEntries.length > 1) {
      const trajVals = trajEntries.map((e) => perFighterNormOf(e));
      const trajMax = Math.max(...trajVals, 1);
      const bars = trajEntries.map((e, i) => {
        const v = trajVals[i];
        const h = Math.max(14, Math.round((v / trajMax) * 100));
        const g = v < 0.30 ? 'g-a' : v < 0.45 ? 'g-b' : v < 0.65 ? 'g-c' : 'g-d';
        const evName = (e as { event?: string }).event ?? 'earlier cycle';
        return `<i class="${g}${i === trajEntries.length - 1 ? ' cur' : ''}" style="height:${h}%" title="${String(evName).replace(/"/g, '&quot;')} — normalised error ${(v * 100).toFixed(0)}%"></i>`;
      }).join('');
      trajHtml = `<div class="learn-traj" title="Accuracy trajectory — last ${trajEntries.length} learning cycles (shorter bars = better)">${bars}</div>`;
    }

    // GLOW-UP 336: summary.bestPrediction / worstPrediction are written by the
    // learning cycle using the OLD mixed-unit score (|dSS| + |dTD| + |dFP|). Once
    // the table below was renormalised the two disagreed on screen — the hero
    // called Wes Schultz best while the table ranked him 9th of 26. A panel that
    // contradicts itself in two places is worse than one that is merely wrong in
    // one, so both now read the ranking that is actually displayed.
    const bestRanked = sortedDeltas.length ? sortedDeltas[0]!.fighter : s.bestPrediction;
    const worstRanked = sortedDeltas.length ? sortedDeltas[sortedDeltas.length - 1]!.fighter : s.worstPrediction;
    // GLOW-UP 337: six of twenty-six rows land past 100% on this card (up to 237%),
    // so a bar clamped at 100% flattens the entire tail into one length. Scaled to
    // the card's own worst instead: the percentage beside it still carries the
    // absolute reading, and the bar goes back to doing the one thing a bar is for,
    // which is ordering things against each other.
    const worstErr = sortedDeltas.length ? Math.max(...sortedDeltas.map(x => x.totalErr), 0.01) : 1;
    const rankedRows = sortedDeltas.map((p, idx) => {
      const ssDelta = Number.isFinite(p.delta.ss) ? `${p.delta.ss > 0 ? '+' : ''}${p.delta.ss.toFixed(1)}` : '—';
      const tdDelta = Number.isFinite(p.delta.td) ? `${p.delta.td > 0 ? '+' : ''}${p.delta.td.toFixed(1)}` : '—';
      const fpDelta = Number.isFinite(p.delta.fp) ? `${p.delta.fp > 0 ? '+' : ''}${p.delta.fp.toFixed(1)}` : '—';
      // Thresholds and bar now sit on the normalised share, so they stop
      // saturating: the old /45 denominator put nine of eleven rows at full-width
      // red on the settled card, which ranks nothing.
      const errColor = p.totalErr < 0.30 ? 'var(--green)' : p.totalErr < 0.50 ? 'var(--amber)' : 'var(--red)';
      const barPct = Math.min(100, (p.totalErr / worstErr) * 100);
      const g = p.totalErr < 0.30 ? 'good' : p.totalErr < 0.50 ? 'mid' : 'bad';
      return `<div class="learn-delta-row" data-grade="${g}">
        <span class="learn-delta-rank">${idx + 1}</span>
        <span class="learn-delta-name">${p.fighter}</span>
        <span class="learn-delta-stat">SS ${ssDelta}</span>
        <span class="learn-delta-stat">TD ${tdDelta}</span>
        <span class="learn-delta-stat">FP ${fpDelta}</span>
        <div class="learn-delta-bar"><div class="learn-delta-bar-fill" style="width:${barPct.toFixed(0)}%;background:${errColor}"></div></div>
        <span class="learn-delta-total" style="color:${errColor}" title="Average error across this fighter's resolved stats, as a share of a typical performance in each. Stats with no market — so nothing to grade against — are left out rather than counted as perfect.${p.capped.length ? ` ${p.capped.join(' and ')} exceeded twice a typical performance and was capped at 200% before averaging, so the real miss on ${p.capped.length > 1 ? 'those stats' : 'that stat'} is larger than this figure implies.` : ''}">${p.capped.length ? `<i class="learn-capped" title="">▲${p.capped.join('/')}</i>` : ''}${Math.round(p.totalErr * 100)}%</span>
      </div>`;
    }).join('');

    learnBody = `${pendingBanner}
    <div class="learn-hero">
      <div class="learn-grade-ring" style="--grade-color:${overallColor}"><span class="learn-grade-letter">${overallGrade}</span></div>
      <div class="learn-hero-meta">
        <div class="learn-hero-title">Prediction Accuracy</div>
        <div class="learn-hero-subtitle" title="Average error across SS, TD and FP, each expressed as a share of a typical value for that stat before being combined. The previous formula averaged the three raw numbers, so a takedown miss of 1.2 counted the same as a fantasy miss of 1.2 — thirty times smaller in proportion. Raw per-stat figures are on the chips below.">Normalised error ${(overallNorm * 100).toFixed(0)}% across ${sortedDeltas.length} fighters${trendTag(overallNorm * 100, prevOverall != null ? prevOverall * 100 : null)}</div>
        <div class="learn-hero-badges">
          <span class="learn-badge-best" title="Lowest normalised error on this card — the same ranking as the table below.">▲ Best · ${bestRanked}</span>
          <span class="learn-badge-worst" title="Highest normalised error on this card — the same ranking as the table below.">▼ Worst · ${worstRanked}</span>
        </div>
      </div>
      ${trajHtml}
    </div>
    <div class="learn-chips-row">
      ${statChip('SS', s.avgAbsDeltaSS, prevS?.avgAbsDeltaSS)}
      ${statChip('TD', s.avgAbsDeltaTD, prevS?.avgAbsDeltaTD)}
      ${statChip('FP', s.avgAbsDeltaFP, prevS?.avgAbsDeltaFP)}
    </div>
    <div class="learn-meta-row">
      <details class="weights-details"><summary>Weights — click to expand</summary><div class="weights-body">${wAdj}</div></details>
      <span class="learn-trend-label"><span class="learn-trend-tag">Trends</span> ${s.trendUpdates}</span>
    </div>
    <div class="learn-delta-header">
      <span class="learn-dh-rank">#</span>
      <span class="learn-dh-name">Fighter</span>
      <span class="learn-dh-stat">SS</span>
      <span class="learn-dh-stat">TD</span>
      <span class="learn-dh-stat">FP</span>
      <span class="learn-dh-bar">Error</span>
      <span class="learn-dh-total">|Δ|</span>
    </div>
    ${rankedRows}`;
  } else {
    // Show learn button if we have unsettled predictions and settled archive data
    const unsettled = (preds).find(p => !p.settled);
    if (unsettled) {
      const eventOver = Number.isFinite(upcomingEventTs) && upcomingEventTs > 0 && upcomingEventTs < Date.now();
      const isCurrentEvent = (unsettled.event === (upcomingEventName || '').trim() || unsettled.event === upcomingEventName) && !eventOver;
      const deleteBtn = `<button id="predictorDeleteBtn" class="btn btn-sm" style="background:none;border:1px solid var(--text-muted);color:var(--text-muted);padding:3px 10px;border-radius:6px;cursor:pointer;font-size:10px;margin-left:8px" title="Delete these predictions">✕ Delete</button>`;
      if (isCurrentEvent) {
        // Predictions match the upcoming event — not ready for learning yet
        learnBody = `<div style="text-align:center;padding:12px 0">
          <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px">Predictions for "${unsettled.event}" — awaiting event results</div>
          ${deleteBtn}
        </div>`;
      } else {
        learnBody = `<div style="text-align:center;padding:12px 0">
          <div style="font-size:11px;color:var(--text-muted);margin-bottom:8px">Predictions for "${unsettled.event}" ready for learning</div>
          <button id="predictorLearnBtn" class="btn btn-sm" style="background:var(--green);color:#000;padding:5px 14px;border-radius:6px;border:none;cursor:pointer;font-size:11px;font-weight:600">▶ Run Learning Cycle</button>
          ${deleteBtn}
        </div>`;
      }
    } else {
      learnBody = `<div class="inline-empty-msg" style="font-size:10px">No learning data yet — generate predictions, then settle an event</div>`;
    }
  }

  const learnCount = latestLearn ? `${latestLearn.event}` : '';

  return `${cSec('predictions', '', '', 'Prop Line Predictions', predCount, predBody, 'margin-bottom:12px')}
    ${cSec('learning', '', '', 'Learning Summary', learnCount, learnBody, 'margin-bottom:12px')}`;
}

async function renderArchivePanel(container: HTMLElement): Promise<void> {
  container.innerHTML = loadingSkeleton('Loading prop archive…');

  // Auto-settle once per session if there are past unresolved events
  if (!_archiveAutoSettleFired) {
    _archiveAutoSettleFired = true;
    runtimeSendMessage<{ ok: boolean; settled: number }>({ type: 'GRADE_ARCHIVE' })
      .then(res => {
        if (res?.ok && res.settled > 0) {
          showToast(`✓ Auto-settled ${res.settled} result(s) from UFCStats`);
          void renderArchivePanel(container);
        }
      })
      .catch(() => {});
  }

  const [result, linesPayload] = await Promise.all([
    storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY, STORAGE_BEST_PICKS_PLACED_KEY, STORAGE_BEST_PICKS_SNAPSHOT_KEY, STORAGE_PARLAY_PLACED_KEY]),
    storageGet<Record<string, unknown>>(STORAGE_LINE_KEYS as unknown as string[]),
  ]);
  const allRowsRaw = result[STORAGE_PROP_ARCHIVE_KEY];
  const allRows = Array.isArray(allRowsRaw) ? (allRowsRaw as PropArchiveRecord[]) : [];
  const rowsForEvent = makeRowsByEvent(allRows, eventDedupeKey);

  // Lines staleness — find most recent capturedAt across all platform payloads
  const linesCapturedAt = Math.max(0, ...STORAGE_LINE_KEYS.map(k => {
    const val = (linesPayload as Record<string, any>)[k];
    return Number(val?.capturedAt || 0);
  }));
  const stalenessMins = linesCapturedAt > 0 ? Math.floor((Date.now() - linesCapturedAt) / 60000) : null;
  const stalenessLabel = stalenessMins == null ? '' :
    stalenessMins < 5 ? '· Lines: just now' :
    stalenessMins < 60 ? `· Lines: ${stalenessMins}m ago` :
    `· Lines: ${Math.floor(stalenessMins / 60)}h ago`;

  const currentRoster = new Set(
    allFighters.map((f) => normalizeName(f.name)?.toLowerCase()).filter((n): n is string => !!n)
  );
  // When no lines are loaded, treat all archive fighters as "on roster" so archive always shows
  const rosterFilter = (fighter: string) => currentRoster.size === 0 || currentRoster.has(fighter.toLowerCase());

  const londonTs = Date.parse(UFC_LONDON_CUTOFF_ISO);
  const nowTs    = Date.now();

  // Normalize event name to a dedup key — extract sorted fighter surnames from "UFC Fight Night: A vs B"
  function eventDedupeKey(name: string): string {
    const m = name.match(/:\s*(.+?)\s+vs\.?\s+(.+)/i);
    if (!m) return name.toLowerCase().trim();
    const a = m[1].trim().split(/\s+/).pop()!.toLowerCase();
    const b = m[2].trim().split(/\s+/).pop()!.toLowerCase();
    return [a, b].sort().join('|');
  }

  // ── GLOW-UP 172 (Placed → Learning level 1): Placed Ledger ─────────────
  // Every leg the user marked ● PLACED (best_picks_placed_v1, keyed per
  // event), live-joined against the archive: ✓ HIT / ✗ MISS with the actual
  // number once the prop settles, ○ PENDING until then. Read-only join —
  // persistence of outcomes is level 3's job.
  type PlacedLedgerRec = { name: string; pretty: string; dir: string; source: string; statLabel: string; line: number | null; book: string | null; bookLabel: string; opponent: string | null; placedAt: number; outcome?: 'hit' | 'miss'; actual?: number | null; resolvedAt?: number };
  type PlacedOutcomeUpdate = { evKey: string; legKey: string; outcome: 'hit' | 'miss'; actual: number | null };
  // Placed source key → archive PropType candidates. FP is book-aware:
  // PrizePicks scores differently, so it archives as Fantasy_PP. Hoisted to
  // panel scope (GLOW-UP 181) so the Parlay Ledger resolves legs identically.
  const propTypesFor = (source: string, book: string | null): string[] => {
    if (source === 'fp') return book === 'prizepicks' ? ['Fantasy_PP', 'Fantasy'] : ['Fantasy', 'Fantasy_PP'];
    if (source === 'ss') return ['SS'];
    if (source === 'ss_r1') return ['SS_R1'];
    if (source === 'td') return ['TD'];
    if (source === 'ft') return ['FightTime'];
    // Both spellings, because CTRL is archived under two of them. A live CTRL
    // LINE lands as 'ctrl': toArchivePropTypeFromLineKey has no case for
    // 'line_ctrl' (its `includes('control')` test doesn't fire) so it falls
    // through to the generic strip-and-space branch. Those are the rows the
    // settle path resolves — in minutes, and the only ones carrying a line.
    // Historical control from the UFCStats backfill lands as 'Control'.
    // resolveVsArchive compares the RAW propType, so asking only for 'Control'
    // matched the backfilled rows and never the settled ones.
    if (source === 'ctrl') return ['ctrl', 'Control'];
    if (source === 'kd') return ['KD'];
    return [];
  };
  // ── PERF · the Archive's freeze was 246 million string compares ──────────
  // resolveVsArchive ran `allRows.find(...)` once per candidate propType, and the
  // predicate did a Date.parse AND a normalizeName on every row it touched. One
  // render issues ~3,200 of those calls — 91 placed legs, 91 parlay legs, 811
  // snapshot picks walked twice (board baseline and selection diagnostics), 1,375
  // ai-lean picks — against a 38,689-row archive. Worst case a quarter of a
  // billion predicate evaluations before the first pixel, which is the blank
  // skeleton you sit through after clicking ARCHIVE.
  //
  // The lookup is exact-match on three fields, so it wants a Map, not a scan.
  // Built once per render, lazily, so a view that never resolves anything pays
  // nothing for it.
  //
  // Two behaviours preserved deliberately, both load-bearing:
  //  · FIRST row wins for a duplicate key, because `.find` returned the earliest
  //    row in allRows order and duplicate-event shadow rows are a real thing here.
  //  · The candidate list stays PRIORITY-ORDERED at the call site below. The index
  //    keys propType so 'Fantasy' before 'Fantasy_PP' (and 'ctrl' before
  //    'Control') still resolves in the caller's order, not the archive's.
  // The date guard and the finite-result guard move into the build, where they
  // run once per row instead of once per row per call.
  let _archiveIdx: Map<string, typeof allRows[number]> | null = null;
  const archiveIdx = (): Map<string, typeof allRows[number]> => {
    if (_archiveIdx) return _archiveIdx;
    const m = new Map<string, typeof allRows[number]>();
    for (const r of allRows) {
      if (!Number.isFinite(Number(r.result))) continue;
      const ts = Date.parse(r.date);
      if (!Number.isFinite(ts) || ts > nowTs) continue;
      const k = `${eventDedupeKey(r.event || '')}|${normalizeName(r.fighter)?.toLowerCase() || ''}|${String(r.propType)}`;
      if (!m.has(k)) m.set(k, r);
    }
    _archiveIdx = m;
    return m;
  };
  // ── GLOW-UP 311 · the CLOSING line for a leg, not just its outcome ────────
  // resolveVsArchive answers "did it hit". This answers "where did the line end
  // up", which is what turns an entry price into CLV. Same index, same candidate
  // priority, same first-row-wins — it is the identical lookup, returning a
  // different field, so the two can never disagree about which row they mean.
  const closeLineFor = (evDk: string, fighterRaw: string, candidates: string[]): number | null => {
    if (!candidates.length) return null;
    const fighterNorm = normalizeName(fighterRaw)?.toLowerCase() || fighterRaw.toLowerCase();
    const idx = archiveIdx();
    for (const want of candidates) {
      const m = idx.get(`${evDk}|${fighterNorm}|${want}`);
      if (m && Number.isFinite(Number(m.line))) return Number(m.line);
    }
    return null;
  };
  // Shared date-guarded resolver — used by the placed ledger, the board
  // baseline, and the parlay ledger so nothing can be graded differently.
  const resolveVsArchive = (evDk: string, fighterRaw: string, candidates: string[], line: number | null, dir: 'over' | 'under'): { outcome: 'hit' | 'miss' | 'pending'; actual: number | null } => {
    if (!candidates.length || line == null || !Number.isFinite(Number(line))) return { outcome: 'pending', actual: null };
    const fighterNorm = normalizeName(fighterRaw)?.toLowerCase() || fighterRaw.toLowerCase();
    // ── The candidate list is PRIORITY-ORDERED; honour it ────────────────
    // This used to be one `allRows.find` with `candidates.includes(propType)`,
    // which returns whichever row sits earliest in allRows and so ignored the
    // order entirely. propTypesFor is explicitly a preference list — 'Fantasy'
    // then 'Fantasy_PP' for Pick6/UD/Betr, reversed for PrizePicks — because the
    // two are DIFFERENT RULEBOOKS, not two copies of one number: PrizePicks
    // scores no control time, no non-sig strikes, and a decision win at 10
    // against 30. Grading an Underdog leg against the PP total is grading it
    // against a sport it wasn't placed in.
    //
    // It stayed hidden until an event settled. The settle path writes one row;
    // the UFCStats backfill writes BOTH Fantasy and Fantasy_PP, and only runs
    // once the card lands in fighters' fight history — i.e. after the event. So
    // pre-settle there was nothing to pick wrongly, and post-settle the live
    // resolve started disagreeing with outcomes the Placed Ledger had already
    // frozen. Esteban Ribovics OVER 93.99 FP @ Underdog, UFC 330: 97.2 by
    // Fantasy scoring (a hit, as the Placed Ledger had persisted), graded a miss
    // in the Parlay Ledger against his PP-scored total.
    //
    // Now also load-bearing for CTRL, whose candidates are ['ctrl','Control'] —
    // 'ctrl' is the settled row that carries the line and must win.
    // Same candidate priority as before — the loop order IS the preference, and
    // the index only replaces the scan inside it.
    const idx = archiveIdx();
    let match: typeof allRows[number] | undefined;
    for (const want of candidates) {
      match = idx.get(`${evDk}|${fighterNorm}|${want}`);
      if (match) break;
    }
    if (!match) return { outcome: 'pending', actual: null };
    const actual = normalizeArchiveResult(String(match.propType), Number(match.result));
    const hit = dir === 'over' ? actual > Number(line) : actual < Number(line);
    return { outcome: hit ? 'hit' : 'miss', actual };
  };
  const placedLedgerData = ((): { html: string; settled: number; hits: number; total: number; boardSettled: number; boardHits: number; updates: PlacedOutcomeUpdate[] } => {
    const placedRaw = result[STORAGE_BEST_PICKS_PLACED_KEY];
    const placedAll: Record<string, Record<string, PlacedLedgerRec>> =
      placedRaw && typeof placedRaw === 'object' && !Array.isArray(placedRaw)
        ? (placedRaw as Record<string, Record<string, PlacedLedgerRec>>)
        : {};

    // GLOW-UP 173 (level 2): the board's side of the comparison — latest
    // snapshot per event (closing board) from best_picks_snapshots_v1,
    // resolved through the same resolver. Compared only on events where
    // the user placed something, so the baseline is apples-to-apples.
    const snapsRaw = result[STORAGE_BEST_PICKS_SNAPSHOT_KEY];
    const snaps = Array.isArray(snapsRaw) ? (snapsRaw as Array<{ event?: string; date?: string; picks?: Array<{ fighter?: string; lean?: string; line?: number | null; source?: string; platform?: string }> }>) : [];
    const latestSnapByDk = new Map<string, typeof snaps[number]>();
    for (const s of snaps) {
      const dk = eventDedupeKey(String(s?.event || ''));
      if (!dk) continue;
      const prev = latestSnapByDk.get(dk);
      if (!prev || Date.parse(String(s?.date || '')) > Date.parse(String(prev?.date || ''))) latestSnapByDk.set(dk, s);
    }
    const boardPropTypesFor = (source: string, platformLabel: string): string[] => {
      if (source === 'fp') return /prizepicks|(^|\s)PP\b/i.test(platformLabel) ? ['Fantasy_PP', 'Fantasy'] : ['Fantasy', 'Fantasy_PP'];
      return propTypesFor(source, null);
    };
    const boardStatsFor = (evDk: string): { settled: number; hits: number } => {
      const snap = latestSnapByDk.get(evDk);
      let settled = 0, hits = 0;
      for (const p of (snap?.picks || [])) {
        const lean = String(p?.lean || '');
        if (lean !== 'over' && lean !== 'under') continue;
        const res = resolveVsArchive(evDk, String(p?.fighter || ''), boardPropTypesFor(String(p?.source || 'fp'), String(p?.platform || '')), p?.line ?? null, lean);
        if (res.outcome === 'pending') continue;
        settled++;
        if (res.outcome === 'hit') hits++;
      }
      return { settled, hits };
    };

    type LedgerLeg = { rec: PlacedLedgerRec; outcome: 'hit' | 'miss' | 'pending'; actual: number | null };
    const events: { evKey: string; newest: number; legs: LedgerLeg[] }[] = [];
    // GLOW-UP 174: legs that just settled get their outcome queued for
    // write-back so history survives archive pruning; legs with a persisted
    // outcome skip the archive lookup entirely (storage wins over recompute).
    const updates: PlacedOutcomeUpdate[] = [];
    for (const [evKey, legsMap] of Object.entries(placedAll)) {
      const legEntries = Object.entries(legsMap || {}).filter(([, r]) => r && typeof r === 'object');
      if (!legEntries.length) continue;
      const evDk = eventDedupeKey(evKey);
      const legs: LedgerLeg[] = legEntries.map(([legKey, rec]) => {
        if (rec.outcome === 'hit' || rec.outcome === 'miss') {
          return { rec, outcome: rec.outcome, actual: rec.actual ?? null };
        }
        const dir = rec.dir === 'OVER' ? 'over' as const : 'under' as const;
        const res = resolveVsArchive(evDk, rec.name, propTypesFor(rec.source, rec.book), rec.line, dir);
        if (res.outcome !== 'pending') updates.push({ evKey, legKey, outcome: res.outcome, actual: res.actual });
        return { rec, outcome: res.outcome, actual: res.actual };
      });
      events.push({ evKey, newest: Math.max(0, ...legEntries.map(([, r]) => Number(r.placedAt) || 0)), legs });
    }
    events.sort((a, b) => b.newest - a.newest);
    const flat = events.flatMap(e => e.legs);
    const settled = flat.filter(l => l.outcome !== 'pending').length;
    const hits = flat.filter(l => l.outcome === 'hit').length;

    // ── GLOW-UP 175 (level 4): selection diagnostics ──────────────────────
    // Split each placed event's suggested slate (latest snapshot) into the
    // picks you TOOK vs the ones you SKIPPED, grade both cohorts with the
    // shared resolver, and measure the gap — are you picking the right
    // picks off the board? Match key: fighter + direction + stat source.
    const selection = ((): { html: string } => {
      type Cohort = { settled: number; hits: number; confSum: number; confN: number };
      const taken: Cohort = { settled: 0, hits: 0, confSum: 0, confN: 0 };
      const skipped: Cohort = { settled: 0, hits: 0, confSum: 0, confN: 0 };
      for (const e of events) {
        const evDk = eventDedupeKey(e.evKey);
        const snap = latestSnapByDk.get(evDk);
        if (!snap?.picks?.length) continue;
        const placedKeys = new Set(e.legs.map(l =>
          `${normalizeName(l.rec.name)?.toLowerCase() || l.rec.name.toLowerCase()}|${l.rec.dir.toLowerCase()}|${l.rec.source}`));
        for (const p of snap.picks) {
          const lean = String((p as { lean?: string })?.lean || '');
          if (lean !== 'over' && lean !== 'under') continue;
          const fighter = String((p as { fighter?: string })?.fighter || '');
          const source = String((p as { source?: string })?.source || 'fp');
          const res = resolveVsArchive(evDk, fighter, boardPropTypesFor(source, String((p as { platform?: string })?.platform || '')), (p as { line?: number | null })?.line ?? null, lean);
          if (res.outcome === 'pending') continue;
          const key = `${normalizeName(fighter)?.toLowerCase() || fighter.toLowerCase()}|${lean}|${source}`;
          const cohort = placedKeys.has(key) ? taken : skipped;
          cohort.settled++;
          if (res.outcome === 'hit') cohort.hits++;
          const conf = Number((p as { confidence?: number })?.confidence);
          if (Number.isFinite(conf) && conf > 0) { cohort.confSum += conf; cohort.confN++; }
        }
      }
      if (!taken.settled || !skipped.settled) return { html: '' };
      const takenRate = taken.hits / taken.settled;
      const skippedRate = skipped.hits / skipped.settled;
      // ── GLOW-UP 310 · a headline number the sample could not support ─────────
      // This read ALPHA -21pts on the live ledger, in a rose chip, as the loudest
      // claim in the panel — off NINE settled taken legs. The standard error of
      // that gap is 16pts, so -21 sits 1.3 SE from zero: indistinguishable from no
      // effect at all. "The picks you skip are beating the ones you take" is a
      // serious thing to tell someone about their own judgement, and it was being
      // said on noise.
      //
      // Two corrections, both already house convention elsewhere. The rates are
      // Laplace-shrunk (+1 hit / +1 miss, what shrunkHitRate uses) so a thin cohort
      // cannot claim its extremes; and below 1.5 SE the chip stops taking a side —
      // neutral, no colour, and it says outright how many legs it is standing on.
      const lap = (h: number, n: number): number => (h + 1) / (n + 2);
      const alphaRaw = takenRate - skippedRate;
      const alphaShrunk = lap(taken.hits, taken.settled) - lap(skipped.hits, skipped.settled);
      const seDiff = Math.sqrt(
        (takenRate * (1 - takenRate)) / taken.settled + (skippedRate * (1 - skippedRate)) / skipped.settled,
      );
      const conclusive = Number.isFinite(seDiff) && seDiff > 0 && Math.abs(alphaRaw) >= 1.5 * seDiff;
      const alphaPts = Math.round(alphaShrunk * 100);
      const rateTxt = `Your taken picks hit ${Math.round(takenRate * 100)}% (${taken.hits}/${taken.settled}) against ${Math.round(skippedRate * 100)}% (${skipped.hits}/${skipped.settled}) for the board picks you passed on.`;
      const alphaChip = !conclusive
        ? `<span class="plg-alpha thin" title="${rateTxt} The gap is ${Math.round(alphaRaw * 100)}pts raw, but its standard error is ${Math.round(seDiff * 100)}pts — under 1.5 SE, so it is not distinguishable from no effect. On ${taken.settled} settled taken leg${taken.settled === 1 ? '' : 's'} this cannot yet tell you whether your selection helps or hurts, and the shown figure is Laplace-shrunk so a thin cohort cannot claim its extremes. Read it again around 30 taken legs.">ALPHA ${alphaPts >= 0 ? '+' : ''}${alphaPts}pts <i>±${Math.round(seDiff * 100)} · n=${taken.settled}</i></span>`
        : alphaPts >= 0
        ? `<span class="plg-alpha pos" title="${rateTxt} Your selection is adding ${alphaPts}pts over blind-following the board (Laplace-shrunk; ±${Math.round(seDiff * 100)}pts standard error on ${taken.settled} taken legs).">ALPHA +${alphaPts}pts</span>`
        : `<span class="plg-alpha neg" title="${rateTxt} The picks you skip are outhitting the ones you take by ${-alphaPts}pts (Laplace-shrunk; ±${Math.round(seDiff * 100)}pts standard error on ${taken.settled} taken legs).">ALPHA ${alphaPts}pts</span>`;
      const confNote = taken.confN && skipped.confN
        ? `<span class="plg-sel-conf" title="Average model confidence of the suggestions you take vs the ones you skip — a large gap here means you're selecting on confidence, a small one means you're selecting on something else">conf taken ${Math.round(taken.confSum / taken.confN)}% · skipped ${Math.round(skipped.confSum / skipped.confN)}%</span>`
        : '';
      return { html: `<div class="plg-selection">
        <span class="plg-sel-label">SELECTION</span>
        <span class="plg-sel-cohort">TAKEN <b>${taken.hits}/${taken.settled}</b> (${Math.round(takenRate * 100)}%)</span>
        <span class="plg-sel-cohort">SKIPPED <b>${skipped.hits}/${skipped.settled}</b> (${Math.round(skippedRate * 100)}%)</span>
        ${alphaChip}${confNote}
      </div>` };
    })();
    if (!events.length) {
      return { html: '<div class="inline-empty-msg" style="font-size:10px">No placed legs yet — check picks into My Slate on AI Best Picks and mark them ● PLACED</div>', settled: 0, hits: 0, total: 0, boardSettled: 0, boardHits: 0, updates: [] };
    }
    let boardSettledTotal = 0, boardHitsTotal = 0;
    const html = events.map(e => {
      const evSettled = e.legs.filter(l => l.outcome !== 'pending').length;
      const evHits = e.legs.filter(l => l.outcome === 'hit').length;
      // GLOW-UP 173: board baseline for this event — only meaningful once
      // something settled on either side.
      const board = boardStatsFor(eventDedupeKey(e.evKey));
      boardSettledTotal += board.settled;
      boardHitsTotal += board.hits;
      const youRate = evSettled ? evHits / evSettled : null;
      const boardRate = board.settled ? board.hits / board.settled : null;
      const boardChip = board.settled
        ? `<span class="plg-ev-record board" title="The board's full suggested slate for this event (latest snapshot), graded by the same resolver: ${board.hits}/${board.settled} hit">BOARD ${board.hits}/${board.settled}</span>`
        : '';
      const evSummary = evSettled
        ? `<span class="plg-ev-record ${youRate != null && (boardRate == null || youRate >= boardRate) ? 'good' : 'bad'}" title="Your placed legs for this event: ${evHits}/${evSettled} hit${boardRate != null ? ` · board baseline ${Math.round(boardRate * 100)}%` : ''}">YOU ${evHits}/${evSettled}</span>${boardChip}`
        : `<span class="plg-ev-record">all pending</span>${boardChip}`;
      // ── GLOW-UP 309 · your exposure is per FIGHT, and the ledger hid it ──────
      // Legs render in storage-key order, which reads alphabetically by fighter. So
      // Anthony Hernandez sits at row 1 and Gregory Rodrigues — the other half of
      // the same fight — at row 11, and the three legs you hold on one fight are
      // scattered down a 40-row list. Correlation is the whole reason to look at a
      // ledger rather than a bet slip, and this was the one view that could show it.
      // Sorted by fight, then by fighter so the order inside a group is stable.
      const fightKeyOf = (r: PlacedLedgerRec): string =>
        [String(r.name || '').toLowerCase(), String(r.opponent || '').toLowerCase()].sort().join('|');
      const fightCount = new Map<string, number>();
      for (const l of e.legs) { const k = fightKeyOf(l.rec); fightCount.set(k, (fightCount.get(k) || 0) + 1); }
      const sortedLegs = [...e.legs].sort((a, b) => {
        const ka = fightKeyOf(a.rec), kb = fightKeyOf(b.rec);
        if (ka !== kb) return ka < kb ? -1 : 1;
        return String(a.rec.name).localeCompare(String(b.rec.name));
      });
      let lastFight = '';
      // GLOW-UP 316: the design system defines --book-* and --stat-* hues and the
      // rest of the app uses them; both ledgers rendered every book and every stat
      // in the same grey. These map the stored keys onto the existing tokens — no
      // new colours, just the ones this codebase already committed to.
      const bookTone = (bk: string | null | undefined): string => {
        const k = String(bk || '').toLowerCase();
        return k === 'pick6' ? 'bk-p6'
          : k === 'underdog' ? 'bk-ud'
          : k === 'prizepicks' ? 'bk-pp'
          : k === 'betr' ? 'bk-betr'
          : k.startsWith('draftkings') || k === 'dk' ? 'bk-dk'
          : '';
      };
      const rows = sortedLegs.map((l, rowI) => {
        const r = l.rec;
        const fk = fightKeyOf(r);
        const nFight = fightCount.get(fk) || 1;
        const isGroupHead = fk !== lastFight;
        lastFight = fk;
        const unit = r.source === 'ft' ? 'm' : '';
        const status = l.outcome === 'hit'
          ? `<span class="plg-status hit" title="Settled: actual ${l.actual}${unit} vs line ${r.line} — your ${r.dir} hit">✓ HIT</span>`
          : l.outcome === 'miss'
          ? `<span class="plg-status miss" title="Settled: actual ${l.actual}${unit} vs line ${r.line} — your ${r.dir} missed">✗ MISS</span>`
          // GLOW-UP 308: when NOTHING in the event has settled, the event header
          // already says "all pending" and these repeat it once per row — on the live
          // card that is forty identical grey chips down the right edge, a column of
          // pure repetition where the settled events carry real results. Rendered
          // only when the event is mixed, i.e. when pending actually distinguishes
          // this leg from its neighbours.
          : evSettled > 0
          ? `<span class="plg-status pending" title="No settled archive result for this prop yet">○ PENDING</span>`
          : '';
        const actualHtml = l.actual != null
          ? `<span class="plg-actual">actual <b>${Math.round(l.actual * 10) / 10}${unit}</b></span>`
          : '';
        // ── GLOW-UP 311 · YOUR entry against the close, on the row ─────────────
        // The CLV panel above this reads ai_lean_snapshots — the BOARD's lines. On
        // 62% of placed legs that is not the line you took (Edson Barboza SS UNDER:
        // entered 63.5, board snapshot 32.5), so it never answered "did I get a good
        // price". This does, per leg, from the line actually stored on the record.
        //
        // Signed by direction so positive ALWAYS means the market moved your way:
        // an OVER wants the close ABOVE your entry, an UNDER wants it below. The
        // >20 bound is the existing sanity rule — a gap that large is a name or
        // platform mismatch, not real movement.
        const closeLn = closeLineFor(eventDedupeKey(e.evKey), r.name, propTypesFor(r.source, r.book));
        const entryLn = Number(r.line);
        let clvHtml = '';
        if (closeLn != null && Number.isFinite(entryLn)) {
          const delta = (r.dir === 'OVER' ? 1 : -1) * (closeLn - entryLn);
          if (Math.abs(delta) <= 20 && Math.abs(delta) >= 0.5) {
            const good = delta > 0;
            clvHtml = `<span class="plg-clv ${good ? 'pos' : 'neg'}" title="You entered at ${entryLn}${unit}; the line closed at ${closeLn}${unit}. ${good
              ? `The market moved TOWARD your side by ${Math.abs(delta).toFixed(1)} — you took a better price than the close.`
              : `The market moved AGAINST your side by ${Math.abs(delta).toFixed(1)} — the close was a better price than you got.`} This is your ACTUAL entry against the close; the CLV panel above measures the board's lines, which differ from yours on most legs.">${entryLn}→${closeLn} <b>${good ? '▲' : '▼'}${Math.abs(delta).toFixed(1)}</b></span>`;
          }
        }
        // GLOW-UP 309: the count rides the FIRST row of each group, so a fight you
        // are three legs deep on announces itself once instead of tagging every row.
        const groupTag = isGroupHead && nFight > 1
          ? `<i class="plg-fight-n" title="You hold ${nFight} legs on this one fight. They share a duration and a pace, so they are not independent — an early finish, or a slow round, moves all ${nFight} together.">${nFight} legs</i>`
          : '';
        // ── GLOW-UP 317 · the row becomes columns ────────────────────────────
        // Every field used to live inside one .plg-leg-main that flowed as a
        // sentence, so the line under a long name sat further right than the line
        // under a short one and nothing down 99 rows could be compared without
        // reading it. These are now direct grid children — the wrapper is gone,
        // because a grid cannot align what a flex wrapper has already laid out.
        //
        // The trailing three cells stay in the markup even when empty. That is the
        // point: a pending row and a settled row occupy the same columns, so the
        // ledger reads as one table rather than two shapes.
        return `<div class="plg-leg${nFight > 1 ? ' in-group' : ''}${isGroupHead ? ' group-head' : ''}" style="--plg-i:${Math.min(rowI, 28)}">
          <span class="plc-name">${r.pretty}</span>
          <b class="bps-dir ${r.dir === 'OVER' ? 'ov' : 'un'}">${r.dir}</b>
          <span class="bps-line">${r.line ?? '—'}</span>
          <i class="bps-stat st-${r.source}">${r.statLabel}</i>
          <span class="bps-vs">${r.opponent ? `vs ${r.opponent}` : ''}</span>
          <span class="plc-book-cell">${r.bookLabel ? `<span class="plg-book ${bookTone(r.book)}">${r.bookLabel}</span>` : ''}</span>
          <span class="plc-tag">${groupTag}</span>
          <span class="plc-clv">${clvHtml}</span>
          <span class="plc-actual">${actualHtml}</span>
          <span class="plc-status">${status}</span>
          <span class="plc-gap"></span>
        </div>`;
      }).join('');
      // One header per event rather than one for the whole ledger: the columns are
      // the same, but each event is its own scroll destination and a table you have
      // scrolled into needs its headings within reach.
      const colHead = `<div class="plg-leg plg-colhead">
        <span class="plc-name">FIGHTER</span><b class="bps-dir">SIDE</b><span class="bps-line">LINE</span>
        <i class="bps-stat">STAT</i><span class="bps-vs">OPPONENT</span><span class="plc-book-cell">BOOK</span>
        <span class="plc-tag"></span><span class="plc-clv">ENTRY → CLOSE</span>
        <span class="plc-actual">ACTUAL</span><span class="plc-status">RESULT</span><span class="plc-gap"></span>
      </div>`;
      return `<div class="plg-event"><div class="plg-ev-head"><span class="plg-ev-name">${e.evKey}</span>${evSummary}</div>${colHead}${rows}</div>`;
    }).join('');
    return { html: selection.html + html, settled, hits, total: flat.length, boardSettled: boardSettledTotal, boardHits: boardHitsTotal, updates };
  })();

  // GLOW-UP 174: write freshly settled outcomes back onto the placed records
  // — read-modify-write of the full store, fire-and-forget (a failed write
  // just means the same legs re-resolve from the archive next render).
  if (placedLedgerData.updates.length) {
    void (async () => {
      try {
        const payload = await storageGet<Record<string, unknown>>([STORAGE_BEST_PICKS_PLACED_KEY]);
        const raw = payload[STORAGE_BEST_PICKS_PLACED_KEY];
        const all: Record<string, Record<string, PlacedLedgerRec>> =
          raw && typeof raw === 'object' && !Array.isArray(raw)
            ? { ...(raw as Record<string, Record<string, PlacedLedgerRec>>) }
            : {};
        let changed = false;
        const now = Date.now();
        for (const u of placedLedgerData.updates) {
          const ev = all[u.evKey];
          if (!ev || !ev[u.legKey] || ev[u.legKey].outcome) continue;
          ev[u.legKey] = { ...ev[u.legKey], outcome: u.outcome, actual: u.actual, resolvedAt: now };
          changed = true;
        }
        if (changed) await storageSet({ [STORAGE_BEST_PICKS_PLACED_KEY]: all });
      } catch { /* best-effort — archive re-resolve covers a failed write */ }
    })();
  }
  // GLOW-UP 173: all-time roll-up in the section header — your settled hit
  // rate vs the board's, scoped to events where you actually placed legs.
  const placedLedgerSummary = ((): string => {
    if (!placedLedgerData.total) return `<span style="font-size:10px;color:var(--text-muted)">no placed legs yet</span>`;
    const you = placedLedgerData.settled
      ? `YOU ${placedLedgerData.hits}/${placedLedgerData.settled} (${Math.round((placedLedgerData.hits / placedLedgerData.settled) * 100)}%)`
      : 'none settled yet';
    const board = placedLedgerData.boardSettled
      ? ` · BOARD ${placedLedgerData.boardHits}/${placedLedgerData.boardSettled} (${Math.round((placedLedgerData.boardHits / placedLedgerData.boardSettled) * 100)}%)`
      : '';
    return `<span style="font-size:10px;color:var(--text-muted)">${placedLedgerData.total} leg${placedLedgerData.total === 1 ? '' : 's'} · ${you}${board}</span>`;
  })();

  // ── GLOW-UP 181: Parlay Ledger ─────────────────────────────────────────
  // Placed slips (parlay_placed_v1) resolved leg-by-leg through the same
  // resolver; a slip CASHES only if every leg hits (partial pick'em payouts
  // are noted but not modeled here — this is the all-or-nothing view).
  const parlayLedgerData = ((): { html: string; count: number; cashed: number; settled: number } => {
    const raw = result[STORAGE_PARLAY_PLACED_KEY];
    const all = raw && typeof raw === 'object' && !Array.isArray(raw) ? (raw as Record<string, PlacedParlay[]>) : {};
    const evs = Object.entries(all)
      .map(([evKey, list]) => ({ evKey, list: Array.isArray(list) ? list : [] }))
      .filter(e => e.list.length);
    if (!evs.length) {
      return { html: '<div class="inline-empty-msg" style="font-size:10px">No placed parlays yet — build a slip in Parlay Lab and hit ● PLACE PARLAY</div>', count: 0, cashed: 0, settled: 0 };
    }
    evs.sort((a, b) => Math.max(0, ...b.list.map(p => p.placedAt || 0)) - Math.max(0, ...a.list.map(p => p.placedAt || 0)));
    let count = 0, cashed = 0, settledSlips = 0;
    const html = evs.map(e => {
      const evDk = eventDedupeKey(e.evKey);
      // ── GLOW-UP 305/306 · slips are not independent, and the ledger said nothing
      // Two facts live ACROSS slips, so no per-slip renderer could ever surface
      // them, and this ledger only ever rendered one slip at a time:
      //
      //  1. CONTAINMENT. On the live card the 4-leg Betr slip's legs are all four
      //     inside the 7-leg Betr slip. That is not two bets — it is one bet plus a
      //     rider. Every leg that busts the small one busts the big one too, so the
      //     "diversification" of holding both is entirely illusory.
      //  2. SHARED LEGS. Vitor Petrino OVER 73.5 FP sits in three separate slips.
      //     One prop missing takes all three down, and nothing on screen said so.
      //
      // Both are computed once per event, before any card renders.
      const legKeyOf = (l: { fighter?: string; dir?: string; line?: number | null; stat?: string }): string =>
        `${String(l.fighter || '').toLowerCase()}|${l.dir}|${l.line}|${l.stat}`;
      const slipSets = e.list.map(p => new Set((p.legs || []).map(legKeyOf)));
      const legSlipCount = new Map<string, number>();
      for (const set of slipSets) for (const k of set) legSlipCount.set(k, (legSlipCount.get(k) || 0) + 1);
      // Strictly smaller AND fully contained. Equal-size duplicates are a different
      // problem (the same slip placed twice) and would report each as inside the other.
      const insideOf = slipSets.map((set, i) => {
        for (let j = 0; j < slipSets.length; j++) {
          if (i === j) continue;
          const other = slipSets[j]!;
          if (set.size < other.size && [...set].every(k => other.has(k))) return j;
        }
        return -1;
      });
      const containsIdx = slipSets.map((_, i) => insideOf.reduce<number[]>((a, v, j) => (v === i ? [...a, j] : a), []));
      const cards = e.list.map((p, pi) => {
        count++;
        const cardI = Math.min(pi, 20);
        const legs = (p.legs || []).map(l => {
          const dir = l.dir === 'OVER' ? 'over' as const : 'under' as const;
          const res = resolveVsArchive(evDk, l.fighter, propTypesFor(l.stat, l.book), l.line, dir);
          return { l, outcome: res.outcome };
        });
        const settledN = legs.filter(x => x.outcome !== 'pending').length;
        const hitN = legs.filter(x => x.outcome === 'hit').length;
        const anyPending = legs.some(x => x.outcome === 'pending');
        const anyMiss = legs.some(x => x.outcome === 'miss');
        if (!anyPending) { settledSlips++; if (!anyMiss) cashed++; }
        const statusChip = anyPending
          ? `<span class="plg-status pending" title="${legs.length - settledN} leg(s) not settled yet">○ ${settledN}/${legs.length} SETTLED</span>`
          : anyMiss
          // GLOW-UP 307: a slip one leg from cashing and a slip that missed
          // everything both read "✗ BUST" in the same weight. The near miss is the
          // more informative outcome of the two — it says the read was right and the
          // slip was too long — so it now says so and is toned back from the full
          // bust rather than shouting equally.
          ? `<span class="plg-status miss${legs.length - hitN === 1 ? ' near' : ''}" title="${legs.length - hitN} leg(s) missed — the full slip busts (in-app partial pick'em payouts may still apply).${legs.length - hitN === 1 ? ` ONE leg away: ${hitN} of ${legs.length} landed. The read was right and the slip was one leg too long — worth checking whether that leg was the one you were least sure of.` : ''}">✗ BUST ${hitN}/${legs.length}${legs.length - hitN === 1 ? ' <i>1 away</i>' : ''}</span>`
          : `<span class="plg-status hit" title="All ${legs.length} legs hit — slip cashes">✓ CASH ${hitN}/${legs.length}</span>`;
        const legRows = legs.map(x => {
          const st = x.outcome === 'hit' ? '<span class="plp-mini hit">✓</span>' : x.outcome === 'miss' ? '<span class="plp-mini miss">✗</span>' : '<span class="plp-mini pending">○</span>';
          // GLOW-UP 306: this exact leg also carries other slips. Marked ON the leg
          // rather than only summarised on the header, because when you are reading
          // down a slip deciding what hurt, the shared one is the row that matters.
          const shared = legSlipCount.get(legKeyOf(x.l)) || 1;
          const sharedTag = shared > 1
            ? `<i class="plp-shared" title="This same leg is in ${shared} of your slips for this event. They are not independent bets — if this prop misses, all ${shared} die together.">×${shared}</i>`
            : '';
          return `<span class="plp-leg${shared > 1 ? ' is-shared' : ''}">${st} ${prettyName(x.l.fighter)} <b class="bps-dir ${x.l.dir === 'OVER' ? 'ov' : 'un'}">${x.l.dir}</b> <span class="bps-line">${x.l.line ?? '—'}</span> <i class="bps-stat st-${x.l.stat}">${x.l.statLabel}</i>${sharedTag}</span>`;
        }).join('');
        // Plain-text summary for the confirm dialog — the user should see exactly
        // which slip they are about to drop, not just "this parlay".
        const legSummary = (p.legs || [])
          .map(l => `${prettyName(l.fighter)} ${l.dir} ${l.line ?? '—'} ${l.statLabel}`)
          .join('  +  ');
        const esc = (x: string): string => String(x).replace(/"/g, '&quot;');
        const removeBtn = `<button class="plp-remove" data-plp-ev="${esc(e.evKey)}" data-plp-id="${esc(String(p.id))}" data-plp-sum="${esc(legSummary)}" title="Remove this parlay from the ledger — use when the book voided it (a fight falling off the card) or it was placed by mistake. Re-place from Parlay Lab if needed.">✕</button>`;
        // GLOW-UP 305: the containment badge. Deliberately on BOTH slips — from the
        // small one you need to know it buys you nothing the big one didn't already
        // have; from the big one you need to know a second slip dies with it.
        const inIdx = insideOf[pi] ?? -1;
        const holds = containsIdx[pi] || [];
        const containTag = inIdx >= 0
          ? `<span class="plp-contain inside" title="Every leg of this slip is also in your ${e.list[inIdx]?.legs.length}-leg slip. These are not two independent bets — anything that busts this one busts that one too, so holding both concentrates the same position rather than spreading it.">⊂ INSIDE ${e.list[inIdx]?.legs.length}-LEG</span>`
          : holds.length
          ? `<span class="plp-contain holds" title="${holds.length} smaller slip${holds.length === 1 ? '' : 's'} (${holds.map(j => `${e.list[j]?.legs.length}-leg`).join(', ')}) sit entirely inside this one — they cannot cash unless this one's shared legs do, so they add exposure to the same position rather than diversifying it.">⊃ HOLDS ${holds.length}</span>`
          : '';
        return `<div class="plp-parlay${inIdx >= 0 ? ' is-inside' : ''}" style="--plg-i:${cardI}"><div class="plp-head"><span class="plp-title">${p.legs.length}-LEG</span>${p.legs[0]?.bookLabel ? `<span class="plp-book ${(() => { const k = String(p.legs[0]?.book || '').toLowerCase(); return k === 'pick6' ? 'bk-p6' : k === 'underdog' ? 'bk-ud' : k === 'prizepicks' ? 'bk-pp' : k === 'betr' ? 'bk-betr' : k.startsWith('draftkings') || k === 'dk' ? 'bk-dk' : ''; })()}">${p.legs[0].bookLabel}</span>` : ''}${containTag}${statusChip}${removeBtn}</div><div class="plp-legs">${legRows}</div></div>`;
      }).join('');
      return `<div class="plg-event"><div class="plg-ev-head"><span class="plg-ev-name">${e.evKey}</span><span class="plg-ev-record">${e.list.length} parlay${e.list.length === 1 ? '' : 's'}</span></div>${cards}</div>`;
    }).join('');
    return { html, count, cashed, settled: settledSlips };
  })();
  const parlayLedgerSummary = parlayLedgerData.count
    ? `<span style="font-size:10px;color:var(--text-muted)">${parlayLedgerData.count} parlay${parlayLedgerData.count === 1 ? '' : 's'} · ${parlayLedgerData.settled ? `${parlayLedgerData.cashed}/${parlayLedgerData.settled} cashed` : 'none settled yet'}</span>`
    : `<span style="font-size:10px;color:var(--text-muted)">no placed parlays yet</span>`;

  // ── Per-event breakdown ────────────────────────────────────────────────
  // key = dedup key, value includes display name, date, and counts
  const ONE_DAY_MS = 24 * 60 * 60 * 1000;
  type BiggestMover = { fighter: string; propType: string; platform: string; openLine: number; line: number; delta: number };
  const eventMap = new Map<string, { display: string; date: number; hits: number; total: number; unresolved: number; recordCount: number; clvMoved: number; clvTracked: number; clvAbsSum: number; biggestMover: BiggestMover | null }>();
  for (const r of allRows.filter(r => Number.isFinite(Date.parse(r.date)) && Date.parse(r.date) >= londonTs)) {
    const ev = r.event || 'Unknown';
    const key = eventDedupeKey(ev);
    const rDate = Date.parse(r.date);
    const bucket = eventMap.get(key) || { display: ev, date: rDate, hits: 0, total: 0, unresolved: 0, recordCount: 0, clvMoved: 0, clvTracked: 0, clvAbsSum: 0, biggestMover: null as BiggestMover | null };
    // Prefer the longer, more descriptive event name as display name
    if (ev.length > bucket.display.length) bucket.display = ev;
    // Track earliest record date for this event
    if (rDate < bucket.date) bucket.date = rDate;
    bucket.recordCount++;
    if (Number.isFinite(Number(r.line)) && Number.isFinite(Number(r.result))) {
      bucket.total++;
      if (normalizeArchiveResult(String(r.propType), Number(r.result)) > Number(r.line)) bucket.hits++;
    } else if (Number.isFinite(Number(r.line))) {
      bucket.unresolved++;
    }
    // Market CLV: capture line drift when openLine and line both present.
    const openLine = Number(r.openLine);
    const closeLine = Number(r.line);
    if (Number.isFinite(openLine) && Number.isFinite(closeLine)) {
      bucket.clvTracked++;
      const delta = closeLine - openLine;
      if (delta !== 0) {
        bucket.clvMoved++;
        bucket.clvAbsSum += Math.abs(delta);
        if (!bucket.biggestMover || Math.abs(delta) > Math.abs(bucket.biggestMover.delta)) {
          bucket.biggestMover = {
            fighter: r.fighter,
            propType: String(r.propType),
            platform: String(r.platform || ''),
            openLine,
            line: closeLine,
            delta,
          };
        }
      }
    }
    eventMap.set(key, bucket);
  }

  // Note: eventDedupeKey already handles reversed-name duplicates (e.g. "Grasso vs Barber" ↔
  // "Barber vs Grasso") by sorting surnames — no extra date-proximity merge needed.

  // ── AI lean snapshot accuracy per event ───────────────────────────────
  const aiSnapshotPayload = await storageGet<Record<string, unknown>>([STORAGE_AI_LEAN_SNAPSHOT_KEY]);
  const aiSnapshots: any[] = Array.isArray(aiSnapshotPayload[STORAGE_AI_LEAN_SNAPSHOT_KEY])
    ? (aiSnapshotPayload[STORAGE_AI_LEAN_SNAPSHOT_KEY] as any[])
    : [];

  // See collapseSnapshotsByEvent: the raw list is one snapshot PER DAY, not per event.
  // Every panel below wants one observation per fighter+stat, never one per day survived.
  const aiSnapsFinal = collapseSnapshotsByEvent(aiSnapshots, eventDedupeKey, 'latest');
  const aiSnapsFirst = collapseSnapshotsByEvent(aiSnapshots, eventDedupeKey, 'earliest');

  // Returns { hits, total } for AI picks in a snapshot cross-referenced against archive rows for the same event.
  function computeAiAccuracy(snap: any, eventArchiveRows: PropArchiveRecord[]): { hits: number; total: number } {
    let hits = 0;
    let total = 0;
    for (const pick of (snap?.picks ?? []) as any[]) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '');
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine)) continue;
      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.result))
        )
        .sort((a, b) => {
          const aPlatformPenalty = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPlatformPenalty = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPlatformPenalty !== bPlatformPenalty) return aPlatformPenalty - bPlatformPenalty;
          return Math.abs(Number(a.line ?? activeLine) - activeLine) - Math.abs(Number(b.line ?? activeLine) - activeLine);
        })[0];
      if (!match) continue;
      total++;
      const res = Number(match.result);
      if (lean === 'over' && res > activeLine) hits++;
      if (lean === 'under' && res < activeLine) hits++;
    }
    return { hits, total };
  }

  // Map dedup key → best AI accuracy for that event
  const aiAccuracyMap = new Map<string, { hits: number; total: number }>();
  for (const snap of aiSnapsFinal) {
    const key = eventDedupeKey(String(snap?.event || ''));
    if (!key || aiAccuracyMap.has(key)) continue;
    const eventArchiveRows = rowsForEvent(key);
    const acc = computeAiAccuracy(snap, eventArchiveRows);
    if (acc.total > 0) aiAccuracyMap.set(key, acc);
  }

  // Returns { aligned, total } for AI picks whose lean direction matches market drift.
  // aligned: lean='over' && delta>0, or lean='under' && delta<0. Zero-drift excluded.
  function computeAiClvAgreement(snap: any, eventArchiveRows: PropArchiveRecord[]): { aligned: number; total: number } {
    let aligned = 0;
    let total = 0;
    for (const pick of (snap?.picks ?? []) as any[]) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '');
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under')) continue;
      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.openLine)) &&
          Number.isFinite(Number(r.line))
        )
        .sort((a, b) => {
          const aPlatformPenalty = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPlatformPenalty = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPlatformPenalty !== bPlatformPenalty) return aPlatformPenalty - bPlatformPenalty;
          if (!Number.isFinite(activeLine)) return 0;
          return Math.abs(Number(a.line) - activeLine) - Math.abs(Number(b.line) - activeLine);
        })[0];
      if (!match) continue;
      const delta = Number(match.line) - Number(match.openLine);
      if (delta === 0) continue;
      total++;
      if (lean === 'over' && delta > 0) aligned++;
      if (lean === 'under' && delta < 0) aligned++;
    }
    return { aligned, total };
  }

  // Map dedup key → AI × CLV agreement for that event
  const aiClvAgreementMap = new Map<string, { aligned: number; total: number }>();
  // First-seen: agreement asks whether the model called the line MOVE, which needs the
  // line as it stood when the model first spoke, not one taken after the move happened.
  for (const snap of aiSnapsFirst) {
    const key = eventDedupeKey(String(snap?.event || ''));
    if (!key || aiClvAgreementMap.has(key)) continue;
    const eventArchiveRows = rowsForEvent(key);
    const agg = computeAiClvAgreement(snap, eventArchiveRows);
    if (agg.total > 0) aiClvAgreementMap.set(key, agg);
  }

  // Split into past events (show results) and upcoming (show as pending only)
  const pastEventRows = Array.from(eventMap.values())
    .filter(d => d.date <= nowTs || d.total > 0) // treat settled events as past regardless of date
    .sort((a, b) => b.date - a.date)
    .slice(0, 6);
  const upcomingEvents = Array.from(eventMap.values())
    .filter(d => d.date > nowTs && d.total === 0);

  // Only count resolved rows from past events for stats
  const pastEventKeys = new Set(
    Array.from(eventMap.entries())
      .filter(([, d]) => d.date <= nowTs)
      .map(([k]) => k)
  );
  const resolvedRows = allRows.filter(r =>
    Number.isFinite(Number(r.line)) && Number.isFinite(Number(r.result)) &&
    Number.isFinite(Date.parse(r.date)) && Date.parse(r.date) >= londonTs &&
    pastEventKeys.has(eventDedupeKey(r.event || ''))
  );
  const unresolvedCount = allRows.filter(r =>
    Number.isFinite(Number(r.line)) && !Number.isFinite(Number(r.result))
  ).length;

  // ── Pending outcomes — past events with unresolved props ─────────────────
  // Build per-event pending breakdowns (propType counts) for the settlement banner
  type PendingEvent = { display: string; total: number; byType: Record<string, number> };
  const upcomingKey = eventDedupeKey(upcomingEventName || '');
  const pendingEventMap = new Map<string, PendingEvent>();
  for (const r of allRows) {
    if (!Number.isFinite(Number(r.line)) || Number.isFinite(Number(r.result))) continue;
    const key = eventDedupeKey(r.event || '');
    const evData = eventMap.get(key);
    if (!evData) continue;
    // ── GLOW-UP 343 · the banner asked to settle a fight that has not happened ──
    // The guard below intends "past events only", and could never achieve it:
    // evData.date is the ARCHIVE RECORD's date — when the prop was written — not
    // when the fight is. Lines for an upcoming card are archived the moment they
    // post, so `date` is ~now and `date > nowTs` is false. On 2026-08-25 that put
    // "⏳ AWAITING SETTLEMENT — 23 props · UFC Fight Night: Nurmagomedov vs. Song"
    // on screen with a SETTLE NOW button, for a card still days away.
    //
    // pastEventKeys is built from the same field, so it carries the same flaw and
    // could not be used to fix this. The upcoming card's NAME is the one
    // unambiguous signal available, so it is excluded explicitly.
    if (upcomingKey && key === upcomingKey) continue;
    if (evData.date > nowTs && evData.total === 0) continue;
    const p = pendingEventMap.get(key) || { display: evData.display, total: 0, byType: {} };
    p.total++;
    const pt = String(r.propType || 'Unknown');
    p.byType[pt] = (p.byType[pt] || 0) + 1;
    pendingEventMap.set(key, p);
  }
  const pendingEvents = Array.from(pendingEventMap.values()).sort((a, b) => b.total - a.total);

  // ── AI pick accuracy by stat type (lean-direction correct, over + under) ──
  const aiAccuracyByType: Record<string, { hits: number; total: number; overHits: number; overTotal: number; underHits: number; underTotal: number }> = {};
  for (const snap of aiSnapsFinal) {
    const key = eventDedupeKey(String(snap?.event || ''));
    if (!key || !pastEventKeys.has(key)) continue;
    const eventArchiveRows = rowsForEvent(key);
    for (const pick of (snap?.picks ?? []) as any[]) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '');
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine)) continue;
      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.result))
        )
        .sort((a, b) => {
          const aPlatformPenalty = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPlatformPenalty = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPlatformPenalty !== bPlatformPenalty) return aPlatformPenalty - bPlatformPenalty;
          return Math.abs(Number(a.line ?? activeLine) - activeLine) - Math.abs(Number(b.line ?? activeLine) - activeLine);
        })[0];
      if (!match) continue;
      if (!aiAccuracyByType[propType]) aiAccuracyByType[propType] = { hits: 0, total: 0, overHits: 0, overTotal: 0, underHits: 0, underTotal: 0 };
      const bucket = aiAccuracyByType[propType];
      bucket.total++;
      const res = Number(match.result);
      const dirHit = lean === 'over' ? res > activeLine : res < activeLine;
      if (dirHit) bucket.hits++;
      if (lean === 'over') { bucket.overTotal++; if (dirHit) bucket.overHits++; }
      else { bucket.underTotal++; if (dirHit) bucket.underHits++; }
    }
  }

  // ── Entry-vs-close CLV (per-source) ────────────────────────────────────
  // For each AI pick, compare activeLine (entry) to match.line (close).
  // CLV for OVER = closeLine - entryLine (we want close to rise);
  // CLV for UNDER = entryLine - closeLine (we want close to fall).
  // Unlike aiAccuracyByType, CLV doesn't require a settled result — only a
  // closing line — so pending past-event picks still contribute.
  type EntryClvBucket = {
    picks: number; clvSum: number; clvPosCount: number; hitCount: number; resolvedCount: number;
    // CLV × outcome cross: does beating the close actually predict winning?
    posHit: number; posResolved: number; nonPosHit: number; nonPosResolved: number;
  };
  const entryClvByType: Record<string, EntryClvBucket> = {};
  // First-seen deliberately - see collapseSnapshotsByEvent.
  for (const snap of aiSnapsFirst) {
    const key = eventDedupeKey(String(snap?.event || ''));
    if (!key || !pastEventKeys.has(key)) continue;
    const eventArchiveRows = rowsForEvent(key);
    for (const pick of (snap?.picks ?? []) as any[]) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '');
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine)) continue;
      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.line))
        )
        .sort((a, b) => {
          const aP = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bP = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aP !== bP) return aP - bP;
          return Math.abs(Number(a.line) - activeLine) - Math.abs(Number(b.line) - activeLine);
        })[0];
      if (!match) continue;
      const closeLine = Number(match.line);
      if (!Number.isFinite(closeLine)) continue;
      // Sanity-bound: a gap > 20 units is almost certainly a name/platform mismatch, not real CLV.
      const raw = (lean === 'over' ? 1 : -1) * (closeLine - activeLine);
      if (Math.abs(raw) > 20) continue;
      if (!entryClvByType[propType]) entryClvByType[propType] = { picks: 0, clvSum: 0, clvPosCount: 0, hitCount: 0, resolvedCount: 0, posHit: 0, posResolved: 0, nonPosHit: 0, nonPosResolved: 0 };
      const b = entryClvByType[propType];
      b.picks++;
      b.clvSum += raw;
      if (raw > 0) b.clvPosCount++;
      const res = Number(match.result);
      if (Number.isFinite(res)) {
        b.resolvedCount++;
        const hit = lean === 'over' ? res > activeLine : res < activeLine;
        if (hit) b.hitCount++;
        if (raw > 0) { b.posResolved++; if (hit) b.posHit++; }
        else { b.nonPosResolved++; if (hit) b.nonPosHit++; }
      }
    }
  }

  // ── Fantasy hit rate ───────────────────────────────────────────────────
  /**
   * ONE ENTRY PER FIGHTER PER FIGHT — not per posted line.
   *
   * These leaderboards counted archive ROWS and labelled them "events". A fighter's
   * SS line is posted by up to five books, and a card can sit under two event-name
   * variants, so a single performance was counted up to ten times. Bilal Hasan's UFC
   * DEBUT rendered as "9 events · 9/9 over"; Islam Makhachev's one fight as "7 events
   * · 7/7"; Gauge Young's two fights as "14 events". Measured inflation across the
   * archive: SS 4.67x, TD 2.31x, FP 1.80x.
   *
   * The ranking was the real casualty. Sorting on that count ordered fighters by HOW
   * MANY BOOKS HAPPENED TO COVER THEM rather than by track record — Gauge Young sat
   * above Bilal Hasan purely on coverage, when deduped they are 2/2 and 1/1.
   *
   * Keyed on fighter + DATE, because a fighter has at most one bout per day and the
   * date is immune to the duplicate event-name shadow rows that inflate a name count
   * (Gauge Young: 4 event names across 2 dates).
   *
   * Within a fight the books disagree on the line, so the outcome is decided against
   * their MEDIAN — the consensus number — rather than counting each book separately.
   * That matters: 22 SS fights had books split, and those are exactly the ones where
   * counting rows inflated a rate (Rei Tsuruya SS read 7/10 = 70%, truly 1/2 = 50%).
   *
   * Fantasy_PP is dropped when a shared-scale Fantasy row exists for the same fight —
   * PrizePicks scores fantasy on a different formula, so the two are not one sample.
   */
  const perFightHitRates = (rows: typeof resolvedRows): Map<string, { hits: number; total: number }> => {
    const median = (xs: number[]): number => {
      const a = [...xs].sort((x, y) => x - y);
      const m = a.length >> 1;
      return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2;
    };
    type Grp = { fighter: string; propType: string; lines: number[]; result: number };
    const groups = new Map<string, Grp>();
    for (const r of rows) {
      const line = Number(r.line), result = Number(r.result);
      if (!Number.isFinite(line) || !Number.isFinite(result)) continue;
      const fighter = normalizeName(r.fighter) || String(r.fighter);
      const date = String(r.date || "").slice(0, 10);
      if (!fighter || !date) continue;
      const k = `${fighter}|${date}|${String(r.propType)}`;
      const g = groups.get(k);
      if (g) g.lines.push(line);
      else groups.set(k, { fighter, propType: String(r.propType), lines: [line], result });
    }
    // Collapse to one group per fighter+fight, preferring the shared-scale propType.
    const perFight = new Map<string, Grp>();
    for (const [k, g] of groups) {
      const fightKey = k.slice(0, k.lastIndexOf("|"));
      const prev = perFight.get(fightKey);
      if (!prev || (prev.propType.endsWith("_PP") && !g.propType.endsWith("_PP"))) perFight.set(fightKey, g);
    }
    const out = new Map<string, { hits: number; total: number }>();
    for (const g of perFight.values()) {
      const e = out.get(g.fighter) || { hits: 0, total: 0 };
      e.total++;
      if (g.result > median(g.lines)) e.hits++;
      out.set(g.fighter, e);
    }
    return out;
  };
  const sumRates = (m: Map<string, { hits: number; total: number }>) => {
    let hits = 0, total = 0;
    for (const v of m.values()) { hits += v.hits; total += v.total; }
    return { hits, total };
  };

  const fantasyRows = resolvedRows.filter(r => r.propType === 'Fantasy' || r.propType === 'Fantasy_PP');
  const fighterFantasy = perFightHitRates(fantasyRows);
  const _fpAgg = sumRates(fighterFantasy);
  const fantasyHits = _fpAgg.hits;
  const fantasyTotal = _fpAgg.total;
  const fantasyHitRate = fantasyTotal ? Math.round((fantasyHits / fantasyTotal) * 100) : 0;
  const topFantasy = Array.from(fighterFantasy.entries())
    .filter(([fighter, v]) => v.total >= 2 && rosterFilter(fighter))
    .map(([fighter, v]) => ({ fighter, rate: Math.round((v.hits / v.total) * 100), total: v.total }))
    .sort((a, b) => b.rate - a.rate || b.total - a.total)
    .slice(0, 8);

  // ── SS per-fighter hit rates ───────────────────────────────────────────
  const ssRows = resolvedRows.filter(r => String(r.propType) === 'SS');
  const fighterSS = perFightHitRates(ssRows);
  const _ssAgg = sumRates(fighterSS);
  const topSS = Array.from(fighterSS.entries())
    .filter(([fighter, v]) => v.total >= 2 && rosterFilter(fighter))
    .map(([fighter, v]) => ({ fighter, rate: Math.round((v.hits / v.total) * 100), total: v.total }))
    .sort((a, b) => b.rate - a.rate || b.total - a.total)
    .slice(0, 8);
  const ssHits = _ssAgg.hits;
  const ssTotal = _ssAgg.total;

  // ── TD per-fighter hit rates ───────────────────────────────────────────
  const tdRows = resolvedRows.filter(r => String(r.propType) === 'TD');
  const fighterTD = perFightHitRates(tdRows);
  const _tdAgg = sumRates(fighterTD);
  const tdTotal = _tdAgg.total;
  const topTD = Array.from(fighterTD.entries())
    .filter(([fighter, v]) => v.total >= 2 && rosterFilter(fighter))
    .map(([fighter, v]) => ({ fighter, rate: Math.round((v.hits / v.total) * 100), total: v.total }))
    .sort((a, b) => b.rate - a.rate || b.total - a.total)
    .slice(0, 8);
  // Per-fight, like the total beside it. Left as a row count this reported 195 hits
  // against a 281-fight denominator — two different populations in one fraction.
  const tdHits = _tdAgg.hits;

  // ── FightTime hit rate ────────────────────────────────────────────────
  const ftRows = resolvedRows.filter(r => String(r.propType) === 'FightTime');
  const ftHits = ftRows.filter(r => normalizeArchiveResult('FightTime', Number(r.result)) > Number(r.line)).length;

  // ── Per-platform summary (all prop types combined) ────────────────────
  // Deduped: this is the aggregation the Platform Bias panel actually renders.
  const platSummary = new Map<string, { hits: number; total: number; edgeSum: number }>();
  for (const r of dedupeBiasRows(resolvedRows.filter(r => !!r.platform))) {
    const key = String(r.platform).toLowerCase();
    const b = platSummary.get(key) || { hits: 0, total: 0, edgeSum: 0 };
    const normResult = normalizeArchiveResult(String(r.propType), Number(r.result));
    b.total++;
    b.edgeSum += normResult - Number(r.line);
    if (normResult > Number(r.line)) b.hits++;
    platSummary.set(key, b);
  }

  // ── Platform bias ──────────────────────────────────────────────────────
  const biasMap = new Map<string, { platform: string; propType: string; hits: number; total: number; edgeSum: number }>();
  for (const r of dedupeBiasRows(resolvedRows.filter(r => !!r.platform))) {
    const key = `${String(r.platform).toLowerCase()}|${r.propType}`;
    const b = biasMap.get(key) || { platform: String(r.platform).toLowerCase(), propType: String(r.propType), hits: 0, total: 0, edgeSum: 0 };
    const normResult = normalizeArchiveResult(String(r.propType), Number(r.result));
    b.total++;
    b.edgeSum += normResult - Number(r.line);
    if (normResult > Number(r.line)) b.hits++;
    biasMap.set(key, b);
  }
  const biasRows = Array.from(biasMap.values())
    .filter(b => b.total >= 2)
    .map(b => ({ ...b, hitRate: Math.round((b.hits / b.total) * 100), avgEdge: Number((b.edgeSum / b.total).toFixed(1)) }))
    .sort((a, b) => Math.abs(b.avgEdge) - Math.abs(a.avgEdge) || b.total - a.total)
    .slice(0, 14);

  // ── HTML ───────────────────────────────────────────────────────────────
  const deleteBtn = (eventName: string) =>
    `<button class="archive-delete-event-btn" data-event="${eventName.replace(/"/g, '&quot;')}" title="Delete all records for this event" style="margin-left:auto;background:none;border:none;cursor:pointer;color:var(--text-muted);font-size:13px;padding:0 4px;line-height:1">✕</button>`;

  const upcomingHtml = upcomingEvents
    .filter(d => d.unresolved > 0 || d.total > 0) // hide empty shell events
    .map(d =>
      `<div class="event-row" style="opacity:0.6">
        <div class="event-pct" style="font-size:9px;color:var(--text-muted)">SOON</div>
        <div style="flex:1"><div class="best-pick-name" style="font-size:12px">${d.display}</div><div class="evr-chips"><span class="evr-chip pending">${d.unresolved} LINES ARCHIVED · AWAITING RESULTS</span></div></div>
        ${deleteBtn(d.display)}
      </div>`
    ).join('');

  const eventHtml = (pastEventRows.length || upcomingHtml)
    ? upcomingHtml + pastEventRows.map((d) => {
        const key = eventDedupeKey(d.display);
        const rate = d.total ? Math.round((d.hits / d.total) * 100) : null;
        const ai = aiAccuracyMap.get(key);
        const aiRate = ai ? Math.round((ai.hits / ai.total) * 100) : null;
        // AI pick accuracy is the real per-event scoreboard — promote it from
        // buried mid-sentence text to a graded badge beside the event name.
        const aiBadge = ai
          ? `<span class="evr-ai ${aiRate! >= 60 ? 'good' : aiRate! >= 45 ? 'mid' : 'bad'}" title="AI pick accuracy this event: ${ai.hits}/${ai.total} lean directions correct">AI ${aiRate}%</span>`
          : '';
        const chips: string[] = [];
        chips.push(`<span class="evr-chip" title="Market overs rate — share of all archived lines that settled OVER">OVERS ${d.hits}/${d.total}</span>`);
        if (d.unresolved > 0) chips.push(`<span class="evr-chip pending">${d.unresolved} PENDING</span>`);
        if (d.clvTracked > 0) {
          const avgAbs = d.clvMoved > 0 ? (d.clvAbsSum / d.clvMoved).toFixed(2) : '0.00';
          chips.push(`<span class="evr-chip" title="Closing-line value: how many lines moved from open, and the average absolute move">CLV ${d.clvMoved}/${d.clvTracked} · |Δ| ${avgAbs}</span>`);
          const agreement = aiClvAgreementMap.get(key);
          if (agreement) {
            const pct = Math.round((agreement.aligned / agreement.total) * 100);
            chips.push(`<span class="evr-chip agree ${pct >= 60 ? 'good' : pct >= 40 ? 'mid' : 'bad'}" title="How often the AI lean direction matched the market's line movement (${agreement.aligned}/${agreement.total})">AI×CLV ${pct}%</span>`);
          }
          const bm = d.biggestMover;
          if (bm) {
            chips.push(`<span class="evr-chip mover" title="Biggest line move of the event">⚡ ${bm.fighter} ${bm.propType} ${bm.openLine}→${bm.line} (${bm.delta > 0 ? '+' : ''}${bm.delta.toFixed(1)})</span>`);
          }
        }
        return `<div class="event-row">
          <div class="event-pct" style="color:${rate === null ? 'var(--text3)' : rate >= 60 ? 'var(--green)' : rate >= 40 ? 'var(--gold)' : 'var(--red)'}">${rate !== null ? rate + '%' : '—'}</div>
          <div style="flex:1;min-width:0"><div class="best-pick-name" style="font-size:12px">${d.display}${aiBadge}</div><div class="evr-chips">${chips.join('')}</div></div>
          ${deleteBtn(d.display)}
        </div>`;
      }).join('')
    : '<div class="inline-empty-msg">No event data yet</div>';

  const topFantasyHtml = topFantasy.length
    ? topFantasy.map(x => `<div class="best-pick-row">
          <div class="best-pick-rank">${x.rate}%</div>
          <div><div class="best-pick-name">${prettyName(x.fighter)}</div><div class="best-pick-reason">${x.total} events · ${Math.round(x.rate / 100 * x.total)}/${x.total} over</div></div>
          <div class="best-pick-meta"><span class="best-pick-platform">Fantasy</span></div>
          <div class="best-pick-line">${x.total} events</div>
        </div>`).join('')
    : `<div class="rate-hero"><div class="rate-hero-num" style="color:${fantasyHitRate >= 50 ? 'var(--green)' : fantasyHitRate >= 35 ? 'var(--gold)' : 'var(--red)'}">${fantasyHitRate}%</div><div class="rate-hero-bar"><span style="width:${Math.max(2, Math.min(100, fantasyHitRate))}%;background:${fantasyHitRate >= 50 ? 'var(--green)' : fantasyHitRate >= 35 ? 'var(--gold)' : 'var(--red)'}"></span></div><div class="rate-hero-sub">${fantasyHits}/${fantasyTotal} hit on current roster · per-fighter breakdown needs 2+ events each</div></div>`;

  const topSSHtml = topSS.length
    ? topSS.map(x => `<div class="best-pick-row">
          <div class="best-pick-rank">${x.rate}%</div>
          <div><div class="best-pick-name">${prettyName(x.fighter)}</div><div class="best-pick-reason">${x.total} events · ${Math.round(x.rate / 100 * x.total)}/${x.total} over</div></div>
          <div class="best-pick-meta"><span class="best-pick-platform">SS</span></div>
          <div class="best-pick-line">${x.total} events</div>
        </div>`).join('')
    : `<div class="rate-hero"><div class="rate-hero-num" style="color:${Math.round(ssHits / Math.max(1, ssTotal) * 100) >= 50 ? 'var(--green)' : Math.round(ssHits / Math.max(1, ssTotal) * 100) >= 35 ? 'var(--gold)' : 'var(--red)'}">${Math.round(ssHits / Math.max(1, ssTotal) * 100)}%</div><div class="rate-hero-bar"><span style="width:${Math.max(2, Math.min(100, Math.round(ssHits / Math.max(1, ssTotal) * 100)))}%;background:${Math.round(ssHits / Math.max(1, ssTotal) * 100) >= 50 ? 'var(--green)' : Math.round(ssHits / Math.max(1, ssTotal) * 100) >= 35 ? 'var(--gold)' : 'var(--red)'}"></span></div><div class="rate-hero-sub">${ssHits}/${ssTotal} hit on current roster · per-fighter breakdown needs 2+ events each</div></div>`;

  const topTDHtml = topTD.length
    ? topTD.map(x => `<div class="best-pick-row">
          <div class="best-pick-rank">${x.rate}%</div>
          <div><div class="best-pick-name">${prettyName(x.fighter)}</div><div class="best-pick-reason">${x.total} events · ${Math.round(x.rate / 100 * x.total)}/${x.total} over</div></div>
          <div class="best-pick-meta"><span class="best-pick-platform">TD</span></div>
          <div class="best-pick-line">${x.total} events</div>
        </div>`).join('')
    : `<div class="rate-hero"><div class="rate-hero-num" style="color:${Math.round(tdHits / Math.max(1, tdTotal) * 100) >= 50 ? 'var(--green)' : Math.round(tdHits / Math.max(1, tdTotal) * 100) >= 35 ? 'var(--gold)' : 'var(--red)'}">${Math.round(tdHits / Math.max(1, tdTotal) * 100)}%</div><div class="rate-hero-bar"><span style="width:${Math.max(2, Math.min(100, Math.round(tdHits / Math.max(1, tdTotal) * 100)))}%;background:${Math.round(tdHits / Math.max(1, tdTotal) * 100) >= 50 ? 'var(--green)' : Math.round(tdHits / Math.max(1, tdTotal) * 100) >= 35 ? 'var(--gold)' : 'var(--red)'}"></span></div><div class="rate-hero-sub">${tdHits}/${tdTotal} hit on current roster · per-fighter breakdown needs 2+ events each</div></div>`;

  // ── AI pick accuracy by stat type (lean-direction correct, not raw over rate) ──
  const aiStatBadge = (label: string, propType: string): string => {
    const d = aiAccuracyByType[propType];
    if (!d?.total) return `<span class="archive-stat-badge archive-stat-empty"><span class="asb-label">${label}</span><span class="asb-val">—</span></span>`;
    const pct = Math.round((d.hits / d.total) * 100);
    const lowN = d.total < 5;
    // Don't color-grade until 5+ samples — small samples produce misleading red/green signals
    const color = lowN ? 'var(--text-muted)' : pct >= 65 ? 'var(--green)' : pct >= 45 ? 'var(--amber)' : 'var(--red)';
    const nTag = lowN ? ` <span style="opacity:0.5;font-size:9px">(n=${d.total})</span>` : '';
    // Direction split: the aggregate hides the actionable read ("trust FP
    // overs, fade FP unders"). Same 5-sample rule before color-grading.
    const splitRow = (arrow: string, dirLabel: string, h: number, t: number): string => {
      if (!t) return '';
      const p = Math.round((h / t) * 100);
      const low = t < 5;
      const c = low ? 'var(--text-muted)' : p >= 65 ? 'var(--green)' : p >= 45 ? 'var(--amber)' : 'var(--red)';
      return `<span class="asb-split" title="${dirLabel} picks: ${h}/${t} correct${low ? ' (low sample)' : ''}">${arrow} <b style="color:${c}">${p}%</b><i>${h}/${t}</i></span>`;
    };
    const splits = `<span class="asb-splits">${splitRow('▲', 'OVER', d.overHits, d.overTotal)}${splitRow('▼', 'UNDER', d.underHits, d.underTotal)}</span>`;
    return `<span class="archive-stat-badge"${lowN ? '' : ` style="--asb-color:${color}"`}><span class="asb-label">${label}</span><span class="asb-val" style="color:${color}">${d.hits}/${d.total} <span style="opacity:0.7">(${pct}%)${nTag}</span></span><span class="asb-bar"><span style="width:${Math.max(2, Math.min(100, pct))}%;background:${color}"></span><span class="asb-tick" title="~55% — rough break-even zone for pick-em entries"></span></span>${splits}</span>`;
  };
  const statSummaryHtml = `
    <div class="archive-stat-summary">
      ${aiStatBadge('FP', 'Fantasy')}
      ${aiStatBadge('SS', 'SS')}
      ${aiStatBadge('TD', 'TD')}
      ${aiStatBadge('FT', 'FightTime')}
    </div>`;

  // ── Entry-vs-close CLV badges ─────────────────────────────────────────
  const entryClvBadge = (label: string, propType: string): string => {
    const d = entryClvByType[propType];
    if (!d?.picks) {
      return `<span class="archive-stat-badge archive-stat-empty"><span class="asb-label">${label}</span><span class="asb-val">—</span></span>`;
    }
    const avgClv = d.clvSum / d.picks;
    const beatPct = Math.round((d.clvPosCount / d.picks) * 100);
    const lowN = d.picks < 5;
    const clvColor = lowN ? 'var(--text-muted)' : avgClv > 0.1 ? 'var(--green)' : avgClv < -0.1 ? 'var(--red)' : 'var(--amber)';
    const beatColor = lowN ? 'var(--text-muted)' : beatPct >= 55 ? 'var(--green)' : beatPct >= 45 ? 'var(--amber)' : 'var(--red)';
    const hitStr = d.resolvedCount > 0 ? ` · <span style="opacity:0.8">${Math.round((d.hitCount / d.resolvedCount) * 100)}% hit</span>` : '';
    const nTag = lowN ? ` <span style="opacity:0.5;font-size:9px">(n=${d.picks})</span>` : ` <span style="opacity:0.5;font-size:9px">(n=${d.picks})</span>`;
    // CLV validation split: hit rate when the entry beat the close vs when it
    // didn't. A real gap means line movement is confirming the picks; no gap
    // means CLV is noise for this stat. Same 5-sample color floor as elsewhere.
    // GLOW-UP 313: a one-sample cell printed "0%" (TD BEAT 0% 0/1). Greying the
    // colour was not enough — the number itself is the claim, and 0/1 has no rate.
    // Under 5 the fraction stands alone.
    const clvSplit = (splitLabel: string, h: number, t: number, tip: string): string => {
      if (!t) return '';
      const p = Math.round((h / t) * 100);
      const low = t < 5;
      const c = low ? 'var(--text-muted)' : p >= 55 ? 'var(--green)' : p >= 45 ? 'var(--amber)' : 'var(--red)';
      const val = low ? '—' : `${p}%`;
      return `<span class="asb-split" title="${tip}: ${h}/${t} hit${low ? ' — too few to state a rate, so the fraction is shown bare' : ''}">${splitLabel} <b style="color:${c}">${val}</b><i>${h}/${t}</i></span>`;
    };
    // ── GLOW-UP 314 · the gap was the point, and nothing measured it ──────────
    // This panel's own reasoning is that a real BEAT-vs-OTHER gap means line
    // movement is confirming the picks, and no gap means CLV is noise for that
    // stat. It then rendered both cells and left the comparison to the eye — so a
    // +17pt gap on n=12 looked stronger than a -5pt gap on n=346, when only the
    // second is a large enough sample to mean anything.
    //
    // Same 1.5-SE rule as the ledger's ALPHA chip, for the same reason: a verdict
    // the sample cannot support is worse than no verdict.
    const gapVerdict = ((): string => {
      const pr = d.posResolved, nr = d.nonPosResolved;
      if (!pr || !nr || pr < 5 || nr < 5) return '';
      const p1 = d.posHit / pr, p2 = d.nonPosHit / nr;
      const se = Math.sqrt((p1 * (1 - p1)) / pr + (p2 * (1 - p2)) / nr);
      const gap = (p1 - p2) * 100;
      if (!Number.isFinite(se) || se <= 0) return '';
      const strong = Math.abs(gap) >= 1.5 * se * 100;
      const cls = !strong ? 'noise' : gap > 0 ? 'confirms' : 'inverts';
      const label = !strong ? 'CLV NOISE' : gap > 0 ? `CLV CONFIRMS +${gap.toFixed(0)}` : `CLV INVERTS ${gap.toFixed(0)}`;
      const tip = !strong
        ? `Beating the close is worth ${gap > 0 ? '+' : ''}${gap.toFixed(0)}pts of hit rate here, against a standard error of ${(se * 100).toFixed(0)}pts — under 1.5 SE, so it is not distinguishable from no effect. For this stat, CLV is not yet predicting whether a pick lands.`
        : gap > 0
          ? `Picks whose entry beat the close hit ${gap.toFixed(0)}pts more often (±${(se * 100).toFixed(0)}pts). Line movement is confirming this stat — beating the close is a real signal here.`
          : `Picks whose entry beat the close hit ${Math.abs(gap).toFixed(0)}pts LESS often (±${(se * 100).toFixed(0)}pts). The movement is going against the result on this stat, which is the opposite of what CLV is supposed to mean — worth understanding before trusting it.`;
      return `<span class="asb-gap ${cls}" title="${tip.replace(/"/g, '&quot;')}">${label}</span>`;
    })();
    const splits = (d.posResolved || d.nonPosResolved)
      ? `<span class="asb-splits">${
          clvSplit('BEAT', d.posHit, d.posResolved, 'Picks where your entry beat the close — hit rate')
        }${
          clvSplit('OTHER', d.nonPosHit, d.nonPosResolved, 'Picks where the close was flat or moved against you — hit rate')
        }${gapVerdict}</span>`
      : '';
    return `<span class="archive-stat-badge"><span class="asb-label">${label}</span><span class="asb-val"><span style="color:${clvColor};font-weight:700">${avgClv > 0 ? '+' : ''}${avgClv.toFixed(2)}</span> <span style="opacity:0.7;font-size:9px">· <span style="color:${beatColor}">${beatPct}% beat</span>${hitStr}${nTag}</span></span>${splits}</span>`;
  };
  const entryClvHtml = `
    <div class="archive-stat-summary">
      ${entryClvBadge('FP', 'Fantasy')}
      ${entryClvBadge('SS', 'SS')}
      ${entryClvBadge('TD', 'TD')}
      ${entryClvBadge('FT', 'FightTime')}
    </div>`;

  // ── Per-platform summary ────────────────────────────────────────────────
  const PLAT_LABELS: Record<string, string> = { pick6: 'Pick6', underdog: 'UD', prizepicks: 'PP', betr: 'Betr', draftkings_sportsbook: 'DK' };
  const platSummaryHtml = platSummary.size > 0
    ? `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px">` +
      [...platSummary.entries()]
        .filter(([, v]) => v.total >= 1)
        .sort((a, b) => (b[1].hits / b[1].total) - (a[1].hits / a[1].total))
        .map(([plat, v]) => {
          const pct = Math.round((v.hits / v.total) * 100);
          const avgEdge = (v.edgeSum / v.total).toFixed(1);
          const col = pct >= 65 ? 'var(--green)' : pct >= 45 ? 'var(--amber)' : 'var(--red)';
          return `<span style="font-size:11px;padding:3px 8px;border-radius:5px;background:var(--surface2)">
            <span style="color:var(--text-muted)">${PLAT_LABELS[plat] || plat.toUpperCase()}</span>
            <span style="color:${col};font-weight:700;margin-left:4px">${pct}%</span>
            <span style="color:var(--text-muted);font-size:10px;margin-left:3px">${v.hits}/${v.total} · edge ${Number(avgEdge) > 0 ? '+' : ''}${avgEdge}</span>
          </span>`;
        }).join('') + `</div>`
    : '';

  // Platform bias — sortable; sort key stored at module level so it persists across re-renders
  const sk = _archiveBiasSortKey;
  const sortFn = (a: typeof biasRows[0], b: typeof biasRows[0]): number => {
    if (sk === 'hitRate') return b.hitRate - a.hitRate;
    if (sk === 'total') return b.total - a.total;
    return Math.abs(b.avgEdge) - Math.abs(a.avgEdge);
  };
  const biasSorted = [...biasRows].sort(sortFn);
  const biasHdr = (label: string, key: string) =>
    `<span data-bias-sort="${key}" style="cursor:pointer;text-decoration:underline dotted;color:${sk === key ? 'var(--text)' : 'var(--text-muted)'}">${label}${sk === key ? ' ▼' : ''}</span>`;
  // Side verdict: translate the signed edge into the actionable read. Edge is
  // result − line, so a NEGATIVE edge means results land below the book's
  // lines → the book shades HIGH → the UNDER side carries the value.
  // Thresholds are stat-scaled (FP points ≠ TD counts) and verdicts need 5+
  // records — below that the chip stays off rather than faking a signal.
  const biasVerdict = (propType: string, avgEdge: number, total: number): string => {
    if (total < 5) return '';
    const pt = propType.toLowerCase();
    const thr = pt.startsWith('fantasy') ? 4.0
      : pt === 'td' ? 0.4
      : pt === 'fighttime' ? 1.0
      : 2.0; // SS family (SS, SS_R1, ss leg, ss body)
    if (avgEdge <= -thr) return ` <span class="bias-verdict under" title="Results average ${Math.abs(avgEdge)} below this book's ${propType} lines (n=${total}) — lines shade HIGH, the UNDER side carries the value">▼ UNDER VALUE</span>`;
    if (avgEdge >= thr) return ` <span class="bias-verdict over" title="Results average +${avgEdge} above this book's ${propType} lines (n=${total}) — lines shade LOW, the OVER side carries the value">▲ OVER VALUE</span>`;
    return ` <span class="bias-verdict fair" title="Lines track results within ±${thr} (n=${total}) — no exploitable shading">≈ FAIR</span>`;
  };
  const biasHtml = biasSorted.length
    ? `<div style="display:flex;gap:12px;font-size:10px;margin-bottom:6px;padding:0 4px">
        <span style="flex:1;color:var(--text-muted)">Platform / Prop</span>
        ${biasHdr('Avg Edge', 'avgEdge')} &nbsp; ${biasHdr('Hit%', 'hitRate')} &nbsp; ${biasHdr('N', 'total')}
       </div>` +
      biasSorted.map(x => { const rc = x.hitRate >= 55 ? 'var(--green)' : x.hitRate >= 45 ? 'var(--gold)' : 'var(--red)'; return `<div class="bias-row">
        <span class="bias-platform">${x.platform.toUpperCase()}</span>
        <div class="bias-main"><div class="bias-prop">${x.propType}${biasVerdict(x.propType, x.avgEdge, x.total)}</div><div class="bias-sub">${x.total} records · avg edge ${x.avgEdge > 0 ? '+' : ''}${x.avgEdge}</div></div>
        <span class="bias-bar"><span style="width:${Math.max(2, Math.min(100, x.hitRate))}%;background:${rc}"></span></span>
        <span class="bias-rate" style="color:${rc}">${x.hitRate}%</span>
      </div>`; }).join('')
    : '<div class="inline-empty-msg">No resolved outcomes yet</div>';

  // ── Platform bias bar chart (avg edge per stat, grouped by platform) ─────
  // Shows whether each platform sets lines too high (+) or too low (-) per stat.
  const STAT_ORDER_CHART = ['Fantasy', 'SS', 'TD', 'FightTime'];
  const STAT_LABELS_CHART: Record<string, string> = { Fantasy: 'FP', SS: 'SS', TD: 'TD', FightTime: 'FT' };
  const biasChartData: Record<string, Record<string, { avgEdge: number; total: number }>> = {};
  for (const b of Array.from(biasMap.values()).filter(bv => bv.total >= 2)) {
    if (!biasChartData[b.propType]) biasChartData[b.propType] = {};
    biasChartData[b.propType][b.platform] = {
      avgEdge: Number((b.edgeSum / b.total).toFixed(1)),
      total: b.total,
    };
  }
  const allEdgeAbsVals = Object.values(biasChartData)
    .flatMap(plats => Object.values(plats).map(v => Math.abs(v.avgEdge)));
  const maxEdgeScale = allEdgeAbsVals.length ? Math.max(...allEdgeAbsVals, 1) : 1;

  const biasByStatHtml = STAT_ORDER_CHART.filter(pt => biasChartData[pt] && Object.keys(biasChartData[pt]).length > 0).map(pt => {
    const label = STAT_LABELS_CHART[pt] || pt;
    const entries = Object.entries(biasChartData[pt]).sort((a, b) => b[1].avgEdge - a[1].avgEdge);
    const bars = entries.map(([plat, { avgEdge, total }]) => {
      const pctBar = Math.round(Math.abs(avgEdge) / maxEdgeScale * 80); // cap at 80% width
      const isPos = avgEdge >= 0;
      const col = isPos ? 'var(--green)' : 'var(--red)';
      const platLabel = PLAT_LABELS[plat] || plat.toUpperCase();
      return `<div title="${platLabel} · avg edge ${avgEdge > 0 ? '+' : ''}${avgEdge} · n=${total}" style="display:flex;align-items:center;gap:4px">
        <span style="font-size:9px;color:var(--text-muted);min-width:26px;text-align:right">${platLabel}</span>
        <div style="width:100px;background:var(--surface2);border-radius:2px;height:8px;overflow:hidden">
          <div style="height:100%;width:${pctBar}%;background:${col};border-radius:2px;opacity:0.85"></div>
        </div>
        <span style="font-size:9px;color:${col};min-width:30px">${avgEdge > 0 ? '+' : ''}${avgEdge}</span>
      </div>`;
    }).join('');
    return `<div style="display:flex;align-items:flex-start;gap:6px;margin-bottom:6px">
      <span style="font-size:10px;font-weight:700;color:var(--text);min-width:16px;padding-top:1px">${label}</span>
      <div style="display:flex;flex-direction:column;gap:2px">${bars}</div>
    </div>`;
  }).join('');

  const biasChartHtml = biasByStatHtml
    ? `<div style="margin:8px 0 10px 0;padding:8px 10px;background:var(--surface2);border-radius:6px">
        <div style="font-size:9px;color:var(--text-muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.08em">Avg Edge by Stat (+ = result beats line)</div>
        ${biasByStatHtml}
       </div>`
    : '';

  // ── Calibration Curve — confidence vs actual hit rate ─────────────────
  // Join AI lean snapshot picks (which have confidence scores) with archive
  // results to compute actual hit rate per confidence bucket.
  type CalibBucket = { rangeLabel: string; midpoint: number; hits: number; total: number };
  const calibBuckets: CalibBucket[] = [
    { rangeLabel: '50–54%', midpoint: 52, hits: 0, total: 0 },
    { rangeLabel: '55–59%', midpoint: 57, hits: 0, total: 0 },
    { rangeLabel: '60–64%', midpoint: 62, hits: 0, total: 0 },
    { rangeLabel: '65–69%', midpoint: 67, hits: 0, total: 0 },
    { rangeLabel: '70–74%', midpoint: 72, hits: 0, total: 0 },
    { rangeLabel: '75–79%', midpoint: 77, hits: 0, total: 0 },
    { rangeLabel: '80–84%', midpoint: 82, hits: 0, total: 0 },
    { rangeLabel: '85–89%', midpoint: 87, hits: 0, total: 0 },
    { rangeLabel: '90%+',   midpoint: 92, hits: 0, total: 0 },
  ];
  // Also track per-stat-type calibration
  const calibByType: Record<string, CalibBucket[]> = {};
  const CALIB_STAT_TYPES = ['Fantasy', 'SS', 'TD', 'FightTime'];
  for (const pt of CALIB_STAT_TYPES) {
    calibByType[pt] = calibBuckets.map(b => ({ ...b, hits: 0, total: 0 }));
  }
  let calibTotalSamples = 0;
  // Snapshots predating displayedConfidence fall back to raw, so the curve is a MIXED
  // sample until the store turns over. Counted so the panel can say so out loud rather
  // than quietly reporting a number that is mostly the old measurement.
  let calibDisplayedSamples = 0;

  for (const snap of aiSnapsFinal) {
    const snapEventKey = eventDedupeKey(String(snap?.event || ''));
    if (!snapEventKey || !pastEventKeys.has(snapEventKey)) continue;
    const eventArchiveRows = rowsForEvent(snapEventKey);
    if (!eventArchiveRows.length) continue;

    for (const pick of (snap?.picks ?? []) as Array<Record<string, any>>) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '').toLowerCase();
      // Readout: calibrate what the BOARD showed. The map that produced it is built from
      // RAW confidence in initRecalibrationMap / the scope below — do not switch those.
      const conf = snapshotDisplayConf(pick);
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine) || !Number.isFinite(conf) || conf < 50) continue;

      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.result))
        )
        .sort((a, b) => {
          const aPP = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPP = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPP !== bPP) return aPP - bPP;
          return Math.abs(Number(a.line ?? activeLine) - activeLine) - Math.abs(Number(b.line ?? activeLine) - activeLine);
        })[0];
      if (!match) continue;

      const result = Number(match.result);
      const isHit = (lean === 'over' && result > activeLine) || (lean === 'under' && result < activeLine);

      // Find the right bucket
      const bucketIdx = conf >= 90 ? 8 : conf >= 85 ? 7 : conf >= 80 ? 6 : conf >= 75 ? 5
        : conf >= 70 ? 4 : conf >= 65 ? 3 : conf >= 60 ? 2 : conf >= 55 ? 1 : 0;
      calibBuckets[bucketIdx].total++;
      if (isHit) calibBuckets[bucketIdx].hits++;
      calibTotalSamples++;
      if (snapshotUsesDisplayedConf(pick)) calibDisplayedSamples++;

      // Per-type calibration
      if (calibByType[propType]) {
        calibByType[propType][bucketIdx].total++;
        if (isHit) calibByType[propType][bucketIdx].hits++;
      }
    }
  }

  // Compute overall calibration score (Brier-style: lower = better calibrated)
  // Mean squared error of predicted probability vs actual hit rate across buckets
  // WEIGHTED BY BUCKET POPULATION. This counted BUCKETS, so a 9-pick bucket carried the
  // same weight as a 250-pick one — and on the 2026-08-29 archive a single n=9 bucket
  // supplied 71% of the total error, making the headline score a readout of the thinnest
  // cell on the panel rather than of the model.
  let calibBrierSum = 0;
  let calibBrierN = 0;
  // Signed, same weighting: magnitude alone cannot tell over- from under-confidence, and
  // the direction is the actionable half. The archive shows the 60-79% range running
  // 5-11 points BELOW its stated confidence across n=611 — 56% of all graded picks, all
  // leaning the same way. That is systematic, and an unsigned "88/100 Excellent" hid it.
  let calibBiasSum = 0;
  for (const b of calibBuckets) {
    if (b.total < 2) continue;
    const predicted = b.midpoint / 100;
    const actual = b.hits / b.total;
    calibBrierSum += b.total * (predicted - actual) ** 2;
    calibBiasSum += b.total * (actual - predicted);
    calibBrierN += b.total;
  }
  const calibScore = calibBrierN > 0 ? Math.round((1 - Math.sqrt(calibBrierSum / calibBrierN)) * 100) : null;
  /** Positive = the model is UNDER-confident (it beats its own number); negative = it is
   *  OVER-confident. Points of hit rate, not a probability. */
  const calibBiasPts = calibBrierN > 0 ? Math.round((calibBiasSum / calibBrierN) * 1000) / 10 : null;

  // Build calibration curve HTML
  const calibActiveBuckets = calibBuckets.filter(b => b.total > 0);
  const calibCurveHtml = calibActiveBuckets.length >= 2 ? (() => {
    const maxBarH = 96;
    const BREAKEVEN_PCT = 52.4; // -110 pick-em breakeven — same goalpost the KPI meter uses
    const beY = Math.round((BREAKEVEN_PCT / 100) * maxBarH);
    const barRows = calibBuckets.map(b => {
      if (b.total === 0) return '';
      const actualRate = Math.round((b.hits / b.total) * 100);
      const predicted = b.midpoint;
      const diff = actualRate - predicted;
      const diffSign = diff > 0 ? '+' : '';
      const diffCls = Math.abs(diff) <= 5 ? 'good' : Math.abs(diff) <= 12 ? 'warn' : 'bad';
      const predictedH = Math.round((predicted / 100) * maxBarH);
      const actualH = Math.max(3, Math.round((actualRate / 100) * maxBarH));
      const barCls = actualRate >= predicted - 3 ? 'good' : actualRate >= predicted - 12 ? 'warn' : 'bad';
      const lowN = b.total < CALIB_THIN_N;
      return `<div class="cal-col${lowN ? ' cal-low-n' : ''}">
        <span class="cal-diff cal-diff-${diffCls}" title="Actual minus predicted for this bucket${lowN ? ' — thin sample, read lightly' : ''}">${diffSign}${diff}%</span>
        <div class="cal-track" style="height:${maxBarH}px">
          <i class="cal-be" style="bottom:${beY}px" title="52.4% breakeven (-110) — buckets above this line profit"></i>
          <div class="cal-pred" style="height:${predictedH}px" title="Predicted: ${predicted}%"></div>
          <div class="cal-actual cal-actual-${barCls}" style="height:${actualH}px" title="Actual: ${actualRate}% (${b.hits}/${b.total})"></div>
        </div>
        <span class="cal-rate">${actualRate}%</span>
        <span class="cal-range">${b.rangeLabel}</span>
        <span class="cal-n">n=${b.total}</span>
      </div>`;
    }).filter(Boolean).join('');

    // Per-stat-type mini calibration rows — stat-family colors match the board
    const STAT_CLS: Record<string, string> = { Fantasy: 'fp', SS: 'ss', TD: 'td', FightTime: 'ft' };
    const typeCalibHtml = CALIB_STAT_TYPES.map(pt => {
      const buckets = calibByType[pt];
      const active = buckets.filter(b => b.total > 0);
      if (active.length < 1) return '';
      const label = pt === 'FightTime' ? 'FT' : pt === 'Fantasy' ? 'FP' : pt;
      const totalHits = active.reduce((s, b) => s + b.hits, 0);
      const totalN = active.reduce((s, b) => s + b.total, 0);
      const overallRate = totalN > 0 ? Math.round((totalHits / totalN) * 100) : 0;
      const dots = buckets.map(b => {
        if (b.total === 0) return `<i class="cal-dot cal-dot-empty" title="${b.rangeLabel}: no data"></i>`;
        const actual = Math.round((b.hits / b.total) * 100);
        const diff = Math.abs(actual - b.midpoint);
        const dotCls = diff <= 5 ? 'good' : diff <= 12 ? 'warn' : 'bad';
        return `<i class="cal-dot cal-dot-${dotCls}${b.total < 3 ? ' cal-dot-thin' : ''}" title="${b.rangeLabel}: ${actual}% actual (${b.hits}/${b.total})"></i>`;
      }).join('');
      const rateCls = overallRate >= 55 ? 'good' : overallRate >= 45 ? 'warn' : 'bad';
      return `<div class="cal-stat-row">
        <span class="cal-stat-label cal-stat-${STAT_CLS[pt] || 'fp'}">${label}</span>
        <div class="cal-dots">${dots}</div>
        <span class="cal-stat-rate cal-rate-${rateCls}">${totalHits}/${totalN} · ${overallRate}%</span>
      </div>`;
    }).filter(Boolean).join('');

    const scoreCls = calibScore == null ? '' : calibScore >= 85 ? 'good' : calibScore >= 70 ? 'warn' : 'bad';
    const scoreHtml = calibScore != null
      ? `<div class="cal-head">
          <span class="cal-score cal-score-${scoreCls}">${calibScore}<i>/100</i></span>
          <span class="cal-verdict">${calibScore >= 85 ? 'Excellent — confidence closely matches reality' : calibScore >= 70 ? 'Good — minor gaps between predicted and actual' : 'Needs work — confidence scores are off from reality'}${calibBiasPts != null && Math.abs(calibBiasPts) >= 2 ? ` · <b style="color:${calibBiasPts < 0 ? 'var(--red)' : 'var(--green)'}">${calibBiasPts > 0 ? '+' : ''}${calibBiasPts} pts ${calibBiasPts < 0 ? 'over' : 'under'}-confident</b>` : ''}</span>
          <span class="cal-samples" title="AI lean snapshot picks matched to settled archive results">📎 ${calibTotalSamples} graded picks</span>
        </div>`
      : '';

    return `${scoreHtml}
      <div class="cal-legend">
        <span class="cal-key"><i class="cal-key-pred"></i>predicted</span>
        <span class="cal-key"><i class="cal-key-actual"></i>actual hit rate</span>
        <span class="cal-key"><i class="cal-key-be"></i>52.4% breakeven</span>
      </div>
      <div class="cal-chart">${barRows}</div>
      ${typeCalibHtml ? `<div class="cal-stat-block">
        <div class="cal-stat-head">Per-Stat Calibration</div>
        ${typeCalibHtml}
      </div>` : ''}`;
  })() : null;

  const statusLine = unresolvedCount > 0
    ? `<span style="color:var(--amber)">${unresolvedCount} unresolved records</span>`
    : `<span style="color:var(--green)">All records settled ✓</span>`;

  // ── Awaiting Settlement banner ─────────────────────────────────────────
  const TYPE_ABBR: Record<string, string> = { Fantasy: 'FP', SS: 'SS', TD: 'TD', FightTime: 'FT' };
  const pendingBannerHtml = pendingEvents.length > 0 ? `
    <div class="pending-settle-banner" style="margin-bottom:12px;border:1px solid rgba(240,180,40,0.35);border-left:3px solid var(--amber);border-radius:6px;background:rgba(240,180,40,0.06);padding:10px 14px">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px">
        <span style="font-family:'Space Grotesk',sans-serif;font-size:11px;letter-spacing:0.1em;text-transform:uppercase;color:var(--amber);font-weight:700">⏳ Awaiting Settlement</span>
        <span style="font-size:10px;color:var(--text-muted)">${unresolvedCount} props across ${pendingEvents.length} event${pendingEvents.length === 1 ? '' : 's'} need results</span>
        <button id="pendingDismissBtn" style="margin-left:auto;background:none;border:1px solid rgba(255,255,255,0.15);border-radius:4px;padding:3px 10px;font-size:10px;font-family:'JetBrains Mono',monospace;font-weight:600;cursor:pointer;color:var(--text-muted);letter-spacing:0.04em" title="Mark remaining unresolved records as push (result = line)">✕ DISMISS</button>
        <button id="pendingSettleBtn" style="background:var(--amber);color:#000;border:none;border-radius:4px;padding:3px 10px;font-size:11px;font-family:'JetBrains Mono',monospace;font-weight:700;cursor:pointer;letter-spacing:0.04em">⚡ SETTLE NOW</button>
      </div>
      ${pendingEvents.map(p => {
        const breakdown = Object.entries(p.byType)
          .sort((a, b) => b[1] - a[1])
          .map(([type, n]) => `${TYPE_ABBR[type] ?? type} ×${n}`)
          .join(' · ');
        return `<div style="display:flex;align-items:center;gap:8px;padding:4px 0;border-top:1px solid rgba(255,255,255,0.04)">
          <span style="font-size:11px;color:var(--amber);font-weight:700;min-width:28px">${p.total}</span>
          <div>
            <div style="font-size:11px;color:var(--text);font-weight:600">${p.display}</div>
            <div style="font-size:10px;color:var(--text-muted)">${breakdown}</div>
          </div>
        </div>`;
      }).join('')}
    </div>` : '';

  // ── Backtesting Dashboard ────────────────────────────────────────────
  _cachedBacktestResults = computeBacktestFromHistory();
  const bt = _cachedBacktestResults;
  const backtestHtml = bt ? (() => {
    const wf = bt.wf;
    const accPct = (wf.overallAccuracy * 100).toFixed(1);
    const brierStr = wf.overallBrierScore.toFixed(3);
    const driftStr = (wf.driftScore * 100).toFixed(1);
    const avgCal = wf.folds.reduce((s, f) => s + f.calibrationScore, 0) / wf.folds.length;
    const calPct = (avgCal * 100).toFixed(1);

    // Grade the model
    const grade = wf.overallAccuracy >= 0.60 ? 'A' : wf.overallAccuracy >= 0.55 ? 'B' : wf.overallAccuracy >= 0.50 ? 'C' : 'D';
    const gradeCol = grade === 'A' ? 'var(--green)' : grade === 'B' ? 'var(--amber)' : 'var(--red)';

    // Summary stat cards — using bt-stat-card CSS class with animated counters
    // data-target = numeric value to count to, data-suffix = text after number, data-decimals = decimal places
    const statCard = (label: string, numericValue: number, suffix: string, decimals: number, sub: string, color: string) =>
      `<div class="bt-stat-card" style="--card-accent:${color}">
        <div class="bt-stat-val bt-counter" style="color:${color}" data-target="${numericValue}" data-suffix="${suffix}" data-decimals="${decimals}">0${suffix}</div>
        <div class="bt-stat-label">${label}</div>
        <div class="bt-stat-sub">${sub}</div>
      </div>`;

    const accColor = wf.overallAccuracy >= 0.55 ? 'var(--green)' : wf.overallAccuracy >= 0.50 ? 'var(--amber)' : 'var(--red)';
    const brierColor = wf.overallBrierScore <= 0.20 ? 'var(--green)' : wf.overallBrierScore <= 0.25 ? 'var(--amber)' : 'var(--red)';
    const driftColor = wf.driftScore <= 0.08 ? 'var(--green)' : wf.driftScore <= 0.15 ? 'var(--amber)' : 'var(--red)';

    const statsRow = `<div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap">
      ${statCard('Accuracy', parseFloat(accPct), '%', 1, `${bt.totalPreds} predictions`, accColor)}
      ${statCard('Brier Score', wf.overallBrierScore, '', 3, Number(brierStr) <= 0.200 ? 'well-calibrated' : 'needs tuning', brierColor)}
      ${statCard('Drift', parseFloat(driftStr), '%', 1, wf.driftScore <= 0.08 ? 'stable' : 'unstable', driftColor)}
      ${statCard('Calibration', parseFloat(calPct), '%', 1, `${wf.folds.length} folds`, avgCal >= 0.85 ? 'var(--green)' : avgCal >= 0.70 ? 'var(--amber)' : 'var(--red)')}
    </div>`;

    // Grade badge — using bt-grade-badge CSS class
    const gradeBadge = `<div class="bt-grade-badge" style="background:${gradeCol}11;border:1px solid ${gradeCol}44;margin-bottom:12px">
      <span class="bt-grade-letter" style="color:${gradeCol}">${grade}</span>
      <span class="bt-grade-desc">Model Grade — ${
        grade === 'A' ? 'Strong edge, model is profitable' :
        grade === 'B' ? 'Marginal edge, use with confidence filters' :
        grade === 'C' ? 'Breakeven, needs improvement' : 'Below breakeven'
      }</span>
    </div>`;

    // Fold accuracy sparkline (mini bar chart)
    const maxFolds = Math.min(wf.folds.length, 20);
    const recentFolds = wf.folds.slice(-maxFolds);
    const sparkBarH = 44;
    const sparkBars = recentFolds.map((f, i) => {
      const h = Math.round(f.accuracy * sparkBarH);
      const col = f.accuracy >= 0.55 ? 'var(--green)' : f.accuracy >= 0.50 ? 'var(--amber)' : 'var(--red)';
      return `<div title="Fold ${wf.folds.length - maxFolds + i + 1}: ${(f.accuracy * 100).toFixed(1)}% (n=${f.testSize})" style="flex:1;min-width:4px;display:flex;align-items:flex-end;justify-content:center">
        <div style="width:100%;height:${h}px;background:${col};border-radius:2px 2px 0 0;opacity:0.8;transition:opacity 0.15s"></div>
      </div>`;
    }).join('');
    const sparkline = `<div class="bt-spark-panel">
      <div class="bt-spark-title">Per-Fold Accuracy (last ${maxFolds} folds) — 50% line dashed</div>
      <div style="position:relative;height:${sparkBarH}px">
        <div style="position:absolute;top:${Math.round(sparkBarH * 0.5)}px;left:0;right:0;border-top:1px dashed rgba(125,145,190,0.25);z-index:0"></div>
        <div style="display:flex;gap:2px;height:100%;position:relative;z-index:1">${sparkBars}</div>
      </div>
    </div>`;

    // Bankroll curve (simple SVG sparkline)
    const bc = bt.bankrollCurve;
    const minB = Math.min(...bc.map(p => p.bankroll));
    const maxB = Math.max(...bc.map(p => p.bankroll));
    const rangeB = maxB - minB || 1;
    const svgW = 280;
    const svgH = 54;
    const points = bc.map((p, i) => {
      const x = (i / Math.max(1, bc.length - 1)) * svgW;
      const y = svgH - ((p.bankroll - minB) / rangeB) * (svgH - 4) - 2;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(' ');
    // Area fill under the curve
    const areaPoints = `0,${svgH} ${points} ${svgW},${svgH}`;
    const finalB = bc[bc.length - 1]?.bankroll ?? 1000;
    const roi = ((finalB - 1000) / 1000 * 100).toFixed(1);
    const roiCol = finalB >= 1000 ? 'var(--green)' : 'var(--red)';
    const bankrollChart = `<div class="bt-bankroll-panel">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <span class="bt-spark-title" style="margin-bottom:0">Simulated Bankroll ($1000 start)</span>
        <span style="font-family:'Space Grotesk',sans-serif;font-size:13px;font-weight:700;color:${roiCol}">$${finalB.toFixed(0)} <span style="font-size:10px;opacity:0.7">(${Number(roi) >= 0 ? '+' : ''}${roi}%)</span></span>
      </div>
      <svg viewBox="0 0 ${svgW} ${svgH}" style="width:100%;height:${svgH}px" preserveAspectRatio="none">
        <defs><linearGradient id="bankrollFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${roiCol}" stop-opacity="0.15"/><stop offset="100%" stop-color="${roiCol}" stop-opacity="0.02"/></linearGradient></defs>
        <polygon points="${areaPoints}" fill="url(#bankrollFill)" />
        <line x1="0" y1="${svgH - ((1000 - minB) / rangeB) * (svgH - 4) - 2}" x2="${svgW}" y2="${svgH - ((1000 - minB) / rangeB) * (svgH - 4) - 2}" stroke="rgba(125,145,190,0.15)" stroke-dasharray="4,3" />
        <polyline points="${points}" fill="none" stroke="${roiCol}" stroke-width="2" stroke-linejoin="round" />
      </svg>
    </div>`;

    return `${gradeBadge}${statsRow}${sparkline}${bankrollChart}`;
  })() : null;

  // ── Prop Archive Grading Dashboard ─────────────────────────────────────
  // Track record by platform, stat type, and confidence grade
  type GradeRecord = { hits: number; total: number; avgEdge: number; edgeSum: number };
  const gradingByPlatStat = new Map<string, GradeRecord>();
  const gradingByGrade = new Map<string, GradeRecord>();
  const gradingByPlatGrade = new Map<string, GradeRecord>();
  // See calibDisplayedSamples — same mixed-sample caveat while the store turns over.
  let gradingDisplayedPicks = 0;

  for (const snap of aiSnapsFinal) {
    const snapKey = eventDedupeKey(String(snap?.event || ''));
    if (!snapKey || !pastEventKeys.has(snapKey)) continue;
    const eventArchiveRows = rowsForEvent(snapKey);

    for (const pick of (snap?.picks ?? []) as Array<Record<string, any>>) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '').toLowerCase();
      // Readout: grade what the BOARD showed, not the raw pre-recalibration number.
      const conf = snapshotDisplayConf(pick);
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine)) continue;

      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FT' : 'FP';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          (String(r.propType) === propType || (propType === 'FP' && (String(r.propType) === 'Fantasy' || String(r.propType) === 'Fantasy_PP')) || (propType === 'FT' && String(r.propType) === 'FightTime')) &&
          Number.isFinite(Number(r.result))
        )
        .sort((a, b) => {
          const aPP = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPP = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPP !== bPP) return aPP - bPP;
          return Math.abs(Number(a.line ?? activeLine) - activeLine) - Math.abs(Number(b.line ?? activeLine) - activeLine);
        })[0];
      if (!match) continue;

      const result = Number(match.result);
      const isHit = (lean === 'over' && result > activeLine) || (lean === 'under' && result < activeLine);
      if (snapshotUsesDisplayedConf(pick)) gradingDisplayedPicks++;
      const edge = result - activeLine;

      // Guard only. Every snapshot pick carries a confidence today, so this drops nothing
      // — checked against the live archive: 1161 graded picks before and after. It stays
      // because an unrated pick is not a low-confidence pick, and the old expression
      // silently filed one as a D. Do not read the D row as evidence this ever fired.
      if (!Number.isFinite(conf)) continue;
      const grade = conf >= 80 ? 'A' : conf >= 65 ? 'B' : conf >= 55 ? 'C' : 'D';
      const plat = activePlatform || 'unknown';

      // By platform+stat
      const psKey = `${plat}|${propType}`;
      const ps = gradingByPlatStat.get(psKey) || { hits: 0, total: 0, avgEdge: 0, edgeSum: 0 };
      ps.total++; if (isHit) ps.hits++; ps.edgeSum += edge;
      gradingByPlatStat.set(psKey, ps);

      // By grade
      const gr = gradingByGrade.get(grade) || { hits: 0, total: 0, avgEdge: 0, edgeSum: 0 };
      gr.total++; if (isHit) gr.hits++; gr.edgeSum += edge;
      gradingByGrade.set(grade, gr);

      // By platform+grade
      const pgKey = `${plat}|${grade}`;
      const pg = gradingByPlatGrade.get(pgKey) || { hits: 0, total: 0, avgEdge: 0, edgeSum: 0 };
      pg.total++; if (isHit) pg.hits++; pg.edgeSum += edge;
      gradingByPlatGrade.set(pgKey, pg);
    }
  }

  // Grade breakdown HTML
  const GRADE_ORDER = ['A', 'B', 'C', 'D'];
  const gradeBreakdownHtml = GRADE_ORDER.map(g => {
    const d = gradingByGrade.get(g);
    if (!d?.total) return '';
    const pct = Math.round((d.hits / d.total) * 100);
    const avgE = (d.edgeSum / d.total).toFixed(1);
    const col = pct >= 60 ? 'var(--green)' : pct >= 48 ? 'var(--amber)' : 'var(--red)';
    const barW = Math.round(Math.min(100, pct));
    return `<div class="grade-row">
      <span style="font-family:'Space Grotesk',sans-serif;font-size:16px;font-weight:900;color:${col};min-width:22px">${g}</span>
      <div class="grade-bar-bg">
        <div class="grade-bar-fill" data-fill-width="${barW}%" style="width:0%;background:${col};opacity:0.65"></div>
        <span class="grade-bar-pct">${pct}%</span>
      </div>
      <span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text3);min-width:52px;text-align:right">${d.hits}/${d.total}</span>
      <span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:${Number(avgE) >= 0 ? 'var(--green)' : 'var(--red)'};min-width:44px;text-align:right">${Number(avgE) > 0 ? '+' : ''}${avgE}</span>
    </div>`;
  }).filter(Boolean).join('');

  // Platform x Stat heatmap
  const platStatEntries = Array.from(gradingByPlatStat.entries())
    .map(([k, v]) => {
      const [plat, stat] = k.split('|');
      return { plat, stat, ...v, pct: Math.round((v.hits / v.total) * 100), avgEdge: Number((v.edgeSum / v.total).toFixed(1)) };
    })
    .filter(x => x.total >= 2)
    // RANKED ON THE WILSON LOWER BOUND, DISPLAYED RAW. "DK TD 100%" on n=4 and
    // "Pick6 TD 100%" on n=2 were outranking "Pick6 FP 62%" on n=632, so the table read
    // as advice to follow whichever cell had the least evidence behind it. A first pass
    // sorted on shrunkHitRate and changed the order not at all — Laplace scores 4/4 at
    // .833, still above .620 — which is why this uses an interval bound instead.
    .sort((a, b) => wilsonBound(b.hits, b.total, true) - wilsonBound(a.hits, a.total, true) || b.total - a.total);

  const platStatHtml = platStatEntries.length > 0
    ? `<div style="display:flex;gap:12px;font-size:10px;margin-bottom:6px;padding:0 6px">
        <span style="flex:1;color:var(--text3);font-family:'JetBrains Mono',monospace">Platform / Stat</span>
        <span style="color:var(--text3);font-family:'JetBrains Mono',monospace;min-width:48px;text-align:right">Hit Rate</span>
        <span style="color:var(--text3);font-family:'JetBrains Mono',monospace;min-width:44px;text-align:right">Avg Edge</span>
        <span style="color:var(--text3);font-family:'JetBrains Mono',monospace;min-width:36px;text-align:right">N</span>
       </div>` +
      platStatEntries.map(x => {
        const col = x.pct >= 60 ? 'var(--green)' : x.pct >= 48 ? 'var(--amber)' : 'var(--red)';
        const platLabel = PLAT_LABELS[x.plat] || x.plat.toUpperCase();
        return `<div class="plat-stat-row">
          <div style="flex:0 0 150px;display:flex;align-items:center;gap:6px">
            <span style="font-family:'Space Grotesk',sans-serif;font-size:11px;font-weight:700;color:var(--text)">${platLabel}</span>
            <span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text3)">${x.stat}</span>
          </div>
          <span class="ps-bar"><span style="width:${Math.max(2, Math.min(100, x.pct))}%;background:${col}"></span></span>
          <span style="font-family:'Space Grotesk',sans-serif;font-size:12px;font-weight:700;color:${col};min-width:48px;text-align:right">${x.pct}%</span>
          <span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:${x.avgEdge >= 0 ? 'var(--green)' : 'var(--red)'};min-width:44px;text-align:right">${x.avgEdge > 0 ? '+' : ''}${x.avgEdge}</span>
          <span style="font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text3);min-width:36px;text-align:right">${x.total}</span>
        </div>`;
      }).join('')
    : '';

  // Best & worst platform+grade combos
  const platGradeAll = Array.from(gradingByPlatGrade.entries())
    .map(([k, v]) => {
      const [plat, grade] = k.split('|');
      return { plat, grade, ...v, pct: Math.round((v.hits / v.total) * 100), avgEdge: Number((v.edgeSum / v.total).toFixed(1)) };
    });

  // The bar these lists are measured against: how the model does overall. Taken from the
  // UNFILTERED set so the sample floor below cannot move the bar it is judged by.
  const comboBaseHits = platGradeAll.reduce((n, x) => n + x.hits, 0);
  const comboBaseTotal = platGradeAll.reduce((n, x) => n + x.total, 0);
  const comboBaseRate = comboBaseTotal > 0 ? comboBaseHits / comboBaseTotal : 0.5;

  // SAMPLE FLOOR 10, was 3. Three or four graded picks is not a track record for a
  // book-and-grade pairing, it is one card. At 3 the panel listed "Betr B 75% (3/4)"
  // and "Betr C 75% (3/4)" - and after the ranking fix those two landed in the WORST
  // list, because with ten combos and five fixed slots per side the lists had to swallow
  // the middle. A book earns a row here once it has been measured, not before.
  const platGradeEntries = platGradeAll.filter(x => x.total >= 10);

  // NOT five and five. These are two ends of one distribution, so forcing a fixed count
  // per side makes each list reach past its own name - "best" collecting below-average
  // cells, "worst" collecting above-average ones. Split on the overall rate instead and
  // let each list be as long as it deserves (max 5). This also makes them disjoint by
  // construction, replacing the exclusion set that was doing that job.
  //
  // Each side still ranks on the bound that is conservative FOR THAT SIDE: the
  // pessimistic bound for best, the optimistic one for worst. Ranking both on the same
  // bound would hand one of the two lists to whichever cell was thinnest.
  const bestCombos = platGradeEntries
    .filter(x => x.hits / x.total >= comboBaseRate)
    .sort((a, b) => wilsonBound(b.hits, b.total, true) - wilsonBound(a.hits, a.total, true) || b.total - a.total)
    .slice(0, 5);
  const worstCombos = platGradeEntries
    .filter(x => x.hits / x.total < comboBaseRate)
    .sort((a, b) => wilsonBound(a.hits, a.total, false) - wilsonBound(b.hits, b.total, false) || b.total - a.total)
    .slice(0, 5);
  const comboBasePct = Math.round(comboBaseRate * 100);

  const comboRow = (x: typeof platGradeEntries[0], rank: number) => {
    const col = x.pct >= 60 ? 'var(--green)' : x.pct >= 48 ? 'var(--amber)' : 'var(--red)';
    const platLabel = PLAT_LABELS[x.plat] || x.plat.toUpperCase();
    return `<div class="combo-row">
      <span style="font-family:'JetBrains Mono',monospace;color:var(--text3);min-width:14px;font-size:10px">${rank}.</span>
      <span style="font-family:'Space Grotesk',sans-serif;font-weight:700;color:var(--text)">${platLabel}</span>
      <span style="font-family:'Space Grotesk',sans-serif;color:${col};font-weight:800;font-size:11px">${x.grade}</span>
      <span style="font-family:'Space Grotesk',sans-serif;color:${col};font-weight:700;margin-left:auto">${x.pct}%</span>
      <span style="font-family:'JetBrains Mono',monospace;color:var(--text3);font-size:10px">${x.hits}/${x.total}</span>
    </div>`;
  };

  const gradingTotalPicks = Array.from(gradingByGrade.values()).reduce((s, d) => s + d.total, 0);

  const gradingDashboardHtml = gradingTotalPicks > 0 ? `
    <div style="margin-bottom:10px">
      <span style="font-family:'JetBrains Mono',monospace;font-size:9px;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em">Track record by confidence grade — ${gradingTotalPicks} graded picks</span>
    </div>
    ${gradeBreakdownHtml ? `<div style="margin-bottom:14px">${gradeBreakdownHtml}</div>` : ''}
    ${platStatHtml ? `<div style="margin-bottom:14px;padding:10px 12px;background:var(--bg3);border:1px solid var(--border);border-radius:6px">
      <div style="font-family:'JetBrains Mono',monospace;font-size:9px;color:var(--text3);text-transform:uppercase;letter-spacing:0.1em;margin-bottom:8px">Platform x Stat Hit Rates</div>
      ${platStatHtml}
    </div>` : ''}
    ${bestCombos.length || worstCombos.length ? `<div style="display:flex;gap:12px;flex-wrap:wrap">
      ${bestCombos.length ? `<div class="combo-card combo-card-best">
        <div class="combo-card-title" style="color:var(--green)">Best Combos <span style="color:var(--text3);font-weight:400">above ${comboBasePct}%</span></div>
        ${bestCombos.map((x, i) => comboRow(x, i + 1)).join('')}
      </div>` : ''}
      ${worstCombos.length ? `<div class="combo-card combo-card-worst">
        <div class="combo-card-title" style="color:var(--red)">Worst Combos <span style="color:var(--text3);font-weight:400">below ${comboBasePct}%</span></div>
        ${worstCombos.map((x, i) => comboRow(x, i + 1)).join('')}
      </div>` : ''}
    </div>` : ''}` : null;

  // Collapsible section helper — wraps header with chevron + body with slide wrapper
  const cSec = (id: string, extraClass: string, headerClass: string, title: string, count: string, body: string, style = '') => {
    const isCollapsed = _archiveCollapsedSections.has(id);
    return `<div class="best-picks-section ${extraClass}${isCollapsed ? ' collapsed' : ''}" data-section-id="${id}" style="${style}">
      <div class="best-picks-header ${headerClass}"><span class="best-picks-title">${title}</span><span class="best-picks-count">${count}</span><span class="section-chevron">▼</span></div>
      <div class="section-body">${body}</div>
    </div>`;
  };

  // ── Load prediction data for the Predictions section ──
  _cachedPredictions = await PropLinePredictorService.getPredictions();
  try {
    const arcRaw = await new Promise<Record<string, any>>(res => chrome.storage.local.get(['prop_archive_v1'], res));
    const arc = Array.isArray(arcRaw.prop_archive_v1) ? arcRaw.prop_archive_v1 as PropArchiveRecord[] : [];
    _marketFpShift = PropLinePredictorService.computeMarketFpShift(arc);
  } catch { _marketFpShift = null; }
  // Auto-correct event name if prediction fighters match the current upcoming card
  const curEventName = (upcomingEventName || '').trim();
  debugLog(`Prediction auto-correct check: curEvent="${curEventName}" cardPairs=${upcomingCardPairs.length} preds=${_cachedPredictions.length}`);
  if (curEventName && upcomingCardPairs.length > 0) {
    const cardNames = new Set(upcomingCardPairs.flatMap(p => [p.f1.toLowerCase(), p.f2.toLowerCase()]));
    for (const pred of _cachedPredictions) {
      if (pred.settled || pred.event === curEventName) continue;
      const matchCount = pred.predictions.filter(p => cardNames.has(p.fighter.toLowerCase()) || cardNames.has((normalizeName(p.fighter) || '').toLowerCase())).length;
      debugLog(`Prediction auto-correct: "${pred.event}" matchCount=${matchCount}/${pred.predictions.length} threshold=${Math.min(pred.predictions.length, 4)}`);
      if (matchCount >= Math.min(pred.predictions.length, 4)) {
        debugLog(`Auto-correcting prediction event: "${pred.event}" → "${curEventName}"`);
        pred.event = curEventName;
        await PropLinePredictorService.savePredictions(_cachedPredictions);
      }
    }
  }
  _cachedLearningLog = await PropLinePredictorService.getLearningLog();
  const predictionsHtml = renderPredictionsHtml(cSec);

  const calibBody = calibCurveHtml
    ? calibCurveHtml
    : `<div class="archive-empty-state">
        <div class="archive-empty-icon">📈</div>
        <div class="archive-empty-text">${
        calibTotalSamples === 0
          ? `No AI lean snapshots matched to settled archive records yet.<br>The calibration curve needs picks with <b style="color:var(--text2)">confidence scores</b> matched to actual outcomes.`
          : calibActiveBuckets.length < 2
            ? `Only ${calibActiveBuckets.length} confidence bucket has data — need picks across at least <b style="color:var(--text2)">2 confidence ranges</b> for a meaningful curve.`
            : `${calibTotalSamples} picks resolved — collecting more data...`
      }</div>
      </div>`;

  const backtestBody = backtestHtml
    ? backtestHtml
    : `<div class="archive-empty-state">
        <div class="archive-empty-icon">📊</div>
        <div class="archive-empty-text">Walk-forward backtesting needs fighters with <b style="color:var(--text2)">7+ historical fight results</b> loaded.<br>Load an event with fighter databases to populate this panel.</div>
      </div>`;

  const gradingBody = gradingDashboardHtml
    ? gradingDashboardHtml
    : `<div class="archive-empty-state">
        <div class="archive-empty-icon">🎯</div>
        <div class="archive-empty-text">Grading dashboard needs <b style="color:var(--text2)">AI lean snapshots</b> matched to settled archive results.<br>Snap your picks before an event and settle results after to populate this panel.</div>
      </div>`;

  container.innerHTML = `
    ${pendingBannerHtml}
    <div style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center">
      <button id="archiveSettleBtn" class="btn btn-sm" style="background:var(--accent);color:#fff;padding:4px 12px;border-radius:6px;border:none;cursor:pointer;font-size:12px">
        ⚡ Settle from UFCStats
      </button>
      <button id="archiveBackfillBtn" class="btn btn-sm" style="background:var(--surface2);color:var(--text);padding:4px 12px;border-radius:6px;border:none;cursor:pointer;font-size:12px">
        ↻ Force Backfill
      </button>
      <span style="font-size:11px;color:var(--text-muted)">${allRows.length} total records · ${statusLine} <span style="color:var(--text-muted)">${stalenessLabel}</span></span>
    </div>
    ${predictionsHtml}
    ${cSec('events', '', '', 'Per-Event Results', `${resolvedRows.length} resolved`, eventHtml, 'margin-bottom:12px')}
    ${cSec('ai-accuracy', '', '', 'AI Pick Accuracy by Stat Type', `<span style="font-size:10px;color:var(--text-muted)">lean direction correct (over + under)</span>`, statSummaryHtml, 'margin-bottom:12px')}
    ${cSec('entry-clv', '', '', 'Board CLV (model line → close)', `<span style="font-size:10px;color:var(--text-muted)" title="Measured from the line the BOARD held when each lean was snapshotted, not from the line you entered at — those differ on 62% of placed legs. Your own entry-vs-close is on each row of the Placed Ledger below.">avg Δ from the board's line · positive = the board's number beat the close · <b>not your entries</b></span>`, entryClvHtml, 'margin-bottom:12px')}
    ${cSec('placed-ledger', '', '', 'My Placed Ledger', placedLedgerSummary, placedLedgerData.html, 'margin-bottom:12px')}
    ${cSec('parlay-ledger', '', '', 'My Parlay Ledger', parlayLedgerSummary, parlayLedgerData.html, 'margin-bottom:12px')}
    <div class="best-picks-grid">
      ${cSec('fp-hitrate', 'over', 'takes', 'Fantasy Line Hit Rate (Current Roster)', `${fantasyHits}/${fantasyTotal} · ${fantasyHitRate}%`, topFantasyHtml)}
    </div>
    <div class="best-picks-grid" style="margin-top:12px">
      ${cSec('ss-hitrate', 'over', 'takes', 'SS Hit Rate (Current Roster)', `${ssHits}/${ssTotal}`, topSSHtml)}
      ${cSec('td-hitrate', 'under', 'takes', 'TD Hit Rate (Current Roster)', `${tdHits}/${tdTotal}`, topTDHtml)}
    </div>
    ${cSec('bias', '', '', 'Platform Bias', `<span style="font-size:10px;color:var(--text-muted)">${dedupeBiasRows(resolvedRows.filter(r => !!r.platform)).length} markets priced</span>`, `${platSummaryHtml}${biasChartHtml}${biasHtml}`, 'margin-top:12px')}
    ${cSec('calibration', '', '', 'Calibration Curve', `<span style="font-size:10px;color:var(--text-muted)">${calibTotalSamples} picks resolved across ${new Set(resolvedRows.map(r => r.event)).size} event(s)${calibDisplayedSamples < calibTotalSamples ? ` <span style="color:var(--amber)" title="Snapshots taken before displayedConfidence existed carry only the RAW pre-recalibration number and fall back to it. Until this reads ${calibTotalSamples}/${calibTotalSamples}, the curve is a mixed sample and the over-confidence figure is still mostly the old measurement.">· ${calibDisplayedSamples}/${calibTotalSamples} on displayed conf</span>` : ''}</span>`, calibBody, 'margin-top:12px')}
    ${cSec('backtest', '', '', 'Backtesting Dashboard', `<span style="font-size:10px;color:var(--text3)">${bt ? `${bt.totalEvents} events · ${bt.totalPreds} predictions · ${bt.wf.folds.length} folds` : 'needs fighter history'}</span>`, backtestBody, 'margin-top:12px')}
    ${cSec('grading', '', '', 'Prop Archive Grading', `<span style="font-size:10px;color:var(--text3)">${gradingTotalPicks > 0 ? `${gradingTotalPicks} graded AI picks${gradingDisplayedPicks < gradingTotalPicks ? ` <span style="color:var(--amber)" title="Snapshots taken before displayedConfidence existed carry only the RAW pre-recalibration number and fall back to it. Grades below are a mixed sample until this reads ${gradingTotalPicks}/${gradingTotalPicks}.">· ${gradingDisplayedPicks}/${gradingTotalPicks} on displayed conf</span>` : ''}` : 'needs settled AI picks'}</span>`, gradingBody, 'margin-top:12px')}
  `;

  // Shared settle handler — used by both the main button and the pending banner CTA
  const runSettle = async (btn: HTMLButtonElement, resetLabel: string) => {
    btn.disabled = true;
    btn.textContent = '⏳ Fetching results...';
    try {
      const res = await runtimeSendMessage<{ ok: boolean; settled: number; skipped: number; errors: string[] }>({ type: 'GRADE_ARCHIVE' });
      if (res?.ok) {
        _confidenceMemoryCache = null;
        showToast(`✓ Settled ${res.settled} records from UFCStats${res.errors.length ? ` (${res.errors.length} events not found yet)` : ''}`);
        _fighterArchiveStats = null; // force reload so fighter cards reflect new results
        _fighterClvDrift = null;
        void renderArchivePanel(container);
      } else {
        showToast('Settle failed — check console');
      }
    } catch {
      showToast('Settle error — extension may need reload');
    } finally {
      btn.disabled = false;
      btn.textContent = resetLabel;
    }
  };

  // Wire up action buttons
  document.getElementById('archiveSettleBtn')?.addEventListener('click', (e) => {
    void runSettle(e.currentTarget as HTMLButtonElement, '⚡ Settle from UFCStats');
  });

  document.getElementById('pendingSettleBtn')?.addEventListener('click', (e) => {
    void runSettle(e.currentTarget as HTMLButtonElement, '⚡ SETTLE NOW');
  });

  document.getElementById('pendingDismissBtn')?.addEventListener('click', async (e) => {
    const btn = e.currentTarget as HTMLButtonElement;
    btn.disabled = true;
    btn.textContent = '⏳...';
    try {
      const raw = await new Promise<Record<string, any>>(res => chrome.storage.local.get(['prop_archive_v1'], res));
      const archive: any[] = Array.isArray(raw.prop_archive_v1) ? raw.prop_archive_v1 : [];
      let dismissed = 0;
      for (const r of archive) {
        if (Number.isFinite(Number(r.line)) && Number(r.line) > 0 && !Number.isFinite(Number(r.result))) {
          r.result = Number(r.line); // mark as push
          dismissed++;
        }
      }
      if (dismissed > 0) {
        await new Promise<void>((res, rej) => chrome.storage.local.set({ prop_archive_v1: archive }, () => {
          const err = chrome.runtime?.lastError;
          if (err) rej(new Error(err.message)); else res();
        }));
      }
      // All resolved — clear Betr lines since event is over
      await new Promise<void>((res) => chrome.storage.local.remove(['lines_betr', 'lines_betr_manual_v1'], () => res()));
      showToast(`✓ Dismissed ${dismissed} record${dismissed === 1 ? '' : 's'} — Betr lines cleared`);
      void renderArchivePanel(container);
    } catch {
      showToast('Dismiss error');
    } finally {
      btn.disabled = false;
      btn.textContent = '✕ DISMISS';
    }
  });

  document.getElementById('archiveBackfillBtn')?.addEventListener('click', async (e) => {
    const btn = e.currentTarget as HTMLButtonElement;
    btn.disabled = true;
    btn.textContent = '⏳ Running...';
    try {
      const res = await runtimeSendMessage<{ ok: boolean; changed: number; unresolvedBefore: number; unresolvedAfter: number }>({ type: 'FORCE_BACKFILL' });
      if (res?.ok) {
        showToast(`✓ Backfill: ${res.changed} records resolved (${res.unresolvedAfter} still pending)`);
        void renderArchivePanel(container);
      }
    } catch {
      showToast('Backfill error');
    } finally {
      btn.disabled = false;
      btn.textContent = '↻ Force Backfill';
    }
  });

  // Pred rows: avatar hydration + jump-to-card
  hydrateAvatarImgs(container);
  // Parlay Ledger ✕ — the counterpart to the ● PLACED toggle that single legs
  // always had. Confirms first: a slip is several legs and rebuilding it means
  // reconstructing the whole thing in Parlay Lab, so this is more costly to undo
  // than un-placing one leg.
  container.querySelectorAll<HTMLElement>('.plp-remove').forEach(btn => {
    btn.addEventListener('click', async (ev) => {
      ev.stopPropagation();
      const evKey = btn.dataset.plpEv || '';
      const id = btn.dataset.plpId || '';
      const summary = btn.dataset.plpSum || 'this parlay';
      if (!confirm(`Remove this placed parlay?\n\n${summary}\n\nIt leaves the Parlay Ledger and stops being graded. Re-place it from Parlay Lab if this was a mistake.`)) return;
      const ok = await removePlacedParlay(evKey, id);
      showToast(ok ? '✕ Parlay removed from ledger' : 'Could not remove that parlay');
      if (ok) void renderArchivePanel(container);
    });
  });

  container.querySelectorAll<HTMLElement>('.pred-row[data-jump]').forEach(el => {
    el.addEventListener('click', () => jumpToFighterCard(el.dataset['jump'] || ''));
  });

  // GLOW-UP 264: hovering a prediction row lights its opponent's row. Same
  // mechanism as GLOW-UP 169 on Best Picks — the pair is only adjacent under the
  // CARD sort, and every other sort splits it.
  container.querySelectorAll<HTMLElement>('.pred-row[data-fightkey]').forEach(row => {
    const fk = row.dataset['fightkey'] || '';
    if (!fk) return;
    row.addEventListener('mouseenter', () => {
      container.querySelectorAll<HTMLElement>(`.pred-row[data-fightkey="${CSS.escape(fk)}"]`).forEach(r => {
        if (r !== row) r.classList.add('fight-glow');
      });
    });
    row.addEventListener('mouseleave', () => {
      container.querySelectorAll<HTMLElement>('.pred-row.fight-glow').forEach(r => r.classList.remove('fight-glow'));
    });
  });

  container.querySelectorAll<HTMLElement>('[data-psort]').forEach(btn => {
    btn.addEventListener('click', () => {
      const v = btn.dataset['psort'] as PredSort;
      if (v && v !== _predSort) { _predSort = v; void renderArchivePanel(container); }
    });
  });

  // Predictor: Generate Predictions button
  container.querySelectorAll<HTMLButtonElement>('#predictorGenerateBtn').forEach(btn => {
    btn.addEventListener('click', async () => {
      btn.disabled = true;
      btn.textContent = '⏳ Fetching fighter data...';
      try {
        await generatePredictions(container);
      } catch (err) {
        showToast('Prediction error — ' + (err instanceof Error ? err.message : String(err)));
      } finally {
        btn.disabled = false;
        btn.textContent = '⚡ Generate Predictions';
      }
    });
  });

  // Predictor: Run Learning Cycle button
  container.querySelector<HTMLButtonElement>('#predictorLearnBtn')?.addEventListener('click', async (e) => {
    const btn = e.currentTarget as HTMLButtonElement;
    btn.disabled = true;
    btn.textContent = '⏳ Learning...';
    try {
      const raw = await new Promise<Record<string, any>>(res => chrome.storage.local.get(['prop_archive_v1'], res));
      const archive: PropArchiveRecord[] = Array.isArray(raw.prop_archive_v1) ? raw.prop_archive_v1 : [];
      const preds = await PropLinePredictorService.getPredictions();
      // Match the button-visibility gate: learn a prediction when it's a different event
      // OR the current event is already over (date passed) — so a just-finished, settled
      // card can be absorbed before the next slate flips upcomingEventName.
      const eventIsOver = Number.isFinite(upcomingEventTs) && upcomingEventTs > 0 && upcomingEventTs < Date.now();
      const unsettled = preds.find(p => {
        if (p.settled) return false;
        const isDifferentEvent = p.event !== (upcomingEventName || '').trim() && p.event !== upcomingEventName;
        return isDifferentEvent || eventIsOver;
      });
      if (!unsettled) { showToast('No unsettled predictions to learn from'); return; }
      const result = await PropLinePredictorService.runLearningCycle(unsettled.event, archive);
      if (result) {
        showToast(`✓ Learned from ${result.predictions.length} fighters — weights v${(await PropLinePredictorService.getWeights()).version}`);
        _cachedPredictions = null;
        _cachedLearningLog = null;
        void renderArchivePanel(container);
      } else {
        showToast('No matching predictions found for learning');
      }
    } catch (err) {
      showToast('Learning error — ' + (err instanceof Error ? err.message : String(err)));
    } finally {
      btn.disabled = false;
      btn.textContent = '▶ Run Learning Cycle';
    }
  });

  container.querySelector<HTMLButtonElement>('#predictorDeleteBtn')?.addEventListener('click', async () => {
    const preds = await PropLinePredictorService.getPredictions();
    const curEvent = (upcomingEventName || '').trim();
    // Prefer past-event unsettled (the banner case); fall back to any unsettled.
    const unsettled = preds.find(p =>
      !p.settled && p.event !== curEvent && p.event !== upcomingEventName
    ) ?? preds.find(p => !p.settled);
    if (!unsettled) return;
    // Delete all UNSETTLED entries for this event — preserves the settled audit
    // record (if any) but cleans up duplicates from re-generation.
    const matches = preds.filter(p => p.event === unsettled.event && !p.settled);
    const dupNote = matches.length > 1 ? ` (${matches.length} duplicates)` : '';
    if (!confirm(`Delete predictions for "${unsettled.event}"${dupNote}?`)) return;
    const filtered = preds.filter(p => !(p.event === unsettled.event && !p.settled));
    await PropLinePredictorService.savePredictions(filtered);
    _cachedPredictions = null;
    showToast(`Deleted predictions for "${unsettled.event}"${dupNote}`);
    void renderArchivePanel(container);
  });

  // Platform bias sort headers
  container.querySelectorAll<HTMLElement>('[data-bias-sort]').forEach(el => {
    el.addEventListener('click', () => {
      const key = el.dataset.biasSort as 'hitRate' | 'avgEdge' | 'total';
      if (key) { _archiveBiasSortKey = key; void renderArchivePanel(container); }
    });
  });

  // Delete-event buttons
  container.querySelectorAll<HTMLButtonElement>('.archive-delete-event-btn').forEach(btn => {
    btn.addEventListener('click', async () => {
      const eventName = btn.dataset.event || '';
      if (!eventName) return;
      if (!confirm(`Delete all archive records for "${eventName}"?`)) return;
      const res = await runtimeSendMessage<{ ok: boolean; deleted: number }>({ type: 'DELETE_ARCHIVE_EVENT', eventName });
      if (res?.ok) {
        showToast(`Deleted ${res.deleted} records for ${eventName}`);
        void renderArchivePanel(container);
      }
    });
  });

  // ── Collapsible section toggle ───────────────────────────────────────
  container.querySelectorAll<HTMLElement>('.best-picks-section[data-section-id]').forEach(section => {
    const header = section.querySelector<HTMLElement>('.best-picks-header');
    if (!header) return;
    header.addEventListener('click', (e) => {
      // Don't collapse when clicking buttons/links inside the header
      if ((e.target as HTMLElement).closest('button, a, [data-bias-sort]')) return;
      const id = section.dataset.sectionId!;
      const body = section.querySelector<HTMLElement>('.section-body');
      if (!body) return;

      if (_archiveCollapsedSections.has(id)) {
        // Expand: set max-height to scrollHeight for smooth open, then remove after transition
        _archiveCollapsedSections.delete(id);
        section.classList.remove('collapsed');
        body.style.maxHeight = body.scrollHeight + 'px';
        body.addEventListener('transitionend', function handler() {
          body.style.maxHeight = '';
          body.removeEventListener('transitionend', handler);
        }, { once: true });
      } else {
        // Collapse: set explicit max-height first so transition has a start value
        _archiveCollapsedSections.add(id);
        body.style.maxHeight = body.scrollHeight + 'px';
        // Force reflow so the browser registers the starting value
        void body.offsetHeight;
        section.classList.add('collapsed');
        body.style.maxHeight = '0';
      }
    });
  });

  buildDataSubNav(container);

  // ── Animate archive bars (grade bars, etc.) on scroll into view ──────
  if (typeof IntersectionObserver !== 'undefined') {
    const archiveBarObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        entry.target.querySelectorAll<HTMLElement>('[data-fill-width]').forEach((bar, idx) => {
          setTimeout(() => { bar.style.width = bar.dataset.fillWidth!; }, Math.min(idx * 6, 350));
        });
        archiveBarObserver.unobserve(entry.target);
      });
    }, { threshold: 0.1 });

    container.querySelectorAll('.best-picks-section[data-section-id]').forEach(sec => {
      archiveBarObserver.observe(sec);
    });
  } else {
    container.querySelectorAll<HTMLElement>('[data-fill-width]').forEach(bar => {
      bar.style.width = bar.dataset.fillWidth!;
    });
  }

  // ── Animated number counters for backtest stat cards ─────────────────
  const counterEls = container.querySelectorAll<HTMLElement>('.bt-counter');
  if (counterEls.length > 0) {
    const DURATION = 900; // ms
    const startTime = performance.now();
    const counters = Array.from(counterEls).map(el => ({
      el,
      target: parseFloat(el.dataset.target || '0'),
      suffix: el.dataset.suffix || '',
      decimals: parseInt(el.dataset.decimals || '0', 10),
    }));

    const easeOutExpo = (t: number): number => t === 1 ? 1 : 1 - Math.pow(2, -10 * t);

    const tick = (now: number) => {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / DURATION, 1);
      const eased = easeOutExpo(progress);

      for (const c of counters) {
        const current = c.target * eased;
        c.el.textContent = current.toFixed(c.decimals) + c.suffix;
      }

      if (progress < 1) {
        requestAnimationFrame(tick);
      }
    };

    // Small delay so the card fade-in animation starts first
    setTimeout(() => requestAnimationFrame(tick), 80);
  }
}

// ── Platform Line Bias Cache ─────────────────────────────────────────────────
// Populated by initPlatformBiasCache (called at data load) and renderCalibrationPanel.
// Key = "platform|propType" e.g. "pick6|SS". Value includes avg edge, hit rate, sample size.
const PLAT_LABEL_MAP: Record<string, string> = { pick6: 'Pick6', underdog: 'UD', prizepicks: 'PP', betr: 'Betr', draftkings_sportsbook: 'DK' };
const SOURCE_TO_PLAT: Record<string, string> = { p6: 'pick6', ud: 'underdog', pp: 'prizepicks', betr: 'betr', dk: 'draftkings_sportsbook' };
interface PlatformBiasEntry { platform: string; propType: string; hits: number; total: number; edgeSum: number; avgEdge: number; hitRate: number; }
let _platformBiasCache: PlatformBiasEntry[] | null = null;

/** For a given stat + lean direction, rank platforms by historical edge. Returns best platform source key. */
function getBiasAdjustedBest(stat: 'ss'|'td'|'ft', leanDir: 'over'|'under', available: Array<'p6'|'ud'|'pp'|'betr'|'dk'>): 'p6'|'ud'|'pp'|'betr'|'dk' | null {
  if (!_platformBiasCache || available.length < 2) return null;
  const propType = stat === 'ss' ? 'SS' : stat === 'td' ? 'TD' : 'FightTime';
  const scored = available.map(src => {
    const plat = SOURCE_TO_PLAT[src] || src;
    const bias = _platformBiasCache!.find(b => b.platform === plat && b.propType === propType);
    if (!bias || bias.total < 3) return { src, score: 0, n: 0 };
    // For OVER: want positive edge (result > line = line set too low = soft)
    // For UNDER: want negative edge (result < line = line set too high = soft)
    const score = leanDir === 'over' ? bias.avgEdge : -bias.avgEdge;
    return { src, score, n: bias.total };
  }).filter(s => s.n >= 3);
  if (scored.length < 1) return null;
  scored.sort((a, b) => b.score - a.score);
  // Only badge if top edge is meaningfully better than average
  if (scored[0].score <= 0.3) return null;
  return scored[0].src;
}

async function initPlatformBiasCache(): Promise<void> {
  try {
    const payload = await storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY]);
    const allRows = Array.isArray(payload[STORAGE_PROP_ARCHIVE_KEY])
      ? (payload[STORAGE_PROP_ARCHIVE_KEY] as PropArchiveRecord[]) : [];
    if (!allRows.length) return;
    const londonTs = Date.parse(UFC_LONDON_CUTOFF_ISO);
    const resolved = allRows.filter(r =>
      Number.isFinite(Number(r.line)) && Number.isFinite(Number(r.result)) &&
      Number.isFinite(Date.parse(r.date)) && Date.parse(r.date) >= londonTs && !!r.platform
    );
    const map = new Map<string, { platform: string; propType: string; hits: number; total: number; edgeSum: number }>();
    // Same dedupe as the panel — this cache feeds leanBestBook, so a doubled sample here
    // silently overweights whichever books covered the double-filed cards.
    for (const r of dedupeBiasRows(resolved)) {
      const key = `${String(r.platform).toLowerCase()}|${r.propType}`;
      const b = map.get(key) || { platform: String(r.platform).toLowerCase(), propType: String(r.propType), hits: 0, total: 0, edgeSum: 0 };
      let result = Number(r.result);
      const line = Number(r.line);
      // Normalize FT results stored in seconds to minutes (line is always in minutes)
      if (String(r.propType) === 'FightTime' && result > 25) result = result / 60;
      b.total++;
      b.edgeSum += result - line;
      if (result > line) b.hits++;
      map.set(key, b);
    }
    _platformBiasCache = Array.from(map.values())
      .filter(b => b.total >= 2)
      .map(b => ({ ...b, avgEdge: Number((b.edgeSum / b.total).toFixed(1)), hitRate: Math.round((b.hits / b.total) * 100) }));
    if (_platformBiasCache.length) debugLog(`Platform bias cache: ${_platformBiasCache.length} entries`);
  } catch (e) {
    debugLog(`Platform bias init error: ${(e as Error).message}`);
  }
}

// ── Confidence Recalibration Engine ──────────────────────────────────────────
// Maps raw confidence bucket midpoint → recalibrated confidence (actual hit rate).
// Populated by renderCalibrationPanel, consumed by getRecalibratedConfidence.
let _recalibrationMap: Map<number, number> | null = null;
let _recalibrationByType: Record<string, Map<number, number>> = {};

// Pseudo-count for Bayesian shrinkage of a calibration bucket's empirical hit-rate
// toward the bucket's OWN confidence prior (its midpoint). The effective calibration
// pool is only settled rows that matched a surfaced AI pick — spread across 4 types ×
// 9 buckets, so most active cells are single-digit-n. A raw hits/total there overfits
// hard (3/3 → "100%", 0/3 → "0%"), and that noise flows into displayed confidence, the
// EV chip, and parlay leg probabilities. K phantom observations at the prior rate pull
// thin cells back toward the model's own number; only real sample volume earns a big
// move. Same Laplace idea as shrunkHitRate, anchored to the displayed confidence rather
// than 50%. Panel-displayed empirical rates stay RAW; only this live-transform map is shrunk.
const RECAL_SHRINK_K = 6;
// GLOW-UP 249: the sample size below which a calibration bucket is drawn as thin
// evidence. Was an inline `< 5` in both curve renderers, which stopped meaning
// anything once GLOW-UP 247 made the diagnosis panel require n>=20 before stating a
// per-stat claim: a bucket could be too thin to draw a conclusion from and still be
// painted at full strength. One number, so the chart and the advice agree about what
// counts as evidence. The curve still PLOTS the raw rate — dimming is a hint about
// confidence in the sample, not a change to the data.
const CALIB_THIN_N = 20;
function shrunkRecalRate(hits: number, total: number, midpoint: number): number {
  const prior = midpoint / 100;
  return Math.round(((hits + RECAL_SHRINK_K * prior) / (total + RECAL_SHRINK_K)) * 100);
}

/** True once the map has enough buckets for getRecalibratedConfidence to return anything. */
function isRecalibrationReady(): boolean {
  return !!_recalibrationMap && _recalibrationMap.size >= 2;
}

/**
 * Confidence for a READOUT — the number the board actually showed for this pick.
 *
 * Snapshots written before this field existed carry only raw confidence, so those fall
 * back to it and the panel stays populated rather than emptying out. Panels that care
 * about the mix report snapshotUsesDisplayedConf() alongside the total.
 *
 * NOT for the recalibration map or the memory engine — both are keyed on RAW confidence
 * (pick.confidence) and must stay that way, or the engine trains on its own output.
 */
function snapshotDisplayConf(pick: Record<string, any>): number {
  const shown = Number(pick?.displayedConfidence);
  if (Number.isFinite(shown) && shown > 0) return shown;
  return Number(pick?.confidence);
}

/** Whether this pick carries a true displayed confidence (vs. falling back to raw). */
function snapshotUsesDisplayedConf(pick: Record<string, any>): boolean {
  const shown = Number(pick?.displayedConfidence);
  return Number.isFinite(shown) && shown > 0;
}

function getRecalibratedConfidence(rawConf: number, source?: LeanSource): number | null {
  if (!_recalibrationMap || _recalibrationMap.size < 2) return null;
  const typeKey = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
  const typeMap = _recalibrationByType[typeKey];
  const map = (typeMap && typeMap.size >= 2) ? typeMap : _recalibrationMap;
  // Find the two nearest bucket midpoints and interpolate
  const entries = Array.from(map.entries()).sort((a, b) => a[0] - b[0]);
  if (rawConf <= entries[0][0]) return entries[0][1];
  if (rawConf >= entries[entries.length - 1][0]) return entries[entries.length - 1][1];
  for (let i = 0; i < entries.length - 1; i++) {
    const [lo, loVal] = entries[i];
    const [hi, hiVal] = entries[i + 1];
    if (rawConf >= lo && rawConf <= hi) {
      const t = (rawConf - lo) / (hi - lo);
      return Math.round(loVal + t * (hiVal - loVal));
    }
  }
  return null;
}

// ── Calibration Panel (dedicated tab) ────────────────────────────────────────
async function renderCalibrationPanel(container: HTMLElement): Promise<void> {
  container.innerHTML = loadingSkeleton('Loading calibration data…');

  const [archivePayload, aiSnapshotPayload] = await Promise.all([
    storageGet<Record<string, unknown>>([STORAGE_PROP_ARCHIVE_KEY]),
    storageGet<Record<string, unknown>>([STORAGE_AI_LEAN_SNAPSHOT_KEY]),
  ]);
  const allRows = Array.isArray(archivePayload[STORAGE_PROP_ARCHIVE_KEY])
    ? (archivePayload[STORAGE_PROP_ARCHIVE_KEY] as PropArchiveRecord[]) : [];
  const rowsForEvent = makeRowsByEvent(allRows, eventDedupeKey);
  const aiSnapshots: any[] = Array.isArray(aiSnapshotPayload[STORAGE_AI_LEAN_SNAPSHOT_KEY])
    ? (aiSnapshotPayload[STORAGE_AI_LEAN_SNAPSHOT_KEY] as any[]) : [];

  const londonTs = Date.parse(UFC_LONDON_CUTOFF_ISO);
  const nowTs = Date.now();

  // Build event dedup key inline (same logic as archive panel)
  function eventDedupeKey(name: string): string {
    const m = name.match(/:\s*(.+?)\s+vs\.?\s+(.+)/i);
    if (!m) return name.toLowerCase().trim();
    const a = m[1].trim().split(/\s+/).pop()!.toLowerCase();
    const b = m[2].trim().split(/\s+/).pop()!.toLowerCase();
    return [a, b].sort().join('|');
  }

  // Determine past event keys
  const eventDateMap = new Map<string, number>();
  for (const r of allRows) {
    const ts = Date.parse(r.date);
    if (!Number.isFinite(ts) || ts < londonTs) continue;
    const key = eventDedupeKey(r.event || '');
    const existing = eventDateMap.get(key) || Infinity;
    if (ts < existing) eventDateMap.set(key, ts);
  }
  const pastEventKeys = new Set(
    Array.from(eventDateMap.entries())
      .filter(([, ts]) => ts <= nowTs || allRows.some(r => eventDedupeKey(r.event || '') === eventDedupeKey(r.event || '') && Number.isFinite(Number(r.result))))
      .map(([k]) => k)
  );

  // ── Build calibration buckets ──────────────────────────────────────────────
  type CalibBucket = { rangeLabel: string; midpoint: number; hits: number; total: number };
  const makeBuckets = (): CalibBucket[] => [
    { rangeLabel: '50–54%', midpoint: 52, hits: 0, total: 0 },
    { rangeLabel: '55–59%', midpoint: 57, hits: 0, total: 0 },
    { rangeLabel: '60–64%', midpoint: 62, hits: 0, total: 0 },
    { rangeLabel: '65–69%', midpoint: 67, hits: 0, total: 0 },
    { rangeLabel: '70–74%', midpoint: 72, hits: 0, total: 0 },
    { rangeLabel: '75–79%', midpoint: 77, hits: 0, total: 0 },
    { rangeLabel: '80–84%', midpoint: 82, hits: 0, total: 0 },
    { rangeLabel: '85–89%', midpoint: 87, hits: 0, total: 0 },
    { rangeLabel: '90%+',   midpoint: 92, hits: 0, total: 0 },
  ];
  const calibBuckets = makeBuckets();
  const CALIB_STAT_TYPES = ['Fantasy', 'SS', 'TD', 'FightTime'] as const;
  const calibByType: Record<string, CalibBucket[]> = {};
  for (const pt of CALIB_STAT_TYPES) calibByType[pt] = makeBuckets();

  // Per-event calibration (for temporal trend)
  type EventCalib = { event: string; date: number; hits: number; total: number; brierSum: number };
  const eventCalibMap = new Map<string, EventCalib>();

  // Over/under breakdown
  let overHits = 0, overTotal = 0, underHits = 0, underTotal = 0;
  let calibTotalSamples = 0;

  const bucketIdx = (conf: number) =>
    conf >= 90 ? 8 : conf >= 85 ? 7 : conf >= 80 ? 6 : conf >= 75 ? 5
      : conf >= 70 ? 4 : conf >= 65 ? 3 : conf >= 60 ? 2 : conf >= 55 ? 1 : 0;

  // Daily snapshots collapsed to one per event - see collapseSnapshotsByEvent.
  for (const snap of collapseSnapshotsByEvent(aiSnapshots, eventDedupeKey, 'latest')) {
    const snapEventKey = eventDedupeKey(String(snap?.event || ''));
    if (!snapEventKey || !pastEventKeys.has(snapEventKey)) continue;
    const eventArchiveRows = rowsForEvent(snapEventKey);
    if (!eventArchiveRows.length) continue;

    for (const pick of (snap?.picks ?? []) as Array<Record<string, any>>) {
      const fighter = normalizeName(String(pick?.fighter || ''))?.toLowerCase();
      const lean = String(pick?.lean || '').toLowerCase();
      // RAW, deliberately — NOT snapshotDisplayConf. This scope populates _recalibrationMap
      // and _recalibrationByType further down, so it must stay on the raw domain for the
      // same reason as initRecalibrationMap. See snapshotDisplayConf's doc comment.
      const conf = Number(pick?.confidence);
      const source = String(pick?.source || 'fp');
      const activeLine = finiteLineOrNaN(pick?.activeLine);
      const activePlatform = String(pick?.activePlatform || '').trim().toLowerCase();
      if (!fighter || (lean !== 'over' && lean !== 'under') || !Number.isFinite(activeLine) || !Number.isFinite(conf) || conf < 50) continue;

      const propType = source === 'ss' ? 'SS' : source === 'td' ? 'TD' : source === 'ft' ? 'FightTime' : 'Fantasy';
      const match = eventArchiveRows
        .filter(r =>
          normalizeName(r.fighter)?.toLowerCase() === fighter &&
          String(r.propType) === propType &&
          Number.isFinite(Number(r.result))
        )
        .sort((a, b) => {
          const aPP = activePlatform && String(a.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          const bPP = activePlatform && String(b.platform || '').toLowerCase() === activePlatform ? 0 : 1;
          if (aPP !== bPP) return aPP - bPP;
          return Math.abs(Number(a.line ?? activeLine) - activeLine) - Math.abs(Number(b.line ?? activeLine) - activeLine);
        })[0];
      if (!match) continue;

      const result = Number(match.result);
      const isHit = (lean === 'over' && result > activeLine) || (lean === 'under' && result < activeLine);

      // Global buckets
      const bi = bucketIdx(conf);
      calibBuckets[bi].total++;
      if (isHit) calibBuckets[bi].hits++;
      calibTotalSamples++;

      // Per-type
      if (calibByType[propType]) {
        calibByType[propType][bi].total++;
        if (isHit) calibByType[propType][bi].hits++;
      }

      // Over/Under
      if (lean === 'over') { overTotal++; if (isHit) overHits++; }
      else { underTotal++; if (isHit) underHits++; }

      // Per-event temporal tracking
      const eventName = String(snap?.event || 'Unknown');
      const eventDate = Date.parse(String(snap?.eventDate || snap?.capturedAt || ''));
      const ec = eventCalibMap.get(snapEventKey) || { event: eventName, date: Number.isFinite(eventDate) ? eventDate : 0, hits: 0, total: 0, brierSum: 0 };
      ec.total++;
      if (isHit) ec.hits++;
      const predicted = conf / 100;
      ec.brierSum += (predicted - (isHit ? 1 : 0)) ** 2;
      eventCalibMap.set(snapEventKey, ec);
    }
  }

  // ── Build recalibration map ────────────────────────────────────────────────
  const newRecalMap = new Map<number, number>();
  const newRecalByType: Record<string, Map<number, number>> = {};
  for (const b of calibBuckets) {
    if (b.total >= 3) newRecalMap.set(b.midpoint, shrunkRecalRate(b.hits, b.total, b.midpoint));
  }
  for (const pt of CALIB_STAT_TYPES) {
    newRecalByType[pt] = new Map<number, number>();
    for (const b of calibByType[pt]) {
      if (b.total >= 3) newRecalByType[pt].set(b.midpoint, shrunkRecalRate(b.hits, b.total, b.midpoint));
    }
  }
  _recalibrationMap = newRecalMap;
  _recalibrationByType = newRecalByType;

  // ── Compute overall calibration score ──────────────────────────────────────
  let brierSum = 0, brierN = 0;
  for (const b of calibBuckets) {
    if (b.total < 2) continue;
    brierSum += ((b.midpoint / 100) - (b.hits / b.total)) ** 2;
    brierN++;
  }
  const calibScore = brierN > 0 ? Math.round((1 - Math.sqrt(brierSum / brierN)) * 100) : null;

  // ── Collapsible section helper ─────────────────────────────────────────────
  const cSec = (id: string, title: string, count: string, body: string, style = '') => {
    const isCollapsed = _archiveCollapsedSections.has(id);
    return `<div class="best-picks-section${isCollapsed ? ' collapsed' : ''}" data-section-id="${id}" style="${style}">
      <div class="best-picks-header"><span class="best-picks-title">${title}</span><span class="best-picks-count">${count}</span><span class="section-chevron">▼</span></div>
      <div class="section-body">${body}</div>
    </div>`;
  };

  // ── Empty state ────────────────────────────────────────────────────────────
  if (calibTotalSamples === 0) {
    container.innerHTML = `
      <div class="archive-empty-state" style="padding:40px 20px;text-align:center">
        <div class="archive-empty-icon">📈</div>
        <div class="archive-empty-text">
          No calibration data yet.<br><br>
          The calibration panel needs <b style="color:var(--text2)">AI lean snapshots</b> matched to
          <b style="color:var(--text2)">settled archive results</b>.<br>
          Load an event, let the analyzer generate picks, then settle results after the fights.
        </div>
      </div>`;
    return;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 1: Hero Score Ring + Summary
  // ═══════════════════════════════════════════════════════════════════════════
  const scoreColor = calibScore != null
    ? (calibScore >= 85 ? 'var(--green)' : calibScore >= 70 ? 'var(--amber)' : 'var(--red)')
    : 'var(--text-muted)';
  const scorePct = calibScore ?? 0;
  const scoreVerdict = calibScore == null ? 'Insufficient data'
    : calibScore >= 85 ? 'Excellent — confidence closely matches reality'
    : calibScore >= 70 ? 'Good — minor gaps between predicted and actual'
    : calibScore >= 55 ? 'Fair — noticeable overconfidence or underconfidence'
    : 'Needs work — confidence scores diverge from reality';
  const overallHitRate = calibTotalSamples > 0
    ? Math.round(calibBuckets.reduce((s, b) => s + b.hits, 0) / calibTotalSamples * 100) : 0;
  const eventCount = eventCalibMap.size;

  const heroHtml = `<div class="calib-hero">
    <div class="calib-score-ring" style="--calib-pct:${scorePct};--calib-color:${scoreColor}">
      <div class="calib-score-inner">
        <div class="calib-score-num" style="color:${scoreColor}">${calibScore ?? '—'}</div>
        <div class="calib-score-label">Calibration</div>
      </div>
    </div>
    <div class="calib-summary">
      <div class="calib-summary-title">Confidence Calibration</div>
      <div class="calib-summary-text">
        ${scoreVerdict}<br>
        <span style="color:var(--text-muted)">${calibTotalSamples} picks resolved across ${eventCount} event${eventCount === 1 ? '' : 's'} · Overall hit rate: <span style="color:${overallHitRate >= 55 ? 'var(--green)' : overallHitRate >= 45 ? 'var(--amber)' : 'var(--red)'};font-weight:700">${overallHitRate}%</span></span>
      </div>
    </div>
  </div>`;

  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 2: Calibration Curve (bar chart — same visual as archive)
  // ═══════════════════════════════════════════════════════════════════════════
  const maxBarH = 90;
  const activeBuckets = calibBuckets.filter(b => b.total > 0);
  const curveBarHtml = calibBuckets.map(b => {
    if (b.total === 0) return '';
    const actualRate = Math.round((b.hits / b.total) * 100);
    const predicted = b.midpoint;
    const diff = actualRate - predicted;
    const diffSign = diff > 0 ? '+' : '';
    const diffColor = Math.abs(diff) <= 5 ? 'var(--green)' : Math.abs(diff) <= 12 ? 'var(--amber)' : 'var(--red)';
    const predictedH = Math.round((predicted / 100) * maxBarH);
    const actualH = Math.round((actualRate / 100) * maxBarH);
    const actualColor = actualRate >= predicted - 3 ? 'var(--green)' : actualRate >= predicted - 12 ? 'var(--amber)' : 'var(--red)';
    const lowN = b.total < CALIB_THIN_N;
    return `<div style="display:flex;flex-direction:column;align-items:center;gap:2px;flex:1;min-width:42px">
      <div style="font-size:9px;color:${diffColor};font-weight:700${lowN ? ';opacity:0.5' : ''}">${diffSign}${diff}%</div>
      <div style="position:relative;width:100%;height:${maxBarH}px;display:flex;align-items:flex-end;justify-content:center">
        <div style="position:absolute;bottom:0;width:60%;height:${predictedH}px;background:rgba(125,145,190,0.12);border:1px dashed rgba(125,145,190,0.3);border-radius:3px" title="Predicted: ${predicted}%"></div>
        <div style="position:relative;width:50%;height:${actualH}px;background:${actualColor};opacity:${lowN ? 0.45 : 0.85};border-radius:4px 4px 2px 2px;box-shadow:0 0 10px ${actualColor};z-index:1" title="Actual: ${actualRate}% (${b.hits}/${b.total})"></div>
      </div>
      <div style="font-size:10px;font-weight:700;color:var(--text)">${actualRate}%</div>
      <div style="font-size:9px;color:var(--text-muted)">${b.rangeLabel}</div>
      <div style="font-size:8px;color:var(--text-muted);opacity:0.6">n=${b.total}</div>
    </div>`;
  }).filter(Boolean).join('');

  const curveHtml = activeBuckets.length >= 2
    ? `<div style="font-size:9px;color:var(--text-muted);margin-bottom:8px">Dashed = predicted confidence · Solid = actual hit rate · Green = well-calibrated</div>
       <div style="display:flex;gap:3px;align-items:flex-end;padding:6px 0 0 0">${curveBarHtml}</div>`
    : `<div class="archive-empty-state"><div class="archive-empty-icon">📊</div><div class="archive-empty-text">Need picks across at least 2 confidence ranges for a meaningful curve.</div></div>`;

  // Per-stat mini row
  const statMiniHtml = CALIB_STAT_TYPES.map(pt => {
    const buckets = calibByType[pt];
    const active = buckets.filter(b => b.total > 0);
    if (active.length < 1) return '';
    const label = pt === 'FightTime' ? 'FT' : pt === 'Fantasy' ? 'FP' : pt;
    const totalHits = active.reduce((s, b) => s + b.hits, 0);
    const totalN = active.reduce((s, b) => s + b.total, 0);
    const overallRate = totalN > 0 ? Math.round((totalHits / totalN) * 100) : 0;
    const dots = buckets.map(b => {
      if (b.total === 0) return `<div style="width:8px;height:8px;border-radius:50%;background:var(--surface2);border:1px solid rgba(125,145,190,0.15)" title="${b.rangeLabel}: no data"></div>`;
      const actual = Math.round((b.hits / b.total) * 100);
      const ddiff = Math.abs(actual - b.midpoint);
      const col = ddiff <= 5 ? 'var(--green)' : ddiff <= 12 ? 'var(--amber)' : 'var(--red)';
      return `<div style="width:8px;height:8px;border-radius:50%;background:${col};opacity:${b.total < 3 ? 0.4 : 0.85}" title="${b.rangeLabel}: ${actual}% actual (${b.hits}/${b.total})"></div>`;
    }).join('');
    const rateColor = overallRate >= 55 ? 'var(--green)' : overallRate >= 45 ? 'var(--amber)' : 'var(--red)';
    return `<div style="display:flex;align-items:center;gap:6px;padding:3px 0">
      <span style="font-size:10px;font-weight:700;min-width:18px;color:var(--text)">${label}</span>
      <div style="display:flex;gap:3px;align-items:center">${dots}</div>
      <span style="font-size:10px;color:${rateColor};margin-left:auto">${totalHits}/${totalN} (${overallRate}%)</span>
    </div>`;
  }).filter(Boolean).join('');

  const curveBody = curveHtml + (statMiniHtml ? `<div style="margin-top:10px;padding-top:8px;border-top:1px solid rgba(125,145,190,0.1)">
    <div style="font-size:9px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-bottom:4px">Per-Stat Calibration</div>
    ${statMiniHtml}
  </div>` : '');

  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 3: Overconfidence Diagnosis
  // ═══════════════════════════════════════════════════════════════════════════
  type DiagCard = { title: string; body: string; action: string; severity: 'green' | 'amber' | 'red'; badge: string };
  const diagCards: DiagCard[] = [];

  // Over/Under imbalance
  const overRate = overTotal > 0 ? Math.round((overHits / overTotal) * 100) : null;
  const underRate = underTotal > 0 ? Math.round((underHits / underTotal) * 100) : null;
  if (overRate !== null && underRate !== null && overTotal >= 5 && underTotal >= 5) {
    const gap = Math.abs(overRate - underRate);
    if (gap >= 15) {
      const weaker = overRate < underRate ? 'OVER' : 'UNDER';
      const weakerRate = overRate < underRate ? overRate : underRate;
      const strongerRate = overRate < underRate ? underRate : overRate;
      diagCards.push({
        title: `${weaker} Leans Underperforming`,
        body: `${weaker} picks hit at ${weakerRate}% vs ${strongerRate}% for the other side. The model may be systematically misjudging one direction.`,
        action: `Consider raising the confidence threshold for ${weaker} leans by ~${Math.round(gap / 2)} points before acting on them.`,
        severity: gap >= 25 ? 'red' : 'amber',
        badge: `${weakerRate}% hit`,
      });
    }
  }

  // Per-bucket overconfidence detection
  // ── GLOW-UP 247 — the diagnosis fires on the SHRUNK rate ────────────────
  // The curve above deliberately plots RAW hits/total; that is the honest picture
  // of what happened. But this panel turns those rates into ADVICE, and raw rates
  // in a thin cell are not evidence. On UFC 330's data an n=8 cell (5/8) produced
  // "85-89% Confidence is Overconfident, -24%, treat A-grade as C-grade" — sitting
  // beside an n=87 finding, styled identically and shouting louder for having the
  // bigger number. One fight flipping in that cell moves it 12 points.
  //
  // So the THRESHOLD now reads the same shrunk rate the recalibration engine
  // already applies (K=6 phantom observations at the bucket's own midpoint), while
  // the body still reports the raw hits/total, because what actually happened is
  // what you want to read. Effect on this data: the n=8 card stops firing (shrinks
  // to -14, under the bar) and the n=87 one survives at -16. Exactly the sort.
  for (const b of calibBuckets) {
    if (b.total < 5) continue;
    const actual = Math.round((b.hits / b.total) * 100);
    const shrunk = shrunkRecalRate(b.hits, b.total, b.midpoint);
    const diff = shrunk - b.midpoint;
    const rawDiff = actual - b.midpoint;
    // Named so the card can say when the raw number is louder than the evidence.
    const thin = Math.abs(rawDiff - diff) >= 5
      ? ` Raw is ${rawDiff > 0 ? '+' : ''}${rawDiff}pts on ${b.total} pick${b.total === 1 ? '' : 's'}; shrunk toward the model's own prior it is ${diff > 0 ? '+' : ''}${diff}, which is what this card is graded on.`
      : '';
    if (diff <= -15) {
      diagCards.push({
        title: `${b.rangeLabel} Confidence is Overconfident`,
        body: `Picks rated ${b.rangeLabel} confidence actually hit at only ${actual}% (${b.hits}/${b.total}). The model overestimates its certainty in this range by ${Math.abs(diff)} points.${thin}`,
        action: `Treat "${getConfidenceGrade(b.midpoint)}-grade" picks in this range as ${getConfidenceGrade(actual)}-grade. The recalibration engine below auto-corrects this.`,
        severity: diff <= -25 ? 'red' : 'amber',
        badge: `${diff > 0 ? '+' : ''}${diff}%`,
      });
    } else if (diff >= 10 && actual >= 60) {
      diagCards.push({
        title: `${b.rangeLabel} Confidence is Underconfident`,
        body: `Picks rated ${b.rangeLabel} actually hit at ${actual}% — the model is more accurate than it thinks here (+${diff}pts). These are hidden value picks.${thin}`,
        action: `This is good! Picks in this range are better than their confidence label suggests.`,
        severity: 'green',
        badge: `+${diff}%`,
      });
    }
  }

  // Per-stat-type diagnosis
  for (const pt of CALIB_STAT_TYPES) {
    const buckets = calibByType[pt];
    const active = buckets.filter(b => b.total >= 3);
    if (active.length < 2) continue;
    const totalHits = active.reduce((s, b) => s + b.hits, 0);
    const totalN = active.reduce((s, b) => s + b.total, 0);
    const overallRate = Math.round((totalHits / totalN) * 100);
    const avgPredicted = Math.round(active.reduce((s, b) => s + b.midpoint * b.total, 0) / totalN);
    // GLOW-UP 247: same treatment per stat type, plus a hard volume floor. TD on
    // UFC 330 read "Deflated by 41pts — hidden edge, high-value targets" off
    // 10/11. A 20-point gap is indistinguishable from luck at n=11, and calling
    // it a hidden edge invites staking into noise. 20 is the point where a gap
    // this size starts to mean something; below it the card simply stays quiet
    // rather than making a claim the sample cannot carry.
    const shrunkRate = shrunkRecalRate(totalHits, totalN, avgPredicted);
    const gap = shrunkRate - avgPredicted;
    const label = pt === 'FightTime' ? 'FT' : pt === 'Fantasy' ? 'FP' : pt;
    if (totalN < 20) continue;
    if (Math.abs(gap) >= 12) {
      diagCards.push({
        title: `${label} Confidence ${gap < 0 ? 'Inflated' : 'Deflated'} by ${Math.abs(gap)}pts`,
        body: `${label} picks: avg predicted ${avgPredicted}%, actual ${overallRate}% (${totalHits}/${totalN}). ${gap < 0 ? 'The model is overconfident on this stat type.' : 'The model is underconfident — hidden edge here.'}`,
        action: gap < 0
          ? `Subtract ~${Math.abs(gap)} from displayed ${label} confidence, or use the recalibrated values below.`
          : `${label} picks are stronger than labeled — these are high-value targets.`,
        severity: gap < 0 ? (gap <= -20 ? 'red' : 'amber') : 'green',
        badge: `${gap > 0 ? '+' : ''}${gap}%`,
      });
    }
  }

  // Overall calibration summary card
  if (calibScore != null && calibTotalSamples >= 10) {
    const avgPredicted = Math.round(calibBuckets.filter(b => b.total > 0).reduce((s, b) => s + b.midpoint * b.total, 0) / calibTotalSamples);
    if (overallHitRate < avgPredicted - 8) {
      diagCards.push({
        title: 'Systematic Overconfidence Detected',
        body: `Average predicted confidence is ${avgPredicted}% but actual hit rate is ${overallHitRate}%. The model is over-rating its edge by ${avgPredicted - overallHitRate} points overall.`,
        action: `Enable the recalibration engine (below) to auto-correct displayed confidence scores.`,
        severity: (avgPredicted - overallHitRate) >= 20 ? 'red' : 'amber',
        badge: `−${avgPredicted - overallHitRate}pts`,
      });
    } else if (overallHitRate > avgPredicted + 5) {
      diagCards.push({
        title: 'Model is Conservative',
        body: `Actual hit rate (${overallHitRate}%) exceeds average predicted confidence (${avgPredicted}%) by ${overallHitRate - avgPredicted} points. The model is underrating its edge.`,
        action: `Good sign — you can trust the confidence scores. Higher actual grades mean real edge.`,
        severity: 'green',
        badge: `+${overallHitRate - avgPredicted}pts`,
      });
    }
  }

  const sevColor = (s: string) => s === 'green' ? 'var(--green)' : s === 'amber' ? 'var(--amber)' : 'var(--red)';
  const diagHtml = diagCards.length > 0
    ? `<div class="calib-diag-grid">${diagCards.map(d => `
        <div class="calib-diag-card" style="--diag-color:${sevColor(d.severity)}">
          <div class="calib-diag-badge" style="background:${sevColor(d.severity)}22;color:${sevColor(d.severity)}">${d.badge}</div>
          <div class="calib-diag-title">${d.title}</div>
          <div class="calib-diag-body">${d.body}</div>
          <div class="calib-diag-action">→ ${d.action}</div>
        </div>`).join('')}
      </div>`
    : `<div style="font-size:11px;color:var(--text-muted);padding:12px 0">No significant calibration issues detected — confidence scores are reasonably accurate.</div>`;

  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 4: Temporal Calibration Trend
  // ═══════════════════════════════════════════════════════════════════════════
  const eventCalibArr = Array.from(eventCalibMap.values())
    .filter(e => e.total >= 2 && e.date > 0)
    .sort((a, b) => a.date - b.date);

  let trendHtml = '';
  if (eventCalibArr.length >= 2) {
    const svgW = 400;
    const svgH = 80;
    const padL = 4;
    const padR = 4;
    const plotW = svgW - padL - padR;

    // Compute running calibration score per event (cumulative Brier)
    let cumBrierSum = 0;
    let cumBrierN = 0;
    const trendPoints: Array<{ x: number; y: number; label: string; rate: number; n: number; brierScore: number }> = [];
    for (let i = 0; i < eventCalibArr.length; i++) {
      const e = eventCalibArr[i];
      const hitRate = Math.round((e.hits / e.total) * 100);
      cumBrierSum += e.brierSum;
      cumBrierN += e.total;
      const avgBrier = cumBrierSum / cumBrierN;
      const calScore = Math.round((1 - Math.sqrt(avgBrier)) * 100);
      const x = padL + (i / Math.max(1, eventCalibArr.length - 1)) * plotW;
      const y = svgH - 6 - (calScore / 100) * (svgH - 16);
      trendPoints.push({ x, y, label: e.event.replace(/UFC\s*(Fight Night|on ESPN):?\s*/i, '').trim(), rate: hitRate, n: e.total, brierScore: calScore });
    }

    // Smooth bezier path through points
    const smoothPath = (pts: typeof trendPoints): string => {
      if (pts.length < 2) return '';
      let d = `M${pts[0].x.toFixed(1)},${pts[0].y.toFixed(1)}`;
      for (let i = 1; i < pts.length; i++) {
        const prev = pts[i - 1];
        const curr = pts[i];
        const cpx = (prev.x + curr.x) / 2;
        d += ` C${cpx.toFixed(1)},${prev.y.toFixed(1)} ${cpx.toFixed(1)},${curr.y.toFixed(1)} ${curr.x.toFixed(1)},${curr.y.toFixed(1)}`;
      }
      return d;
    };
    const pathD = smoothPath(trendPoints);
    const lastPt = trendPoints[trendPoints.length - 1];
    const firstPt = trendPoints[0];
    const areaD = `${pathD} L${lastPt.x.toFixed(1)},${svgH} L${firstPt.x.toFixed(1)},${svgH} Z`;

    // Trend direction
    const first3 = trendPoints.slice(0, Math.min(3, trendPoints.length));
    const last3 = trendPoints.slice(-Math.min(3, trendPoints.length));
    const avgFirst = first3.reduce((s, p) => s + p.brierScore, 0) / first3.length;
    const avgLast = last3.reduce((s, p) => s + p.brierScore, 0) / last3.length;
    const trendDelta = Math.round(avgLast - avgFirst);
    const trendArrow = trendDelta > 3 ? '↑' : trendDelta < -3 ? '↓' : '→';
    const trendLabel = trendDelta > 3 ? 'Improving' : trendDelta < -3 ? 'Degrading' : 'Stable';
    const trendColor = trendDelta > 3 ? 'var(--green)' : trendDelta < -3 ? 'var(--red)' : 'var(--text-muted)';
    const trendColorHex = trendDelta > 3 ? '#20df8f' : trendDelta < -3 ? '#ff3a60' : '#7d91be';

    // Reference lines at 25, 50, 75
    const refLines = [25, 50, 75].map(val => {
      const ry = svgH - 8 - (val / 100) * (svgH - 20);
      return `<line x1="${padL}" y1="${ry.toFixed(1)}" x2="${svgW - padR}" y2="${ry.toFixed(1)}" stroke="rgba(125,145,190,0.10)" stroke-dasharray="3,4"/>
        <text x="${padL + 2}" y="${ry - 3}" fill="rgba(125,145,190,0.25)" font-size="7" font-family="'JetBrains Mono',monospace">${val}</text>`;
    }).join('');

    // Dots with score labels
    const dotsHtml = trendPoints.map((p, i) => {
      const col = p.brierScore >= 85 ? '#20df8f' : p.brierScore >= 70 ? '#f0c040' : '#ff3a60';
      const labelY = p.y < 30 ? p.y + 16 : p.y - 10;
      return `<g class="calib-trend-dot-group">
        <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="8" fill="${col}" opacity="0.12" class="calib-trend-dot-halo"/>
        <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="5" fill="${col}" stroke="rgba(10,14,24,0.8)" stroke-width="2" class="calib-trend-dot">
          <title>${p.label} — Score: ${p.brierScore} · Hit: ${p.rate}% · n=${p.n}</title>
        </circle>
        <text x="${p.x.toFixed(1)}" y="${labelY.toFixed(1)}" fill="${col}" font-size="8" font-weight="700" text-anchor="middle" font-family="'JetBrains Mono',monospace" class="calib-trend-score-label">${p.brierScore}</text>
      </g>`;
    }).join('');

    // Current score callout (last point)
    const currentScore = lastPt.brierScore;
    const currentColor = currentScore >= 85 ? 'var(--green)' : currentScore >= 70 ? 'var(--amber)' : 'var(--red)';

    trendHtml = `
      <div class="calib-trend-header">
        <div class="calib-trend-current">
          <div class="calib-trend-current-score" style="color:${currentColor}">${currentScore}</div>
          <div class="calib-trend-current-label">Current</div>
        </div>
        <div class="calib-trend-direction" data-trend="${trendDelta > 3 ? 'up' : trendDelta < -3 ? 'down' : 'stable'}">
          <span class="calib-trend-arrow" style="color:${trendColor}">${trendArrow}</span>
          <div>
            <div class="calib-trend-label" style="color:${trendColor}">${trendLabel}</div>
            <div class="calib-trend-delta">${trendDelta > 0 ? '+' : ''}${trendDelta} pts across ${eventCalibArr.length} events</div>
          </div>
        </div>
      </div>
      <div class="calib-trend-chart" style="height:130px">
        <svg class="calib-trend-svg" viewBox="0 0 ${svgW} ${svgH}" preserveAspectRatio="xMidYMid meet">
          <defs>
            <linearGradient id="calibTrendGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stop-color="${trendColorHex}" stop-opacity="0.30"/>
              <stop offset="50%" stop-color="${trendColorHex}" stop-opacity="0.08"/>
              <stop offset="100%" stop-color="${trendColorHex}" stop-opacity="0.01"/>
            </linearGradient>
            <linearGradient id="calibTrendStroke" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stop-color="${trendColorHex}" stop-opacity="0.5"/>
              <stop offset="50%" stop-color="${trendColorHex}" stop-opacity="1"/>
              <stop offset="100%" stop-color="${trendColorHex}" stop-opacity="0.8"/>
            </linearGradient>
            <filter id="calibLineGlow">
              <feGaussianBlur stdDeviation="3" result="blur"/>
              <feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge>
            </filter>
          </defs>
          ${refLines}
          <path d="${areaD}" fill="url(#calibTrendGrad)"/>
          <path d="${pathD}" fill="none" stroke="url(#calibTrendStroke)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" filter="url(#calibLineGlow)"/>
          ${dotsHtml}
        </svg>
      </div>
      <div class="calib-event-timeline">
        ${eventCalibArr.slice(-8).map((e, i) => {
          const rate = Math.round((e.hits / e.total) * 100);
          const col = rate >= 55 ? 'var(--green)' : rate >= 45 ? 'var(--amber)' : 'var(--red)';
          const colHex = rate >= 55 ? '#20df8f' : rate >= 45 ? '#f0c040' : '#ff3a60';
          const shortName = e.event.replace(/UFC\s*(Fight Night|on ESPN):?\s*/i, '').replace(/\s+/g, ' ').trim();
          return `<div class="calib-event-card" style="--event-color:${col};--event-color-hex:${colHex};animation-delay:${i * 0.04}s">
            <div class="calib-event-card-name" title="${e.event}">${shortName}</div>
            <div class="calib-event-card-rate"><span style="color:${col}">${rate}%</span> <span class="calib-event-card-ratio">hit</span></div>
            <div class="calib-event-card-bar"><div class="calib-event-card-fill" style="width:${rate}%;background:${col}"></div></div>
            <div class="calib-event-card-count">${e.hits}/${e.total}</div>
          </div>`;
        }).join('')}
      </div>`;
  } else {
    trendHtml = `<div style="font-size:11px;color:var(--text-muted);padding:12px 0">Need picks resolved across at least 2 events to show a trend.</div>`;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 5: Confidence Recalibration Engine Table
  // ═══════════════════════════════════════════════════════════════════════════
  const recalRows = calibBuckets.filter(b => b.total >= 3).map(b => {
    const rawRate = Math.round((b.hits / b.total) * 100);      // honest empirical hit rate
    const applied = shrunkRecalRate(b.hits, b.total, b.midpoint); // what the engine actually applies (shrunk toward prior)
    const delta = applied - b.midpoint;
    const origGrade = getConfidenceGrade(b.midpoint);
    const newGrade = getConfidenceGrade(applied);
    const deltaColor = delta > 0 ? 'var(--green)' : delta < -5 ? 'var(--red)' : 'var(--amber)';
    const gradeChanged = origGrade !== newGrade;
    return `<tr>
      <td>${b.rangeLabel}</td>
      <td style="text-align:center">${b.midpoint}%</td>
      <td style="text-align:center"><span class="calib-recal-arrow">→</span><span class="calib-recal-adjusted" style="color:${deltaColor}">${applied}%</span><br><span style="font-size:9px;color:var(--text-muted)" title="Raw empirical hit rate before shrinkage toward the confidence prior">raw ${rawRate}%</span></td>
      <td style="text-align:center"><span class="calib-recal-delta" style="color:${deltaColor}">${delta > 0 ? '+' : ''}${delta}</span></td>
      <td style="text-align:center">${origGrade}${gradeChanged ? ` <span class="calib-recal-arrow">→</span> <span style="color:${deltaColor};font-weight:700">${newGrade}</span>` : ''}</td>
      <td style="text-align:center;color:var(--text-muted)">${b.total}</td>
    </tr>`;
  });

  // Per-stat recalibration summary
  const perStatRecalHtml = CALIB_STAT_TYPES.map(pt => {
    const buckets = calibByType[pt];
    const eligible = buckets.filter(b => b.total >= 3);
    if (eligible.length < 2) return '';
    const label = pt === 'FightTime' ? 'FT' : pt === 'Fantasy' ? 'FP' : pt;
    const rows = eligible.map(b => {
      const applied = shrunkRecalRate(b.hits, b.total, b.midpoint);
      const rawRate = Math.round((b.hits / b.total) * 100);
      const delta = applied - b.midpoint;
      const col = delta > 0 ? 'var(--green)' : delta < -5 ? 'var(--red)' : 'var(--amber)';
      return `<span style="font-size:10px;padding:2px 6px;border-radius:4px;background:var(--surface2)" title="Raw empirical hit rate: ${rawRate}% (${b.hits}/${b.total}); shrunk toward the ${b.midpoint}% prior">${b.rangeLabel}: <span style="color:${col};font-weight:600">${applied}%</span> <span style="color:${col};font-size:9px">(${delta > 0 ? '+' : ''}${delta})</span></span>`;
    }).join(' ');
    return `<div style="margin-top:8px"><span style="font-size:10px;font-weight:700;color:var(--text);margin-right:6px">${label}:</span>${rows}</div>`;
  }).filter(Boolean).join('');

  const recalHtml = recalRows.length >= 2
    ? `<div style="font-size:10px;color:var(--text-muted);margin-bottom:8px">
        The recalibration engine adjusts displayed confidence based on historical accuracy.<br>
        When active, a pick labeled "80% confidence" that historically hits at 65% will display as "65% (recalibrated)".
      </div>
      <table class="calib-recal-table">
        <thead><tr>
          <th>Range</th><th style="text-align:center">Predicted</th><th style="text-align:center">Recalibrated</th>
          <th style="text-align:center">Delta</th><th style="text-align:center">Grade</th><th style="text-align:center">N</th>
        </tr></thead>
        <tbody>${recalRows.join('')}</tbody>
      </table>
      ${perStatRecalHtml}
      <div style="margin-top:12px;padding:10px 14px;border-radius:6px;background:rgba(0,232,122,0.06);border:1px solid rgba(0,232,122,0.2);font-size:10px;color:var(--text3)">
        <span style="color:var(--green);font-weight:700">Recalibration Active</span> — Fighter cards now show recalibrated confidence when data is available. The original confidence is preserved in tooltips.
      </div>`
    : `<div style="font-size:11px;color:var(--text-muted);padding:12px 0">Need at least 3 resolved picks in 2+ confidence buckets to build a recalibration table.</div>`;

  // ═══════════════════════════════════════════════════════════════════════════
  // ═══════════════════════════════════════════════════════════════════════════
  // SECTION 6: Platform Line Bias Tracker
  // ═══════════════════════════════════════════════════════════════════════════
  // Recompute bias from the same archive data we already loaded (no extra fetch)
  const biasMap = new Map<string, { platform: string; propType: string; hits: number; total: number; edgeSum: number }>();
  // ONE observation per book per market. Counting rows is right in principle here — unlike
  // the hit-rate leaderboards, each BOOK posting its own number genuinely is a separate
  // observation of that book pricing that fight. What is not separate is the SAME book,
  // same fighter, same fight appearing twice because the card is filed under two event
  // names (a live case carried 4 event names across 2 dates). That is one market counted
  // twice, and it silently overweights whichever fights happened to be captured under a
  // shadow name. First row wins, matching the archive index invariant documented above.
  for (const r of dedupeBiasRows(allRows.filter(r => !!r.platform && Number.isFinite(Number(r.line)) && Number.isFinite(Number(r.result)) && Date.parse(r.date) >= londonTs))) {
    const key = `${String(r.platform).toLowerCase()}|${r.propType}`;
    const b = biasMap.get(key) || { platform: String(r.platform).toLowerCase(), propType: String(r.propType), hits: 0, total: 0, edgeSum: 0 };
    const normResult = normalizeArchiveResult(String(r.propType), Number(r.result));
    b.total++;
    b.edgeSum += normResult - Number(r.line);
    if (normResult > Number(r.line)) b.hits++;
    biasMap.set(key, b);
  }
  const biasEntries = Array.from(biasMap.values())
    .filter(b => b.total >= 2)
    .map(b => ({ ...b, avgEdge: Number((b.edgeSum / b.total).toFixed(1)), hitRate: Math.round((b.hits / b.total) * 100) }));

  // Also update the module-level cache
  _platformBiasCache = biasEntries;

  // Group by platform for report cards
  const PLAT_ORDER = ['pick6', 'underdog', 'prizepicks', 'betr', 'draftkings_sportsbook'];
  const STAT_ORDER = ['Fantasy', 'SS', 'TD', 'FightTime'];
  const STAT_SHORT: Record<string, string> = { Fantasy: 'FP', SS: 'SS', TD: 'TD', FightTime: 'FT' };
  const PLAT_COLORS: Record<string, string> = {
    pick6: BOOK_COLORS.p6, underdog: BOOK_COLORS.ud, prizepicks: BOOK_COLORS.pp,
    betr: BOOK_COLORS.betr, draftkings_sportsbook: BOOK_COLORS.dk,
  };

  // Per-platform overall stats
  const platOverall = new Map<string, { hits: number; total: number; edgeSum: number }>();
  for (const b of biasEntries) {
    const o = platOverall.get(b.platform) || { hits: 0, total: 0, edgeSum: 0 };
    o.hits += b.hits; o.total += b.total; o.edgeSum += b.edgeSum;
    platOverall.set(b.platform, o);
  }

  // Best platform per stat+direction
  type BestPick = { stat: string; direction: 'OVER' | 'UNDER'; platform: string; avgEdge: number; total: number };
  const bestPicks: BestPick[] = [];
  for (const stat of STAT_ORDER) {
    const statEntries = biasEntries.filter(b => b.propType === stat && b.total >= 3);
    if (statEntries.length < 2) continue;
    // Best for OVER = highest positive avg edge (result beats line most)
    const sortedOver = [...statEntries].sort((a, b) => b.avgEdge - a.avgEdge);
    if (sortedOver[0].avgEdge > 0) {
      bestPicks.push({ stat, direction: 'OVER', platform: sortedOver[0].platform, avgEdge: sortedOver[0].avgEdge, total: sortedOver[0].total });
    }
    // Best for UNDER = most negative avg edge (result below line most)
    const sortedUnder = [...statEntries].sort((a, b) => a.avgEdge - b.avgEdge);
    if (sortedUnder[0].avgEdge < 0) {
      bestPicks.push({ stat, direction: 'UNDER', platform: sortedUnder[0].platform, avgEdge: sortedUnder[0].avgEdge, total: sortedUnder[0].total });
    }
  }

  // Build platform report cards
  const platCardHtml = PLAT_ORDER.filter(p => platOverall.has(p)).map(plat => {
    const o = platOverall.get(plat)!;
    const label = PLAT_LABEL_MAP[plat] || plat.toUpperCase();
    const color = PLAT_COLORS[plat] || 'var(--text)';
    const overallEdge = Number((o.edgeSum / o.total).toFixed(1));
    const overallRate = Math.round((o.hits / o.total) * 100);
    const edgeColor = overallEdge > 0.5 ? 'var(--green)' : overallEdge < -0.5 ? 'var(--red)' : 'var(--text-muted)';
    const softness = overallEdge > 1.5 ? 'Soft' : overallEdge > 0.3 ? 'Slightly Soft' : overallEdge < -1.5 ? 'Tight' : overallEdge < -0.3 ? 'Slightly Tight' : 'Neutral';

    // Per-stat bars
    const maxAbsEdge = Math.max(1, ...biasEntries.filter(b => b.platform === plat).map(b => Math.abs(b.avgEdge)));
    const statBars = STAT_ORDER.map(st => {
      const entry = biasEntries.find(b => b.platform === plat && b.propType === st);
      if (!entry || entry.total < 2) return `<div class="bias-stat-row"><span class="bias-stat-label">${STAT_SHORT[st]}</span><div class="bias-bar-track"><div class="bias-bar-empty">—</div></div></div>`;
      const pct = Math.round(Math.abs(entry.avgEdge) / maxAbsEdge * 70);
      const isPos = entry.avgEdge >= 0;
      const barColor = isPos ? 'var(--green)' : 'var(--red)';
      const hint = isPos
        ? `Lines avg ${entry.avgEdge} pts below actual — soft for OVER`
        : `Lines avg ${Math.abs(entry.avgEdge)} pts above actual — soft for UNDER`;
      return `<div class="bias-stat-row" title="${hint}">
        <span class="bias-stat-label">${STAT_SHORT[st]}</span>
        <div class="bias-bar-track">
          <div class="bias-bar-fill ${isPos ? 'positive' : 'negative'}" style="width:${pct}%;background:${barColor}"></div>
        </div>
        <span class="bias-stat-edge" style="color:${barColor}">${isPos ? '+' : ''}${entry.avgEdge}</span>
        <span class="bias-stat-n">${entry.total}</span>
      </div>`;
    }).join('');

    return `<div class="bias-plat-card" style="--plat-color:${color}">
      <div class="bias-plat-header">
        <span class="bias-plat-name" style="color:${color}">${label}</span>
        <span class="bias-plat-softness" style="color:${edgeColor}">${softness}</span>
      </div>
      <div class="bias-plat-overview">
        <span class="bias-plat-stat">Avg Edge: <b style="color:${edgeColor}">${overallEdge > 0 ? '+' : ''}${overallEdge}</b></span>
        <span class="bias-plat-stat">Over Rate: <b style="color:${overallRate >= 55 ? 'var(--green)' : overallRate >= 45 ? 'var(--amber)' : 'var(--red)'}">${overallRate}%</b></span>
        <span class="bias-plat-stat" style="color:var(--text-muted)">${o.total} props</span>
      </div>
      ${statBars}
    </div>`;
  }).join('');

  // Edge Finder — best platform recommendations
  const edgeFinderHtml = bestPicks.length > 0
    ? `<div class="bias-edge-finder">
        <div style="font-size:9px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-bottom:8px">Edge Finder — Best Platform by Stat + Direction</div>
        <div class="bias-edge-grid">${bestPicks.map(bp => {
          const label = PLAT_LABEL_MAP[bp.platform] || bp.platform.toUpperCase();
          const color = PLAT_COLORS[bp.platform] || 'var(--text)';
          const dirColor = bp.direction === 'OVER' ? 'var(--green)' : 'var(--red)';
          const arrow = bp.direction === 'OVER' ? '▲' : '▼';
          return `<div class="bias-edge-chip">
            <span class="bias-edge-dir" style="color:${dirColor}">${arrow} ${bp.direction}</span>
            <span class="bias-edge-stat">${STAT_SHORT[bp.stat]}</span>
            <span class="bias-edge-arrow">→</span>
            <span class="bias-edge-plat" style="color:${color};font-weight:700">${label}</span>
            <span class="bias-edge-val" style="color:${bp.avgEdge > 0 ? 'var(--green)' : 'var(--red)'}">${bp.avgEdge > 0 ? '+' : ''}${bp.avgEdge} avg edge</span>
            <span class="bias-edge-n">${bp.total}</span>
          </div>`;
        }).join('')}</div>
      </div>`
    : '';

  // Heatmap — all platforms × all stats
  const heatmapHtml = (() => {
    const activePlats = PLAT_ORDER.filter(p => biasEntries.some(b => b.platform === p));
    const activeStats = STAT_ORDER.filter(s => biasEntries.some(b => b.propType === s));
    if (activePlats.length < 2 || activeStats.length < 2) return '';
    const headerCells = activePlats.map(p => `<th style="color:${PLAT_COLORS[p] || 'var(--text)'}">${PLAT_LABEL_MAP[p] || p.toUpperCase()}</th>`).join('');
    const rows = activeStats.map(st => {
      const cells = activePlats.map(p => {
        const entry = biasEntries.find(b => b.platform === p && b.propType === st);
        if (!entry || entry.total < 2) return `<td class="bias-heat-cell empty">—</td>`;
        const e = entry.avgEdge;
        const intensity = Math.min(1, Math.abs(e) / 4);
        const bg = e >= 0
          ? `rgba(0,232,122,${(intensity * 0.35).toFixed(2)})`
          : `rgba(255,58,96,${(intensity * 0.35).toFixed(2)})`;
        const textColor = Math.abs(e) > 1.5 ? (e > 0 ? 'var(--green)' : 'var(--red)') : 'var(--text)';
        const hint = e >= 0
          ? `${PLAT_LABEL_MAP[p]} ${STAT_SHORT[st]} lines avg ${e} below actual (soft for OVER)`
          : `${PLAT_LABEL_MAP[p]} ${STAT_SHORT[st]} lines avg ${Math.abs(e)} above actual (soft for UNDER)`;
        return `<td class="bias-heat-cell" style="background:${bg};color:${textColor}" title="${hint} · n=${entry.total}">${e > 0 ? '+' : ''}${e}<span class="bias-heat-n">${entry.total}</span></td>`;
      }).join('');
      return `<tr><td class="bias-heat-label">${STAT_SHORT[st]}</td>${cells}</tr>`;
    }).join('');
    return `<div style="margin-top:12px">
      <div style="font-size:9px;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.08em;margin-bottom:6px">Avg Edge Heatmap (green = soft for over · red = soft for under)</div>
      <table class="bias-heatmap"><thead><tr><th></th>${headerCells}</tr></thead><tbody>${rows}</tbody></table>
    </div>`;
  })();

  const biasTrackerBody = biasEntries.length >= 2
    ? `${edgeFinderHtml}
       <div class="bias-plat-grid">${platCardHtml}</div>
       ${heatmapHtml}`
    : `<div style="font-size:11px;color:var(--text-muted);padding:12px 0">Need settled archive records with platform data across at least 2 platforms to show bias analysis.</div>`;

  const biasTrackerCount = `<span style="font-size:10px;color:var(--text-muted)">${platOverall.size} platform${platOverall.size === 1 ? '' : 's'} · ${biasEntries.reduce((s, b) => s + b.total, 0)} settled props</span>`;

  // ASSEMBLE FULL PANEL
  // ═══════════════════════════════════════════════════════════════════════════
  container.innerHTML = `
    ${heroHtml}
    ${cSec('cal-curve', 'Calibration Curve', `<span style="font-size:10px;color:var(--text-muted)">${calibTotalSamples} picks · ${activeBuckets.length} buckets</span>`, curveBody, 'margin-bottom:12px')}
    ${cSec('cal-diagnosis', 'Overconfidence Diagnosis', `<span style="font-size:10px;color:var(--text-muted)">${diagCards.length} finding${diagCards.length === 1 ? '' : 's'}</span>`, diagHtml, 'margin-bottom:12px')}
    ${cSec('cal-trend', 'Calibration Trend', `<span style="font-size:10px;color:var(--text-muted)">${eventCalibArr.length} events</span>`, trendHtml, 'margin-bottom:12px')}
    ${cSec('cal-recal', 'Recalibration Engine', `<span style="font-size:10px;color:var(--text-muted)">${recalRows.length} bucket${recalRows.length === 1 ? '' : 's'} mapped</span>`, recalHtml, 'margin-bottom:12px')}
    ${cSec('cal-bias', 'Platform Line Bias Tracker', biasTrackerCount, biasTrackerBody, 'margin-bottom:12px')}
  `;

  // Bind collapsible section toggles
  container.querySelectorAll<HTMLElement>('.best-picks-header').forEach(header => {
    header.addEventListener('click', () => {
      const section = header.closest<HTMLElement>('.best-picks-section');
      const id = section?.dataset['sectionId'];
      if (!section || !id) return;
      const body = section.querySelector<HTMLElement>('.section-body');
      if (!body) return;
      if (_archiveCollapsedSections.has(id)) {
        _archiveCollapsedSections.delete(id);
        section.classList.remove('collapsed');
        body.style.maxHeight = body.scrollHeight + 'px';
        body.addEventListener('transitionend', function handler() { body.style.maxHeight = ''; body.removeEventListener('transitionend', handler); }, { once: true });
      } else {
        _archiveCollapsedSections.add(id);
        body.style.maxHeight = body.scrollHeight + 'px';
        void body.offsetHeight;
        section.classList.add('collapsed');
        body.style.maxHeight = '0';
      }
    });
  });

  buildDataSubNav(container);
}

// ── GLOW-UP 194: Lean Over/Under triage surface ──────────────────────────────
// Turns the directional filter views from "the same full cards, filtered" into a
// purpose-built triage: conviction order (L2), a command header (L1), compact
// rows (L3), same-fight correlation flags (L4), and one-click add-to-slip (L5).
let _leanCompact = false; // L3 compact-density toggle (per-session)
const _leanSlateData = new Map<string, BestPicksSlatePick>(); // L5 staging for add-to-slip

// Per-stat book fields in preference order (full SourcePlatformKey → line field).
const LEAN_STAT_FIELDS: Record<string, Array<[string, keyof AnalyzerFighter]>> = {
  fp:    [['pick6','line_p6'],['underdog','line_ud'],['betr','line_betr'],['prizepicks','line_pp']],
  ss:    [['pick6','line_p6_ss'],['underdog','line_ud_ss'],['prizepicks','line_pp_ss'],['betr','line_betr_ss'],['draftkings_sportsbook','line_dk_ss']],
  ss_r1: [['prizepicks','line_pp_ss_r1'],['underdog','line_ud_ss_r1'],['draftkings_sportsbook','line_dk_ss_r1']],
  td:    [['pick6','line_p6_td'],['underdog','line_ud_td'],['prizepicks','line_pp_td'],['betr','line_betr_td'],['draftkings_sportsbook','line_dk_td']],
  ft:    [['prizepicks','line_pp_ft'],['draftkings_sportsbook','line_dk_ft'],['underdog','line_ud_ft'],['pick6','line_p6_ft'],['betr','line_betr_ft']],
  ctrl:  [['pick6','line_p6_ctrl'],['underdog','line_ud_ctrl'],['prizepicks','line_pp_ctrl'],['betr','line_betr_ctrl'],['draftkings_sportsbook','line_dk_ctrl']],
  kd:    [['prizepicks','line_pp_kd']],
};
const LEAN_BOOK_LABEL: Record<string, string> = { pick6:'Pick6', underdog:'Underdog', prizepicks:'PrizePicks', betr:'Betr', draftkings_sportsbook:'DK' };

// The confidence a row actually DISPLAYS (raw model conf → CLV boost →
// recalibration), so conviction rank + header tiers match the number on screen.
// Mirrors the pipeline in buildFighterRow.
function displayedConfFor(f: AnalyzerFighter, lean: EffectiveLean): number {
  const raw = lean.conf || 0;
  if (raw <= 0) return 0;
  const clv = getClvBoost(f, lean);
  const boosted = clv ? Math.max(25, Math.min(90, raw + clv.delta)) : raw;
  const recal = getRecalibratedConfidence(boosted, lean._source);
  return recal != null ? recal : boosted;
}

// Takes the lean explicitly because the snapshot writers log a SPECIFIC lean (the column
// the pick was built from), which is not always getEffectiveLean(f).
function getDisplayedConf(f: AnalyzerFighter): number {
  return displayedConfFor(f, getEffectiveLean(f));
}

// Per-book UNDER-side availability for stat props. MUST stay in sync with
// renderBestPicks' ssUnderBookOffered / tdUnderBookOffered — it's the same rule,
// reused here so leanBestBook and the effective-lean fall-through can't surface an
// unplaceable under (e.g. a Pick6 TD under, which is More/OVER-only unless a Less
// button is confirmed, or a non-favorite's Pick6 SS under).
function statUnderBookOffered(f: AnalyzerFighter, source: string, book: string): boolean {
  if (source === 'ss') {
    if (book === 'draftkings_sportsbook' || book === 'prizepicks' || book === 'betr') return true;
    const dog = isMoneylineUnderdog(f);
    if (book === 'underdog') return dog;     // UD: under only for underdogs
    if (book === 'pick6') return !dog;       // Pick6: under only for favorites
    return true;
  }
  if (source === 'td') {
    if (book === 'pick6') return (f.td_under_available ?? null) === true;   // More-only unless Less confirmed
    if (book === 'underdog') return (f.ud_td_under_avail ?? null) !== false;
    return true;
  }
  if (source === 'kd') return (f.kd_under_available ?? null) === true;      // PP demon/goblin = More-only
  return true; // ft / ctrl / ss_r1: no per-book under gating modeled (matches Best Picks)
}

// GLOW-UP 195 L3 — per-book placement breakdown for a lean's direction: which books
// will take it, and which have a line but block the side (or price it as chalk).
// Same rules as leanBestBook, but it reports the WHY instead of just picking one.
function placementDetail(f: AnalyzerFighter, source: string, dir: 'over' | 'under'): { ok: string[]; blocked: string[] } {
  const ok: string[] = [], blocked: string[] = [];
  for (const [bk, fld] of (LEAN_STAT_FIELDS[source] || [])) {
    const v = (f as unknown as Record<string, unknown>)[fld as string] as number | null;
    if (v == null || !Number.isFinite(v)) continue;
    const label = LEAN_BOOK_LABEL[bk] || bk;
    if (source === 'fp') {
      if (shouldSkipFpSideForFighter(f, 'fp', dir, bk as SourcePlatformKey)) { blocked.push(`${label} (${dir} not offered)`); continue; }
    } else if (dir === 'under' && !statUnderBookOffered(f, source, bk)) {
      blocked.push(`${label} (no under side)`); continue;
    }
    if (bk === 'draftkings_sportsbook' && dkSideChalk(f, source, dir)) {
      const o = dkSideOdds(f, source, dir);
      blocked.push(`${label} (${o != null ? fmtOdds(o) : 'chalk'} — chalk)`); continue;
    }
    ok.push(`${label} ${v}`);
  }
  return { ok, blocked };
}

// Placement chip for a lean panel title: the resolved best book, or a NO BOOK flag
// when every book with a line blocks the side. Hover lists the full breakdown.
function buildPlacementChip(f: AnalyzerFighter, source: string, dir: string | null | undefined): string {
  if (dir !== 'over' && dir !== 'under') return '';
  const { ok, blocked } = placementDetail(f, source, dir);
  const best = leanBestBook(f, source, dir);
  const blockedTxt = blocked.length ? ` · Blocked: ${blocked.join(', ')}` : '';
  if (best.book == null) {
    return `<span class="place-chip blocked" title="No book takes this ${dir.toUpperCase()}${blockedTxt || ' (no line posted)'}">⛔ NO BOOK</span>`;
  }
  const label = LEAN_BOOK_LABEL[best.book] || best.book;
  return `<span class="place-chip ok" title="Best placeable entry for this ${dir.toUpperCase()}: ${label} ${best.line}${ok.length > 1 ? ` · Also takes it: ${ok.filter(o => !o.startsWith(label)).join(', ')}` : ''}${blockedTxt}">✔ ${label} ${best.line}</span>`;
}

// GLOW-UP 195 — the line-grid source keys → canonical book keys.
const LINE_SRC_TO_BOOK: Record<string, SourcePlatformKey> = {
  p6: 'pick6', ud: 'underdog', pp: 'prizepicks', betr: 'betr', dk: 'draftkings_sportsbook',
};

// Which SIDES a book actually offers for a stat on this fighter. These rules already
// existed (they gate Best Picks and the directional views) but the line grid never
// showed them — a cell could read "P6 TD 0.5" with no hint that only the OVER is
// takeable there. Conservative by design: a side is only reported unavailable when a
// rule or a positively-false flag says so (UD's avail flags fail open — see
// project_underdog_api_quirks).
function sideAvailability(
  f: AnalyzerFighter,
  stat: 'fp'|'ss'|'td'|'ft'|'ctrl',
  book: SourcePlatformKey,
): { over: boolean; under: boolean } {
  if (stat === 'fp') {
    return {
      over:  !shouldSkipFpSideForFighter(f, 'fp', 'over', book),
      under: !shouldSkipFpSideForFighter(f, 'fp', 'under', book),
    };
  }
  if (stat === 'ctrl') {
    // Pick6 CTRL is sometimes OVER-only; calcCTRLLean already suppresses the lean.
    return { over: true, under: book === 'pick6' ? (f.ctrl_under_available ?? null) !== false : true };
  }
  if (stat === 'ft') {
    if (book === 'underdog') {
      return { over: (f.ud_ft_over_avail ?? null) !== false, under: (f.ud_ft_under_avail ?? null) !== false };
    }
    return { over: true, under: true };
  }
  // ss / td — under side via the authoritative shared rule; over side only marked
  // unavailable when UD explicitly recorded it false.
  let over = true;
  if (book === 'underdog') {
    if (stat === 'ss') over = (f.ud_ss_over_avail ?? null) !== false;
    if (stat === 'td') over = (f.ud_td_over_avail ?? null) !== false;
  }
  return { over, under: statUnderBookOffered(f, stat, book) };
}

// DK is the only book with real American odds, so it's the only one that can post
// a "chalk" side with no value even when placeable. Exclude DK sides at -300 or
// worse (a -5000 TD under etc.); -299 and better is fine. Pick-em books carry no
// American odds, so this only ever gates DK candidates.
const DK_CHALK_THRESHOLD = -300;
function dkSideOdds(f: AnalyzerFighter, source: string, dir: string): number | null {
  const field =
      source === 'ss'    ? (dir === 'over' ? 'ss_over_odds'    : 'ss_under_odds')
    : source === 'ss_r1' ? (dir === 'over' ? 'ss_r1_over_odds' : 'ss_r1_under_odds')
    : source === 'td'    ? (dir === 'over' ? 'td_over_odds'    : 'td_under_odds')
    : source === 'ft'    ? (dir === 'over' ? 'ft_over_odds'    : 'ft_under_odds')
    : source === 'ctrl'  ? (dir === 'over' ? 'ctrl_over_odds'  : 'ctrl_under_odds')
    : null;
  if (!field) return null;
  const odds = (f as unknown as Record<string, unknown>)[field] as number | null;
  return odds != null && Number.isFinite(odds) ? odds : null;
}
function fmtOdds(o: number): string { return o > 0 ? `+${o}` : String(o); }
function dkSideChalk(f: AnalyzerFighter, source: string, dir: string): boolean {
  const odds = dkSideOdds(f, source, dir);
  return odds != null && odds <= DK_CHALK_THRESHOLD;
}

/**
 * GLOW-UP 212 — FP scoring families. Fantasy lines are comparable ONLY within a
 * family, because comparing them means comparing the same underlying number.
 * PrizePicks scores fantasy points differently from everyone else — the archive
 * has always split it (`Fantasy` vs `Fantasy_PP`) — so a PP line is a different
 * prop and can never be shopped against the others. Pick6, Underdog and Betr
 * share one scoring system (confirmed by the user 2026-08-13), so those three ARE
 * comparable, and the best line among them is real, free edge.
 */
const FP_SCORING_FAMILY: Record<string, string> = {
  pick6: 'standard', underdog: 'standard', betr: 'standard', prizepicks: 'pp',
};

// Best entry book+line for a lean's stat/direction (over → lowest line, under →
// highest), mirroring the card's best-shop logic for the add-to-slip payload.
function leanBestBook(f: AnalyzerFighter, source: string, dir: string): { book: string | null; line: number | null } {
  // FP-under placeability varies by book — a dog's FP UNDER is placeable ONLY on
  // Underdog (Pick6/PP/Betr block it) — so candidates are filtered by the real
  // placeability rule before any line comparison.
  //
  // GLOW-UP 212: FP is now line-shopped WITHIN its scoring family. This used to
  // return the first placeable book by priority on the belief that FP lines were
  // never comparable; that is only true of PrizePicks. Pick6/Underdog/Betr share
  // scoring, so taking the first by priority quietly handed over real value —
  // Joel Alvarez's FP OVER resolved to Pick6 93.5 while Betr had 85.5 on the same
  // scoring, 8 points given away on one pick.
  if (source === 'fp') {
    const fpBooks: Array<[string, keyof AnalyzerFighter]> = [
      ['pick6', 'line_p6'], ['underdog', 'line_ud'], ['prizepicks', 'line_pp'], ['betr', 'line_betr'],
    ];
    // Active platform first — now purely the TIE-BREAK, since reduce below keeps
    // the earlier candidate when lines are equal.
    const ordered = fpBooks.slice().sort((a, b) =>
      (b[0] === currentPlatform ? 1 : 0) - (a[0] === currentPlatform ? 1 : 0));
    const placeable = ordered
      .map(([bk, fld]) => ({ bk, val: Number((f as unknown as Record<string, unknown>)[fld as string]) , has: (f as unknown as Record<string, unknown>)[fld as string] != null }))
      .filter(c => c.has && Number.isFinite(c.val)
        && !shouldSkipFpSideForFighter(f, 'fp' as LeanSource, dir as 'over' | 'under', c.bk as SourcePlatformKey));
    if (!placeable.length) return { book: null, line: null };
    const familyOf = (bk: string): string => FP_SCORING_FAMILY[bk] || 'standard';
    // Shop within the family the user is actually entering on. If the active
    // platform's family has nothing placeable, fall back to the standard three
    // rather than silently offering a PP line as if it were the same prop.
    const activeFamily = familyOf(currentPlatform);
    const inActive = placeable.filter(c => familyOf(c.bk) === activeFamily);
    const inStandard = placeable.filter(c => familyOf(c.bk) === 'standard');
    const cands = inActive.length ? inActive : (inStandard.length ? inStandard : placeable);
    const best = dir === 'over'
      ? cands.reduce((a, b) => (b.val < a.val ? b : a))
      : cands.reduce((a, b) => (b.val > a.val ? b : a));
    return { book: best.bk, line: best.val };
  }
  const fields = LEAN_STAT_FIELDS[source] || [];
  const cands = fields
    .map(([bk, fld]) => ({ bk, val: (f as unknown as Record<string, unknown>)[fld as string] as number | null }))
    .filter((c): c is { bk: string; val: number } => c.val != null && Number.isFinite(c.val)
      // Drop books that don't offer the UNDER side (e.g. Pick6 TD-under is More-only).
      && !(dir === 'under' && !statUnderBookOffered(f, source, c.bk))
      // Drop DK chalk sides (-300 or worse) — placeable but no value.
      && !(c.bk === 'draftkings_sportsbook' && dkSideChalk(f, source, dir)));
  if (!cands.length) return { book: null, line: null };
  const best = dir === 'over'
    ? cands.reduce((a, b) => (b.val < a.val ? b : a))
    : cands.reduce((a, b) => (b.val > a.val ? b : a));
  return { book: best.bk, line: best.val };
}

/**
 * Build a slate pick for an EXPLICIT stat + side, rather than for whatever the
 * model happens to lean. Every add-to-slate entry point used to derive its
 * direction from the lean, so the opposite side of a prop was simply unreachable:
 * Donte Johnson SS 34.5 leans UNDER, and there was no control anywhere that
 * produced the OVER. The user's read is allowed to disagree with the model's.
 *
 * `leanBestBook` is already direction-aware (lowest line wins an OVER, highest
 * wins an UNDER), so asking it for the other side returns the correct entry —
 * nothing about line selection needed changing, only the ability to ask.
 */
/** One specific book's line for a stat, or null when that book hasn't posted it. */
function lineForBook(f: AnalyzerFighter, source: string, book: string): number | null {
  const entry = (LEAN_STAT_FIELDS[source] || []).find(([bk]) => bk === book);
  if (!entry) return null;
  const v = (f as unknown as Record<string, unknown>)[entry[1] as string] as number | null;
  return v != null && Number.isFinite(Number(v)) ? Number(v) : null;
}

/**
 * GLOW-UP 211 — `bookOverride` targets ONE book instead of letting leanBestBook
 * resolve it.
 *
 * Needed because FP is the one stat that cannot be line-shopped: each book scores
 * fantasy points differently, so Pick6 93.5 and Betr 85.5 are not the same prop
 * measured twice — they're two different props. leanBestBook therefore returns the
 * FIRST PLACEABLE book by priority rather than a min/max, which is correct, but it
 * left every other book's FP line unreachable: wanting Joel Alvarez's Betr OVER at
 * 85.5 got you the Pick6 OVER at 93.5 and no way to ask for the other one.
 *
 * The key only gains a `|book` suffix when a book is explicitly named, so picks
 * built the old way keep their exact key and still dedupe with Best Picks.
 */
function buildSlatePickFor(
  f: AnalyzerFighter,
  source: string,
  dir: 'over' | 'under',
  fallbackLine: number | null = null,
  bookOverride?: string | null,
): { key: string; pick: BestPicksSlatePick } {
  const { book, line } = bookOverride
    ? { book: bookOverride, line: lineForBook(f, source, bookOverride) }
    : leanBestBook(f, source, dir);
  const finalLine = line ?? fallbackLine ?? null;
  const statLabel = EFFECTIVE_LEAN_STAT_LABEL[source] || 'FP';
  const bookLabel = book ? (LEAN_BOOK_LABEL[book] || book) : 'No book';
  const clip = `${prettyName(f.name)} ${dir.toUpperCase()} ${finalLine ?? ''} ${statLabel}${book ? ` @ ${bookLabel}` : ''}${f.opponent ? ` (vs ${prettyName(f.opponent)})` : ''}`.replace(/\s+/g, ' ').trim();
  const key = `${f.name}|${dir}|${source}${bookOverride ? `|${bookOverride}` : ''}`;
  return {
    key,
    // `key` rides along on the pick so no consumer has to rebuild it — see the
    // field's note on BestPicksSlatePick.
    pick: { key, name: f.name, pretty: prettyName(f.name), dir: dir.toUpperCase(), source, statLabel, line: finalLine, book, bookLabel, clip, opponent: f.opponent ? prettyName(f.opponent) : null, opponentRaw: f.opponent || null },
  };
}

function buildLeanSlatePick(f: AnalyzerFighter, lean: EffectiveLean): { key: string; pick: BestPicksSlatePick } {
  const source = lean._source || 'fp';
  const dir = lean.lean;
  const { book, line } = leanBestBook(f, source, dir);
  const finalLine = line ?? lean.line ?? null;
  const statLabel = EFFECTIVE_LEAN_STAT_LABEL[source] || 'FP';
  const bookLabel = book ? (LEAN_BOOK_LABEL[book] || book) : 'No book';
  const clip = `${prettyName(f.name)} ${dir.toUpperCase()} ${finalLine ?? ''} ${statLabel}${book ? ` @ ${bookLabel}` : ''}${f.opponent ? ` (vs ${prettyName(f.opponent)})` : ''}`.replace(/\s+/g, ' ').trim();
  // Same key shape as Best Picks (`name|lean|source`) so a pick added here and one
  // added there are the SAME slate entry — they dedupe and sync automatically.
  const key = `${f.name}|${dir}|${source}`;
  return {
    key,
    pick: { key, name: f.name, pretty: prettyName(f.name), dir: dir.toUpperCase(), source, statLabel, line: finalLine, book, bookLabel, clip, opponent: f.opponent ? prettyName(f.opponent) : null, opponentRaw: f.opponent || null },
  };
}

/**
 * Two-sided add-to-slate control for ONE stat. Renders ▲ and ▼ side by side and
 * registers BOTH directions in `_leanSlateData`, so the click handler can resolve
 * whichever the user picks.
 *
 * Why both sides are always offered, including the one no book takes: the model's
 * lean is an opinion, not a constraint, and the user frequently wants the other
 * side of a prop the board is leaning. Placeability is still REPORTED — a side no
 * book will take is marked `noBook` and says so on hover — but it is no longer
 * enforced by omission. The ✔/⛔ placement chip beside this still gives the
 * per-book truth; this only decides what you can queue.
 *
 * The model's own side carries `is-lean` so the panel still reads as a
 * recommendation at a glance rather than a neutral pair of buttons.
 */
/**
 * Does ONE named book take this exact side? The same rules `leanBestBook` filters
 * candidates with, asked about a specific book instead of resolving the best one.
 *
 * Needed because the per-book path only ever consulted `shouldSkipFpSideForFighter`,
 * which returns false for every non-FP stat — so a Pick6 TD under (More-only) or a
 * DK chalk side reported as takeable the moment a book was named explicitly.
 */
function bookTakesSide(f: AnalyzerFighter, source: string, dir: 'over' | 'under', book: string): boolean {
  if (lineForBook(f, source, book) == null) return false;
  if (source === 'fp') return !shouldSkipFpSideForFighter(f, 'fp', dir, book as SourcePlatformKey);
  if (dir === 'under' && !statUnderBookOffered(f, source, book)) return false;
  if (book === 'draftkings_sportsbook' && dkSideChalk(f, source, dir)) return false;
  return true;
}

/** The sub-lean object for a stat, so panel controls can re-derive their own direction. */
function leanResultForSource(f: AnalyzerFighter, source: string): LeanResult | null {
  switch (source) {
    case 'ss':    return f.lean_ss ?? null;
    case 'ss_r1': return f.lean_ss_r1 ?? null;
    case 'td':    return f.lean_td ?? null;
    case 'ft':    return f.lean_ft ?? null;
    case 'ctrl':  return f.lean_ctrl ?? null;
    case 'kd':    return f.lean_kd ?? null;
    default:      return f.lean ?? null;
  }
}
function leanDirForSource(f: AnalyzerFighter, source: string): 'over' | 'under' | null {
  const l = leanResultForSource(f, source);
  return l && (l.lean === 'over' || l.lean === 'under') ? l.lean : null;
}

/**
 * GLOW-UP 225 — which book each lean panel is pointed at.
 *
 * Session-scoped by design: this changes the book you are QUEUEING against, never
 * what the model picked, so it belongs with the other view-only state rather than
 * in storage.
 */
const _panelBookChoice = new Map<string, string>();

/**
 * GLOW-UP 225 — the placement chip becomes a book selector.
 *
 * The chip named the BEST book for the side and the ▲▼ beside it queued that
 * book's line, which is the right default and the wrong answer whenever you
 * placed the bet somewhere else: Ian Machado Garry's R1 SS chip read PrizePicks
 * 6.5 while the bet was on DK at 7.5, and there was no control anywhere that
 * produced the DK entry. Every book with a line for this prop is now reachable by
 * clicking through the chip, and the pickers follow the selection — so the queued
 * leg carries the line you actually placed.
 *
 * The model's own resolution stays marked (★ BEST), so cycling away from it is
 * visibly a deliberate choice rather than a lost recommendation.
 */
function buildBookPlacementControl(f: AnalyzerFighter, source: string, dir: 'over' | 'under' | null): string {
  const books = (LEAN_STAT_FIELDS[source] || [])
    .map(([bk]) => ({ bk, line: lineForBook(f, source, bk) }))
    .filter((c): c is { bk: string; line: number } => c.line != null);
  // No book has posted this prop — the old chip still says that better than an
  // empty selector would.
  if (!books.length) return dir ? buildPlacementChip(f, source, dir) : '';

  const key = `${f.name}|${source}`;
  const best = dir ? leanBestBook(f, source, dir).book : null;
  const stored = _panelBookChoice.get(key);
  const chosen = stored && books.some(b => b.bk === stored)
    ? stored
    : (best && books.some(b => b.bk === best) ? best : books[0].bk);
  const idx = Math.max(0, books.findIndex(b => b.bk === chosen));
  const cur = books[idx];
  const label = LEAN_BOOK_LABEL[cur.bk] || cur.bk;
  const takes = dir ? bookTakesSide(f, source, dir, cur.bk) : true;
  const isBest = best != null && best === cur.bk;

  const others = books.filter(b => b.bk !== cur.bk)
    .map(b => `${LEAN_BOOK_LABEL[b.bk] || b.bk} ${b.line}`).join(', ');
  const tip = books.length > 1
    ? `Queueing against ${label} ${cur.line}${isBest ? " — the book the model's pick resolves to" : ''}.${dir && !takes ? ` ${label} does not offer this ${dir.toUpperCase()} — queue it anyway if you have it.` : ''} Click to switch: ${others}.`
    : `${label} ${cur.line} is the only book posting this prop${dir && !takes ? ` and does not offer the ${dir.toUpperCase()} side` : ''}.`;

  return `<span class="book-place" data-book-place="${key.replace(/"/g, '&quot;')}">`
    + `<button type="button" class="place-chip book-cycle ${takes ? 'ok' : 'blocked'}${isBest ? ' is-best' : ''}"`
    + ` data-book-cycle="${key.replace(/"/g, '&quot;')}" title="${tip.replace(/"/g, '&quot;')}">`
    + `${takes ? '✔' : '⛔'} ${label} ${cur.line}`
    + `${isBest ? '<u>★</u>' : ''}`
    + `${books.length > 1 ? `<i>${idx + 1}/${books.length} ⟳</i>` : ''}`
    + `</button>`
    + buildSidePicker(f, source, dir, cur.bk)
    + `</span>`;
}

function buildSidePicker(f: AnalyzerFighter, source: string, leanDir: string | null | undefined, bookOverride?: string | null): string {
  const one = (dir: 'over' | 'under'): string => {
    const { key, pick } = buildSlatePickFor(f, source, dir, null, bookOverride);
    _leanSlateData.set(key, pick);
    const inSlate = bestPicksSlate.has(key);
    const isLean = dir === leanDir;
    // With a book named, placeability is that BOOK's answer, not the best book's.
    // GLOW-UP 225: via bookTakesSide, which knows the non-FP rules too — the old
    // call was FP-only, so a named Pick6 TD under reported as takeable.
    const takesIt = bookOverride
      ? bookTakesSide(f, source, dir, bookOverride)
      : leanBestBook(f, source, dir).book != null;
    const best = leanBestBook(f, source, dir);
    const where = bookOverride
      ? (takesIt
          ? `${LEAN_BOOK_LABEL[bookOverride] || bookOverride} ${pick.line}`
          : `${LEAN_BOOK_LABEL[bookOverride] || bookOverride} does not offer this side — queue it anyway if you have it`)
      : best.book
        ? `${LEAN_BOOK_LABEL[best.book] || best.book} ${best.line}`
        : 'no book posts this side — queue it anyway and enter it wherever you have it';
    const tip = `${inSlate ? 'Remove from' : 'Add to'} My Slate: ${prettyName(f.name)} ${dir.toUpperCase()} ${pick.line ?? '—'} ${pick.statLabel} · ${where}${isLean ? ' · model leans THIS side' : ' · opposite the model lean'}`;
    return `<button class="side-pick-btn ${dir}${inSlate ? ' on' : ''}${isLean ? ' is-lean' : ''}${takesIt ? '' : ' noBook'}" data-slate-key="${key.replace(/"/g, '&quot;')}" title="${tip.replace(/"/g, '&quot;')}">${dir === 'over' ? '▲' : '▼'}${inSlate ? '<i>✓</i>' : ''}</button>`;
  };
  return `<span class="side-pick" title="${bookOverride ? `Queue either side of this book's line — ${LEAN_BOOK_LABEL[bookOverride] || bookOverride} specifically` : "Queue either side of this prop — the model's lean is highlighted, but you can take the other side"}">${one('over')}${one('under')}</span>`;
}

/**
 * GLOW-UP 211 — the FP panel's per-book pickers. FP lines are NOT comparable
 * across books (each scores fantasy points its own way), so there is no "best" FP
 * line to shop for — only the book you intend to enter it on. Every book that has
 * posted therefore gets its own ▲▼ pair, and the one the model resolved to is
 * marked so the panel still reads as a recommendation.
 */
function buildFpBookPickers(f: AnalyzerFighter, leanDir: string | null | undefined): string {
  const resolved = leanDir ? leanBestBook(f, 'fp', leanDir as 'over' | 'under').book : null;
  const cells = (LEAN_STAT_FIELDS['fp'] || []).map(([bk, fld]) => {
    const raw = (f as unknown as Record<string, unknown>)[fld as string] as number | null;
    const label = LEAN_BOOK_LABEL[bk] || bk;
    if (raw == null || !Number.isFinite(Number(raw))) {
      return `<span class="fpbk empty" title="${label} has not posted an FP line for ${prettyName(f.name)}">${label} —</span>`;
    }
    return `<span class="fpbk${bk === resolved ? ' resolved' : ''}" title="${label} FP ${raw}${bk === resolved ? " — the book the model's pick resolves to" : ''}"><b>${label}</b> ${raw}${buildSidePicker(f, 'fp', leanDir, bk)}</span>`;
  });
  return `<span class="fpbk-rail">${cells.join('')}</span>`;
}

// ── GLOW-UP 198 — ALL FIGHTERS full-slate pass ────────────────────────────
// The default landing view was the only major surface with no header: Best Picks,
// Slate Check and the directional views all summarise themselves; this one opened
// straight onto row 1. Nothing here is newly derived — every number below is
// already computed per row, it just had nowhere to be read at slate level.
let _slateCompact = false;                                     // L3 density
type SlateFilter = 'all' | 'lean' | 'ev' | 'gaps' | 'pattern' | 'fadepattern';
let _slateFilter: SlateFilter = 'all';                         // L2 filter chips

const SLATE_BOOKS: Array<{ key: 'p6' | 'ud' | 'pp' | 'betr' | 'dk'; label: string }> = [
  { key: 'p6', label: 'P6' }, { key: 'ud', label: 'UD' }, { key: 'pp', label: 'PP' },
  { key: 'betr', label: 'BT' }, { key: 'dk', label: 'DK' },
];

/**
 * Books that posted anything at all for this slate. A book sitting at zero (DK
 * routinely, since it posts props progressively) is a BOOK-level absence, which
 * Slate Check already reports — not a per-fighter gap. Counting it made LINE GAPS
 * match every fighter on the card and the filter did nothing.
 */
function slateLiveBooks(fighters: AnalyzerFighter[]): Array<'p6' | 'ud' | 'pp' | 'betr' | 'dk'> {
  return SLATE_BOOKS.filter(b => fighters.some(f => hasSourceLine(f, b.key))).map(b => b.key);
}

/** L2 — does this fighter survive the active slate filter? */
function slateFilterAccepts(
  f: AnalyzerFighter,
  liveBooks: Array<'p6' | 'ud' | 'pp' | 'betr' | 'dk'>,
): boolean {
  if (_slateFilter === 'all') return true;
  // GLOW-UP 199 — arrived from a Learning Drilldown directive.
  if (_slateFilter === 'pattern') return fighterMatchesDirective(f, _memoryDirectives.lean);
  if (_slateFilter === 'fadepattern') return fighterMatchesDirective(f, _memoryDirectives.fade);
  const lean = getEffectiveLean(f);
  const directional = lean.lean === 'over' || lean.lean === 'under';
  if (_slateFilter === 'lean') return directional;
  if (_slateFilter === 'ev') {
    if (!directional) return false;
    const ev = computeFighterEV(f, lean);
    return ev != null && ev > 0;
  }
  // 'gaps' — missing a book that OTHER fighters on this slate do have, i.e. a
  // real per-fighter hole rather than a book that hasn't posted yet.
  return liveBooks.some(k => !hasSourceLine(f, k));
}

/**
 * L5 — add-to-slip on the slate view, hung off the play pill.
 *
 * Docked inside `.play-pill`, deliberately. Two alternatives were tried and are
 * NOT improvements:
 *  1. A 46px left gutter (what the lean views use) — doesn't transfer, because
 *     inside `.fight-pair` the `.fighter-main` grid is fractional
 *     (`minmax(192px, 1.15fr) …`) and its identity column already ellipsizes
 *     ordinary names; taking 46px more would truncate further.
 *  2. Stacked above the ▼ in `.row-expand-slot` — costs no width, but that column
 *     is 22px of dead space at the far right of a very wide row, and the button
 *     was effectively invisible there. Rejected on discoverability (user call).
 * The pill wraps to two lines on narrow identity columns. That's accepted: the
 * button belongs to the play, and reading as part of the pill is worth the row.
 * Same `name|lean|source` key as Best Picks, so a pick added here is the SAME
 * slate entry and the two surfaces dedupe.
 */
function attachSlateSlipButton(row: HTMLElement, f: AnalyzerFighter): void {
  const pill = row.querySelector('.play-pill');
  if (!pill) return;
  const lean = getEffectiveLean(f);
  if (lean.lean !== 'over' && lean.lean !== 'under') return;
  const { key, pick } = buildLeanSlatePick(f, lean);
  _leanSlateData.set(key, pick);
  const inSlate = bestPicksSlate.has(key);
  const btn = document.createElement('button');
  btn.className = `slate-slip-btn${inSlate ? ' on' : ''}`;
  btn.dataset['slateKey'] = key;
  btn.title = inSlate ? 'Remove from My Slate' : `Add to My Slate — ${pick.clip}`;
  btn.textContent = inSlate ? '✓' : '+';
  pill.appendChild(btn);
}

// L1 — slate command header: fights, leans, tiers, avg EV, top edge, coverage.
function buildSlateViewHeader(shown: AnalyzerFighter[], total: number): HTMLElement {
  const el = document.createElement('div');
  el.className = 'slate-cmd-header';
  let over = 0, under = 0, high = 0, med = 0, low = 0;
  let evSum = 0, evCount = 0, posEv = 0;
  let top: { name: string; label: string; conf: number } | null = null;
  for (const f of shown) {
    const lean = getEffectiveLean(f);
    const directional = lean.lean === 'over' || lean.lean === 'under';
    if (lean.lean === 'over') over++; else if (lean.lean === 'under') under++;
    if (directional) {
      const conf = getDisplayedConf(f);
      if (conf >= 72) high++; else if (conf >= 58) med++; else low++;
      if (!top || conf > top.conf) {
        top = {
          name: prettyName(f.name),
          label: `${EFFECTIVE_LEAN_STAT_LABEL[lean._source || 'fp'] || 'FP'}${lean.line != null ? ' ' + lean.line : ''}`,
          conf,
        };
      }
    }
    const ev = computeFighterEV(f, lean);
    if (ev != null) { evSum += ev; evCount++; if (ev > 0) posEv++; }
  }
  const avgEv = evCount ? evSum / evCount : null;
  const filtered = shown.length !== total;
  const cov = SLATE_BOOKS.map(b => ({
    label: b.label,
    n: shown.filter(f => hasSourceLine(f, b.key)).length,
  }));
  const chip = (id: SlateFilter, text: string, title: string): string =>
    `<button class="sch-filter${_slateFilter === id ? ' on' : ''}" data-slate-filter="${id}" title="${title}">${text}</button>`;

  el.innerHTML = `
    <div class="sch-row">
      <span class="sch-title">◆ SLATE</span>
      <span class="sch-count" title="${filtered ? `${shown.length} shown of ${total} fighters` : `${total} fighters on the slate`}">${shown.length}${filtered ? `<i class="sch-of">/${total}</i>` : ''}</span>
      <span class="sch-dirs">
        <span class="sch-dir over" title="Fighters whose effective lean is OVER">▲ ${over}</span>
        <span class="sch-dir under" title="Fighters whose effective lean is UNDER">▼ ${under}</span>
      </span>
      <span class="sch-tiers">
        <span class="sch-tier high" title="Confidence ≥72%">${high} High</span>
        <span class="sch-tier med" title="Confidence 58–71%">${med} Med</span>
        <span class="sch-tier low" title="Confidence &lt;58%">${low} Low</span>
      </span>
      ${avgEv != null ? `<span class="sch-ev ${avgEv > 0 ? 'pos' : 'neg'}" title="Average EV across every fighter with a priced lean — ${posEv} of ${evCount} are above breakeven">avg EV ${avgEv > 0 ? '+' : ''}${avgEv.toFixed(1)}% <i class="sch-ev-n">${posEv}/${evCount} +EV</i></span>` : ''}
      ${top ? `<span class="sch-top" title="Highest-confidence lean on the slate">⭐ ${top.name} · ${top.label} · ${Math.round(top.conf)}%</span>` : ''}
      ${bestPicksSlate.size ? `<button class="sch-slip" data-slate-jump="1" title="${bestPicksSlate.size} pick(s) in My Slate — the tray only renders on AI BEST PICKS. Click to jump there and review them.">🧾 MY SLATE <b>${bestPicksSlate.size}</b> →</button>` : ''}
    </div>
    <div class="sch-row sch-row-2">
      <span class="sch-filters">
        ${chip('all', 'ALL', 'Every fighter on the slate')}
        ${chip('lean', 'HAS LEAN', 'Only fighters with a directional lean (over or under)')}
        ${chip('ev', '+EV', 'Only leans priced above breakeven')}
        ${chip('gaps', 'LINE GAPS', 'Fighters missing at least one book — the fetch worklist behind Slate Check coverage')}
        ${(() => {
          // A pattern filter arrives from the Learning Drilldown, not from these
          // chips, so it needs to announce itself or the board looks arbitrarily short.
          const sig = _slateFilter === 'pattern' ? _memoryDirectives.lean
                    : _slateFilter === 'fadepattern' ? _memoryDirectives.fade : null;
          if (!sig) return '';
          const verb = _slateFilter === 'pattern' ? '▲ LEAN INTO' : '▼ FADE';
          const label = `${formatSourceLabel(sig.source)} ${sig.lean.toUpperCase()} · ${sig.tagLabel}`;
          return `<button class="sch-pattern ${_slateFilter === 'pattern' ? 'is-lean' : 'is-fade'}" data-slate-filter="all" title="Archive pattern from the Learning Drilldown — ${Math.round(sig.hitRate * 100)}% over ${sig.total} settled rows. Click to clear.">${verb} ${label} ✕</button>`;
        })()}
      </span>
      <span class="sch-cov" title="Fighters covered per book, of ${shown.length} shown">
        ${cov.map(c => `<span class="sch-cov-book${c.n === 0 ? ' none' : c.n === shown.length ? ' full' : ''}">${c.label} <b>${c.n}</b></span>`).join('')}
      </span>
      <button class="sch-compact-toggle${_slateCompact ? ' on' : ''}" data-slate-compact title="Slim every row to identity + lean (hide the line grid &amp; stat deck) for faster full-slate scanning">▤ ${_slateCompact ? 'FULL ROWS' : 'SLIM ROWS'}</button>
    </div>`;
  return el;
}

// L1 — directional command header: count, tier breakdown, avg EV, strongest play.
function buildLeanViewHeader(fighters: AnalyzerFighter[], dir: 'over' | 'under'): HTMLElement {
  const el = document.createElement('div');
  el.className = `lean-cmd-header lch-${dir}`;
  let high = 0, med = 0, low = 0, evSum = 0, evCount = 0;
  let top: { name: string; label: string; conf: number } | null = null;
  for (const f of fighters) {
    const lean = getEffectiveLean(f);
    const conf = getDisplayedConf(f);
    if (conf >= 72) high++; else if (conf >= 58) med++; else low++;
    const ev = computeFighterEV(f, lean);
    if (ev != null) { evSum += ev; evCount++; }
    if (!top || conf > top.conf) {
      top = { name: prettyName(f.name), label: `${EFFECTIVE_LEAN_STAT_LABEL[lean._source || 'fp'] || 'FP'}${lean.line != null ? ' ' + lean.line : ''}`, conf };
    }
  }
  const avgEv = evCount ? evSum / evCount : null;
  const dirLabel = dir === 'over' ? '▲ LEAN OVER' : '▼ LEAN UNDER';
  el.innerHTML = `
    <div class="lch-row">
      <span class="lch-title">${dirLabel}</span>
      <span class="lch-count">${fighters.length}</span>
      <span class="lch-tiers">
        <span class="lch-tier high" title="Confidence ≥72%">${high} High</span>
        <span class="lch-tier med" title="Confidence 58–71%">${med} Med</span>
        <span class="lch-tier low" title="Confidence &lt;58%">${low} Low</span>
      </span>
      ${avgEv != null ? `<span class="lch-ev ${avgEv > 0 ? 'pos' : 'neg'}" title="Average EV across these leans">avg EV ${avgEv > 0 ? '+' : ''}${avgEv.toFixed(1)}%</span>` : ''}
      ${top ? `<span class="lch-top" title="Highest-confidence play in this direction">⭐ ${top.name} · ${top.label} · ${Math.round(top.conf)}%</span>` : ''}
      <button class="lch-compact-toggle${_leanCompact ? ' on' : ''}" data-lean-compact title="Slim these rows to identity + play + lean (hide the stat deck &amp; line grid) for faster directional scanning">▤ ${_leanCompact ? 'FULL ROWS' : 'SLIM ROWS'}</button>
    </div>`;
  return el;
}

// Coalesce multiple renderFighters() calls in the same frame into a single
// render. Many code paths (mergeAndEnrich, line-move handlers, sort/filter,
// news arrivals) fire renderFighters() back-to-back; without coalescing each
// one rebuilds 26 rows from scratch.
let _renderScheduled = false;
function renderFighters(): void {
  if (_renderScheduled) return;
  _renderScheduled = true;
  requestAnimationFrame(() => {
    _renderScheduled = false;
    _renderFightersImpl();
  });
}

function updateViewTabCounts(): void {
  // Count only PLACEABLE directional leans so the LEAN OVER/UNDER tab badges match
  // what the (now placeability-filtered) views actually render — an unplaceable FP
  // lean is dropped from both the view and the count.
  let bestOver = 0, bestUnder = 0;
  for (const f of allFighters) {
    const el = getEffectiveLean(f);
    if (el.lean === 'over') {
      if (!shouldSkipFpSideForFighter(f, el._source, 'over', el._platform)) bestOver++;
    } else if (el.lean === 'under') {
      if (!shouldSkipFpSideForFighter(f, el._source, 'under', el._platform)) bestUnder++;
    }
  }
  const setText = (id: string, n: number): void => {
    const el = document.getElementById(id);
    if (el) el.textContent = String(n);
  };
  // Best Picks panel caps each section at 8; this approximates the visible pick count.
  setText('tabCountAll', allFighters.length);
  setText('tabCountOver', bestOver);
  setText('tabCountUnder', bestUnder);
  setText('tabCountBestPicks', Math.min(8, bestOver) + Math.min(8, bestUnder));
}

// ── FIGHT-PAIR LAYOUT ─────────────────────────────────────────────────────
// Group two opponents into a single Fight so the upcoming-card view can render
// them side-by-side with a shared spine. Presentation only — does not feed
// predictor, EV, or storage paths.
type FightCardPosition = 'main' | 'co-main' | 'main-card' | 'prelim';
type CorrelationStat = 'SS' | 'FP' | 'FT';
interface FightCorrelation {
  type: 'neg-correlated-same-direction';
  stat: CorrelationStat;
  direction: 'over' | 'under';
  note: string;
}
interface FightPair {
  fighterA: AnalyzerFighter;
  fighterB: AnalyzerFighter | null;
  fightIndex: number;
  weightClass?: WeightClass;
  rounds: 3 | 5;
  cardPosition: FightCardPosition;
  ftLine: number | null;
  ftPlatKey: 'p6' | 'ud' | 'pp' | 'betr' | 'dk' | null;
  bothHaveCtrl: boolean;
  correlation: FightCorrelation | null;
  isTopEdgeFight: boolean;
  topEdgeConf: number;
}

function isPlaceholderFighter(f: AnalyzerFighter | null | undefined): boolean {
  return !!f && f.db?.loaded === false;
}

function fighterHasCtrlProp(f: AnalyzerFighter | null): boolean {
  if (!f) return false;
  return f.line_p6_ctrl != null || f.line_ud_ctrl != null
      || f.line_pp_ctrl != null || f.line_betr_ctrl != null
      || f.line_dk_ctrl != null;
}

function pickFightTimeLine(
  f: AnalyzerFighter | null,
): { value: number; plat: 'p6' | 'ud' | 'pp' | 'betr' | 'dk' } | null {
  if (!f) return null;
  const candidates: Array<{ value: number | null | undefined; plat: 'p6' | 'ud' | 'pp' | 'betr' | 'dk' }> = [
    { value: f.line_p6_ft,   plat: 'p6'   },
    { value: f.line_ud_ft,   plat: 'ud'   },
    { value: f.line_pp_ft,   plat: 'pp'   },
    { value: f.line_betr_ft, plat: 'betr' },
    { value: f.line_dk_ft,   plat: 'dk'   },
  ];
  for (const c of candidates) {
    if (c.value != null && Number.isFinite(c.value)) return { value: c.value, plat: c.plat };
  }
  return null;
}

function computeFightCorrelation(
  a: AnalyzerFighter,
  b: AnalyzerFighter,
): FightCorrelation | null {
  if (isPlaceholderFighter(a) || isPlaceholderFighter(b)) return null;
  const aSs = a.lean_ss?.lean, bSs = b.lean_ss?.lean;
  if (aSs && aSs === bSs && (aSs === 'over' || aSs === 'under')) {
    return {
      type: 'neg-correlated-same-direction',
      stat: 'SS',
      direction: aSs,
      note: `Both ${aSs.toUpperCase()} SS — same-fight same-direction. Lean ONE side.`,
    };
  }
  const aFp = a.lean?.lean, bFp = b.lean?.lean;
  if (aFp && aFp === bFp && (aFp === 'over' || aFp === 'under')) {
    return {
      type: 'neg-correlated-same-direction',
      stat: 'FP',
      direction: aFp,
      note: aFp === 'over'
        ? `Both OVER FP — only one fighter gets the win bonus. Lean ONE side.`
        : `Both UNDER FP — needs a fast finish. Lean ONE side.`,
    };
  }
  const aFt = a.lean_ft?.lean, bFt = b.lean_ft?.lean;
  if (aFt && aFt === bFt && (aFt === 'over' || aFt === 'under')) {
    return {
      type: 'neg-correlated-same-direction',
      stat: 'FT',
      direction: aFt,
      note: `Both ${aFt.toUpperCase()} FT — same fight, same direction. Lean ONE side.`,
    };
  }
  return null;
}

// GLOW-UP 198 L4 — the MAIN EVENT badge is now headliner-matched, like the 5R
// chip beside it. `rounds` was fixed to use fightIsMainEvent() (cd122bb) but this
// stayed on raw array position, so on a card whose UFCStats order isn't main-first
// the badge and the rounds chip pointed at DIFFERENT fights. Positional 'main' is
// kept only as the fallback when no headliner could be identified at all.
function cardPositionForFightIndex(
  fightIndex: number,
  totalFights: number,
  isMainEvent: boolean,
  headlinerKnown: boolean,
): FightCardPosition {
  if (isMainEvent) return 'main';
  if (!headlinerKnown && fightIndex === 0) return 'main';
  if (fightIndex === 1) return 'co-main';
  if (fightIndex < Math.ceil(totalFights * 0.55)) return 'main-card';
  return 'prelim';
}

function buildFights(activeFighters: AnalyzerFighter[]): FightPair[] {
  const out: FightPair[] = [];

  // Identify the main event by the (now title-authoritative) headliner pair rather
  // than array position — UFCStats upcoming-card order is NOT reliably main-first,
  // so `fightIndex === 0` would award the 5R badge to whatever prelim happens to be
  // first. Compute once; compare each pair's fighters by name (tolerant) below.
  const headlinerPair = findHeadlinerPair();
  const fightIsMainEvent = (a: AnalyzerFighter, b: AnalyzerFighter | null): boolean => {
    if (!headlinerPair || !b) return false;
    const na = normalizeName(a?.name);
    const nb = normalizeName(b?.name);
    if (!na || !nb) return false;
    const inPair = (n: string): boolean =>
      n === headlinerPair.f1 || n === headlinerPair.f2 ||
      strictCardNameMatch(n, headlinerPair.f1) || strictCardNameMatch(n, headlinerPair.f2);
    return inPair(na) && inPair(nb);
  };

  // Slate-wide top-edge scan — confidence on whichever leaned stat scores highest.
  let topEdgeName = '';
  let topEdgeConf = 0;
  for (const f of activeFighters) {
    if (isPlaceholderFighter(f)) continue;
    const el = getEffectiveLean(f);
    if (el.lean !== 'over' && el.lean !== 'under') continue;
    const c = el.conf || 0;
    if (c > topEdgeConf) { topEdgeConf = c; topEdgeName = f.name; }
  }

  // ── Card-driven pairing ────────────────────────────────────────────────
  // Previously this walked activeFighters two at a time and TRUSTED
  // orderFightersByCard to have aligned them, reading weightClass from
  // upcomingCardPairs[i/2] by position. Any card pair contributing an ODD number
  // of fighters shifted every fight after it by one — and that happens routinely:
  // a fighter with no lines yet, or (2026-08-02) a STALE cached card. The cached
  // card held 9 fights while UFCStats listed 11, so Sousa/Miranda and Johns/Rosas
  // fell into the unordered tail and Billy Ray Goff ended up beside JULIANA Miller
  // instead of Ty Miller, dragging Oliveira, Sousa, Miranda, Johns and Rosas out
  // of position behind him.
  //
  // Pair from the card itself and adjacency can't drift. Fighters absent from the
  // (possibly stale) card fall through to adjacency at the end, so a lagging cache
  // degrades to the old behaviour for those rows only instead of corrupting all of
  // them.
  const unpaired = new Set(activeFighters);
  const takeFromBoard = (cardName: string): AnalyzerFighter | null => {
    for (const f of unpaired) {
      const n = normalizeName(f.name) || f.name;
      if (n === cardName) { unpaired.delete(f); return f; }
    }
    for (const f of unpaired) {
      const n = normalizeName(f.name) || f.name;
      if (namesMatch(n, cardName) || strictCardNameMatch(n, cardName)) { unpaired.delete(f); return f; }
    }
    return null;
  };

  const slots: Array<{ a: AnalyzerFighter; b: AnalyzerFighter | null; weightClass?: WeightClass }> = [];
  for (const cp of upcomingCardPairs) {
    const f1 = takeFromBoard(cp.f1);
    const f2 = takeFromBoard(cp.f2);
    if (!f1 && !f2) continue;               // neither side on the board yet
    // A half-resolved pair keeps its own slot rather than borrowing the next
    // fight's fighter — that borrowing is what cascaded.
    slots.push({ a: (f1 || f2)!, b: f1 ? f2 : null, weightClass: cp.weightClass });
  }
  // Anyone the card doesn't know about (stale cache, late addition). Pair them by
  // their OWN opponent field before falling back to adjacency — the platforms know
  // these matchups even when the cached card predates them, and adjacency here was
  // what left Jessie Rosas orphaned while Richie Miranda sat next to Miles Johns.
  const leftovers = activeFighters.filter((f) => unpaired.has(f));
  for (const f of leftovers) {
    if (!unpaired.has(f)) continue;
    unpaired.delete(f);
    let partner: AnalyzerFighter | null = null;
    const oppNorm = f.opponent ? (normalizeName(f.opponent) || f.opponent) : null;
    if (oppNorm) {
      for (const g of unpaired) {
        const gn = normalizeName(g.name) || g.name;
        if (gn === oppNorm || namesMatch(gn, oppNorm) || strictCardNameMatch(gn, oppNorm)) {
          partner = g;
          unpaired.delete(g);
          break;
        }
      }
    }
    slots.push({ a: f, b: partner });
  }

  // Real slot count — ceil(fighters/2) over-counted whenever a pair was half
  // resolved, skewing the main-card/prelim split in cardPositionForFightIndex.
  const totalFights = slots.length;

  for (let fightIndex = 0; fightIndex < slots.length; fightIndex++) {
    const { a, b, weightClass } = slots[fightIndex];
    const ft = pickFightTimeLine(a) || pickFightTimeLine(b);
    const correlation = b ? computeFightCorrelation(a, b) : null;
    const isMain = fightIsMainEvent(a, b);
    const rounds: 3 | 5 = isMain ? 5 : 3;
    const topEdge = !!topEdgeName && (a.name === topEdgeName || b?.name === topEdgeName);
    out.push({
      fighterA: a,
      fighterB: b,
      fightIndex,
      weightClass,
      rounds,
      cardPosition: cardPositionForFightIndex(fightIndex, totalFights, isMain, !!headlinerPair),
      ftLine: ft?.value ?? null,
      ftPlatKey: ft?.plat ?? null,
      bothHaveCtrl: fighterHasCtrlProp(a) && fighterHasCtrlProp(b),
      correlation,
      isTopEdgeFight: topEdge,
      topEdgeConf: topEdge ? topEdgeConf : 0,
    });
  }
  return out;
}

function spineHasContent(fight: FightPair): boolean {
  return !!fight.ftLine || fight.bothHaveCtrl || !!fight.correlation || fight.isTopEdgeFight;
}

function weightClassChip(weight: WeightClass | undefined): string {
  if (!weight) return '';
  const label = String(weight).replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  return `<span class="fight-spine-weight" title="Weight class">${label}</span>`;
}

// ── FILLED-SPINE HELPERS ──────────────────────────────────────────────────
// Per-fighter colors used across the filled-spine sections (matchup values,
// L5 trend strokes, common-opp stat lines, legend chips). Cyan = side A,
// yellow = side B. Yellow intentionally matches the existing top-edge callout.
const SPINE_COLOR_A = '#5ee5e0';
const SPINE_COLOR_B = '#ffd24a';

function spineFightTime(f: FightResult): number {
  if (!f.date) return 0;
  const t = new Date(f.date).getTime();
  return Number.isFinite(t) ? t : 0;
}

function spineHistorySorted(db: FighterDB | null | undefined): FightResult[] {
  if (!db?.history?.length) return [];
  return [...db.history].sort((x, y) => spineFightTime(y) - spineFightTime(x));
}

function spineOppAbsorbsSS(db: FighterDB | null | undefined): number | null {
  if (!db?.history?.length) return null;
  const samples = db.history
    .map(h => h.oppStats?.sigStr)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
  if (samples.length < 2) return null;
  return parseFloat((samples.reduce((s, v) => s + v, 0) / samples.length).toFixed(1));
}

function spineEscape(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function spineMethodShort(method: string | null | undefined): string {
  const m = String(method || '').toUpperCase();
  if (/SUB/.test(m)) return 'SUB';
  if (/KO|TKO/.test(m)) return 'KO';
  return 'DEC';
}

function spineResultLetter(result: string | null | undefined): string {
  const r = String(result || '').toLowerCase();
  if (r === 'win') return 'W';
  if (r === 'loss' || r === 'lose') return 'L';
  if (r === 'draw') return 'D';
  return '–';
}

function spineFighterStatLine(f: FightResult, color: string): string {
  const ss = f.sigStr != null ? String(Math.round(f.sigStr)) : '—';
  const fp = f.fp != null ? String(Math.round(f.fp)) : '—';
  const res = spineResultLetter(f.result);
  const meth = spineMethodShort(f.method);
  // Result letter carries its own W/L color (green/red) inside the
  // fighter-colored line, and the title decodes the compact format.
  const resCls = res === 'W' ? ' cmn-res-w' : res === 'L' ? ' cmn-res-l' : '';
  return `<span class="spine-cmn-stat" style="color:${color}" title="vs this opponent: SS ${ss} · FP ${fp} · ${res} by ${meth}">${ss}·${fp}·<b class="cmn-res${resCls}">${res}/${meth}</b></span>`;
}

function spineMatchupHTML(a: AnalyzerFighter, b: AnalyzerFighter): string {
  const da = a.db, db2 = b.db;
  const ssA = da?.avgSigStr, ssB = db2?.avgSigStr;
  const absA = spineOppAbsorbsSS(da), absB = spineOppAbsorbsSS(db2);
  const fnA = da?.finishRate, fnB = db2?.finishRate;
  const fmt = (v: number | null | undefined): string =>
    v == null || !Number.isFinite(v) ? '<span class="spine-missing">—</span>' : (v as number).toFixed(1);
  const fmtPct = (v: number | null | undefined): string =>
    v == null || !Number.isFinite(v) ? '<span class="spine-missing">—</span>' : `${Math.round((v as number) * 100)}%`;
  // GLOW-UP 20: each row gets a teal/gold share-of-total bar + winner glow
  const row = (rawA: number | null | undefined, rawB: number | null | undefined, dispA: string, dispB: string, label: string): string => {
    const okA = rawA != null && Number.isFinite(rawA);
    const okB = rawB != null && Number.isFinite(rawB);
    const winA = okA && okB && (rawA as number) > (rawB as number);
    const winB = okA && okB && (rawB as number) > (rawA as number);
    let bar = '';
    if (okA && okB && ((rawA as number) + (rawB as number)) > 0) {
      const shareA = Math.round(((rawA as number) / ((rawA as number) + (rawB as number))) * 100);
      bar = `<div class="spine-adv-bar"><i class="adv-a" style="width:${shareA}%"></i><i class="adv-b" style="width:${100 - shareA}%"></i></div>`;
    }
    return `<div class="spine-matchup-row">
        <span class="spine-val-a${winA ? ' adv-win' : ''}">${dispA}</span>
        <span class="spine-row-label">${label}</span>
        <span class="spine-val-b${winB ? ' adv-win' : ''}">${dispB}</span>
      </div>${bar}`;
  };
  return `
    <div class="spine-section">
      <div class="spine-section-head">MATCHUP</div>
      ${row(ssA, ssB, fmt(ssA), fmt(ssB), 'SS/fight')}
      ${row(absA, absB, fmt(absA), fmt(absB), 'opp abs')}
      ${row(fnA, fnB, fmtPct(fnA), fmtPct(fnB), 'P(fin)')}
    </div>
  `;
}

function spineCommonOppsHTML(a: AnalyzerFighter, b: AnalyzerFighter): string {
  const histA = spineHistorySorted(a.db).slice(0, 8);
  const histB = spineHistorySorted(b.db).slice(0, 8);
  // Build normalized opp → fight map for side A so we can intersect in O(N).
  const mapA = new Map<string, FightResult>();
  for (const fight of histA) {
    const norm = normalizeName(fight.opp);
    if (norm && !mapA.has(norm.toLowerCase())) mapA.set(norm.toLowerCase(), fight);
  }
  const shared: Array<{ nameDisp: string; fA: FightResult; fB: FightResult; recency: number }> = [];
  for (const fight of histB) {
    const norm = normalizeName(fight.opp);
    if (!norm) continue;
    const key = norm.toLowerCase();
    const fA = mapA.get(key);
    if (!fA) continue;
    shared.push({
      nameDisp: norm,
      fA,
      fB: fight,
      recency: Math.max(spineFightTime(fA), spineFightTime(fight)),
    });
  }
  shared.sort((x, y) => y.recency - x.recency);
  const top3 = shared.slice(0, 3);
  let body: string;
  if (top3.length === 0) {
    body = `<div class="spine-cmn-empty">none in past 8 fights</div>`;
  } else {
    body = top3.map(s => `
      <div class="spine-cmn-row">
        <div class="spine-cmn-name">${spineEscape(s.nameDisp)}</div>
        <div class="spine-cmn-stats">
          ${spineFighterStatLine(s.fA, SPINE_COLOR_A)}
          <span class="spine-cmn-sep">·</span>
          ${spineFighterStatLine(s.fB, SPINE_COLOR_B)}
        </div>
      </div>
    `).join('');
  }
  return `
    <div class="spine-section">
      <div class="spine-section-head">COMMON OPPS</div>
      ${body}
    </div>
  `;
}

function spineL5TrendsHTML(a: AnalyzerFighter, b: AnalyzerFighter): string {
  const histAAll = spineHistorySorted(a.db);
  const histBAll = spineHistorySorted(b.db);
  // Need ≥2 fights on both sides to plot a polyline; otherwise suppress whole section.
  if (histAAll.length < 2 || histBAll.length < 2) return '';
  const n = Math.min(5, histAAll.length, histBAll.length);
  // Slice newest-N then reverse to chronological asc so the polyline reads
  // oldest → newest left-to-right (with the end-dot landing on the latest fight).
  const histA = histAAll.slice(0, n).reverse();
  const histB = histBAll.slice(0, n).reverse();
  const stats: Array<{ label: string; key: 'sigStr' | 'fp' | 'td' }> = [
    { label: 'SS', key: 'sigStr' },
    { label: 'FP', key: 'fp' },
    { label: 'TD', key: 'td' },
  ];
  const pickStat = (h: FightResult, k: 'sigStr' | 'fp' | 'td'): number => {
    const v = k === 'sigStr' ? h.sigStr : k === 'fp' ? h.fp : h.td;
    return v == null ? NaN : v;
  };
  const rows = stats.map(({ label, key }) => {
    const valsA = histA.map(h => pickStat(h, key)).filter(v => Number.isFinite(v));
    const valsB = histB.map(h => pickStat(h, key)).filter(v => Number.isFinite(v));
    const sparkA = valsA.length >= 2
      ? renderSparkline(valsA.map((v, i) => ({ t: i, v })), 'auto', { color: SPINE_COLOR_A, w: 70, h: 14, area: true, glow: true })
      : '<span class="spine-missing">—</span>';
    const sparkB = valsB.length >= 2
      ? renderSparkline(valsB.map((v, i) => ({ t: i, v })), 'auto', { color: SPINE_COLOR_B, w: 70, h: 14, area: true, glow: true })
      : '<span class="spine-missing">—</span>';
    const fmtLast = (vals: number[]): string => {
      if (!vals.length) return '';
      const v = vals[vals.length - 1];
      return Number.isInteger(v) ? String(v) : v.toFixed(1);
    };
    return `
      <div class="spine-trend-row">
        <span class="spine-trend-cell">${sparkA}<span class="spine-trend-val tv-a">${fmtLast(valsA)}</span></span>
        <span class="spine-trend-label">${label}</span>
        <span class="spine-trend-cell"><span class="spine-trend-val tv-b">${fmtLast(valsB)}</span>${sparkB}</span>
      </div>
    `;
  }).join('');
  const lastNameA = a.name.split(' ').pop() || a.name;
  const lastNameB = b.name.split(' ').pop() || b.name;
  return `
    <div class="spine-section">
      <div class="spine-section-head">L${n} TRENDS</div>
      ${rows}
      <div class="spine-trend-legend">
        <span class="spine-legend-a">${spineEscape(lastNameA)}</span>
        <span class="spine-legend-b">${spineEscape(lastNameB)}</span>
      </div>
    </div>
  `;
}

// Built once per fight-pair render. Returns '' for placeholder fighters so
// the spine stays narrow and only the shared-header chips show. CSS hides
// the wrapper in default state — `.fight-pair:has(.fighter-row.expanded)`
// reveals it.
function buildFilledSpineWrapper(a: AnalyzerFighter, b: AnalyzerFighter | null): string {
  if (!b || isPlaceholderFighter(a) || isPlaceholderFighter(b)) return '';
  return `
    <div class="fight-spine-filled">
      ${spineMatchupHTML(a, b)}
      ${spineCommonOppsHTML(a, b)}
      ${spineL5TrendsHTML(a, b)}
      <div class="fight-spine-spacer"></div>
    </div>
  `;
}

// Open head-to-head for a fighter by name, with hardened opponent lookup and
// toast feedback instead of silent failure.
function openH2HByName(fighterName: string): void {
  if (!fighterName) return;
  const fEntry = _h2hFighterMap.get(fighterName.toLowerCase());
  if (!fEntry) { showToast(`No data loaded for ${prettyName(fighterName)} yet`); return; }
  const oppRaw = (fEntry.opponent || '').toLowerCase().trim();
  let oppEntry = oppRaw ? _h2hFighterMap.get(oppRaw) : undefined;
  if (!oppEntry && oppRaw) {
    for (const [key, val] of _h2hFighterMap) {
      if (key.includes(oppRaw) || oppRaw.includes(key)) { oppEntry = val; break; }
    }
  }
  if (!oppEntry && oppRaw) {
    const oppNorm = (normalizeName(oppRaw) || oppRaw).toLowerCase();
    for (const [, val] of _h2hFighterMap) {
      if ((normalizeName(val.name) || val.name).toLowerCase() === oppNorm) { oppEntry = val; break; }
    }
  }
  if (oppEntry) renderH2HModal(fEntry, oppEntry);
  else showToast(`No opponent data for ${prettyName(fighterName)} yet — try a refetch`);
}

function buildFightSpine(fight: FightPair): HTMLDivElement {
  const spine = document.createElement('div');
  spine.className = 'fight-spine';

  // Seamless H2H entry: the whole center spine is a big, reliable trigger
  // (the tiny ⚔ button was a 20px target that took multiple tries).
  if (fight.fighterB && !isPlaceholderFighter(fight.fighterA) && !isPlaceholderFighter(fight.fighterB)) {
    const fb = fight.fighterB;
    spine.classList.add('h2h-clickable');
    spine.title = `Head-to-head: ${fight.fighterA.name} vs ${fb.name}`;
    spine.addEventListener('click', () => renderH2HModal(fight.fighterA, fb));
  }

  const roundsChip = `<span class="fight-spine-rounds" title="Scheduled rounds">${fight.rounds}R</span>`;
  const weightChip = weightClassChip(fight.weightClass);

  let ftBlock = '';
  if (fight.ftLine != null) {
    const platLabels: Record<string, string> = { p6: 'P6', ud: 'UD', pp: 'PP', betr: 'BT', dk: 'DK' };
    const platLabel = fight.ftPlatKey ? platLabels[fight.ftPlatKey] : '';
    const aName = fight.fighterA.name;
    const sparkPoints = fight.ftPlatKey ? getSparklinePointsForPlat(aName, 'ft', fight.ftPlatKey) : [];
    const sparkHtml = sparkPoints.length >= 2 ? renderSparkline(sparkPoints, 'auto') : '';
    ftBlock = `<div class="fight-spine-ft" title="Fight time line">
      <span class="fight-spine-ft-label">FT</span>
      <span class="fight-spine-ft-value">${fight.ftLine}</span>
      ${platLabel ? `<span class="fight-spine-ft-plat">${platLabel}</span>` : ''}
      ${sparkHtml}
    </div>`;
  }

  let ctrlBlock = '';
  if (fight.bothHaveCtrl) {
    ctrlBlock = `<div class="fight-spine-ctrl" title="Both fighters have a CTRL prop">CTRL ×2</div>`;
  }

  let corrBlock = '';
  if (fight.correlation) {
    const c = fight.correlation;
    corrBlock = `<div class="fight-spine-corr corr-${c.direction}" title="${c.note}">⚠ ${c.direction.toUpperCase()} ${c.stat} ×2</div>`;
  }

  let topEdgeBlock = '';
  if (fight.isTopEdgeFight && fight.topEdgeConf > 0) {
    topEdgeBlock = `<div class="fight-spine-top-edge" title="Slate's top-edge lean lives in this fight">TOP EDGE • ${Math.round(fight.topEdgeConf)}%</div>`;
  }

  const filledBlock = buildFilledSpineWrapper(fight.fighterA, fight.fighterB);

  spine.innerHTML = `
    <div class="fight-spine-chips">${roundsChip}${weightChip}</div>
    ${ftBlock}
    ${ctrlBlock}
    ${corrBlock}
    ${topEdgeBlock}
    ${filledBlock}
  `;
  return spine;
}

function _renderFightersImpl(): void {
  const container = document.getElementById('cardContainer');
  if (!container) return;
  // ── GLOW-UP 320 · four of six views never primed the lean cache ───────────
  // primeCaches() sat AFTER the view dispatch, and bestpicks / parlaylab /
  // calibration / archive all `return` before reaching it. So loading straight
  // into any of those left _leanCache null and the weight-miss adjustments
  // unapplied for the whole session — and updateViewTabCounts(), which ran
  // earlier still, counted leans against that un-primed state. The nav read
  // LEAN OVER 0 · LEAN UNDER 0 · AI BEST PICKS 0 beside ALL FIGHTERS 26.
  //
  // It looked intermittent because a single visit to a fighters view primed the
  // module state for the rest of the session, so the counts were right or wrong
  // depending on where you had been, not on the data.
  //
  // Priming first is also the correct order regardless: the counts are DERIVED
  // from the leans, so computing them before the leans exist could only ever have
  // been right by accident.
  primeCaches();
  updateViewTabCounts();
  container.innerHTML = '';
  if (currentView === 'bestpicks') { bestPicksRenderSeq++; void renderBestPicks(container, bestPicksRenderSeq); return; }
  if (currentView === 'parlaylab') { renderParlayLab(container); return; }
  if (currentView === 'calibration') { void renderCalibrationPanel(container); return; }
  if (currentView === 'archive') { void renderArchivePanel(container); return; }

  // Load archive stats once per session for per-fighter accuracy badges
  if (_fighterArchiveStats === null) { void loadFighterArchiveStats(); }
  // Load open→current drift map (unresolved rows) for the AI×CLV confidence boost
  if (_fighterClvDrift === null) { void loadFighterClvDrift(); }

  const _q = currentSearch.toLowerCase().trim();

  // Parse advanced filter tags: conf:70+, lean:over, fp:under, ss:over, td:under, split:yes, ev:+
  const _tagRe = /\b(conf|lean|fp|ss|td|ft|split|ev):([^\s]+)/gi;
  const _tags: Record<string, string> = {};
  const _nameQ = _q.replace(_tagRe, (_, k, v) => { _tags[k.toLowerCase()] = v.toLowerCase(); return ''; }).trim();

  let fighters = allFighters.filter(f => {
    if (_nameQ && !f.name.toLowerCase().includes(_nameQ)) return false;
    if (currentView === 'over' || currentView === 'under') {
      const _eff = getEffectiveLean(f);
      if (_eff.lean !== currentView) return false;
      // GLOW-UP 194: drop unplaceable effective leans from the directional triage —
      // no bettable side means it's not an actionable play. FP via the dedicated
      // placeability rule; stats via leanBestBook (which now filters under-side book
      // availability, e.g. Pick6 TD-under being More-only). Covers both the FP
      // fallback and a fighter whose top lean is an unplaceable stat under.
      const _placeable = _eff._source === 'fp'
        ? !shouldSkipFpSideForFighter(f, 'fp', currentView as 'over' | 'under')
        : leanBestBook(f, _eff._source, currentView).book != null;
      if (!_placeable) return false;
    }
    // Advanced tag filters
    if (_tags['lean']) { if (getEffectiveLean(f).lean !== _tags['lean']) return false; }
    if (_tags['fp'])   { if (f.lean?.lean !== _tags['fp']) return false; }
    if (_tags['ss'])   { if (f.lean_ss?.lean !== _tags['ss']) return false; }
    if (_tags['td'])   { if (f.lean_td?.lean !== _tags['td']) return false; }
    if (_tags['ft'])   { if (f.lean_ft?.lean !== _tags['ft']) return false; }
    if (_tags['split']) { if (_tags['split'] === 'yes' && !hasCrossStatConflict(f)) return false; }
    if (_tags['ev']) {
      const ev = computeFighterEV(f, getEffectiveLean(f));
      if (_tags['ev'] === '+' && (ev == null || ev <= 0)) return false;
      if (_tags['ev'] === '-' && (ev == null || ev >= 0)) return false;
    }
    if (_tags['conf']) {
      const op = _tags['conf'].endsWith('+') ? '>=' : _tags['conf'].endsWith('-') ? '<=' : '>=';
      const n  = parseInt(_tags['conf']);
      if (!isNaN(n)) { const c = getEffectiveLean(f).conf || 0; if (op === '>=' && c < n) return false; if (op === '<=' && c > n) return false; }
    }
    return true;
  });
  fighters = applySourceVisibilityFilter(fighters);
  fighters = sortFighters(fighters, currentSort);
  // Default sort = card-order display with fight badges. Reorder so each fight's
  // two fighters land at adjacent indices (i, i+1) in UFCStats card sequence;
  // the badge logic downstream is positional (Math.floor(i / 2) = fightIndex).
  if (currentSort === 'default') {
    fighters = orderFightersByCard(fighters);
  }

  if (fighters.length === 0) {
    container.innerHTML = '<div class="inline-empty-msg">No fighters match this filter</div>';
    renderModelHealthWidget();
    return;
  }
function sanitizeOpponentName(raw: unknown, selfName?: string): string | null {
  if (typeof raw !== 'string') return null;
  let val = raw.replace(/^\s*vs\.?\s*/i, '').replace(/\s+/g, ' ').trim();
  val = val.replace(/\b(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b.*$/i, '').trim();
  val = val.replace(/\b\d{1,2}:\d{2}\s*(?:am|pm)\b.*$/i, '').trim();
  val = val.replace(/\b(?:edt|est|cdt|cst|mdt|mst|pdt|pst|utc)\b.*$/i, '').trim();
  val = val.replace(/[^A-Za-z'\-\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!val || val.split(' ').length < 2) return null;
  if (selfName && val.toLowerCase() === selfName.toLowerCase()) return null;
  return val;
}

function sanitizeLooseOpponentToken(raw: unknown, selfName?: string): string | null {
  if (typeof raw !== 'string') return null;
  let val = raw.replace(/^\s*vs\.?\s*/i, '').replace(/\s+/g, ' ').trim();
  val = val.replace(/\b(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)\b.*$/i, '').trim();
  val = val.replace(/\b\d{1,2}:\d{2}\s*(?:am|pm)\b.*$/i, '').trim();
  val = val.replace(/\b(?:edt|est|cdt|cst|mdt|mst|pdt|pst|utc)\b.*$/i, '').trim();
  val = val.replace(/[^A-Za-z'\-\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!val) return null;
  if (selfName && val.toLowerCase() === selfName.toLowerCase()) return null;
  return val;
}

function findOpponentBySingleToken(token: string, selfName: string): AnalyzerFighter | null {
  const t = token.toLowerCase();
  const matches = allFighters.filter((x) => {
    if (x.name === selfName) return false;
    const parts = x.name.toLowerCase().split(' ');
    const last = parts[parts.length - 1] || '';
    return last === t;
  });
  return matches.length === 1 ? matches[0] : null;
}

function resolveOpponentEntry(fighter: AnalyzerFighter, explicitOpp: string | null, looseOpp: string | null): AnalyzerFighter | null {
  const rawOpp = explicitOpp || looseOpp;
  const fighterNorm = normalizeName(fighter.name) || fighter.name;
  const cardOpp = findOpponentFromUpcomingCard(fighter.name);
  const oppNorm = rawOpp ? (normalizeName(rawOpp) || rawOpp) : (cardOpp ? (normalizeName(cardOpp) || cardOpp) : null);
  const singleToken = looseOpp && looseOpp.split(' ').length === 1 ? looseOpp.toLowerCase() : null;

  // The UFCStats card is AUTHORITATIVE over a platform's abbreviated opponent text.
  // Pick6 renders opponents surname-only ("vs Miller"), which makes singleToken match
  // ANY fighter sharing that surname at score 82 — outranking nothing, because cardOpp
  // was previously consulted only when rawOpp was absent. On the Gamrot/Salkilld card
  // that paired Billy Ray Goff (card opponent: Ty Miller, welterweight) with JULIANA
  // Miller (womenFlyweight), because Ty Miller had no lines yet 6 days out and was the
  // only Miller missing from the board. That single bad pair then cascaded: Juliana was
  // consumed by Goff, so Ravena Oliveira slid onto Alexia Thainara and Amanda Lemos was
  // left orphaned — the classic "every pair after slot N is wrong" shift.
  const cardOppNorm = cardOpp ? (normalizeName(cardOpp) || cardOpp).toLowerCase() : null;
  const matchesCardOpp = (candidateNorm: string): boolean => {
    if (!cardOppNorm) return false;
    const c = candidateNorm.toLowerCase();
    return c === cardOppNorm || namesMatch(c, cardOppNorm);
  };

  // Fast-path: exact normalized name lookup via pre-built map (O(1) vs O(N) loop)
  if (oppNorm && _fighterByNorm) {
    const direct = _fighterByNorm.get(oppNorm.toLowerCase());
    if (direct && direct.name !== fighter.name) return direct;
  }

  let best: AnalyzerFighter | null = null;
  let bestScore = 0;
  let tieAtBest = false;

  for (const candidate of allFighters) {
    if (candidate.name === fighter.name) continue;

    const candidateNorm = normalizeName(candidate.name) || candidate.name;
    const candidateOppNorm = normalizeName(candidate.opponent || '') || null;
    let score = 0;

    if (oppNorm) {
      if (candidateNorm === oppNorm) score = Math.max(score, 100);
      else if (namesMatch(candidateNorm, oppNorm)) score = Math.max(score, 90);
      else if (rawOpp && namesMatch(candidate.name, rawOpp)) score = Math.max(score, 88);
    }

    // Card agreement wins outright — a full-name pairing from UFCStats beats any
    // abbreviated platform string.
    if (matchesCardOpp(candidateNorm)) score = Math.max(score, 110);

    // Surname/first-name guesses are only allowed when the card has NOTHING to say
    // about this fighter. If the card names an opponent and this candidate isn't
    // them, a shared surname is a collision, not a match.
    if (singleToken && (!cardOppNorm || matchesCardOpp(candidateNorm))) {
      const parts = candidateNorm.toLowerCase().split(' ');
      const first = parts[0] || '';
      const last = parts[parts.length - 1] || '';
      if (last === singleToken) score = Math.max(score, 82);
      else if (first === singleToken) score = Math.max(score, 78);
    }

    if (candidateOppNorm && (candidateOppNorm === fighterNorm || namesMatch(candidateOppNorm, fighterNorm))) {
      score = Math.max(score, 72);
    }

    if (score === 0) continue;

    if (score > bestScore) {
      best = candidate;
      bestScore = score;
      tieAtBest = false;
    } else if (score === bestScore) {
      tieAtBest = true;
    }
  }

  if (best && !tieAtBest) return best;

  // Both remaining fallbacks are surname/reverse guesses. Gate them the same way:
  // when the card names an opponent who simply isn't on the board yet (no lines
  // posted), the honest answer is "unresolved" — the row shows the card's name as a
  // placeholder. Guessing produces a wrong pairing AND steals a fighter from their
  // real opponent, shifting every pair after them.
  const fallbackBySingleToken = (singleToken && !cardOppNorm)
    ? findOpponentBySingleToken(singleToken, fighter.name)
    : null;
  if (fallbackBySingleToken) return fallbackBySingleToken;

  const fallbackByReverse = allFighters.find((x) => {
    if (x.name === fighter.name) return false;
    if (!x.opponent) return false;
    const xOppNorm = normalizeName(x.opponent) || x.opponent;
    if (cardOppNorm && !matchesCardOpp(normalizeName(x.name) || x.name)) return false;
    return xOppNorm === fighterNorm || namesMatch(xOppNorm, fighterNorm);
  });
  return fallbackByReverse || null;
}
  // Filter out cancelled fighters from the display list
  let activeFighters = fighters.filter(f => !isCancelledFighter(f.name));

  // GLOW-UP 194 L2 — Lean Over/Under are a directional TRIAGE, not a card readout,
  // so default them to conviction order (strongest directional play first) instead
  // of card-order. Any explicit sort choice still wins.
  const isLeanView = currentView === 'over' || currentView === 'under';
  if (isLeanView && currentSort === 'default') {
    const _dc = new Map<string, number>();
    for (const f of activeFighters) _dc.set(f.name, getDisplayedConf(f));
    activeFighters = [...activeFighters].sort((a, b) => {
      const ca = _dc.get(a.name) ?? 0, cb = _dc.get(b.name) ?? 0;
      if (cb !== ca) return cb - ca;
      const ea = computeFighterEV(a, getEffectiveLean(a)) ?? -999;
      const eb = computeFighterEV(b, getEffectiveLean(b)) ?? -999;
      return eb - ea;
    });
  }

  // GLOW-UP 198 L2 — apply the slate filter before _slatePresentSlots so a
  // filtered slate also collapses any book column it just emptied.
  const isSlateView = currentView === 'all';
  // Both the slate and the lean views populate _leanSlateData for their add-to-slip
  // handlers, so it has to be cleared for either — not just the lean branch.
  if (isSlateView) _leanSlateData.clear();
  const _slateTotalBeforeFilter = activeFighters.length;
  if (isSlateView && _slateFilter !== 'all') {
    const liveBooks = _slateFilter === 'gaps' ? slateLiveBooks(activeFighters) : [];
    activeFighters = activeFighters.filter(f => slateFilterAccepts(f, liveBooks));
  }

  // Compute which (platform, stat) slots have data for at least one fighter on
  // this slate. lineCell skips emitting cells (placeholder or real) for slots
  // outside this set, so dead columns don't take horizontal space across cards.
  _slatePresentSlots = (() => {
    const present = new Set<string>();
    const platforms: Array<'p6'|'ud'|'pp'|'betr'|'dk'> = ['p6','ud','pp','betr','dk'];
    const stats: Array<'fp'|'ss'|'td'|'ft'|'ctrl'> = ['fp','ss','td','ft','ctrl'];
    for (const f of activeFighters) {
      for (const p of platforms) {
        for (const s of stats) {
          if (p === 'dk' && s === 'fp') continue;
          const key = (s === 'fp' ? `line_${p}` : `line_${p}_${s}`) as keyof AnalyzerFighter;
          if ((f as unknown as Record<string, unknown>)[key as string] != null) {
            present.add(`${p}:${s}`);
          }
        }
      }
    }
    return present;
  })();

  // Build into a DocumentFragment so the browser only does layout/paint once
  // when the fragment is committed at the end. Direct container.appendChild
  // per row triggers a layout pass per row (~80 passes for a 26-fighter card).
  const frag = document.createDocumentFragment();

  if (isSlateView) frag.appendChild(buildSlateViewHeader(activeFighters, _slateTotalBeforeFilter));

  // A filter breaks opponent adjacency, so fall back to the flat list — same
  // reason an active search does.
  const showFightGroups = currentSort === 'default' && currentView === 'all'
    && !currentSearch.trim() && _slateFilter === 'all';

  const buildRowForFighter = (f: AnalyzerFighter, rowIdx: number, fightIndex: number): HTMLDivElement => {
    const explicitOpp = sanitizeOpponentName(f.opponent, f.name);
    const looseOpp = sanitizeLooseOpponentToken(f.opponent, f.name);
    const opp = explicitOpp || looseOpp;
    const oppEntry = resolveOpponentEntry(f, explicitOpp, looseOpp);
    debugLog(`TD/SS lookup: ${f.name} → rawOpp="${String(f.opponent ?? '')}" explicitOpp="${explicitOpp}" looseOpp="${looseOpp}" resolvedOpp="${opp}" oppEntry="${oppEntry?.name}" oppTdLine=${oppEntry?.line_p6_td ?? oppEntry?.line_ud_td ?? oppEntry?.line_pp_td ?? oppEntry?.line_betr_td ?? null} oppSsLine=${oppEntry?.line_p6_ss ?? oppEntry?.line_ud_ss ?? oppEntry?.line_pp_ss ?? oppEntry?.line_betr_ss ?? null} selfTdLine=${f.line_p6_td ?? f.line_ud_td ?? f.line_pp_td ?? f.line_betr_td ?? null}`);
    const row = buildFighterRow(f, oppEntry ?? null, fightIndex);
    row.style.setProperty('--row-index', String(rowIdx % 18));
    if (isPlaceholderFighter(f)) row.classList.add('fighter-row-placeholder');
    // GLOW-UP 198 L5 — slate rows can feed My Slate too, not just the lean views.
    if (isSlateView && !isPlaceholderFighter(f)) attachSlateSlipButton(row, f);
    return row;
  };

  if (showFightGroups) {
    const fights = buildFights(activeFighters);
    fights.forEach((fight, idx) => {
      const a = fight.fighterA;
      const b = fight.fighterB;
      // Skip only truly empty pairs (no UFCStats AND no platform lines). When
      // UFCStats whiffs the whole card (e.g. early fight-week before detail
      // pages exist), db.loaded is false everywhere but UD/Pick6 still have
      // real lines — those must render.
      const hasAnyLine = (x: AnalyzerFighter): boolean =>
        hasSourceLine(x, 'p6') || hasSourceLine(x, 'ud') || hasSourceLine(x, 'pp')
        || hasSourceLine(x, 'betr') || hasSourceLine(x, 'dk');
      if (b && isPlaceholderFighter(a) && isPlaceholderFighter(b) && !hasAnyLine(a) && !hasAnyLine(b)) return;

      const badgeText = fight.cardPosition === 'main' ? 'MAIN EVENT'
                      : fight.cardPosition === 'co-main' ? 'CO-MAIN'
                      : fight.cardPosition === 'main-card' ? 'MAIN CARD'
                      : 'PRELIM';
      const badgeCls = fight.cardPosition === 'main' ? 'main'
                     : fight.cardPosition === 'co-main' ? 'co'
                     : fight.cardPosition === 'main-card' ? 'card'
                     : 'prelim';
      const header = document.createElement('div');
      header.className = `fight-group-header fgh-${badgeCls}`;
      const f2Name = b?.name || '';
      header.innerHTML = `<div class="fight-group-line"></div><span class="fight-badge ${badgeCls}">${badgeText}</span><button class="fight-cancel-btn" title="Mark fight as cancelled — hides both fighters from the slate (use for withdrawals)">× Cancel fight</button><div class="fight-group-line"></div>`;
      const cancelBtn = header.querySelector('.fight-cancel-btn') as HTMLButtonElement;
      cancelBtn?.addEventListener('click', () => { void cancelFight(a.name, f2Name); });
      frag.appendChild(header);

      const rowA = buildRowForFighter(a, idx * 2, idx);

      if (!b) {
        frag.appendChild(rowA);
        return;
      }

      const rowB = buildRowForFighter(b, idx * 2 + 1, idx);
      const hasSpine = spineHasContent(fight);

      const pair = document.createElement('div');
      pair.className = 'fight-pair';
      if (!hasSpine) pair.classList.add('fight-pair-no-spine');
      rowA.classList.add('fight-pair-fighter-a');
      rowB.classList.add('fight-pair-fighter-b');

      pair.appendChild(rowA);
      if (hasSpine) {
        pair.appendChild(buildFightSpine(fight));
      } else {
        const emptySpine = document.createElement('div');
        emptySpine.className = 'fight-spine fight-spine-empty';
        // Filled-mode content needs to exist in DOM even when no header chips
        // exist, so the `.fight-pair:has(.expanded)` CSS rule can reveal it.
        emptySpine.innerHTML = buildFilledSpineWrapper(fight.fighterA, fight.fighterB);
        pair.appendChild(emptySpine);
      }
      pair.appendChild(rowB);
      frag.appendChild(pair);
    });
  } else {
    // GLOW-UP 194 — Lean Over/Under triage: command header (L1), rank badges (L2),
    // same-fight correlation flags (L4), one-click add-to-slip (L5).
    if (isLeanView) {
      _leanSlateData.clear();
      frag.appendChild(buildLeanViewHeader(activeFighters, currentView as 'over' | 'under'));
    }
    const inViewNames = isLeanView ? new Set(activeFighters.map(x => normalizeName(x.name))) : null;
    activeFighters.forEach((f, i) => {
      const row = buildRowForFighter(f, i, Math.floor(i / 2));
      if (isLeanView) {
        row.classList.add('lean-view-row');
        const lean = getEffectiveLean(f);
        const { key, pick } = buildLeanSlatePick(f, lean);
        _leanSlateData.set(key, pick);
        const inSlate = bestPicksSlate.has(key);
        const oppNorm = f.opponent ? normalizeName(f.opponent) : null;
        const sameFight = !!(oppNorm && inViewNames && inViewNames.has(oppNorm));
        if (sameFight) row.classList.add('lean-samefight');
        const controls = document.createElement('div');
        controls.className = 'lean-row-controls';
        controls.innerHTML = `<span class="lean-rank" title="Conviction rank">#${i + 1}</span>`
          + (sameFight ? `<span class="lean-corr-flag" title="Opponent also leans ${currentView.toUpperCase()} — same-fight ${currentView} legs are negatively correlated; lean one side">⚠ corr</span>` : '')
          + `<button class="lean-slate-btn${inSlate ? ' on' : ''}" data-slate-key="${key.replace(/"/g, '&quot;')}" title="${inSlate ? 'Remove from My Slate' : 'Add to My Slate'}">${inSlate ? '✓' : '+'}</button>`;
        const fmain = row.querySelector('.fighter-main');
        // Compact-mode play line — fills the space freed by hiding the line grid so
        // a slim row still shows WHAT to bet (side · stat · line · book), not just
        // the direction. Only when there's a placeable book (no book → no bet → no
        // line). display:none in full mode → takes no grid cell.
        if (pick.book != null && pick.line != null) {
          const cp = document.createElement('div');
          cp.className = 'lean-compact-play';
          cp.innerHTML = `<span class="lcp-side ${pick.dir === 'OVER' ? 'over' : 'under'}">${pick.dir === 'OVER' ? '▲' : '▼'} ${pick.dir}</span>`
            + `<span class="lcp-stat">${pick.statLabel}</span>`
            + `<span class="lcp-line">${pick.line}</span>`
            + `<span class="lcp-book" title="Best entry book for this side">@ ${pick.bookLabel}</span>`;
          const finfo = fmain?.querySelector('.fighter-info');
          if (finfo && finfo.nextSibling) fmain!.insertBefore(cp, finfo.nextSibling);
          else fmain?.appendChild(cp);
        }
        fmain?.prepend(controls);
      }
      frag.appendChild(row);
      if (i % 2 === 1 && i < activeFighters.length - 1) {
        const sp = document.createElement('div');
        sp.style.cssText = 'height:8px';
        frag.appendChild(sp);
      }
    });
  }

  // Show cancelled fights at bottom with restore option
  if (cancelledFightPairs.length > 0 && showFightGroups) {
    const cancelHeader = document.createElement('div');
    cancelHeader.className = 'fight-group-header';
    cancelHeader.innerHTML = `<div class="fight-group-line"></div><span class="fight-badge cancelled">CANCELLED</span><div class="fight-group-line"></div>`;
    frag.appendChild(cancelHeader);
    for (const pair of cancelledFightPairs) {
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;align-items:center;gap:8px;padding:4px 8px;opacity:0.5;font-size:12px;color:var(--text3);';
      row.innerHTML = `<span style="text-decoration:line-through">${pair.f1} vs ${pair.f2}</span>`;
      const restoreBtn = document.createElement('button');
      restoreBtn.className = 'fight-restore-btn';
      restoreBtn.textContent = 'Restore';
      restoreBtn.addEventListener('click', () => { void restoreCancelledFight(pair.f1, pair.f2); });
      row.appendChild(restoreBtn);
      frag.appendChild(row);
    }
  }

  // Commit the entire fragment in one DOM operation.
  container.appendChild(frag);

  // GLOW-UP 198 L2/L3 — slate filter + density handlers. Bound after the commit
  // because the header lives inside the fragment.
  container.classList.toggle('slate-compact', isSlateView && _slateCompact);
  if (isSlateView) {
    container.querySelector<HTMLElement>('[data-slate-compact]')?.addEventListener('click', () => {
      _slateCompact = !_slateCompact;
      renderFighters();
    });
    container.querySelectorAll<HTMLElement>('[data-slate-filter]').forEach(btn => {
      btn.addEventListener('click', () => {
        const next = (btn.dataset['slateFilter'] || 'all') as SlateFilter;
        // Re-clicking the active chip clears it, so the filter is never a trap.
        _slateFilter = _slateFilter === next ? 'all' : next;
        renderFighters();
      });
    });
    // The My Slate tray is built inside the Best Picks render path only, so adding
    // from here has nowhere to show itself. Jump the user to the tray instead.
    container.querySelector<HTMLElement>('[data-slate-jump]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      bestPicksSlateOpen = true;
      (document.querySelector('.tab-btn[data-view="bestpicks"]') as HTMLElement | null)?.click();
    });
    // L5 — same toggle semantics as the lean views' .lean-slate-btn. stopPropagation
    // matters: the row itself is clickable and would otherwise expand underneath.
    container.querySelectorAll<HTMLElement>('.slate-slip-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const key = btn.dataset['slateKey'] || '';
        if (bestPicksSlate.has(key)) {
          bestPicksSlate.delete(key);
        } else {
          const d = _leanSlateData.get(key);
          if (d) { if (!bestPicksSlate.size) bestPicksSlateOpen = true; bestPicksSlate.set(key, d); }
        }
        renderFighters();
      });
    });
  }

  // GLOW-UP 194 — lean-view container state (L3 compact) + control handlers.
  container.classList.toggle('lean-triage', isLeanView);
  container.classList.toggle('lean-compact', isLeanView && _leanCompact);
  if (isLeanView) {
    container.querySelectorAll<HTMLElement>('.lean-slate-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const key = btn.dataset['slateKey'] || '';
        if (bestPicksSlate.has(key)) {
          bestPicksSlate.delete(key);
        } else {
          const d = _leanSlateData.get(key);
          if (d) { if (!bestPicksSlate.size) bestPicksSlateOpen = true; bestPicksSlate.set(key, d); }
        }
        renderFighters();
      });
    });
    container.querySelector<HTMLElement>('[data-lean-compact]')?.addEventListener('click', (e) => {
      e.stopPropagation();
      _leanCompact = !_leanCompact;
      renderFighters();
    });
  }

  // ── Animate bars on scroll into view (IntersectionObserver) ─────────
  // Skip bars inside .fighter-detail — those are hidden by default and get
  // animated on toggleRow expand. Animating them here scheduled 100+ setTimeouts
  // per row for invisible work, then toggleRow re-fired them on expand.
  // Also cap stagger total at ~350ms so the wave doesn't drag for huge rows.
  const fillBarsInElement = (el: Element) => {
    const bars = el.querySelectorAll<HTMLElement>('[data-fill-width]');
    let visibleIdx = 0;
    bars.forEach((bar) => {
      if (bar.closest('.fighter-detail')) return;
      const target = bar.dataset.fillWidth!;
      const delay = Math.min(visibleIdx * 6, 350);
      visibleIdx++;
      setTimeout(() => { bar.style.width = target; }, delay);
    });
  };

  if (typeof IntersectionObserver !== 'undefined') {
    const barObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        fillBarsInElement(entry.target);
        barObserver.unobserve(entry.target);
      });
    }, { threshold: 0.1 });

    container.querySelectorAll('.fighter-row').forEach(row => barObserver.observe(row));
  } else {
    // Fallback: fill all bars immediately
    fillBarsInElement(container);
  }

  renderModelHealthWidget();
}

// ── NEWS FETCHING ──────────────────────────────────────────────────────────
// ── MANUAL WEIGHT-MISS OVERRIDE ────────────────────────────────────────────
// Used when Google News auto-detection can't disambiguate (e.g., headline
// uses "MMA legend" instead of fighter name). User flags via console:
//   window.markMissedWeight('Jeremy Stephens', 4)
//   window.clearMissedWeight('Jeremy Stephens')
// Manual entries persist in chrome.storage.local and are re-applied after
// every fetchAllFighterNews (which clears auto-signals first).
async function loadManualWeightMisses(): Promise<ManualWeightMissMap> {
  try {
    const data = await storageGet<Record<string, unknown>>([MANUAL_WEIGHT_MISS_KEY]);
    const raw = data[MANUAL_WEIGHT_MISS_KEY];
    return (raw && typeof raw === 'object') ? (raw as ManualWeightMissMap) : {};
  } catch { return {}; }
}
async function saveManualWeightMisses(map: ManualWeightMissMap): Promise<void> {
  await new Promise<void>((res) => chrome.storage.local.set({ [MANUAL_WEIGHT_MISS_KEY]: map }, res));
}
async function applyManualWeightMisses(): Promise<void> {
  const map = await loadManualWeightMisses();
  for (const [nameLower, entry] of Object.entries(map)) {
    const lbs = Number(entry.lbsOver);
    if (!Number.isFinite(lbs) || lbs <= 0) continue;
    _weightMissSignals.set(nameLower, {
      lbsOver: lbs,
      severity: severityFromLbs(lbs),
      source: `Manual override: ${lbs} lbs over`,
    });
  }
}
async function setManualWeightMiss(name: string, lbsOver: number): Promise<void> {
  const map = await loadManualWeightMisses();
  map[name.toLowerCase()] = { lbsOver, addedAt: Date.now() };
  await saveManualWeightMisses(map);
  await applyManualWeightMisses();
  renderFighters();
  console.log(`[UFC Analyzer] Manual weight-miss flag set: ${name} = ${lbsOver} lbs over. Badge should now appear.`);
}
async function clearManualWeightMiss(name: string): Promise<void> {
  const map = await loadManualWeightMisses();
  const key = name.toLowerCase();
  if (!(key in map)) {
    console.log(`[UFC Analyzer] No manual flag found for ${name}.`);
    return;
  }
  delete map[key];
  await saveManualWeightMisses(map);
  _weightMissSignals.delete(key);
  renderFighters();
  console.log(`[UFC Analyzer] Manual weight-miss flag cleared for ${name}.`);
}
async function listManualWeightMisses(): Promise<void> {
  const map = await loadManualWeightMisses();
  const entries = Object.entries(map);
  if (!entries.length) { console.log('[UFC Analyzer] No manual weight-miss flags set.'); return; }
  console.table(entries.map(([name, e]) => ({
    fighter: name,
    lbsOver: e.lbsOver,
    addedAt: new Date(e.addedAt).toLocaleString(),
  })));
}
// Expose to console
(window as unknown as { markMissedWeight: typeof setManualWeightMiss }).markMissedWeight = setManualWeightMiss;
(window as unknown as { clearMissedWeight: typeof clearManualWeightMiss }).clearMissedWeight = clearManualWeightMiss;
(window as unknown as { listMissedWeights: typeof listManualWeightMisses }).listMissedWeights = listManualWeightMisses;

// ── MANUAL FP-UNDER AVAILABILITY OVERRIDE ──────────────────────────────────
// Pick6 makes a fighter's FP prop More/OVER-only when THEY treat him as the
// structural dog — which is their own pricing call, not the sportsbook's. The
// scraped Less-button flag (fp_under_available) is the authority, but it goes
// undefined whenever findCardText can't locate the cards on Pick6's current
// layout, and an undefined flag fails OPEN. When the sportsbook moneyline also
// disagrees (a near-pick-em fighter Pick6 treats as the dog), nothing catches
// it and an unplaceable FP UNDER reaches the board.
//   window.blockFpUnder('Steve Erceg')      → mark his Pick6 FP UNDER unplaceable
//   window.unblockFpUnder('Steve Erceg')    → clear it when Pick6 adds the Less button
//   window.listFpUnderBlocks()
// Persists in chrome.storage.local, so it survives reloads and needs no rebuild
// when the line flips mid-week.
const MANUAL_FP_UNDER_BLOCK_KEY = 'manual_fp_under_blocked_v1' as const;
const _fpUnderBlocked = new Set<string>();
async function loadFpUnderBlocks(): Promise<void> {
  try {
    const data = await storageGet<Record<string, unknown>>([MANUAL_FP_UNDER_BLOCK_KEY]);
    const raw = data[MANUAL_FP_UNDER_BLOCK_KEY];
    _fpUnderBlocked.clear();
    if (Array.isArray(raw)) for (const n of raw) if (typeof n === 'string') _fpUnderBlocked.add(n.toLowerCase());
  } catch { /* absent key is fine */ }
}
async function saveFpUnderBlocks(): Promise<void> {
  await new Promise<void>((res) => chrome.storage.local.set({ [MANUAL_FP_UNDER_BLOCK_KEY]: [..._fpUnderBlocked] }, res));
}
async function blockFpUnder(...names: string[]): Promise<void> {
  for (const n of names) _fpUnderBlocked.add(String(n).toLowerCase().trim());
  await saveFpUnderBlocks();
  _leanCache = null;
  renderFighters();
  console.log(`[UFC Analyzer] Pick6 FP UNDER blocked for: ${names.join(', ')}. Now ${_fpUnderBlocked.size} total.`);
}
async function unblockFpUnder(...names: string[]): Promise<void> {
  for (const n of names) _fpUnderBlocked.delete(String(n).toLowerCase().trim());
  await saveFpUnderBlocks();
  _leanCache = null;
  renderFighters();
  console.log(`[UFC Analyzer] Pick6 FP UNDER un-blocked for: ${names.join(', ')}. Now ${_fpUnderBlocked.size} total.`);
}
function listFpUnderBlocks(): void {
  if (!_fpUnderBlocked.size) { console.log('[UFC Analyzer] No manual FP-UNDER blocks set.'); return; }
  console.log('[UFC Analyzer] Pick6 FP UNDER blocked for:', [..._fpUnderBlocked].join(', '));
}
(window as unknown as { blockFpUnder: typeof blockFpUnder }).blockFpUnder = blockFpUnder;
(window as unknown as { unblockFpUnder: typeof unblockFpUnder }).unblockFpUnder = unblockFpUnder;
(window as unknown as { listFpUnderBlocks: typeof listFpUnderBlocks }).listFpUnderBlocks = listFpUnderBlocks;

// ── MANUAL FIGHTER-STYLE OVERRIDE ──────────────────────────────────────────
// deriveStyle is a crude threshold classifier (tdAvg > 2.0 → grappler, etc.)
// that misfires when a fighter has stat-padded numbers vs lower competition
// or when their matchup-specific role differs from career averages. User
// flags via console:
//   window.setFighterStyle('Melquizael Costa', 'striker')
//   window.clearFighterStyle('Melquizael Costa')
//   window.listFighterStyles()
// After overriding, re-run Generate Predictions to recompute SS/TD with the
// new style. Persists in chrome.storage.local under FIGHTER_STYLE_OVERRIDE_KEY.
async function loadFighterStyleOverrides(): Promise<Record<string, FighterStyle>> {
  try {
    const data = await storageGet<Record<string, unknown>>([FIGHTER_STYLE_OVERRIDE_KEY]);
    const raw = data[FIGHTER_STYLE_OVERRIDE_KEY];
    return (raw && typeof raw === 'object') ? (raw as Record<string, FighterStyle>) : {};
  } catch { return {}; }
}
async function saveFighterStyleOverrides(map: Record<string, FighterStyle>): Promise<void> {
  await new Promise<void>((res) => chrome.storage.local.set({ [FIGHTER_STYLE_OVERRIDE_KEY]: map }, res));
}
async function applyFighterStyleOverrides(): Promise<void> {
  const map = await loadFighterStyleOverrides();
  _fighterStyleOverrides.clear();
  for (const [nameLower, style] of Object.entries(map)) {
    if (style === 'striker' || style === 'grappler' || style === 'balanced') {
      _fighterStyleOverrides.set(nameLower, style);
    }
  }
  // Mutate any already-cached fighter DBs so panels reflect the change without
  // a refetch. Generate Predictions still needs to re-run to recompute SS/TD.
  for (const [cacheKey, db] of Object.entries(statsCache)) {
    const override = _fighterStyleOverrides.get(cacheKey.trim().toLowerCase());
    if (override && db.style !== override) db.style = override;
  }
}
async function setFighterStyle(name: string, style: FighterStyle): Promise<void> {
  if (style !== 'striker' && style !== 'grappler' && style !== 'balanced') {
    console.error(`[UFC Analyzer] Invalid style "${style}" — must be 'striker' | 'grappler' | 'balanced'`);
    return;
  }
  const map = await loadFighterStyleOverrides();
  map[name.trim().toLowerCase()] = style;
  await saveFighterStyleOverrides(map);
  await applyFighterStyleOverrides();
  console.log(`[UFC Analyzer] Style override set: ${name} → ${style}. Re-run Generate Predictions to recompute SS/TD/FP with the new style.`);
}
async function clearFighterStyle(name: string): Promise<void> {
  const map = await loadFighterStyleOverrides();
  const key = name.trim().toLowerCase();
  if (!(key in map)) {
    console.log(`[UFC Analyzer] No style override found for ${name}.`);
    return;
  }
  delete map[key];
  await saveFighterStyleOverrides(map);
  _fighterStyleOverrides.delete(key);
  console.log(`[UFC Analyzer] Style override cleared for ${name}. Re-run Generate Predictions to revert to classifier output.`);
}
async function listFighterStyles(): Promise<void> {
  const map = await loadFighterStyleOverrides();
  const entries = Object.entries(map);
  if (!entries.length) { console.log('[UFC Analyzer] No fighter-style overrides set.'); return; }
  console.table(entries.map(([name, style]) => ({ fighter: name, style })));
}
(window as unknown as { setFighterStyle: typeof setFighterStyle }).setFighterStyle = setFighterStyle;
(window as unknown as { clearFighterStyle: typeof clearFighterStyle }).clearFighterStyle = clearFighterStyle;

// ── MANUAL LINE-BASELINE RESET ─────────────────────────────────────────────
// When a fighter's opponent changes mid-event (e.g., Bellato pulls out and
// Edwards replaces him), the prior fighter's baselines become stale — the new
// opener vs the replacement gets diffed against the old line vs the dropped
// opponent, producing a false drift + RLM badge. Baselines are keyed by
// fighter name alone (no opponent in the key) and the existing wipe triggers
// only fire on event changes, so opponent-swaps within the same event need a
// manual nudge. User runs:
//   window.resetFighterBaseline('Modestas Bukauskas')
// to clear all opening-line + prev-refresh + history entries for that fighter
// across every platform/stat. Next refresh re-snapshots current lines as the
// new opener.
async function resetFighterBaseline(name: string): Promise<void> {
  const target = name.trim().toLowerCase();
  if (!target) {
    console.error('[UFC Analyzer] resetFighterBaseline: name required');
    return;
  }
  let openingCleared = 0;
  for (const key of [..._openingLines.keys()]) {
    const parts = key.split('|');
    if (parts[2] === target) { _openingLines.delete(key); openingCleared++; }
  }
  let prevCleared = 0;
  for (const key of [..._prevRefreshLines.keys()]) {
    const parts = key.split('|');
    if (parts[2] === target) { _prevRefreshLines.delete(key); prevCleared++; }
  }
  let historyCleared = 0;
  for (const key of Object.keys(_lineHistory.series)) {
    if (key.startsWith(`${target}|`)) { delete _lineHistory.series[key]; historyCleared++; }
  }
  if (openingCleared === 0 && prevCleared === 0 && historyCleared === 0) {
    console.log(`[UFC Analyzer] resetFighterBaseline: no entries found for "${name}" — check spelling. Nothing cleared.`);
    return;
  }
  _lineHistory.updatedAt = Date.now();
  await Promise.all([
    persistOpeningLines(),
    storageSet({ [STORAGE_LINE_HISTORY_KEY]: _lineHistory }),
  ]);
  renderFighters();
  console.log(`[UFC Analyzer] Baseline reset for ${name}: cleared ${openingCleared} opening / ${prevCleared} prev-refresh / ${historyCleared} history entries. Next refresh re-anchors.`);
}
(window as unknown as { resetFighterBaseline: typeof resetFighterBaseline }).resetFighterBaseline = resetFighterBaseline;
(window as unknown as { listFighterStyles: typeof listFighterStyles }).listFighterStyles = listFighterStyles;

// fetchFighterNews moved to ./analyzer/news.ts. fetchAllFighterNews stays here
// because it orchestrates module-scoped state (allFighters, renderFighters).
async function fetchAllFighterNews(): Promise<void> {
  _newsAlertFighters.clear();
  _weightMissSignals.clear();
  // Pass 1 — fetch all per-fighter results in parallel, set alert flags, and
  // collect weight-miss candidates per fighter. Outlets often use generic
  // clickbait titles ("Longtime veteran misses weight at UFC Perth") that
  // never name the misser in title or description, so a strict name-in-haystack
  // gate would miss them. Instead we collect candidates broadly here and let
  // Pass 2 attribute by counting articles per fighter within the fight pair —
  // the misser's name appears in the article body (so Google News surfaces
  // multiple matching articles in their search) while the opponent's search
  // returns at most a single tangential card-recap mention.
  type WMCandidate = { sig: WeightMissSignal; index: number; namesSelf: boolean };
  const candidatesByFighter = new Map<string, WMCandidate[]>();
  await Promise.all(allFighters.map(async (f) => {
    const items = await fetchFighterNews(f.name);
    const hasAlert = items.some(item =>
      NEWS_INJURY_KEYWORDS.some(kw => item.title.toLowerCase().includes(kw))
    );
    if (hasAlert) _newsAlertFighters.add(f.name.toLowerCase());
    const fLower = f.name.toLowerCase();
    const fLast = fLower.split(' ').pop() || fLower;
    // Cross-fighter guard: outlets sometimes name a different fighter on the
    // same card ("JDM and Prates make weight"); reject those for f.
    const otherLastNames = allFighters
      .filter(o => o.name.toLowerCase() !== fLower)
      .map(o => (o.name.toLowerCase().split(' ').pop() || ''))
      .filter(ln => ln.length >= 4 && ln !== fLast);
    const fCands: WMCandidate[] = [];
    items.forEach((item, idx) => {
      const sig = parseWeightMissFromTitle(item.title, f.name);
      if (!sig) return;
      const haystack = (item.title + ' ' + (item.description || '')).toLowerCase();
      const namesSelf = haystack.includes(fLower) || new RegExp(`\\b${fLast}\\b`).test(haystack);
      const namesOther = otherLastNames.some(ln => new RegExp(`\\b${ln}\\b`).test(haystack));
      // Reject only if another fighter is explicitly named — those are about
      // someone else, not us. Articles that name no one are kept as candidates;
      // Pass 2 disambiguates them via per-pair count comparison.
      if (namesOther) return;
      fCands.push({ sig, index: idx, namesSelf });
    });
    if (fCands.length > 0) candidatesByFighter.set(fLower, fCands);
  }));

  // Pass 2 — within each fight pair, compare candidate counts. The actual
  // misser has 2+ matching articles (their name is in the article body so
  // Google News surfaces multiple weight-miss articles in their search); the
  // opponent has 0–1 tangential card-recap mentions. A clear margin attributes
  // the signal; ambiguity (both sides similar) skips. As a tiebreaker for
  // close cases, prefer a fighter explicitly named in title/description.
  const applyBestSignal = (key: string, cands: WMCandidate[]): void => {
    let best: WMCandidate | null = null;
    for (const c of cands) {
      if (!best) { best = c; continue; }
      // Prefer higher severity; then higher lbsOver; then namesSelf; then lower index.
      if (best.sig.severity === 'unknown' && c.sig.severity !== 'unknown') { best = c; continue; }
      if (c.sig.severity === 'unknown' && best.sig.severity !== 'unknown') continue;
      if (c.sig.lbsOver != null && best.sig.lbsOver != null && c.sig.lbsOver > best.sig.lbsOver) { best = c; continue; }
      if (c.sig.lbsOver != null && best.sig.lbsOver == null) { best = c; continue; }
      if (c.namesSelf && !best.namesSelf) { best = c; continue; }
      if (c.index < best.index && c.namesSelf === best.namesSelf) best = c;
    }
    if (best) _weightMissSignals.set(key, best.sig);
  };
  const processed = new Set<string>();
  for (const f of allFighters) {
    const fLower = f.name.toLowerCase();
    if (processed.has(fLower)) continue;
    const oppLower = (f.opponent || '').toLowerCase();
    const fCands = candidatesByFighter.get(fLower) || [];
    const oCands = oppLower ? (candidatesByFighter.get(oppLower) || []) : [];
    processed.add(fLower);
    if (oppLower) processed.add(oppLower);
    if (fCands.length === 0 && oCands.length === 0) continue;
    const fCount = fCands.length;
    const oCount = oCands.length;
    // Clear margin: 2+ articles AND at least 2 more than the opponent.
    if (fCount >= 2 && fCount - oCount >= 2) { applyBestSignal(fLower, fCands); continue; }
    if (oCount >= 2 && oCount - fCount >= 2) { applyBestSignal(oppLower, oCands); continue; }
    // Close counts: fall back to the explicit-name gate. If exactly one side
    // has a candidate that names them in title/description, fire for them.
    const fNamed = fCands.filter(c => c.namesSelf);
    const oNamed = oCands.filter(c => c.namesSelf);
    if (fNamed.length > 0 && oNamed.length === 0) applyBestSignal(fLower, fNamed);
    else if (oNamed.length > 0 && fNamed.length === 0) applyBestSignal(oppLower, oNamed);
    // else: ambiguous — both sides named or neither, similar counts → skip.
  }

  // Apply manual overrides AFTER auto-detection so user flags always win.
  await applyManualWeightMisses();

  renderFighters();
}

// ── STYLE MATCHUP PANEL ────────────────────────────────────────────────────
function buildModelRivalryPanel(lean: LeanResult): string {
  const models = lean.rivalryModels || [];
  if (!models.length) return '';

  const consensusTone = lean.rivalryConsensus === 'over'
    ? 'var(--green)'
    : lean.rivalryConsensus === 'under'
      ? 'var(--red)'
      : 'var(--text2)';
  const consensusText = lean.rivalryConsensus === 'over'
    ? 'OVER consensus'
    : lean.rivalryConsensus === 'under'
      ? 'UNDER consensus'
      : 'Split board';
  const impactText = lean.rivalryConfidenceDelta
    ? `Confidence ${lean.rivalryConfidenceDelta > 0 ? '+' : ''}${lean.rivalryConfidenceDelta}`
    : 'No confidence change';
  const rows = models.map((model) => {
    const tone = model.lean === 'over'
      ? 'var(--green)'
      : model.lean === 'under'
        ? 'var(--red)'
        : 'var(--text2)';
    const bg = model.lean === 'over'
      ? 'rgba(72,199,142,0.10)'
      : model.lean === 'under'
        ? 'rgba(255,100,100,0.10)'
        : 'rgba(125,145,190,0.08)';
    const border = model.model === lean.rivalryStrongDissent
      ? 'rgba(255,184,77,0.55)'
      : model.lean === 'over'
        ? 'rgba(72,199,142,0.25)'
        : model.lean === 'under'
          ? 'rgba(255,100,100,0.25)'
          : 'rgba(125,145,190,0.18)';
    const label = model.lean === 'over' ? '▲ OVER' : model.lean === 'under' ? '▼ UNDER' : '~ PUSH';
    return `<div style="display:flex;justify-content:space-between;gap:10px;padding:8px 10px;border-radius:10px;border:1px solid ${border};background:${bg}">
      <div style="min-width:0">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <span style="font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:${tone}">${model.label}</span>
          ${model.model === lean.rivalryStrongDissent ? `<span style="font-size:9px;padding:2px 6px;border-radius:999px;background:rgba(255,184,77,0.12);border:1px solid rgba(255,184,77,0.35);color:#ffbe6b;letter-spacing:0.08em;text-transform:uppercase">Dissent</span>` : ''}
        </div>
        <div style="font-size:10px;color:var(--text2);margin-top:4px">${model.note}</div>
      </div>
      <div style="text-align:right;min-width:78px">
        <div style="font-size:11px;font-weight:700;color:${tone}">${label}</div>
        <div style="font-size:10px;color:${tone};margin-top:3px">${model.confidence}%${model.projected != null ? ` · ${model.projected.toFixed(1)}` : ''}</div>
      </div>
    </div>`;
  }).join('');

  return `<div class="detail-panel mr-panel">
    <div class="detail-panel-title">Model Rivalry</div>
    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">
      <span class="style-matchup-chip style-chip-default" style="color:${consensusTone}">${consensusText}</span>
      <span style="font-size:10px;color:var(--text2);letter-spacing:0.06em;text-transform:uppercase">${impactText}</span>
    </div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:8px">${lean.rivalrySummary || 'Four FP brains are cross-checking the lean.'}</div>
    ${lean.rivalryDissent ? `<div style="font-size:10px;color:#ffbe6b;background:rgba(255,184,77,0.08);border:1px solid rgba(255,184,77,0.28);border-radius:8px;padding:7px 9px;margin-bottom:8px">${lean.rivalryDissent}</div>` : ''}
    <div style="display:grid;gap:8px">${rows}</div>
  </div>`;
}

// ── FAIR VALUE PANEL ──────────────────────────────────────────────────────
function buildFairValuePanel(lean: LeanResult): string {
  if (lean.fairValue == null || lean.fairValueEdge == null) return '';
  const fv = lean.fairValue;
  const edge = lean.fairValueEdge;
  const perBook = lean.fairValuePerBook || [];
  const absEdge = Math.abs(edge);

  // Edge tier for the header badge
  const edgeTier = absEdge >= 4 ? 'strong' : absEdge >= 2 ? 'moderate' : 'slim';
  const edgeColor = absEdge >= 4
    ? (edge > 0 ? 'var(--green)' : 'var(--red)')
    : absEdge >= 2
      ? 'var(--amber)'
      : 'var(--text2)';
  const edgeBg = absEdge >= 4
    ? (edge > 0 ? 'rgba(72,199,142,0.10)' : 'rgba(255,100,100,0.10)')
    : absEdge >= 2
      ? 'rgba(240,192,64,0.10)'
      : 'rgba(125,145,190,0.08)';
  const edgeDir = edge > 0 ? 'OVER value' : edge < 0 ? 'UNDER value' : 'No edge';
  const tierLabel = edgeTier === 'strong' ? 'Strong edge' : edgeTier === 'moderate' ? 'Moderate edge' : 'Slim edge';

  // Per-model projections row
  const models = lean.rivalryModels || [];
  const modelCells = models
    .filter(m => m.projected != null)
    .map(m => {
      const tone = m.lean === 'over' ? 'var(--green)' : m.lean === 'under' ? 'var(--red)' : 'var(--text2)';
      return `<div style="text-align:center;min-width:58px">
        <div style="font-size:9px;text-transform:uppercase;letter-spacing:0.08em;color:var(--text2);margin-bottom:3px">${m.label}</div>
        <div style="font-size:13px;font-weight:700;color:${tone}">${m.projected!.toFixed(1)}</div>
      </div>`;
    }).join('');

  // Per-book edge rows
  const bookRows = perBook.map(b => {
    const bEdge = b.edge;
    const bAbs = Math.abs(bEdge);
    const bColor = bAbs >= 4
      ? (bEdge > 0 ? 'var(--green)' : 'var(--red)')
      : bAbs >= 2
        ? 'var(--amber)'
        : 'var(--text2)';
    const bBg = bAbs >= 4
      ? (bEdge > 0 ? 'rgba(72,199,142,0.08)' : 'rgba(255,100,100,0.08)')
      : bAbs >= 2
        ? 'rgba(240,192,64,0.08)'
        : 'rgba(125,145,190,0.06)';
    const bBorder = bAbs >= 4
      ? (bEdge > 0 ? 'rgba(72,199,142,0.30)' : 'rgba(255,100,100,0.30)')
      : bAbs >= 2
        ? 'rgba(240,192,64,0.30)'
        : 'rgba(125,145,190,0.18)';
    const bestTag = perBook.length > 1 && b === perBook[0] && bAbs >= 2
      ? `<span style="font-size:8px;padding:1px 5px;border-radius:999px;background:rgba(72,199,142,0.12);border:1px solid rgba(72,199,142,0.35);color:var(--green);letter-spacing:0.08em;text-transform:uppercase;margin-left:6px">Best</span>`
      : '';
    return `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 10px;border-radius:8px;border:1px solid ${bBorder};background:${bBg}">
      <div style="display:flex;align-items:center;gap:6px">
        <span style="font-size:10px;font-weight:700;letter-spacing:0.08em;color:var(--text1)">${b.source}</span>
        <span style="font-size:10px;color:var(--text2)">line ${b.line}</span>
        ${bestTag}
      </div>
      <div style="text-align:right">
        <span style="font-size:12px;font-weight:700;color:${bColor}">${bEdge > 0 ? '+' : ''}${bEdge.toFixed(1)}</span>
        <span style="font-size:9px;color:var(--text2);margin-left:4px">pts</span>
      </div>
    </div>`;
  }).join('');

  return `<div class="detail-panel fv-panel">
    <div class="detail-panel-title">Fair Value Generator</div>
    <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
      <div style="display:flex;align-items:baseline;gap:6px">
        <span style="font-size:20px;font-weight:800;color:var(--text1)">${fv.toFixed(1)}</span>
        <span style="font-size:10px;color:var(--text2);text-transform:uppercase;letter-spacing:0.06em">fair line</span>
      </div>
      <div style="padding:3px 10px;border-radius:999px;background:${edgeBg};border:1px solid ${edgeColor}40">
        <span style="font-size:11px;font-weight:700;color:${edgeColor}">${edge > 0 ? '+' : ''}${edge.toFixed(1)} ${edgeDir}</span>
      </div>
      <span style="font-size:9px;color:var(--text2);text-transform:uppercase;letter-spacing:0.06em">${tierLabel}</span>
    </div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:10px">Confidence-weighted projection from 4 rivalry models vs the book${perBook.length > 1 ? 's' : ''} line.</div>
    ${modelCells ? `<div style="display:flex;justify-content:space-around;padding:8px 6px;border-radius:10px;background:rgba(125,145,190,0.06);border:1px solid rgba(125,145,190,0.15);margin-bottom:10px">${modelCells}</div>` : ''}
    ${bookRows ? `<div style="display:grid;gap:6px">${bookRows}</div>` : ''}
  </div>`;
}

function buildPayoutEVPanel(
  f: AnalyzerFighter,
  lean: EffectiveLean,
  evDetail: EVResult | null,
  perBookEv: PerBookEV[],
): string {
  if (evDetail == null) return '';
  const ev = evDetail.ev;
  const evColor = ev >= 10 ? 'var(--green)' : ev >= 3 ? 'var(--amber)' : ev > 0 ? 'var(--text2)' : 'var(--red)';
  const evBg = ev >= 10 ? 'rgba(72,199,142,0.10)' : ev >= 3 ? 'rgba(240,192,64,0.10)' : ev > 0 ? 'rgba(125,145,190,0.08)' : 'rgba(255,100,100,0.10)';
  const vigLabel = evDetail.vig != null
    ? `<span style="font-size:9px;color:${evDetail.vig > 5 ? 'var(--red)' : evDetail.vig > 3 ? 'var(--amber)' : 'var(--green)'};margin-left:6px">${evDetail.vig}% vig</span>`
    : '';
  const sourceLabel = evDetail.isAssumedVig
    ? '<span style="font-size:8px;padding:1px 5px;border-radius:999px;background:rgba(125,145,190,0.10);border:1px solid rgba(125,145,190,0.25);color:var(--text2);letter-spacing:0.06em;text-transform:uppercase;margin-left:6px">Est</span>'
    : '<span style="font-size:8px;padding:1px 5px;border-radius:999px;background:rgba(72,199,142,0.10);border:1px solid rgba(72,199,142,0.25);color:var(--green);letter-spacing:0.06em;text-transform:uppercase;margin-left:6px">Live</span>';

  const profitLabel = `${evDetail.profit.toFixed(2)}x payout`;

  // Per-book EV breakdown rows (only when there are actual odds)
  const bookRows = perBookEv.map(b => {
    const bColor = b.ev >= 10 ? 'var(--green)' : b.ev >= 3 ? 'var(--amber)' : b.ev > 0 ? 'var(--text2)' : 'var(--red)';
    const bBg = b.ev >= 10 ? 'rgba(72,199,142,0.08)' : b.ev >= 3 ? 'rgba(240,192,64,0.08)' : b.ev > 0 ? 'rgba(125,145,190,0.06)' : 'rgba(255,100,100,0.08)';
    const bBorder = b.ev >= 10 ? 'rgba(72,199,142,0.30)' : b.ev >= 3 ? 'rgba(240,192,64,0.30)' : 'rgba(125,145,190,0.18)';
    const oddsStr = Math.abs(b.odds) >= 100 ? (b.odds > 0 ? `+${b.odds}` : `${b.odds}`) : `${b.odds.toFixed(2)}x`;
    const vigStr = b.vig != null ? `<span style="font-size:9px;color:${b.vig > 5 ? 'var(--red)' : b.vig > 3 ? 'var(--amber)' : 'var(--green)'};margin-left:4px">${b.vig}%</span>` : '';
    const bestTag = b.isBest && perBookEv.length > 1
      ? `<span style="font-size:8px;padding:1px 5px;border-radius:999px;background:rgba(72,199,142,0.12);border:1px solid rgba(72,199,142,0.35);color:var(--green);letter-spacing:0.08em;text-transform:uppercase;margin-left:6px">Best</span>`
      : '';
    return `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 10px;border-radius:8px;border:1px solid ${bBorder};background:${bBg}">
      <div style="display:flex;align-items:center;gap:6px">
        <span style="font-size:10px;font-weight:700;letter-spacing:0.08em;color:var(--text1)">${b.source}</span>
        <span style="font-size:10px;color:var(--text2)">${lean.lean?.toUpperCase()} @ ${oddsStr}</span>
        ${vigStr}${bestTag}
      </div>
      <div style="text-align:right">
        <span style="font-size:12px;font-weight:700;color:${bColor}">${b.ev > 0 ? '+' : ''}${b.ev}%</span>
        <span style="font-size:9px;color:var(--text2);margin-left:4px">EV</span>
      </div>
    </div>`;
  }).join('');

  return `<div class="detail-panel ev-panel">
    <div class="detail-panel-title">Payout EV</div>
    <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
      <div style="padding:3px 10px;border-radius:999px;background:${evBg};border:1px solid ${evColor}40">
        <span style="font-size:14px;font-weight:800;color:${evColor}">${ev > 0 ? '+' : ''}${ev}%</span>
      </div>
      ${sourceLabel}${vigLabel}
      <span style="font-size:9px;color:var(--text2)">${profitLabel}</span>
    </div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:8px">${evDetail.isAssumedVig
      ? 'Estimated EV using assumed -110 standard vig (no book odds available for this prop type). Win prob from confidence score.'
      : `Actual payout-weighted EV using scraped ${lean.lean?.toUpperCase()} odds. Win prob ${((lean.conf || 0)).toFixed(0)}% × ${evDetail.profit.toFixed(3)}x return − ${(100 - (lean.conf || 0)).toFixed(0)}% loss.`
    }</div>
    ${bookRows ? `<div style="display:grid;gap:6px;margin-top:6px">${bookRows}</div>` : ''}
  </div>`;
}

function buildArchetypeLearnerPanel(
  fighterName: string,
  db: FighterDB,
  oppDB: FighterDB | null,
  moneyline: number | null,
): string {
  if (!db?.loaded) return '';
  const profile = learnArchetypeProfile(fighterName, db, oppDB, moneyline);
  const confidenceTone = profile.confidence >= 80 ? 'var(--green)' : profile.confidence >= 68 ? 'var(--amber)' : 'var(--text2)';
  const secondary = profile.secondaryLabel ? ` · Secondary: ${formatCareerArchetypeLabel(profile.secondaryLabel)}` : '';
  const alert = profile.matchupAlert !== 'none'
    ? `<div class="lean-point"><span class="lean-point-icon neg">↓</span><span>${formatMatchupAlertLabel(profile.matchupAlert)} alert: ${profile.reasons[profile.reasons.length - 1] || 'Matchup-specific fragility detected.'}</span></div>`
    : '';
  const reasonRows = profile.reasons
    .slice(0, profile.matchupAlert !== 'none' ? 3 : 2)
    .map((reason, index) => `<div class="lean-point"><span class="lean-point-icon ${index === 0 ? 'pos' : ''}">${index === 0 ? '↑' : '→'}</span><span>${reason}</span></div>`)
    .join('');

  return `<div class="detail-panel arch-panel">
    <div class="detail-panel-title">Archetype Learner</div>
    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px">
      <span class="style-matchup-chip style-chip-default">${formatCareerArchetypeLabel(profile.careerLabel)}</span>
      ${profile.matchupAlert !== 'none' ? `<span class="style-matchup-chip" style="background:rgba(255,100,100,0.12);border-color:rgba(255,100,100,0.35);color:#ff8f8f">${formatMatchupAlertLabel(profile.matchupAlert)}</span>` : ''}
      <span style="font-size:10px;color:${confidenceTone};letter-spacing:0.06em;text-transform:uppercase">Learner ${profile.confidence}%</span>
    </div>
    <div style="font-size:10px;color:var(--text2);margin-bottom:8px">${profile.summary}${secondary}</div>
    <div class="lean-reason">${reasonRows}${alert}</div>
  </div>`;
}

function buildStyleMatchupPanel(db: FighterDB, oppDB: FighterDB | null, ssLine: number | null, tdLine: number | null): string {
  if (!db?.loaded) return '';
  const myStyle = db.style || 'balanced';
  const oppStyle = oppDB?.style || null;

  // Chip styling
  const chipKey = oppStyle ? `${myStyle[0]}${oppStyle[0]}` : '';
  const chipClassMap: Record<string, string> = { ss: 'style-chip-ss', gg: 'style-chip-gg', sg: 'style-chip-sg', gs: 'style-chip-gs', bs: 'style-chip-bs', sb: 'style-chip-sb', bg: 'style-chip-default', gb: 'style-chip-default', bb: 'style-chip-default' };
  const chipClass = chipClassMap[chipKey] || 'style-chip-default';
  const matchupLabel = oppStyle ? `${myStyle.toUpperCase()} vs ${oppStyle.toUpperCase()}` : myStyle.toUpperCase();

  // Style matchup edge reasons
  const edgeHtml = oppStyle && oppDB
    ? styleMatchupEdge(myStyle, oppStyle, db, oppDB).edges.map(e =>
        `<div class="lean-point"><span class="lean-point-icon ${e.icon === 'pos' ? 'pos' : e.icon === 'neg' ? 'neg' : ''}">${e.icon === 'pos' ? '↑' : e.icon === 'neg' ? '↓' : '→'}</span><span>${e.text}</span></div>`
      ).join('')
    : '';

  // Historical SS over rate split by opponent style (uses statsCache for past opponents)
  interface StyleBucket { ssOver: number; ssUnder: number; tdOver: number; tdUnder: number }
  const buckets: Record<string, StyleBucket> = { striker: { ssOver:0, ssUnder:0, tdOver:0, tdUnder:0 }, grappler: { ssOver:0, ssUnder:0, tdOver:0, tdUnder:0 }, balanced: { ssOver:0, ssUnder:0, tdOver:0, tdUnder:0 } };
  for (const h of (db.history || [])) {
    const hOppDb = statsCache[h.opp];
    if (!hOppDb?.loaded) continue;
    const s = hOppDb.style || 'balanced';
    const b = buckets[s];
    if (!b) continue;
    if (ssLine != null && h.sigStr != null) { if (h.sigStr > ssLine) b.ssOver++; else b.ssUnder++; }
    if (tdLine != null && h.td != null) { if (h.td > tdLine) b.tdOver++; else b.tdUnder++; }
  }

  const buildHitRow = (label: string, over: number, under: number, isCurrent: boolean): string => {
    const total = over + under;
    if (total === 0) return '';
    const pct = Math.round(over / total * 100);
    const barClass = pct >= 55 ? 'over-bar' : 'under-bar';
    const color = pct >= 60 ? '#48c78e' : pct <= 40 ? '#ff6464' : 'var(--text2)';
    return `<div class="style-hit-row${isCurrent ? ' style-hit-current' : ''}">
      <span class="style-hit-label">vs ${label}s</span>
      <div class="style-hit-bar-wrap"><div class="style-hit-bar ${barClass}" data-fill-width="${pct}%" style="width:0%"></div></div>
      <span class="style-hit-pct" style="color:${color}">${pct}%</span>
      <span class="style-hit-count">${over}/${total}</span>
    </div>`;
  };

  const hitRows = [
    buildHitRow('striker', buckets.striker.ssOver, buckets.striker.ssUnder, oppStyle === 'striker'),
    buildHitRow('grappler', buckets.grappler.ssOver, buckets.grappler.ssUnder, oppStyle === 'grappler'),
    buildHitRow('balanced', buckets.balanced.ssOver, buckets.balanced.ssUnder, oppStyle === 'balanced'),
  ].filter(Boolean).join('');

  // Only render if there is something meaningful to show
  if (!oppStyle && !edgeHtml && !hitRows) return '';

  return `<div class="detail-panel style-matchup-panel">
    <div class="detail-panel-title">Style Matchup${oppStyle ? `<span class="style-matchup-chip ${chipClass}">${matchupLabel}</span>` : ''}</div>
    ${edgeHtml ? `<div class="lean-reason" style="margin-bottom:8px">${edgeHtml}</div>` : ''}
    ${hitRows ? `<div class="style-hit-section-label">SS OVER RATE BY OPP STYLE${ssLine != null ? ` · line ${ssLine}` : ''}</div>${hitRows}` : ''}
  </div>`;
}

// ── FIGHT TIME SUMMARY PANEL ──────────────────────────────────────────────
function buildFightTimeSummaryPanel(db: FighterDB, oppDB: FighterDB | null, ftLine: number | null): string {
  if (!db?.loaded || !db.history?.length) return '';
  const allHist = db.history;
  const timedFights = allHist.filter(h => Number.isFinite(Number(h.timeSecs)) && Number(h.timeSecs) > 0);
  if (timedFights.length < 2) return '';

  const wins   = allHist.filter(h => h.result === 'win'  && h.method);
  const losses = allHist.filter(h => h.result === 'loss' && h.method);
  const cmatch = (arr: FightResult[], re: RegExp) => arr.filter(h => re.test(h.method || '')).length;

  const wKO = cmatch(wins, /KO|TKO/i), wSUB = cmatch(wins, /SUB/i), wDEC = wins.length - wKO - wSUB;
  const lKO = cmatch(losses, /KO|TKO/i), lSUB = cmatch(losses, /SUB/i), lDEC = losses.length - lKO - lSUB;

  const bar = (n: number, total: number, cls: string, label: string) => {
    if (!total || !n) return '';
    const pct = Math.round(n / total * 100);
    return `<div class="finish-bar-row">
      <span class="finish-bar-label">${label}</span>
      <div class="finish-bar-wrap"><div class="finish-bar ${cls}" data-fill-width="${pct}%" style="width:0%"></div></div>
      <span class="finish-bar-pct">${n}/${total}</span>
    </div>`;
  };

  const myFinishRate  = db.finishRate  ?? 0;
  const oppFinishRate = oppDB?.finishRate ?? 0;
  const combined = oppDB?.loaded ? 1 - (1 - myFinishRate) * (1 - oppFinishRate) : myFinishRate;
  const riskColor = combined > 0.80 ? '#ff6464' : combined > 0.55 ? '#efb84d' : '#48c78e';
  const riskLabel = combined > 0.80 ? 'HIGH' : combined > 0.55 ? 'MODERATE' : 'LOW';
  const ftSignal  = combined > 0.75 ? { icon:'neg', text:'↓ LEAN UNDER FT — high early-finish probability' }
                  : combined < 0.30 ? { icon:'pos', text:'↑ LEAN OVER FT — both fighters tend to go the distance' }
                  : null;

  const avgFT = timedFights.reduce((s, h) => s + Number(h.timeSecs) / 60, 0) / timedFights.length;

  const winsHtml = wins.length ? `<div class="finish-split-section">
    <div class="finish-split-header">Win methods (${wins.length})</div>
    ${bar(wKO, wins.length, 'ko-bar', 'KO/TKO')}${bar(wSUB, wins.length, 'sub-bar', 'SUB')}${bar(wDEC, wins.length, 'dec-bar', 'DEC')}
  </div>` : '';

  const lossHtml = losses.length ? `<div class="finish-split-section">
    <div class="finish-split-header">Loss methods (${losses.length})${lKO > 0 ? ` <span style="color:#ff6060">⚠ ${lKO} KO/TKO</span>` : ''}</div>
    ${bar(lKO, losses.length, 'ko-bar-loss', 'KO/TKO')}${bar(lSUB, losses.length, 'sub-bar', 'SUB')}${bar(lDEC, losses.length, 'dec-bar', 'DEC')}
  </div>` : '';

  const oppLine = oppDB?.loaded ? `<div style="font-size:10px;color:var(--text3);margin-bottom:4px">Opponent finish rate: <strong style="color:${oppFinishRate>0.6?'#ff6464':oppFinishRate>0.35?'#efb84d':'#48c78e'}">${Math.round(oppFinishRate*100)}%</strong></div>` : '';

  return `<div class="detail-panel ftb-panel">
    <div class="detail-panel-title">Fight Time Breakdown</div>
    <div class="finish-split-wrap">${winsHtml}${lossHtml}</div>
    <div style="margin-top:10px">
      ${oppLine}
      <div class="ft-combined-risk" style="background:rgba(${combined>0.8?'255,100,100':combined>0.55?'239,184,84':'72,199,142'},0.07);border-left:2px solid ${riskColor}">
        <div style="font-size:10px;font-weight:700;letter-spacing:0.06em;color:${riskColor}">COMBINED EARLY-FINISH RISK: ${riskLabel} (${Math.round(combined*100)}%)</div>
        <div style="font-size:10px;color:var(--text3);margin-top:2px">Avg fight time: ${avgFT.toFixed(1)}m${ftLine!=null?` · FT line: ${ftLine}m`:''}${oppDB?.loaded?' · both fighters factored':''}</div>
        ${ftSignal?`<div style="font-size:10px;font-weight:600;margin-top:3px;color:${ftSignal.icon==='pos'?'#48c78e':'#ff6464'}">${ftSignal.text}</div>`:''}
      </div>
    </div>
  </div>`;
}

// ── OPPONENT ACTIVITY CONTEXT PANEL ───────────────────────────────────────
// ── SIMILAR-OPPONENT BACKTESTING ──────────────────────────────────────────
// For each fight in a fighter's history, approximate the past opponent's style
// profile and score similarity to the current opponent. Show performance in
// fights against the most similar past opponents.

interface OpponentProfile {
  style: 'striker' | 'grappler' | 'balanced';
  stance: string | null;
  slpm: number;
  sapm: number;
  tdAvgPerFight: number;
  tdDef: number;
  strDef: number;
  finishRate: number;
  archetype: LearnedCareerArchetype | null;
}

interface SimilarFightMatch {
  oppName: string;
  similarity: number; // 0-1
  matchReasons: string[];
  fightResult: FightResult;
  betrFP: number | null;
}

function buildOpponentProfile(oppDB: FighterDB): OpponentProfile {
  const profile = learnArchetypeProfile('', oppDB, null, null);
  return {
    style: oppDB.style,
    stance: oppDB.stance || null,
    slpm: oppDB.slpm ?? 3.5,
    sapm: oppDB.sapm ?? 3.5,
    tdAvgPerFight: oppDB.avgTDperFight ?? oppDB.avgTD ?? 0.8,
    tdDef: oppDB.tdDef ?? 55,
    strDef: oppDB.strDef ?? 55,
    finishRate: oppDB.finishRate ?? 0.45,
    archetype: profile.careerLabel,
  };
}

/** Infer a rough opponent profile from in-fight stats when no DB is available */
function inferOpponentProfileFromFight(fight: FightResult): OpponentProfile | null {
  const opp = fight.oppStats;
  if (!opp) return null;

  const oppSS = opp.sigStr ?? 0;
  const oppTD = opp.td ?? 0;
  const oppCtrl = opp.ctrlSecs ?? 0;

  // Rough style inference from what the opponent did IN the fight
  let style: 'striker' | 'grappler' | 'balanced' = 'balanced';
  if (oppTD >= 2 || oppCtrl >= 120) style = 'grappler';
  else if (oppSS >= 25 && oppTD <= 1) style = 'striker';

  // Rough archetype from in-fight behavior
  let archetype: LearnedCareerArchetype | null = null;
  if (oppSS >= 40 && oppTD <= 1) archetype = 'volume_accumulator';
  else if (oppTD >= 3) archetype = 'control_merchant';
  else if (oppSS >= 20 && oppSS <= 35 && oppTD <= 1) archetype = 'point_bank_striker';
  else if (oppTD >= 2 && oppSS >= 15) archetype = 'durable_generalist';

  return {
    style,
    stance: null, // can't infer stance from stats
    slpm: oppSS / Math.max(1, (fight.timeSecs ?? 900) / 300), // rough SLpM
    sapm: (fight.sigStr ?? 0) / Math.max(1, (fight.timeSecs ?? 900) / 300),
    tdAvgPerFight: oppTD,
    tdDef: 55, // unknown, use average
    strDef: 55,
    finishRate: 0.45,
    archetype,
  };
}

function scoreOpponentSimilarity(
  currentOpp: OpponentProfile,
  pastOpp: OpponentProfile,
): { score: number; reasons: string[] } {
  let score = 0;
  const reasons: string[] = [];

  // Style match (weight: 25%)
  if (currentOpp.style === pastOpp.style) {
    score += 0.25;
    reasons.push(`Same style (${currentOpp.style})`);
  } else {
    // Partial: balanced is closer to either than striker↔grappler
    if (currentOpp.style === 'balanced' || pastOpp.style === 'balanced') {
      score += 0.10;
    }
  }

  // Archetype match (weight: 20%)
  if (currentOpp.archetype && pastOpp.archetype) {
    if (currentOpp.archetype === pastOpp.archetype) {
      score += 0.20;
      reasons.push(`Same archetype`);
    } else {
      // Group similar archetypes
      const strikerTypes: LearnedCareerArchetype[] = ['volume_accumulator', 'point_bank_striker', 'chaos_brawler'];
      const grapplerTypes: LearnedCareerArchetype[] = ['control_merchant', 'submission_chaser'];
      if (
        (strikerTypes.includes(currentOpp.archetype) && strikerTypes.includes(pastOpp.archetype)) ||
        (grapplerTypes.includes(currentOpp.archetype) && grapplerTypes.includes(pastOpp.archetype))
      ) {
        score += 0.10;
        reasons.push(`Similar archetype group`);
      }
    }
  }

  // Stance match (weight: 10%)
  if (currentOpp.stance && pastOpp.stance) {
    if (currentOpp.stance.toLowerCase() === pastOpp.stance.toLowerCase()) {
      score += 0.10;
      if (currentOpp.stance.toLowerCase() === 'southpaw') reasons.push(`Both southpaw`);
    }
  }

  // SLPM similarity (weight: 12%) — striking pace
  const slpmDiff = Math.abs(currentOpp.slpm - pastOpp.slpm);
  const slpmScore = Math.max(0, 1 - slpmDiff / 3); // 0 diff = full, 3+ diff = 0
  score += slpmScore * 0.12;
  if (slpmScore >= 0.7) reasons.push(`Similar striking pace`);

  // TD rate similarity (weight: 12%)
  const tdDiff = Math.abs(currentOpp.tdAvgPerFight - pastOpp.tdAvgPerFight);
  const tdScore = Math.max(0, 1 - tdDiff / 3);
  score += tdScore * 0.12;
  if (tdScore >= 0.7 && (currentOpp.tdAvgPerFight >= 1.5 || pastOpp.tdAvgPerFight >= 1.5)) {
    reasons.push(`Similar TD pressure`);
  }

  // TD defense similarity (weight: 8%)
  const tdDefDiff = Math.abs(currentOpp.tdDef - pastOpp.tdDef);
  const tdDefScore = Math.max(0, 1 - tdDefDiff / 30);
  score += tdDefScore * 0.08;

  // Striking defense similarity (weight: 8%)
  const strDefDiff = Math.abs(currentOpp.strDef - pastOpp.strDef);
  const strDefScore = Math.max(0, 1 - strDefDiff / 30);
  score += strDefScore * 0.08;

  // Finish rate similarity (weight: 5%)
  const frDiff = Math.abs(currentOpp.finishRate - pastOpp.finishRate);
  const frScore = Math.max(0, 1 - frDiff / 0.4);
  score += frScore * 0.05;

  return { score: Math.min(1, score), reasons };
}

function findSimilarOpponentFights(
  db: FighterDB,
  currentOppDB: FighterDB,
  minSimilarity: number = 0.35,
  maxResults: number = 5,
): SimilarFightMatch[] {
  const currentOppProfile = buildOpponentProfile(currentOppDB);
  const history = db.history || [];
  const matches: SimilarFightMatch[] = [];

  for (const fight of history) {
    if (fight.sigStr == null && fight.totStr == null) continue; // no stat data

    // Try to find this past opponent in allFighters (loaded data)
    const pastOppNorm = (normalizeName(fight.opp) || fight.opp).toLowerCase();
    const pastOppEntry = _fighterByNorm?.get(pastOppNorm) ?? null;
    let pastOppProfile: OpponentProfile | null = null;

    if (pastOppEntry?.db?.loaded) {
      pastOppProfile = buildOpponentProfile(pastOppEntry.db);
    } else {
      // Infer from in-fight stats
      pastOppProfile = inferOpponentProfileFromFight(fight);
    }

    if (!pastOppProfile) continue;

    const { score, reasons } = scoreOpponentSimilarity(currentOppProfile, pastOppProfile);
    if (score < minSimilarity) continue;

    // Calculate Betr FP for this fight
    const won = fight.result === 'win';
    const betrFP = calcFPForPlatform('betr', fight.sigStr, fight.totStr, fight.ctrlSecs, fight.timeSecs, fight.kd, fight.td, fight.rev, fight.sub, won, fight.method, fight.round);

    matches.push({
      oppName: fight.opp,
      similarity: score,
      matchReasons: reasons,
      fightResult: fight,
      betrFP,
    });
  }

  // Sort by similarity descending
  matches.sort((a, b) => b.similarity - a.similarity);
  return matches.slice(0, maxResults);
}

function buildSimilarOpponentPanel(
  fighterName: string,
  db: FighterDB,
  oppDB: FighterDB | null,
  fpLine: number | null,
  ssLine: number | null,
  tdLine: number | null,
  ctrlLine: number | null,
  ssR1Line: number | null = null,
): string {
  if (!db?.loaded || !oppDB?.loaded || !db.history?.length) return '';

  const matches = findSimilarOpponentFights(db, oppDB, 0.35, 5);
  if (matches.length < 1) return '';

  const currentOppProfile = buildOpponentProfile(oppDB);
  const archLabel = currentOppProfile.archetype
    ? formatCareerArchetypeLabel(currentOppProfile.archetype)
    : currentOppProfile.style;

  // Compute average performance vs similar opponents
  const withFP = matches.filter(m => m.betrFP != null);
  const withSS = matches.filter(m => m.fightResult.sigStr != null);
  const withR1SS = matches.filter(m => m.fightResult.sigStrR1 != null);
  const withTD = matches.filter(m => m.fightResult.td != null);
  const avgFP = withFP.length > 0 ? withFP.reduce((s, m) => s + m.betrFP!, 0) / withFP.length : null;
  const avgSS = withSS.length > 0 ? withSS.reduce((s, m) => s + (m.fightResult.sigStr || 0), 0) / withSS.length : null;
  const avgR1SS = withR1SS.length > 0 ? withR1SS.reduce((s, m) => s + (m.fightResult.sigStrR1 || 0), 0) / withR1SS.length : null;
  const avgTD = withTD.length > 0 ? withTD.reduce((s, m) => s + (m.fightResult.td || 0), 0) / withTD.length : null;
  const winRate = matches.length > 0 ? matches.filter(m => m.fightResult.result === 'win').length / matches.length : null;

  // Career averages for comparison
  const careerFP = db.avgFP_betr ?? db.avgFP ?? null;
  const careerSS = db.avgSigStr ?? null;
  const r1History = (db.history || []).filter(h => h.sigStrR1 != null);
  const careerR1SS = r1History.length > 0 ? r1History.reduce((s, h) => s + (h.sigStrR1 || 0), 0) / r1History.length : null;
  const careerTD = db.avgTDperFight ?? null;

  // Delta arrows
  const deltaIcon = (similar: number | null, career: number | null): string => {
    if (similar == null || career == null) return '';
    const diff = similar - career;
    const pct = career > 0 ? (diff / career * 100) : 0;
    if (Math.abs(pct) < 5) return '<span style="color:var(--text4)"> ≈</span>';
    return diff > 0
      ? `<span style="color:#1bdc88"> ↑${Math.abs(pct).toFixed(0)}%</span>`
      : `<span style="color:#ff6c88"> ↓${Math.abs(pct).toFixed(0)}%</span>`;
  };

  // Over-rate vs lines
  let fpOverHtml = '';
  if (fpLine != null && withFP.length >= 2) {
    const overCount = withFP.filter(m => m.betrFP! > fpLine).length;
    const pct = Math.round(overCount / withFP.length * 100);
    const color = pct >= 60 ? '#1bdc88' : pct <= 40 ? '#ff6c88' : 'var(--text2)';
    fpOverHtml = `<div style="font-size:9.5px;color:${color};margin-top:2px">vs similar: ${overCount}/${withFP.length} (${pct}%) went OVER ${fpLine} FP</div>`;
  }
  let ssOverHtml = '';
  if (ssLine != null && withSS.length >= 2) {
    const overCount = withSS.filter(m => (m.fightResult.sigStr || 0) > ssLine).length;
    const pct = Math.round(overCount / withSS.length * 100);
    const color = pct >= 60 ? '#1bdc88' : pct <= 40 ? '#ff6c88' : 'var(--text2)';
    ssOverHtml = `<div style="font-size:9.5px;color:${color};margin-top:2px">vs similar: ${overCount}/${withSS.length} (${pct}%) went OVER ${ssLine} SS</div>`;
  }
  let ssR1OverHtml = '';
  if (ssR1Line != null && withR1SS.length >= 2) {
    const overCount = withR1SS.filter(m => (m.fightResult.sigStrR1 || 0) > ssR1Line).length;
    const pct = Math.round(overCount / withR1SS.length * 100);
    const color = pct >= 60 ? '#1bdc88' : pct <= 40 ? '#ff6c88' : 'var(--text2)';
    ssR1OverHtml = `<div style="font-size:9.5px;color:${color};margin-top:2px">vs similar: ${overCount}/${withR1SS.length} (${pct}%) went OVER ${ssR1Line} R1 SS</div>`;
  }
  let tdOverHtml = '';
  if (tdLine != null && withTD.length >= 2) {
    const overCount = withTD.filter(m => (m.fightResult.td || 0) > tdLine).length;
    const pct = Math.round(overCount / withTD.length * 100);
    const color = pct >= 60 ? '#1bdc88' : pct <= 40 ? '#ff6c88' : 'var(--text2)';
    tdOverHtml = `<div style="font-size:9.5px;color:${color};margin-top:2px">vs similar: ${overCount}/${withTD.length} (${pct}%) went OVER ${tdLine} TD</div>`;
  }
  let ctrlOverHtml = '';
  // ctrlLine is in minutes (decimal, e.g. 5.5 = 5:30); fightResult.ctrlSecs is in seconds.
  const withCtrl = matches.filter(m => m.fightResult.ctrlSecs != null);
  if (ctrlLine != null && withCtrl.length >= 2) {
    const lineSecs = ctrlLine * 60;
    const overCount = withCtrl.filter(m => (m.fightResult.ctrlSecs || 0) > lineSecs).length;
    const pct = Math.round(overCount / withCtrl.length * 100);
    const color = pct >= 60 ? '#1bdc88' : pct <= 40 ? '#ff6c88' : 'var(--text2)';
    const mm = Math.floor(lineSecs / 60);
    const ss = Math.round(lineSecs % 60);
    const ctrlLabel = `${mm}:${String(ss).padStart(2, '0')}`;
    ctrlOverHtml = `<div style="font-size:9.5px;color:${color};margin-top:2px">vs similar: ${overCount}/${withCtrl.length} (${pct}%) went OVER ${ctrlLabel} Ctrl</div>`;
  }

  // Build fight rows
  const fightRows = matches.map(m => {
    const sim = Math.round(m.similarity * 100);
    const simColor = sim >= 70 ? '#1bdc88' : sim >= 50 ? 'var(--gold)' : 'var(--text3)';
    const resultBadge = m.fightResult.result === 'win'
      ? '<span style="color:#1bdc88;font-weight:700">W</span>'
      : '<span style="color:#ff6c88;font-weight:700">L</span>';
    const method = m.fightResult.method || '—';
    const round = m.fightResult.round ? `R${m.fightResult.round}` : '';
    const fp = m.betrFP != null ? m.betrFP.toFixed(1) : '—';
    const ss = m.fightResult.sigStr != null ? String(m.fightResult.sigStr) : '—';
    const ssR1 = m.fightResult.sigStrR1 != null ? String(m.fightResult.sigStrR1) : '';
    const td = m.fightResult.td != null ? String(m.fightResult.td) : '—';
    const kd = m.fightResult.kd != null && m.fightResult.kd > 0 ? String(m.fightResult.kd) : '';
    const ctrl = m.fightResult.ctrlSecs != null && m.fightResult.ctrlSecs > 0
      ? `${Math.floor(m.fightResult.ctrlSecs / 60)}:${String(m.fightResult.ctrlSecs % 60).padStart(2, '0')}`
      : '';
    const reasonTags = m.matchReasons.slice(0, 3).map(r =>
      `<span class="sim-opp-reason-tag">${r}</span>`
    ).join('');

    // FP line comparison badge
    let fpBadge = '';
    if (fpLine != null && m.betrFP != null) {
      fpBadge = m.betrFP > fpLine
        ? `<span style="color:#1bdc88;font-size:8px;margin-left:3px">▲</span>`
        : `<span style="color:#ff6c88;font-size:8px;margin-left:3px">▼</span>`;
    }

    return `<div class="sim-opp-fight-row">
      <div class="sim-opp-fight-header">
        <span class="sim-opp-score" style="color:${simColor}">${sim}%</span>
        <span class="sim-opp-name">${resultBadge} vs ${m.oppName}</span>
        <span class="sim-opp-method">${method} ${round}</span>
      </div>
      <div class="sim-opp-stats">
        <span class="sim-opp-stat">FP: <b>${fp}</b>${fpBadge}</span>
        <span class="sim-opp-stat">SS: <b>${ss}</b></span>
        ${ssR1 ? `<span class="sim-opp-stat">R1: <b>${ssR1}</b></span>` : ''}
        <span class="sim-opp-stat">TD: <b>${td}</b></span>
        ${kd ? `<span class="sim-opp-stat">KD: <b>${kd}</b></span>` : ''}
        ${ctrl ? `<span class="sim-opp-stat">Ctrl: <b>${ctrl}</b></span>` : ''}
      </div>
      <div class="sim-opp-reasons">${reasonTags}</div>
    </div>`;
  }).join('');

  // Summary averages row
  const avgRow = `<div class="sim-opp-averages">
    <div class="sim-opp-avg-title">AVG vs SIMILAR (${matches.length} fights)${winRate != null ? ` · Win rate: ${Math.round(winRate * 100)}%` : ''}</div>
    <div class="sim-opp-avg-stats">
      ${avgFP != null ? `<span class="sim-opp-stat">FP: <b>${avgFP.toFixed(1)}</b>${deltaIcon(avgFP, careerFP)}</span>` : ''}
      ${avgSS != null ? `<span class="sim-opp-stat">SS: <b>${avgSS.toFixed(1)}</b>${deltaIcon(avgSS, careerSS)}</span>` : ''}
      ${avgR1SS != null ? `<span class="sim-opp-stat">R1 SS: <b>${avgR1SS.toFixed(1)}</b>${deltaIcon(avgR1SS, careerR1SS)}</span>` : ''}
      ${avgTD != null ? `<span class="sim-opp-stat">TD: <b>${avgTD.toFixed(1)}</b>${deltaIcon(avgTD, careerTD)}</span>` : ''}
    </div>
  </div>`;

  return `<div class="detail-panel soh-panel">
    <div class="detail-panel-title">Similar Opponent History</div>
    <div style="font-size:9.5px;color:var(--text3);margin-bottom:6px">
      Current opponent profile: <span style="color:var(--text2)">${archLabel} · ${currentOppProfile.style} · ${currentOppProfile.slpm.toFixed(1)} SLpM · ${currentOppProfile.tdAvgPerFight.toFixed(1)} TD/fight · ${currentOppProfile.tdDef}% TD def</span>
    </div>
    ${avgRow}
    ${fpOverHtml}${ssOverHtml}${ssR1OverHtml}${tdOverHtml}${ctrlOverHtml}
    <div class="sim-opp-fights">${fightRows}</div>
  </div>`;
}

function buildOpponentQualityPanel(db: FighterDB, fpLine: number | null, ssLine: number | null): string {
  if (!db?.loaded || !db.history?.length) return '';
  const withOppData = db.history.filter(h => h.oppStats?.sigStr != null);
  if (withOppData.length < 3) return '';

  const ACTIVE_THRESH  = 25; // opponent landed >25 SS = active/dangerous fight
  const PASSIVE_THRESH = 12; // opponent landed <12 SS = passive/easy match

  const active  = withOppData.filter(h => (h.oppStats!.sigStr || 0) >  ACTIVE_THRESH);
  const passive = withOppData.filter(h => (h.oppStats!.sigStr || 0) <  PASSIVE_THRESH);
  if (active.length < 2 && passive.length < 2) return '';

  const fpOverRate = (arr: FightResult[]) => {
    if (!fpLine || !arr.length) return null;
    const v = arr.filter(h => h.fp != null);
    if (!v.length) return null;
    const over = v.filter(h => (h.fp || 0) > fpLine).length;
    return { over, total: v.length, pct: Math.round(over / v.length * 100) };
  };
  const ssOverRate = (arr: FightResult[]) => {
    if (!ssLine || !arr.length) return null;
    const v = arr.filter(h => h.sigStr != null);
    if (!v.length) return null;
    const over = v.filter(h => (h.sigStr || 0) > ssLine).length;
    return { over, total: v.length, pct: Math.round(over / v.length * 100) };
  };

  const aFP = fpOverRate(active),  pFP = fpOverRate(passive);
  const aSS = ssOverRate(active),  pSS = ssOverRate(passive);

  // Quality flag: big drop in active vs passive signals softer schedule inflation
  let flagHtml = '';
  if (aFP && pFP) {
    const drop = pFP.pct - aFP.pct;
    if (drop >= 25 && pFP.pct >= 60) {
      flagHtml = `<div class="lean-point"><span class="lean-point-icon neg">↓</span><span>FP over rate drops ${drop}% vs active opponents (${aFP.pct}% active vs ${pFP.pct}% passive) — schedule quality concern</span></div>`;
    } else if (aFP.pct >= 65) {
      flagHtml = `<div class="lean-point"><span class="lean-point-icon pos">↑</span><span>Maintains ${aFP.pct}% FP over rate even vs active opponents — quality-adjusted edge</span></div>`;
    }
  }

  const buildRow = (label: string, r: {over:number;total:number;pct:number}|null) => {
    if (!r) return '';
    const color = r.pct >= 60 ? '#48c78e' : r.pct <= 40 ? '#ff6464' : 'var(--text2)';
    return `<div class="style-hit-row">
      <span class="style-hit-label" style="width:80px;font-size:9px">${label}</span>
      <div class="style-hit-bar-wrap"><div class="style-hit-bar ${r.pct>=55?'over-bar':'under-bar'}" data-fill-width="${r.pct}%" style="width:0%"></div></div>
      <span class="style-hit-pct" style="color:${color}">${r.pct}%</span>
      <span class="style-hit-count">${r.over}/${r.total}</span>
    </div>`;
  };

  const activeRows  = active.length  >= 2 ? `<div class="oq-section-label">vs active opp (opp >${ACTIVE_THRESH} SS · ${active.length} fights)</div>${buildRow('FP over', aFP)}${buildRow('SS over', aSS)}` : '';
  const passiveRows = passive.length >= 2 ? `<div class="oq-section-label">vs passive opp (opp <${PASSIVE_THRESH} SS · ${passive.length} fights)</div>${buildRow('FP over', pFP)}${buildRow('SS over', pSS)}` : '';
  if (!activeRows && !passiveRows) return '';

  return `<div class="detail-panel oac-panel">
    <div class="detail-panel-title">Opponent Activity Context</div>
    ${flagHtml ? `<div class="lean-reason" style="margin-bottom:8px">${flagHtml}</div>` : ''}
    <div style="font-size:9px;color:var(--text4);margin-bottom:4px">${withOppData.length} fights with opponent stat data</div>
    ${activeRows}${passiveRows}
  </div>`;
}

// ── LINE MOVEMENT TIMELINE PANEL ──────────────────────────────────────────
function buildLineTimelinePanel(f: AnalyzerFighter): string {
  const stats: Array<{ label: string; stat: string; platLines: Array<[string, number | null | undefined]> }> = [
    { label: 'FP', stat: 'fp', platLines: [['p6', f.line_p6], ['ud', f.line_ud], ['pp', f.line_pp], ['betr', f.line_betr]] },
    { label: 'SS', stat: 'ss', platLines: [['p6', f.line_p6_ss], ['ud', f.line_ud_ss], ['pp', f.line_pp_ss], ['betr', f.line_betr_ss], ['dk', f.line_dk_ss]] },
    { label: 'TD', stat: 'td', platLines: [['p6', f.line_p6_td], ['ud', f.line_ud_td], ['pp', f.line_pp_td], ['betr', f.line_betr_td], ['dk', f.line_dk_td]] },
  ];

  const platColors: Record<string, string> = BOOK_COLORS;
  const platLabels: Record<string, string> = { p6: 'P6', ud: 'UD', pp: 'PP', betr: 'BT', dk: 'DK' };

  let chartsHtml = '';
  let hasAny = false;

  for (const { label, stat, platLines } of stats) {
    const history = getLineHistoryForFighter(f.name, stat);
    if (history.length < 2) continue;
    hasAny = true;

    const openKey = openingLineKey('p6', stat, f.name);
    const openVal = _openingLines.get(openKey);

    const tMin = history[0].t;
    const tMax = history[history.length - 1].t;
    const tRange = tMax - tMin || 1;

    const activePlats = new Set<string>();
    for (const pt of history) {
      for (const plat of Object.keys(pt.v)) activePlats.add(plat);
    }

    // Per-platform sparkline rows
    let rowsHtml = '';
    for (const plat of activePlats) {
      const color = platColors[plat] || '#888';
      const pLabel = platLabels[plat] || plat;
      const vals: Array<{t: number; v: number}> = [];
      for (const pt of history) {
        if (pt.v[plat] != null) vals.push({ t: pt.t, v: pt.v[plat] });
      }
      if (vals.length === 0) continue;

      const currentVal = vals[vals.length - 1].v;
      const firstVal = vals[0].v;
      const delta = currentVal - firstVal;
      const deltaStr = delta === 0 ? '—' : `${delta > 0 ? '+' : ''}${delta.toFixed(1)}`;
      const deltaClass = delta > 0 ? 'lm-row-rise' : delta < 0 ? 'lm-row-drop' : '';

      // Sparkline SVG — per-platform, isolated
      const sparkW = 180;
      const sparkH = 32;
      const sPad = 4;
      const platVals = vals.map(v => v.v);
      const pMin = Math.min(...platVals);
      const pMax = Math.max(...platVals);
      const pRange = pMax - pMin || 1;
      const pPad = pRange * 0.2;

      let sparkPath = '';
      if (vals.length === 1 || pMax === pMin) {
        // Flat line
        const sy = sparkH / 2;
        sparkPath = `<line x1="${sPad}" y1="${sy}" x2="${sparkW - sPad}" y2="${sy}" stroke="${color}" stroke-width="2" opacity="0.6" stroke-dasharray="4,3"/>`;
      } else {
        // Step sparkline
        const pts = vals.map(v => ({
          x: sPad + ((v.t - tMin) / tRange) * (sparkW - sPad * 2),
          y: sPad + (sparkH - sPad * 2) - ((v.v - (pMin - pPad)) / (pRange + pPad * 2)) * (sparkH - sPad * 2)
        }));
        let d = `M${pts[0].x.toFixed(1)},${pts[0].y.toFixed(1)}`;
        for (let i = 1; i < pts.length; i++) {
          d += ` L${pts[i].x.toFixed(1)},${pts[i - 1].y.toFixed(1)} L${pts[i].x.toFixed(1)},${pts[i].y.toFixed(1)}`;
        }
        d += ` L${(sparkW - sPad).toFixed(1)},${pts[pts.length - 1].y.toFixed(1)}`;

        sparkPath = `<path d="${d}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity="0.85"/>`;
        // Start + end dots
        sparkPath += `<circle cx="${pts[0].x.toFixed(1)}" cy="${pts[0].y.toFixed(1)}" r="3" fill="${color}" opacity="0.4"/>`;
        sparkPath += `<circle cx="${pts[pts.length - 1].x.toFixed(1)}" cy="${pts[pts.length - 1].y.toFixed(1)}" r="3.5" fill="${color}" stroke="rgba(10,14,24,0.6)" stroke-width="1"/>`;
      }

      const changeCount = vals.reduce((c, v, i) => i > 0 && v.v !== vals[i - 1].v ? c + 1 : c, 0);

      rowsHtml += `
        <div class="lm-plat-row" style="--plat-color:${color}">
          <span class="lm-plat-label">${pLabel}</span>
          <div class="lm-plat-spark">
            <svg viewBox="0 0 ${sparkW} ${sparkH}" preserveAspectRatio="none">${sparkPath}</svg>
          </div>
          <span class="lm-plat-val">${currentVal}</span>
          <span class="lm-plat-delta ${deltaClass}">${deltaStr}</span>
          <span class="lm-plat-changes">${changeCount}×</span>
        </div>`;
    }

    // Time range footer
    const timeFirst = new Date(tMin).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    const timeLast = new Date(tMax).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    const dateFirst = new Date(tMin).toLocaleDateString([], { month: 'short', day: 'numeric' });

    chartsHtml += `
      <div class="line-timeline-stat">
        <div class="line-timeline-stat-header">
          <span class="line-tl-stat-label">${label}</span>
          ${openVal != null ? `<span class="lm-open-badge">Open: ${openVal}</span>` : ''}
        </div>
        <div class="lm-plat-rows">${rowsHtml}</div>
        <div class="lm-time-footer">${dateFirst} · ${timeFirst} – ${timeLast}</div>
      </div>`;
  }

  if (!hasAny) return '';

  return `<div class="detail-panel line-timeline-panel">
    <div class="detail-panel-title">Line Movement Timeline</div>
    ${chartsHtml}
  </div>`;
}

// ── LINE SHOP MODAL ────────────────────────────────────────────────────────
// GLOW-UP 214 (five-level pass). Session-scoped view state — same contract as
// Parlay Lab's command strip: these change what is DRAWN, never what the lines
// are. Reset on reload by design.
type LsSort = 'spread' | 'conf' | 'card';
type LsStatFilter = 'all' | 'fp' | 'ss' | 'td';
let lsSort: LsSort = 'spread';
let lsStatFilter: LsStatFilter = 'all';
/* GLOW-UP 235 — ON by default. The panel is called line shopping DIFF, and on
 * a typical card a quarter of the fighters have no diff worth shopping. Opening
 * on all 22 meant 22 readable rows could not fit a screen, which is what drove
 * the zooming and then the auto-scaling that made everything squint-sized. The
 * ~17 with a real spread DO fit at full size. The rest are one click away and,
 * by definition, have nothing to shop. */
let lsBigOnly = true;
let lsShowFlat = false;
/* GLOW-UP 237 — the platform-bias strip is reference data: how each book's
 * lines have historically landed against results. Useful to consult, not
 * something you act on row by row — and it was costing a full row of the list
 * every time the panel opened. Collapsed by default, one chip away. */
let lsShowBias = false;
let lsBiasBook: string | null = null;
/** GLOW-UP 216 G4 — the biggest single gain on the current card, so the chip
 *  that carries it can be styled as THE opportunity rather than one of many. */
let _lsTopGain = 0;

/** Can this book actually take this side for this fighter? The line-shop panel's
 *  whole job is naming a book to use, so a "best" line the book won't take is a
 *  trap, not a bargain. Same rules the rest of the app gates picks on. */
function lsPlaceable(f: AnalyzerFighter, stat: string, dir: 'over' | 'under', book: string): boolean {
  if (stat === 'fp') return !shouldSkipFpSideForFighter(f, 'fp' as LeanSource, dir, book as SourcePlatformKey);
  if (dir === 'under') return statUnderBookOffered(f, stat, book);
  return true;
}

function generateLineShopModal(): void {
  if (!allFighters.length) { showToast('No fighters loaded'); return; }

  // Lean-aware formatter: for OVER lean, lowest line = best (easiest to clear);
  // for UNDER lean, highest line = best (most room to go under).
  type LeanDir = 'over' | 'under' | 'none';
  // GLOW-UP 214: fmtCell / spreadChip removed. Both were read-only formatters
  // built around "colour the extremes, print the spread"; renderCell and
  // renderVerdict replace them with a control and a decision, and the
  // best/worst choice now runs off the per-stat analysis rather than being
  // recomputed inline per cell.

  // Filter values that are on a compatible scale (within 3x of median).
  // Prevents a platform using per-round or differently-scoped props from
  // inflating the spread vs. platforms using total-fight stats.
  // Filter values that are on a compatible scale (within 45%–220% of median).
  // Prevents a platform using per-round or differently-scoped props from
  // inflating the spread vs. platforms using total-fight stats.
  const compatibleFilter = (vals: number[]): number[] => {
    if (vals.length < 2) return vals;
    const sorted = [...vals].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    const median = sorted.length % 2 !== 0 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
    return vals.filter(v => median > 0 && v >= median * 0.45 && v <= median * 2.2);
  };

  // ── GLOW-UP 214 L2 — per-stat analysis ───────────────────────────────────
  // The old panel computed a spread (best vs worst) and coloured cells. Spread
  // answers "how much do these books disagree", which is interesting; it does not
  // answer "what do I gain by shopping", which is the decision. Your default is
  // whatever book the rest of the app resolves to, so the number that matters is
  // best-vs-DEFAULT — shopping from a book you were never going to use is worth
  // nothing. Both are kept: spread as context, gain as the call.
  const LS_TAG: Record<string, string> = {
    pick6: 'P6', underdog: 'UD', betr: 'BT', prizepicks: 'PP', draftkings_sportsbook: 'DK',
  };
  const STAT_DEFS: Array<{ key: 'fp' | 'ss' | 'td'; label: string }> = [
    { key: 'fp', label: 'FP' }, { key: 'ss', label: 'SS' }, { key: 'td', label: 'TD' },
  ];
  interface LsCell { bk: string; val: number | null; offFamily: boolean; placeable: boolean; }
  interface LsStatView {
    key: 'fp' | 'ss' | 'td'; label: string; dir: LeanDir; cells: LsCell[];
    spread: number; best: LsCell | null; worst: LsCell | null;
    defBook: string | null; defVal: number | null; gain: number; blocked: boolean;
    /** GLOW-UP 215 V3 — the comparable range, so disagreement can be drawn as a
     *  position on a track instead of read as two numbers and subtracted. */
    lo: number | null; hi: number | null;
  }

  const analyseStat = (f: AnalyzerFighter, key: 'fp' | 'ss' | 'td', dir: LeanDir): LsStatView => {
    const fields = LEAN_STAT_FIELDS[key] || [];
    const raw: LsCell[] = fields.map(([bk, fld]) => {
      const v = (f as unknown as Record<string, unknown>)[fld as string] as number | null;
      const val = v != null && Number.isFinite(Number(v)) ? Number(v) : null;
      return {
        bk, val,
        // FP only compares within a scoring family — PrizePicks is a different
        // prop, not a worse price (GLOW-UP 212).
        offFamily: key === 'fp' && FP_SCORING_FAMILY[bk] !== 'standard',
        placeable: val != null && dir !== 'none' ? lsPlaceable(f, key, dir, bk) : true,
      };
    });
    // Fixed display order across every stat so the columns line up vertically —
    // LEAN_STAT_FIELDS is keyed by book-priority, which differs per stat.
    const ORDER = ['pick6', 'underdog', 'betr', 'prizepicks', 'draftkings_sportsbook'];
    raw.sort((a, b) => ORDER.indexOf(a.bk) - ORDER.indexOf(b.bk));
    const present = raw.filter(c => c.val != null && !c.offFamily) as Array<LsCell & { val: number }>;
    // Scale guard stays: a book quoting a different scope would fake a spread.
    const okVals = compatibleFilter(present.map(c => c.val));
    const comparable = present.filter(c => okVals.includes(c.val));
    const spread = comparable.length >= 2
      ? parseFloat((Math.max(...comparable.map(c => c.val)) - Math.min(...comparable.map(c => c.val))).toFixed(1))
      : 0;
    const pickBest = (pool: Array<LsCell & { val: number }>): LsCell | null => {
      if (!pool.length) return null;
      return dir === 'under'
        ? pool.reduce((a, b) => (b.val > a.val ? b : a))
        : pool.reduce((a, b) => (b.val < a.val ? b : a)); // over AND no-lean: lowest
    };
    const bestAny = pickBest(comparable);
    const placeablePool = comparable.filter(c => c.placeable);
    const best = pickBest(placeablePool) || bestAny;
    const worst = comparable.length >= 2
      ? (dir === 'under'
          ? comparable.reduce((a, b) => (b.val < a.val ? b : a))
          : comparable.reduce((a, b) => (b.val > a.val ? b : a)))
      : null;
    const defBook = getSourceActivePlatformKey(f, key) ?? null;
    const defCell = defBook ? comparable.find(c => c.bk === defBook) : undefined;
    const defVal = defCell?.val ?? null;
    const gain = (best?.val != null && defVal != null)
      ? parseFloat((dir === 'under' ? best.val - defVal : defVal - best.val).toFixed(1))
      : 0;
    return {
      key, label: key.toUpperCase(), dir, cells: raw, spread, best, worst, defBook, defVal,
      gain: gain > 0 ? gain : 0,
      // Blocked means there is NOWHERE to take this side — not merely that the
      // sharpest line happens to be unplaceable. When a placeable alternative
      // exists the verdict still names it, and the unplaceable cell renders
      // dashed on its own, which explains why the better-looking number lost.
      blocked: dir !== 'none' && comparable.length > 0 && placeablePool.length === 0,
      lo: comparable.length ? Math.min(...comparable.map(c => c.val)) : null,
      hi: comparable.length ? Math.max(...comparable.map(c => c.val)) : null,
    };
  };

  const rows = allFighters.map(f => {
    const leanDir = (f.lean?.lean === 'over' || f.lean?.lean === 'under') ? f.lean.lean as LeanDir : 'none' as LeanDir;
    const dirFor = (l: LeanResult | null | undefined): LeanDir =>
      (l?.lean === 'over' || l?.lean === 'under') ? l.lean as LeanDir : leanDir;
    const stats: Record<string, LsStatView> = {
      fp: analyseStat(f, 'fp', leanDir),
      ss: analyseStat(f, 'ss', dirFor(f.lean_ss)),
      td: analyseStat(f, 'td', dirFor(f.lean_td)),
    };
    const max_sp = Math.max(stats['fp'].spread, stats['ss'].spread, stats['td'].spread);
    const max_gain = Math.max(stats['fp'].gain, stats['ss'].gain, stats['td'].gain);
    return { f, stats, max_sp, max_gain, leanDir, conf: f.lean?.conf || 0 };
  });
  type LsRow = typeof rows[number];

  // L1 — the view. Sorting was hard-coded to spread while the sub-header claimed
  // it as fact; now it is a control and the header reports what it actually did.
  const statsOf = (r: LsRow): LsStatView[] =>
    (lsStatFilter === 'all' ? STAT_DEFS.map(d => r.stats[d.key]) : [r.stats[lsStatFilter]]);
  const rowSpread = (r: LsRow): number => Math.max(0, ...statsOf(r).map(s => s.spread));
  const rowGain = (r: LsRow): number => Math.max(0, ...statsOf(r).map(s => s.gain));
  let viewRows = rows.filter(r => statsOf(r).some(s => s.cells.some(c => c.val != null)));
  if (lsBigOnly) viewRows = viewRows.filter(r => rowSpread(r) >= 2.5);
  // L5 — a bias chip becomes a filter: show only rows where that book wins.
  if (lsBiasBook) viewRows = viewRows.filter(r => statsOf(r).some(s => s.best?.bk === lsBiasBook));
  const sorted = [...viewRows];
  if (lsSort === 'spread') sorted.sort((a, b) => rowSpread(b) - rowSpread(a) || rowGain(b) - rowGain(a));
  else if (lsSort === 'conf') sorted.sort((a, b) => b.conf - a.conf);
  // 'card' keeps allFighters order untouched.
  // L4 — rows where nothing is shoppable are noise on a decision panel. Folded,
  // not dropped: a zero spread is still information when you go looking for it.
  _lsTopGain = Math.max(0, ...rows.map(r => r.max_gain));
  const liveRows = sorted.filter(r => rowSpread(r) > 0);
  const flatRows = sorted.filter(r => rowSpread(r) === 0);

  // L3 — cells are controls, not readouts. The panel's entire purpose is naming a
  // book to use, so clicking that book queues exactly it into My Slate via the
  // bookOverride path (GLOW-UP 211). Seeing the edge and taking it were two
  // different screens before this.
  const renderCell = (f: AnalyzerFighter, sv: LsStatView, c: LsCell): string => {
    // GLOW-UP 216 G3 — a book with no line for this prop renders NOTHING. The
    // dashes were placeholders for books that mostly never post that stat on a
    // given card, so half the FP column was punctuation. Each chip carries its
    // own book tag, so nothing is lost by collapsing the gaps.
    if (c.val == null) return '';
    const tag = LS_TAG[c.bk] || c.bk.toUpperCase();
    if (c.offFamily) {
      return `<span class="ls-cell-val ls-scale-mismatch" title="PrizePicks scores fantasy points differently — a separate prop, not a worse price, so it is excluded from the spread."><span class="ls-plat-tag">${tag}</span>~${c.val}</span>`;
    }
    const isBest = sv.best?.bk === c.bk && sv.spread > 0;
    const isWorst = sv.worst?.bk === c.bk && sv.spread > 0;
    const blocked = sv.dir !== 'none' && !c.placeable;
    // V4 — book identity. This is a multi-book comparison surface, the one place
    // the colour system licenses hue-by-book, so the app's existing platform
    // lanes are reused rather than invented (P6 blue, UD indigo, BT orange,
    // PP teal, DK gold — same values as the Parlay Lab leg chips).
    const cls = `plat-${c.bk} ${isBest ? 'ls-best' : isWorst ? 'ls-worst' : 'ls-neutral'}${blocked ? ' ls-blocked' : ''}${isBest && !blocked ? ' ls-take' : ''}`;
    if (sv.dir === 'none') {
      return `<span class="ls-cell-val ${cls}" title="${tag} ${sv.label} ${c.val} — no lean on this prop, so no side to take."><span class="ls-plat-tag">${tag}</span>${c.val}</span>`;
    }
    const built = buildSlatePickFor(f, sv.key, sv.dir as 'over' | 'under', c.val, c.bk);
    _leanSlateData.set(built.key, built.pick);
    const inSlate = bestPicksSlate.has(built.key);
    const tip = blocked
      ? `${tag} does not offer the ${sv.dir.toUpperCase()} side of this ${sv.label} prop for ${prettyName(f.name)} — queue it anyway if you have it somewhere.`
      : `${inSlate ? 'Remove from' : 'Add to'} My Slate: ${prettyName(f.name)} ${sv.dir.toUpperCase()} ${c.val} ${sv.label} @ ${LEAN_BOOK_LABEL[c.bk] || tag}`;
    return `<button class="ls-cell-val ${cls}${inSlate ? ' ls-on' : ''}" data-ls-take="${built.key.replace(/"/g, '&quot;')}" title="${tip.replace(/"/g, '&quot;')}"><span class="ls-plat-tag">${tag}</span>${c.val}${inSlate ? '<i class="ls-check">✓</i>' : ''}</button>`;
  };

  // V3 — magnitude as position. Two numbers and a subtraction is arithmetic the
  // reader shouldn't have to do: every comparable book becomes a dot on the
  // prop's own min→max axis, so the shape of the disagreement is seen at a
  // glance and the good end is always the lit end.
  const renderTrack = (sv: LsStatView): string => {
    if (sv.lo == null || sv.hi == null || sv.spread === 0) return '';
    const span = sv.hi - sv.lo;
    const dots = sv.cells
      .filter(c => c.val != null && !c.offFamily && c.val >= sv.lo! && c.val <= sv.hi!)
      .map(c => {
        const pct = span > 0 ? ((c.val! - sv.lo!) / span) * 100 : 50;
        const isBest = sv.best?.bk === c.bk;
        return `<b class="ls-dot plat-${c.bk}${isBest ? ' is-best' : ''}" style="left:${pct.toFixed(1)}%" title="${LS_TAG[c.bk] || c.bk} ${c.val}"></b>`;
      }).join('');
    // The lit end is the side the lean wants — lowest for an OVER, highest for
    // an UNDER — so "good" is always a direction, never a colour to decode.
    const goodEnd = sv.dir === 'under' ? 'hi' : 'lo';
    // No end labels: every value is already printed on the cells above, so
    // repeating the range only collided with the dots and cost a line of height.
    return `<div class="ls-track good-${goodEnd}" title="Every book on this prop placed across its ${sv.lo}–${sv.hi} range. The lit end is the side your lean wants.">
      <i class="ls-track-rail"></i>${dots}
    </div>`;
  };

  // V2 — the take, compressed to a single inline chip that sits on the SAME line
  // as the cells. The first cut gave it its own full-width card, which read well
  // in isolation and turned every row into three stacked bands — 14 rows ran off
  // the page and the panel had to be zoomed out to use, which is worse than the
  // wall it replaced. The gain stays the hero; everything else moves to the
  // tooltip, where it costs no height.
  const renderTake = (sv: LsStatView): string => {
    if (!sv.cells.some(c => c.val != null)) return '';
    const bestTag = sv.best ? (LS_TAG[sv.best.bk] || sv.best.bk) : '—';
    const defTag = sv.defBook ? (LS_TAG[sv.defBook] || sv.defBook) : null;
    // GLOW-UP 217 U1 — one book posting a prop is not "the books agree", it is
    // nothing to compare. Printing `=` there put a chip at the far right of an
    // otherwise empty band and made the column look broken rather than quiet.
    const posted = sv.cells.filter(c => c.val != null && !c.offFamily).length;
    if (posted < 2) return '';
    if (sv.spread === 0) {
      return `<span class="ls-take-mini is-flat" title="All ${posted} books posting this prop have the same number — nothing to shop.">=</span>`;
    }
    if (sv.dir === 'none') {
      return `<span class="ls-take-mini is-nolean" title="No model lean on this prop, so there is no side to take — but the books disagree by ${sv.spread}, which is worth knowing if you have your own read.">Δ${sv.spread}</span>`;
    }
    if (sv.blocked) {
      return `<span class="ls-take-mini is-blocked" title="Every book that posts this prop refuses the ${sv.dir.toUpperCase()} side for this fighter — the best line on the board is not one you can act on.">⛔</span>`;
    }
    if (sv.gain > 0) {
      // G4 — the single biggest edge on the card is the one thing worth drawing
      // the eye first, so it gets its own treatment rather than being one green
      // chip among fifteen identical green chips.
      const isTop = _lsTopGain > 0 && sv.gain === _lsTopGain;
      return `<span class="ls-take-mini is-take${isTop ? ' is-jewel' : ''}" title="Take ${sv.dir.toUpperCase()} on ${LEAN_BOOK_LABEL[sv.best!.bk] || bestTag} at ${sv.best?.val}${defTag ? ` instead of ${defTag} ${sv.defVal}` : ''} — worth ${sv.gain} points. Spread across all books is ${sv.spread}.${isTop ? ' This is the biggest single edge on the card.' : ''}"><b>+${sv.gain}</b> ${bestTag} ${sv.best?.val}</span>`;
    }
    return `<span class="ls-take-mini is-none" title="Your default book (${defTag} ${sv.defVal}) already holds the best side — the ${sv.spread} spread is real, but shopping gains you nothing.">✓ best</span>`;
  };

  // V1/V5 — the row gets a hierarchy and a spine. The fighter is the heading,
  // the gain is the badge that earns attention, and a left accent rail keyed to
  // value gives the table a rhythm so 14 rows stop reading as one grey block.
  const renderRow = (r: LsRow, rank: number): string => {
    const { f } = r;
    const leanChip = r.leanDir !== 'none'
      ? `<span class="ls-lean-chip ls-lean-${r.leanDir}">${r.leanDir === 'over' ? '▲' : '▼'} ${r.leanDir.toUpperCase()}${r.conf > 0 ? ` ${r.conf}%` : ''}</span>`
      : '';
    // Two bands per stat, not three: cells + take on one line, the track as a
    // sliver beneath. Keeps the whole panel on one screen at 100% zoom.
    const cols = statsOf(r).map(sv => `<td class="ls-stat-td">
        <div class="ls-cellrow">${sv.cells.map(c => renderCell(f, sv, c)).join('')}${(() => {
          const take = renderTake(sv);
          // U1 — a dotted leader carries the eye from the last cell to the take
          // chip. Right-aligning the chips gives the table a clean vertical
          // "take" column; the leader stops the gap it opens from reading as a
          // hole in the row.
          return take ? `<i class="ls-lead"></i>${take}` : '';
        })()}</div>
        ${renderTrack(sv)}
      </td>`).join('');
    const topGain = rowGain(r);
    const heat = topGain >= 8 ? 'heat-3' : topGain >= 4 ? 'heat-2' : topGain > 0 ? 'heat-1' : 'heat-0';
    return `<tr class="ls-row ${heat}">
      <td class="lineshop-fighter-name">
        <div class="ls-name-line">
          ${rank <= 3 && topGain > 0 ? `<span class="ls-rank" title="One of the three biggest shopping gains on the card right now.">${rank}</span>` : ''}
          <span class="ls-name">${prettyName(f.name)}</span>
          ${topGain > 0 ? `<span class="ls-row-gain" title="Best single-prop gain available on this fighter by shopping away from your default book.">+${topGain}</span>` : ''}
        </div>
        <div class="ls-meta-line">${leanChip}${f.opponent ? `<span class="ls-vs">vs ${prettyName(f.opponent).split(' ').slice(-1)[0]}</span>` : ''}</div>
      </td>${cols}
    </tr>`;
  };

  const rowsHtml = liveRows.map((r, i) => renderRow(r, i + 1)).join('');
  const flatHtml = lsShowFlat ? flatRows.map(r => renderRow(r, 999)).join('') : '';

  const content = document.getElementById('lineShopContent');
  const modal = document.getElementById('lineShopModal');
  if (!content || !modal) return;

  const biggestSpreads = rows.filter(r => r.max_sp >= 2.5).length;
  const totalGain = parseFloat(rows.reduce((n, r) => n + Math.max(0, r.max_gain), 0).toFixed(1));
  const sub = document.getElementById('lineShopSub');
  const sortWord = lsSort === 'spread' ? 'biggest discrepancy' : lsSort === 'conf' ? 'lean confidence' : 'card order';
  if (sub) {
    sub.textContent = `${liveRows.length} shoppable · ${biggestSpreads} with spread ≥ 2.5 · sorted by ${sortWord}`;
  }

  // ── GLOW-UP 216 G1 — the headline ────────────────────────────────────────
  // "38 pts on the table" was the most valuable sentence in this panel and it
  // was set in 10px grey inside a subtitle. It is the reason to open the screen,
  // so it gets tile treatment — the same shape Slate Check uses for CALIBRATED
  // HIT RATE / TOP EDGE, so the app reads as one system.
  const topRow = [...rows].filter(r => r.max_gain > 0).sort((a, b) => b.max_gain - a.max_gain)[0];
  const topStat = topRow ? STAT_DEFS.map(d => topRow.stats[d.key]).filter(s => s.gain === topRow.max_gain)[0] : null;
  const heroHtml = `<div class="ls-hero">
      <div class="ls-hero-tile is-primary" title="Every point here is a better number available on a book you are not currently defaulting to. Summed across the card, best prop per fighter.">
        <span class="ls-hero-label">ON THE TABLE</span>
        <span class="ls-hero-val">${totalGain}<em>pts</em></span>
        <span class="ls-hero-sub">across ${liveRows.length} fighters</span>
      </div>
      <div class="ls-hero-tile" title="Fighters where at least two books disagree by 2.5 or more on the same prop.">
        <span class="ls-hero-label">WIDE SPREADS</span>
        <span class="ls-hero-val">${biggestSpreads}</span>
        <span class="ls-hero-sub">of ${rows.length} on the card</span>
      </div>
      ${topRow && topStat ? `<div class="ls-hero-tile is-top" title="The single biggest gain available right now: ${prettyName(topRow.f.name)} ${topStat.label} on ${LEAN_BOOK_LABEL[topStat.best?.bk || ''] || (LS_TAG[topStat.best?.bk || ''] || '')} at ${topStat.best?.val}, worth ${topRow.max_gain} points versus your default book.">
        <span class="ls-hero-label">BIGGEST EDGE</span>
        <span class="ls-hero-val">+${topRow.max_gain}<em>${LS_TAG[topStat.best?.bk || ''] || ''}</em></span>
        <span class="ls-hero-sub">${prettyName(topRow.f.name)} · ${topStat.label}</span>
      </div>` : ''}
    </div>`;

  content.innerHTML = `
    ${heroHtml}
    <div class="ls-controls">
      <span class="ls-ctl-group">
        <span class="ls-ctl-label">SORT</span>
        <button class="ls-btn${lsSort === 'spread' ? ' on' : ''}" data-ls-sort="spread" title="Widest book disagreement first">SPREAD</button>
        <button class="ls-btn${lsSort === 'conf' ? ' on' : ''}" data-ls-sort="conf" title="Highest model confidence first — shop the props you're most likely to actually play">CONF</button>
        <button class="ls-btn${lsSort === 'card' ? ' on' : ''}" data-ls-sort="card" title="Card order — main event down">CARD</button>
      </span>
      <span class="ls-ctl-group">
        <span class="ls-ctl-label">STAT</span>
        <button class="ls-chip${lsStatFilter === 'all' ? ' on' : ''}" data-ls-stat="all" title="All stat families">ALL</button>
        ${STAT_DEFS.map(d => `<button class="ls-chip${lsStatFilter === d.key ? ' on' : ''}" data-ls-stat="${d.key}" title="Only ${d.label} — the column widens (click again for all)">${d.label}</button>`).join('')}
      </span>
      <span class="ls-ctl-group">
        <button class="ls-chip${lsBigOnly ? ' on' : ''}" data-ls-big title="Only props where the books disagree by 2.5 or more">Δ ≥ 2.5</button>
        ${_platformBiasCache && _platformBiasCache.length >= 2 ? `<button class="ls-chip${lsShowBias ? ' on' : ''}" data-ls-bias-toggle title="Show how each book's lines have historically landed against results. Reference data — hidden by default so the fighter list gets the room.">BIAS</button>` : ''}
        ${(lsSort !== 'spread' || lsStatFilter !== 'all' || !lsBigOnly || lsBiasBook) ? '<button class="ls-reset-inline" data-ls-reset title="Back to the default view">reset</button>' : ''}
      </span>
      <span class="ls-legend-inline">
        <span class="ls-cell-val ls-best ls-legend-swatch"><span class="ls-plat-tag">BT</span>80.5</span> take
        <span class="ls-cell-val ls-worst ls-legend-swatch"><span class="ls-plat-tag">P6</span>92.5</span> worst
        <span class="ls-cell-val ls-blocked ls-legend-swatch"><span class="ls-plat-tag">UD</span>—</span> won't take the side
        <em>OVER wants the lowest line · UNDER the highest</em>
      </span>
    </div>
    ${lsBiasBook ? `<div class="ls-filter-note">Showing only fighters where <b>${LS_TAG[lsBiasBook] || lsBiasBook}</b> holds the best line · <button class="ls-reset-inline" data-ls-reset>clear</button></div>` : ''}
    ${(lsShowBias || lsBiasBook) && _platformBiasCache && _platformBiasCache.length >= 2 ? `<div class="ls-bias-strip">
      <span class="ls-bias-head" title="Historical settle data: how far each book's line sits from the result on average. A negative number means the book posts LOW, so its overs clear more easily than the field's.">Platform bias</span>
      ${_platformBiasCache.filter(b => b.total >= 3 && Math.abs(b.avgEdge) >= 0.5).sort((a, b) => Math.abs(b.avgEdge) - Math.abs(a.avgEdge)).slice(0, 6).map(b => {
        const plat = PLAT_LABEL_MAP[b.platform] || b.platform.toUpperCase();
        const st = b.propType === 'FightTime' ? 'FT' : b.propType === 'Fantasy' ? 'FP' : b.propType === 'Fantasy_PP' ? 'FP·PP' : b.propType;
        const soft = b.avgEdge > 0 ? 'posts HIGH — its unders are the easier side' : 'posts LOW — its overs are the easier side';
        const bookKey = Object.keys(LS_TAG).find(k => (PLAT_LABEL_MAP[k] || k.toUpperCase()) === plat) || '';
        return `<button class="ls-bias-chip${lsBiasBook && lsBiasBook === bookKey ? ' on' : ''}"${bookKey ? ` data-ls-bias="${bookKey}"` : ''} title="${plat} ${st}: lines land ${b.avgEdge > 0 ? '+' : ''}${b.avgEdge} from the result on average across ${b.total} settled props — ${plat} ${soft}.${bookKey ? ' Click to show only fighters where this book has the best line.' : ''}"><span class="ls-bias-plat">${plat}</span> <span class="ls-bias-stat">${st}</span> <span class="ls-bias-val ${b.avgEdge > 0 ? 'pos' : 'neg'}">${b.avgEdge > 0 ? '+' : ''}${b.avgEdge}</span></button>`;
      }).join('')}
    </div>` : ''}
    <table class="lineshop-table">
      <thead><tr>
        <th style="text-align:left">FIGHTER + LEAN</th>
        ${(lsStatFilter === 'all' ? STAT_DEFS : STAT_DEFS.filter(d => d.key === lsStatFilter))
          .map(d => {
            // U2 — each stat owns a hue on this board (the app's existing
            // stat-family lanes), so the three zones separate without a rule
            // between them. Book hue stays on the chips; stat hue stays here.
            const n = liveRows.filter(r => r.stats[d.key].gain > 0).length;
            return `<th class="ls-th src-${d.key}" title="${n} fighter${n === 1 ? '' : 's'} with a ${d.label} line worth shopping right now.">
              <span class="ls-th-label">${d.label}</span>
              <span class="ls-th-sub">${n ? `${n} shoppable` : 'lines · take'}</span>
            </th>`;
          }).join('')}
      </tr></thead>
      <tbody>${rowsHtml || `<tr><td colspan="${(lsStatFilter === 'all' ? 3 : 1) + 1}" class="ls-empty-row">No shoppable disagreement under this filter — <button class="ls-reset-inline" data-ls-reset>reset</button></td></tr>`}</tbody>
      ${flatRows.length ? `<tbody class="ls-flat-body">
        <tr><td colspan="${(lsStatFilter === 'all' ? 3 : 1) + 1}" class="ls-fold-row"><button class="ls-fold" data-ls-fold>${lsShowFlat ? '▾' : '▸'} ${flatRows.length} fighter${flatRows.length === 1 ? '' : 's'} with no book disagreement</button></td></tr>
        ${flatHtml}
      </tbody>` : ''}
    </table>`;

  // ── GLOW-UP 234 — the panel fits itself instead of asking you to zoom ────
  // The whole card is 22 rows plus hero tiles, controls and a bias strip, which
  // is taller than the viewport at 100%. Capping it and scrolling (233) made it
  // FIT but not VISIBLE — you could still only see about fifteen fighters, and
  // the reason to open this screen is to compare the whole card at once.
  //
  // So it does what you were doing by hand, scoped to the panel: measure what
  // the content needs, measure what the window has, and scale by the ratio.
  // Browser zoom did this to the entire app; this does it to one modal.
  //
  // `width: 100/k %` before the transform is the standard pairing — scale()
  // shrinks the painted box but not the layout box, so without it the table
  // would render at full width, scale down, and leave dead space on the right.
  // ── handlers ─────────────────────────────────────────────────────────────
  // Every control re-runs this function; it is idempotent and rebinds each time,
  // the same pattern renderParlayLab uses.
  content.querySelectorAll<HTMLElement>('[data-ls-sort]').forEach(b => b.addEventListener('click', () => {
    lsSort = (b.dataset['lsSort'] as LsSort) || 'spread'; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-stat]').forEach(b => b.addEventListener('click', () => {
    const v = (b.dataset['lsStat'] as LsStatFilter) || 'all';
    lsStatFilter = lsStatFilter === v && v !== 'all' ? 'all' : v; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-bias-toggle]').forEach(b => b.addEventListener('click', () => {
    lsShowBias = !lsShowBias; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-big]').forEach(b => b.addEventListener('click', () => {
    lsBigOnly = !lsBigOnly; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-fold]').forEach(b => b.addEventListener('click', () => {
    lsShowFlat = !lsShowFlat; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-bias]').forEach(b => b.addEventListener('click', () => {
    const v = b.dataset['lsBias'] || '';
    lsBiasBook = lsBiasBook === v ? null : v; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-reset]').forEach(b => b.addEventListener('click', () => {
    lsSort = 'spread'; lsStatFilter = 'all'; lsBigOnly = true; lsBiasBook = null; lsShowBias = false; generateLineShopModal();
  }));
  content.querySelectorAll<HTMLElement>('[data-ls-take]').forEach(btn => btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const key = btn.dataset['lsTake'] || '';
    if (!key) return;
    if (bestPicksSlate.has(key)) {
      bestPicksSlate.delete(key);
      showToast(`Removed from My Slate (${bestPicksSlate.size})`);
    } else {
      const d = _leanSlateData.get(key);
      if (!d) return;
      if (!bestPicksSlate.size) bestPicksSlateOpen = true;
      bestPicksSlate.set(key, d);
      showToast(`+ ${d.clip} · My Slate (${bestPicksSlate.size})`);
    }
    generateLineShopModal();
  }));

  modal.classList.remove('is-hidden');
}

// AI × CLV Phase 2 — market-validation boost.
// Reads the live open→current drift for this fighter/propType/platform (unresolved rows only).
// If the market has moved in the AI lean's direction → +5 confidence (market validates the pick).
// If the market has moved against the lean → −5 (market disagrees). Zero drift = no adjustment.
// Returns null when no drift data is available or the lean has no direction.
function getClvBoost(f: AnalyzerFighter, el: EffectiveLean): { delta: number; marketDelta: number; openLine: number; line: number; platform: string } | null {
  if (!_fighterClvDrift) return null;
  if (el.lean !== 'over' && el.lean !== 'under') return null;
  const key = (normalizeName(f.name) || f.name).toLowerCase();
  const byProp = _fighterClvDrift.get(key);
  if (!byProp) return null;
  const propType = el._source === 'fp' ? 'Fantasy' : el._source === 'ft' ? 'FightTime' : el._source.toUpperCase();
  const byPlatform = byProp[propType];
  if (!byPlatform) return null;
  const platform = normalizeArchivePlatformLabel(activePlatformLabel(f)) || '';
  // Prefer the active platform; fall back to any available platform entry for this prop.
  let entry = platform ? byPlatform[platform] : undefined;
  let usedPlatform = platform;
  if (!entry) {
    const first = Object.entries(byPlatform)[0];
    if (!first) return null;
    usedPlatform = first[0];
    entry = first[1];
  }
  const marketDelta = entry.line - entry.openLine;
  if (marketDelta === 0) return null;
  const aligned = (el.lean === 'over' && marketDelta > 0) || (el.lean === 'under' && marketDelta < 0);
  return {
    delta: aligned ? 5 : -5,
    marketDelta,
    openLine: entry.openLine,
    line: entry.line,
    platform: usedPlatform,
  };
}

// Lazy-render: the .fighter-detail HTML for each row is built on first expand
// instead of at row creation. Builder closures captured here, keyed by row el.
// Cuts initial render from ~1000ms to ~250ms by deferring detail innerHTML.
const _pendingDetailBuilders = new WeakMap<HTMLElement, () => string>();

// Set of "platform:stat" keys present somewhere on the active slate. Populated
// by the render loop before iterating fighters; lineCell skips slots not in
// this set so dead columns don't take horizontal space.
let _slatePresentSlots: Set<string> | null = null;

function buildFighterRow(f: AnalyzerFighter, oppEntry: AnalyzerFighter|null, fightIndex = 0): HTMLDivElement {
  _h2hFighterMap.set(f.name.toLowerCase(), f);
  const db = f.db || {} as FighterDB;
  const lean = getEffectiveLean(f);
  const leanEv = computeFighterEV(f, lean);
  const leanEvDetail = computeDetailedEV(f, lean);
  const perBookEv = computePerBookEV(f, lean);
  const leanClass = lean.lean === 'over' ? 'lean-over' : lean.lean === 'under' ? 'lean-under' : lean.lean === 'push' ? 'lean-push' : 'lean-none';
  const leanSuffix = lean._label || '';
  const leanText  = lean.lean === 'over' ? `▲ OVER${leanSuffix}` : lean.lean === 'under' ? `▼ UNDER${leanSuffix}` : lean.lean === 'push' ? '~ PUSH' : db.loaded ? '—' : '⟳';
  const leanRGB = lean.lean === 'over' ? '0,232,122' : lean.lean === 'under' ? '255,58,96' : lean.lean === 'push' ? '240,192,64' : '50,58,88';
  const ownMl = f.moneyline ?? resolveMoneylineFromMap(f.name);
  const _roleOppName = f.opponent || '';
  const oppMl = _roleOppName ? (resolveMoneylineFromMap(_roleOppName) ?? allFighters.find(x => namesMatch(normalizeName(x.name) || '', normalizeName(_roleOppName) || ''))?.moneyline ?? null) : null;
  const isDog = ownMl != null && oppMl != null
    ? (ownMl > oppMl)
    : isMoneylineUnderdog(f);
  const roleRGB = isDog ? '255,138,61' : '44,212,208';
  const rawConfPct = lean.conf || 0;
  const clvBoost = rawConfPct > 0 ? getClvBoost(f, lean) : null;
  const confPct = clvBoost
    ? Math.max(25, Math.min(90, rawConfPct + clvBoost.delta))
    : rawConfPct;
  const recalConf = confPct > 0 ? getRecalibratedConfidence(confPct, lean._source) : null;
  const displayConf = recalConf != null ? recalConf : confPct;
  const leanGradStyle = lean.lean !== 'none' && displayConf > 0
    ? `background:linear-gradient(90deg,rgba(${roleRGB},0.18) ${displayConf}%,rgba(${roleRGB},0.04) ${displayConf}%);`
    : '';
  const gradeLetter = displayConf > 0 ? getConfidenceGrade(displayConf) : '';
  const displayGrade = gradeLetter ? ` ${gradeLetter}` : '';
  const gradeChipHtml = gradeLetter ? ` <span class="lean-grade-chip lean-grade-${gradeLetter.toLowerCase()}" title="Confidence grade ${gradeLetter}">${gradeLetter}</span>` : '';
  const clvTag = clvBoost
    ? (() => {
        const arrow = clvBoost.delta > 0 ? '↑' : '↓';
        const signed = `${clvBoost.delta > 0 ? '+' : ''}${clvBoost.delta}`;
        const color = clvBoost.delta > 0 ? 'var(--green)' : 'var(--red)';
        const driftStr = `${clvBoost.marketDelta > 0 ? '+' : ''}${clvBoost.marketDelta.toFixed(1)}`;
        const note = clvBoost.delta > 0
          ? `Market validates ${lean.lean?.toUpperCase()}: line drifted ${driftStr} from open (${clvBoost.openLine}→${clvBoost.line}) on ${clvBoost.platform}.`
          : `Market disagrees with ${lean.lean?.toUpperCase()}: line drifted ${driftStr} from open (${clvBoost.openLine}→${clvBoost.line}) on ${clvBoost.platform}.`;
        return ` <span style="color:${color};font-size:9px;font-weight:700" title="${note}">${arrow}${signed}</span>`;
      })()
    : '';
  const confInlineLabel = confPct > 0
    ? recalConf != null && recalConf !== confPct
      ? `<span class="lean-conf-inline" title="Original: ${rawConfPct}% ${lean.confidenceGrade || ''} · Recalibrated from historical accuracy${clvBoost ? ` · AI×CLV ${clvBoost.delta > 0 ? '+' : ''}${clvBoost.delta}` : ''}">${displayConf}%${gradeChipHtml} <span style="font-size:9px;opacity:0.6">↻</span>${clvTag}</span>`
      : `<span class="lean-conf-inline" title="Confidence${lean.confidenceGrade ? ' ' + lean.confidenceGrade : ''}: ${rawConfPct}%${clvBoost ? ` · AI×CLV ${clvBoost.delta > 0 ? '+' : ''}${clvBoost.delta}` : ''}">${confPct}%${gradeChipHtml}${clvTag}</span>`
    : '';
  const activeLine = activePlatformLine(f);
  const platformLabel = activePlatformLabel(f);
  const showSource = (s: 'p6'|'ud'|'pp'|'betr'|'dk') => !!sourceVisibility[s];
  // ── Best line shopping ─────────────────────────────────────────────────────
  // For each stat, find which book has the best number given lean direction.
  // over → want the LOWEST line (easiest to beat); under → want the HIGHEST line.
  // Only badge when ≥2 books post the stat AND spread ≥ 0.5.
  type BookEntry = { source: 'p6'|'ud'|'pp'|'betr'|'dk'; value: number };
  // Chip key → the book key statUnderBookOffered expects.
  const SHOP_BOOK_KEY: Record<'p6'|'ud'|'pp'|'betr'|'dk', string> = {
    p6: 'pick6', ud: 'underdog', pp: 'prizepicks', betr: 'betr', dk: 'draftkings_sportsbook',
  };
  /**
   * Books that actually offer the side we're leaning. For an UNDER this matters:
   * Pick6 TD props are More-only unless a Less button was positively scraped, and
   * that varies PER FIGHTER on the same card (Stirling 1.5 has Less, Blachowicz
   * 1.5 does not). Without this filter the badge recommended the mathematically
   * best line on a book that wouldn't take the bet — and contradicted the play
   * pill on the same row, which routes through leanBestBook and DOES filter.
   * Overs need no gating: every book that posts a line takes the over.
   */
  const shopPlaceable = (
    list: BookEntry[],
    leanDir: string,
    stat: 'ss'|'ss_r1'|'td'|'ft'|'ctrl',
  ): BookEntry[] => leanDir !== 'under'
    ? list
    : list.filter(c => statUnderBookOffered(f, stat, SHOP_BOOK_KEY[c.source]));

  function calcBestShop(
    candidates: BookEntry[],
    leanDir: string | null | undefined,
    stat: 'ss'|'ss_r1'|'td'|'ft'|'ctrl'
  ): 'p6'|'ud'|'pp'|'betr'|'dk' | null {
    const visible = candidates.filter(c => c.value != null && showSource(c.source));
    if (visible.length < 2 || !leanDir || leanDir === 'push' || leanDir === 'none') return null;
    const usable = shopPlaceable(visible, leanDir, stat);
    if (!usable.length) return null;
    // Exactly one book takes this side while others show a line: that IS the
    // shopping answer, even with no spread to compare — flag it rather than
    // going silent and leaving the unplaceable books looking equally valid.
    if (usable.length === 1) return usable[0].source;
    const vals = usable.map(c => c.value);
    if (Math.max(...vals) - Math.min(...vals) < 0.5) return null;
    const best = leanDir === 'over'
      ? usable.reduce((b, c) => c.value < b.value ? c : b)
      : usable.reduce((b, c) => c.value > b.value ? c : b);
    return best.source;
  }
  const ssCandidates: BookEntry[] = ([
    { source: 'p6'   as const, value: f.line_p6_ss   },
    { source: 'ud'   as const, value: f.line_ud_ss   },
    { source: 'pp'   as const, value: f.line_pp_ss   },
    { source: 'betr' as const, value: f.line_betr_ss },
    { source: 'dk'   as const, value: f.line_dk_ss   },
  ] as BookEntry[]).filter(c => c.value != null);
  const tdCandidates: BookEntry[] = ([
    { source: 'p6'   as const, value: f.line_p6_td   },
    { source: 'ud'   as const, value: f.line_ud_td   },
    { source: 'pp'   as const, value: f.line_pp_td   },
    { source: 'betr' as const, value: f.line_betr_td },
    { source: 'dk'   as const, value: f.line_dk_td   },
  ] as BookEntry[]).filter(c => c.value != null);
  const ftCandidates: BookEntry[] = ([
    { source: 'p6'   as const, value: f.line_p6_ft   },
    { source: 'ud'   as const, value: f.line_ud_ft   },
    { source: 'pp'   as const, value: f.line_pp_ft   },
    { source: 'betr' as const, value: f.line_betr_ft },
    { source: 'dk'   as const, value: f.line_dk_ft   },
  ] as BookEntry[]).filter(c => c.value != null);
  const ctrlCandidates: BookEntry[] = ([
    { source: 'p6'   as const, value: f.line_p6_ctrl   },
    { source: 'ud'   as const, value: f.line_ud_ctrl   },
    { source: 'pp'   as const, value: f.line_pp_ctrl   },
    { source: 'betr' as const, value: f.line_betr_ctrl },
    { source: 'dk'   as const, value: f.line_dk_ctrl   },
  ] as BookEntry[]).filter(c => c.value != null);
  // GLOW-UP 193 L4 — extend best-line shopping to R1 SS (cross-book comparable
  // across PP/UD/DK, and now a full lean source). FP is intentionally NOT shopped:
  // each book scores fantasy points on a different formula, so raw FP lines aren't
  // comparable across books.
  const ssR1Candidates: BookEntry[] = ([
    { source: 'pp' as const, value: f.line_pp_ss_r1 },
    { source: 'ud' as const, value: f.line_ud_ss_r1 },
    { source: 'dk' as const, value: f.line_dk_ss_r1 },
  ] as BookEntry[]).filter(c => c.value != null);
  const bestSS   = calcBestShop(ssCandidates,   f.lean_ss?.lean   ?? null, 'ss');
  const bestTD   = calcBestShop(tdCandidates,   f.lean_td?.lean   ?? null, 'td');
  const bestFT   = calcBestShop(ftCandidates,   f.lean_ft?.lean   ?? null, 'ft');
  const bestCTRL = calcBestShop(ctrlCandidates, f.lean_ctrl?.lean ?? null, 'ctrl');
  const bestSSR1 = calcBestShop(ssR1Candidates, f.lean_ss_r1?.lean ?? null, 'ss_r1');
  // Best-side badge for the inline R1 SS cells (they don't route through lineCell).
  const ssR1BestBadge = (source: 'pp'|'ud'|'dk'): string => bestSSR1 === source
    ? `<div class="best-shop-badge" title="Best line for ${(f.lean_ss_r1?.lean || '').toUpperCase()} R1 SS: ${source.toUpperCase()} vs other books">best</div>`
    : '';
  const ssR1BestCls = (source: 'pp'|'ud'|'dk'): string => bestSSR1 === source ? ' best-line' : '';

  // Worst-line: the least favorable line for the lean direction (opposite of best)
  function calcWorstShop(
    candidates: BookEntry[],
    leanDir: string | null | undefined,
    stat: 'ss'|'ss_r1'|'td'|'ft'|'ctrl'
  ): 'p6'|'ud'|'pp'|'betr'|'dk' | null {
    const visible = candidates.filter(c => c.value != null && showSource(c.source));
    if (visible.length < 2 || !leanDir || leanDir === 'push' || leanDir === 'none') return null;
    // Same placeability filter as calcBestShop: a book that won't take the side
    // isn't a worse price, it's not a price at all. Calling it "worst" implies
    // it was in the running.
    const usable = shopPlaceable(visible, leanDir, stat);
    if (usable.length < 2) return null;
    const vals = usable.map(c => c.value);
    if (Math.max(...vals) - Math.min(...vals) < 0.5) return null;
    const worst = leanDir === 'over'
      ? usable.reduce((w, c) => c.value > w.value ? c : w)
      : usable.reduce((w, c) => c.value < w.value ? c : w);
    return worst.source;
  }
  const worstSS   = calcWorstShop(ssCandidates,   f.lean_ss?.lean   ?? null, 'ss');
  const worstTD   = calcWorstShop(tdCandidates,   f.lean_td?.lean   ?? null, 'td');
  const worstFT   = calcWorstShop(ftCandidates,   f.lean_ft?.lean   ?? null, 'ft');
  const worstCTRL = calcWorstShop(ctrlCandidates, f.lean_ctrl?.lean ?? null, 'ctrl');

  const lineCell = (source: 'p6'|'ud'|'pp'|'betr'|'dk', stat: 'fp'|'ss'|'td'|'ft'|'ctrl', value: number | null | undefined): string => {
    if (!showSource(source)) return '';
    if (value == null) return '';
    if (_slatePresentSlots && !_slatePresentSlots.has(`${source}:${stat}`)) return '';
    const sourceLabel = source === 'p6' ? 'P6' : source === 'ud' ? 'UD' : source === 'pp' ? 'PP' : source === 'dk' ? 'DK' : 'BT';
    const _key = openingLineKey(source, stat, f.name);
    const openVal = _openingLines.get(_key);
    const openDeltaRaw = (openVal != null) ? parseFloat((value - openVal).toFixed(1)) : null;
    const openDelta = sanitizeDelta(stat, openDeltaRaw);
    const movementHtml = (openDelta != null && Math.abs(openDelta) >= 0.5)
      ? `<div class="line-movement ${openDelta > 0 ? 'mv-up' : 'mv-down'}" title="${openVal != null ? `Was: ${openVal}` : ''}"><span class="mv-arrow">${openDelta > 0 ? '▲' : '▼'}</span>${Math.abs(openDelta)}</div>`
      : '';
    const flashClass = (openDelta != null && Math.abs(openDelta) >= 0.5)
      ? (openDelta > 0 ? ' line-flash-up' : ' line-flash-down')
      : '';
    const isBest = (stat === 'ss'   && bestSS   === source) ||
                   (stat === 'td'   && bestTD   === source) ||
                   (stat === 'ft'   && bestFT   === source) ||
                   (stat === 'ctrl' && bestCTRL === source);
    const isWorst = !isBest && (
                   (stat === 'ss'   && worstSS   === source) ||
                   (stat === 'td'   && worstTD   === source) ||
                   (stat === 'ft'   && worstFT   === source) ||
                   (stat === 'ctrl' && worstCTRL === source));
    const leanDir = stat === 'ss'   ? f.lean_ss?.lean
                  : stat === 'td'   ? f.lean_td?.lean
                  : stat === 'ft'   ? f.lean_ft?.lean
                  : stat === 'ctrl' ? f.lean_ctrl?.lean
                  : null;
    const bestBadge = isBest
      ? `<div class="best-shop-badge" title="Best line for ${leanDir?.toUpperCase()} on ${sourceLabel}: ${value} vs other books">best</div>`
      : '';
    const lineClass = isBest ? ' best-line' : isWorst ? ' worst-line' : '';
    // GLOW-UP 195 L1/L2 — one-sided marker. The book may only offer ONE side
    // (Pick6 TD is More-only, a dog's Pick6 FP has no Less, …), and DK — the only
    // book with real odds — can price a side as chalk (-300 or worse), which is
    // one-sided in practice even when both are posted. Same ↑ convention the KD
    // chip already uses. Both sides usable → no mark, so the grid stays quiet.
    const sides = sideAvailability(f, stat, LINE_SRC_TO_BOOK[source]);
    const chalkOver  = source === 'dk' && dkSideChalk(f, stat, 'over');
    const chalkUnder = source === 'dk' && dkSideChalk(f, stat, 'under');
    const usableOver  = sides.over  && !chalkOver;
    const usableUnder = sides.under && !chalkUnder;
    let sideMark = '';
    if (!usableOver && !usableUnder) {
      sideMark = `<span class="side-only none" title="Neither side is takeable on ${sourceLabel} for this ${stat.toUpperCase()}">⛔</span>`;
    } else if (usableOver !== usableUnder) {
      const onlyOver = usableOver;
      const byChalk = onlyOver ? chalkUnder : chalkOver;
      const chalkOdds = dkSideOdds(f, stat, onlyOver ? 'under' : 'over');
      const why = byChalk
        ? `${sourceLabel} prices the ${onlyOver ? 'UNDER' : 'OVER'} at ${chalkOdds != null ? fmtOdds(chalkOdds) : 'chalk'} — chalk (${DK_CHALK_THRESHOLD} or worse), no value. Only the ${onlyOver ? 'OVER' : 'UNDER'} is worth taking here.`
        : `${sourceLabel} offers the ${onlyOver ? 'OVER' : 'UNDER'} only on this ${stat.toUpperCase()} — the ${onlyOver ? 'under' : 'over'} side is not placeable.`;
      sideMark = `<span class="side-only${byChalk ? ' chalk' : ''}" title="${why}">${onlyOver ? '↑' : '↓'}</span>`;
    }
    const oneSidedCls = sideMark ? (usableOver !== usableUnder ? ' one-sided' : ' no-side') : '';
    const sparkHtml = buildChipSparkline(f.name, stat, source);
    return `<div class="line-cell ${stat} src-${source}${lineClass}${flashClass}${oneSidedCls}"><div class="line-platform"><span class="line-source-tag src-${source}">${sourceLabel}</span><span>${stat.toUpperCase()}</span>${sideMark}</div><div class="line-value ${source}">${value}${movementHtml}</div>${sparkHtml}${bestBadge}</div>`;
  };

  function platformStatLine(entry: AnalyzerFighter | null, stat: 'ss' | 'td' | 'ft' | 'ctrl' | 'ss_r1'): number | null {
    if (!entry) return null;
    // R1 SS is a PP/UD/DK-only market — Pick6 and Betr never post it (there is no
    // line_p6_ss_r1 or line_betr_ss_r1 anywhere), so those two selections fall
    // through to a book that does rather than blanking the panel.
    if (stat === 'ss_r1') {
      const pp1 = entry.line_pp_ss_r1, ud1 = entry.line_ud_ss_r1, dk1 = entry.line_dk_ss_r1;
      if (currentPlatform === 'underdog') return ud1 ?? pp1 ?? dk1 ?? null;
      if (currentPlatform === 'draftkings_sportsbook') return dk1 ?? pp1 ?? ud1 ?? null;
      return pp1 ?? ud1 ?? dk1 ?? null;
    }
    const p6 = stat === 'ss' ? entry.line_p6_ss   : stat === 'td' ? entry.line_p6_td   : stat === 'ft' ? entry.line_p6_ft   : entry.line_p6_ctrl;
    const ud = stat === 'ss' ? entry.line_ud_ss   : stat === 'td' ? entry.line_ud_td   : stat === 'ft' ? entry.line_ud_ft   : entry.line_ud_ctrl;
    const pp = stat === 'ss' ? entry.line_pp_ss   : stat === 'td' ? entry.line_pp_td   : stat === 'ft' ? entry.line_pp_ft   : entry.line_pp_ctrl;
    const dk = stat === 'ss' ? entry.line_dk_ss   : stat === 'td' ? entry.line_dk_td   : stat === 'ft' ? entry.line_dk_ft   : entry.line_dk_ctrl;
    const bt = stat === 'ss' ? entry.line_betr_ss : stat === 'td' ? entry.line_betr_td : stat === 'ft' ? entry.line_betr_ft : entry.line_betr_ctrl;
    if (currentPlatform === 'pick6') return p6 ?? ud ?? pp ?? dk ?? bt ?? null;
    if (currentPlatform === 'underdog') return ud ?? p6 ?? pp ?? dk ?? bt ?? null;
    if (currentPlatform === 'prizepicks') return pp ?? p6 ?? ud ?? dk ?? bt ?? null;
    if (currentPlatform === 'draftkings_sportsbook') return dk ?? p6 ?? ud ?? pp ?? bt ?? null;
    return bt ?? p6 ?? ud ?? pp ?? dk ?? null;
  }

  const oppSsLine = platformStatLine(oppEntry, 'ss');
  const oppTdLine = platformStatLine(oppEntry, 'td');
  const oppFpLine = oppEntry ? activePlatformLine(oppEntry) : null;
  const oppName   = oppEntry ? oppEntry.name : (f.opponent || null);
  debugLog(`SS/TD chart: ${f.name} → oppEntry="${oppEntry?.name ?? 'NOT FOUND'}" oppSsLine=${oppSsLine} oppTdLine=${oppTdLine} (opp ss p6=${oppEntry?.line_p6_ss ?? '—'} ud=${oppEntry?.line_ud_ss ?? '—'} pp=${oppEntry?.line_pp_ss ?? '—'} bt=${oppEntry?.line_betr_ss ?? '—'} | opp td p6=${oppEntry?.line_p6_td ?? '—'} ud=${oppEntry?.line_ud_td ?? '—'} pp=${oppEntry?.line_pp_td ?? '—'} bt=${oppEntry?.line_betr_td ?? '—'})`);

  type HistoryRow = { opp?: string | null; fp?: number | null; sigStr?: number | null; sigStrR1?: number | null; sigStrBody?: number | null; sigStrLeg?: number | null; td?: number | null; kd?: number | null; timeSecs?: number | null; ctrlSecs?: number | null; result?: string | null; method?: string | null; date?: string | null; round?: number | null };

  function formatMinutesAsClock(minutes: number | null | undefined): string {
    if (minutes == null || !Number.isFinite(minutes)) return '—';
    const totalSeconds = Math.max(0, Math.round(minutes * 60));
    const mm = Math.floor(totalSeconds / 60);
    const ss = totalSeconds % 60;
    return `${mm}:${String(ss).padStart(2, '0')}`;
  }

  function buildHistoryBars(
    fights: HistoryRow[] | undefined,
    valFn: (h: HistoryRow) => number | null | undefined,
    lineFP: number | null,
    lineSS: number | null,
    lineTD: number | null,
    lineFT: number | null,
    labelFn: 'fp'|'ss'|'td'|'ft'|'ctrl',
    lineCTRL: number | null = null,
    // GLOW-UP 166 (level-up 4): when provided, the panel renders a line-
    // sensitivity strip — history hit rate recomputed at EVERY book's line.
    bookLines: Array<{ tag: string; line: number }> | null = null,
  ): string {
    if (!fights?.length) return db.loaded
      ? '<div class="history-empty">No fight history found on UFCStats</div>'
      : '<div class="history-empty">⟳ Fetching from UFCStats...</div>';

    const recentRows = fights;
    const values = recentRows
      .map(valFn)
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));

    if (!values.length) {
      return '<div class="history-empty">No stat samples available</div>';
    }

    const line = labelFn === 'fp' ? lineFP
               : labelFn === 'ss' ? lineSS
               : labelFn === 'td' ? lineTD
               : labelFn === 'ft' ? lineFT
               : lineCTRL;
    const maxVal = Math.max(...values, (line || 0) * 1.3, 1);

    // ── GLOW-UP 19: drilldown chart evolution ─────────────────────────────
    const fmtVal = (v: number): string => (labelFn === 'ft' || labelFn === 'ctrl')
      ? formatMinutesAsClock(v)
      : (Number.isInteger(v) ? String(v) : v.toFixed(1));
    const escAttr = (x: string): string => x.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));

    // Panel meta header: hit rate vs line + sample average (with avg marker in bars)
    const avg = values.reduce((s2, v) => s2 + v, 0) / values.length;

    // ── WIN/LOSS SPLIT OF THE SAME SAMPLES ────────────────────────────────
    // A single career average blends two different fighters. Steven Asplund
    // averages 101.8 FP overall, but that is 134.1 across his wins and 37.2 in
    // his loss — and which of those the projection should resemble depends on
    // whether he is expected to win. The blended number describes neither.
    //
    // Pair values with results BEFORE filtering: `values` above drops nulls and
    // loses the row alignment, so it cannot be zipped back to results afterwards.
    //
    // Rendered whenever the sample carries ANY result. An earlier cut hid the
    // split unless BOTH sides had fights, reasoning that for an unbeaten fighter
    // "W avg" merely repeats "avg". That was wrong in practice: on this card
    // Thainara (4-0), Salkilld (6-0), Ty Miller (2-0) and Sousa (2-0) all showed
    // nothing, and a silently absent chip reads as BROKEN rather than as
    // "there is nothing to split". An empty side now renders as a muted dash
    // with its zero count, so the panel states which kind of empty it is.
    //
    // Opponent-side panels (OPP x SCORED VS y) carry no result/method at all —
    // those still render nothing, because there is no outcome to report.
    const wlPairs = recentRows
      .map(h => ({ v: valFn(h), r: (h.result || '').toLowerCase() }))
      .filter((x): x is { v: number; r: string } => typeof x.v === 'number' && Number.isFinite(x.v));
    const winVals = wlPairs.filter(x => x.r === 'win').map(x => x.v);
    const lossVals = wlPairs.filter(x => x.r === 'loss').map(x => x.v);
    const meanOf = (a: number[]): number => a.reduce((s2, v) => s2 + v, 0) / a.length;
    const wlChip = (cls: 'w' | 'l', label: string, vals: number[], tip: string): string =>
      `<span class="hm-wl ${cls}${vals.length ? '' : ' empty'}" title="${tip}">${label} ${vals.length ? fmtVal(meanOf(vals)) : '—'}<i>${vals.length}</i></span>`;
    const wlHTML = wlPairs.some(x => x.r === 'win' || x.r === 'loss')
      ? wlChip('w', 'W', winVals,
          winVals.length
            ? `Average across the ${winVals.length} fight${winVals.length === 1 ? '' : 's'} this fighter WON. Compare against the losses figure: a wide gap means the stat is outcome-driven, so the projection is really a bet on the result.`
            : 'No wins in this sample.')
        + wlChip('l', 'L', lossVals,
          lossVals.length
            ? `Average across the ${lossVals.length} fight${lossVals.length === 1 ? '' : 's'} this fighter LOST.`
            : 'No losses in this sample — every fight on record is a win, so the W average IS the overall average and there is nothing to split.')
      : '';

    let metaHTML = '';
    if (line != null && line > 0) {
      const overs = values.filter(v => v > line).length;
      const rate = overs / values.length;
      const chipCls = rate >= 0.6 ? 'over' : rate <= 0.4 ? 'under' : 'mixed';
      const ratePct = Math.round(rate * 100);
      // GLOW-UP 166 (level-up 3): L5 split — recency vs career. Values are
      // newest-first, so the first five are the last five fights. Only shown
      // when the career sample is bigger than 5 (otherwise it IS the rate).
      let l5HTML = '';
      if (values.length > 5) {
        const l5Overs = values.slice(0, 5).filter(v => v > line).length;
        const l5Cls = l5Overs / 5 >= 0.6 ? 'over' : l5Overs / 5 <= 0.4 ? 'under' : 'mixed';
        l5HTML = `<span class="hm-rate hm-l5 ${l5Cls}" title="Hit rate over the 5 most recent fights — when this disagrees with the career rate, the profile is shifting">L5 ${l5Overs}/5</span>`;
      }
      metaHTML = `<div class="hist-meta"><span class="hm-rate ${chipCls}">${overs}/${values.length} over line</span>${l5HTML}<span class="hm-track" title="${ratePct}% of fights cleared the line"><i style="width:${ratePct}%"></i></span><span class="hm-avg">avg ${fmtVal(avg)}</span>${wlHTML}</div>`;
    } else if (wlHTML) {
      // No line posted for this stat, so no hit-rate row — but the win/loss split
      // still says something, and previously the whole meta header vanished.
      metaHTML = `<div class="hist-meta"><span class="hm-avg">avg ${fmtVal(avg)}</span>${wlHTML}</div>`;
    }

    // (Rematch grouping was tried and reverted by request — every meeting
    // renders as its own row so each fight's number stays visible in place.)
    const rowHtml = (h: HistoryRow): string => {
      const val = valFn(h);
      if (val == null) return '';
      const pct = Math.min(100, (val / maxVal) * 100);
      const linePct = line ? Math.min(100, (line / maxVal) * 100) : null;
      const isOver = line ? val > line : true;
      const displayVal = fmtVal(val);

      // Result dot + tooltip payload (opp rows lack result/method — degrade gracefully)
      const res = (h.result || '').toLowerCase();
      const resCls = res === 'win' ? 'w' : res === 'loss' ? 'l' : '';
      const m = (h.method || '').toUpperCase();
      const methodAbbr = m.includes('KO') ? 'KO' : m.includes('SUB') ? 'SUB' : m.includes('DEC') ? 'DEC' : '';
      const resText = resCls
        ? `${resCls === 'w' ? 'W' : 'L'}${methodAbbr ? ' · ' + methodAbbr : ''}${h.round ? ' R' + h.round : ''}`
        : '';
      const delta = line != null && line > 0 ? val - line : null;
      const deltaText = delta == null ? '' : (labelFn === 'ft' || labelFn === 'ctrl')
        ? `${delta < 0 ? '-' : '+'}${formatMinutesAsClock(Math.abs(delta))}`
        : `${delta > 0 ? '+' : ''}${delta.toFixed(1)}`;
      // GLOW-UP 166 (H2H level-up 1): display-name repair + year tag — every
      // data point says WHEN it's from without a hover.
      const oppName = prettyName(h.opp || '?');
      const yr = (h.date || '').match(/(\d{4})/)?.[1] || '';
      // GLOW-UP 166 (level-up 3): rows 3+ years old dim — ancient data points
      // shouldn't read as loud as last year's (hover restores full brightness).
      const oldRow = yr !== '' && (new Date().getFullYear() - Number(yr)) >= 3;
      return `<div class="history-bar-row has-tip${oldRow ? ' hist-old' : ''}" data-ht-opp="${escAttr(oppName)}" data-ht-res="${resCls}" data-ht-restext="${escAttr(resText)}" data-ht-date="${escAttr(h.date || '')}" data-ht-val="${escAttr(displayVal)}" data-ht-line="${line != null && line > 0 ? escAttr(fmtVal(line)) : ''}" data-ht-delta="${escAttr(deltaText)}" data-ht-over="${isOver ? '1' : '0'}">
        <div class="history-opp">${resCls ? `<span class="hist-res ${resCls}"></span>` : ''}${oppName}</div>
        <div class="history-bar-wrap">
          <div class="history-bar-fill ${isOver ? 'over-line' : 'under-line'}" data-fill-width="${pct}%" style="width:0%"></div>
          ${linePct != null ? `<div class="line-marker" style="left:${linePct}%"></div>` : ''}
        </div>
        <span class="hist-yr" title="${escAttr(h.date || '')}">${yr ? `'${yr.slice(2)}` : ''}</span>
        ${resCls ? `<span class="hist-outcome ${resCls}" title="${escAttr(resText)}${h.method ? ' — ' + escAttr(h.method) : ''}">${resCls === 'w' ? 'W' : 'L'}${methodAbbr ? `<i>${methodAbbr}</i>` : ''}</span>` : '<span class="hist-outcome empty"></span>'}
        <div class="history-bar-val">${displayVal}</div>
      </div>`;
    };

    const rowsHTML = recentRows.map(h => rowHtml(h)).join('');

    // GLOW-UP 166 (level-up 4): line-sensitivity strip — same history, every
    // book's line. Highest hit count tints green (softest line for overs),
    // lowest tints red (softest for unders). Needs 2+ distinct lines to say
    // anything a single meta row doesn't.
    let sensHTML = '';
    if (bookLines && bookLines.length >= 2 && values.length >= 3) {
      const uniqLines = new Set(bookLines.map(b => b.line));
      if (uniqLines.size >= 2) {
        const rates = bookLines.map(b => ({ ...b, overs: values.filter(v => v > b.line).length }));
        const maxR = Math.max(...rates.map(r => r.overs));
        const minR = Math.min(...rates.map(r => r.overs));
        sensHTML = `<div class="hist-sens" title="History hit rate recomputed at each book's current line — green = cleared most often (softest for OVER), red = least often (softest for UNDER)"><span class="hs-label">@ line</span>${rates.map(r =>
          `<span class="hs-chip${maxR !== minR && r.overs === maxR ? ' hs-hi' : ''}${maxR !== minR && r.overs === minR ? ' hs-lo' : ''}"><b>${r.tag}</b> ${fmtVal(r.line)} <i>${r.overs}/${values.length}</i></span>`
        ).join('')}</div>`;
      }
    }

    return metaHTML + sensHTML + rowsHTML;
  }

  const fights    = db.history    || [];
  const oppFights = db.oppHistory || [];
  const ssLine   = platformStatLine(f, 'ss');
  const tdLine   = platformStatLine(f, 'td');
  const ftLine   = platformStatLine(f, 'ft');
  const ctrlLine = platformStatLine(f, 'ctrl');
  const primarySSLine = ssLine;
  const avgSS = db.avgSigStr ?? null;

  // ── Opponent-adjusted SS projection ───────────────────────────────────────
  // oppHistory[n].sigStr = SS landed ON the opponent in fight n = "SS allowed"
  const oppSSAllowedSamples = (oppEntry?.db?.oppHistory ?? [])
    .map(h => h.sigStr)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const oppAvgSSAllowed = oppSSAllowedSamples.length >= 3
    ? parseFloat((oppSSAllowedSamples.reduce((s, v) => s + v, 0) / oppSSAllowedSamples.length).toFixed(1))
    : null;
  // Classic attack/defense split: average fighter output with opponent's concession rate
  const projSS = (avgSS != null && oppAvgSSAllowed != null)
    ? parseFloat(((avgSS + oppAvgSSAllowed) / 2).toFixed(1))
    : null;
  const displaySS = projSS ?? avgSS;

  // ── 5R vs 3R normalization ─────────────────────────────────────────────────
  // Primary: scheduledRoundsMap populated from UFCStats upcoming card scrape.
  // Fallback: FT line > 12.5 min. Default: 3 rounds.
  const _ftLine = platformStatLine(f, 'ft');
  const _normFighterName = normalizeName(f.name);
  // Title-based main-event lookup (UFCStats event-page fight order is not reliable
  // for upcoming cards, so we identify the headliner by parsing the event title).
  const _headliner = findHeadlinerPair();
  const _isMainEventFighter = _normFighterName != null && _headliner != null &&
    (_headliner.f1 === _normFighterName || _headliner.f2 === _normFighterName);
  const isFiveRound = _isMainEventFighter;
  // Expected average actual fight durations (accounting for all finish rates in that format)
  const FIVE_ROUND_MINS  = 15.0;
  const THREE_ROUND_MINS = 9.0;
  const histAvgMins = db.avgTimeMins ?? null;
  let roundNormFactor = 1.0;
  let roundNormTag    = '';  // '5R↑' | '3R↓' | ''
  if (histAvgMins != null && histAvgMins >= 3) {
    if (isFiveRound) {
      // 5R fight: boost stats if fighter's history is shorter (typical 3R background)
      const raw = FIVE_ROUND_MINS / histAvgMins;
      if (raw > 1.08) {
        roundNormFactor = parseFloat(Math.min(1.8, raw).toFixed(3));
        roundNormTag = '5R↑';
      } else if (raw < 0.92) {
        roundNormFactor = parseFloat(Math.max(0.6, raw).toFixed(3));
        roundNormTag = '5R↓';
      }
    } else {
      // 3R fight: only reduce if fighter's history is notably longer (e.g. title fight veterans)
      const raw = THREE_ROUND_MINS / histAvgMins;
      if (raw < 0.92) {
        roundNormFactor = parseFloat(Math.max(0.6, raw).toFixed(3));
        roundNormTag = '3R↓';
      }
      // Never boost for 3R fights — the line already accounts for the fighter's finish rate
    }
  }

  // Round-normalize SS: apply factor after opp-adjustment, before delta calc
  const normDisplaySS = (displaySS != null && roundNormFactor !== 1.0)
    ? parseFloat((displaySS * roundNormFactor).toFixed(1))
    : null;
  const finalDisplaySS = normDisplaySS ?? displaySS;

  // ── Opponent-adjusted TD projection ──────────────────────────────────────────
  const avgTDraw = db.avgTDperFight ?? null;
  const oppTDAllowedSamples = (oppEntry?.db?.oppHistory ?? [])
    .map(h => h.td)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v >= 0);
  const oppAvgTDAllowed = oppTDAllowedSamples.length >= 3
    ? parseFloat((oppTDAllowedSamples.reduce((s, v) => s + v, 0) / oppTDAllowedSamples.length).toFixed(1))
    : null;
  const projTD = (avgTDraw != null && oppAvgTDAllowed != null)
    ? parseFloat(((avgTDraw + oppAvgTDAllowed) / 2).toFixed(1))
    : null;
  const displayTD = projTD ?? avgTDraw;
  const normDisplayTD = (displayTD != null && roundNormFactor !== 1.0)
    ? parseFloat((displayTD * roundNormFactor).toFixed(1))
    : null;
  const finalDisplayTD = normDisplayTD ?? displayTD;

  // ── NO-HISTORY FIGHTERS ────────────────────────────────────────────────────
  // A fighter with an empty UFCStats log carries slpm 0 and an empty history, so
  // every average computes to 0.0 — and 0.0 renders identically to a real
  // measurement of zero. It is not a zero, it is an ABSENCE, and the delta built
  // on it is arithmetic on nothing: the further the line sits above zero, the
  // more confident the UNDER looks. Measured on the 2026-08-08 card: Richie
  // Miranda (0 fights) showed `SS AVG 0.0 · LINE 26.5 · −26.5` and a ▼ UNDER 71%
  // at ~EV +36%; Gigi Canuto (0 fights) showed ▼ UNDER 59%. Same shape as the
  // phantom-line bug — a meaningless number presenting as the best bet on the
  // board rather than as an error.
  //
  // Display-side only. This suppresses the FAKE PRECISION; it does not touch the
  // lean, which is a separate call the user has not made.
  const hasNoHistory = !f.db || !Array.isArray(f.db.history) || f.db.history.length === 0;

  const ssDelta = (finalDisplaySS != null && primarySSLine != null && !hasNoHistory) ? finalDisplaySS - primarySSLine : null;
  const ssDeltaText = ssDelta == null ? '—' : `${ssDelta > 0 ? '+' : ''}${ssDelta.toFixed(1)}`;
  const ssDeltaClass = ssDelta == null ? '' : ssDelta >= 0 ? 'delta-plus' : 'delta-minus';

  // ── SS variance band ───────────────────────────────────────────────────────
  const ssStdDev = db.ssStdDev ?? null;
  // Thresholds: ≤7 tight (predictable), 7–14 moderate, >14 volatile
  const ssSpreadColor = ssStdDev == null ? '' : ssStdDev <= 7 ? 'var(--green)' : ssStdDev <= 14 ? 'var(--amber)' : 'var(--red)';
  const ssSpreadLabel = ssStdDev != null ? `±${ssStdDev.toFixed(1)}` : '';
  const ssSpreadTip   = ssStdDev == null ? '' :
    ssStdDev <= 7  ? `SS spread ±${ssStdDev.toFixed(1)} — tight (predictable output, high line confidence)` :
    ssStdDev <= 14 ? `SS spread ±${ssStdDev.toFixed(1)} — moderate variance (treat lean with some caution)` :
                     `SS spread ±${ssStdDev.toFixed(1)} — volatile output (wide range, lean confidence is lower)`;

  const historyPlatform: 'pick6'|'underdog'|'prizepicks'|'betr' =
    currentPlatform === 'pick6' ? 'pick6' :
    currentPlatform === 'underdog' ? 'underdog' :
    currentPlatform === 'prizepicks' ? 'prizepicks' :
    'betr';

  // GLOW-UP 166 (level-up 4): per-book lines for the sensitivity strip —
  // fighter's OWN panels only (opp/R1/body/leg variants would inherit the
  // wrong books, so they don't get one).
  const sensBooks = (stat: 'fp'|'ss'|'td'|'ft'|'ss_r1'|'ss_body'|'ss_leg'): Array<{ tag: string; line: number }> => {
    const defs: Array<[string, number | null | undefined]> =
      // R1 SS carries its OWN per-book lines, so it can have a sensitivity strip
      // like the others. The exclusion above was about opp/body/leg variants
      // inheriting the wrong books; R1 does not — it has PP/UD/DK of its own, and
      // they genuinely differ (De Ridder: PP 11.5, UD 15.5, DK 12.5).
      stat === 'ss_r1' ? [['PP', f.line_pp_ss_r1], ['UD', f.line_ud_ss_r1], ['DK', f.line_dk_ss_r1]]
      // Body/Leg are UD+PP only. Their LINE already followed the selection via
      // platformBodyLegLine — they were only missing the per-book record strip.
      : stat === 'ss_body' ? [['UD', f.line_ud_ss_body], ['PP', f.line_pp_ss_body]]
      : stat === 'ss_leg' ? [['UD', f.line_ud_ss_leg], ['PP', f.line_pp_ss_leg]]
      : stat === 'fp' ? [['P6', f.line_p6], ['UD', f.line_ud], ['PP', f.line_pp], ['BT', f.line_betr]]
      : stat === 'ss' ? [['P6', f.line_p6_ss], ['UD', f.line_ud_ss], ['PP', f.line_pp_ss], ['BT', f.line_betr_ss], ['DK', f.line_dk_ss]]
      : stat === 'td' ? [['P6', f.line_p6_td], ['UD', f.line_ud_td], ['PP', f.line_pp_td], ['BT', f.line_betr_td], ['DK', f.line_dk_td]]
      : [['P6', f.line_p6_ft], ['UD', f.line_ud_ft], ['PP', f.line_pp_ft], ['BT', f.line_betr_ft], ['DK', f.line_dk_ft]];
    return defs
      .filter((d): d is [string, number] => typeof d[1] === 'number' && d[1] > 0)
      .map(([tag, line]) => ({ tag, line }));
  };
  const historyHTML   = buildHistoryBars(fights, h => getFightFantasyValueForPlatform(h, historyPlatform), activeLine, ssLine, tdLine, ftLine, 'fp', null, sensBooks('fp'));
  const ssHistoryHTML = buildHistoryBars(fights, h => h.sigStr, activeLine, ssLine, tdLine, ftLine, 'ss', null, sensBooks('ss'));
  // Was a fixed PP ?? UD ?? DK fallback, so selecting DK still graded R1 history
  // against PrizePicks' line. Follows the selected book now, exactly as SS/TD/FT do.
  const ssR1Line = platformStatLine(f, 'ss_r1');
  // R1 SS is offered by PrizePicks, Underdog, and DK — label the panel by whichever
  // platform(s) actually supplied a line (PP is shown first when several exist).
  const ssR1Sources = [f.line_pp_ss_r1 != null ? 'PP' : null, f.line_ud_ss_r1 != null ? 'UD' : null, f.line_dk_ss_r1 != null ? 'DK' : null].filter(Boolean) as string[];
  const ssR1Badge = ssR1Sources.length === 1 ? `${ssR1Sources[0]}-only` : ssR1Sources.join('+');
  const ssR1Meta = buildPanelMetaChips([
    ...(f.line_pp_ss_r1 != null ? [{ tag: 'PP', raw: f.line_pp_ss_r1 }] : []),
    ...(f.line_ud_ss_r1 != null ? [{ tag: 'UD', raw: f.line_ud_ss_r1 }] : []),
    ...(f.line_dk_ss_r1 != null ? [{ tag: 'DK', raw: f.line_dk_ss_r1 }] : []),
  ]);
  const ssR1HistoryHTML = buildHistoryBars(fights, h => h.sigStrR1, ssR1Line, ssR1Line, null, null, 'ss', null, sensBooks('ss_r1'));
  // Body/Leg sig strikes (Underdog + PrizePicks only). History bars use per-fight body/leg
  // landed from UFCStats (populated after the v50 cache re-fetch). The displayed line
  // follows the active platform — PrizePicks shows the PP line, every other selection
  // (Underdog and platforms without body/leg) defaults to UD-first — so clicking the UD
  // vs PP pill switches the number like the other props do. The meta footer still lists
  // both books so the alternate line stays visible.
  const platformBodyLegLine = (ud: number | null | undefined, pp: number | null | undefined): number | null => {
    const udv = ud ?? null;
    const ppv = pp ?? null;
    return currentPlatform === 'prizepicks' ? (ppv ?? udv) : (udv ?? ppv);
  };
  const bodyLine = platformBodyLegLine(f.line_ud_ss_body, f.line_pp_ss_body);
  const bodySources = [f.line_ud_ss_body != null ? 'UD' : null, f.line_pp_ss_body != null ? 'PP' : null].filter(Boolean) as string[];
  const bodyBadge = bodySources.length === 1 ? `${bodySources[0]}-only` : bodySources.join('+');
  const bodyMeta = buildPanelMetaChips([
    ...(f.line_ud_ss_body != null ? [{ tag: 'UD', raw: f.line_ud_ss_body }] : []),
    ...(f.line_pp_ss_body != null ? [{ tag: 'PP', raw: f.line_pp_ss_body }] : []),
  ]);
  const bodyHistoryHTML = buildHistoryBars(fights, h => h.sigStrBody, bodyLine, bodyLine, null, null, 'ss', null, sensBooks('ss_body'));
  const legLine = platformBodyLegLine(f.line_ud_ss_leg, f.line_pp_ss_leg);
  const legSources = [f.line_ud_ss_leg != null ? 'UD' : null, f.line_pp_ss_leg != null ? 'PP' : null].filter(Boolean) as string[];
  const legBadge = legSources.length === 1 ? `${legSources[0]}-only` : legSources.join('+');
  const legMeta = buildPanelMetaChips([
    ...(f.line_ud_ss_leg != null ? [{ tag: 'UD', raw: f.line_ud_ss_leg }] : []),
    ...(f.line_pp_ss_leg != null ? [{ tag: 'PP', raw: f.line_pp_ss_leg }] : []),
  ]);
  const legHistoryHTML = buildHistoryBars(fights, h => h.sigStrLeg, legLine, legLine, null, null, 'ss', null, sensBooks('ss_leg'));
  const tdHistoryHTML = buildHistoryBars(fights, h => h.td,     activeLine, ssLine, tdLine, ftLine, 'td', null, sensBooks('td'));
  // Knockdowns (PrizePicks-only prop) — panel only renders when a KD line exists.
  const kdLine = f.line_pp_kd ?? null;
  const kdHistoryHTML = buildHistoryBars(fights, h => h.kd, kdLine, null, kdLine, null, 'td');
  const ftHistoryHTML = buildHistoryBars(
    fights,
    h => Number.isFinite(Number(h.timeSecs)) ? Number(h.timeSecs) / 60 : null,
    activeLine,
    ssLine,
    tdLine,
    ftLine,
    'ft',
    null,
    sensBooks('ft')
  );
  const ctrlHistoryHTML = buildHistoryBars(
    fights,
    h => Number.isFinite(Number(h.ctrlSecs)) ? Number(h.ctrlSecs) / 60 : null,
    activeLine,
    ssLine,
    tdLine,
    ftLine,
    'ctrl',
    ctrlLine,
  );
  const oppCompareFpLine   = oppFpLine;
  const oppCompareSsLine   = oppSsLine;
  const oppCompareTdLine   = oppTdLine;
  const oppCompareCtrlLine = platformStatLine(oppEntry, 'ctrl');
  const oppCompareSsR1Line = oppEntry?.line_pp_ss_r1 ?? oppEntry?.line_ud_ss_r1 ?? oppEntry?.line_dk_ss_r1 ?? null;
  const oppSsR1Sources = [oppEntry?.line_pp_ss_r1 != null ? 'PP' : null, oppEntry?.line_ud_ss_r1 != null ? 'UD' : null, oppEntry?.line_dk_ss_r1 != null ? 'DK' : null].filter(Boolean) as string[];
  const oppSsR1Badge = oppSsR1Sources.length === 1 ? `${oppSsR1Sources[0]}-only` : oppSsR1Sources.join('+');
  const oppFPHistory   = buildHistoryBars(oppFights, h => getFightFantasyValueForPlatform(h, historyPlatform), oppCompareFpLine, oppCompareSsLine, oppCompareTdLine, null, 'fp');
  const oppSSHistory   = buildHistoryBars(oppFights, h => h.sigStr, oppCompareFpLine, oppCompareSsLine, oppCompareTdLine, null, 'ss');
  const oppSSR1History = buildHistoryBars(oppFights, h => h.sigStrR1, oppCompareSsR1Line, oppCompareSsR1Line, null, null, 'ss');
  // Opp body/leg "scored vs" charts — what this fighter's past opponents landed to
  // body/leg, vs the upcoming opponent's body/leg line (active-platform aware, same as
  // the self panels above). Mirrors opp R1 SS.
  const oppCompareBodyLine = platformBodyLegLine(oppEntry?.line_ud_ss_body, oppEntry?.line_pp_ss_body);
  const oppCompareLegLine  = platformBodyLegLine(oppEntry?.line_ud_ss_leg,  oppEntry?.line_pp_ss_leg);
  const oppBodySources = [oppEntry?.line_ud_ss_body != null ? 'UD' : null, oppEntry?.line_pp_ss_body != null ? 'PP' : null].filter(Boolean) as string[];
  const oppLegSources  = [oppEntry?.line_ud_ss_leg  != null ? 'UD' : null, oppEntry?.line_pp_ss_leg  != null ? 'PP' : null].filter(Boolean) as string[];
  const oppBodyBadge = oppBodySources.length === 1 ? `${oppBodySources[0]}-only` : oppBodySources.join('+');
  const oppLegBadge  = oppLegSources.length === 1 ? `${oppLegSources[0]}-only` : oppLegSources.join('+');
  const oppBodyHistory = buildHistoryBars(oppFights, h => h.sigStrBody, oppCompareBodyLine, oppCompareBodyLine, null, null, 'ss');
  const oppLegHistory  = buildHistoryBars(oppFights, h => h.sigStrLeg,  oppCompareLegLine,  oppCompareLegLine,  null, null, 'ss');
  const oppTDHistory   = buildHistoryBars(oppFights, h => h.td,     oppCompareFpLine, oppCompareSsLine, oppCompareTdLine, null, 'td');
  const oppCompareKdLine = oppEntry?.line_pp_kd ?? null;
  const oppKDHistory   = buildHistoryBars(oppFights, h => h.kd, oppCompareKdLine, null, oppCompareKdLine, null, 'td');
  const oppCTRLHistory = buildHistoryBars(
    oppFights,
    h => Number.isFinite(Number(h.ctrlSecs)) ? Number(h.ctrlSecs) / 60 : null,
    oppCompareFpLine,
    oppCompareSsLine,
    oppCompareTdLine,
    null,
    'ctrl',
    oppCompareCtrlLine,
  );

  const leanReasons = lean.reasons || [];
  const proReasons = leanReasons.filter((r) => r.icon === 'pos');
  const riskReasons = leanReasons.filter((r) => r.icon === 'neg');
  const neutralReasons = leanReasons.filter((r) => r.icon !== 'pos' && r.icon !== 'neg');

  // Columns resolved against the LEAN, not the raw icon. The icon is
  // directional ('pos' = pushes the number up), so labelling a column "Pro"
  // straight off it listed the reasons arguing AGAINST every UNDER lean — the
  // same inversion GLOW-UP 184 fixed on the factor chips. Falls back to the raw
  // split for push/no-lean, where "for" and "against" have no meaning.
  const directional = lean.lean === 'over' || lean.lean === 'under';
  const forReasons     = directional ? leanReasons.filter(r => factorPolarity(r.icon, lean.lean) === 'sup') : proReasons;
  const againstReasons = directional ? leanReasons.filter(r => factorPolarity(r.icon, lean.lean) === 'opp') : riskReasons;
  const contextReasons = directional ? leanReasons.filter(r => factorPolarity(r.icon, lean.lean) === 'neu') : neutralReasons;

  // "Why this lean" — top 3 drivers in the direction of the lean.
  // Position-in-array is the implicit ranking — each producer pushes its
  // strongest reason first.
  // Only for a real direction. The header prints "UNDER" for anything that
  // isn't "over", so on a push/no-lean this block would read "Why UNDER" over a
  // list of UP reasons — it stayed hidden before and must keep doing so.
  const topDrivers = directional ? forReasons.slice(0, 3) : [];
  const topDriversHTML = topDrivers.length > 0 ? `
    <div class="top-drivers ${lean.lean}">
      <div class="top-drivers-head">Why ${lean.lean === 'over' ? 'OVER' : 'UNDER'} · Top ${topDrivers.length} driver${topDrivers.length > 1 ? 's' : ''}</div>
      ${topDrivers.map((r, i) => `<div class="top-driver"><span class="top-driver-rank">${i + 1}</span><span class="top-driver-text">${r.text}</span></div>`).join('')}
    </div>` : '';

  const reasonRow = (r: LeanReason) => `<div class="lean-point">
    <span class="lean-point-icon ${r.icon==='pos'?'pos':r.icon==='neg'?'neg':''}">${r.icon==='pos'?'↑':r.icon==='neg'?'↓':'→'}</span>
    <span>${r.text}</span>
  </div>`;

  const leanDirWord = lean.lean === 'over' ? 'OVER' : lean.lean === 'under' ? 'UNDER' : '';
  const groupsInner = `
    <div class="lean-reason-groups">
      <div class="lean-reason-col pro">
        <div class="lean-reason-head">${directional ? `Supports ${leanDirWord}` : 'Pro'}</div>
        ${forReasons.length ? forReasons.map(reasonRow).join('') : '<div class="lean-point muted"><span class="lean-point-icon">·</span><span>No strong supporting edge</span></div>'}
      </div>
      <div class="lean-reason-col risk">
        <div class="lean-reason-head">${directional ? 'Argues against' : 'Risk'}</div>
        ${againstReasons.length ? againstReasons.map(reasonRow).join('') : '<div class="lean-point muted"><span class="lean-point-icon">·</span><span>No major counter-signal</span></div>'}
      </div>
      ${contextReasons.length ? `<div class="lean-reason-col neutral"><div class="lean-reason-head">Context</div>${contextReasons.slice(0, 2).map(reasonRow).join('')}</div>` : ''}
    </div>`;

  // GLOW-UP 186: fold the columns away, matching the stat panels. The top-3
  // drivers stay visible above — those are the headline, not the detail.
  const groupedReasonsHTML = leanReasons.length >= 2
    ? `<details class="lean-prose"><summary>Full rationale · ${leanReasons.length} points${directional ? ` (${forReasons.length} for / ${againstReasons.length} against)` : ''}</summary>${groupsInner}</details>`
    : groupsInner;

  // Chip summary — same ✓/✗ language as the SS/TD/FT panels.
  const fpFactors = pickDistinctFactors(leanReasons, 5);
  const fpFactorChips = fpFactors.length >= 2
    ? `<div class="lean-factors">${fpFactors.map(r => factorChipHtml(r, lean.lean, 'lean-factor')).join('')}</div>`
    : '';

  function panelConfidence(samples: number, line: number | null): { label: 'High'|'Med'|'Low'; cls: 'high'|'med'|'low' } {
    if (samples >= 7 && line != null) return { label: 'High', cls: 'high' };
    if (samples >= 4) return { label: 'Med', cls: 'med' };
    return { label: 'Low', cls: 'low' };
  }

  function panelBadge(conf: { label: 'High'|'Med'|'Low'; cls: 'high'|'med'|'low' }): string {
    return ` <span class="panel-confidence ${conf.cls}">${conf.label}</span>`;
  }

  const fpConf     = panelConfidence(fights.length,    activeLine);
  const ssConf     = panelConfidence(fights.length,    ssLine);
  const tdConf     = panelConfidence(fights.length,    tdLine);
  const ftConf     = panelConfidence(fights.length,    ftLine);
  const ctrlConf   = panelConfidence(fights.length,    ctrlLine);
  const oppFpConf  = panelConfidence(oppFights.length, oppCompareFpLine);
  const oppSsConf  = panelConfidence(oppFights.length, oppCompareSsLine);
  const oppTdConf  = panelConfidence(oppFights.length, oppCompareTdLine);
  const oppCtrlConf= panelConfidence(oppFights.length, oppCompareCtrlLine);
  const leanConfBadge = panelBadge(lean.conf >= 72 && leanReasons.length >= 5 ? { label: 'High', cls: 'high' } : lean.conf >= 58 ? { label: 'Med', cls: 'med' } : { label: 'Low', cls: 'low' });

  const fpFloor    = db.fpFloor    != null ? db.fpFloor.toFixed(1)    : '...';
  const fpCeiling  = db.fpCeiling  != null ? db.fpCeiling.toFixed(1)  : '...';
  const fpConsistency = db.fpConsistency ?? null;
  const consistencyClass = fpConsistency != null ? (fpConsistency >= 70 ? 'consistency-high' : fpConsistency >= 45 ? 'consistency-mid' : 'consistency-low') : '';
  
  // #18: Peer Comparison Percentiles
  const peerPercentiles = calcPeerPercentileRanking(allFighters, f.name);
  const archetypeProfile = learnArchetypeProfile(f.name, db, oppEntry?.db || null, f.moneyline ?? null);
  const archetypeFullName = formatCareerArchetypeLabel(archetypeProfile.careerLabel);
  const archetypeDesc = describeCareerArchetype(archetypeProfile.careerLabel);
  const archetypeTitle = `${archetypeFullName} — ${archetypeDesc}${archetypeProfile.matchupAlert !== 'none' ? ` · Matchup alert: ${formatMatchupAlertLabel(archetypeProfile.matchupAlert)}` : ''}`;
  const archetypeBadgeHtml = `<span class="style-matchup-chip style-chip-default" title="${archetypeTitle.replace(/"/g, '&quot;')}" style="margin-left:6px;font-size:9px;padding:1px 6px">${shortCareerArchetypeLabel(archetypeProfile.careerLabel)}</span>`;
  const archetypeAlertHtml = archetypeProfile.matchupAlert !== 'none'
    ? `<span class="style-matchup-chip" title="${formatMatchupAlertLabel(archetypeProfile.matchupAlert)}" style="margin-left:4px;font-size:9px;padding:1px 6px;background:rgba(255,100,100,0.12);border-color:rgba(255,100,100,0.32);color:#ff8f8f">${formatMatchupAlertLabel(archetypeProfile.matchupAlert)}</span>`
    : '';
  const avgFPPercentileLabel = peerPercentiles.avgFPPercentile >= 75 ? '🔴' : peerPercentiles.avgFPPercentile >= 50 ? '🟡' : '🟢';
  
  const streakEmoji = db.streak?.type === 'hot' ? ' 🔥' : db.streak?.type === 'cold' ? ' ❄️' : '';

  // ── Sharp line movement detection ─────────────────────────────────────────
  // Flag any stat/platform where current line has moved ≥2 pts from opening
  const SHARP_THRESHOLD = 1.0;
  type MoveEntry = { platLabel: string; statLabel: string; delta: number; opening: number; current: number };
  const sharpMoves: MoveEntry[] = [];
  const _allStatLines: Array<[string, string, number | null | undefined]> =
    LINE_STAT_ACCESSORS.map(([plat, stat, get]) => [plat, stat, get(f)]);
  for (const [plat, stat, current] of _allStatLines) {
    if (current == null) continue;
    const _smKey = openingLineKey(plat, stat, f.name);
    const opening = _openingLines.get(_smKey);
    if (opening == null) continue;
    const openDeltaRaw = parseFloat((current - opening).toFixed(1));
    const openDelta = sanitizeDelta(stat, openDeltaRaw) ?? 0;
    if (Math.abs(openDelta) >= SHARP_THRESHOLD) {
      sharpMoves.push({ platLabel: statPlatLabel(plat), statLabel: statDisplayLabel(stat), delta: openDelta, opening, current });
    }
  }
  sharpMoves.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  // Deduplicate: if same stat moved on multiple books, keep largest move only
  const seenStat = new Set<string>();
  const dedupedMoves = sharpMoves.filter(m => { if (seenStat.has(m.statLabel)) return false; seenStat.add(m.statLabel); return true; });

  // Steam detection: same stat moved >=2pts across 2+ platforms
  const STEAM_THRESHOLD = 2.0;
  const statMoveCounts = new Map<string, MoveEntry[]>();
  for (const m of sharpMoves) {
    const arr = statMoveCounts.get(m.statLabel) || [];
    arr.push(m);
    statMoveCounts.set(m.statLabel, arr);
  }
  const steamStats: string[] = [];
  for (const [stat, moves] of statMoveCounts) {
    if (moves.length >= 2 && moves.some(m => Math.abs(m.delta) >= STEAM_THRESHOLD)) {
      steamStats.push(stat);
    }
  }
  const isSteam = steamStats.length > 0;

  // Reverse steam: line dropped then recovered (V-shape in history)
  const reverseSteamStats: string[] = [];
  for (const stat of ['fp', 'ss', 'td']) {
    const history = getLineHistoryForFighter(f.name, stat);
    if (history.length < 3) continue;
    for (const plat of ['p6', 'ud', 'pp', 'betr', 'dk']) {
      const vals = history.map(h => h.v[plat]).filter((v): v is number => v != null);
      if (vals.length < 3) continue;
      const first = vals[0], min = Math.min(...vals), last = vals[vals.length - 1];
      if (first - min >= 1.0 && last - min >= 1.0 && Math.abs(last - first) < 0.5) {
        reverseSteamStats.push(stat.toUpperCase());
        break;
      }
    }
  }
  const isReverseSteam = reverseSteamStats.length > 0;

  const sharpBadgeHtml = (() => {
    if (!dedupedMoves.length && !isReverseSteam) return '';
    const parts: string[] = [];
    if (isSteam) {
      const dir = dedupedMoves[0]?.delta > 0 ? '📈' : '📉';
      parts.push(`<div class="sharp-move-badge steam-badge" title="Steam move (sharp money signal): ${steamStats.join(', ')} ${dedupedMoves[0]?.delta > 0 ? 'rising' : 'dropping'} ≥${STEAM_THRESHOLD}pts across multiple books — strong market move worth respecting">${dir} STEAM ${steamStats.join('/')}</div>`);
    }
    if (isReverseSteam) {
      parts.push(`<div class="sharp-move-badge reverse-steam-badge" title="Reverse steam: ${reverseSteamStats.join(', ')} dropped then recovered">↩ REVERSE ${reverseSteamStats.join('/')}</div>`);
    }
    if (dedupedMoves.length && !isSteam) {
      const top = dedupedMoves[0];
      const arrow = top.delta > 0 ? '📈' : '📉';
      const sign  = top.delta > 0 ? '+' : '';
      const extra = dedupedMoves.length > 1 ? ` <span style="opacity:0.6">+${dedupedMoves.length - 1} more</span>` : '';
      const tipLines = dedupedMoves.map(m => `${m.platLabel} ${m.statLabel}: ${m.opening} → ${m.current} (${m.delta > 0 ? '+' : ''}${m.delta})`).join(' · ');
      parts.push(`<div class="sharp-move-badge" title="Line movement since opening: ${tipLines}">${arrow} ${top.statLabel} ${sign}${top.delta} <span class="sharp-move-book">${top.platLabel}</span>${extra}</div>`);
    }
    return parts.join('');
  })();
  const weightedAvg = db.avgFP_weighted ?? null;
  const platformAvgFP = activePlatformAvgFP(db);
  const weightedDiff = (weightedAvg != null && platformAvgFP != null) ? (weightedAvg - platformAvgFP) : null;
  const weightedArrow = weightedDiff == null ? '' : weightedDiff > 3 ? ' ↑' : weightedDiff < -3 ? ' ↓' : '';
  const mlAdjFP = calcMLAdjustedFP(db.history || [], f.moneyline ?? null);
  const mlAdjShift = (mlAdjFP != null && platformAvgFP != null) ? mlAdjFP - platformAvgFP : null;

  // ── Opponent-adjusted FP projection ──────────────────────────────────────────
  const oppFPAllowedSamples = (oppEntry?.db?.oppHistory ?? [])
    .map(h => h.fp)
    .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
  const oppAvgFPAllowed = oppFPAllowedSamples.length >= 3
    ? parseFloat((oppFPAllowedSamples.reduce((s, v) => s + v, 0) / oppFPAllowedSamples.length).toFixed(1))
    : null;
  const baseAvgFP = mlAdjFP ?? platformAvgFP ?? null;
  const projFP = (baseAvgFP != null && oppAvgFPAllowed != null)
    ? parseFloat(((baseAvgFP + oppAvgFPAllowed) / 2).toFixed(1))
    : null;
  // Round-normalized display values (applied after mlAdj / proj calculations)
  const normDisplayFP = roundNormFactor !== 1.0
    ? parseFloat(((projFP ?? mlAdjFP ?? platformAvgFP ?? 0) * roundNormFactor).toFixed(1))
    : null;
  // normDisplaySS and normDisplayTD computed after projSS/avgTD are available (below)

  const _tw = trendWindow === 0 ? 9999 : trendWindow; // 9999 → all vals "recent" → delta=0 → flat → no chip
  const fpTrend  = calcStatTrend(fights, h => getFightFantasyValueForPlatform(h, historyPlatform), 5, _tw);
  const ssTrend  = calcStatTrend(fights, h => h.sigStr ?? null, 4, _tw);
  const tdTrend  = calcStatTrend(fights, h => h.td   ?? null, 0.5, _tw);
  const _twLabel = trendWindow === 0 ? 'Career' : `L${trendWindow}`;

  function trendChip(t: StatTrend, tooltip: string): string {
    if (t.direction === null || t.direction === 'flat' || t.delta == null) return '';
    const sign = t.delta > 0 ? '+' : '';
    return `<span class="stat-trend-chip ${t.direction}" title="${tooltip}">${t.direction === 'up' ? '↑' : '↓'} ${_twLabel} ${sign}${t.delta}</span>`;
  }
  // Removed hitProb, badgeText, badgeCls, spikeEvent UI, and all oddsBadge/fantasy_over_odds/fantasy_under_odds logic
  const hitProb = null;
  const spikeEvent = null;

  interface SSAnalysis {
    name: string;
    currentLine: number | null;
    currentLineSource: string;
    currentLineText: string;
    avgText: string;
    vsLineText: string;
    matchupNotes: string;
    verdictText: string;
    confidenceText: string;
    edge: number;
    confidence: number;
    available: boolean;
  }

  function pickStatLine(entry: AnalyzerFighter, platform: 'p6'|'ud'|'pp'|'dk'|'betr', stat: 'ss'|'td'|'ctrl'): number | null | undefined {
    if (platform === 'p6')   return stat === 'ss' ? entry.line_p6_ss   : stat === 'td' ? entry.line_p6_td   : entry.line_p6_ctrl;
    if (platform === 'ud')   return stat === 'ss' ? entry.line_ud_ss   : stat === 'td' ? entry.line_ud_td   : entry.line_ud_ctrl;
    if (platform === 'pp')   return stat === 'ss' ? entry.line_pp_ss   : stat === 'td' ? entry.line_pp_td   : entry.line_pp_ctrl;
    if (platform === 'dk')   return stat === 'ss' ? entry.line_dk_ss   : stat === 'td' ? entry.line_dk_td   : entry.line_dk_ctrl;
    return stat === 'ss' ? entry.line_betr_ss : stat === 'td' ? entry.line_betr_td : entry.line_betr_ctrl;
  }

  function selectedBookLine(entry: AnalyzerFighter | null, stat: 'ss' | 'td' | 'ctrl'): number | null {
    if (!entry) return null;
    if (currentPlatform === 'pick6') return pickStatLine(entry, 'p6', stat) ?? null;
    if (currentPlatform === 'underdog') return pickStatLine(entry, 'ud', stat) ?? null;
    if (currentPlatform === 'prizepicks') return pickStatLine(entry, 'pp', stat) ?? null;
    if (currentPlatform === 'draftkings_sportsbook') return pickStatLine(entry, 'dk', stat) ?? null;
    return pickStatLine(entry, 'betr', stat) ?? null;
  }

  function anyBookLine(entry: AnalyzerFighter | null, stat: 'ss' | 'td' | 'ctrl'): number | null {
    if (!entry) return null;
    return pickStatLine(entry, 'p6', stat)
        ?? pickStatLine(entry, 'ud', stat)
        ?? pickStatLine(entry, 'pp', stat)
        ?? pickStatLine(entry, 'dk', stat)
        ?? pickStatLine(entry, 'betr', stat)
        ?? null;
  }

  function formatLineSource(entry: AnalyzerFighter | null, stat: 'ss' | 'td' | 'ctrl', line: number | null): string {
    if (!entry || line == null) return 'none';
    if (pickStatLine(entry, 'p6',   stat) === line) return 'P6';
    if (pickStatLine(entry, 'ud',   stat) === line) return 'UD';
    if (pickStatLine(entry, 'pp',   stat) === line) return 'PP';
    if (pickStatLine(entry, 'dk',   stat) === line) return 'DK';
    if (pickStatLine(entry, 'betr', stat) === line) return 'BT';
    return 'unknown';
  }

  function resolveAnalysisLine(entry: AnalyzerFighter | null, stat: 'ss' | 'td' | 'ctrl'): { line: number | null; source: string } {
    const selected = selectedBookLine(entry, stat);
    if (selected != null) return { line: selected, source: currentPlatform.toUpperCase() };
    const fallback = anyBookLine(entry, stat);
    if (fallback != null) return { line: fallback, source: `fallback ${formatLineSource(entry, stat, fallback)}` };
    return { line: null, source: 'missing' };
  }

  const fighterSsLineResolved = resolveAnalysisLine(f, 'ss');
  const opponentSsLineResolved = resolveAnalysisLine(oppEntry, 'ss');

  function buildSSAnalysis(
    fighterName: string,
    fighterDb: FighterDB | null,
    currentSsLine: number | null,
    lineSource: string,
    opponentDb: FighterDB | null,
  ): SSAnalysis {
    if (!fighterDb?.loaded || currentSsLine == null || !Number.isFinite(currentSsLine)) {
      return {
        name: fighterName,
        currentLine: currentSsLine,
        currentLineSource: lineSource,
        currentLineText: currentSsLine != null ? `${currentSsLine.toFixed(1)} (${lineSource})` : 'Unavailable',
        avgText: 'Unavailable',
        vsLineText: 'Insufficient line/history data',
        matchupNotes: 'Needs both current SS line and fighter history.',
        verdictText: 'No bet (insufficient data)',
        confidenceText: '0',
        edge: 0,
        confidence: 0,
        available: false,
      };
    }

    const ssSamples = (fighterDb.history || [])
      .map((h) => h.sigStr)
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
    if (!ssSamples.length) {
      return {
        name: fighterName,
        currentLine: currentSsLine,
        currentLineSource: lineSource,
        currentLineText: `${currentSsLine.toFixed(1)} (${lineSource})`,
        avgText: 'Unavailable',
        vsLineText: 'No historical SS samples',
        matchupNotes: 'Unable to compute historical over/under hit profile.',
        verdictText: 'No bet (insufficient data)',
        confidenceText: '0',
        edge: 0,
        confidence: 0,
        available: false,
      };
    }

    const avg = ssSamples.reduce((s, v) => s + v, 0) / ssSamples.length;
    const overCount = ssSamples.filter((v) => v > currentSsLine).length;
    const underCount = ssSamples.length - overCount;
    const overRate = overCount / ssSamples.length;

    let matchupAdj = 0;
    const notes: string[] = [];
    if (lineSource.startsWith('fallback')) {
      notes.push(`Selected-book SS line missing; using ${lineSource}.`);
    }
    if (opponentDb?.loaded) {
      const oppStrDef = opponentDb.strDef;
      const oppSapm = opponentDb.sapm;
      const oppTdDef = opponentDb.tdDef;
      const oppAvgTd = opponentDb.avgTD;

      if (oppStrDef != null) {
        if (oppStrDef >= 60) { matchupAdj -= 4; notes.push(`Opponent striking defense ${oppStrDef}% suppresses clean SS volume.`); }
        else if (oppStrDef <= 45) { matchupAdj += 4; notes.push(`Opponent striking defense ${oppStrDef}% is exploitable for SS accumulation.`); }
      }
      if (oppSapm != null) {
        if (oppSapm >= 4.7) { matchupAdj += 2.5; notes.push(`Opponent absorbs ${oppSapm.toFixed(1)} sig strikes/min, pace supports overs.`); }
        else if (oppSapm <= 3.0) { matchupAdj -= 2.5; notes.push(`Opponent absorbs only ${oppSapm.toFixed(1)} sig strikes/min, downside for SS output.`); }
      }
      if (oppAvgTd != null && oppAvgTd >= 2.2) {
        matchupAdj -= 1.5;
        notes.push(`Opponent wrestling pressure (${oppAvgTd.toFixed(1)} TD avg) can suppress striking exchanges.`);
      }
      if (oppTdDef != null && oppTdDef < 50 && (fighterDb.avgTD ?? 0) > 1.3) {
        matchupAdj -= 1;
        notes.push('Fighter may choose grappling routes vs weak TD defense, reducing SS ceiling.');
      }
    } else {
      notes.push('Opponent profile not loaded; matchup adjustment limited to fighter history baseline.');
    }

    const projection = avg + matchupAdj;
    const verdict = projection >= currentSsLine ? 'OVER' : 'UNDER';
    const confidence = Math.max(
      45,
      Math.min(
        93,
        Math.round(
          52
          + Math.min(18, Math.abs(projection - currentSsLine) * 1.4)
          + Math.min(12, Math.abs(overRate - 0.5) * 100 * 0.24)
          + Math.min(8, ssSamples.length * 0.9)
        )
      )
    );

    const vsLineText = `${overCount}/${ssSamples.length} over (${(overRate * 100).toFixed(0)}%) · ${underCount}/${ssSamples.length} under`;
    const matchupNotes = notes.length ? notes.join(' ') : 'Neutral style/pace indicators.';

    return {
      name: fighterName,
      currentLine: currentSsLine,
      currentLineSource: lineSource,
      currentLineText: `${currentSsLine.toFixed(1)} (${lineSource})`,
      avgText: avg.toFixed(1),
      vsLineText,
      matchupNotes,
      verdictText: `${verdict} ${currentSsLine.toFixed(1)} (proj ${projection.toFixed(1)})`,
      confidenceText: String(confidence),
      edge: projection - currentSsLine,
      confidence,
      available: true,
    };
  }

  function buildKeyReasons(a: SSAnalysis, b: SSAnalysis): string {
    const reasons: string[] = [];
    if (a.available) reasons.push(`${a.name}: edge ${a.edge >= 0 ? '+' : ''}${a.edge.toFixed(1)} vs line`);
    if (b.available) reasons.push(`${b.name}: edge ${b.edge >= 0 ? '+' : ''}${b.edge.toFixed(1)} vs line`);
    if (!reasons.length) reasons.push('Insufficient SS line/history data for one or both sides');
    return reasons.join(' | ');
  }

  function validateSSOutput(a: SSAnalysis, b: SSAnalysis, keyReasons: string): boolean {
    const check1 = a.currentLine != null && b.currentLine != null;
    const check2 = a.avgText !== 'Unavailable' && b.avgText !== 'Unavailable' && a.vsLineText.length > 0 && b.vsLineText.length > 0;
    const check3 = (a.verdictText.includes('OVER') || a.verdictText.includes('UNDER') || a.verdictText.includes('No bet'))
      && (b.verdictText.includes('OVER') || b.verdictText.includes('UNDER') || b.verdictText.includes('No bet'));
    const check4 = keyReasons.length > 0;
    return check1 && check2 && check3 && check4;
  }

  let fighterSsAnalysis = buildSSAnalysis(f.name, db, fighterSsLineResolved.line, fighterSsLineResolved.source, oppEntry?.db || null);
  let opponentSsAnalysis = buildSSAnalysis(oppEntry?.name || (f.opponent || 'Opponent'), oppEntry?.db || null, opponentSsLineResolved.line, opponentSsLineResolved.source, db);

  // Self-correct once if selected-book line is missing by forcing best available line on both sides.
  let keyReasons = buildKeyReasons(fighterSsAnalysis, opponentSsAnalysis);
  if (!validateSSOutput(fighterSsAnalysis, opponentSsAnalysis, keyReasons)) {
    const fighterFallbackLine = anyBookLine(f, 'ss');
    const opponentFallbackLine = anyBookLine(oppEntry, 'ss');
    fighterSsAnalysis = buildSSAnalysis(f.name, db, fighterFallbackLine, formatLineSource(f, 'ss', fighterFallbackLine), oppEntry?.db || null);
    opponentSsAnalysis = buildSSAnalysis(oppEntry?.name || (f.opponent || 'Opponent'), oppEntry?.db || null, opponentFallbackLine, formatLineSource(oppEntry, 'ss', opponentFallbackLine), db);
    keyReasons = buildKeyReasons(fighterSsAnalysis, opponentSsAnalysis);
  }

  const strongest = Math.abs(fighterSsAnalysis.edge) >= Math.abs(opponentSsAnalysis.edge)
    ? fighterSsAnalysis
    : opponentSsAnalysis;
  const volatilityFlags: string[] = [];
  if ((db.fpStdDev ?? 0) > 22) volatilityFlags.push(`${f.name} high variance profile`);
  if ((oppEntry?.db?.fpStdDev ?? 0) > 22) volatilityFlags.push(`${oppEntry?.name || 'Opponent'} high variance profile`);
  if (!fighterSsAnalysis.available || !opponentSsAnalysis.available) volatilityFlags.push('incomplete opponent/line data');
  const recommendedLeans = [fighterSsAnalysis, opponentSsAnalysis]
    .filter((x) => x.available && x.confidence >= 62)
    .sort((a, b) => b.confidence - a.confidence)
    .slice(0, 2)
    .map((x) => `${x.name}: ${x.verdictText} (${x.confidence}% conf)`);

  // ── CTRL Matchup Analyzer ───────────────────────────────────────────────
  // Parallel to the SS analyzer — produces the same prose-style verdict for
  // control-time props. Lines default to Pick6 since that's the primary book.
  interface CTRLAnalysis {
    name: string;
    currentLine: number | null;
    currentLineText: string;
    avgText: string;
    vsLineText: string;
    matchupNotes: string;
    verdictText: string;
    confidenceText: string;
    edge: number;
    confidence: number;
    available: boolean;
  }

  function buildCTRLAnalysis(
    fighterName: string,
    fighterDb: FighterDB | null,
    currentCtrlLine: number | null,
    lineSource: string,
    opponentDb: FighterDB | null,
  ): CTRLAnalysis {
    const lineText = currentCtrlLine != null ? `${formatMinutesAsClock(currentCtrlLine)} (${lineSource})` : 'Unavailable';
    if (!fighterDb?.loaded || currentCtrlLine == null || !Number.isFinite(currentCtrlLine)) {
      return {
        name: fighterName, currentLine: currentCtrlLine, currentLineText: lineText,
        avgText: 'Unavailable', vsLineText: 'Insufficient line/history data',
        matchupNotes: 'Needs both current CTRL line and fighter history.',
        verdictText: 'No bet (insufficient data)', confidenceText: '0',
        edge: 0, confidence: 0, available: false,
      };
    }
    const samples = (fighterDb.history || [])
      .map(h => h.ctrlSecs)
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v))
      .map(s => s / 60);
    if (samples.length < 2) {
      return {
        name: fighterName, currentLine: currentCtrlLine, currentLineText: lineText,
        avgText: 'Unavailable', vsLineText: 'No historical control samples',
        matchupNotes: 'Unable to compute historical over/under hit profile.',
        verdictText: 'No bet (insufficient data)', confidenceText: '0',
        edge: 0, confidence: 0, available: false,
      };
    }
    const avg = samples.reduce((s, v) => s + v, 0) / samples.length;
    const overCount = samples.filter(v => v > currentCtrlLine).length;
    const underCount = samples.length - overCount;
    const overRate = overCount / samples.length;

    let matchupAdj = 0;
    const notes: string[] = [];
    if (lineSource.startsWith('fallback')) notes.push(`Selected-book CTRL line missing; using ${lineSource}.`);
    if (fighterDb.style === 'grappler') { matchupAdj += 0.5; notes.push('Grappler profile supports sustained control.'); }
    else if (fighterDb.style === 'striker') { matchupAdj -= 0.5; notes.push('Striker profile rarely posts large control windows.'); }
    const tdAvg = fighterDb.avgTDperFight ?? fighterDb.avgTD ?? null;
    if (tdAvg != null) {
      if (tdAvg >= 2.5) { matchupAdj += 0.8; notes.push(`High TD volume (${tdAvg.toFixed(1)}/fight) fuels control upside.`); }
      else if (tdAvg >= 1.2) { matchupAdj += 0.3; notes.push(`Moderate TD volume (${tdAvg.toFixed(1)}/fight).`); }
      else if (tdAvg < 0.4) { matchupAdj -= 0.6; notes.push(`Low TD volume (${tdAvg.toFixed(1)}/fight) caps control ceiling.`); }
    }
    if (opponentDb?.loaded && opponentDb.tdDef != null) {
      if (opponentDb.tdDef >= 75) { matchupAdj -= 0.9; notes.push(`Opponent TD defense ${opponentDb.tdDef}% suppresses ground control.`); }
      else if (opponentDb.tdDef <= 45) { matchupAdj += 0.6; notes.push(`Opponent TD defense only ${opponentDb.tdDef}% — favorable for control accumulation.`); }
    }
    const oppTD = opponentDb?.avgTDperFight ?? opponentDb?.avgTD ?? null;
    if (opponentDb?.loaded && oppTD != null && oppTD >= 2.2) {
      matchupAdj -= 0.4;
      notes.push(`Opponent also wrestles (${oppTD.toFixed(1)} TD/fight) — fighter may lose scramble battles.`);
    }
    if (!opponentDb?.loaded) notes.push('Opponent profile not loaded; matchup adjustment limited to fighter history baseline.');

    const projection = avg + matchupAdj;
    const verdict = projection >= currentCtrlLine ? 'OVER' : 'UNDER';
    const confidence = Math.max(
      45,
      Math.min(
        92,
        Math.round(
          52
          + Math.min(18, Math.abs(projection - currentCtrlLine) * 6)
          + Math.min(12, Math.abs(overRate - 0.5) * 100 * 0.24)
          + Math.min(8, samples.length * 0.9)
        )
      )
    );
    return {
      name: fighterName,
      currentLine: currentCtrlLine,
      currentLineText: lineText,
      avgText: formatMinutesAsClock(avg),
      vsLineText: `${overCount}/${samples.length} over (${(overRate * 100).toFixed(0)}%) · ${underCount}/${samples.length} under`,
      matchupNotes: notes.length ? notes.join(' ') : 'Neutral style/pace indicators.',
      verdictText: `${verdict} ${formatMinutesAsClock(currentCtrlLine)} (proj ${formatMinutesAsClock(projection)})`,
      confidenceText: String(confidence),
      edge: projection - currentCtrlLine,
      confidence,
      available: true,
    };
  }

  const fighterCtrlLineResolved = resolveAnalysisLine(f, 'ctrl');
  const opponentCtrlLineResolved = resolveAnalysisLine(oppEntry, 'ctrl');
  const fighterCtrlAnalysis = buildCTRLAnalysis(f.name, db, fighterCtrlLineResolved.line, fighterCtrlLineResolved.source, oppEntry?.db || null);
  const opponentCtrlAnalysis = buildCTRLAnalysis(oppEntry?.name || (f.opponent || 'Opponent'), oppEntry?.db || null, opponentCtrlLineResolved.line, opponentCtrlLineResolved.source, db);
  const ctrlStrongest = Math.abs(fighterCtrlAnalysis.edge) >= Math.abs(opponentCtrlAnalysis.edge) ? fighterCtrlAnalysis : opponentCtrlAnalysis;
  const ctrlKeyReasons = [
    fighterCtrlAnalysis.available ? `${fighterCtrlAnalysis.name}: edge ${fighterCtrlAnalysis.edge >= 0 ? '+' : ''}${fighterCtrlAnalysis.edge.toFixed(1)}m vs line` : null,
    opponentCtrlAnalysis.available ? `${opponentCtrlAnalysis.name}: edge ${opponentCtrlAnalysis.edge >= 0 ? '+' : ''}${opponentCtrlAnalysis.edge.toFixed(1)}m vs line` : null,
  ].filter(Boolean).join(' | ') || 'Insufficient CTRL line/history data for one or both sides';
  const ctrlRecommendedLeans = [fighterCtrlAnalysis, opponentCtrlAnalysis]
    .filter(x => x.available && x.confidence >= 62)
    .sort((a, b) => b.confidence - a.confidence)
    .slice(0, 2)
    .map(x => `${x.name}: ${x.verdictText} (${x.confidence}% conf)`);

  const maVal = (t: string): string => /^(unavailable|insufficient|needs both|no |none)/i.test(t) ? `<span class="ma-value-dim">${t}</span>` : t;
  const maVerdictChip = (text: string): string => {
    const cls = /\bOVER\b/i.test(text) ? 'over' : /\bUNDER\b/i.test(text) ? 'under' : 'none';
    return `<span class="ma-verdict-chip ${cls}">${text}</span>`;
  };
  const maConfBar = (conf: number): string => {
    const n = Math.max(0, Math.min(100, Math.round(conf)));
    const hue = n >= 70 ? 'high' : n >= 50 ? 'med' : 'low';
    return `<span class="ma-conf"><span class="ma-conf-bar"><span class="ma-conf-fill ${hue}" style="width:${Math.max(4, n)}%"></span></span><span class="ma-conf-num">${n}</span></span>`;
  };
  const maSection = (label: string, a: { name: string; currentLineText: string; avgText: string; vsLineText: string; matchupNotes: string; verdictText: string; confidenceText: string; confidence: number }) => `
        <div class="ma-subhead">${prettyName(a.name)} <span class="ma-subhead-tag">${label}</span></div>
        <div class="ma-row"><span class="ma-label">Current line</span><span class="ma-value">${maVal(a.currentLineText)}</span></div>
        <div class="ma-row"><span class="ma-label">Historical avg</span><span class="ma-value">${maVal(a.avgText)}</span></div>
        <div class="ma-row"><span class="ma-label">Vs similar lines</span><span class="ma-value">${maVal(a.vsLineText)}</span></div>
        <div class="ma-row"><span class="ma-label">Matchup notes</span><span class="ma-value">${maVal(a.matchupNotes)}</span></div>
        <div class="ma-row"><span class="ma-label">Verdict</span><span class="ma-value">${maVerdictChip(a.verdictText)}</span></div>
        <div class="ma-row"><span class="ma-label">Confidence</span><span class="ma-value">${maConfBar(a.confidence)}</span></div>`;

  const ctrlAnalysisHtml = `
    <div class="detail-panel ma-panel ma-ctrl">
      <div class="detail-panel-title">CTRL Matchup Analyzer</div>
      <div class="lean-reason ma-analysis">
        ${maSection('CTRL', fighterCtrlAnalysis)}
        ${maSection('CTRL · OPP', opponentCtrlAnalysis)}
        <div class="ma-subhead">Final Summary</div>
        <div class="ma-row"><span class="ma-label">Clearest value</span><span class="ma-value ma-verdict">${ctrlStrongest.available ? `${ctrlStrongest.name} (${ctrlStrongest.verdictText})` : 'No clear edge (insufficient data)'}</span></div>
        <div class="ma-row"><span class="ma-label">Key reasons</span><span class="ma-value">${ctrlKeyReasons}</span></div>
        <div class="ma-row"><span class="ma-label">Recommended</span><span class="ma-value">${ctrlRecommendedLeans.length ? ctrlRecommendedLeans.join(' | ') : 'No CTRL lean above confidence threshold'}</span></div>
      </div>
    </div>`;

  const ssAnalysisHtml = `
    <div class="detail-panel ma-panel ma-ss">
      <div class="detail-panel-title">SS Matchup Analyzer</div>
      <div class="lean-reason ma-analysis">
        ${maSection('SS', fighterSsAnalysis)}
        ${maSection('SS · OPP', opponentSsAnalysis)}
        <div class="ma-subhead">Final Summary</div>
        <div class="ma-row"><span class="ma-label">Clearest value</span><span class="ma-value ma-verdict">${strongest.available ? `${strongest.name} (${strongest.verdictText})` : 'No clear edge (insufficient data)'}</span></div>
        <div class="ma-row"><span class="ma-label">Key reasons</span><span class="ma-value">${keyReasons}</span></div>
        <div class="ma-row"><span class="ma-label">Volatility flags</span><span class="ma-value">${volatilityFlags.length ? volatilityFlags.join(' · ') : 'None flagged from fetched variance/style metrics'}</span></div>
        <div class="ma-row"><span class="ma-label">Recommended</span><span class="ma-value">${recommendedLeans.length ? recommendedLeans.join(' | ') : 'No SS lean above confidence threshold'}</span></div>
      </div>
    </div>`;

  // GLOW-UP 193 L1 — card-head "play pill": a compact scan anchor next to the
  // fighter identity so ALL FIGHTERS scans top-to-bottom instead of eye-tracking
  // to the far-right lean cell. Same effective lean, surfaced on the left with the
  // line included and the verdict reason on hover.
  const playPillHtml = (() => {
    if (!lean || lean.lean === 'none' || !db.loaded) return '';
    const stat = EFFECTIVE_LEAN_STAT_LABEL[lean._source || 'fp'] || 'FP';
    const arrow = lean.lean === 'over' ? '▲' : lean.lean === 'under' ? '▼' : '~';
    const sideCls = lean.lean === 'over' ? 'over' : lean.lean === 'under' ? 'under' : 'push';
    const sideTxt = lean.lean === 'push' ? 'TOSS-UP' : lean.lean.toUpperCase();
    // Slimmed to a pure scan anchor — direction · stat · line · book. Conf% and EV
    // live on the right-side lean cell; repeating them here read as redundant (and
    // the EV divider was visually busy). GLOW-UP 195 L4: resolve the line/book
    // through leanBestBook so the pill names the book that will actually TAKE the
    // play (the card head never showed placement) — matches the slim-row play line.
    const resolved = lean.lean === 'push' ? { book: null, line: null } : leanBestBook(f, lean._source || 'fp', lean.lean);
    const shownLine = resolved.line ?? lean.line ?? null;
    const lineTxt = shownLine != null ? ` ${shownLine}` : '';
    const bookTxt = resolved.book
      ? `<span class="play-pill-book" title="Best placeable entry for this side">@ ${LEAN_BOOK_LABEL[resolved.book] || resolved.book}</span>`
      : (lean.lean !== 'push' ? `<span class="play-pill-book blocked" title="No book takes this side — see the lean panel for the per-book breakdown">no book</span>` : '');
    return `<div class="play-pill play-${sideCls}" title="${(lean.verdict || '').replace(/"/g, '&quot;')}">${arrow} ${sideTxt} ${stat}${lineTxt}${bookTxt}</div>`;
  })();

  // GLOW-UP 193 L2 — opponent profile strip: promotes the buried opponent context
  // (archetype, durability, and what they ALLOW) into a legible chip row, so a high
  // projection reads as "because this opponent gets hit" — these are the exact
  // quantities the v10/v11 projection weighting feeds on.
  const oppProfileHtml = (() => {
    const odb = oppEntry?.db;
    if (!odb || !odb.loaded) return '';
    const r1Samples = (odb.oppHistory ?? []).slice(0, 5)
      .map(h => h.sigStrR1)
      .filter((v): v is number => typeof v === 'number' && Number.isFinite(v) && v > 0);
    const oppR1Allowed = r1Samples.length >= 3
      ? parseFloat((r1Samples.reduce((s, v) => s + v, 0) / r1Samples.length).toFixed(1))
      : null;
    const chips: string[] = [];
    if (odb.style) chips.push(`<span class="opp-chip opp-chip-style">${odb.style}</span>`);
    if (odb.avgTimeMins != null) chips.push(`<span class="opp-chip" title="Opponent average fight time — durability (a long average means they don't get finished early, so the fight goes rounds)">⏱ ${odb.avgTimeMins.toFixed(1)}m</span>`);
    const allows: string[] = [];
    if (oppAvgFPAllowed != null) allows.push(`FP ${oppAvgFPAllowed}`);
    if (oppAvgSSAllowed != null) allows.push(`SS ${oppAvgSSAllowed}`);
    if (oppR1Allowed != null) allows.push(`R1 ${oppR1Allowed}`);
    if (allows.length) chips.push(`<span class="opp-chip opp-chip-allows" title="Fantasy/strike output this opponent has historically ALLOWED (last 5) — the projection's opponent term">allows ${allows.join(' · ')}</span>`);
    if (odb.tdDef != null) chips.push(`<span class="opp-chip" title="Opponent takedown defense %">TD-def ${Math.round(odb.tdDef)}%</span>`);
    if (!chips.length) return '';
    return `<div class="opp-profile-strip"><span class="opp-profile-vs" title="Opponent">vs ${prettyName(oppName || 'opp')}</span>${chips.join('')}</div>`;
  })();

  // GLOW-UP 193 L3 — projection provenance: the stat-deck tooltips already carry
  // the full "(avg + opp)/2 × norm = final" math; this surfaces it as a compact
  // inline micro-chain so the opponent-weighting is visible without hovering.
  const provChain = (parts: string[]): string => parts.length >= 2
    ? `<div class="stat-prov">${parts.map((p, i) => `${i > 0 ? '<span class="stat-prov-arrow">→</span>' : ''}<span class="stat-prov-step">${p}</span>`).join('')}</div>`
    : '';
  const fpProvHtml = (() => {
    if (!db.loaded || (projFP == null && normDisplayFP == null)) return '';
    const steps: string[] = [];
    if (platformAvgFP != null) steps.push(`avg ${platformAvgFP.toFixed(1)}`);
    if (mlAdjFP != null && platformAvgFP != null && Math.abs(mlAdjFP - platformAvgFP) >= 0.5) steps.push(`ML ${mlAdjFP.toFixed(1)}`);
    if (projFP != null && oppAvgFPAllowed != null) steps.push(`opp ${oppAvgFPAllowed}`);
    if (normDisplayFP != null) steps.push(`×${roundNormFactor.toFixed(2)}`);
    const finalFP = normDisplayFP ?? projFP ?? mlAdjFP ?? platformAvgFP;
    if (finalFP != null) steps.push(`= ${finalFP.toFixed(1)}`);
    return provChain(steps);
  })();
  const ssProvHtml = (() => {
    if (!db.loaded || (projSS == null && normDisplaySS == null)) return '';
    const steps: string[] = [];
    if (avgSS != null) steps.push(`avg ${avgSS.toFixed(1)}`);
    if (projSS != null && oppAvgSSAllowed != null) steps.push(`opp ${oppAvgSSAllowed}`);
    if (normDisplaySS != null) steps.push(`×${roundNormFactor.toFixed(2)}`);
    if (finalDisplaySS != null) steps.push(`= ${finalDisplaySS.toFixed(1)}`);
    return provChain(steps);
  })();

  const row = document.createElement('div') as HTMLDivElement;
  const rowRoleClass = isDog ? ' role-dog' : ' role-fav';
  const rowConfTier = displayConf >= 72 ? ' conf-tier-high' : displayConf >= 58 ? ' conf-tier-med' : displayConf > 0 ? ' conf-tier-low' : '';
  row.className = 'fighter-row' + rowRoleClass + rowConfTier;
  row.dataset['name'] = f.name;
  row.innerHTML = `
    <div class="fighter-main">
      <div class="fighter-info">
        <div class="fighter-avatar-wrap" title="Head-to-head vs ${prettyName(f.opponent || 'opponent')}"><div class="fighter-avatar"><span class="fighter-avatar-flag">${db.country || '🏴'}</span><img class="fighter-avatar-img" alt="" /></div><span class="fighter-avatar-country">${db.country || ''}</span></div>
        <div>
          <div class="fighter-name" title="${prettyName(f.name)}">${prettyName(f.name)}${streakEmoji}</div>
          <div class="fighter-record">${db.record || '—'} · ${db.style || '...'}${(() => { const oppStrength = calcOpponentStrengthScore(oppEntry?.db ?? null); const emoji = oppStrength.score >= 1.45 ? '🔴' : oppStrength.score >= 0.75 ? '🟡' : oppStrength.score > -0.2 ? '⚪' : '🟢'; return oppEntry?.db?.loaded ? ` <span title="${oppStrength.label}" style="font-size:11px;opacity:0.85">${emoji}</span>` : ''; })()}</div>
          ${(() => { const recent = (db.history || []).slice(0, 5).filter(h => h.result === 'win' || h.result === 'loss'); return recent.length >= 2 ? `<div class="form-dots" title="Last ${recent.length} fights — newest first">${recent.map(h => `<span class="form-dot ${h.result}"></span>`).join('')}</div>` : ''; })()}
          <div style="display:flex;align-items:center;gap:4px;flex-wrap:wrap;margin-top:4px">${archetypeBadgeHtml}${archetypeAlertHtml}</div>
          ${sharpBadgeHtml}
          ${playPillHtml}
          ${oppProfileHtml}
        </div>
      </div>
      <div class="platform-lines">
        ${lineCell('p6', 'fp', f.line_p6)}
        ${lineCell('p6', 'ss', f.line_p6_ss)}
        ${lineCell('p6', 'td', f.line_p6_td)}
        ${lineCell('p6', 'ft', f.line_p6_ft)}
        ${lineCell('p6', 'ctrl', f.line_p6_ctrl)}
        ${lineCell('ud', 'fp', f.line_ud)}
        ${lineCell('ud', 'ss', f.line_ud_ss)}
        ${(f.line_ud_ss_r1 != null && showSource('ud')) ? `<div class="line-cell ss src-ud${ssR1BestCls('ud')}"><div class="line-platform"><span class="line-source-tag src-ud">UD</span><span>R1 SS</span></div><div class="line-value ud">${f.line_ud_ss_r1}</div>${ssR1BestBadge('ud')}</div>` : ''}
        ${(f.line_ud_ss_body != null && showSource('ud')) ? `<div class="line-cell ss src-ud"><div class="line-platform"><span class="line-source-tag src-ud">UD</span><span>Body</span></div><div class="line-value ud">${f.line_ud_ss_body}</div></div>` : ''}
        ${(f.line_ud_ss_leg != null && showSource('ud')) ? `<div class="line-cell ss src-ud"><div class="line-platform"><span class="line-source-tag src-ud">UD</span><span>Leg</span></div><div class="line-value ud">${f.line_ud_ss_leg}</div></div>` : ''}
        ${lineCell('ud', 'td', f.line_ud_td)}
        ${lineCell('ud', 'ft', f.line_ud_ft)}
        ${lineCell('ud', 'ctrl', f.line_ud_ctrl)}
        ${lineCell('betr', 'fp', f.line_betr)}
        ${lineCell('betr', 'ss', f.line_betr_ss)}
        ${lineCell('betr', 'td', f.line_betr_td)}
        ${lineCell('betr', 'ft', f.line_betr_ft)}
        ${lineCell('betr', 'ctrl', f.line_betr_ctrl)}
        ${lineCell('pp', 'fp', f.line_pp)}
        ${lineCell('pp', 'ss', f.line_pp_ss)}
        ${(f.line_pp_ss_r1 != null && showSource('pp')) ? `<div class="line-cell ss src-pp${ssR1BestCls('pp')}"><div class="line-platform"><span class="line-source-tag src-pp">PP</span><span>R1 SS</span></div><div class="line-value pp">${f.line_pp_ss_r1}</div>${ssR1BestBadge('pp')}</div>` : ''}
        ${(f.line_pp_ss_body != null && showSource('pp')) ? `<div class="line-cell ss src-pp"><div class="line-platform"><span class="line-source-tag src-pp">PP</span><span>Body</span></div><div class="line-value pp">${f.line_pp_ss_body}</div></div>` : ''}
        ${(f.line_pp_ss_leg != null && showSource('pp')) ? `<div class="line-cell ss src-pp"><div class="line-platform"><span class="line-source-tag src-pp">PP</span><span>Leg</span></div><div class="line-value pp">${f.line_pp_ss_leg}</div></div>` : ''}
        ${(f.line_pp_kd != null && showSource('pp')) ? `<div class="line-cell ss src-pp" title="Knockdowns O/U (PrizePicks). ${f.kd_under_available === true ? 'More + Less offered — Best Picks eligible.' : 'More-only (demon/goblin) — display only, not Best Picks eligible.'}"><div class="line-platform"><span class="line-source-tag src-pp">PP</span><span>KD${f.kd_under_available === true ? '' : ' ↑'}</span></div><div class="line-value pp">${f.line_pp_kd}</div></div>` : ''}
        ${lineCell('pp', 'td', f.line_pp_td)}
        ${lineCell('pp', 'ft', f.line_pp_ft)}
        ${lineCell('pp', 'ctrl', f.line_pp_ctrl)}
        ${lineCell('dk', 'ss', f.line_dk_ss)}
        ${(f.line_dk_ss_r1 != null && showSource('dk')) ? `<div class="line-cell ss src-dk${ssR1BestCls('dk')}"><div class="line-platform"><span class="line-source-tag src-dk">DK</span><span>R1 SS</span></div><div class="line-value dk">${f.line_dk_ss_r1}</div>${ssR1BestBadge('dk')}</div>` : ''}
        ${lineCell('dk', 'td', f.line_dk_td)}
        ${lineCell('dk', 'ft', f.line_dk_ft)}
        ${lineCell('dk', 'ctrl', f.line_dk_ctrl)}
        ${hasAnyVisibleSourceLine(f) ? '' : '<div class="line-value-empty">No visible source lines</div>'}
        <!-- Removed spikeEvent and odds badge UI -->
      </div>
      <div class="stats-mini">
        <div class="stat-card stat-card-fp" title="${normDisplayFP!=null?`Round-normalized (${roundNormTag}): ${(projFP??mlAdjFP??platformAvgFP??0).toFixed(1)} × ${roundNormFactor.toFixed(2)} = ${normDisplayFP}. Hist avg fight: ${histAvgMins}m, expected: ${isFiveRound?FIVE_ROUND_MINS:THREE_ROUND_MINS}m.`:projFP!=null?`Opp-adjusted projection: (your avg ${baseAvgFP!.toFixed(1)} + opp allows ${oppAvgFPAllowed!.toFixed(1)}) ÷ 2 = ${projFP.toFixed(1)}. Based on ${oppFPAllowedSamples.length} opp fights.`:mlAdjFP!=null?`ML-adjusted: ${mlAdjFP.toFixed(1)} FP (win/loss FP weighted by ${f.moneyline!=null?(f.moneyline<0?f.moneyline:'+'+f.moneyline):'-'} implied win prob). Raw avg: ${platformAvgFP!=null?platformAvgFP.toFixed(1):'—'}`:'Recent fantasy points average from UFCStats history'}">
          <div class="stat-card-head">
            <span class="stat-card-label">${projFP!=null?'Proj FP':'Avg FP'}</span>
            ${roundNormTag?`<span class="round-norm-tag">${roundNormTag}</span>`:''}
          </div>
          <div class="stat-card-big">
            <span class="stat-card-num${hasNoHistory?' stat-nodata':''}">${hasNoHistory?'—':normDisplayFP!=null?normDisplayFP.toFixed(1):projFP!=null?projFP.toFixed(1):mlAdjFP!=null?mlAdjFP.toFixed(1):(platformAvgFP!=null?platformAvgFP.toFixed(1):'...')}</span>
            <span class="stat-card-meta">${avgFPPercentileLabel}${projFP!=null&&!normDisplayFP?`<span class="opp-allows-badge" title="Opponent allows ${oppAvgFPAllowed} FP avg">(${oppAvgFPAllowed})</span>`:''}${mlAdjShift!=null&&Math.abs(mlAdjShift)>=3&&!normDisplayFP&&!projFP?`<span class="ml-adj-badge ${mlAdjShift>0?'pos':'neg'}">${mlAdjShift>0?'+':''}${mlAdjShift.toFixed(1)}</span>`:''}${trendChip(fpTrend,`${_twLabel} avg: ${fpTrend.recentAvg} · Career: ${fpTrend.careerAvg}`)}</span>
          </div>
          ${fpProvHtml}
          ${db.fpFloor!=null?`<div class="stat-card-foot">${fpFloor}–${fpCeiling}</div>`:''}
        </div>
        <div class="stat-card stat-card-ss">
          <div class="stat-card-head">
            <span class="stat-card-label">SS</span>
            ${roundNormTag?`<span class="round-norm-tag">${roundNormTag}</span>`:''}
          </div>
          <div class="stat-row" title="${normDisplaySS!=null?`Round-normalized (${roundNormTag}): ${displaySS!.toFixed(1)} × ${roundNormFactor.toFixed(2)} = ${normDisplaySS}.`:projSS!=null?`Opp-adjusted projection: (your avg ${avgSS!.toFixed(1)} + opp allows ${oppAvgSSAllowed!.toFixed(1)}) ÷ 2 = ${projSS.toFixed(1)}.${ssSpreadTip?' | '+ssSpreadTip:''}`:ssSpreadTip||'Average significant strikes landed per fight'}">
            <span class="stat-row-label">${projSS!=null?'proj':'avg'}</span>
            <span class="stat-row-val${hasNoHistory?' stat-nodata':''}">${hasNoHistory?'—':finalDisplaySS!=null?finalDisplaySS.toFixed(1):'...'}${hasNoHistory?'':ssSpreadLabel?`<span class="ss-spread-inline" style="color:${ssSpreadColor}" title="${ssSpreadTip}">${roundNormFactor!==1.0?`±${(parseFloat(ssSpreadLabel.slice(1))*roundNormFactor).toFixed(1)}`:ssSpreadLabel}</span>`:''}${projSS!=null&&!normDisplaySS?`<span class="opp-allows-badge" title="Opponent allows ${oppAvgSSAllowed} SS avg">(${oppAvgSSAllowed})</span>`:''}${trendChip(ssTrend,`SS ${_twLabel} avg: ${ssTrend.recentAvg} · Career: ${ssTrend.careerAvg}`)}</span>
          </div>
          ${ssProvHtml}
          <div class="stat-row" title="Current active platform SS betting line">
            <span class="stat-row-label">line</span>
            <span class="stat-row-val">${primarySSLine!=null?primarySSLine.toFixed(1):'...'}</span>
          </div>
          <div class="stat-delta-block ${ssDeltaClass}" title="${normDisplaySS!=null?`Delta = Norm SS (${finalDisplaySS!.toFixed(1)}) minus SS line.`:projSS!=null?`Delta = Proj SS (${projSS.toFixed(1)}) minus SS line.`:'Delta = Avg SS minus SS line. Positive favors over, negative favors under.'}">
            <span class="stat-delta-val">${ssDeltaText}</span>
            ${normDisplayTD!=null?`<span class="stat-delta-td" title="${projTD!=null?`Proj TD opp-adj: (avg ${avgTDraw} + opp allows ${oppAvgTDAllowed}) ÷ 2 = ${projTD}, normalized: ${normDisplayTD}`:`TD normalized: ${avgTDraw} × ${roundNormFactor.toFixed(2)} = ${normDisplayTD}`}">${projTD!=null?'P':'A'}TD ${normDisplayTD}</span>`:projTD!=null&&!normDisplayTD?`<span class="stat-delta-td" title="Proj TD: (avg ${avgTDraw} + opp allows ${oppAvgTDAllowed}) ÷ 2 = ${projTD}">PTD ${projTD}</span>`:''}
          </div>
        </div>
      </div>
      <div class="lean-cell">
        <div class="lean-badge ${leanClass}" style="${leanGradStyle}" title="${lean.verdict}">${leanText}${confInlineLabel}</div>
        ${confPct > 0 ? `<div class="confidence-meter" title="Confidence${displayGrade}: ${confPct}%${recalConf != null && recalConf !== confPct ? ' (recal: ' + recalConf + '%)' : ''}"><div class="confidence-fill" data-fill-width="${displayConf}%" style="width:0%; background: rgb(${roleRGB}); color: rgb(${roleRGB});"></div></div>` : ''}
        ${(() => {
          const wm = _weightMissSignals.get(f.name.toLowerCase());
          if (!wm) return '';
          const lbsLabel = wm.lbsOver != null ? `${wm.lbsOver % 1 === 0 ? wm.lbsOver : wm.lbsOver.toFixed(1)} LB` : '';
          const tip = wm.source.replace(/"/g, '&quot;').replace(/</g, '&lt;');
          return `<button class="weight-miss-badge weight-miss-${wm.severity}" data-news-fighter="${f.name}" title="${tip}">⚖ MISS${lbsLabel ? ' ' + lbsLabel : ''}</button>`;
        })()}
        ${_newsAlertFighters.has(f.name.toLowerCase()) ? `<button class="news-warn-badge" data-news-fighter="${f.name}" title="Recent injury/withdrawal news detected — click for headlines">⚠ NEWS</button>` : ''}
        ${hasNoHistory ? `<div class="nodata-badge" title="No UFCStats fight history for this fighter — every striking/grappling average computes to 0.0 from an empty log. The averages and deltas above are therefore blank rather than zero, because a zero here would be a measurement and this is an absence. Any lean shown is built WITHOUT a personal baseline: it can only be reading the line, the opponent and the matchup. Treat its confidence with suspicion.">⌀ NO HISTORY</div>` : ''}
        ${(() => {
          // v21 drops lines priced against a fighter who left the card. Without this
          // badge the only trace is a console line and one fewer chip — which reads
          // as "the book never posted it" rather than "we removed it, and here is why".
          const drop = _staleLineDrops.get((normalizeName(f.name) || f.name).toLowerCase());
          if (!drop) return '';
          const books = drop.books.map(b => b.toUpperCase()).join(', ');
          const opp = drop.opponent.replace(/"/g, '&quot;').replace(/</g, '&lt;');
          return `<div class="stale-line-badge" title="Dropped ${drop.books.length} line source(s) — ${books} — priced against ${opp}, who is no longer on this card. Those numbers were set for a different matchup, so the model ignores them — the book simply has not repriced yet. If this appears on MANY fighters at once, suspect a stale or mis-paired card rather than the books."><b class="slb-mark">⊘</b>STALE <i class="slb-books">${books}</i></div>`;
        })()}
        ${hasCrossStatConflict(f) ? `<div class="conflict-warn" title="FP leans ${lean.lean?.toUpperCase()} but SS and TD both lean the opposite — grappling/striking split. Lower confidence.">⚠ Stat split</div>` : ''}
        ${hasConsensusLean(f) ? `<div class="consensus-lean" title="FP, SS, and TD all lean ${hasConsensusLean(f)?.toUpperCase()} — strong multi-stat alignment">⚡ consensus</div>` : ''}
        ${lean.rivalryDissent ? `<div class="conflict-warn" style="background:rgba(255,184,77,0.10);border-color:rgba(255,184,77,0.35);color:#ffbe6b" title="Rival models disagree with the main lean — ${String(lean.rivalryDissent).replace(/"/g, '&quot;')}">⚔ Rival models dissent</div>` : ''}
        ${(() => {
          if (!_fighterArchiveStats) return '';
          const key = (normalizeName(f.name) || f.name).toLowerCase();
          const stats = _fighterArchiveStats.get(key);
          if (!stats) return '';
          const parts: string[] = [];
          for (const [pt, d] of Object.entries(stats)) {
            if (d.total < 2) continue;
            const pct = Math.round(d.hits / d.total * 100);
            const col = pct >= 65 ? 'var(--green)' : pct >= 45 ? 'var(--amber)' : 'var(--red)';
            const label = pt === 'FightTime' ? 'FT' : pt === 'Fantasy' ? 'FP' : pt;
            parts.push(`<span style="color:${col}">${label} ${pct}%</span>`);
          }
          if (!parts.length) return '';
          const totalEvents = Math.max(...Object.values(stats).map(d => d.total));
          return `<div class="archive-accuracy-badge" title="Archive hit rate for ${f.name} across ${totalEvents} settled event(s)">📊 ${parts.join(' · ')}</div>`;
        })()}
        ${leanEvDetail != null ? `<div class="ev-label ${leanEvDetail.ev > 0 ? 'ev-pos' : leanEvDetail.ev < 0 ? 'ev-neg' : ''}" title="EV from ${Math.round(leanEvDetail.prob * 100)}% win prob${leanEvDetail.recalibrated ? ' (recalibrated from realized accuracy ↻)' : ''} · ${leanEvDetail.isAssumedVig ? 'assumed -110 vig (no book odds for FP)' : `actual odds · profit ${leanEvDetail.profit.toFixed(2)}x${leanEvDetail.vig != null ? ` · vig ${leanEvDetail.vig}%` : ''}`}">${leanEvDetail.isAssumedVig ? '~' : ''}EV: ${leanEvDetail.ev > 0 ? '+' : ''}${leanEvDetail.ev}%${leanEvDetail.recalibrated ? ' <span style="font-size:8px;opacity:0.6">↻</span>' : ''}${!leanEvDetail.isAssumedVig && leanEvDetail.vig != null ? ` <span style="color:${leanEvDetail.vig > 5 ? 'var(--red)' : leanEvDetail.vig > 3 ? 'var(--amber)' : 'var(--green)'};font-size:8px">(${leanEvDetail.vig}%)</span>` : ''}</div>` : ''}
        ${weightedAvg != null ? `<div class="weighted-avg-label">W.Avg: ${weightedAvg.toFixed(1)}</div>` : ''}
        ${(() => {
          const fvEdge = lean.fairValueEdge;
          const fvVal = lean.fairValue;
          if (fvEdge == null || fvVal == null || Math.abs(fvEdge) < 1.5) return '';
          const absE = Math.abs(fvEdge);
          const col = absE >= 4 ? (fvEdge > 0 ? '#48c78e' : '#ff6464') : '#f0c040';
          const bg = absE >= 4 ? (fvEdge > 0 ? 'rgba(72,199,142,0.12)' : 'rgba(255,100,100,0.12)') : 'rgba(240,192,64,0.12)';
          return `<div class="fair-value-chip" style="font-size:9px;padding:2px 7px;border-radius:6px;background:${bg};border:1px solid ${col}40;color:${col};letter-spacing:0.04em" title="Fair value ${fvVal.toFixed(1)} — edge ${fvEdge > 0 ? '+' : ''}${fvEdge.toFixed(1)} pts vs active line">FV ${fvEdge > 0 ? '+' : ''}${fvEdge.toFixed(1)}</div>`;
        })()}
      </div>
      <div class="row-expand-slot"><span class="expand-arrow">▼</span></div>
    </div>
    <div class="fighter-detail"></div>`;

  // Lazy: defer building the detail panel HTML until the row is expanded.
  // GLOW-UP 166 (level-up 5): verdict synthesis — the fighter's own hit rate
  // at HIS line fused with how often THIS opponent's past foes cleared that
  // same line. Purely descriptive of the two histories; a direction is only
  // called when both agree (both ≥60% over → OVER EDGE, both ≤40% → UNDER).
  const oppAllowsFights: HistoryRow[] = oppEntry?.db?.oppHistory || [];
  const synthFor = (line: number | null, statVal: (h: HistoryRow) => number | null | undefined): string => {
    if (line == null || line <= 0) return '';
    const own = (db.history || []).map(statVal).filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
    const allows = oppAllowsFights.map(statVal).filter((v): v is number => typeof v === 'number' && Number.isFinite(v));
    if (own.length < 3 || allows.length < 3) return '';
    const oOv = own.filter(v => v > line).length;
    const aOv = allows.filter(v => v > line).length;
    const oR = oOv / own.length;
    const aR = aOv / allows.length;
    const dir = oR >= 0.6 && aR >= 0.6 ? 'over' : oR <= 0.4 && aR <= 0.4 ? 'under' : 'mixed';
    const label = dir === 'over' ? '▲ OVER EDGE' : dir === 'under' ? '▼ UNDER EDGE' : '≈ MIXED';
    return `<div class="hist-synth hist-synth-${dir}" title="Both halves of the matchup measured at this line (${line}): ${prettyName(f.name)} cleared it in ${oOv}/${own.length} career fights; ${prettyName(oppName || 'the opponent')}'s past foes cleared it ${aOv}/${allows.length} times against him. A direction is only called when both agree."><span class="sy-label">SYNTH</span><span class="sy-part">history <b>${oOv}/${own.length}</b></span><span class="sy-sep">·</span><span class="sy-part">opp allows <b>${aOv}/${allows.length}</b></span><span class="sy-verdict">${label}</span></div>`;
  };

  // The closure captures all per-row state (db, oppEntry, history strings, etc).
  // GLOW-UP 193 L5 — the actionable "why" lean panels were dead-last under every
  // history/model panel. Hoist them into a conviction-first section at the TOP of
  // the expanded card, gated behind a per-card SIGNAL-ONLY toggle for the
  // full-slate / 50%-zoom workflow.
  // ── GLOW-UP 213 — KD lean panel ──────────────────────────────────────────
  // Knockdowns have had a lean since MODEL v8 (calcKDLean) and it already feeds
  // Best Picks and Parlay Lab — but there was no panel, making KD the only stat
  // that could put you on a pick with no way to see the reasoning behind it.
  //
  // The market rule IS the headline here, so it's stated on the panel rather than
  // left implicit: knockdowns are PrizePicks-only, and PP's odds_type decides
  // everything. A standard projection posts More AND Less and is Best-Picks
  // eligible; a demon/goblin is More-only on a non-standard payout, which makes
  // NEITHER side an ordinary pick-em play — the same rule parlayUnrankableReason
  // enforces, said out loud where the user is looking at the prop.
  // ── GLOW-UP 224 — every prop panel follows the LINE, not the lean ─────────
  // Each lean panel was gated on its lean object existing, but the side picker
  // INSIDE the panel is the only control that queues a pick for that prop. So a
  // posted line with no lean — a normal state, not an edge case, whenever the
  // model lacks the history it needs — meant the prop was unreachable from the
  // board: no panel, no picker, no way to track a bet already placed on it.
  // A live line is now enough to earn the panel. The lean, when there is one,
  // still supplies the verdict chip, the factor block and the placement chip;
  // without one the panel is lines plus the two-sided picker, which is exactly
  // what FP has always been.
  const leanDirOf = (l?: LeanResult | null): 'over' | 'under' | null =>
    l && (l.lean === 'over' || l.lean === 'under') ? l.lean : null;
  const anyLine = (...vals: Array<number | null | undefined>): boolean => vals.some(v => v != null);
  const noReadNote = (what: string): string =>
    `<div class="ctrl-noplay">No ${what} read — the model takes no side here, usually for want of the history it scores from. The line is live, so either side can still be queued.</div>`;
  const ssHasLine = anyLine(f.line_p6_ss, f.line_ud_ss, f.line_pp_ss, f.line_betr_ss, f.line_dk_ss);
  const tdHasLine = anyLine(f.line_p6_td, f.line_ud_td, f.line_pp_td, f.line_betr_td, f.line_dk_td);
  const ftHasLine = anyLine(f.line_p6_ft, f.line_ud_ft, f.line_pp_ft, f.line_betr_ft, f.line_dk_ft);
  const ctrlHasLine = anyLine(f.line_p6_ctrl, f.line_ud_ctrl, f.line_pp_ctrl, f.line_betr_ctrl, f.line_dk_ctrl);
  const r1HasLine = anyLine(f.line_pp_ss_r1, f.line_ud_ss_r1, f.line_dk_ss_r1);
  const ssDir = leanDirOf(f.lean_ss);
  const tdDir = leanDirOf(f.lean_td);
  const ftDir = leanDirOf(f.lean_ft);
  const ctrlDir = leanDirOf(f.lean_ctrl);
  const r1Dir = leanDirOf(f.lean_ss_r1);
  const kdStandard = f.kd_under_available === true;
  const kdDir = f.lean_kd && (f.lean_kd.lean === 'over' || f.lean_kd.lean === 'under') ? f.lean_kd.lean : null;
  const kdPanel = (f.lean_kd || f.line_pp_kd != null)
    ? `<div class="detail-panel">
          <div class="detail-panel-title">KD ${f.lean_kd ? 'Lean' : 'Lines'}${kdDir ? ` <span class="lean-verdict ${kdDir}" style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;margin-left:6px">${kdDir === 'over' ? '▲ OVER' : '▼ UNDER'} ${f.lean_kd?.conf ?? 0}%</span>` : ''} · PP: ${f.line_pp_kd ?? '—'}${kdStandard && kdDir ? buildPlacementChip(f, 'kd', kdDir) : ''}${buildSidePicker(f, 'kd', kdDir)}</div>
          ${kdStandard
            ? ''
            : `<div class="ctrl-overonly-note" title="PrizePicks prices this knockdowns prop More-only (a demon or goblin projection). Those carry non-standard payouts, so neither side is a normal pick-em play and the board keeps KD display-only here — the lean below is information, not a play.">⚠ MORE-ONLY (demon/goblin) — non-standard payout, so neither side is Best-Picks eligible.</div>`}
          ${f.lean_kd ? buildLeanFactorBlock(f.lean_kd.reasons, f.lean_kd.lean) : ''}
          ${f.lean_kd ? `<div class="lean-verdict ${f.lean_kd.lean}">${f.lean_kd.verdict}</div>` : ''}
          ${!kdStandard
            ? '<div class="ctrl-noplay">Display-only on this card — PrizePicks is More-only here, so this fighter contributes no KD pick.</div>'
            : !kdDir
              ? '<div class="ctrl-noplay">No KD edge either way.</div>'
              : ''}
        </div>`
    : '';

  const leanPanelsHtml = [
    // FP has no lean panel of its own — its verdict lives on the row's play pill,
    // which only ever shows the EFFECTIVE lean. So whenever the effective lean is
    // some other stat, fantasy points had no home in the panel stack and no way to
    // be queued from either side. Minimal by design: per-book FP lines plus a side
    // picker, no factor block — the FP rationale is already the row's main verdict.
    (f.line_p6 != null || f.line_ud != null || f.line_pp != null || f.line_betr != null) ? `<div class="detail-panel">
          <div class="detail-panel-title">FP Lines${buildFpBookPickers(f, lean && lean._source === 'fp' ? lean.lean : null)}</div>
        </div>` : '',
    (f.lean_ss || ssHasLine) ? `<div class="detail-panel">
          <div class="detail-panel-title">SS ${f.lean_ss ? 'Lean' : 'Lines'} (P6: ${f.line_p6_ss??'—'} · UD: ${f.line_ud_ss??'—'} · PP: ${f.line_pp_ss??'—'} · BT: ${f.line_betr_ss??'—'} · DK: ${f.line_dk_ss??'—'})${buildBookPlacementControl(f, 'ss', ssDir)}</div>
          ${f.lean_ss ? buildLeanFactorBlock(f.lean_ss.reasons, f.lean_ss.lean) : ''}
          ${f.lean_ss
            ? `<div class="lean-verdict ${f.lean_ss.lean}">${f.lean_ss.verdict}</div>`
            : noReadNote('significant strikes')}
        </div>` : '',
    // ── GLOW-UP 224 — the R1 SS panel follows the LINE, not the lean ────────
    // This panel was gated on `f.lean_ss_r1`, so a fighter with a live round-one
    // SS line but no lean had no panel — and the side picker inside it is the
    // only control that queues an R1 SS pick, so the prop was unreachable from
    // the board entirely. calcSSR1Lean needs round-one history the fighter may
    // simply not have, which makes "line posted, no lean" a normal state rather
    // than an edge case: Lucas Fernando held an Underdog R1 SS 16.5 that had
    // already been bet, with nothing on the card to track it against.
    // FP gates on lines and KD gates on `lean || line` — R1 SS now matches.
    (f.lean_ss_r1 || r1HasLine) ? `<div class="detail-panel">
          <div class="detail-panel-title">R1 SS ${f.lean_ss_r1 ? 'Lean' : 'Lines'}${r1Dir ? ` <span class="lean-verdict ${r1Dir}" style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;margin-left:6px">${r1Dir === 'over' ? '▲ OVER' : '▼ UNDER'} ${f.lean_ss_r1?.conf ?? 0}%</span>` : ''} (PP: ${f.line_pp_ss_r1||'—'} · UD: ${f.line_ud_ss_r1||'—'} · DK: ${f.line_dk_ss_r1||'—'})${buildBookPlacementControl(f, 'ss_r1', r1Dir)}</div>
          ${f.lean_ss_r1 ? buildLeanFactorBlock(f.lean_ss_r1.reasons, f.lean_ss_r1.lean) : ''}
          ${f.lean_ss_r1
            ? `<div class="lean-verdict ${f.lean_ss_r1.lean}">${f.lean_ss_r1.verdict}</div>`
            : '<div class="ctrl-noplay">No round-one read — the model needs round-one history this fighter does not have, so it takes no side. The line is live and either side can still be queued.</div>'}
        </div>` : '',
    (f.lean_td || tdHasLine) ? `<div class="detail-panel">
          <div class="detail-panel-title">TD ${f.lean_td ? 'Lean' : 'Lines'} (P6: ${f.line_p6_td??'—'} · UD: ${f.line_ud_td??'—'} · PP: ${f.line_pp_td??'—'} · BT: ${f.line_betr_td??'—'} · DK: ${f.line_dk_td??'—'})${buildBookPlacementControl(f, 'td', tdDir)}</div>
          ${f.lean_td ? buildLeanFactorBlock(f.lean_td.reasons, f.lean_td.lean) : ''}
          ${f.lean_td
            ? `<div class="lean-verdict ${f.lean_td.lean}">${f.lean_td.verdict}</div>`
            : noReadNote('takedown')}
        </div>` : '',
    (f.lean_ft || ftHasLine) ? `<div class="detail-panel">
          <div class="detail-panel-title">FT ${f.lean_ft ? 'Lean' : 'Lines'}${ftDir?` <span class="lean-verdict ${ftDir}" style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;margin-left:6px">${ftDir==='over'?'▲ OVER':'▼ UNDER'} ${f.lean_ft?.conf ?? 0}%</span>`:''} · P6: ${f.line_p6_ft??'—'} · UD: ${f.line_ud_ft??'—'} · PP: ${f.line_pp_ft??'—'} · BT: ${f.line_betr_ft??'—'} · DK: ${f.line_dk_ft??'—'}${buildBookPlacementControl(f, 'ft', ftDir)}</div>
          ${f.lean_ft ? buildLeanFactorBlock(f.lean_ft.reasons, f.lean_ft.lean) : ''}
          ${f.lean_ft
            ? `<div class="lean-verdict ${f.lean_ft.lean}">${f.lean_ft.verdict}</div>`
            : noReadNote('fight-time')}
        </div>` : '',
    // CTRL panel (MODEL v16). CTRL had history/opp panels and line cells but no
    // lean panel, so its verdict was computed and never shown. The over-only rule
    // is stated ON the panel rather than left implicit: when the model lands on
    // UNDER, the honest answer is "no play", not a pick you can't enter.
    (f.lean_ctrl || ctrlHasLine) ? `<div class="detail-panel">
          <div class="detail-panel-title">CTRL ${f.lean_ctrl ? 'Lean' : 'Lines'}${ctrlDir === 'over' ? ` <span class="lean-verdict over" style="display:inline-block;padding:1px 8px;border-radius:8px;font-size:10px;margin-left:6px">▲ OVER ${f.lean_ctrl?.conf ?? 0}%</span>` : ''} · P6: ${f.line_p6_ctrl??'—'} · UD: ${f.line_ud_ctrl??'—'} · PP: ${f.line_pp_ctrl??'—'} · BT: ${f.line_betr_ctrl??'—'} · DK: ${f.line_dk_ctrl??'—'}${buildBookPlacementControl(f, 'ctrl', ctrlDir)}</div>
          <div class="ctrl-overonly-note" title="Control-time props are More-only in practice — Pick6 is the primary CTRL book and posts no Less button, and no other book reliably offers the under. So CTRL contributes OVER picks to the board and nothing else; an under lean is information, not a play.">⚠ OVER-ONLY market — the under side isn't offered, so only an OVER can become a pick.</div>
          ${f.lean_ctrl ? buildLeanFactorBlock(f.lean_ctrl.reasons, f.lean_ctrl.lean) : ''}
          ${f.lean_ctrl ? `<div class="lean-verdict ${f.lean_ctrl.lean}">${f.lean_ctrl.verdict}</div>` : ''}
          ${!f.lean_ctrl
            ? noReadNote('control-time')
            : f.lean_ctrl.lean !== 'over'
              ? `<div class="ctrl-noplay">${f.lean_ctrl.lean === 'under'
                  ? 'Model leans UNDER here — not takeable, so this fighter contributes no CTRL pick.'
                  : 'No CTRL edge either way.'}</div>`
              : ''}
        </div>` : '',
    kdPanel,
  ].filter(Boolean).join('');

  _pendingDetailBuilders.set(row, () => `<div class="detail-grid">
        <div class="detail-signal-bar">${leanPanelsHtml ? `<button class="detail-signal-toggle" type="button" data-signal-toggle title="Hide reference panels — show only the actionable leans">⚡ SIGNAL ONLY</button>` : ''}</div>
        ${leanPanelsHtml ? `<div class="detail-leans-section"><div class="detail-section-head">⚡ Leans — the play</div>${leanPanelsHtml}</div>` : ''}
        <div class="detail-section-head">📊 Stat Head-to-Head — ${prettyName(f.name)} vs ${prettyName(oppName || 'Opponent')}</div>
        <div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">FP History vs Line (${platformLabel})</div>${historyHTML}${synthFor(activeLine, h => getFightFantasyValueForPlatform(h, historyPlatform))}${activeLine?`<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([{ tag: platformKeyShort(getSourceActivePlatformKey(f, 'fp')), raw: activeLine }])}</div>`:''}</div>
        <div class="detail-panel"><div class="detail-panel-title">⚔️ Opp FP Scored vs ${f.name}${oppCompareFpLine != null ? ` · ${oppName} line ${oppCompareFpLine}` : ''}</div>${oppFights.length?oppFPHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>
        </div>
        <div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">Sig Strikes History${ssLine != null ? ` vs Line ${ssLine}` : ''}</div>${ssHistoryHTML}${synthFor(ssLine, h => h.sigStr)}${ssLine != null ? `<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([
          { tag: 'P6', raw: f.line_p6_ss }, { tag: 'UD', raw: f.line_ud_ss }, { tag: 'PP', raw: f.line_pp_ss }, { tag: 'BT', raw: f.line_betr_ss },
          ...(f.line_dk_ss != null ? [{ tag: 'DK', raw: f.line_dk_ss }] : []),
        ])}</div>` : ''}</div>
        <div class="detail-panel"><div class="detail-panel-title">⚔️ Opp SS Scored vs ${f.name}${oppCompareSsLine != null ? ` · ${oppName} SS line ${oppCompareSsLine}` : ''}</div>${oppFights.length?oppSSHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>
        </div>
        ${(ssR1Line != null || oppCompareSsR1Line != null) ? `<div class="stat-pair">` : ''}
        ${ssR1Line != null ? `<div class="detail-panel"><div class="detail-panel-title">R1 Sig Strikes History vs Line ${ssR1Line} <span class="panel-confidence low">${ssR1Badge}</span></div>${ssR1HistoryHTML}<div class="panel-meta"><div class="panel-meta-line"></div> ${ssR1Meta}</div></div>` : ''}
        ${oppCompareSsR1Line != null ? `<div class="detail-panel"><div class="detail-panel-title">⚔️ Opp R1 SS Scored vs ${f.name} · ${oppName} R1 SS line ${oppCompareSsR1Line} <span class="panel-confidence low">${oppSsR1Badge}</span></div>${oppFights.length?oppSSR1History:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>` : ''}
        ${(ssR1Line != null || oppCompareSsR1Line != null) ? `</div>` : ''}
        ${(bodyLine != null || oppCompareBodyLine != null) ? `<div class="stat-pair">` : ''}
        ${bodyLine != null ? `<div class="detail-panel"><div class="detail-panel-title">Body Sig Strikes History vs Line ${bodyLine} <span class="panel-confidence low">${bodyBadge}</span></div>${bodyHistoryHTML}<div class="panel-meta"><div class="panel-meta-line"></div> ${bodyMeta}</div></div>` : ''}
        ${oppCompareBodyLine != null ? `<div class="detail-panel"><div class="detail-panel-title">⚔️ Opp Body SS Scored vs ${f.name} · ${oppName} Body line ${oppCompareBodyLine} <span class="panel-confidence low">${oppBodyBadge}</span></div>${oppFights.length?oppBodyHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>` : ''}
        ${(bodyLine != null || oppCompareBodyLine != null) ? `</div>` : ''}
        ${(legLine != null || oppCompareLegLine != null) ? `<div class="stat-pair">` : ''}
        ${legLine != null ? `<div class="detail-panel"><div class="detail-panel-title">Leg Sig Strikes History vs Line ${legLine} <span class="panel-confidence low">${legBadge}</span></div>${legHistoryHTML}<div class="panel-meta"><div class="panel-meta-line"></div> ${legMeta}</div></div>` : ''}
        ${oppCompareLegLine != null ? `<div class="detail-panel"><div class="detail-panel-title">⚔️ Opp Leg SS Scored vs ${f.name} · ${oppName} Leg line ${oppCompareLegLine} <span class="panel-confidence low">${oppLegBadge}</span></div>${oppFights.length?oppLegHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>` : ''}
        ${(legLine != null || oppCompareLegLine != null) ? `</div>` : ''}
        <div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">Takedowns History${tdLine!=null?` vs Line ${tdLine}`:''}${trendChip(tdTrend,`TD ${_twLabel} avg: ${tdTrend.recentAvg} · Career: ${tdTrend.careerAvg}`)}</div>${tdHistoryHTML}${synthFor(tdLine, h => h.td)}${tdLine!=null?`<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([
          { tag: 'P6', raw: f.line_p6_td }, { tag: 'UD', raw: f.line_ud_td }, { tag: 'PP', raw: f.line_pp_td }, { tag: 'BT', raw: f.line_betr_td },
          ...(f.line_dk_td != null ? [{ tag: 'DK', raw: f.line_dk_td }] : []),
        ])}</div>`:''}</div>
        <div class="detail-panel"><div class="detail-panel-title">⚔️ Opp TDs Scored vs ${f.name}${oppCompareTdLine != null ? ` · ${oppName} TD line ${oppCompareTdLine}` : ''}</div>${oppFights.length?oppTDHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>
        </div>
        ${(kdLine != null || oppCompareKdLine != null) ? `<div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">Knockdowns History${kdLine!=null?` vs Line ${kdLine}`:''}${kdLine!=null && f.kd_under_available !== true ? ' <span class="panel-confidence low" title="PrizePicks More-only (demon/goblin) — display only, not Best Picks eligible">MORE-only</span>' : ''}</div>${kdHistoryHTML}${kdLine!=null?`<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([{ tag: 'PP', raw: kdLine }])}</div>`:''}</div>
        <div class="detail-panel"><div class="detail-panel-title">⚔️ Opp KDs Scored vs ${f.name}${oppCompareKdLine != null ? ` · ${oppName} KD line ${oppCompareKdLine}` : ''}</div>${oppFights.length?oppKDHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>
        </div>` : ''}
        <div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">Control Time History${ctrlLine!=null?` vs Line ${formatMinutesAsClock(ctrlLine)}`:''}${panelBadge(ctrlConf)}${f.line_p6_ctrl!=null && f.ctrl_under_available === false ? ' <span class="panel-confidence low" title="Pick6 only offers OVER on this CTRL line — UNDER is unplaceable">OVER-only</span>' : ''}</div>${ctrlHistoryHTML}${ctrlLine!=null?`<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([
          { tag: 'P6', raw: f.line_p6_ctrl }, { tag: 'UD', raw: f.line_ud_ctrl }, { tag: 'PP', raw: f.line_pp_ctrl }, { tag: 'BT', raw: f.line_betr_ctrl },
          ...(f.line_dk_ctrl != null ? [{ tag: 'DK', raw: f.line_dk_ctrl }] : []),
        ], formatMinutesAsClock)}</div>`:''}</div>
        <div class="detail-panel"><div class="detail-panel-title">⚔️ Opp CTRL Scored vs ${f.name}${oppCompareCtrlLine != null ? ` · ${oppName} CTRL line ${formatMinutesAsClock(oppCompareCtrlLine)}` : ''}${panelBadge(oppCtrlConf)}</div>${oppFights.length?oppCTRLHistory:'<div class="history-empty">Clear cache &amp; reload to fetch</div>'}</div>
        </div>
        <div class="stat-pair">
        <div class="detail-panel"><div class="detail-panel-title">Fight Time History${ftLine!=null?` vs Line ${formatMinutesAsClock(ftLine)}`:''}</div>${ftHistoryHTML}${ftLine!=null?`<div class="panel-meta"><div class="panel-meta-line"></div>${buildPanelMetaChips([
          { tag: 'P6', raw: f.line_p6_ft }, { tag: 'UD', raw: f.line_ud_ft }, { tag: 'PP', raw: f.line_pp_ft }, { tag: 'BT', raw: f.line_betr_ft },
          ...(f.line_dk_ft != null ? [{ tag: 'DK', raw: f.line_dk_ft }] : []),
        ], formatMinutesAsClock)}</div>`:''}</div>
        ${buildFightTimeSummaryPanel(db, oppEntry?.db || null, platformStatLine(f, 'ft'))}
        </div>
        <div class="detail-section-head">🧠 Matchup Models &amp; Career</div>
        <div class="panel-pair">
        ${ssAnalysisHtml}
        ${ctrlAnalysisHtml}
        </div>
        <div class="panel-pair">
        <div class="detail-panel">
          <div class="detail-panel-title">UFCStats Career Data</div>
          <span class="stat-val mid">${db.record||'...'}</span>
          <div class="stat-row"><span class="stat-label">SIG STRIKES / MIN</span><span class="stat-val ${db.slpm!=null&&db.slpm>5?'good':db.slpm!=null&&db.slpm>3?'mid':'low'}">${db.slpm!=null?db.slpm.toFixed(2):'...'}</span></div>
          <div class="stat-row"><span class="stat-label">STRIKING ACC %</span><span class="stat-val ${db.strAcc!=null&&db.strAcc>48?'good':db.strAcc!=null&&db.strAcc>38?'mid':'low'}">${db.strAcc!=null?db.strAcc+'%':'...'}</span></div>
          <div class="stat-row"><span class="stat-label">TD AVG / 15 MIN</span><span class="stat-val ${db.avgTD!=null&&db.avgTD>2?'good':db.avgTD!=null&&db.avgTD>1?'mid':'low'}">${db.avgTD!=null?db.avgTD.toFixed(2):'...'}</span></div>
          <div class="stat-row"><span class="stat-label">TD DEFENSE %</span><span class="stat-val ${db.tdDef!=null&&db.tdDef>70?'good':db.tdDef!=null&&db.tdDef>50?'mid':'low'}">${db.tdDef!=null?db.tdDef+'%':'...'}</span></div>
          ${(() => {
            const h = db.history || [];
            const wins   = h.filter(x => x.result === 'win'  && x.method);
            const losses = h.filter(x => x.result === 'loss' && x.method);
            const cm = (arr: FightResult[], re: RegExp) => arr.filter(x => re.test(x.method || '')).length;
            const wKO = cm(wins, /KO|TKO/i), wSUB = cm(wins, /SUB/i), wDEC = wins.length - wKO - wSUB;
            const lKO = cm(losses, /KO|TKO/i), lSUB = cm(losses, /SUB/i);
            const miniBar = (n: number, tot: number, cls: string, lbl: string) => {
              if (!tot || !n) return '';
              const pct = Math.round(n/tot*100);
              return `<div class="finish-bar-row"><span class="finish-bar-label">${lbl}</span><div class="finish-bar-wrap"><div class="finish-bar ${cls}" data-fill-width="${pct}%" style="width:0%"></div></div><span class="finish-bar-pct">${n}/${tot}</span></div>`;
            };
            return wins.length + losses.length > 0 ? `
              <div class="stat-row" style="flex-direction:column;align-items:flex-start;gap:2px;margin-top:4px">
                <span class="stat-label">FINISH RATE ${db.finishRate!=null?`<span class="stat-val ${db.finishRate>0.6?'good':'mid'}" style="margin-left:4px">${Math.round(db.finishRate*100)}%</span>`:''}</span>
                <div class="finish-split-wrap" style="margin-top:4px">
                  ${wins.length ? `<div class="finish-split-section"><div class="finish-split-header">Wins (${wins.length})</div>${miniBar(wKO,wins.length,'ko-bar','KO/TKO')}${miniBar(wSUB,wins.length,'sub-bar','SUB')}${miniBar(wDEC,wins.length,'dec-bar','DEC')}</div>` : ''}
                  ${losses.length ? `<div class="finish-split-section"><div class="finish-split-header">Losses (${losses.length})</div>${miniBar(lKO,losses.length,'ko-bar-loss','KO/TKO')}${miniBar(lSUB,losses.length,'sub-bar','SUB')}${miniBar(losses.length-lKO-lSUB,losses.length,'dec-bar','DEC')}</div>` : ''}
                </div>
              </div>` : `<div class="stat-row"><span class="stat-label">FINISH RATE</span><span class="stat-val mid">${db.finishRate!=null?Math.round(db.finishRate*100)+'%':'...'}</span></div>`;
          })()}
          <div class="stat-row"><span class="stat-label">AVG FP (CALC)</span><span class="stat-val ${(db.avgFP??db.avgFP_p6)!=null&&activeLine!=null&&((db.avgFP??db.avgFP_p6) as number)>activeLine?'good':'low'}">${db.avgFP!=null?db.avgFP.toFixed(1):(db.avgFP_p6!=null?db.avgFP_p6.toFixed(1):'...')}</span></div>
          <div class="stat-row"><span class="stat-label">W.AVG FP (RECENT)</span><span class="stat-val ${weightedAvg!=null&&activeLine!=null&&weightedAvg>activeLine?'good':'low'}">${weightedAvg!=null?weightedAvg.toFixed(1):'...'}</span></div>
          <div class="stat-row"><span class="stat-label">FP FLOOR / CEILING</span><span class="stat-val mid">${db.fpFloor!=null?`${fpFloor} / ${fpCeiling}`:'...'}</span></div>
          <div class="stat-row"><span class="stat-label">FP STD DEV</span><span class="stat-val ${db.fpStdDev!=null&&db.fpStdDev<15?'good':db.fpStdDev!=null&&db.fpStdDev<25?'mid':'low'}">${db.fpStdDev!=null?db.fpStdDev:'...'}</span></div>
          <div class="stat-row"><span class="stat-label">CONSISTENCY %</span><span class="stat-val ${consistencyClass}">${fpConsistency!=null?fpConsistency+'%':'...'}</span></div>
          ${db.fiveRoundRate!=null&&db.fiveRoundRate>0?`<div class="stat-row"><span class="stat-label">5-ROUND FIGHT RATE</span><span class="stat-val mid">${Math.round(db.fiveRoundRate*100)}%</span></div>`:''}
          ${db.detailUrl?`<div class="panel-link-wrap"><a href="${db.detailUrl}" target="_blank" class="panel-link">↗ View on UFCStats</a></div>`:''}
        </div>
        ${buildArchetypeLearnerPanel(f.name, db, oppEntry?.db || null, f.moneyline ?? null)}
        </div>
        <div class="panel-pair">
        <div class="detail-panel">
          <div class="detail-panel-title">Lean Analysis (${EFFECTIVE_LEAN_STAT_LABEL[lean._source || 'fp'] || 'FP'})</div>
          ${fpFactorChips}
          <div class="lean-reason">${topDriversHTML}${groupedReasonsHTML}</div>
          ${lean.verdict?`<div class="lean-verdict ${lean.lean}">${lean.verdict}</div>`:''}
        </div>
        ${buildModelRivalryPanel(lean)}
        </div>
        <div class="panel-pair">
        ${buildFairValuePanel(lean)}
        ${buildPayoutEVPanel(f, lean, leanEvDetail, perBookEv)}
        </div>
        <div class="panel-pair">
        ${buildSimilarOpponentPanel(f.name, db, oppEntry?.db || null, activeLine, platformStatLine(f, 'ss'), platformStatLine(f, 'td'), platformStatLine(f, 'ctrl'), f.line_pp_ss_r1 ?? f.line_ud_ss_r1 ?? f.line_dk_ss_r1 ?? null)}
        ${buildOpponentQualityPanel(db, activeLine, platformStatLine(f, 'ss'))}
        </div>
        ${buildLineTimelinePanel(f)}
        ${buildStyleMatchupPanel(db, oppEntry?.db || null, platformStatLine(f, 'ss'), platformStatLine(f, 'td'))}
      </div>`);

  // Async fighter headshot — same cached pipeline as the H2H modal.
  // Falls back silently to the flag emoji when no image resolves.
  void fetchFighterImageUrl(f.name)
    .then(url => {
      if (!url) return;
      const av = row.querySelector('.fighter-avatar');
      const img = row.querySelector('.fighter-avatar-img') as HTMLImageElement | null;
      if (av && img) {
        img.onload = () => av.classList.add('has-img');
        img.src = url;
      }
    })
    .catch(() => { /* cosmetic only */ });

  // Country badge: DK's representing-country code wins (it's what fans expect —
  // Pereira BRA, Topuria GEO), ufc.com birthplace is the fallback.
  const dkCc = resolveFromDkMap(dkCountryByName, f.name);
  if (dkCc) {
    const badge = row.querySelector('.fighter-avatar-country');
    if (badge) { badge.textContent = dkCc; (badge as HTMLElement).title = `Representing: ${dkCc} (DK)`; }
  } else {
    void fetchFighterCountry(f.name)
      .then(c => {
        if (!c) return;
        const badge = row.querySelector('.fighter-avatar-country');
        if (badge) { badge.textContent = countryShort(c); (badge as HTMLElement).title = c; }
      })
      .catch(() => { /* cosmetic only */ });
  }

  return row;
}

function expandRowDetailPanel(row: HTMLElement): void {
  const detail = row.querySelector('.fighter-detail') as HTMLElement | null;
  if (!detail) return;
  // First expand: build the detail-panel HTML now (deferred from row creation).
  const builder = _pendingDetailBuilders.get(row);
  if (builder) {
    detail.innerHTML = builder();
    _pendingDetailBuilders.delete(row);
    // GLOW-UP 193 L5 — SIGNAL-ONLY toggle: collapse reference/history panels to
    // just the actionable leans section.
    // Two-sided add-to-slate. Deliberately does NOT call renderFighters() the way
    // the other slate buttons do — a full re-render rebuilds every row and would
    // slam this expanded card shut on each click, which is unusable when queueing
    // several sides off one fighter. Updates its own button in place instead, and
    // toasts, because My Slate's tray only exists in the Best Picks render path
    // (see GLOW-UP 198 L5 — an add from a view with no tray reads as broken).
    // GLOW-UP 225 — wiring lives in a function because the book selector replaces
    // its own subtree, and the fresh ▲▼ inside it need the same handlers.
    const wireDetailControls = (scope: ParentNode): void => {
      scope.querySelectorAll<HTMLElement>('.side-pick-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const key = btn.dataset['slateKey'] || '';
          if (!key) return;
          if (bestPicksSlate.has(key)) {
            bestPicksSlate.delete(key);
            btn.classList.remove('on');
            btn.querySelector('i')?.remove();
            showToast(`Removed from My Slate (${bestPicksSlate.size})`);
          } else {
            const d = _leanSlateData.get(key);
            if (!d) return;
            if (!bestPicksSlate.size) bestPicksSlateOpen = true;
            bestPicksSlate.set(key, d);
            btn.classList.add('on');
            if (!btn.querySelector('i')) btn.insertAdjacentHTML('beforeend', '<i>✓</i>');
            showToast(`+ ${d.clip} · My Slate (${bestPicksSlate.size})`);
          }
        });
      });
      scope.querySelectorAll<HTMLElement>('[data-book-cycle]').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const key = btn.dataset['bookCycle'] || '';
          const sep = key.lastIndexOf('|');
          if (sep < 0) return;
          const fighterName = key.slice(0, sep);
          const source = key.slice(sep + 1);
          const target = allFighters.find(x => x.name === fighterName);
          const wrap = btn.closest('.book-place') as HTMLElement | null;
          if (!target || !wrap) return;
          const books = (LEAN_STAT_FIELDS[source] || [])
            .map(([bk]) => bk)
            .filter(bk => lineForBook(target, source, bk) != null);
          if (books.length < 2) return;
          // Direction is re-derived rather than captured, so a lean that changed
          // under an open card cannot leave the selector pointed at a stale side.
          const dir = leanDirForSource(target, source);
          // Resolve what is CURRENTLY shown the same way the control does — the
          // stored choice, else the model's book, else the first. Starting from
          // the stored value alone would make the first click jump from the best
          // book to the second in table order.
          const stored = _panelBookChoice.get(key);
          const best = dir ? leanBestBook(target, source, dir).book : null;
          const shown = stored && books.includes(stored)
            ? stored
            : (best && books.includes(best) ? best : books[0]);
          const next = books[(books.indexOf(shown) + 1) % books.length];
          _panelBookChoice.set(key, next);
          wrap.outerHTML = buildBookPlacementControl(target, source, dir);
          const fresh = detail.querySelector(`[data-book-place="${CSS.escape(key)}"]`);
          if (fresh) wireDetailControls(fresh);
        });
      });
    };
    wireDetailControls(detail);

    const sigToggle = detail.querySelector('[data-signal-toggle]') as HTMLButtonElement | null;
    const grid = detail.querySelector('.detail-grid') as HTMLElement | null;
    if (sigToggle && grid) {
      sigToggle.addEventListener('click', (e) => {
        e.stopPropagation();
        const on = grid.classList.toggle('signal-only');
        sigToggle.textContent = on ? '◱ SHOW ALL' : '⚡ SIGNAL ONLY';
        sigToggle.classList.toggle('active', on);
      });
    }
  }
  // Animate bars inside the detail panel when expanding.
  // Reset bars to 0 first (in case of re-expand), then fill with stagger.
  detail.querySelectorAll<HTMLElement>('[data-fill-width]').forEach(bar => {
    bar.style.width = '0%';
  });
  requestAnimationFrame(() => {
    detail.querySelectorAll<HTMLElement>('[data-fill-width]').forEach((bar, idx) => {
      // Cap stagger total at ~350ms — past that the wave is invisible and the
      // last bar firing 3s late just feels like jank.
      const delay = Math.min(idx * 4, 350);
      setTimeout(() => { bar.style.width = bar.dataset.fillWidth!; }, delay);
    });
  });
}

// Cross-view navigation: jump from Best Picks / Line Movers to a fighter's
// card — switches to All Fighters, expands the row, scrolls, and flashes it.
function jumpToFighterCard(name: string): void {
  if (!name) return;
  const go = (attempt = 0): void => {
    const row = document.querySelector<HTMLElement>(`.fighter-row[data-name="${CSS.escape(name)}"]`);
    if (!row) {
      if (attempt < 10) setTimeout(() => go(attempt + 1), 100);
      return;
    }
    if (!row.classList.contains('expanded')) toggleRow(row);
    const y = row.getBoundingClientRect().top + window.scrollY - 150;
    window.scrollTo({ top: y, behavior: 'smooth' });
    row.classList.remove('jump-flash');
    void row.offsetWidth; // restart animation if re-triggered
    row.classList.add('jump-flash');
    setTimeout(() => row.classList.remove('jump-flash'), 1800);
  };
  if (currentView !== 'all') {
    (document.querySelector('.tab-btn[data-view="all"]') as HTMLElement | null)?.click();
    setTimeout(() => go(), 150);
  } else {
    go();
  }
}

function toggleRow(row: HTMLElement): void {
  const wasExpanded = row.classList.contains('expanded');
  const desiredExpanded = !wasExpanded;
  row.classList.toggle('expanded', desiredExpanded);
  if (desiredExpanded) expandRowDetailPanel(row);

  // Paired-row sync: inside a .fight-pair, mirror the expansion on the partner
  // row so both fighters' bar grids show simultaneously for side-by-side
  // comparison. Skips work if the partner is already in the desired state.
  const pair = row.closest('.fight-pair');
  if (pair) {
    const partner = Array.from(pair.querySelectorAll<HTMLElement>('.fighter-row')).find(r => r !== row);
    if (partner && partner.classList.contains('expanded') !== desiredExpanded) {
      partner.classList.toggle('expanded', desiredExpanded);
      if (desiredExpanded) expandRowDetailPanel(partner);
    }
  }
}

// fetchFighterImageUrl extracted to ./analyzer/fighter-image.ts —
// re-imported via the import block above.

// ── HEAD-TO-HEAD MODAL ─────────────────────────────────────────────────────
function renderH2HModal(a: AnalyzerFighter, b: AnalyzerFighter): void {
  const modal = document.getElementById('h2hModal');
  const content = document.getElementById('h2hContent');
  if (!modal || !content) return;

  const mlA = a.moneyline ?? resolveMoneylineFromMap(a.name);
  const mlB = b.moneyline ?? resolveMoneylineFromMap(b.name);
  if (mlA != null && mlB != null && mlA > mlB) {
    [a, b] = [b, a];
  }

  const da = a.db || {} as FighterDB;
  const db2 = b.db || {} as FighterDB;
  const leanA = getEffectiveLean(a);
  const leanB = getEffectiveLean(b);
  const lineA = activePlatformLine(a);
  const lineB = activePlatformLine(b);

  function leanBadge(lean: EffectiveLean): string {
    if (lean.lean === 'over') return `<span class="h2h-lean over">▲ OVER ${lean.conf}%</span>`;
    if (lean.lean === 'under') return `<span class="h2h-lean under">▼ UNDER ${lean.conf}%</span>`;
    return `<span class="h2h-lean none">—</span>`;
  }

  function ssLeanBadge(f: AnalyzerFighter): string {
    const l = f.lean_ss;
    if (!l || l.lean === 'none') return '<span class="h2h-lean none">—</span>';
    if (l.lean === 'over') return `<span class="h2h-lean over">▲ OVER ${l.conf}%</span>`;
    return `<span class="h2h-lean under">▼ UNDER ${l.conf}%</span>`;
  }

  function tdLeanBadge(f: AnalyzerFighter): string {
    const l = f.lean_td;
    if (!l || l.lean === 'none') return '<span class="h2h-lean none">—</span>';
    if (l.lean === 'over') return `<span class="h2h-lean over">▲ OVER ${l.conf}%</span>`;
    return `<span class="h2h-lean under">▼ UNDER ${l.conf}%</span>`;
  }

  // prettier-ignore
  function statRow(label: string, valA: string | number | null | undefined, valB: string | number | null | undefined, higherBetter = true): string {
    // parseFloat (vs Number) so '48%'-style values still compare + render bars
    const na = valA == null ? null : parseFloat(String(valA));
    const nb = valB == null ? null : parseFloat(String(valB));
    let clsA = '', clsB = '';
    let barHtml = '';
    if (na != null && nb != null && Number.isFinite(na) && Number.isFinite(nb)) {
      if (na !== nb) {
        const aBetter = higherBetter ? na > nb : na < nb;
        clsA = aBetter ? 'h2h-win' : 'h2h-lose';
        clsB = aBetter ? 'h2h-lose' : 'h2h-win';
      }
      // GLOW-UP 33: center-out advantage bar (dominant side fills to 100%)
      const absA = Math.abs(na), absB = Math.abs(nb);
      const maxV = Math.max(absA, absB);
      if (maxV > 0) {
        const wA = Math.round((absA / maxV) * 100);
        const wB = Math.round((absB / maxV) * 100);
        barHtml = `<tr class="h2h-bar-row"><td colspan="3"><div class="h2h-adv-track"><div class="h2h-adv-half a"><i style="width:${wA}%"></i></div><div class="h2h-adv-half b"><i style="width:${wB}%"></i></div></div></td></tr>`;
      }
    }
    const dispA = valA == null ? '—' : String(valA);
    const dispB = valB == null ? '—' : String(valB);
    return `<tr><td class="${clsA}">${dispA}</td><td class="h2h-label">${label}</td><td class="${clsB}">${dispB}</td></tr>${barHtml}`;
  }


  const ssLineA = a.line_p6_ss ?? a.line_ud_ss ?? a.line_pp_ss ?? a.line_betr_ss ?? null;
  const ssLineB = b.line_p6_ss ?? b.line_ud_ss ?? b.line_pp_ss ?? b.line_betr_ss ?? null;
  const tdLineA = a.line_p6_td ?? a.line_ud_td ?? a.line_pp_td ?? a.line_betr_td ?? null;
  const tdLineB = b.line_p6_td ?? b.line_ud_td ?? b.line_pp_td ?? b.line_betr_td ?? null;

  const avgFPA = da.avgFP_weighted ?? da.avgFP ?? null;
  const avgFPB = db2.avgFP_weighted ?? db2.avgFP ?? null;
  const avgSSA = da.avgSigStr != null ? da.avgSigStr : (da as any).avgSS ?? null;
  const avgSSB = db2.avgSigStr != null ? db2.avgSigStr : (db2 as any).avgSS ?? null;

  const moneyA = a.moneyline;
  const moneyB = b.moneyline;
  function formatML(ml: number | null | undefined): string {
    if (ml == null || !Number.isFinite(ml)) return '—';
    return ml > 0 ? `+${ml}` : String(ml);
  }

  content.innerHTML = `
    <div class="h2h-fighters">
      <div class="h2h-fighter-col h2h-side-a">
        <div class="h2h-img-wrap"><img id="h2hImgA" class="h2h-img" src="" alt="${a.name}" /></div>
        <div class="h2h-fighter-name">${a.name}</div>
        <div class="h2h-fighter-record">${da.record || '—'}</div>
      </div>
      <div class="h2h-vs">VS</div>
      <div class="h2h-fighter-col h2h-side-b">
        <div class="h2h-img-wrap"><img id="h2hImgB" class="h2h-img" src="" alt="${b.name}" /></div>
        <div class="h2h-fighter-name">${b.name}</div>
        <div class="h2h-fighter-record">${db2.record || '—'}</div>
      </div>
    </div>
    ${(() => {
      // GLOW-UP 36: DK-implied win probability, vig removed. Only renders when
      // both moneylines are present (they should be, post-DK-API pipeline).
      // Prefer DK's own vig-free trueOdds probabilities; fall back to
      // normalizing the displayed moneylines ourselves.
      const tpA = resolveFromDkMap(dkTrueProbByName, a.name);
      const tpB = resolveFromDkMap(dkTrueProbByName, b.name);
      let rawA: number, rawB: number;
      if (tpA != null && tpB != null && tpA > 0 && tpB > 0) {
        rawA = tpA; rawB = tpB;
      } else {
        const mlA = moneyA, mlB = moneyB;
        if (mlA == null || mlB == null || !Number.isFinite(mlA) || !Number.isFinite(mlB)) return '';
        const imp = (ml: number): number => ml < 0 ? (-ml) / ((-ml) + 100) : 100 / (ml + 100);
        rawA = imp(mlA); rawB = imp(mlB);
      }
      const total = rawA + rawB;
      if (!(total > 0)) return '';
      const pA = Math.round((rawA / total) * 100);
      const pB = 100 - pA;
      return `<div class="h2h-prob-strip">
        <span class="h2h-prob-val a">${pA}%</span>
        <div class="h2h-prob-track"><i class="a" style="width:${pA}%"></i><i class="b" style="width:${pB}%"></i></div>
        <span class="h2h-prob-val b">${pB}%</span>
      </div>
      <div class="h2h-prob-label">WIN PROBABILITY · DK implied, vig removed</div>`;
    })()}
    ${(() => {
      const hA = resolveFromDkMap(dkBetHandleByName, a.name);
      const hB = resolveFromDkMap(dkBetHandleByName, b.name);
      if (hA == null || hB == null) return '';
      return `<div class="h2h-prob-strip h2h-handle-strip">
        <span class="h2h-prob-val a">${hA}%</span>
        <div class="h2h-prob-track h2h-handle-track"><i class="a" style="width:${hA}%"></i><i class="b" style="width:${hB}%"></i></div>
        <span class="h2h-prob-val b">${hB}%</span>
      </div>
      <div class="h2h-prob-label">% OF BETS PLACED · DK public money</div>`;
    })()}
    <div class="h2h-common">${spineCommonOppsHTML(a, b)}</div>
    <table class="h2h-table">
      <thead><tr><th class="h2h-side-a">${a.name.split(' ').pop()}</th><th></th><th class="h2h-side-b">${b.name.split(' ').pop()}</th></tr></thead>
      <tbody>
        <tr><td>${da.style||'—'}</td><td class="h2h-label">STYLE</td><td>${db2.style||'—'}</td></tr>
        <tr><td id="h2hCountryA">—</td><td class="h2h-label">COUNTRY</td><td id="h2hCountryB">—</td></tr>
        <tr><td colspan="3" class="h2h-section-head">LINES</td></tr>
        <tr><td>${lineA != null ? lineA : '—'}</td><td class="h2h-label">FP LINE</td><td>${lineB != null ? lineB : '—'}</td></tr>
        <tr><td>${ssLineA != null ? ssLineA : '—'}</td><td class="h2h-label">SS LINE</td><td>${ssLineB != null ? ssLineB : '—'}</td></tr>
        <tr><td>${tdLineA != null ? tdLineA : '—'}</td><td class="h2h-label">TD LINE</td><td>${tdLineB != null ? tdLineB : '—'}</td></tr>
        <tr><td>${formatML(moneyA)}</td><td class="h2h-label">MONEYLINE</td><td>${formatML(moneyB)}</td></tr>
        <tr><td colspan="3" class="h2h-section-head">PROJECTIONS</td></tr>
        ${statRow('AVG FP (W)', avgFPA != null ? avgFPA.toFixed(1) : null, avgFPB != null ? avgFPB.toFixed(1) : null)}
        ${statRow('FP FLOOR', da.fpFloor != null ? da.fpFloor.toFixed(1) : null, db2.fpFloor != null ? db2.fpFloor.toFixed(1) : null)}
        ${statRow('FP CEILING', da.fpCeiling != null ? da.fpCeiling.toFixed(1) : null, db2.fpCeiling != null ? db2.fpCeiling.toFixed(1) : null)}
        ${statRow('FP STD DEV', da.fpStdDev ?? null, db2.fpStdDev ?? null, false)}
        ${statRow('CONSISTENCY', da.fpConsistency != null ? da.fpConsistency+'%' : null, db2.fpConsistency != null ? db2.fpConsistency+'%' : null)}
        <tr><td colspan="3" class="h2h-section-head">STRIKING</td></tr>
        ${statRow('AVG SIG STR', avgSSA != null ? (avgSSA as number).toFixed(1) : null, avgSSB != null ? (avgSSB as number).toFixed(1) : null)}
        ${statRow('SLpM', da.slpm != null ? da.slpm.toFixed(2) : null, db2.slpm != null ? db2.slpm.toFixed(2) : null)}
        ${statRow('STR ACC %', da.strAcc != null ? da.strAcc+'%' : null, db2.strAcc != null ? db2.strAcc+'%' : null)}
        ${statRow('STR DEF %', da.strDef != null ? da.strDef+'%' : null, db2.strDef != null ? db2.strDef+'%' : null)}
        <tr><td colspan="3" class="h2h-section-head">GRAPPLING</td></tr>
        ${statRow('TD AVG/15', da.avgTD != null ? da.avgTD.toFixed(2) : null, db2.avgTD != null ? db2.avgTD.toFixed(2) : null)}
        ${statRow('TD ACC %', da.tdAcc != null ? da.tdAcc+'%' : null, db2.tdAcc != null ? db2.tdAcc+'%' : null)}
        ${statRow('TD DEF %', da.tdDef != null ? da.tdDef+'%' : null, db2.tdDef != null ? db2.tdDef+'%' : null)}
        <tr><td colspan="3" class="h2h-section-head">LEANS</td></tr>
        <tr><td>${leanBadge(leanA)}</td><td class="h2h-label">FP LEAN</td><td>${leanBadge(leanB)}</td></tr>
        <tr><td>${ssLeanBadge(a)}</td><td class="h2h-label">SS LEAN</td><td>${ssLeanBadge(b)}</td></tr>
        <tr><td>${tdLeanBadge(a)}</td><td class="h2h-label">TD LEAN</td><td>${tdLeanBadge(b)}</td></tr>
        ${da.finishRate != null || db2.finishRate != null ? statRow('FINISH RATE', da.finishRate != null ? Math.round(da.finishRate*100)+'%' : null, db2.finishRate != null ? Math.round(db2.finishRate*100)+'%' : null) : ''}
      </tbody>
    </table>`;

  modal.classList.remove('is-hidden');

  // Async load fighter images
  void Promise.all([fetchFighterImageUrl(a.name), fetchFighterImageUrl(b.name)]).then(([urlA, urlB]) => {
    const imgA = document.getElementById('h2hImgA') as HTMLImageElement | null;
    const imgB = document.getElementById('h2hImgB') as HTMLImageElement | null;
    if (imgA && urlA) { imgA.src = urlA; imgA.style.display = 'block'; }
    if (imgB && urlB) { imgB.src = urlB; imgB.style.display = 'block'; }
    // Country names from the same athlete pages
    void fetchFighterCountry(a.name).then(c => { const el = document.getElementById('h2hCountryA'); if (el && c) el.textContent = c; });
    void fetchFighterCountry(b.name).then(c => { const el = document.getElementById('h2hCountryB'); if (el && c) el.textContent = c; });
  });
}

// ── DATA LOADING ──────────────────────────────────────────────────────────
// NAME_ALIASES now lives in config/index.ts (shared with background.ts's settle
// path). Add new aliases there, not here.

function normalizeName(name: string|null|undefined): string|null {
  if (!name || name === 'null' || name === 'undefined') return null;
  let n = name.replace(/[\u200B-\u200D\uFEFF\u00AD]/g, '').trim();
  // Strip diacritics so "Vin\u00EDcius" matches "Vinicius" (UFCStats/card uses plain ASCII).
  n = n.normalize('NFD').replace(/[\u0300-\u036F]/g, '');
  // Drop platform country tags like "Andre (Bra) Lima" \u2192 "Andre Lima".
  n = n.replace(/\([^)]*\)/g, ' ');
  n = n.replace(/\./g, '').replace(/-/g, ' ').replace(/'/g, '').replace(/\s+/g, ' ').trim();
  n = n.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
  return NAME_ALIASES[n] || n;
}

function dedup(str: string): string { return str.replace(/(.)\1+/g, '$1'); }

function namesMatch(a: string, b: string): boolean {
  if (a === b) return true;
  const aParts = a.split(' '), bParts = b.split(' ');
  const aFirst = aParts[0], aLast = aParts[aParts.length - 1];
  const bFirst = bParts[0], bLast = bParts[bParts.length - 1];
  if (aLast === bLast && aFirst[0] === bFirst[0]) return true;
  // Family-name-first reversal: platforms list Chinese fighters in Western order
  // ("Xiaonan Yan") where UFCStats uses Chinese order ("Yan Xiaonan"). The two tokens
  // are the SAME two tokens swapped, which is unambiguous identity — background.ts's
  // strictCardNameMatch has had this rule since the Cong Wang split; namesMatch never
  // got it, so every such fighter needed a hand-written NAME_ALIASES entry and only
  // ever got one AFTER a ghost row appeared on a live card (Yan Xiaonan and Liu Ce,
  // 2026-08-25). Requires an EXACT two-token swap, so it cannot merge distinct people.
  if (aParts.length === 2 && bParts.length === 2 && aFirst === bLast && aLast === bFirst) return true;
  if (dedup(a.toLowerCase()) === dedup(b.toLowerCase())) return true;
  if (aLast === bLast && (aFirst.startsWith(bFirst) || bFirst.startsWith(aFirst))) return true;
  if (a.startsWith(b + ' ') || b.startsWith(a + ' ')) return true;
  // Shared surname alone is NOT identity when both sides have full, differing
  // first names: "Michael Chandler" ≠ "Chelsea Chandler". Only treat a surname
  // match as the same fighter when one first name is an abbreviation/initial
  // (e.g. "C Chandler" → "Chelsea Chandler") or the initials agree.
  if (aLast === bLast && aLast.length > 4) {
    // An abbreviation is exactly ONE character. normalizeName strips periods
    // ("T. Miller" → "T Miller"), so a real initial is always length 1 — while
    // `<= 2` swept in genuine two-letter first names: Ty, Bo, Al, Ed, Su, Yu, Li.
    // That made "Ty Miller" indistinguishable from ANY Miller, so on the
    // Gamrot/Salkilld card the board consumed JULIANA Miller as Ty Miller,
    // paired her with Billy Ray Goff and left Ravena Oliveira unpaired.
    const aAbbrev = aFirst.length === 1 || aFirst.endsWith('.');
    const bAbbrev = bFirst.length === 1 || bFirst.endsWith('.');
    if (aAbbrev || bAbbrev || aFirst[0] === bFirst[0]) return true;
  }
  return false;
}

function resolveFromDkMap<T>(map: Record<string, T>, name: string): T | null {
  const normalized = normalizeName(name);
  if (!normalized) return null;
  if (map[normalized] !== undefined) return map[normalized];
  for (const [k, v] of Object.entries(map)) {
    if (namesMatch(k, normalized)) return v;
  }
  return null;
}

function resolveMoneylineFromMap(name: string): number | null {
  const normalized = normalizeName(name);
  if (!normalized) return null;
  const direct = fightOddsMoneylineByName[normalized];
  if (Number.isFinite(direct)) return direct;

  for (const [oddsName, odds] of Object.entries(fightOddsMoneylineByName)) {
    if (namesMatch(oddsName, normalized)) return odds;
  }
  return null;
}

