interface RuntimeLineDropItem {
  platform?: string;
  type?: string;
  count?: number;
  fighter?: string;
  from?: number;
  to?: number;
  delta?: number;
}

interface RuntimeAnalyzerMessage {
  type?: 'LINES_DROPPED' | 'LINES_UPDATED' | string;
  drops?: RuntimeLineDropItem[];
  platform?: string;
  count?: number;
  event?: string;
  udCount?: number;
  p6Count?: number;
}

function toWatchPlatform(value: string | undefined): WatchPlatform {
  const normalized = String(value || 'underdog').toLowerCase();
  if (normalized.includes('pick6')) return 'pick6';
  if (normalized.includes('betr')) return 'betr';
  if (normalized.includes('prize')) return 'prizepicks';
  return 'underdog';
}

function toWatchedStat(value: string | undefined): WatchedStatType {
  const normalized = String(value || 'fp').toLowerCase();
  if (normalized.includes('ss')) return 'ss';
  if (normalized.includes('td')) return 'td';
  return 'fp';
}

// ── CHROME MESSAGE LISTENER ───────────────────────────────────────────────
if (typeof chrome !== 'undefined' && chrome.runtime?.onMessage) {
  chrome.runtime.onMessage.addListener((msg: RuntimeAnalyzerMessage) => {
    if (msg.type === 'LINES_DROPPED') {
      showLineDropAlert(msg);
      setWatcherVisualState('detected', 'Line Alert');
      const ts = Date.now();
      const converted: LineMovementEvent[] = (msg.drops || []).map((d, i: number) => ({
        id: `bg-${ts}-${i}`,
        timestamp: ts,
        fighter: d.fighter || 'Multiple fighters',
        platform: toWatchPlatform(d.platform),
        stat: toWatchedStat(d.type),
        from: Number(d.from ?? 0),
        to: Number(d.to ?? 0),
        delta: Number(d.delta ?? -1),
        direction: Number(d.delta ?? -1) < 0 ? 'drop' : 'rise',
      }));
      if (converted.length) {
        recentLineMoves = [...converted, ...recentLineMoves].slice(0, 120);
        renderLineMoveFeed();
      }
      requestDataReload(1500);
    }
    if (msg.type === 'LINES_UPDATED') {
      console.log('[UFC Analyzer] Lines updated:', msg.platform, msg.count);
      requestDataReload();
    }
    if (msg.type === 'ODDS_UPDATED') {
      console.log('[UFC Analyzer] Odds updated:', msg.count);
      requestDataReload();
    }
    if (msg.type === 'BET_HANDLE_UPDATED') {
      console.log('[UFC Analyzer] Bet-handle updated:', msg.count);
      requestDataReload();
    }
    if (msg.type === 'ARCHIVE_SETTLED') {
      _confidenceMemoryCache = null;
      const settled = (msg as any).settled ?? 0;
      showToast(`✓ Archive settled: ${settled} result${settled !== 1 ? 's' : ''} updated`);
      // If archive or calibration panel is open, re-render it
      if (currentView === 'archive' || currentView === 'calibration') {
        const container = document.getElementById('cardContainer');
        if (container) {
          if (currentView === 'archive') void renderArchivePanel(container);
          else void renderCalibrationPanel(container);
        }
      }
    }
  });
}

function showLineDropAlert(msg: RuntimeAnalyzerMessage): void {
  const banner = document.getElementById('lineDropBanner');
  const txt    = document.getElementById('lineDropText');
  if (!banner) return;
  const event = msg.event || 'Upcoming UFC Event';
  const dropSummary = (msg.drops || [])
    .map((d) => `${d.platform} ${d.type} (${d.count} fighters)`)
    .join(' · ') || `${msg.udCount || 0} fighters on Underdog`;
  if (txt) txt.innerHTML = `🔔 <strong>LINES DROPPED!</strong> &nbsp;${event} — ${dropSummary}. Auto-loading now...`;
  banner.style.display = 'flex';
  banner.style.animation = 'pulseAlert 0.5s ease-in-out 3';
  setTimeout(() => { banner.style.display = 'none'; }, 25000);
}

function parseEventDateMs(raw: string): number {
  if (!raw) return NaN;
  // UFCStats uses "Apr. 4, 2026" — strip the period so V8 can parse it.
  const normalized = raw.replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\./gi, '$1');
  const direct = new Date(normalized).getTime();
  if (Number.isFinite(direct)) return direct;
  const fallback = new Date(`${normalized} UTC`).getTime();
  return Number.isFinite(fallback) ? fallback : NaN;
}

function toIsoDateOrNull(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const ts = Date.parse(raw);
  if (Number.isFinite(ts)) return new Date(ts).toISOString();
  return null;
}

function rosterNameSet(): Set<string> {
  const set = new Set<string>();
  for (const f of allFighters) {
    const n = normalizeName(f.name);
    if (n) set.add(n.toLowerCase());
  }
  return set;
}

// ── CTRL archive units ───────────────────────────────────────────────────
// UFCStats gives control time in SECONDS; every CTRL *line* is in MINUTES, and
// the settle path has always converted (background.ts, `ctrlMins`). This backfill
// did not — it wrote raw seconds under the same `Control` propType, so the two
// writers disagreed by 60x on the same rows. FightTime, written on the very next
// line here, has always done the divide; Control was simply missed.
//
// It bit through PropArchiveService.updateResult: once an event lands in fighters'
// UFCStats history, the backfill OVERWRITES the settled minutes with seconds, and
// resolveVsArchive then grades placed CTRL legs against it — an OVER reads as a hit
// and an UNDER as a miss whatever actually happened. Rounded to 2dp to match the
// settle path exactly so the two can't differ by a rounding either.
const ctrlMinsOf = (secs: number | null | undefined): number =>
  Math.round((Number(secs) / 60) * 100) / 100;

async function archivePerformanceForRosterFighter(name: string, ufcData: UFCStatsData | null): Promise<void> {
  if (!ufcData?.fightHistory?.length) return;

  const fighterNorm = normalizeName(name);
  if (!fighterNorm) return;

  const roster = rosterNameSet();
  if (!roster.has(fighterNorm.toLowerCase())) return;

  const records: PropArchiveRecord[] = [];

  for (const fight of ufcData.fightHistory) {
    const dateIso = toIsoDateOrNull(fight.date);
    if (!dateIso) continue;
    const eventName = String(fight.event || '').trim();
    if (!eventName) continue;

    const opponent = normalizeName(fight.opponent) || fight.opponent || 'Unknown Opponent';
    const won = fight.result === 'win';

    if (fight.sigStr != null || fight.totStr != null || fight.kd != null || fight.td != null || fight.ctrlSecs != null) {
      const fantasy = calcFPForPlatform('pick6', fight.sigStr, fight.totStr, fight.ctrlSecs, fight.timeSecs, fight.kd, fight.td, fight.rev, fight.sub, won, fight.method, fight.round);
      const fantasyPP = calcFPForPlatform('prizepicks', fight.sigStr, fight.totStr, fight.ctrlSecs, fight.timeSecs, fight.kd, fight.td, fight.rev, fight.sub, won, fight.method, fight.round);
      records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'Fantasy', result: fantasy });
      records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'Fantasy_PP', result: fantasyPP });
      if (fight.sigStr != null) records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'SS', result: Number(fight.sigStr) });
      if (fight.td != null) records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'TD', result: Number(fight.td) });
      if (fight.ctrlSecs != null) records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'Control', result: ctrlMinsOf(fight.ctrlSecs) });
      if (fight.timeSecs != null) records.push({ fighter: fighterNorm, opponent, event: eventName, date: dateIso, propType: 'FightTime', result: parseFloat((Number(fight.timeSecs) / 60).toFixed(2)) });

      await PropArchiveService.updateResult(fighterNorm, eventName, 'Fantasy', fantasy, { date: dateIso, opponent });
      await PropArchiveService.updateResult(fighterNorm, eventName, 'Fantasy_PP', fantasyPP, { date: dateIso, opponent });
      if (fight.sigStr != null) await PropArchiveService.updateResult(fighterNorm, eventName, 'SS', Number(fight.sigStr), { date: dateIso, opponent });
      if (fight.td != null) await PropArchiveService.updateResult(fighterNorm, eventName, 'TD', Number(fight.td), { date: dateIso, opponent });
      if (fight.ctrlSecs != null) await PropArchiveService.updateResult(fighterNorm, eventName, 'Control', ctrlMinsOf(fight.ctrlSecs), { date: dateIso, opponent });
      if (fight.timeSecs != null) await PropArchiveService.updateResult(fighterNorm, eventName, 'FightTime', parseFloat((Number(fight.timeSecs) / 60).toFixed(2)), { date: dateIso, opponent });
    }

    const oppStats = fight.oppStats;
    const oppName = normalizeName(oppStats?.oppName || opponent) || String(oppStats?.oppName || opponent || 'Unknown Opponent');
    if (oppStats && (oppStats.sigStr != null || oppStats.td != null || oppStats.kd != null || oppStats.ctrlSecs != null)) {
      const oppWon = fight.result === 'loss';
      const oppFantasy = calcFPForPlatform('pick6', oppStats.sigStr, oppStats.totStr, oppStats.ctrlSecs, fight.timeSecs, oppStats.kd, oppStats.td, null, oppStats.sub, oppWon, fight.method, fight.round);
      const oppFantasyPP = calcFPForPlatform('prizepicks', oppStats.sigStr, oppStats.totStr, oppStats.ctrlSecs, fight.timeSecs, oppStats.kd, oppStats.td, null, oppStats.sub, oppWon, fight.method, fight.round);
      records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'Fantasy', result: oppFantasy });
      records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'Fantasy_PP', result: oppFantasyPP });
      if (oppStats.sigStr != null) records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'SS', result: Number(oppStats.sigStr) });
      if (oppStats.td != null) records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'TD', result: Number(oppStats.td) });
      if (oppStats.ctrlSecs != null) records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'Control', result: ctrlMinsOf(oppStats.ctrlSecs) });
      if (fight.timeSecs != null) records.push({ fighter: oppName, opponent: fighterNorm, event: eventName, date: dateIso, propType: 'FightTime', result: parseFloat((Number(fight.timeSecs) / 60).toFixed(2)) });

      await PropArchiveService.updateResult(oppName, eventName, 'Fantasy', oppFantasy, { date: dateIso, opponent: fighterNorm });
      await PropArchiveService.updateResult(oppName, eventName, 'Fantasy_PP', oppFantasyPP, { date: dateIso, opponent: fighterNorm });
      if (oppStats.sigStr != null) await PropArchiveService.updateResult(oppName, eventName, 'SS', Number(oppStats.sigStr), { date: dateIso, opponent: fighterNorm });
      if (oppStats.td != null) await PropArchiveService.updateResult(oppName, eventName, 'TD', Number(oppStats.td), { date: dateIso, opponent: fighterNorm });
      if (oppStats.ctrlSecs != null) await PropArchiveService.updateResult(oppName, eventName, 'Control', ctrlMinsOf(oppStats.ctrlSecs), { date: dateIso, opponent: fighterNorm });
      if (fight.timeSecs != null) await PropArchiveService.updateResult(oppName, eventName, 'FightTime', parseFloat((Number(fight.timeSecs) / 60).toFixed(2)), { date: dateIso, opponent: fighterNorm });
    }
  }

  if (!records.length) return;
  await PropArchiveService.addProps(records);
}

async function runArchiveBackfillPass(): Promise<void> {
  try {
    const summary = await PropArchiveService.backfillUnresolvedFromKnownOutcomes({
      eventIncludes: 'ufc',
      maxScore: 12,
      minHoursBetweenRuns: 6,
    });
    if (summary.changed > 0) {
      debugLog(`[Archive Backfill] settled ${summary.changed} rows (${summary.unresolvedBefore} -> ${summary.unresolvedAfter})`);
    }
  } catch (e) {
    debugLog(`[Archive Backfill] failed: ${(e as Error).message}`);
  }
}

// ── LINE WATCHER SERVICE ──────────────────────────────────────────────────

interface WatcherStatusElements {
  statusEl: HTMLElement | null;
  pollBadge: HTMLElement | null;
  lastBadge: HTMLElement | null;
}

function getWatcherStatusElements(): WatcherStatusElements {
  return {
    statusEl: document.getElementById('watcherStatus'),
    // Removed pollBadge and lastBadge UI
    pollBadge: null,
    lastBadge: null,
  };
}

type WatcherVisualState = 'idle'|'watching'|'detected'|'error';

interface WatcherSnapshotPoint {
  fighter: string;
  platform: WatchPlatform;
  stat: WatchedStatType;
  value: number;
}

function setWatcherVisualState(state: WatcherVisualState, text?: string): void {
  const btn = document.getElementById('watcherToggleBtn');
  const txt = document.getElementById('watcherToggleText');
  if (!btn) return;
  btn.classList.remove('state-idle', 'state-watching', 'state-detected', 'state-error');
  btn.classList.add(`state-${state}`);
  if (txt) {
    txt.textContent = text || (state === 'watching' ? 'Watching' : state === 'detected' ? 'Line Alert' : state === 'error' ? 'Watch Error' : 'Watch Lines');
  }
}

// Inline SVG sparkline for LINE MOVERS rows and the fight spine. Returns a
// string of SVG markup (so it can be inlined into innerHTML) or '' when there
// are fewer than 2 points worth plotting. Pure render — no storage access.
// opts.color overrides the direction-derived stroke (used by spine L5 trends
// for per-fighter cyan/yellow). opts.w/h override the default 90×18 box.
function renderSparkline(
  points: Array<{ t: number; v: number }>,
  direction: 'up' | 'down' | 'auto' = 'auto',
  opts?: { color?: string; w?: number; h?: number; area?: boolean; glow?: boolean },
): string {
  if (!points || points.length < 2) return '';
  const w = opts?.w ?? 90, h = opts?.h ?? 18, pad = 2;
  const values = points.map(p => p.v);
  const min = Math.min(...values), max = Math.max(...values);
  const range = max - min || 1;
  const xs: number[] = [];
  const ys: number[] = [];
  for (let i = 0; i < values.length; i++) {
    const x = pad + (i / (values.length - 1)) * (w - pad * 2);
    const y = pad + (1 - (values[i] - min) / range) * (h - pad * 2);
    xs.push(x);
    ys.push(y);
  }
  const coords = xs.map((x, i) => `${x.toFixed(1)},${ys[i].toFixed(1)}`).join(' ');
  const dir = direction === 'auto'
    ? (values[values.length - 1] >= values[0] ? 'up' : 'down')
    : direction;
  const stroke = opts?.color ?? (dir === 'up' ? '#5ee589' : '#ff5a73');
  const x0 = xs[0].toFixed(1), y0 = ys[0].toFixed(1);
  const x1 = xs[xs.length - 1].toFixed(1), y1 = ys[ys.length - 1].toFixed(1);
  const areaHTML = opts?.area
    ? `<polygon points="${x0},${(h - 1).toFixed(1)} ${coords} ${x1},${(h - 1).toFixed(1)}" fill="${stroke}" opacity="0.1"/>`
    : '';
  const glowHTML = opts?.glow ? `<circle cx="${x1}" cy="${y1}" r="4" fill="${stroke}" opacity="0.22"/>` : '';
  return `<svg class="line-sparkline" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true">`
    + areaHTML
    + `<polyline points="${coords}" stroke="${stroke}" stroke-width="1.5" fill="none" stroke-linejoin="round" stroke-linecap="round"/>`
    + `<circle cx="${x0}" cy="${y0}" r="1.8" fill="#6c7080"/>`
    + glowHTML
    + `<circle cx="${x1}" cy="${y1}" r="1.8" fill="${stroke}"/>`
    + `</svg>`;
}

// Extract a per-platform timeline from _lineHistory for (name, stat, platKey).
// _lineHistory.series stores [{t, v: Record<plat, number>}] — we project out
// the requested platform and drop points where that platform was missing.
function getSparklinePointsForPlat(
  name: string,
  stat: string,
  platKey: string,
): Array<{ t: number; v: number }> {
  const series = _lineHistory.series[lineHistoryKey(name, stat)];
  if (!series || series.length === 0) return [];
  const out: Array<{ t: number; v: number }> = [];
  for (const pt of series) {
    const v = pt.v?.[platKey];
    if (typeof v === 'number' && Number.isFinite(v)) out.push({ t: pt.t, v });
  }
  return out;
}

// ── GLOW-UP 201 — LINE MOVERS ─────────────────────────────────────────────
// The board reported that lines moved but never what the move was worth to YOU.
// Every number below already existed: the deltas were computed, the sub-leans
// were computed, they just never met. The one new concept is `priceMove`.
type MoverFilter = 'all' | 'steam' | 'rlm' | 'lean' | 'better' | 'worse';
let _moverFilter: MoverFilter = 'all';
let _moversShowAll = false;
const MOVERS_COLLAPSED_LIMIT = 20;

// Minimum |delta| for a book to count as having moved, per stat. FP/SS/TD/FT
// keep the flat 1.0 this board has always used — retuning them would silently
// rewrite a surface that gets read every card. The stats added in GLOW-UP 201
// sit on much smaller scales (KD lines are 0.5–1.5, CTRL is minutes), so a 1.0
// floor would mean they never appeared at all.
const MOVER_MIN_DELTA: Record<string, number> = {
  fp: 1.0, ss: 1.0, td: 1.0, ft: 1.0, ss_r1: 1.0, ctrl: 0.5, kd: 0.5,
};

// The RLM heuristic's thresholds (±1.0 / ±2.0) were calibrated on FP/SS-sized
// lines. Applying them to CTRL or KD would either never fire or fire on noise,
// so reverse-line-movement stays scoped to the four stats it was built for.
const RLM_STATS = new Set(['fp', 'ss', 'td', 'ft']);

type SummaryEntry = {
  name: string; stat: string; statLabel: string;
  delta: number; open: number; close: number;
  sourcePlat: string; sourcePlatKey: string;
  platforms: string[];
  isSteam: boolean;
  rlm: 'under' | 'over' | null;
  leanDir: 'over' | 'under' | null;
  /**
   * Whether the move helped or hurt the number you'd be taking, NOT whether the
   * market agrees with you. A rising line makes the UNDER easier and the OVER
   * harder — mechanical, no market-psychology claim attached. (The psychology
   * read is what `rlm` already covers, and the two can point opposite ways.)
   */
  priceMove: 'better' | 'worse' | null;
  slipKey: string | null;
  slipClip: string;
};

function renderLineMovementSummary(): void {
  const container = document.getElementById('lineMovementSummary');
  const body = document.getElementById('movementSummaryBody');
  const timeEl = document.getElementById('movementSummaryTime');
  const miniEl = document.getElementById('movementSummaryMini');
  if (!container || !body) return;

  const entries: SummaryEntry[] = [];
  // Pick-em platforms where "public hammers OVER" heuristic applies. DK is a
  // sportsbook with juice, so its moves don't fit the same public-default model.
  const PICKEM_PLATS = new Set(['p6', 'ud', 'pp', 'betr']);

  for (const f of allFighters) {
    const effLean = getEffectiveLean(f);
    for (const [stat, plats] of LINE_STAT_BY_STAT) {
      const minDelta = MOVER_MIN_DELTA[stat] ?? 1.0;
      let maxDelta = 0;
      let maxOpen: number | null = null;
      let maxClose: number | null = null;
      let maxPlatLabel = '';
      let maxPlatKey = '';
      const movedPlats: string[] = [];
      // RLM roll-up: count pick-em platforms moving against the public OVER flow.
      let pickemRise = 0, pickemDrop = 0, maxPickemRise = 0, maxPickemDrop = 0;
      for (const [plat, get] of plats) {
        const current = get(f);
        if (current == null) continue;
        const key = openingLineKey(plat, stat, f.name);
        const opening = _openingLines.get(key);
        if (opening == null) continue;
        const deltaRaw = parseFloat((current - opening).toFixed(1));
        const delta = sanitizeDelta(stat, deltaRaw);
        if (delta != null && Math.abs(delta) >= minDelta) {
          const platLabel = statPlatLabel(plat);
          movedPlats.push(platLabel);
          if (Math.abs(delta) > Math.abs(maxDelta)) {
            maxDelta = delta;
            maxOpen = opening;
            maxClose = current;
            maxPlatLabel = platLabel;
            maxPlatKey = plat;
          }
        }
        if (delta != null && RLM_STATS.has(stat) && PICKEM_PLATS.has(plat)) {
          if (delta >= 1.0) { pickemRise++; if (delta > maxPickemRise) maxPickemRise = delta; }
          if (delta <= -2.0) { pickemDrop++; if (delta < maxPickemDrop) maxPickemDrop = delta; }
        }
      }
      let rlm: 'under' | 'over' | null = null;
      // RLM is a claim that books moved AGAINST the public's OVER default. One
      // book moving is not evidence of that — it's just a line moving, which the
      // row already says. The old rule fired on a single book and on a
      // single-book slate tagged EVERY mover, making the signal synonymous with
      // "moved". Two pick-em books have to agree on the direction now.
      // Consequence, and it is the correct one: when fewer than two pick-em
      // books have posted, RLM cannot fire at all. The header says so rather
      // than leaving a bare zero — see rlmUnavailableNote.
      if (pickemRise >= 2 && maxPickemRise >= 1.0) rlm = 'under';
      // OVER: deep drop agreed by ≥2 pick-em platforms, plus meaningful magnitude.
      else if (pickemDrop >= 2 && Math.abs(maxPickemDrop) >= 2.0) rlm = 'over';
      if (movedPlats.length > 0 && maxOpen != null && maxClose != null) {
        // L2 — the sub-lean scored on THIS stat, not the fighter's headline play.
        // A fighter can lean FT-under overall while their SS line is the one that
        // moved; reading the FT lean against an SS move would be a lie.
        const statLean = leanForStat(f, stat);
        const leanDir = statLean?.lean === 'over' || statLean?.lean === 'under' ? statLean.lean : null;
        const priceMove: 'better' | 'worse' | null = leanDir == null
          ? null
          : (maxDelta > 0) === (leanDir === 'under') ? 'better' : 'worse';

        // L5 — the slip button is offered ONLY when the moved stat is the play
        // the rest of the app would actually hand you: the effective lean's
        // source, which is already placeability-gated by _computeEffectiveLean.
        // Building a pick out of any directional sub-lean would happily queue an
        // unplaceable side that no book will take.
        let slipKey: string | null = null;
        let slipClip = '';
        if ((effLean._source || 'fp') === stat && (effLean.lean === 'over' || effLean.lean === 'under')) {
          const built = buildLeanSlatePick(f, effLean);
          _leanSlateData.set(built.key, built.pick);
          slipKey = built.key;
          slipClip = built.pick.clip;
        }

        entries.push({
          name: f.name,
          stat,
          statLabel: statDisplayLabel(stat),
          delta: maxDelta,
          open: maxOpen,
          close: maxClose,
          sourcePlat: maxPlatLabel,
          sourcePlatKey: maxPlatKey,
          platforms: movedPlats,
          isSteam: movedPlats.length >= 2 && Math.abs(maxDelta) >= 2.0,
          rlm,
          leanDir,
          priceMove,
          slipKey,
          slipClip,
        });
      }
    }
  }

  if (entries.length === 0) {
    container.style.display = 'none';
    if (miniEl) miniEl.textContent = '';
    return;
  }

  entries.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
  container.style.display = '';

  // ── L1: roll-ups over the WHOLE set, not the visible slice ──────────────
  const totalRise = entries.filter(e => e.delta > 0).length;
  const totalDrop = entries.length - totalRise;
  const steamCount = entries.filter(e => e.isSteam).length;
  const rlmCount = entries.filter(e => e.rlm).length;
  // How many pick-em books actually posted something RLM can read. Below two,
  // the rule can never fire, and a bare "0 RLM" would read as a quiet slate
  // rather than an unmeasurable one — same principle as GLOW-UP 199's empty
  // states: say WHICH kind of zero this is.
  const livePickem = [...PICKEM_PLATS].filter(p =>
    LINE_STAT_ACCESSORS.some(([plat, stat, get]) =>
      plat === p && RLM_STATS.has(stat) && allFighters.some(f => get(f) != null)));
  const rlmBlocked = livePickem.length < 2;
  const rlmNote = rlmBlocked
    ? `Not measurable on this slate: reverse line movement means books disagreeing with public OVER flow, which needs two pick-em books to compare. ${livePickem.length === 1 ? `Only ${statPlatLabel(livePickem[0])} has posted.` : 'No pick-em book has posted.'}`
    : 'Two or more pick-em books moved the same way against the public OVER default (FP/SS/TD/FT only — the thresholds are calibrated for those scales)';
  const leanCount = entries.filter(e => e.leanDir).length;
  const betterCount = entries.filter(e => e.priceMove === 'better').length;
  const worseCount = entries.filter(e => e.priceMove === 'worse').length;
  const biggest = entries[0];

  const acceptsFilter = (e: SummaryEntry): boolean => {
    switch (_moverFilter) {
      case 'steam':  return e.isSteam;
      case 'rlm':    return e.rlm != null;
      case 'lean':   return e.leanDir != null;
      case 'better': return e.priceMove === 'better';
      case 'worse':  return e.priceMove === 'worse';
      default:       return true;
    }
  };
  const filtered = entries.filter(acceptsFilter);
  const shown = _moversShowAll ? filtered : filtered.slice(0, MOVERS_COLLAPSED_LIMIT);
  const risers = shown.filter(e => e.delta > 0);
  const drifters = shown.filter(e => e.delta < 0);

  const statChip = (cls: string, label: string, value: string, title: string): string =>
    `<span class="mvs-stat ${cls}" title="${title.replace(/"/g, '&quot;')}"><b>${value}</b> ${label}</span>`;

  const headerHtml = `<div class="mvs-cmd">
    <div class="mvs-cmd-stats">
      ${statChip('', 'movers', String(entries.length), 'Fighter/stat pairs whose line has moved from its opening baseline on at least one book')}
      ${statChip('mvs-c-rise', '▲', String(totalRise), 'Lines that rose above their opening number')}
      ${statChip('mvs-c-drop', '▼', String(totalDrop), 'Lines that dropped below their opening number')}
      ${steamCount ? statChip('mvs-c-steam', 'steam', String(steamCount), 'Moved ≥2.0 on two or more books — books agreeing is a stronger signal than one book drifting') : ''}
      ${rlmCount ? statChip('mvs-c-rlm', 'RLM', String(rlmCount), rlmNote)
        : rlmBlocked ? statChip('mvs-c-na', 'RLM', 'n/a', rlmNote) : ''}
      ${betterCount ? statChip('mvs-c-better', 'better', String(betterCount), 'Moves that improved the number on a stat you lean — you would now be taking a friendlier line than at open') : ''}
      ${worseCount ? statChip('mvs-c-worse', 'worse', String(worseCount), 'Moves that eroded the number on a stat you lean — the good price is gone') : ''}
      ${biggest ? `<span class="mvs-top" title="Largest absolute move on the board">TOP <b>${prettyName(biggest.name)}</b> ${biggest.statLabel} ${biggest.delta > 0 ? '▲' : '▼'}${Math.abs(biggest.delta)}</span>` : ''}
    </div>
    <div class="mvs-filters">
      ${([
        ['all', 'ALL', `Every mover (${entries.length})`],
        ['steam', 'STEAM', `Multi-book agreement (${steamCount})`],
        ['rlm', 'RLM', rlmBlocked ? rlmNote : `Reverse line movement (${rlmCount})`],
        ['lean', 'MY LEANS', `Movement on a stat you actually lean (${leanCount})`],
        ['better', '↑ BETTER', `Your number improved (${betterCount})`],
        ['worse', '↓ WORSE', `Your number eroded (${worseCount})`],
      ] as Array<[MoverFilter, string, string]>).map(([k, label, title]) =>
        `<button class="mvs-filter${_moverFilter === k ? ' on' : ''}" data-mover-filter="${k}" title="${title.replace(/"/g, '&quot;')}${_moverFilter === k && k !== 'all' ? ' — click again to clear' : ''}">${label}</button>`
      ).join('')}
    </div>
  </div>`;

  const rowHtml = (e: SummaryEntry): string => {
    const arrow = e.delta > 0 ? '▲' : '▼';
    const cls = e.delta > 0 ? 'rise' : 'drop';
    const steamTag = e.isSteam ? '<span class="movement-summary-steam">STEAM</span>' : '';
    const rlmTag = e.rlm
      ? `<span class="rlm-tag rlm-${e.rlm}" title="Reverse line movement — ${e.rlm === 'under' ? 'rising against public OVER default → sharp UNDER flow' : 'deep drop below open → heavy OVER action'}">RLM ${e.rlm.toUpperCase()}</span>`
      : '';
    // L2 — what the move did to the price of the side you lean.
    const priceTag = e.priceMove
      ? `<span class="mvs-price mvs-price-${e.priceMove}" title="You lean ${e.leanDir?.toUpperCase()} on ${e.statLabel}. The line ${e.delta > 0 ? 'rose' : 'dropped'} ${e.open}→${e.close}, which makes the ${e.leanDir?.toUpperCase()} ${e.priceMove === 'better' ? 'EASIER than it was at open — the move is in your favour' : 'HARDER than it was at open — you have missed the better number'}.">${e.priceMove === 'better' ? '↑ BETTER' : '↓ WORSE'}</span>`
      : '';
    const sparkPoints = e.sourcePlatKey ? getSparklinePointsForPlat(e.name, e.stat, e.sourcePlatKey) : [];
    const sparkHtml = sparkPoints.length >= 2
      ? `<span class="movement-summary-spark" title="${e.sourcePlat} ${e.statLabel} — ${sparkPoints.length} points over ${Math.round((sparkPoints[sparkPoints.length-1].t - sparkPoints[0].t) / 60000)}m">${renderSparkline(sparkPoints, e.delta > 0 ? 'up' : 'down')}</span>`
      : '';
    const platChips = e.platforms.map(p => `<span class="mvp-chip mvp-${p.toLowerCase()}" title="Moved on ${p}">${p}</span>`).join('');
    // L5 — same key and staging pathway as Best Picks and the slate view, so a pick
    // added from here is the SAME slate entry and the surfaces dedupe.
    const slipBtn = e.slipKey
      ? `<button class="mvs-slate-btn${bestPicksSlate.has(e.slipKey) ? ' on' : ''}" data-slate-key="${e.slipKey.replace(/"/g, '&quot;')}" title="${bestPicksSlate.has(e.slipKey) ? 'Remove from My Slate' : `Add to My Slate — ${e.slipClip.replace(/"/g, '&quot;')}`}">${bestPicksSlate.has(e.slipKey) ? '✓' : '+'}</button>`
      : '';
    return `<div class="movement-summary-row ${cls}" data-jump="${e.name}" title="Open fighter card">
      <span class="movement-summary-fighter">${prettyName(e.name)}</span>
      <span class="movement-summary-stat mvs-${e.stat}">${e.statLabel}</span>
      <span class="movement-summary-line">${e.sourcePlat} ${e.open}→${e.close}</span>
      <span class="movement-summary-delta ${cls}">${arrow}${Math.abs(e.delta)}</span>
      ${sparkHtml}
      <span class="movement-summary-platforms">${platChips}</span>
      ${priceTag}${steamTag}${rlmTag}${slipBtn}
    </div>`;
  };

  const sectionHtml = (label: string, dirClass: 'rise'|'drop', list: SummaryEntry[]): string => {
    if (list.length === 0) return '';
    return `<div class="movement-summary-section-header ${dirClass}">${label} <span class="movement-summary-section-count">${list.length}</span></div>` +
      list.map(rowHtml).join('');
  };

  // An empty state says WHICH kind of empty — a filter that matches nothing is a
  // fact about the slate, and looks identical to a broken matcher otherwise.
  const emptyHtml = `<div class="mvs-empty">No movers match this filter — ${entries.length} on the board overall.</div>`;
  // L3 — the old board sliced to 20 with nothing saying so.
  const moreHtml = filtered.length > MOVERS_COLLAPSED_LIMIT
    ? `<button class="mvs-more" data-movers-toggle="1">${_moversShowAll ? `▲ SHOW TOP ${MOVERS_COLLAPSED_LIMIT}` : `▼ SHOW ALL ${filtered.length}`}</button>`
    : '';

  body.innerHTML = headerHtml
    + (filtered.length === 0
        ? emptyHtml
        // "Steamers" collided with the STEAM badge: the section meant "the line
        // rose", the badge means "≥2 books moved ≥2.0 together". A panel showing
        // `0 steam` above a section headed STEAMERS 4 reads as a contradiction.
        // The section is about direction, so it is named for direction.
        : sectionHtml('▲ Risers', 'rise', risers) + sectionHtml('▼ Drifters', 'drop', drifters))
    + moreHtml;

  body.querySelectorAll<HTMLElement>('.movement-summary-row[data-jump]').forEach(el => {
    el.addEventListener('click', () => jumpToFighterCard(el.dataset['jump'] || ''));
  });
  body.querySelectorAll<HTMLElement>('.mvs-filter').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const next = (btn.dataset['moverFilter'] || 'all') as MoverFilter;
      // Re-click clears, matching the GLOW-UP 198 L2 slate chips.
      _moverFilter = _moverFilter === next ? 'all' : next;
      _moversShowAll = false;
      renderLineMovementSummary();
    });
  });
  body.querySelector<HTMLElement>('.mvs-more')?.addEventListener('click', (ev) => {
    ev.stopPropagation();
    _moversShowAll = !_moversShowAll;
    renderLineMovementSummary();
  });
  // stopPropagation matters: the row itself jumps to the fighter card.
  body.querySelectorAll<HTMLElement>('.mvs-slate-btn').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const key = btn.dataset['slateKey'] || '';
      if (bestPicksSlate.has(key)) {
        bestPicksSlate.delete(key);
      } else {
        const d = _leanSlateData.get(key);
        if (d) { if (!bestPicksSlate.size) bestPicksSlateOpen = true; bestPicksSlate.set(key, d); }
      }
      renderLineMovementSummary();
      // My Slate's tray only exists on the Best Picks render path, so a pick
      // added here needs that view refreshed or the count goes stale.
      if (currentView === 'bestpicks') renderFighters();
    });
  });
  if (timeEl) timeEl.textContent = `Updated ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
  // Mini roll-up survives collapse — the header stays readable when the body is shut.
  if (miniEl) {
    const bits = [`${entries.length} movers`];
    if (steamCount) bits.push(`${steamCount} steam`);
    if (betterCount) bits.push(`${betterCount} better`);
    if (worseCount) bits.push(`${worseCount} worse`);
    miniEl.textContent = bits.join(' · ');
  }
}

function renderLineMoveFeed(): void {
  const list = document.getElementById('lineMoveList');
  if (!list) return;
  if (!recentLineMoves.length) {
    list.innerHTML = '<div class="line-move-item"><div class="meta">No movement events yet</div><div class="delta">--</div><div></div></div>';
    return;
  }
  list.innerHTML = recentLineMoves.slice(0, 12).map((e) => {
    const tm = new Date(e.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const deltaAbs = Math.abs(e.delta).toFixed(1);
    const deltaClass = e.direction === 'drop' ? 'drop' : 'rise';
    const spike = e.valueSpike ? '<span class="value-spike">VALUE SPIKE</span>' : '';
    const rlmTag = e.rlm
      ? `<span class="rlm-tag rlm-${e.rlm}" title="${(e.rlmReason || '').replace(/"/g, '&quot;')}">RLM ${e.rlm.toUpperCase()}</span>`
      : '';
    const flags = [e.steam ? 'steam' : '', e.stealth ? 'stealth' : ''].filter(Boolean).join(' + ');
    return `<div class="line-move-item"><div class="meta">${e.fighter} · ${e.platform.toUpperCase()} ${e.stat.toUpperCase()} · ${tm}${flags ? ` · ${flags}` : ''}</div><div class="delta ${deltaClass}">${e.direction === 'drop' ? '-' : '+'}${deltaAbs}</div><div>${rlmTag}${spike}</div></div>`;
  }).join('');
}

class LineDropService {
  private settings: LineWatchSettings = {
    enabled: false,
    direction: 'drop',
    threshold: 1.5,
    watchPlatforms: ['pick6', 'underdog', 'betr'],
    watchStats: ['fp', 'ss', 'td'],
    fighterAllowList: [],
    detectStealth: true,
    detectSteam: true,
    playSound: false,
  };
  private snapshot = new Map<string, number>();
  private timer: ReturnType<typeof setInterval> | null = null;
  private currentPollMinutes: number | null = null;
  private isPaused = false;
  private lastPollAt: number | null = null;
  private stealthAccumulator = new Map<string, { cumulative: number; lastTs: number }>();
  private readonly settingsKey = 'analyzer_line_watch_settings';

  async init(): Promise<void> {
    await this.loadSettings();
    this.bindVisibilityHandlers();
    this.bindSettingsUI();
    this.updateStatusUI();
    renderLineMoveFeed();
    if (this.settings.enabled) await this.start();
  }

  async toggle(): Promise<void> {
    if (this.settings.enabled) await this.stop();
    else await this.start();
  }

  async start(): Promise<void> {
    this.settings.enabled = true;
    await this.saveSettings();
    setWatcherVisualState('watching');
    await this.pollNow(true);
    this.scheduleTimer();
    this.updateStatusUI();
    showToast('Line watch enabled');
  }

  async stop(): Promise<void> {
    this.settings.enabled = false;
    await this.saveSettings();
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
    setWatcherVisualState('idle');
    this.updateStatusUI();
    showToast('Line watch stopped');
  }

  async manualPoll(): Promise<void> {
    await this.pollNow(false);
  }

  getLatestSpikeForFighter(fighter: string): LineMovementEvent | null {
    return latestValueSpikeByFighter[fighter] || null;
  }

  private async loadSettings(): Promise<void> {
    if (typeof chrome === 'undefined' || !chrome.storage) return;
    const data = await storageGet<Record<string, Partial<LineWatchSettings> | undefined>>([this.settingsKey]);
    const saved = data?.[this.settingsKey] as Partial<LineWatchSettings> | undefined;
    if (saved) this.settings = { ...this.settings, ...saved };
    this.syncSettingsToUI();
  }

  private async saveSettings(): Promise<void> {
    await storageSet({ [this.settingsKey]: this.settings });
  }

  private bindVisibilityHandlers(): void {
    document.addEventListener('visibilitychange', () => {
      this.isPaused = document.hidden;
      if (this.isPaused) this.updateStatusUI('Paused (tab hidden)');
      else {
        this.updateStatusUI();
        if (this.settings.enabled) this.pollNow(false).catch(() => null);
      }
    });
  }

  private bindSettingsUI(): void {
    document.getElementById('watcherSettingsBtn')?.addEventListener('click', () => {
      const panel = document.getElementById('watcherSettingsPanel');
      if (!panel) return;
      panel.classList.toggle('is-hidden');
    });
    document.getElementById('watcherApplyBtn')?.addEventListener('click', async () => {
      this.readSettingsFromUI();
      await this.saveSettings();
      this.scheduleTimer();
      this.updateStatusUI();
      showToast('Watch settings updated');
    });
    document.getElementById('watcherManualPollBtn')?.addEventListener('click', () => this.manualPoll());
  }

  private syncSettingsToUI(): void {
    const setChecked = (id: string, value: boolean): void => {
      const el = document.getElementById(id) as HTMLInputElement | null;
      if (el) el.checked = value;
    };
    const setVal = (id: string, value: string): void => {
      const el = document.getElementById(id) as HTMLInputElement | HTMLSelectElement | null;
      if (el) el.value = value;
    };
    setVal('watchDirection', this.settings.direction);
    setVal('watchThreshold', String(this.settings.threshold));
    setVal('watchFighterFilter', this.settings.fighterAllowList.join(', '));
    setChecked('watchP6', this.settings.watchPlatforms.includes('pick6'));
    setChecked('watchUD', this.settings.watchPlatforms.includes('underdog'));
    setChecked('watchBetr', this.settings.watchPlatforms.includes('betr'));
    setChecked('watchPP', this.settings.watchPlatforms.includes('prizepicks'));
    setChecked('watchFP', this.settings.watchStats.includes('fp'));
    setChecked('watchSS', this.settings.watchStats.includes('ss'));
    setChecked('watchTD', this.settings.watchStats.includes('td'));
    setChecked('watchStealth', this.settings.detectStealth);
    setChecked('watchSteam', this.settings.detectSteam);
    setChecked('watchSound', this.settings.playSound);
  }

  private readSettingsFromUI(): void {
    const q = (id: string) => document.getElementById(id) as HTMLInputElement | HTMLSelectElement | null;
    const direction = (q('watchDirection')?.value || 'drop') as LineWatchSettings['direction'];
    const threshold = parseFloat(q('watchThreshold')?.value || '1.5');
    const fighterList = (q('watchFighterFilter')?.value || '').split(',').map(s => s.trim()).filter(Boolean);
    const watchPlatforms: WatchPlatform[] = [
      (q('watchP6') as HTMLInputElement | null)?.checked ? 'pick6' : null,
      (q('watchUD') as HTMLInputElement | null)?.checked ? 'underdog' : null,
      (q('watchBetr') as HTMLInputElement | null)?.checked ? 'betr' : null,
      (q('watchPP') as HTMLInputElement | null)?.checked ? 'prizepicks' : null,
    ].filter((v): v is WatchPlatform => v != null);
    const watchStats: WatchedStatType[] = [
      (q('watchFP') as HTMLInputElement | null)?.checked ? 'fp' : null,
      (q('watchSS') as HTMLInputElement | null)?.checked ? 'ss' : null,
      (q('watchTD') as HTMLInputElement | null)?.checked ? 'td' : null,
    ].filter((v): v is WatchedStatType => v != null);
    this.settings = {
      ...this.settings,
      direction,
      threshold: Number.isFinite(threshold) ? Math.max(0.1, threshold) : 1.5,
      fighterAllowList: fighterList,
      watchPlatforms: watchPlatforms.length ? watchPlatforms : ['pick6', 'underdog', 'betr'],
      watchStats: watchStats.length ? watchStats : ['fp', 'ss', 'td'],
      detectStealth: !!(q('watchStealth') as HTMLInputElement | null)?.checked,
      detectSteam: !!(q('watchSteam') as HTMLInputElement | null)?.checked,
      playSound: !!(q('watchSound') as HTMLInputElement | null)?.checked,
    };
  }

  private scheduleTimer(): void {
    if (this.timer) clearInterval(this.timer);
    if (!this.settings.enabled) return;
    const mins = this.smartPollMinutes();
    this.currentPollMinutes = mins;
    this.timer = setInterval(() => {
      if (!this.settings.enabled || this.isPaused) return;
      this.pollNow(false).catch(() => null);
    }, mins * 60000);
  }

  private refreshTimerIfNeeded(): void {
    if (!this.settings.enabled) return;
    const nextMins = this.smartPollMinutes();
    if (this.currentPollMinutes === nextMins) return;
    this.scheduleTimer();
    this.updateStatusUI();
  }

  private smartPollMinutes(): number {
    const eventDateText = document.getElementById('eventDate')?.textContent || '';
    const eventMs = parseEventDateMs(eventDateText);
    const days = Number.isFinite(eventMs) ? ((eventMs - Date.now()) / 86400000) : 5;
    if (days <= 0.5) return 3;
    if (days <= 1.5) return 5;
    if (days <= 3) return 10;
    if (days <= 5) return 20;
    return 35;
  }

  private async getSnapshotPoints(): Promise<WatcherSnapshotPoint[]> {
    if (typeof chrome === 'undefined' || !chrome.storage) return [];
    const storage = await storageGet<Record<string, PlatformLinesPayload | null>>([...STORAGE_LINE_KEYS]);
    const platformMap: Array<{ platform: WatchPlatform; key: string }> = [
      { platform: 'pick6', key: 'lines_pick6' },
      { platform: 'underdog', key: 'lines_underdog' },
      { platform: 'betr', key: 'lines_betr' },
      { platform: 'prizepicks', key: 'lines_prizepicks' },
    ];
    const points: WatcherSnapshotPoint[] = [];
    platformMap.forEach(({ platform, key }) => {
      if (!this.settings.watchPlatforms.includes(platform)) return;
      const fighters = storage?.[key]?.fighters || [];
      fighters.forEach((f) => {
        const name = String(f.name || '').trim();
        if (!name) return;
        if (this.settings.fighterAllowList.length && !this.settings.fighterAllowList.some(n => name.toLowerCase().includes(n.toLowerCase()))) return;
        const pushPoint = (stat: WatchedStatType, value: unknown): void => {
          if (!this.settings.watchStats.includes(stat)) return;
          if (value == null || value === '') return;
          const num = Number(value);
          if (!Number.isFinite(num)) return;
          points.push({ fighter: name, platform, stat, value: num });
        };
        pushPoint('fp', f.line_fp ?? f.line);
        pushPoint('ss', f.line_ss);
        pushPoint('td', f.line_td);
      });
    });
    return points;
  }

  private shouldDirectionInclude(direction: 'drop'|'rise'): boolean {
    if (this.settings.direction === 'both') return true;
    return this.settings.direction === direction;
  }

  private detectEvents(points: WatcherSnapshotPoint[]): LineMovementEvent[] {
    const now = Date.now();
    const events: LineMovementEvent[] = [];

    points.forEach((p) => {
      const key = `${p.fighter}|${p.platform}|${p.stat}`;
      const prev = this.snapshot.get(key);
      this.snapshot.set(key, p.value);
      if (prev == null || prev === p.value) return;

      const delta = p.value - prev;
      const direction: 'drop'|'rise' = delta < 0 ? 'drop' : 'rise';
      if (!this.shouldDirectionInclude(direction)) return;

      const absDelta = Math.abs(delta);
      let stealth = false;
      if (absDelta < this.settings.threshold && this.settings.detectStealth) {
        const accum = this.stealthAccumulator.get(key) || { cumulative: 0, lastTs: now };
        const decay = (now - accum.lastTs) > 30 * 60000;
        const cumulative = (decay ? 0 : accum.cumulative) + absDelta;
        this.stealthAccumulator.set(key, { cumulative, lastTs: now });
        if (cumulative >= this.settings.threshold) stealth = true;
      }

      if (absDelta < this.settings.threshold && !stealth) return;

      const recentSame = recentLineMoves.filter(e => e.fighter === p.fighter && e.platform === p.platform && e.stat === p.stat && (now - e.timestamp) <= 20 * 60000);
      const steamMagnitude = recentSame.reduce((s, e) => s + Math.abs(e.delta), 0) + absDelta;
      const steam = this.settings.detectSteam && steamMagnitude >= (this.settings.threshold * 2.2) && recentSame.length >= 1;

      const spike = this.isValueSpike(p.fighter, direction, absDelta);
      const rlmInfo = this.classifyRLM(p, delta);

      events.push({
        id: `${key}|${now}`,
        timestamp: now,
        fighter: p.fighter,
        platform: p.platform,
        stat: p.stat,
        from: prev,
        to: p.value,
        delta,
        direction,
        stealth,
        steam,
        valueSpike: spike,
        rlm: rlmInfo.rlm,
        rlmReason: rlmInfo.rlmReason,
        notes: spike ? 'Value opportunity emerged after line move' : undefined,
      });
    });

    return events;
  }

  // Reverse-line-movement proxy. On pick-em platforms (p6/ud/pp/betr) the public
  // default on fantasy-style props is OVER, so a line RISING against opening is
  // a sharp-UNDER signal. A hard DROP well below opening is a sharp-OVER signal
  // (heavy OVER action forcing the book down). We prefer the opening-anchored
  // delta when available; otherwise fall back to within-session rises.
  private classifyRLM(p: WatcherSnapshotPoint, delta: number): { rlm?: 'under' | 'over'; rlmReason?: string } {
    const absDelta = Math.abs(delta);
    if (absDelta < 1.0) return {};
    const direction: 'drop' | 'rise' = delta < 0 ? 'drop' : 'rise';
    const platMap: Partial<Record<WatchPlatform, string>> = { pick6: 'p6', underdog: 'ud', betr: 'betr', prizepicks: 'pp' };
    const platShort = platMap[p.platform];
    if (!platShort) return {};
    const opening = _openingLines.get(`${platShort}|${p.stat}|${p.fighter.toLowerCase().trim()}`);
    const openingDelta = (typeof opening === 'number' && Number.isFinite(opening)) ? (p.value - opening) : null;

    if (direction === 'rise') {
      if (openingDelta != null && openingDelta >= 1.0) {
        return { rlm: 'under', rlmReason: `+${openingDelta.toFixed(1)} vs open · sharp UNDER flow` };
      }
      if (absDelta >= 1.5) {
        return { rlm: 'under', rlmReason: `rising against public OVER flow` };
      }
      return {};
    }
    // drop direction: only flag as sharp OVER when current is deep under opening
    // AND this single move was meaningful (not tiny drift).
    if (openingDelta != null && openingDelta <= -2.0 && absDelta >= 1.5) {
      return { rlm: 'over', rlmReason: `${openingDelta.toFixed(1)} vs open · heavy OVER action` };
    }
    return {};
  }

  private isValueSpike(fighter: string, direction: 'drop'|'rise', absDelta: number): boolean {
    if (absDelta < Math.max(0.8, this.settings.threshold * 0.75)) return false;
    const f = allFighters.find(x => x.name.toLowerCase() === fighter.toLowerCase());
    if (!f) return false;
    const lean = getEffectiveLean(f);
    if (lean.conf < 62 || lean.lean === 'none' || lean.lean === 'push') return false;
    if (direction === 'drop' && lean.lean === 'over') return true;
    if (direction === 'rise' && lean.lean === 'under') return true;
    return false;
  }

  private emitAlert(events: LineMovementEvent[]): void {
    recentLineMoves = [...events, ...recentLineMoves].slice(0, 120);
    events.filter(e => e.valueSpike).forEach(e => { latestValueSpikeByFighter[e.fighter] = e; });
    renderLineMoveFeed();
    renderFighters();
    const first = events[0];
    setWatcherVisualState('detected', 'Line Alert');
    showLineDropAlert({
      event: document.getElementById('eventName')?.textContent || 'UFC card',
      drops: events.map(e => ({ platform: e.platform.toUpperCase(), type: e.stat.toUpperCase(), count: 1 })),
      udCount: events.length,
      p6Count: 0,
    });
    if (this.settings.playSound) this.playAlertSound();
    const spikeCount = events.filter(e => e.valueSpike).length;
    showToast(`Line move: ${first.fighter} ${first.stat.toUpperCase()} ${first.direction === 'drop' ? 'dropped' : 'rose'} ${Math.abs(first.delta).toFixed(1)}${spikeCount ? ` · ${spikeCount} value spike${spikeCount > 1 ? 's' : ''}` : ''}`);
  }

  private playAlertSound(): void {
    try {
      const AudioContextCtor = window.AudioContext || (window as Window & { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!AudioContextCtor) return;
      const ac = new AudioContextCtor();
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = 'triangle';
      osc.frequency.value = 660;
      gain.gain.value = 0.03;
      osc.connect(gain);
      gain.connect(ac.destination);
      osc.start();
      osc.stop(ac.currentTime + 0.12);
    } catch {
      // ignore audio failures
    }
  }

  private updateStatusUI(override?: string): void {
    const { statusEl, pollBadge, lastBadge } = getWatcherStatusElements();
    if (!statusEl || !pollBadge || !lastBadge) return;
    if (!this.settings.enabled) {
      statusEl.textContent = 'Idle · set filters, threshold, and direction then start watch';
      pollBadge.textContent = 'Poll: off';
      lastBadge.textContent = 'Last: --';
      setWatcherVisualState('idle', 'Watch Lines');
      return;
    }
    const poll = this.smartPollMinutes();
    const last = this.lastPollAt ? new Date(this.lastPollAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--';
    const mode = this.settings.direction === 'both' ? 'drops + rises' : `${this.settings.direction}s only`;
    const watching = override || `Watching ${this.settings.watchPlatforms.map(p => p.toUpperCase()).join('/')} · ${this.settings.watchStats.map(s => s.toUpperCase()).join('/')} · ${mode} ≥ ${this.settings.threshold}`;
    statusEl.textContent = watching;
    pollBadge.textContent = `Poll: ${poll}m`;
    lastBadge.textContent = `Last: ${last}`;
    if (!document.getElementById('watcherToggleBtn')?.classList.contains('state-detected')) {
      setWatcherVisualState('watching', 'Watching');
    }
  }

  async pollNow(initial = false): Promise<void> {
    if (!this.settings.enabled || this.isPaused) return;
    try {
      const points = await this.getSnapshotPoints();
      const events = this.detectEvents(points);
      this.lastPollAt = Date.now();
      this.refreshTimerIfNeeded();
      this.updateStatusUI();
      if (events.length) this.emitAlert(events);
      else if (!initial) setWatcherVisualState('watching', 'Watching');
      if (!initial && typeof chrome !== 'undefined' && chrome.runtime) {
        void runtimeSendMessage({ type: 'MANUAL_POLL_NOW' });
      }
    } catch (e) {
      console.error('[LineDropService] Poll error', e);
      setWatcherVisualState('error', 'Watch Error');
      this.updateStatusUI('Error polling lines — retrying on next cycle');
    }
  }
}

const lineDropService = new LineDropService();

function toggleWatcher(): void {
  lineDropService.toggle().catch((e) => {
    console.error('[LineDropService] toggle failed', e);
    setWatcherVisualState('error', 'Watch Error');
  });
}

// ── AUTO-SCRAPE ────────────────────────────────────────────────────────────
async function triggerAutoScrape(): Promise<void> {
  if (typeof chrome === 'undefined' || !chrome.runtime) {
    showToast('Extension not available — running in demo mode'); return;
  }
  const btn  = document.getElementById('autoScrapeBtn') as HTMLButtonElement|null;
  const icon = document.getElementById('autoScrapeIcon');
  setButtonBusyState(btn, true);
  setIconSpinnerState(icon, true);
  showToast('⚡ Fast auto-fetch: Underdog API first, tabs only if needed...');
  type AutoScrapeResponse = { status?: 'done' | 'already_running' | string; results?: Record<string, number> };
  let result: AutoScrapeResponse | null = null;
  try {
    result = await runtimeSendMessage<AutoScrapeResponse>({ type: 'AUTO_SCRAPE_LINES' });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unexpected auto-scrape error';
    showToast(`Auto-scrape failed: ${message}`);
    return;
  } finally {
    setIconSpinnerState(icon, false);
    setButtonBusyState(btn, false);
  }
  if (result?.status === 'done') {
    const totals = Object.values(result.results || {}).reduce((s: number, n) => s + n, 0);
    showToast(`✓ Fetched lines from ${Object.keys(result.results || {}).length} platforms — ${totals} fighters loaded`);
    requestDataReload();
  } else if (result?.status === 'already_running') {
    showToast('Auto-scrape already in progress...');
  } else {
    showToast('Auto-scrape complete — click Refresh to load');
    requestDataReload();
  }
}

// ── EVENT BANNER ──────────────────────────────────────────────────────────
function formatCountdown(eventDate: string): string {
  const now = Date.now();
  const target = parseEventDateMs(eventDate);
  if (!Number.isFinite(target)) return 'Date unavailable';
  const diff = target - now;
  if (diff <= 0) return 'LIVE NOW 🔴';
  const days  = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const mins  = Math.floor((diff % 3600000)  / 60000);
  if (days > 0)  return `${days}d ${hours}h until event`;
  if (hours > 0) return `${hours}h ${mins}m until event`;
  return `${mins}m until event`;
}

async function loadEventBanner(): Promise<void> {
  if (typeof chrome === 'undefined' || !chrome.runtime) return;
  const banner = document.getElementById('eventBanner');
  const nameEl = document.getElementById('eventName');
  const dateEl = document.getElementById('eventDate');
  const cntEl  = document.getElementById('eventCountdown');
  if (banner) banner.style.display = 'flex';
  if (nameEl) nameEl.textContent = 'Detecting next UFC event...';

  const card = await syncUpcomingCardContext(true);
  if (!card) {
    upcomingCardPairs = [];
    upcomingEventName = '';
    if (banner) banner.style.display = 'none';
    debugLog('Upcoming card ignored: stale/invalid date in runtime+cache');
    return;
  }
  debugLog(`Upcoming card pairs loaded: ${upcomingCardPairs.length}`);

  const cardDate = card.date || '';

  if (nameEl) nameEl.textContent = card.event || 'Upcoming UFC Event';
  if (dateEl) dateEl.textContent = cardDate;
  if (cntEl) cntEl.textContent = formatCountdown(cardDate);

  // Venue badge
  const venueEl = document.getElementById('venueBadge');
  if (venueEl && currentVenueLabel) {
    let badge = `\ud83d\udccd ${currentVenueLabel}`;
    badge += ` \u00b7 <span class="cage-size">${currentVenueFactor.cageSizeFt}ft cage</span>`;
    if (currentVenueFactor.altitudeMeters >= 1200) {
      badge += ` \u00b7 <span class="altitude-warn">\u26a0 ${currentVenueFactor.altitudeMeters}m altitude</span>`;
    }
    if (currentVenueFactor.climateNote) {
      badge += ` \u00b7 <span style="opacity:0.6">${currentVenueFactor.climateNote}</span>`;
    }
    venueEl.innerHTML = badge;
    venueEl.style.display = '';
  } else if (venueEl) {
    venueEl.style.display = 'none';
  }

  if (eventCountdownTimer) clearInterval(eventCountdownTimer);
  eventCountdownTimer = setInterval(() => {
    if (cntEl) cntEl.textContent = formatCountdown(cardDate);
  }, 60000);

  if (card.fighters?.length && allFighters.length === 0) {
    debugLog(`Detected card: ${card.event} — ${card.fighters.length} fights`);
    const detected: AnalyzerFighter[] = [];
    card.fighters.forEach(({ f1, f2 }) => {
      detected.push(createPlaceholderAnalyzerFighter(f1, f2));
      detected.push(createPlaceholderAnalyzerFighter(f2, f1));
    });

    const result = await storageGet<Record<string, PlatformLinesPayload | null>>([...STORAGE_LINE_KEYS]);
    const hasRealData =
      (result['lines_pick6']?.fighters?.length || 0) +
      (result['lines_underdog']?.fighters?.length || 0) +
      (result['lines_prizepicks']?.fighters?.length || 0) +
      (result['lines_draftkings_sportsbook']?.fighters?.length || 0) +
      (result['lines_betr']?.fighters?.length || 0) > 0;
    if (!hasRealData) {
      showToast(`📅 Detected ${card.event} — ${card.fighters.length} fights found. Click ⚡ AUTO-FETCH LINES to get odds.`);
      allFighters = detected;
      renderFighters();
    }
  }
}

// ── BOOT ──────────────────────────────────────────────────────────────────
function setActivePlatform(platform: string): void {
  currentPlatform = platform;
  document.querySelectorAll('[data-platform]').forEach(b => b.classList.remove('platform-selected'));
  const target = document.querySelector(`[data-platform="${platform}"]`);
  if (target) target.classList.add('platform-selected');
  renderFighters();
}

function setTrendWindow(w: 3 | 5 | 0): void {
  trendWindow = w;
  document.querySelectorAll('.trend-btn[data-window]').forEach(b => b.classList.remove('active'));
  document.querySelector(`.trend-btn[data-window="${w}"]`)?.classList.add('active');
  updateSortTrendTriggerLabel();
  renderFighters();
}

function updateSortTrendTriggerLabel(): void {
  const sortEl = document.getElementById('sortTrendActiveSort');
  const trendEl = document.getElementById('sortTrendActiveTrend');
  if (sortEl) {
    const activeSort = document.querySelector('.sort-btn.active') as HTMLElement | null;
    if (activeSort) sortEl.textContent = (activeSort.textContent || '').trim();
  }
  if (trendEl) {
    const activeTrend = document.querySelector('.trend-btn.active') as HTMLElement | null;
    if (activeTrend) trendEl.textContent = (activeTrend.textContent || '').trim();
  }
}

function bindSourceToggles(): void {
  const buttons = document.querySelectorAll<HTMLButtonElement>('.source-toggle[data-source]');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const key = (btn.dataset.source || '') as 'p6'|'ud'|'pp'|'betr'|'dk';
      if (!(key in sourceVisibility)) return;

      sourceVisibility[key] = !sourceVisibility[key];
      if (!Object.values(sourceVisibility).some(Boolean)) {
        sourceVisibility[key] = true;
      }

      updateSourceToggleUI();
      updateSourceRowVisibility(true);
      renderFighters();
    });
  });
  const trigger = document.getElementById('sourceToggleTrigger');
  trigger?.addEventListener('click', () => {
    sourceButtonsExpanded = !sourceButtonsExpanded;
    updateSourceRowVisibility(true);
  });
  updateSourceToggleUI();
}

function bindLearningDetailsToggle(): void {
  const toggle = document.getElementById('ldDetailsToggle');
  const details = document.getElementById('ldDetails');
  if (!toggle || !details) return;
  toggle.addEventListener('click', () => {
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    const next = !expanded;
    toggle.setAttribute('aria-expanded', String(next));
    if (next) details.removeAttribute('hidden');
    else details.setAttribute('hidden', '');
  });
}

function syncDataTabsTrigger(): void {
  const trigger = document.getElementById('dataTabsTrigger');
  const labelEl = document.getElementById('dataTabsLabel');
  if (!trigger || !labelEl) return;
  const isDataView = currentView === 'calibration' || currentView === 'archive';
  trigger.classList.toggle('is-data-active', isDataView);
  if (isDataView) {
    const activeBtn = document.querySelector(`#dataTabsPopover [data-view="${currentView}"]`);
    labelEl.textContent = (activeBtn?.textContent || 'Data').trim();
  } else {
    labelEl.textContent = 'Data';
  }
}

function bindDataTabsTrigger(): void {
  const trigger = document.getElementById('dataTabsTrigger');
  const popover = document.getElementById('dataTabsPopover');
  if (!trigger || !popover) return;
  const closePopover = (): void => {
    trigger.setAttribute('aria-expanded', 'false');
    popover.setAttribute('hidden', '');
  };
  trigger.addEventListener('click', (e) => {
    e.stopPropagation();
    const expanded = trigger.getAttribute('aria-expanded') === 'true';
    trigger.setAttribute('aria-expanded', String(!expanded));
    if (expanded) popover.setAttribute('hidden', '');
    else popover.removeAttribute('hidden');
  });
  // Selecting a sub-tab closes the popover (existing tab handler still fires)
  popover.addEventListener('click', () => closePopover());
  // Click outside → close
  document.addEventListener('click', (e) => {
    if (trigger.contains(e.target as Node) || popover.contains(e.target as Node)) return;
    closePopover();
  });
}

function updateDensityTriggerDot(): void {
  const dot = document.getElementById('densityTriggerDot');
  const trigger = document.getElementById('densityTrigger');
  if (!dot || !trigger) return;
  const nonDefault = currentDensity === 'compact' || currentHistoryDensity === 'readable';
  dot.hidden = !nonDefault;
  if (nonDefault) {
    const labels: string[] = [];
    if (currentDensity === 'compact') labels.push('Compact View');
    if (currentHistoryDensity === 'readable') labels.push('History: Readable');
    trigger.title = `Active: ${labels.join(' · ')}`;
  } else {
    trigger.title = 'Display density options';
  }
}

function applyDensityMode(): void {
  const compact = currentDensity === 'compact';
  document.body.classList.toggle('compact-view', compact);
  const btn = document.getElementById('densityToggleBtn');
  if (btn) {
    btn.textContent = compact ? 'Detailed View' : 'Compact View';
    btn.classList.toggle('active', compact);
  }
  updateDensityTriggerDot();
}

function applyHistoryDensityMode(): void {
  const readable = currentHistoryDensity === 'readable';
  document.body.classList.toggle('readable-history', readable);
  const btn = document.getElementById('historyDensityToggleBtn');
  if (btn) {
    btn.textContent = readable ? 'History: Readable' : 'History: Compact';
    btn.classList.toggle('active', readable);
  }
  updateDensityTriggerDot();
}

function exportToCSV(): void {
  const fighters = allFighters.filter(f => getEffectiveLean(f).lean !== 'none');
  if (!fighters.length) {
    showToast('No leans to export');
    return;
  }
  const csv = [
    'Name,Opponent,Platform,Line,Lean,Confidence,ConfidenceGrade,BayesProb,CalibratedProb,ModelAgreement,KellyBetSize,EV,EV_Source,Vig,FairValue,FairValueEdge,Verdict',
    ...fighters.map(f => {
      const el = getEffectiveLean(f);
      const line = activePlatformLine(f);
      const platform = activePlatformLabel(f);
      const confidenceGrade = el.confidenceGrade || '';
      const bayesProb = el.bayesianProbability != null ? (el.bayesianProbability * 100).toFixed(1) : '';
      const calibratedProb = el.calibratedProbability != null ? (el.calibratedProbability * 100).toFixed(1) : '';
      const modelAgreement = el.ensembleAgreement != null ? (el.ensembleAgreement * 100).toFixed(1) : '';
      const kellyBetSize = el.kellyBetSize != null ? el.kellyBetSize.toFixed(2) : '';
      const evDetail = computeDetailedEV(f, el);
      const evStr = evDetail != null ? `${evDetail.ev}%` : '';
      const evSource = evDetail != null ? (evDetail.isAssumedVig ? 'assumed-110' : 'actual') : '';
      const vigStr = evDetail?.vig != null ? `${evDetail.vig}%` : '';
      const fairValue = el.fairValue != null ? el.fairValue.toFixed(1) : '';
      const fairValueEdge = el.fairValueEdge != null ? el.fairValueEdge.toFixed(1) : '';
      return `"${f.name}","${f.opponent || ''}","${platform}","${line || ''}","${el.lean}","${el.conf}","${confidenceGrade}","${bayesProb}","${calibratedProb}","${modelAgreement}","${kellyBetSize}","${evStr}","${evSource}","${vigStr}","${fairValue}","${fairValueEdge}","${el.verdict}"`;
    })
  ].join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `ufc-leans-${new Date().toISOString().split('T')[0]}.csv`;
  a.click();
  URL.revokeObjectURL(url);
  showToast('Exported leans to CSV');
}

let _reportCardText = '';
/**
 * GLOW-UP 245 — report card sort. Session-scoped, like the shop's lsSort and
 * Parlay Lab's command strip: it changes what is DRAWN, never what the model
 * picked, so it resets on reload by design.
 *
 * CARD is the default and stays the default: you read the report the way the
 * night runs, and it is the only order in which the bout pairings and the
 * BOTH UNDER reads mean anything. The other two flatten deliberately —
 * "what do I enter first" is a different question from "how does the card go",
 * and pretending a confidence ranking still has main-card sections would be
 * grouping that no longer describes anything.
 */
type RcSort = 'card' | 'conf' | 'edge';
let rcSort: RcSort = 'card';

// GLOW-UP 220: `bestAvailableLine` removed. It returned an FP line for any
// fighter regardless of which stat their lean was on — with a lone `line_dk_ss`
// fallback that made SS leans look handled — and the report card was its only
// caller. Deleted rather than left available: it reads like a general-purpose
// "get this fighter's line" helper, which is exactly how it ended up on a
// surface that needed the LEAN'S stat. Use leanBestBook(f, statKey, dir), which
// knows the stat, respects placeability, and shops FP within its scoring family.

// Fetches UFCStats directly from the popup (avoids MV3 service worker kill issue).
// Searches upcoming + completed pages for an event that overlaps with `names`.
async function fetchCardFromUFCStatsDirect(
  names: string[]
): Promise<{ event: string; fighters: Array<{ f1: string; f2: string }> } | null> {
  const nameSet = new Set(names.map(n => n.toLowerCase().replace(/[^a-z ]/g, '')));

  const parseFighters = (html: string): Array<{ f1: string; f2: string }> => {
    const result: Array<{ f1: string; f2: string }> = [];
    for (const rowM of html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)) {
      const row = rowM[1];
      if (row.includes('<th')) continue;
      const links = [...row.matchAll(/fighter-details\/[a-f0-9]+[^>]*>\s*([^<]+)\s*<\/a>/gi)];
      if (links.length < 2) continue;
      const f1 = links[0][1].trim();
      const f2 = links[1][1].trim();
      if (!f1 || !f2 || f1 === '--' || f2 === '--') continue;
      result.push({ f1, f2 });
    }
    return result;
  };

  const parseEventList = (html: string) => {
    const evts: Array<{ name: string; url: string; ts: number }> = [];
    for (const rowM of html.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)) {
      const row = rowM[1];
      if (row.includes('<th')) continue;
      const linkM = row.match(/href="(http[^"]*event-details\/[a-f0-9]+)"/i);
      const nameM = row.match(/event-details\/[a-f0-9]+[^>]*>\s*([^<]+)\s*<\/a>/i);
      const dateM = row.match(/(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\.?\s+\d+,\s+\d{4}/i);
      if (!linkM || !nameM) continue;
      const ts = dateM ? Date.parse(dateM[0]) : 0;
      evts.push({ name: nameM[1].trim(), url: linkM[1], ts });
    }
    return evts;
  };

  const hasEnoughOverlap = (fighters: Array<{ f1: string; f2: string }>) => {
    let count = 0;
    for (const { f1, f2 } of fighters) {
      if (nameSet.has(f1.toLowerCase().replace(/[^a-z ]/g, '')) ||
          nameSet.has(f2.toLowerCase().replace(/[^a-z ]/g, ''))) count++;
    }
    return fighters.length >= 4 && count >= Math.ceil(fighters.length * 0.35);
  };

  try {
    const sources = [
      'http://www.ufcstats.com/statistics/events/upcoming?page=all',
      'http://www.ufcstats.com/statistics/events/completed?page=1',
    ];
    for (const src of sources) {
      const listHtml = await ufcstatsFetchText(src);
      if (!listHtml) continue;

      const evts = parseEventList(listHtml);
      // Sort by proximity to today; check most recent 10
      const sorted = evts.slice().sort((a, b) => Math.abs(Date.now() - a.ts) - Math.abs(Date.now() - b.ts));
      for (const evt of sorted.slice(0, 10)) {
        const evHtml = await ufcstatsFetchText(evt.url);
        if (!evHtml) continue;
        const fighters = parseFighters(evHtml);
        if (hasEnoughOverlap(fighters)) {
          return { event: evt.name, fighters };
        }
      }
    }
  } catch { /* ignore */ }
  return null;
}

async function generateReportCard(): Promise<void> {
  if (!allFighters.length) { showToast('No fighters loaded'); return; }

  // Step 1: Pair fighters using opponent field (reliable — comes from line data, always set)
  const seenPair = new Set<string>();
  const fighterPairs: AnalyzerFighter[][] = [];
  for (const f of allFighters) {
    if (seenPair.has(f.name)) continue;
    seenPair.add(f.name);
    let opp: AnalyzerFighter | undefined;
    if (f.opponent) {
      opp = allFighters.find(x => !seenPair.has(x.name) && (namesMatch(x.name, f.opponent!) || strictCardNameMatch(x.name, f.opponent!)));
    }
    if (opp) { seenPair.add(opp.name); fighterPairs.push([f, opp]); }
    else fighterPairs.push([f]);
  }

  // Step 2: Get card ordering data — only use card pairs that overlap with currently loaded fighters.
  // upcomingCardPairs may contain the NEXT event's fighters (not the event whose lines are loaded).
  let reportTitle = upcomingEventName || inferredEventNameFromLines;
  const loadedNames = new Set(allFighters.map(f => (normalizeName(f.name) || f.name).toLowerCase()));
  const hasOverlap = (pairs: Array<{ f1: string; f2: string }>) =>
    pairs.filter(cp => loadedNames.has(cp.f1.toLowerCase()) || loadedNames.has(cp.f2.toLowerCase())).length
    >= Math.ceil(pairs.length * 0.4);

  const normalizeCardFighters = (fighters: Array<{ f1: string; f2: string }>): Array<{ f1: string; f2: string }> =>
    fighters
      .map((fight) => {
        const f1 = normalizeName(fight.f1);
        const f2 = normalizeName(fight.f2);
        return (f1 && f2 && f1 !== f2) ? { f1, f2 } : null;
      })
      .filter((p): p is { f1: string; f2: string } => p != null);

  const tryCardStorage = async (): Promise<boolean> => {
    const raw = await storageGet<Record<string, any>>(['upcoming_ufc_card', 'last_completed_ufc_card']);
    for (const key of ['upcoming_ufc_card', 'last_completed_ufc_card']) {
      const rawCard = raw[key] as { event?: string; fighters?: Array<{ f1: string; f2: string }> } | undefined;
      if (!rawCard?.fighters?.length) continue;
      const normalized = normalizeCardFighters(rawCard.fighters);
      if (hasOverlap(normalized)) {
        cardOrderPairs = normalized;
        if (!reportTitle) reportTitle = buildEventDisplayName(rawCard.event || '', rawCard.fighters);
        return true;
      }
    }
    return false;
  };

  let cardOrderPairs: Array<{ f1: string; f2: string }> = [];
  if (upcomingCardPairs.length && hasOverlap(upcomingCardPairs)) {
    cardOrderPairs = upcomingCardPairs.slice();
  } else {
    const found = await tryCardStorage();
    if (!found) {
      // Fetch UFCStats directly from popup (avoids MV3 service worker kill mid-fetch)
      const names = allFighters.map(f => f.name);
      const directCard = await fetchCardFromUFCStatsDirect(names);
      if (directCard?.fighters?.length) {
        const normalized = normalizeCardFighters(directCard.fighters);
        if (hasOverlap(normalized)) {
          cardOrderPairs = normalized;
          if (!reportTitle) reportTitle = buildEventDisplayName(directCard.event || '', directCard.fighters);
        }
      }
    }
  }

  // Step 3: Sort pairs by card order (if available)
  const orderedPairs: AnalyzerFighter[][] = [];
  if (cardOrderPairs.length) {
    const usedPairIdx = new Set<number>();
    for (const cp of cardOrderPairs) {
      const idx = fighterPairs.findIndex((pair, i) =>
        !usedPairIdx.has(i) && pair.some(f => strictCardNameMatch(f.name, cp.f1) || strictCardNameMatch(f.name, cp.f2))
      );
      if (idx >= 0) { usedPairIdx.add(idx); orderedPairs.push(fighterPairs[idx]); }
    }
    fighterPairs.forEach((pair, i) => { if (!usedPairIdx.has(i)) orderedPairs.push(pair); });
  } else {
    // No UFCStats card data — use UD storage order as a proxy (UD lists fights in card order)
    const udStorage = await storageGet<Record<string, any>>(['lines_underdog']);
    const udFighterNames: string[] = ((udStorage['lines_underdog'] as any)?.fighters || [])
      .map((f: any) => (normalizeName(String(f?.name || '')) || '').toLowerCase())
      .filter(Boolean);

    if (udFighterNames.length) {
      const udPos = new Map<string, number>();
      udFighterNames.forEach((n, i) => udPos.set(n, i));
      const pairMinUdPos = (pair: AnalyzerFighter[]): number => {
        let min = Infinity;
        for (const f of pair) {
          const key = (normalizeName(f.name) || f.name).toLowerCase();
          const exact = udPos.get(key);
          if (exact !== undefined && exact < min) min = exact;
          if (min === Infinity) {
            const last = key.split(' ').pop() ?? '';
            if (last.length > 4) {
              for (const [k, p] of udPos) {
                if (k.split(' ').pop() === last && p < min) { min = p; break; }
              }
            }
          }
        }
        return min;
      };
      const sorted = fighterPairs.slice().sort((a, b) => pairMinUdPos(a) - pairMinUdPos(b));
      orderedPairs.push(...sorted);
    } else {
      // No UD data — at least promote the main event headliner pair to position 0
      const headsMatch = reportTitle.match(/:\s*(.+?)\s+vs\.?\s+(.+)$/i);
      let headlinerIdx = -1;
      if (headsMatch) {
        const h1 = headsMatch[1].trim();
        const h2 = headsMatch[2].trim();
        headlinerIdx = fighterPairs.findIndex(pair =>
          pair.some(f => strictCardNameMatch(f.name, h1) || strictCardNameMatch(f.name, h2) ||
                         namesMatch(f.name, h1) || namesMatch(f.name, h2))
        );
      }
      if (headlinerIdx > 0) {
        const reordered = fighterPairs.slice();
        reordered.unshift(...reordered.splice(headlinerIdx, 1));
        orderedPairs.push(...reordered);
      } else {
        orderedPairs.push(...fighterPairs);
      }
    }
  }

  const eventTitle = reportTitle || 'UFC Card';
  // ── GLOW-UP 223 L9 — the card states its own vintage ─────────────────────
  // This is the artifact that gets read away from the app, sometimes hours after
  // it was generated, and it dated itself to the DAY. "August 14" says nothing
  // about whether the lines behind it are twelve minutes or nine hours old, and
  // nothing about how long is left to enter. A pre-event report that cannot be
  // aged is a report you have to regenerate to trust.
  const eventDate = new Date().toLocaleString('en-US', {
    month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
  });
  const { tMinus } = eventCountdown();
  // Oldest book bounds the whole card's staleness: every lean on it was scored
  // against some book's number, so the card is only as fresh as its stalest one.
  let lineAge = '';
  try {
    const linesPayload = await storageGet<Record<string, { capturedAt?: number }>>(
      [...STORAGE_LINE_KEYS, STORAGE_BETR_MANUAL_KEY]);
    // Betr's stored capturedAt is the SEED's, not the manual entry's — the manual
    // rows live under their own key and never rewrite it. The QA panel already
    // overlays the effective timestamp before judging staleness; without the same
    // overlay here, a card built minutes after a fresh Betr entry would date its
    // own lines to whenever the seed was written.
    const betrManual = linesPayload?.[STORAGE_BETR_MANUAL_KEY] as { fighters?: unknown[]; capturedAt?: number } | undefined;
    const effectiveCapturedAt = (k: string): number =>
      (k === 'lines_betr' && betrManual?.fighters?.length)
        ? (Number(betrManual.capturedAt) || Date.now())
        : Number(linesPayload?.[k]?.capturedAt || 0);
    const ages = STORAGE_LINE_KEYS
      .map(effectiveCapturedAt)
      .filter(ts => ts > 0)
      .map(ts => Math.floor((Date.now() - ts) / 60000));
    if (ages.length) lineAge = fmtAgeMin(Math.max(...ages));
  } catch { /* the header degrades to no age rather than failing the card */ }
  const vintageBits = [
    `Generated ${eventDate}`,
    lineAge ? `lines ≤${lineAge} old` : '',
    tMinus ? `${tMinus} to first bell` : '',
    `MODEL v${MODEL_VERSION}`,
  ].filter(Boolean);

  interface FightGroup { badge: string; badgeCls: string; pair: AnalyzerFighter[]; }
  const groups: FightGroup[] = [];

  const getBadge = (fi: number, total: number): { badge: string; badgeCls: string } => {
    if (fi === 0) return { badge: 'MAIN EVENT', badgeCls: 'main-event' };
    if (fi === 1) return { badge: 'CO-MAIN', badgeCls: 'co-main' };
    if (fi < Math.ceil(total * 0.55)) return { badge: 'MAIN CARD', badgeCls: 'main-card' };
    return { badge: 'PRELIM', badgeCls: 'prelim' };
  };

  const total = orderedPairs.length;
  orderedPairs.forEach((pair, fi) => {
    const { badge, badgeCls } = getBadge(fi, total);
    groups.push({ badge, badgeCls, pair });
  });

  const isBoilerplate = (t: string): boolean => /^Platform-aware FP baseline/i.test(t.trim());

  // ── GLOW-UP 220 — ONE resolver, two renderers ────────────────────────────
  // The screen and the plain-text export each worked out their own line, book
  // and average, so af0ef21 fixed the screen and left COPY/DOWNLOAD emitting an
  // FP line for every lean regardless of stat. That is the same failure shape as
  // the two line-staleness checks and the rebuilt slate key from earlier today:
  // a fact derived twice drifts. Derived once here; both renderers consume it.
  interface RcRow {
    el: EffectiveLean; statKey: LeanSource; statLbl: string;
    line: number | null; src: string; unplaceable: boolean;
    tier: 'high' | 'med' | 'low'; avgVal: number | null;
    topReason: string; generic: boolean;
  }
  const resolveRow = (f: AnalyzerFighter): RcRow => {
    const el = getEffectiveLean(f);
    // The line must belong to the LEAN'S OWN STAT. bestAvailableLine only ever
    // knew FP lines with a single DK-SS fallback, so it had no idea which prop
    // the lean was on: Eric McConico exported "—" on an SS lean while Pick6 had
    // him at 30.5, and any fighter with both an FP line and an SS lean exported
    // the FP number beside SS reasoning. leanBestBook knows the stat, is
    // placeability-aware, and shops FP within its scoring family.
    const statKey = (el._source || 'fp') as LeanSource;
    const statLbl = EFFECTIVE_LEAN_STAT_LABEL[statKey] || statKey.toUpperCase();
    const resolved = (el.lean === 'over' || el.lean === 'under')
      ? leanBestBook(f, statKey, el.lean)
      : { book: null as string | null, line: null as number | null };
    const line = resolved.line ?? getSourceActiveLine(f, statKey);
    const srcKey = (resolved.book as SourcePlatformKey | null) ?? getSourceActivePlatformKey(f, statKey);
    const topReason = el.reasons?.[0]?.text ?? '';
    return {
      el, statKey, statLbl, line,
      src: srcKey ? platformKeyShort(srcKey) : '',
      // MODEL v23 stamps this on the lean itself, so the card reports the model's
      // own verdict rather than deriving a second opinion from the same inputs.
      unplaceable: el._unplaceable === true
        || ((el.lean === 'over' || el.lean === 'under') && !resolved.book && line != null),
      tier: el.conf >= 72 ? 'high' : el.conf >= 58 ? 'med' : 'low',
      // The average has to be the average OF THAT STAT, or an SS row reads
      // "18.5 · avg 63.0" with the 63.0 being fantasy points.
      avgVal: statKey === 'ss' ? (f.db?.avgSigStr ?? null)
        : statKey === 'td' ? (f.db?.avgTD ?? null)
        : (f.db?.avgFP ?? null),
      topReason,
      generic: !!topReason && isBoilerplate(topReason),
    };
  };

  // ── GLOW-UP 223 L1 — a push is not a lean ────────────────────────────────
  // `lean !== 'none'` also matches 'push', so every count on this card treated a
  // fighter the model has NO side on as an actionable lean. UFC 330 showed it
  // plainly: ACTIONABLE said 19 while DIRECTION said 7/10 — the missing 2 were
  // Makhachev and Ribovics, both pushes, inflating the headline and dragging the
  // average toward 50%. Actionable means the model picked a side.
  const hasSide = (f: AnalyzerFighter): boolean => {
    const l = getEffectiveLean(f).lean;
    return l === 'over' || l === 'under';
  };
  const leanFighters = allFighters.filter(hasSide);
  const pushCount = allFighters.filter(f => getEffectiveLean(f).lean === 'push').length;
  // GLOW-UP 221 — a lean nobody will take is a READ, not something actionable.
  // Neil Magny's FP UNDER sat at the top of this card at 81% while Pick6 posts
  // him More-only (fp_under_available === false, +120 dog) — the placeability
  // rules had already flagged the row, but the headline still recommended it.
  const placeableLeans = leanFighters.filter(f => !resolveRow(f).unplaceable);
  const blockedCount = leanFighters.length - placeableLeans.length;
  // GLOW-UP 222 — ONE denominator for the whole summary. ACTIONABLE and TOP PICK
  // counted placeable leans while DIRECTION, AVG CONF and every section header
  // still averaged all 24, so on UFC 330 the card called itself a "workable card"
  // at 63% with 8 of those leans being bets no book will take. Every summary
  // number now describes the same set: the leans you can actually place. The
  // blocked ones stay visible as rows (they are real reads) and are reported as a
  // count beside each figure, never folded into it.
  const placeableSet = new Set<AnalyzerFighter>(placeableLeans);
  const overCount = placeableLeans.filter(f => getEffectiveLean(f).lean === 'over').length;
  const underCount = placeableLeans.filter(f => getEffectiveLean(f).lean === 'under').length;
  const avgConf = placeableLeans.length
    ? Math.round(placeableLeans.reduce((s, f) => s + getEffectiveLean(f).conf, 0) / placeableLeans.length)
    : 0;

  // ── GLOW-UP 218 R1 — the headline ────────────────────────────────────────
  // The summary was a run-on of four values in one grey line, so the card's own
  // verdict carried no more weight than its punctuation. Tiles, matching the
  // language Slate Check and the line-shop hero already use.
  // Only a lean you can actually place can be the card's recommendation.
  const rankedPlaceable = placeableLeans
    .map(f => ({ f, el: getEffectiveLean(f) }))
    .sort((a, b) => b.el.conf - a.el.conf);
  const topPick = rankedPlaceable[0];
  // ── GLOW-UP 223 L3 — the plays, findable in card order ───────────────────
  // Card order is the right order: you read the report the way the night runs.
  // But it buries the strongest plays among 24 rows, and TOP PICK names exactly
  // one of them. The top three placeable leans carry a rank star, so the card
  // can be scanned for the plays without being re-sorted away from card order.
  const rankMap = new Map<AnalyzerFighter, number>();
  rankedPlaceable.slice(0, 3).forEach((r, i) => rankMap.set(r.f, i + 1));
  // ── GLOW-UP 223 L7 — the bar measures edge, not the number's decimal value ─
  // `width: conf%` meant a 50% lean — the model's coin-flip floor — rendered
  // half full, and a 43% one still showed a third of a bar. Confidence on this
  // card lives in roughly 45–90, so the bar spans that range instead.
  const confBarPct = (c: number): number =>
    Math.round(Math.min(100, Math.max(4, ((c - 45) / 45) * 100)));
  const overPct = placeableLeans.length ? Math.round((overCount / placeableLeans.length) * 100) : 0;
  const sections: string[] = [];
  // The event header and headline stay pinned while the fights scroll beneath —
  // otherwise the card's verdict scrolls away the moment you look at the prelims.
  sections.push(`
    <div class="rc-sticky-top">
    <div class="rc-event-header">
      <div class="rc-event-name">${eventTitle}</div>
      <div class="rc-event-meta" title="When this card was generated, how old the stalest book behind it is, how long until the first bell, and the model that scored it.">${vintageBits.join(' · ')}</div>
    </div>
    <div class="rc-hero">
      <div class="rc-hero-tile" title="Leans you can actually place. ${blockedCount ? `${blockedCount} more have a direction but no book will take that side — they are reads, not bets, and are marked ⛔ below.` : 'Every lean on this card is placeable.'}${pushCount ? ` ${pushCount} fighter${pushCount === 1 ? ' has' : 's have'} no side at all (NO EDGE) and are not counted here.` : ''}">
        <span class="rc-hero-label">ACTIONABLE</span>
        <span class="rc-hero-val">${placeableLeans.length}<em>leans</em></span>
        <span class="rc-hero-sub">${!leanFighters.length && !pushCount ? 'still loading — reopen in a moment'
          : blockedCount ? `${blockedCount} more unplaceable` : `of ${allFighters.length} fighters`}</span>
      </div>
      <div class="rc-hero-tile" title="Direction split across the leans you can place: ${overCount} overs, ${underCount} unders.${blockedCount ? ` The ${blockedCount} unplaceable read${blockedCount === 1 ? ' is' : 's are'} excluded.` : ''} A heavily one-sided card is worth noticing before you build entries.">
        <span class="rc-hero-label">DIRECTION</span>
        <span class="rc-hero-val rc-split"><b class="rc-over">${overCount}</b><i>/</i><b class="rc-under">${underCount}</b></span>
        <span class="rc-hero-bar"><i style="width:${overPct}%"></i></span>
      </div>
      <div class="rc-hero-tile" title="Mean model confidence across the ${placeableLeans.length} placeable lean${placeableLeans.length === 1 ? '' : 's'}.${blockedCount ? ` Unplaceable reads are excluded — including them rated the card on bets you cannot take.` : ''}">
        <span class="rc-hero-label">AVG CONF</span>
        <span class="rc-hero-val">${avgConf}<em>%</em></span>
        <span class="rc-hero-sub">${!placeableLeans.length ? (leanFighters.length ? 'nothing placeable' : 'leans not computed yet') : avgConf >= 70 ? 'strong card' : avgConf >= 60 ? 'workable card' : 'thin card'}</span>
      </div>
      ${topPick ? `<div class="rc-hero-tile is-top" title="Highest-confidence lean on the card: ${prettyName(topPick.f.name)} ${topPick.el.lean.toUpperCase()} at ${topPick.el.conf}%.">
        <span class="rc-hero-label">TOP PICK</span>
        <span class="rc-hero-val">${topPick.el.conf}<em>%</em></span>
        <span class="rc-hero-sub">${prettyName(topPick.f.name)} · ${topPick.el.lean.toUpperCase()}</span>
      </div>` : ''}
    </div>
    ${(() => {
      // ── GLOW-UP 223 L10 — the marks explain themselves ────────────────────
      // ★, ⛔ and NO EDGE all carry meaning that lived only in a hover tooltip,
      // which the exported screenshot and a quick scan both lose. The legend
      // prints only the marks this particular card actually uses.
      const keys: string[] = [];
      if (rankMap.size) keys.push(`<b><i class="rc-rank">★</i> top ${rankMap.size} placeable by confidence</b>`);
      if (blockedCount) keys.push('<b><i class="rc-blocked">⛔</i> no book takes this side — read only</b>');
      if (pushCount) keys.push('<b><i class="rc-key-push">NO EDGE</i> model has no side</b>');
      return keys.length ? `<div class="rc-legend">${keys.join('<s></s>')}</div>` : '';
    })()}
    <!-- GLOW-UP 243 — the card had eight columns and no labels. The shop has
         carried FIGHTER + LEAN / FP / SS / TD since it was built, and it is
         half of why that panel reads as a considered table rather than a list
         of rows: you know what you are looking at before you look. Pinned with
         the rest of the header, so it survives scrolling the way the shop's
         sticky <th> does. -->
    <div class="rc-sortbar">
      <span class="rc-sort-label">SORT</span>
      <button class="rc-sort-btn${rcSort === 'card' ? ' on' : ''}" data-rc-sort="card" title="Card order — main event down. The only order in which the bout pairings and the both-under reads mean anything.">CARD</button>
      <button class="rc-sort-btn${rcSort === 'conf' ? ' on' : ''}" data-rc-sort="conf" title="Highest model confidence first, placeable leans above reads. Flattens the card: sections and bout pairing stop describing anything once the order is not the running order.">CONF</button>
      <button class="rc-sort-btn${rcSort === 'edge' ? ' on' : ''}" data-rc-sort="edge" title="Biggest gap between the fighter's career average and the line, in the direction the pick needs. Also flattens.">Δ LINE</button>
      ${rcSort !== 'card' ? '<span class="rc-sort-note">grouping off — flat ranking</span>' : ''}
    </div>
    <div class="rc-colhead${rcSort === 'card' ? '' : ' is-flat'}" aria-hidden="true">
      <span>FIGHTER</span>
      <span>PICK</span>
      <span class="rc-ch-books">BOOKS</span>
      <span>SPREAD</span>
      <span>WHY</span>
      <span class="rc-ch-r">CONF</span>
      <span class="rc-ch-r">AVG</span>
      <span class="rc-ch-r" title="Career average minus the line — how far his history sits from the number, and which way.">Δ LINE</span>
    </div>
    </div>
  `);

  // R4 — the model's generic fallback rationale. It carries no fighter-specific
  // information, repeats verbatim on a third of the card, and was the string
  // that got truncated mid-word on every row. Detected so it can be demoted
  // rather than compete with real reasoning.
  // R2 — one heading per SECTION, not per fight. "MAIN CARD" printed five times
  // and "PRELIM" five times, which read as five separate sections and buried the
  // structure of the card.
  // ── GLOW-UP 245 — one row builder, two orders ────────────────────────────
  // Hoisted out of the group loop so the sorted view can render the same row.
  // Deriving the row twice was how the screen and the export drifted apart in
  // 220; not making that mistake again for the sake of a sort.
  const renderFighterRow = (f: AnalyzerFighter): string => {
      const { el, statKey, statLbl, line, src, unplaceable, tier, avgVal, topReason, generic } = resolveRow(f);
      // L1 — a push rendered as a bare dash in an empty box, which reads as a
      // failed row rather than as the model's actual answer: no side here.
      const isPush = el.lean === 'push';
      const leanCls = el.lean === 'over' ? 'rc-over' : el.lean === 'under' ? 'rc-under' : isPush ? 'rc-push' : 'rc-none';
      const leanLabel = el.lean === 'over' ? '▲ OVER' : el.lean === 'under' ? '▼ UNDER' : isPush ? 'NO EDGE' : '—';
      // L1/L2 — confidence is a recommendation's WEIGHT, so only a recommendation
      // earns the tiered colour and the bar. A push has no side to back, and an
      // unplaceable lean is not a bet: Ian Machado Garry's blocked 80% was the
      // loudest row on the card, lit spine and full green bar, directly under a
      // headline that had just excluded it.
      const confMuted = isPush || unplaceable;
      const confEl = el.lean === 'none'
        ? `<span class="rc-conf is-none">—</span>`
        : confMuted
          ? `<span class="rc-conf is-muted" title="${isPush
              ? 'The model has no side here, so this number is not a play — shown without weight.'
              : 'A read, not a bet: no book will take this side. Shown without weight so it cannot outrank a placeable lean.'}"><b>${el.conf}%</b></span>`
          : `<span class="rc-conf tier-${tier}" title="Model confidence — ${tier === 'high' ? 'high' : tier === 'med' ? 'medium' : 'low'} tier. The bar spans 45–90%, the range this model's confidence actually occupies."><b>${el.conf}%</b><i class="rc-conf-bar"><u style="width:${confBarPct(el.conf)}%"></u></i></span>`;
      // GLOW-UP 231 L2 — the stat label moved onto the pick block, so repeating
      // it here was the same word twice on one row. The average is now just the
      // number, which is all it ever needed to be beside a labelled line.
      const avgEl = avgVal != null
        ? `<span class="rc-avg" title="This fighter's career average for ${statLbl} — the same stat as the line beside it.">avg <b>${avgVal.toFixed(1)}</b></span>`
        : `<span class="rc-avg"></span>`;
      const reasonTxt = topReason;
      const lineStr = line != null ? line.toFixed(1) : '—';
      // Naming the active book on an unplaceable row was the part that read as a
      // recommendation: "UNDER 73.5 P6" says take it on Pick6, when Pick6 is
      // precisely the book refusing it.
      // L5 — the ⛔ used to sit inside the line cell, so the numbers stopped
      // being a column the moment a row was blocked. The book slot is already
      // empty on exactly those rows, so the flag lands there instead and the
      // line column stays pure.
      const srcEl = unplaceable
        ? `<span class="rc-src is-blocked" title="No book the scraper can see will take this side for this fighter — the lean is a read, not a placeable bet."><i class="rc-blocked">⛔</i></span>`
        : `<span class="rc-src">${src || ''}</span>`;
      const rank = rankMap.get(f);
      const rankEl = rank
        ? `<i class="rc-rank" title="#${rank} of the ${placeableLeans.length} placeable leans by model confidence.">★${rank}</i>`
        : '';
      const rowCls = [
        'rc-fighter-row',
        el.lean === 'none' ? 'is-noplay' : '',
        isPush ? 'is-push' : '',
        unplaceable ? 'is-blocked' : '',
        // The lit spine marks a strong PLAY, so it follows the same rule as the
        // bar: muted rows never earn it.
        confMuted || el.lean === 'none' ? '' : `tier-${tier}`,
      ].filter(Boolean).join(' ');
      // ── GLOW-UP 231 L1 — the pick is ONE object ──────────────────────────
      // Direction, stat, line and book were four separate grid cells spread
      // across the row, so reading "UNDER 83.5 FP on Pick6" meant reassembling
      // it from four places at four different weights — and nothing in the row
      // was dominant, so the eye had nowhere to land. They now share one
      // surface, with the LINE as the typographic anchor and everything else
      // subordinate to it.
      const pickEl = el.lean === 'none'
        ? '<span class="rc-pick is-none" title="No lean on this fighter, so there is no prop to name.">—</span>'
        : `<span class="rc-pick ${leanCls}">`
          + `<i class="rc-dir"${isPush ? ' title="The model scored this fighter and landed on neither side — not a play, and not a missing row."' : ''}>${leanLabel}</i>`
          + `<b class="rc-line">${lineStr}</b>`
          + `<i class="rc-meta">`
          + `<em class="rc-stat-tag src-${statKey}" title="Which prop this lean is on. The line and average beside it are both ${statLbl}.">${statLbl}</em>`
          + srcEl
          + `</i>`
          + `</span>`;
      // ── GLOW-UP 239 — the row becomes a shop row ─────────────────────────
      // The card looked bland next to the line shop for a structural reason,
      // not a styling one: a shop row is a dozen small coloured chips and this
      // was one grey box plus a sentence. Two changes fix that, and the second
      // one earns its place rather than just adding colour.
      //
      // 1. The BOOK RAIL. Every book posting this prop gets a chip, best entry
      //    for the side marked, blocked books dashed. It is the shop's most
      //    recognisable device AND it answers the question the card could not:
      //    the old row named one book, so "where do I actually put this" meant
      //    leaving the card. Uses the same lineForBook / bookTakesSide pair the
      //    shop and the placement chip use, so it cannot disagree with them.
      const dirForRail = (el.lean === 'over' || el.lean === 'under') ? el.lean : null;
      const railBooks = dirForRail
        ? (LEAN_STAT_FIELDS[statKey] || [])
            .map(([bk]) => ({ bk, v: lineForBook(f, statKey, bk) }))
            .filter((c): c is { bk: string; v: number } => c.v != null)
            // Best entry first, the rule leanBestBook shops by.
            .sort((a, b) => dirForRail === 'over' ? a.v - b.v : b.v - a.v)
        : [];
      const railDir = dirForRail as 'over' | 'under';
      const railEl = railBooks.length
        ? `<span class="rc-books">` + railBooks.map((c, i) => {
            const takes = bookTakesSide(f, statKey, railDir, c.bk);
            const label = platformKeyShort(c.bk as SourcePlatformKey);
            // GLOW-UP 242 — brand hue per book, plus the shop's best/worst pair.
            // This IS a multi-book chart, which is the one place the app's colour
            // rules put book identity on the hue axis.
            const isWorst = takes && i === railBooks.length - 1 && railBooks.length > 1;
            const cls = `rc-bk plat-${c.bk}${!takes ? ' is-blocked' : i === 0 ? ' is-best' : isWorst ? ' is-worst' : ''}`;
            const tip = takes
              ? `${LEAN_BOOK_LABEL[c.bk] || c.bk} ${c.v}${i === 0 ? ` — best ${railDir.toUpperCase()} entry of the ${railBooks.length}` : ''}`
              : `${LEAN_BOOK_LABEL[c.bk] || c.bk} posts ${c.v} but will not take this ${railDir.toUpperCase()}`;
            return `<span class="${cls}" title="${tip.replace(/"/g, '&quot;')}"><i>${label}</i><b>${c.v}</b></span>`;
          }).join('') + `</span>`
        : `<span class="rc-books"></span>`;
      // ── GLOW-UP 240 L1 — the spread track ────────────────────────────────
      // The rail left a third of the row empty, which is most of why this still
      // read bland: rows that end two-thirds of the way across look unfinished
      // regardless of what is in them. The shop fills exactly that space with a
      // rail — a track from the worst book to the best with a dot per book —
      // and it is the single most recognisable thing on that screen.
      //
      // It is also the one view of the market the card never had: the chips say
      // WHAT each book posts, the track says how far apart they are and where
      // your pick sits in that range. A wide track is a shopping opportunity; a
      // tight one means the books agree and the number is the number.
      const railVals = railBooks.map(c => c.v);
      const railMin = railVals.length ? Math.min(...railVals) : 0;
      const railMax = railVals.length ? Math.max(...railVals) : 0;
      const railSpan = railMax - railMin;
      const pctOf = (v: number): number => railSpan > 0 ? ((v - railMin) / railSpan) * 100 : 50;
      const spreadEl = railBooks.length >= 2 && railSpan > 0
        ? `<span class="rc-spread${railSpan >= 5 ? ' is-wide' : ''}" title="${railBooks.length} books, ${railMin} to ${railMax} — a ${railSpan.toFixed(1)} point spread on the same prop.${railSpan >= 5 ? ' That is a wide disagreement; the book you choose matters as much as the side.' : ''}">`
          + `<i class="rc-spread-track"></i>`
          + railBooks.map((c, i) => `<i class="rc-spread-dot${i === 0 ? ' is-best' : ''}" style="left:${pctOf(c.v).toFixed(1)}%"></i>`).join('')
          + `</span>`
        : `<span class="rc-spread is-flat"${railBooks.length ? ' title="Every book posting this prop has the same number — nothing to shop."' : ''}></span>`;
      // ── GLOW-UP 241 — the WHY, as chips ──────────────────────────────────
      // 240 handed the row's flexible column to a rail that stretched ~900px
      // for a three-book spread, which made rows look stretched rather than
      // full — and its gold pick-ring was redundant: leanBestBook returns the
      // lowest line for an OVER and the highest for an UNDER, so the pick is
      // ALWAYS an endpoint and the ring always marked the dot already lit.
      //
      // The space goes to factor chips instead — the same ✓/✗ treatment Best
      // Picks uses, via the same pickDistinctFactors/factorChipHtml pair, so
      // the two surfaces cannot describe one lean differently. This also gets
      // the reasoning back ON the card, in a form you can actually scan, after
      // 239 moved it into a tooltip.
      const factorsEl = `<span class="rc-factors">`
        + pickDistinctFactors(el.reasons, 3).map(r => factorChipHtml(r, el.lean, 'rc-fchip')).join('')
        + `</span>`;
      // 2. The DELTA chip. "avg 80.4" beside a line of 83.5 makes you do the
      //    subtraction; the number that matters is the gap and which way it
      //    points. Green when the fighter's history supports the side being
      //    recommended, red when it argues against it — which is the same
      //    thing the reason sentence was spending forty words saying.
      const delta = (avgVal != null && line != null) ? avgVal - line : null;
      const deltaHelps = delta == null ? null : (el.lean === 'over' ? delta > 0 : delta < 0);
      const deltaEl = delta != null
        ? `<span class="rc-delta ${deltaHelps ? 'pos' : 'neg'}" title="Career ${statLbl} average of ${avgVal!.toFixed(1)} against a line of ${line!.toFixed(1)} — ${Math.abs(delta).toFixed(1)} ${delta > 0 ? 'above' : 'below'}, which ${deltaHelps ? 'supports' : 'argues against'} the ${(el.lean || '').toUpperCase()}.">${delta > 0 ? '+' : '−'}${Math.abs(delta).toFixed(1)}</span>`
        : `<span class="rc-delta"></span>`;
      // The reasoning moves to the row's tooltip. It was a third of the width
      // in grey prose and it is the one thing on the card that cannot be read
      // at a glance anyway — so it stops competing with the numbers that can.
      const rowTip = reasonTxt
        ? `${prettyName(f.name)} — ${topReason}`.replace(/"/g, '&quot;')
        : `${prettyName(f.name)} — no specific read; baseline model only.`;
      return `<div class="${rowCls}" title="${rowTip}">
        <span class="rc-name">${rankEl}${prettyName(f.name)}</span>
        ${pickEl}
        ${railEl}
        ${spreadEl}
        ${factorsEl}
        ${confEl}
        ${avgEl}
        ${deltaEl}
      </div>`;
  };

  if (rcSort !== 'card') {
    // Flat ranking. Fighters with no lean at all are dropped rather than parked
    // at the bottom — in card order they are context for their bout, and with
    // the bout gone they are just empty rows.
    const ranked = allFighters.filter(f => getEffectiveLean(f).lean !== 'none');
    const sortKey = (f: AnalyzerFighter): number => {
      const r = resolveRow(f);
      if (rcSort === 'conf') {
        // A read no book will take cannot outrank a placeable lean, however
        // confident it is — the same rule the headline and TOP PICK follow.
        return (r.unplaceable ? 0 : 1000) + (r.el.conf || 0);
      }
      // Δ LINE: how far his history sits from the number in the direction the
      // pick needs. Against the pick sorts below everything that is for it.
      if (r.avgVal == null || r.line == null) return -Infinity;
      const d = r.avgVal - r.line;
      const helps = r.el.lean === 'over' ? d > 0 : d < 0;
      return (helps ? Math.abs(d) : -Math.abs(d)) + (r.unplaceable ? -1000 : 0);
    };
    const rowsHtml = ranked
      .map(f => ({ f, k: sortKey(f) }))
      .sort((a, b) => b.k - a.k)
      .map(x => renderFighterRow(x.f))
      .join('');
    sections.push(`<div class="rc-fight-group rc-flat"><div class="rc-matchup">${rowsHtml}</div></div>`);
  } else {
  let lastBadge = '';
  for (const g of groups) {
    const rows = g.pair.map(renderFighterRow).join('');
    // F4 — each section reports itself. "Is the main card stronger than the
    // prelims?" was a question you could only answer by reading 24 rows and
    // doing the arithmetic in your head.
    const secFighters = groups.filter(x => x.badge === g.badge).flatMap(x => x.pair);
    // GLOW-UP 222 — same denominator as the hero tiles. A section that reads
    // "10 leans · 63%" while four of them are unplaceable is describing a section
    // you cannot enter.
    const secPlaceable = secFighters.filter(x => placeableSet.has(x));
    // L1 — pushes are not leans here either, or a section of coin flips would
    // report itself as a section full of blocked plays.
    const secBlocked = secFighters.filter(hasSide).length - secPlaceable.length;
    const secAvg = secPlaceable.length
      ? Math.round(secPlaceable.reduce((n, x) => n + getEffectiveLean(x).conf, 0) / secPlaceable.length)
      : 0;
    const secTitle = secPlaceable.length
      ? `${secPlaceable.length} placeable lean${secPlaceable.length === 1 ? '' : 's'} in this section, averaging ${secAvg}% confidence.${secBlocked ? ` ${secBlocked} more ${secBlocked === 1 ? 'is a read' : 'are reads'} no book will take (⛔).` : ''}`
      : `No placeable lean in this section — ${secBlocked} read${secBlocked === 1 ? '' : 's'} no book will take (⛔).`;
    const headHtml = g.badge !== lastBadge
      ? `<div class="rc-section-head rc-badge-${g.badgeCls}">
          <span>${g.badge}</span>
          ${secPlaceable.length
            ? `<b class="rc-sec-stat" title="${secTitle}">${secPlaceable.length} leans · ${secAvg}%${secBlocked ? ` <u>+${secBlocked} ⛔</u>` : ''}</b>`
            : secBlocked ? `<b class="rc-sec-stat" title="${secTitle}">${secBlocked} ⛔ only</b>` : ''}
          <i></i>
        </div>`
      : '';
    lastBadge = g.badge;
    // ── GLOW-UP 223 L6 — when the bout itself is the read ────────────────────
    // Both fighters leaning the same way on FP is a statement about the FIGHT,
    // not about either man: two UNDERs is "this ends early", two OVERs is "this
    // goes long and busy". Unnamed, the pair reads as the card contradicting
    // itself. Named, it is the most useful line on the block.
    // Display only. This is CONCENTRATION, never a demotion input — wiring the
    // correlation engine into the same-fight rule once dropped a real pick.
    const fpSides = g.pair
      .map(f => resolveRow(f))
      .filter(r => r.statKey === 'fp' && (r.el.lean === 'over' || r.el.lean === 'under'))
      .map(r => r.el.lean);
    const bothSame = (g.pair.length === 2 && fpSides.length === 2 && fpSides[0] === fpSides[1])
      ? fpSides[0] : null;
    const fightNote = bothSame
      ? `<div class="rc-fight-note is-${bothSame}" title="Both fighters' fantasy-point leans point the same way, which is a read on the bout rather than on either fighter: ${bothSame === 'under'
          ? 'neither man is expected to bank a full night of points, i.e. this ends early.'
          : 'both are expected to clear their number, i.e. a long, busy fight.'} Entering both is concentration on one outcome, not two independent plays."
        >${bothSame === 'under' ? '⇊ BOTH UNDER · reads as an early finish' : '⇈ BOTH OVER · reads as a long, busy fight'}</div>`
      : '';
    // The `Surname vs Surname` label was dropped: both names are already on the
    // two rows directly beneath it, so it repeated the content of the block it
    // headed and cost a line on all twelve fights.
    sections.push(`${headHtml}<div class="rc-fight-group rc-badge-${g.badgeCls}">
      <div class="rc-matchup">${rows}</div>
      ${fightNote}
    </div>`);
  }
  }

  const content = document.getElementById('reportContent');
  if (content) content.innerHTML = sections.join('');
  const sub = document.getElementById('reportModalSub');
  if (sub) sub.textContent = `${allFighters.length} fighters · ${placeableLeans.length} placeable lean${placeableLeans.length === 1 ? '' : 's'}${blockedCount ? ` · ${blockedCount} unplaceable` : ''}`;
  content?.querySelectorAll<HTMLElement>('[data-rc-sort]').forEach(b => b.addEventListener('click', () => {
    rcSort = (b.dataset['rcSort'] as RcSort) || 'card';
    void generateReportCard();
  }));
  document.getElementById('reportModal')?.classList.remove('is-hidden');

  // Build plain-text version for clipboard/download
  // L9 \u2014 the export is the copy that travels, so it carries the vintage too:
  // when it was made, how stale the books behind it are, and how long is left.
  const textLines: string[] = [
    `\uD83D\uDCCA ${eventTitle}`,
    vintageBits.join('  \u00B7  '),
    '',
  ];
  // L3 \u2014 the plays, stated up front. The body stays in card order; this is the
  // answer to "what do I actually enter" without re-reading 24 rows.
  if (rankedPlaceable.length) {
    textLines.push('\u2605 TOP PLACEABLE LEANS');
    rankedPlaceable.slice(0, 3).forEach((r, i) => {
      const row = resolveRow(r.f);
      const lineTxt = row.line != null ? `${row.statLbl} ${row.line.toFixed(1)}${row.src ? ` (${row.src})` : ''}` : row.statLbl;
      textLines.push(`   ${i + 1}. ${r.f.name} \u2014 ${r.el.lean.toUpperCase()} ${lineTxt}  \u00B7  ${r.el.conf}%`);
    });
    textLines.push('');
  }
  for (const g of groups) {
    const bar = '\u2501'.repeat(Math.max(0, 38 - g.badge.length));
    textLines.push(`\u2501\u2501\u2501 ${g.badge} ${bar}`);
    const [fa, fb] = g.pair;
    if (fa && fb) textLines.push(`\u2694  ${fa.name.toUpperCase()} vs ${fb.name.toUpperCase()}`);
    else if (fa) textLines.push(`\u2694  ${fa.name.toUpperCase()}`);
    // L6 \u2014 same note the screen puts on the block.
    const exFpSides = g.pair
      .map(f => resolveRow(f))
      .filter(r => r.statKey === 'fp' && (r.el.lean === 'over' || r.el.lean === 'under'))
      .map(r => r.el.lean);
    if (g.pair.length === 2 && exFpSides.length === 2 && exFpSides[0] === exFpSides[1]) {
      textLines.push(exFpSides[0] === 'under'
        ? '   \u21ca both under \u2014 reads as an early finish (one outcome, not two plays)'
        : '   \u21c8 both over \u2014 reads as a long, busy fight (one outcome, not two plays)');
    }
    for (const f of g.pair) {
      // Same resolver the screen uses, so the exported line can never disagree
      // with the one on the card.
      const { el, statLbl, line, src, unplaceable, avgVal } = resolveRow(f);
      // L1 \u2014 the export had the same silent push as the screen: a bare rule where
      // the model's actual answer was "neither side".
      const leanStr = el.lean === 'over' ? '\u25B2 OVER ' : el.lean === 'under' ? '\u25BC UNDER'
        : el.lean === 'push' ? 'NO EDGE' : '\u2500      ';
      // The stat is printed now: "18.5" alone could be SS, FP or TD, and the
      // export is what gets read away from the app where nothing disambiguates it.
      const statStr = el.lean !== 'none' ? statLbl.padEnd(5) : '     ';
      const lineStr = line != null
        ? `${unplaceable ? '' : `${src} `}${line.toFixed(1)}${unplaceable ? '!' : ''}`.padStart(10)
        : '          ';
      const confStr = el.lean !== 'none' ? `${el.conf}% conf` : '';
      const avgStr = avgVal != null ? `avg: ${avgVal.toFixed(1)} ${statLbl}` : '';
      // L3 \u2014 the same rank the screen shows, so the two cannot disagree about
      // which plays are the card's best.
      const rankStr = rankMap.has(f) ? `\u2605${rankMap.get(f)} ` : '   ';
      textLines.push(`    ${rankStr}${f.name.padEnd(22)} ${leanStr}  ${statStr} ${lineStr}  ${confStr.padEnd(9)}  ${avgStr}`);
    }
    textLines.push('');
  }
  textLines.push('\u2500'.repeat(45));
  // GLOW-UP 222 \u2014 overCount/underCount/avgConf are now placeable-only, so the
  // footer says so. "24 leans \u00B7 5 overs \u00B7 19 unders" beside a placeable-only
  // average was the export telling two stories with one row of numbers.
  textLines.push(`${placeableLeans.length} placeable lean${placeableLeans.length === 1 ? '' : 's'}  \u00B7  ${overCount} overs  \u00B7  ${underCount} unders  \u00B7  avg conf: ${avgConf}%${blockedCount ? `  \u00B7  ${blockedCount} unplaceable` : ''}`);
  // `!` beside a line means no book will take that side \u2014 worth stating, since
  // the export is read away from the tooltips that explain it on screen.
  if (groups.some(g => g.pair.some(f => resolveRow(f).unplaceable))) {
    textLines.push('! = no book posts this side \u2014 read only, not placeable');
  }
  if (pushCount) {
    textLines.push(`NO EDGE = the model landed on neither side (${pushCount} fighter${pushCount === 1 ? '' : 's'}, not counted above)`);
  }
  _reportCardText = textLines.join('\n');
}

function runWalkForwardDiagnostics(): void {
  const engine = new BacktestingEngine();
  const eventsByDate = new Map<number, WalkForwardEvent>();
  let createdPredictions = 0;

  allFighters.forEach(f => {
    const line = activePlatformLine(f) ?? f.db?.avgFP ?? null;
    const history = (f.db?.history || []).filter(h => h.fp != null) as FightResult[];
    if (!line || history.length < 7) return;

    for (let i = 6; i < history.length; i++) {
      const train = history.slice(Math.max(0, i - 6), i);
      const trainFP = train.map(h => h.fp || 0);
      if (!trainFP.length) continue;

      const mean = trainFP.reduce((s, v) => s + v, 0) / trainFP.length;
      const variance = trainFP.reduce((s, v) => s + Math.pow(v - mean, 2), 0) / trainFP.length;
      const std = Math.max(8, Math.sqrt(variance));
      const overProb = 1 / (1 + Math.exp(-((mean - line) / std)));
      const lean = overProb > 0.52 ? 'over' : overProb < 0.48 ? 'under' : 'push';
      if (lean === 'push') continue;

      const confidence = Math.min(0.95, Math.abs(overProb - 0.5) * 2 + 0.45);
      const expectedValue = lean === 'over' ? overProb : 1 - overProb;

      const ts = history[i].date ? new Date(history[i].date as string).getTime() : (Date.now() - (history.length - i) * 86400000);
      const eventTs = Number.isFinite(ts) ? ts : Date.now();

      if (!eventsByDate.has(eventTs)) {
        eventsByDate.set(eventTs, {
          timestamp: eventTs,
          predictions: [],
          actualResults: []
        });
      }

      const evt = eventsByDate.get(eventTs)!;
      evt.predictions.push({
        fighter: f.name,
        line,
        prediction: {
          lean,
          confidence,
          edge: Math.abs(overProb - 0.5) * 2,
          expectedValue
        }
      });
      evt.actualResults.push({
        fighter: f.name,
        actualFP: history[i].fp || 0
      });
      createdPredictions++;
    }
  });

  const events = Array.from(eventsByDate.values())
    .filter(e => e.predictions.length > 0)
    .sort((a, b) => a.timestamp - b.timestamp);

  if (events.length < 7) {
    showToast('Walk-forward needs more history (min 7 event buckets)');
    debugLog(`Walk-forward skipped: only ${events.length} event buckets`);
    return;
  }

  const result = engine.runWalkForwardValidation(events, 6);
  if (!result.folds.length) {
    showToast('Walk-forward produced no valid folds');
    debugLog('Walk-forward produced no folds after filtering');
    return;
  }

  const avgCal = result.folds.reduce((sum, f) => sum + f.calibrationScore, 0) / result.folds.length;
  const msg = `WF OK: acc ${(result.overallAccuracy * 100).toFixed(1)}% · brier ${result.overallBrierScore.toFixed(3)} · cal ${avgCal.toFixed(3)}`;
  showToast(msg);
  debugLog(`Walk-forward diagnostics: events=${events.length}, preds=${createdPredictions}, folds=${result.folds.length}`);
  result.folds.slice(0, 8).forEach((f, idx) => {
    debugLog(`WF fold ${idx + 1}: train=${f.trainSize}, test=${f.testSize}, acc=${(f.accuracy * 100).toFixed(1)}%, brier=${f.brierScore.toFixed(3)}, cal=${f.calibrationScore.toFixed(3)}`);
  });
}

function setExclusiveActive(selector: string, activeEl: Element): void {
  document.querySelectorAll(selector).forEach((el) => el.classList.remove('active'));
  activeEl.classList.add('active');
}

function bindExclusiveButtons(selector: string, onActivate: (el: HTMLElement) => void): void {
  document.querySelectorAll(selector).forEach((el) => {
    el.addEventListener('click', () => {
      setExclusiveActive(selector, el);
      onActivate(el as HTMLElement);
    });
  });
}

// ── UI INIT ───────────────────────────────────────────────────────────────
function initAnalyzerCore(): void {
  // Load any persisted manual style overrides before predictions/fighter DBs build.
  void applyFighterStyleOverrides();

  // Platform switcher
  document.querySelectorAll('[data-platform]').forEach(btn => {
    btn.addEventListener('click', () => setActivePlatform((btn as HTMLElement).dataset['platform'] || 'pick6'));
  });
  setActivePlatform('pick6');

  // Trend window toggle (L3 / L5 / Career)
  document.querySelectorAll('.trend-btn[data-window]').forEach(btn => {
    btn.addEventListener('click', () => {
      const w = parseInt((btn as HTMLElement).dataset['window'] || '3');
      setTrendWindow((w === 0 || w === 5 ? w : 3) as 3 | 5 | 0);
    });
  });
  bindSourceToggles();
  bindLearningDetailsToggle();

  // Top-bar buttons
  document.getElementById('refreshBtn')?.addEventListener('click', loadData);

  document.getElementById('autoScrapeBtn')?.addEventListener('click', triggerAutoScrape);
  document.getElementById('exportBtn')?.addEventListener('click', exportToCSV);

  // Header overflow ("More" dropdown) for rare actions
  const overflowBtn = document.getElementById('headerOverflowBtn');
  const overflowPanel = document.getElementById('headerOverflowPanel') as HTMLElement | null;
  if (overflowBtn && overflowPanel) {
    const closeOverflow = (): void => {
      overflowPanel.hidden = true;
      overflowBtn.setAttribute('aria-expanded', 'false');
    };
    overflowBtn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const willOpen = overflowPanel.hidden;
      overflowPanel.hidden = !willOpen;
      overflowBtn.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    });
    document.addEventListener('click', (ev) => {
      if (overflowPanel.hidden) return;
      const target = ev.target as Node | null;
      if (target && !overflowPanel.contains(target) && target !== overflowBtn && !overflowBtn.contains(target)) {
        closeOverflow();
      }
    });
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape' && !overflowPanel.hidden) closeOverflow();
    });
    overflowPanel.addEventListener('click', (ev) => {
      const target = ev.target as HTMLElement | null;
      if (target?.closest('.overflow-item')) closeOverflow();
    });
  }
  // Line Movement Summary toggle
  document.getElementById('movementSummaryHeader')?.addEventListener('click', () => {
    const body = document.getElementById('movementSummaryBody');
    const toggle = document.getElementById('movementSummaryToggle');
    if (body && toggle) {
      const collapsed = body.style.display === 'none';
      body.style.display = collapsed ? '' : 'none';
      toggle.textContent = collapsed ? '▲' : '▼';
    }
  });
  document.getElementById('reportCardBtn')?.addEventListener('click', generateReportCard);
  document.getElementById('lineShopBtn')?.addEventListener('click', generateLineShopModal);

  document.getElementById('backupStorageBtn')?.addEventListener('click', async () => {
    try {
      const all = await new Promise<Record<string, unknown>>((res) =>
        chrome.storage.local.get(null, (data) => res(data || {}))
      );
      const keys = Object.keys(all);
      const payload = {
        __ufcBackup: true,
        version: 1,
        exportedAt: new Date().toISOString(),
        keyCount: keys.length,
        storage: all,
      };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const stamp = new Date().toISOString().replace(/[:.]/g, '-');
      const a = document.createElement('a');
      a.href = url;
      a.download = `ufc-storage-backup-${stamp}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 2000);
      showToast(`✓ Backup: ${keys.length} keys saved`);
      void storageSet({ ufc_last_backup_ts: Date.now() });
      const overflowTrigger = document.getElementById('headerOverflowBtn');
      if (overflowTrigger) {
        overflowTrigger.classList.remove('backup-stale');
        overflowTrigger.title = 'More actions';
      }
    } catch (e) {
      showToast(`Backup failed: ${e instanceof Error ? e.message : String(e)}`);
    }
  });

  // Line data is irreplaceable (4 events were lost to an uninstall once) —
  // surface backup age: amber dot on the ⋯ More trigger when the last backup
  // is older than 7 days or was never taken. Cleared on a successful backup.
  void (async () => {
    try {
      const BACKUP_STALE_MS = 7 * 24 * 60 * 60 * 1000;
      const data = await storageGet<{ ufc_last_backup_ts?: number }>(['ufc_last_backup_ts']);
      const ts = data.ufc_last_backup_ts;
      if (ts && Date.now() - ts <= BACKUP_STALE_MS) return;
      const trigger = document.getElementById('headerOverflowBtn');
      if (!trigger) return;
      trigger.classList.add('backup-stale');
      trigger.title = ts
        ? `More actions — last storage backup ${Math.floor((Date.now() - ts) / 86400000)}d ago`
        : 'More actions — no storage backup on record yet';
    } catch { /* nudge only — never block init */ }
  })();

  const restoreFileInput = document.getElementById('restoreStorageFile') as HTMLInputElement | null;
  document.getElementById('restoreStorageBtn')?.addEventListener('click', () => restoreFileInput?.click());
  restoreFileInput?.addEventListener('change', async () => {
    const file = restoreFileInput.files?.[0];
    if (!file) return;
    try {
      const text = await file.text();
      const parsed = JSON.parse(text);
      const storage = parsed?.storage && typeof parsed.storage === 'object' ? parsed.storage : null;
      if (!parsed?.__ufcBackup || !storage) {
        showToast('Restore failed: not a valid UFC backup file');
        return;
      }
      const keys = Object.keys(storage);
      if (!keys.length) {
        showToast('Restore failed: backup is empty');
        return;
      }
      const confirmed = confirm(
        `Restore ${keys.length} storage keys from backup exported ${parsed.exportedAt || 'unknown'}?\n\nThis OVERWRITES existing data for those keys. Other keys are left alone.`
      );
      if (!confirmed) return;
      await new Promise<void>((res, rej) =>
        chrome.storage.local.set(storage, () => {
          const err = chrome.runtime?.lastError;
          if (err) rej(new Error(err.message));
          else res();
        })
      );
      showToast(`✓ Restored ${keys.length} keys — reloading…`);
      setTimeout(() => location.reload(), 900);
    } catch (e) {
      showToast(`Restore failed: ${e instanceof Error ? e.message : String(e)}`);
    } finally {
      restoreFileInput.value = '';
    }
  });
  const lineShopModal = document.getElementById('lineShopModal');
  document.getElementById('lineShopClose')?.addEventListener('click', () => lineShopModal?.classList.add('is-hidden'));
  lineShopModal?.addEventListener('click', (e) => { if (e.target === lineShopModal) lineShopModal.classList.add('is-hidden'); });
  const newsModal = document.getElementById('newsModal');
  document.getElementById('newsModalClose')?.addEventListener('click', () => newsModal?.classList.add('is-hidden'));
  newsModal?.addEventListener('click', (e) => { if (e.target === newsModal) newsModal.classList.add('is-hidden'); });
  const reportModal = document.getElementById('reportModal');
  document.getElementById('reportModalClose')?.addEventListener('click', () => reportModal?.classList.add('is-hidden'));
  reportModal?.addEventListener('click', (e) => { if (e.target === reportModal) reportModal.classList.add('is-hidden'); });
  document.getElementById('reportCopyBtn')?.addEventListener('click', async () => {
    if (!_reportCardText) return;
    await navigator.clipboard.writeText(_reportCardText);
    showToast('Report copied to clipboard');
  });
  document.getElementById('reportDownloadBtn')?.addEventListener('click', () => {
    if (!_reportCardText) return;
    const blob = new Blob([_reportCardText], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ufc-report-${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    showToast('Report downloaded');
  });
  document.getElementById('densityToggleBtn')?.addEventListener('click', () => {
    currentDensity = currentDensity === 'compact' ? 'detailed' : 'compact';
    applyDensityMode();
  });
  document.getElementById('historyDensityToggleBtn')?.addEventListener('click', () => {
    currentHistoryDensity = currentHistoryDensity === 'compact' ? 'readable' : 'compact';
    applyHistoryDensityMode();
  });
  applyDensityMode();
  applyHistoryDensityMode();

  // Display-density gear popover
  const densityTrigger = document.getElementById('densityTrigger');
  const densityPopover = document.getElementById('densityPopover') as HTMLElement | null;
  if (densityTrigger && densityPopover) {
    const closeDensityPopover = (): void => {
      densityPopover.hidden = true;
      densityTrigger.setAttribute('aria-expanded', 'false');
    };
    densityTrigger.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const willOpen = densityPopover.hidden;
      densityPopover.hidden = !willOpen;
      densityTrigger.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    });
    document.addEventListener('click', (ev) => {
      if (densityPopover.hidden) return;
      const target = ev.target as Node | null;
      if (target && !densityPopover.contains(target) && target !== densityTrigger && !densityTrigger.contains(target)) {
        closeDensityPopover();
      }
    });
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape' && !densityPopover.hidden) closeDensityPopover();
    });
  }

  // Line drop / empty-state buttons
  document.getElementById('emptyStateAutoFetchBtn')?.addEventListener('click', triggerAutoScrape);

  // Empty state predict button is wired inline in processData() where it's created

  // Watcher and event banner removed by request; ensure any prior background watcher is stopped.
  void runtimeSendMessage({ type: 'STOP_LINE_WATCHER' });

  // View tabs
  bindExclusiveButtons('.tab-btn[data-view]', (btn) => {
    currentView = btn.dataset['view'] || 'all';
    // Archive and best picks work without lines — ensure container is visible
    if (currentView === 'archive' || currentView === 'bestpicks' || currentView === 'parlaylab' || currentView === 'calibration') {
      const empty = document.getElementById('emptyState');
      const container = document.getElementById('cardContainer');
      if (empty) empty.style.display = 'none';
      if (container) container.style.display = 'block';
    }
    renderFighters();
    // GLOW-UP 163: sync Slate Check panel + sticky mini-verdict visibility
    // immediately on view switch (was lagging until the next heartbeat).
    void renderQAPanel();
    syncDataTabsTrigger();
  });
  bindDataTabsTrigger();
  syncDataTabsTrigger();

  // Reset baselines: re-anchor all baselines to current values so deltas become 0.
  // Future real movement will show correctly from this point forward.
  document.getElementById('resetBaselinesBtn')?.addEventListener('click', async () => {
    console.log('[UFC Analyzer] RESET LINES clicked — clearing all baselines and re-anchoring');
    const resetBtn = document.getElementById('resetBaselinesBtn') as HTMLButtonElement | null;
    const resetLabel = resetBtn?.querySelector('.overflow-item-label') as HTMLElement | null;
    if (resetBtn && resetLabel) {
      resetLabel.textContent = 'DONE!';
      resetBtn.classList.add('overflow-item-success');
      setTimeout(() => {
        resetLabel.textContent = 'RESET LINES';
        resetBtn.classList.remove('overflow-item-success');
      }, 2000);
    }
    // Betr-clear rule: the Betr seed itself carries its event date (written by
    // initializeBetrLines in background.ts via BETR_EVENT_DATE). Read that directly
    // so the rule doesn't depend on upcomingEventTs, which can drift if the analyzer
    // auto-advances to the next card.
    //   • betr_event_date is future → we're in fight week → preserve Betr (user's
    //     manual modal entries must survive a baseline re-anchor).
    //   • betr_event_date is past → the seed is stale → wipe storage + in-memory.
    //   • betr_event_date missing → nothing to protect → wipe.
    let eventOver = true;
    try {
      const betrMeta = await new Promise<Record<string, any>>(res =>
        chrome.storage.local.get(['betr_event_date'], res)
      );
      const raw = typeof betrMeta['betr_event_date'] === 'string' ? betrMeta['betr_event_date'] : '';
      // GLOW-UP 210: through the setter, so this read also counts as "loaded"
      // — it is a genuine storage read, and RESET LINES runs before any of the
      // re-anchor snapshots below.
      setCurrentBetrEventDate(raw);
      if (raw) {
        const seedEventMs = new Date(`${raw}T23:59:59`).getTime();
        if (Number.isFinite(seedEventMs) && Date.now() <= seedEventMs) eventOver = false;
      }
    } catch {}
    if (eventOver) {
      await new Promise<void>((res) => chrome.storage.local.remove(['lines_betr', 'lines_betr_manual_v1'], () => res()));
      // Purge Betr values from in-memory fighters too — storage wipe alone leaves stale values on the render path.
      for (const f of allFighters) {
        f.line_betr = null;
        f.line_betr_ss = null;
        f.line_betr_td = null;
        f.line_betr_ft = null;
      }
      console.log('[UFC Analyzer] RESET LINES: event over — Betr lines cleared (storage + in-memory)');
    }
    _openingLines.clear();
    _prevRefreshLines.clear();
    // Re-anchor baselines to current live values
    const _psCombos = LINE_STAT_ACCESSORS;
    for (const fighter of allFighters) {
      for (const [plat, stat, getVal] of _psCombos) {
        const val = getVal(fighter);
        if (val == null || !isPlausibleBaseline(stat, val)) continue;
        const key = openingLineKey(plat, stat, fighter.name);
        _openingLines.set(key, val);
        _prevRefreshLines.set(key, val);
      }
    }
    // Persist with fresh timestamp
    _baselineCapturedAt = Date.now();
    void persistOpeningLines();
    const _oc = document.getElementById('openingLinesCount');
    if (_oc) _oc.textContent = ` · 📍re-anchored ${_openingLines.size} baselines`;
    showToast(eventOver
      ? `Baselines re-anchored + Betr lines cleared (event over)`
      : `Baselines re-anchored — Betr lines preserved (event live)`);
    renderFighters();
    renderLineMovementSummary();
  });

  // Debug panel toggle
  document.getElementById('debugToggleBtn')?.addEventListener('click', () => {
    const wrap = document.getElementById('debugPanelWrap');
    if (!wrap) return;
    const visible = !wrap.classList.contains('debug-panel-hidden');
    wrap.classList.toggle('debug-panel-hidden', visible);
    const icon = document.querySelector('#debugToggleBtn .debug-icon');
    if (icon) icon.textContent = visible ? '⚡' : '✕';
  });

  // Card row expand/collapse
  document.getElementById('cardContainer')?.addEventListener('click', (e) => {
    const newsBadgeBtn = (e.target as HTMLElement).closest('.news-warn-badge');
    if (newsBadgeBtn) {
      e.stopPropagation();
      const fighterName = (newsBadgeBtn as HTMLElement).dataset['newsFighter'] || '';
      const cached = _newsCache.get(fighterName.toLowerCase());
      if (!cached?.items.length) { showToast('No cached news — reload to refresh'); return; }
      const alertItems = cached.items.filter(item => NEWS_INJURY_KEYWORDS.some(kw => item.title.toLowerCase().includes(kw)));
      const otherItems = cached.items.filter(item => !alertItems.includes(item));
      const titleEl = document.getElementById('newsModalTitle');
      const subEl = document.getElementById('newsModalSub');
      const contentEl = document.getElementById('newsModalContent');
      const nm = document.getElementById('newsModal');
      if (!nm || !contentEl) return;
      if (titleEl) titleEl.textContent = `⚠ ${fighterName.toUpperCase()} — NEWS`;
      if (subEl) subEl.textContent = `${alertItems.length} alert headline${alertItems.length !== 1 ? 's' : ''} · ${cached.items.length} total in last 7 days`;
      const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
      const safeHref = (url: string) => (url && /^https?:\/\//i.test(url) ? esc(url) : '#');
      const renderItem = (item: NewsItem, isAlert: boolean) =>
        `<div class="news-item${isAlert ? ' news-item-alert' : ''}">
          <div class="news-item-title"><a href="${safeHref(item.link)}" target="_blank" rel="noopener">${esc(item.title || '(no title)')}</a></div>
          <div class="news-item-meta">${item.pubDate ? esc(new Date(item.pubDate).toLocaleDateString()) : ''}${item.source ? ` · ${esc(item.source)}` : ''}</div>
        </div>`;
      contentEl.innerHTML = [
        ...alertItems.map(item => renderItem(item, true)),
        ...otherItems.map(item => renderItem(item, false)),
      ].join('') || '<div style="color:var(--text3);font-size:12px">No headlines found.</div>';
      nm.classList.remove('is-hidden');
      return;
    }
    // Avatar click = head-to-head. The old ⚔ button was a 20px target whose
    // misses fell through to the row-expand handler ("pulls down fight history
    // instead"). The avatar is big, always visible, and unambiguous.
    const avatarHit = (e.target as HTMLElement).closest('.fighter-avatar-wrap');
    if (avatarHit) {
      const rowEl = avatarHit.closest('.fighter-row') as HTMLElement | null;
      const nm = rowEl?.dataset['name'] || '';
      if (nm) { e.stopPropagation(); openH2HByName(nm); return; }
    }
    const h2hBtn = (e.target as HTMLElement).closest('.h2h-btn');
    if (h2hBtn) {
      e.stopPropagation();
      openH2HByName((h2hBtn as HTMLElement).dataset['fighter'] || '');
      return;
    }
    const main = (e.target as HTMLElement).closest('.fighter-main');
    if (main) toggleRow((main.closest('.fighter-row') as HTMLElement));
  });

  // H2H modal close
  const h2hModal = document.getElementById('h2hModal');
  document.getElementById('h2hModalClose')?.addEventListener('click', () => h2hModal?.classList.add('is-hidden'));
  h2hModal?.addEventListener('click', (e) => { if (e.target === h2hModal) h2hModal.classList.add('is-hidden'); });

  // Search
  document.getElementById('fighterSearch')?.addEventListener('input', (e) => {
    currentSearch = (e.target as HTMLInputElement).value || '';
    renderFighters();
  });

  // Sort
  bindExclusiveButtons('.sort-btn[data-sort]', (btn) => {
    currentSort = btn.dataset['sort'] || 'default';
    updateSortTrendTriggerLabel();
    renderFighters();
  });

  // Sort & Trend popover
  const sortTrendTrigger = document.getElementById('sortTrendTrigger');
  const sortTrendPopover = document.getElementById('sortTrendPopover') as HTMLElement | null;
  if (sortTrendTrigger && sortTrendPopover) {
    const closePopover = (): void => {
      sortTrendPopover.hidden = true;
      sortTrendTrigger.setAttribute('aria-expanded', 'false');
    };
    sortTrendTrigger.addEventListener('click', (ev) => {
      ev.stopPropagation();
      const willOpen = sortTrendPopover.hidden;
      sortTrendPopover.hidden = !willOpen;
      sortTrendTrigger.setAttribute('aria-expanded', willOpen ? 'true' : 'false');
    });
    document.addEventListener('click', (ev) => {
      if (sortTrendPopover.hidden) return;
      const target = ev.target as Node | null;
      if (target && !sortTrendPopover.contains(target) && target !== sortTrendTrigger && !sortTrendTrigger.contains(target)) {
        closePopover();
      }
    });
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape' && !sortTrendPopover.hidden) closePopover();
    });
    sortTrendPopover.addEventListener('click', (ev) => {
      const target = ev.target as HTMLElement | null;
      if (target?.closest('.sort-btn, .trend-btn')) closePopover();
    });
  }
  updateSortTrendTriggerLabel();

  // ── Quick-jump command palette (press K) ──────────────────────────────────
  const cmdPalette = document.getElementById('cmdPalette');
  const cmdInput = document.getElementById('cmdPaletteInput') as HTMLInputElement | null;
  const cmdResults = document.getElementById('cmdPaletteResults');
  let cmdSel = 0;
  const closePalette = (): void => { cmdPalette?.classList.add('is-hidden'); };
  const renderPalette = (q: string): void => {
    if (!cmdResults) return;
    const ql = q.trim().toLowerCase();
    const items = allFighters
      .filter(f => !ql || f.name.toLowerCase().includes(ql) || (f.opponent || '').toLowerCase().includes(ql))
      .slice(0, 12);
    cmdSel = Math.min(cmdSel, Math.max(0, items.length - 1));
    cmdResults.innerHTML = items.length ? items.map((f, i) => {
      const cl = f.lean?.lean;
      const leanChip = (cl === 'over' || cl === 'under') && f.lean?.conf
        ? `<span class="cmd-item-lean ${cl}">${cl === 'over' ? '▲' : '▼'} ${f.lean.conf}%</span>`
        : '';
      return `
      <div class="cmd-item ${i === cmdSel ? 'sel' : ''}" data-name="${f.name}">
        <span class="bp-avatar bp-avatar-sm"><span class="bp-avatar-flag">${f.db?.country || '🥊'}</span><img class="bp-avatar-img" data-name="${f.name}" alt="" /></span>
        <span class="cmd-item-name">${prettyName(f.name)}</span>${leanChip}
        <span class="cmd-item-meta">${f.db?.record || ''} · vs ${prettyName(f.opponent || '—')}</span>
      </div>`;
    }).join('') : '<div class="cmd-item-empty">No fighters match</div>';
    hydrateAvatarImgs(cmdResults);
    cmdResults.querySelectorAll<HTMLElement>('.cmd-item').forEach(el => {
      el.addEventListener('click', () => { closePalette(); jumpToFighterCard(el.dataset['name'] || ''); });
    });
  };
  const openPalette = (): void => {
    if (!cmdPalette || !cmdInput) return;
    cmdSel = 0;
    cmdInput.value = '';
    renderPalette('');
    cmdPalette.classList.remove('is-hidden');
    cmdInput.focus();
  };
  const movePaletteSel = (d: number): void => {
    const items = Array.from(cmdResults?.querySelectorAll<HTMLElement>('.cmd-item') || []);
    if (!items.length) return;
    cmdSel = (cmdSel + d + items.length) % items.length;
    items.forEach((el, i) => el.classList.toggle('sel', i === cmdSel));
    items[cmdSel].scrollIntoView({ block: 'nearest' });
  };
  cmdInput?.addEventListener('input', () => { cmdSel = 0; renderPalette(cmdInput.value); });
  cmdInput?.addEventListener('keydown', (ev) => {
    if (ev.key === 'ArrowDown') { ev.preventDefault(); movePaletteSel(1); }
    else if (ev.key === 'ArrowUp') { ev.preventDefault(); movePaletteSel(-1); }
    else if (ev.key === 'Enter') {
      const sel = cmdResults?.querySelectorAll<HTMLElement>('.cmd-item')[cmdSel];
      if (sel?.dataset['name']) { closePalette(); jumpToFighterCard(sel.dataset['name']); }
    } else if (ev.key === 'Escape') { closePalette(); }
  });
  cmdPalette?.addEventListener('click', (e) => { if (e.target === cmdPalette) closePalette(); });

  // ── Keyboard shortcuts: "/" search, 1-5 views, "?" help overlay ───────────
  const kbdHelp = document.getElementById('kbdHelp');
  kbdHelp?.addEventListener('click', (e) => { if (e.target === kbdHelp) kbdHelp.classList.add('is-hidden'); });
  document.addEventListener('keydown', (ev) => {
    const t = ev.target as HTMLElement | null;
    const typing = !!t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable);
    if (ev.key === 'Escape') { kbdHelp?.classList.add('is-hidden'); cmdPalette?.classList.add('is-hidden'); return; }
    if (typing || ev.ctrlKey || ev.metaKey || ev.altKey) return;
    if (ev.key === '/') {
      ev.preventDefault();
      (document.getElementById('fighterSearch') as HTMLInputElement | null)?.focus();
      return;
    }
    if (ev.key === '?') { ev.preventDefault(); kbdHelp?.classList.toggle('is-hidden'); return; }
    if (ev.key === 'k' || ev.key === 'K') { ev.preventDefault(); openPalette(); return; }
    const viewByKey: Record<string, string> = { '1': 'all', '2': 'over', '3': 'under', '4': 'bestpicks', '5': 'parlaylab' };
    const view = viewByKey[ev.key];
    if (view) {
      (document.querySelector(`.tab-btn[data-view="${view}"]`) as HTMLElement | null)?.click();
    }
  });

  // Back-to-top floating button
  const backToTop = document.getElementById('backToTop');
  if (backToTop) {
    window.addEventListener('scroll', () => {
      backToTop.classList.toggle('visible', window.scrollY > 600);
    }, { passive: true });
    backToTop.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
  }

  // ── GLOW-UP 19: floating tooltip for drilldown history bars ──────────────
  const histTip = document.createElement('div');
  histTip.id = 'histTip';
  histTip.setAttribute('hidden', '');
  document.body.appendChild(histTip);
  let histTipRow: HTMLElement | null = null;
  const escHt = (x: string): string => x.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]!));
  document.addEventListener('mousemove', (ev) => {
    const row = (ev.target as HTMLElement | null)?.closest?.('.history-bar-row.has-tip') as HTMLElement | null;
    if (!row) {
      if (histTipRow) { histTipRow = null; histTip.setAttribute('hidden', ''); }
      return;
    }
    if (row !== histTipRow) {
      histTipRow = row;
      const d = row.dataset;
      const resCls = d['htRes'] === 'w' ? 'w' : d['htRes'] === 'l' ? 'l' : '';
      const overCls = d['htOver'] === '1' ? 'over' : 'under';
      histTip.innerHTML =
        `<div class="ht-head">vs ${escHt(d['htOpp'] || '?')}</div>` +
        (d['htRestext'] ? `<div class="ht-res ${resCls}">${escHt(d['htRestext'])}</div>` : '') +
        (d['htDate'] ? `<div class="ht-date">${escHt(d['htDate'])}</div>` : '') +
        `<div class="ht-val ${overCls}">${escHt(d['htVal'] || '')}` +
        (d['htLine'] ? ` <span class="ht-line">vs line ${escHt(d['htLine'])}</span>` : '') +
        (d['htDelta'] ? ` <span class="ht-delta">${escHt(d['htDelta'])}</span>` : '') +
        `</div>`;
      histTip.removeAttribute('hidden');
    }
    const pad = 13;
    const r = histTip.getBoundingClientRect();
    let x = ev.clientX + pad;
    let y = ev.clientY + pad;
    if (x + r.width > window.innerWidth - 8) x = ev.clientX - r.width - pad;
    if (y + r.height > window.innerHeight - 8) y = ev.clientY - r.height - pad;
    histTip.style.left = `${x}px`;
    histTip.style.top = `${y}px`;
  }, { passive: true });

  // One-time keyboard hint
  try {
    if (!localStorage.getItem('kbd_hint_v1')) {
      localStorage.setItem('kbd_hint_v1', '1');
      setTimeout(() => showToast('Tip: press ? for keyboard shortcuts — / to search, 1–5 to switch views'), 2500);
    }
  } catch { /* storage unavailable */ }

  // Initial data load
  requestDataReload();
  startPeriodicDataReload(60000);
  void runArchiveBackfillPass();

  // Fighter modal
  document.getElementById('modalClose')?.addEventListener('click', () => {
    document.getElementById('fighterModal')?.classList.remove('open');
  });
  document.getElementById('fighterModal')?.addEventListener('click', (e) => {
    if (e.target === document.getElementById('fighterModal'))
      document.getElementById('fighterModal')?.classList.remove('open');
  });
  bindExclusiveButtons('.modal-tab', (tab) => {
    document.querySelectorAll('.modal-panel').forEach(p => p.classList.remove('active'));
    document.getElementById(tab.dataset['panel'] || '')?.classList.add('active');
  });
}

initAnalyzerCore();

// ── DEBUG PANEL BUTTONS ───────────────────────────────────────────────────
interface DebugCardSample {
  text?: string;
  aria?: string;
}

interface DebugCardEntry {
  samples?: DebugCardSample[];
  capturedAt?: number;
}

interface CachedHtmlFight {
  opponent?: string;
  kd?: number | null;
  sigStr?: number | null;
  totStr?: number | null;
  td?: number | null;
  ctrlSecs?: number | null;
  round?: number | null;
  method?: string;
}

interface CachedHtmlResponse {
  error?: string;
  html?: string;
  detailUrl?: string;
  fightHistory?: CachedHtmlFight[];
}

interface ClaudeApiResponse {
  error?: string;
  data?: {
    content?: Array<{ text?: string }>;
  };
}

interface OCRFighterRow {
  name?: string;
  fp?: number | null;
  ss?: number | null;
}

function getDebugPanelEl(): HTMLElement | null {
  return document.getElementById('debugPanel');
}

function setDebugPanelText(text: string): HTMLElement | null {
  const panel = getDebugPanelEl();
  if (!panel) return null;
  panel.textContent = text;
  return panel;
}

function appendDebugPanelText(panel: HTMLElement, text: string): void {
  panel.textContent += text;
}

function scrollDebugPanelToBottom(panel: HTMLElement): void {
  panel.scrollTop = panel.scrollHeight;
}

document.getElementById('dbgTestBtn')?.addEventListener('click', async () => {
  const panel = setDebugPanelText('Reading stored card debug + live lines data...\n');
  if (!panel) return;
  const all = await storageGet<Record<string, unknown>>([]);
  for (const platform of ['pick6', 'underdog']) {
    const key = `lines_${platform}`;
    const lineData = all[key] as PlatformLinesPayload | undefined;
    if (!lineData) { appendDebugPanelText(panel, `${platform}: no lines captured\n`); continue; }
    appendDebugPanelText(panel, `\n=== ${platform} captured fighters (${lineData.fighters?.length}) ===\n`);
    (lineData.fighters || []).slice(0, 5).forEach((f) => {
      appendDebugPanelText(panel, `  ${f.name}: fp=${f.line_fp ?? f.line} ss=${f.line_ss} td=${f.line_td} ft=${f.line_ft}\n`);
    });
  }
  for (const platform of STORAGE_LINE_DEBUG_KEYS) {
    const key = `debug_card_${platform}`;
    const debugEntry = all[key] as DebugCardEntry | undefined;
    if (!debugEntry) { appendDebugPanelText(panel, `\n${platform}: no card debug — visit the page\n`); continue; }
    appendDebugPanelText(panel, `\n=== ${platform} card text samples ===\n`);
    (debugEntry.samples || []).forEach((s, i: number) => { appendDebugPanelText(panel, `[${i}] ${s.text?.slice(0,800)}\n`); });
  }
  scrollDebugPanelToBottom(panel);
});

document.getElementById('dbgDumpBtn')?.addEventListener('click', async () => {
  const panel = setDebugPanelText('Trying UFC Stats URLs with browser headers...\n');
  if (!panel) return;
  const headers = { 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'Accept-Language': 'en-US,en;q=0.5', 'Cache-Control': 'no-cache' };
  const urls = ['http://www.ufcstats.com/fighter-details/0bc62e3c498b5011', 'http://ufcstats.com/fighter-details/0bc62e3c498b5011'];
  for (const url of urls) {
    try {
      appendDebugPanelText(panel, `GET ${url}\n`);
      const res = await fetch(url, { headers, redirect: 'follow' as RequestRedirect, mode: 'cors' as RequestMode });
      const text = await res.text();
      appendDebugPanelText(panel, `Status: ${res.status} | Bytes: ${text.length} | Final URL: ${res.url}\n`);
      appendDebugPanelText(panel, `First 300 chars:\n${JSON.stringify(text.slice(0, 300))}\n\n`);
      if (text.length < 1000) continue;
      const trCount = (text.match(/<tr/gi)||[]).length;
      appendDebugPanelText(panel, `<tr> tags: ${trCount}\n`);
      ['b-fight-details__table-body','fighter-details','b-fight-details'].forEach(m => { appendDebugPanelText(panel, `  "${m}": ${text.includes(m)}\n`); });
      const rows = [...text.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
      const dataRow = rows.find(r => r[1].includes('fighter-details') && r[1].includes('<td'));
      if (!dataRow) { appendDebugPanelText(panel, 'No data row with fighter-details link found\n'); continue; }
      const tds = [...dataRow[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)];
      appendDebugPanelText(panel, `\nDATA ROW — ${tds.length} tds:\n`);
      tds.forEach((td, i) => {
        const ps = [...td[1].matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map(p => p[1].replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim());
        if (ps.length > 0) { appendDebugPanelText(panel, `  td[${i}]: "${ps[0]?.slice(0,45)}" | "${(ps[1]||'').slice(0,45)}"\n`); }
        else { appendDebugPanelText(panel, `  td[${i}]: "${td[1].replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim().slice(0,60)}"\n`); }
      });
      appendDebugPanelText(panel, `\nRAW (first 1000 chars):\n${dataRow[1].slice(0,1000)}`);
      scrollDebugPanelToBottom(panel);
      return;
    } catch(e: unknown) { appendDebugPanelText(panel, `EXCEPTION: ${(e as Error).name}: ${(e as Error).message}\n\n`); }
  }
  appendDebugPanelText(panel, '\nAll URLs failed — UFC Stats may be blocking cross-origin requests.\n');
});

document.getElementById('dbgCopyBtn')?.addEventListener('click', () => {
  const panel = document.getElementById('debugPanel');
  if (!panel) return;
  navigator.clipboard.writeText(panel.textContent || '').then(() => {
    const btn = document.getElementById('dbgCopyBtn');
    if (btn) { btn.textContent = '✓ COPIED'; setTimeout(() => { btn.textContent = 'COPY LOG'; }, 2000); }
  });
});

document.getElementById('dbgClearBtn')?.addEventListener('click', async () => {
  if (typeof chrome !== 'undefined' && chrome.storage) {
    const all = await storageGet<Record<string, unknown>>([]);
    const keys = Object.keys(all).filter(k => k.startsWith('ufcstats_'));
    keys.push('upcoming_ufc_card');
    await storageRemove(keys);
    const panel = document.getElementById('debugPanel');
    if (panel) panel.textContent = `Cleared ${keys.length} cached entries. Reloading...`;
    setTimeout(() => location.reload(), 800);
  }
});

document.getElementById('dbgBgDumpBtn')?.addEventListener('click', async () => {
  const panel = setDebugPanelText('Reading Max Holloway from cache (must be loaded in analyzer first)...\n');
  if (!panel) return;
  const resp = await runtimeSendMessage<CachedHtmlResponse>({ type: 'GET_CACHED_HTML', name: 'Max Holloway' });
  if (!resp || resp.error) {
    appendDebugPanelText(panel, `${resp?.error}\n`);
    appendDebugPanelText(panel, 'Scroll to Max Holloway in the analyzer to trigger a fetch, then try again.\n');
    return;
  }
  appendDebugPanelText(panel, `Cache hit! HTML: ${resp.html?.length} chars | URL: ${resp.detailUrl}\n`);
  appendDebugPanelText(panel, `\nParsed fights (${resp.fightHistory?.length}):\n`);
  (resp.fightHistory||[]).forEach((f, i: number) => {
    appendDebugPanelText(panel, `  [${i}] ${f.opponent} kd=${f.kd} sig=${f.sigStr} tot=${f.totStr} td=${f.td} ctrl=${f.ctrlSecs}s rnd=${f.round} method=${f.method}\n`);
  });
  appendDebugPanelText(panel, '\n--- RAW TD STRUCTURE ---\n');
  const rows = [...(resp.html||'').matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
  const dataRows = rows.filter((r) => !r[1].includes('<th') && (r[1].match(/<td/gi)||[]).length > 5);
  appendDebugPanelText(panel, `Total rows: ${rows.length}, data rows: ${dataRows.length}\n`);
  if (dataRows.length > 0) {
    const row = dataRows[0][1];
    const tds = [...row.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)];
    tds.forEach((td, i: number) => {
      const ps = [...td[1].matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map((p) => p[1].replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim());
      if (ps.length > 0) { appendDebugPanelText(panel, `td[${i}]: "${ps[0]?.slice(0,45)}" | "${(ps[1]||'').slice(0,45)}"\n`); }
    });
  }
  scrollDebugPanelToBottom(panel);
});

document.getElementById('dbgHideBtn')?.addEventListener('click', () => {
  const wrap = document.getElementById('debugPanelWrap');
  if (wrap) wrap.classList.add('debug-panel-hidden');
  const icon = document.querySelector('#debugToggleBtn .debug-icon');
  if (icon) icon.textContent = '⚡';
});

// ── BETR SCREENSHOT READER ────────────────────────────────────────────────
(function() {
  const modal         = document.getElementById('manualModal');
  const openBtn       = document.getElementById('manualEntryBtn');
  const closeBtn      = document.getElementById('manualModalClose');
  const dropZone      = document.getElementById('betrDropZone');
  const fileInput     = document.getElementById('betrFileInput') as HTMLInputElement|null;
  const imageQueue    = document.getElementById('betrImageQueue');
  const analyzeBtn    = document.getElementById('betrAnalyzeBtn') as HTMLButtonElement|null;
  const analyzeStatus = document.getElementById('betrAnalyzeStatus');
  const extracted     = document.getElementById('betrExtracted');
  const extractedRows = document.getElementById('betrExtractedRows');
  const saveBtn       = document.getElementById('betrSaveBtn');
  const addRowBtn     = document.getElementById('betrAddRow');
  const saveStatus    = document.getElementById('betrSaveStatus');

  let queuedImages: { dataUrl: string; name: string }[] = [];

  closeBtn?.addEventListener('click', () => { if (modal) modal.classList.add('is-hidden'); });
  modal?.addEventListener('click', (e) => { if (e.target === modal && modal) modal.classList.add('is-hidden'); });

  function setDropZoneHighlight(active: boolean): void {
    if (!dropZone) return;
    if (active) {
      dropZone.style.borderColor = 'var(--orange)';
      dropZone.style.background = 'rgba(255,122,43,0.08)';
      return;
    }
    dropZone.style.borderColor = 'rgba(255,122,43,0.4)';
    dropZone.style.background = 'rgba(255,122,43,0.04)';
  }

  dropZone?.addEventListener('click', () => fileInput?.click());
  dropZone?.addEventListener('dragover', (e) => { e.preventDefault(); setDropZoneHighlight(true); });
  dropZone?.addEventListener('dragleave', () => { setDropZoneHighlight(false); });
  dropZone?.addEventListener('drop', (e: DragEvent) => {
    e.preventDefault();
    setDropZoneHighlight(false);
    if (e.dataTransfer) addFiles(Array.from(e.dataTransfer.files));
  });
  fileInput?.addEventListener('change', () => { if (fileInput.files) addFiles(Array.from(fileInput.files)); });

  function addFiles(files: File[]): void {
    files.filter(f => f.type.startsWith('image/')).forEach(file => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const dataUrl = e.target?.result as string;
        queuedImages.push({ dataUrl, name: file.name });
        renderQueue();
      };
      reader.readAsDataURL(file);
    });
  }

  function renderQueue(): void {
    if (!imageQueue) return;
    imageQueue.innerHTML = '';
    queuedImages.forEach((img, i) => {
      const wrap = document.createElement('div');
      wrap.className = 'betr-queue-item';
      wrap.innerHTML = `<img src="${img.dataUrl}" class="betr-queue-img"><button data-i="${i}" class="betr-queue-remove">✕</button><div class="betr-queue-name">${img.name}</div>`;
      (wrap.querySelector('button') as HTMLButtonElement).addEventListener('click', () => { queuedImages.splice(i, 1); renderQueue(); });
      imageQueue.appendChild(wrap);
    });
    if (analyzeBtn) {
      setButtonBusyState(analyzeBtn, queuedImages.length === 0, {
        busyOpacity: '0.4',
        idleOpacity: '1',
      });
    }
  }

  analyzeBtn?.addEventListener('click', async () => {
    if (!queuedImages.length) return;
    const apiKeyInput = document.getElementById('betrApiKey') as HTMLInputElement|null;
    const apiKey = apiKeyInput?.value?.trim();
    if (!apiKey) { if (analyzeStatus) analyzeStatus.textContent = '✗ Enter your Anthropic API key first'; return; }
    if (typeof chrome !== 'undefined' && chrome.storage) await storageSet({ betr_api_key: apiKey });
    setButtonBusyState(analyzeBtn, true, { busyText: '⟳ Reading...' });
    if (analyzeStatus) analyzeStatus.textContent = `Sending ${queuedImages.length} image(s) to AI...`;
    if (extracted) extracted.classList.add('is-hidden');
    try {
      const imageContent = queuedImages.map(img => ({
        type: 'image',
        source: { type: 'base64', media_type: img.dataUrl.split(';')[0].split(':')[1], data: img.dataUrl.split(',')[1] }
      }));
      const payload = {
        model: 'claude-sonnet-4-20250514', max_tokens: 1000,
        messages: [{ role: 'user', content: [...imageContent, { type: 'text', text: `These are screenshots from the Betr fantasy sports app showing UFC fighter prop lines. Extract every fighter's lines.\nReturn ONLY a JSON array: [{"name":"First Last","fp":number_or_null,"ss":number_or_null}]` }] }]
      };
      const resp = await runtimeSendMessage<ClaudeApiResponse>({ type: 'CLAUDE_API', payload, apiKey });
      if (!resp) throw new Error('No response from analyzer runtime');
      if (resp?.error) throw new Error(resp.error);
      const data = resp.data;
      const text = data?.content?.map((c) => c.text || '').join('') || '';
      let fighters: OCRFighterRow[] = [];
      try { fighters = JSON.parse(text.replace(/```json|```/g, '').trim()) as OCRFighterRow[]; }
      catch(e) { throw new Error('Could not parse AI response: ' + text?.slice(0, 200)); }
      if (analyzeStatus) analyzeStatus.textContent = `✓ Found ${fighters.length} fighter(s)`;
      renderExtractedRows(fighters);
      if (extracted) extracted.classList.remove('is-hidden');
    } catch(err: unknown) {
      if (analyzeStatus) analyzeStatus.textContent = '✗ Error: ' + (err as Error).message;
    } finally {
      setButtonBusyState(analyzeBtn, false, { idleText: '🔍 READ WITH AI' });
    }
  });

  function renderExtractedRows(fighters: OCRFighterRow[]): void { if (extractedRows) { extractedRows.innerHTML = ''; fighters.forEach(f => addExtractedRow(f)); } }

  function addExtractedRow(f: OCRFighterRow = {}): void {
    if (!extractedRows) return;
    const row = document.createElement('div');
    row.className = 'betr-row';
    row.innerHTML = `<input type="text" class="betr-name betr-input name" value="${f.name || ''}" placeholder="Fighter name"><input type="number" class="betr-fp betr-input fp" value="${f.fp ?? ''}" placeholder="—" step="0.5"><input type="number" class="betr-ss betr-input ss" value="${f.ss ?? ''}" placeholder="—" step="0.5"><button class="betr-remove-btn">✕</button>`;
    (row.querySelector('button') as HTMLButtonElement).addEventListener('click', () => row.remove());
    extractedRows.appendChild(row);
  }

  addRowBtn?.addEventListener('click', () => addExtractedRow());

  openBtn?.addEventListener('click', async () => {
    if (modal) modal.classList.remove('is-hidden');
    // Pre-populate rows from currently stored BETR lines AND update event title
    if (extractedRows) {
      try {
        await syncUpcomingCardContext(true);
        const stored = await storageGet<{
          lines_betr?: { fighters?: RawLineFighter[] };
          lines_betr_manual_v1?: { fighters?: RawLineFighter[] };
        }>(['lines_betr', 'lines_betr_manual_v1']);

        // Do not fall back to UFCStats event text here; that feed can lag and show the wrong card.
        const eventName = (inferredEventNameFromLines || '').trim();
        const reviewTitle = modal?.querySelector('.betr-review-title') as HTMLElement | null;
        if (reviewTitle) {
          reviewTitle.textContent = eventName
            ? `${eventName} Lines \u2014 Review & Edit Before Saving`
            : 'Upcoming UFC Lines \u2014 Review & Edit Before Saving';
        }

        // Always refresh rows on modal open so stale event rows cannot linger between cards.
        extractedRows.innerHTML = '';
        const baseExisting = stored['lines_betr']?.fighters || [];
        const manualOverrides = stored['lines_betr_manual_v1']?.fighters;
        // Apply manual overrides so user-adjusted values survive a clear+re-seed cycle.
        const existing = manualOverrides?.length
          ? applyBetrManualOverrides(baseExisting, manualOverrides)
          : baseExisting;
        // Bypass card filter when upcoming event is >10 days away (avoids filtering against the wrong card)
        const tooFarAway = Number.isFinite(upcomingEventTs) && upcomingEventTs - Date.now() > 10 * 24 * 60 * 60 * 1000;
        const filteredExisting = (!tooFarAway && upcomingCardPairs.length)
          ? existing.filter((f) => isUpcomingCardFighter(f.name) || isUpcomingCardFighter(f.opponent || ''))
          : existing;
        if (filteredExisting.length > 0) {
          renderExtractedRows(filteredExisting.map(f => ({ name: f.name || '', fp: f.line_fp ?? null, ss: f.line_ss ?? null })));
        }
        // No stored lines — modal opens empty, ready for new screenshots
      } catch { /* no stored lines is fine */ }
    }
  });

  saveBtn?.addEventListener('click', async () => {
    if (!extractedRows) return;
    const rows = extractedRows.querySelectorAll('div');
    const fighters: RawLineFighter[] = [];
    rows.forEach(row => {
      const name = (row.querySelector('.betr-name') as HTMLInputElement)?.value?.trim();
      if (!name) return;
      const fp = parseFloat((row.querySelector('.betr-fp') as HTMLInputElement)?.value) || null;
      const ss = parseFloat((row.querySelector('.betr-ss') as HTMLInputElement)?.value) || null;
      // GLOW-UP 190: attach the opponent from the card. pruneOrphanFighters drops
      // any fighter without an opponent once a payload has >=10 rows, so a full
      // slate saved without it (>=10 fighters) was silently pruned down to
      // nothing — the reader was unusable for a full card.
      if (fp || ss) fighters.push({ name, opponent: findOpponentFromUpcomingCard(name), line_fp: fp, line_ss: ss, line_td: null });
    });
    if (!fighters.length) {
      // No valid lines — explicitly clear Betr manual storage
      if (typeof chrome !== 'undefined' && chrome.storage) {
        chrome.storage.local.remove('lines_betr_manual_v1', () => {
          if (saveStatus) saveStatus.textContent = '✓ Betr lines cleared';
          setTimeout(() => { if (saveStatus) saveStatus.textContent = ''; }, 2000);
        });
      }
      return;
    }
    const capturedAt = Date.now();
    const data = { fighters, capturedAt };
    if (typeof chrome !== 'undefined' && chrome.storage) {
      // Detect line movements before saving — compare against opening lines
      const movements: string[] = [];
      for (const fighter of fighters) {
        const fname = String(fighter.name || '').trim();
        if (!fname) continue;
        const checks: Array<[string, number | null]> = [
          ['fp', fighter.line_fp ?? null],
          ['ss', fighter.line_ss ?? null],
          ['td', fighter.line_td ?? null],
        ];
        for (const [stat, val] of checks) {
          if (val == null) continue;
          const key = openingLineKey('betr', stat, fname);
          const openVal = _openingLines.get(key);
          if (openVal != null && Math.abs(val - openVal) >= 0.5) {
            const delta = parseFloat((val - openVal).toFixed(1));
            movements.push(`${fname} ${stat.toUpperCase()} ${delta > 0 ? '▲+' : '▼'}${delta} (was ${openVal})`);
          }
        }
      }

      await storageSet({ lines_betr: data, [STORAGE_BETR_MANUAL_KEY]: data });

      if (movements.length) {
        const msg = `✓ Saved — Line moves: ${movements.join(' · ')}`;
        if (saveStatus) saveStatus.textContent = msg;
      } else {
        if (saveStatus) saveStatus.textContent = `✓ Saved ${fighters.length} Betr lines`;
      }
      const countBetr = document.getElementById('countBetr');
      if (countBetr) countBetr.textContent = fighters.length + ' fighters';
      document.getElementById('pillBetr')?.classList.add('active');
      setTimeout(() => { if (modal) modal.classList.add('is-hidden'); }, 800);
      const result = await storageGet<Record<string, PlatformLinesPayload | null>>([...STORAGE_BETR_LINE_KEYS]);
      const p6 = result['lines_pick6']?.fighters || [];
      const ud = result['lines_underdog']?.fighters || [];
      const bt = result['lines_betr']?.fighters || [];
      await mergeAndEnrich(p6, ud, bt);
      detectAndRecordMovements();
      snapshotOpeningLines();
      snapshotLineHistory();
      renderFighters();
      renderLineMovementSummary();
    }
  });
})();

// ── ADVANCED UI ENHANCEMENTS ──────────────────────────────────────────────

// Mouse tracking for interactive backgrounds
let mouseX = 50;
let mouseY = 50;
let dynamicEffectsInitialized = false;
let performanceMonitorStarted = false;

document.addEventListener('mousemove', (e) => {
  mouseX = (e.clientX / window.innerWidth) * 100;
  mouseY = (e.clientY / window.innerHeight) * 100;
  document.documentElement.style.setProperty('--mouse-x', `${mouseX}%`);
  document.documentElement.style.setProperty('--mouse-y', `${mouseY}%`);
});

// Dynamic class toggling for enhanced effects
function addDynamicEffects(): void {
  // Add morphing classes randomly
  setInterval(() => {
    const cards = document.querySelectorAll('.fighter-card');
    cards.forEach(card => {
      if (Math.random() > 0.95) { // 5% chance
        card.classList.add('morphing');
        setTimeout(() => card.classList.remove('morphing'), 6000);
      }
    });
  }, 3000);

  // Add energy field effects to strong leans
  setInterval(() => {
    const strongLeans = document.querySelectorAll('.lean-indicator.strong');
    strongLeans.forEach(lean => {
      if (Math.random() > 0.8) { // 20% chance
        lean.classList.add('energy-field');
        setTimeout(() => lean.classList.remove('energy-field'), 4000);
      }
    });
  }, 5000);

  // Dynamic particle generation
  setInterval(() => {
    if (Math.random() > 0.9) { // 10% chance
      const particle = document.createElement('div');
      particle.className = 'quantum-particle';
      particle.style.left = Math.random() * 100 + '%';
      particle.style.top = Math.random() * 100 + '%';
      particle.style.animationDelay = Math.random() * 4 + 's';
      document.querySelector('.quantum-particles')?.appendChild(particle);
      setTimeout(() => particle.remove(), 8000);
    }
  }, 2000);
}

// Enhanced hover effects with sound-like feedback (visual)
document.addEventListener('mouseover', (e) => {
  const target = e.target as HTMLElement;
  if (target.classList.contains('btn') || target.classList.contains('fighter-card') || target.classList.contains('line-cell')) {
    // Add ripple effect
    const ripple = document.createElement('div');
    ripple.style.position = 'absolute';
    ripple.style.border = '2px solid rgba(0,232,122,0.6)';
    ripple.style.borderRadius = '50%';
    ripple.style.width = '20px';
    ripple.style.height = '20px';
    ripple.style.left = '50%';
    ripple.style.top = '50%';
    ripple.style.transform = 'translate(-50%, -50%)';
    ripple.style.animation = 'ripple 0.6s ease-out';
    ripple.style.pointerEvents = 'none';
    target.appendChild(ripple);
    setTimeout(() => ripple.remove(), 600);
  }
});

// Performance monitoring and dynamic adjustments
let frameCount = 0;
let lastTime = performance.now();

function monitorPerformance(): void {
  if (!performanceMonitorStarted) performanceMonitorStarted = true;
  frameCount++;
  const currentTime = performance.now();
  if (currentTime - lastTime >= 1000) {
    const fps = Math.round((frameCount * 1000) / (currentTime - lastTime));
    if (fps < 30) {
      // Reduce animations for performance
      document.documentElement.style.setProperty('--animation-duration', '0.1s');
    } else {
      document.documentElement.style.setProperty('--animation-duration', '0.3s');
    }
    frameCount = 0;
    lastTime = currentTime;
  }
  requestAnimationFrame(monitorPerformance);
}

// Initialize advanced effects
document.addEventListener('DOMContentLoaded', () => {
  if (!dynamicEffectsInitialized) {
    dynamicEffectsInitialized = true;
    addDynamicEffects();
  }
  if (!performanceMonitorStarted) monitorPerformance();

  // Add loading animation to body
  document.body.classList.add('loading');
  setTimeout(() => document.body.classList.remove('loading'), 1000);

  // Enhanced scroll effects
  let scrollTimeout: ReturnType<typeof setTimeout>;
  window.addEventListener('scroll', () => {
    document.body.classList.add('scrolling');
    clearTimeout(scrollTimeout);
    scrollTimeout = setTimeout(() => {
      document.body.classList.remove('scrolling');
    }, 150);
  });
});

// Keyboard shortcuts for power users
function handleShortcutRefresh(): void {
  requestDataReload();
  // Add visual feedback
  document.body.style.animation = 'none';
  setTimeout(() => {
    document.body.style.animation = 'pulse 0.3s ease-in-out';
  }, 10);
}

function handleShortcutDebugToggle(): void {
  const debugPanel = document.getElementById('debugPanelWrap');
  if (debugPanel) {
    debugPanel.style.display = debugPanel.style.display === 'none' ? 'block' : 'none';
  }
}

document.addEventListener('keydown', (e) => {
  // Ctrl+Shift+R for rapid refresh
  if (e.ctrlKey && e.shiftKey && e.key === 'R') {
    e.preventDefault();
    handleShortcutRefresh();
  }

  // Ctrl+Shift+D for debug mode toggle
  if (e.ctrlKey && e.shiftKey && e.key === 'D') {
    e.preventDefault();
    handleShortcutDebugToggle();
  }

});

// Auto-save user preferences
let preferencesTimeout: ReturnType<typeof setTimeout>;
const PREFS_STORAGE_KEY = 'ufc-analyzer-prefs';

interface AnalyzerPreferences {
  theme?: string;
  lastVisit?: number;
}

function readAnalyzerPreferences(): AnalyzerPreferences | null {
  const raw = localStorage.getItem(PREFS_STORAGE_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as AnalyzerPreferences;
  } catch (e) {
    console.warn('Failed to parse preferences:', e);
    return null;
  }
}

function savePreferences(): void {
  clearTimeout(preferencesTimeout);
  preferencesTimeout = setTimeout(() => {
    const prefs: AnalyzerPreferences = {
      theme: document.documentElement.className,
      lastVisit: Date.now()
    };
    localStorage.setItem(PREFS_STORAGE_KEY, JSON.stringify(prefs));
  }, 1000);
}

window.addEventListener('beforeunload', savePreferences);

// Load saved preferences
const savedPrefs = readAnalyzerPreferences();
if (savedPrefs?.theme) {
  document.documentElement.className = savedPrefs.theme;
}
